// === Autofill shield ===
// The browser's own password manager -- not this app -- was writing into the
// dashboard's fields: the credentials saved for localhost:3420 turned up as the
// username in the Vault "new key" panel's DESCRIPTION box and as the password in
// its VALUE box (Boss, 2026-08-10; the screenshot showed Chrome's pale autofill
// tint on both). Chrome reads any text input sitting next to a type=password
// input as a sign-in form, and a lone text box (the email search) as a username
// box. Saving that panel would have filed Boss's own dashboard password into the
// Vault under whatever key name was typed, so this is a correctness problem, not
// only a cosmetic one.
//
// Every field is therefore opted out ONCE, here, rather than patched one at a
// time as each new offender is spotted:
//   - autocomplete: "new-password" on password fields (Chrome honours that and
//     refuses to fill saved credentials into it -- it ignores "off" there),
//     "off" on the rest.
//   - data-1p-ignore / data-lpignore / data-bwignore / data-form-type: the
//     opt-out attributes 1Password, LastPass, Bitwarden and Dashlane read.
//   - readonly while empty and unfocused: Chrome does not autofill a readonly
//     field, and the flag is dropped the moment the user points at or focuses
//     the box, so typing is untouched. This is the part that actually stops the
//     fill -- the attributes above are advisory and Chrome overrules them at
//     will. Same trick the kanban search box already uses (see below); this
//     generalises it instead of leaving the next field to be found by Boss.
// A MutationObserver covers everything rendered later, which is most of this UI
// (it is built from JS strings), so a field added tomorrow is protected without
// being listed anywhere.
//
// NOT shielded on purpose: inputs that ask for a credential deliberately, i.e.
// the ones declaring autocomplete="username" or "current-password" (the login
// card, the change-password form). There the fill is the feature.
;(() => {
  const WANTED = new Set(['username', 'current-password'])
  // Input types a credential can be filled into. checkbox/radio/file/date/etc.
  // are skipped -- nothing fills those, and readonly means other things there.
  const FILLABLE = new Set(['text', 'search', 'email', 'tel', 'url', 'number', 'password', ''])

  function shield(el) {
    if (!el || el.dataset.afShield) return
    const tag = el.tagName
    if (tag !== 'INPUT' && tag !== 'TEXTAREA') return
    const type = tag === 'INPUT' ? (el.getAttribute('type') || 'text').toLowerCase() : 'text'
    if (tag === 'INPUT' && !FILLABLE.has(type)) return
    if (WANTED.has((el.getAttribute('autocomplete') || '').toLowerCase())) {
      el.dataset.afShield = 'wanted'
      return
    }
    el.dataset.afShield = '1'
    el.setAttribute('autocomplete', type === 'password' ? 'new-password' : 'off')
    el.setAttribute('data-1p-ignore', '')
    el.setAttribute('data-lpignore', 'true')
    el.setAttribute('data-bwignore', '')
    if (!el.hasAttribute('data-form-type')) el.setAttribute('data-form-type', 'other')
    // A field that arrives readonly is readonly because its own code wants it
    // that way (the vault password-history rows, for one) -- never unlock it.
    if (el.readOnly) return
    // Only ever unlock a lock this shield put on (afLocked). Other code locks
    // fields for its own reasons while they are on screen -- applyMarveenReadonlyMode
    // makes the main agent's CLAUDE.md / SOUL.md textareas readonly -- and a
    // blanket unlock-on-focus would quietly hand those back for editing.
    const lock = () => {
      if (el.readOnly || el.value || document.activeElement === el) return
      el.readOnly = true
      el.dataset.afLocked = '1'
    }
    const unlock = () => {
      if (el.dataset.afLocked !== '1') return
      el.readOnly = false
      delete el.dataset.afLocked
    }
    el.addEventListener('pointerdown', unlock)
    el.addEventListener('focus', unlock)
    el.addEventListener('blur', lock)
    lock()
  }

  function scan(root) {
    if (!root || root.nodeType !== 1) return
    shield(root)
    if (root.querySelectorAll) for (const el of root.querySelectorAll('input,textarea')) shield(el)
  }

  function start() {
    scan(document.body)
    new MutationObserver(records => {
      for (const r of records) for (const n of r.addedNodes) scan(n)
    }).observe(document.body, { childList: true, subtree: true })
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true })
  else start()
})()

// === Avatar cache-busting epoch ===
// Avatar URLs used to carry ?t=Date.now() on every render, which defeated the
// browser cache and re-downloaded ~1MB per avatar on each rerender (brutal on
// slow remote links). Instead the URLs are stable (server sends max-age +
// ETag) until an avatar is actually changed in THIS session, which bumps the
// epoch and re-busts every avatar URL rendered afterwards.
let _avatarEpoch = 0
function bumpAvatarEpoch() { _avatarEpoch = Date.now() }
function avatarBust() { return _avatarEpoch ? `?t=${_avatarEpoch}` : '' }

// === i18n runtime ===
// Priority: localStorage['marveen.lang'] > DASHBOARD_LANG (server default, read
// from /api/settings on init) > 'hu' (hardcoded fallback).
// Rick's spec (kanban card 209696a9): t(key,params), window._i18n={hu,en},
// window._lang; {name} interpolation; EN-fallback then key; dev-mode warning.
;(() => {
  const LS_KEY = 'marveen.lang'
  const VALID = new Set(['hu', 'en'])

  // Brand tokens ({brand} = product/brand name, {bot} = main agent display
  // name, {agentId} = canonical slug) are filled from /api/marveen once it
  // resolves (see initSidebarBrand). Until then these defaults keep a stock
  // install byte-identical. Explicit params passed to t() still win over them.
  window._brandTokens = window._brandTokens || { brand: 'Marveen', bot: 'Marveen', agentId: 'marveen', owner: '' }

  window.t = function t(key, params = {}) {
    const lang = window._lang || 'hu'
    const str =
      window._i18n?.[lang]?.[key] ??
      window._i18n?.['en']?.[key] ??
      key
    if (str === key && localStorage.getItem('marveen.dev') === '1') {
      console.warn('[i18n] missing key:', key)
    }
    const vals = { ...window._brandTokens, ...params }
    return str.replace(/\{(\w+)\}/g, (_, k) => (vals[k] != null ? vals[k] : `{${k}}`))
  }

  function applyLang(lang) {
    window._lang = VALID.has(lang) ? lang : 'hu'
  }

  // Initialise from localStorage; server default fetched async below.
  applyLang(localStorage.getItem(LS_KEY) || 'hu')

  // Fetch server default (DASHBOARD_LANG) and apply only if localStorage not
  // set. Deferred to a MICROTASK: this IIFE evaluates before the fetch-wrapper
  // IIFE installs the Bearer-injecting window.fetch, so an eager call here
  // went out with the native fetch, got 401 from the /api gate, and the
  // server default was silently dead code. Microtasks run after the whole
  // classic script has evaluated, when window.fetch is the wrapped version.
  queueMicrotask(() => {
    fetch('/api/settings')
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (!data || localStorage.getItem(LS_KEY)) return
        const entry = (data.settings || []).find(s => s.key === 'DASHBOARD_LANG')
        if (!entry || !VALID.has(entry.value) || entry.value === window._lang) return
        // Apply WITHOUT persisting (localStorage must keep overriding the
        // server default), and re-run the render dance: the initial
        // DOMContentLoaded render almost always beats this response, so a
        // plain applyLang would leave the page painted in the old language.
        applyLang(entry.value)
        if (typeof renderNav === 'function') renderNav()
        if (typeof renderStaticI18n === 'function') renderStaticI18n()
        const activeLink = document.querySelector('.sb-link.active[data-page]')
        if (activeLink && typeof switchPage === 'function') switchPage(activeLink.dataset.page)
      })
      .catch(() => {})
  })

  window.setLang = function setLang(lang) {
    if (!VALID.has(lang)) return
    window._lang = lang
    localStorage.setItem(LS_KEY, lang)
    renderNav()
    // Static elements (kanban column titles, hints, empty states) are otherwise
    // only translated at DOMContentLoaded -- re-apply them on every switch so the
    // currently-open page updates live, not just after a manual reload.
    if (typeof renderStaticI18n === 'function') renderStaticI18n()
    // Re-render the active page by re-triggering the switchPage handler.
    // location.hash (not a `.active` nav-link query) is the source of truth
    // for the current page -- dynamically-added nav links (e.g. each email
    // account's own sidebar link, rendered by renderEmailAccountNav() long
    // after this IIFE's `navLinks` snapshot was taken) never get their
    // `.active` class cleared by switchPage(), so querying `.active` could
    // match one of THOSE instead of the real current page and silently
    // navigate away on every language switch (Boss, 2026-08-06/07: "a
    // nyelvvalasztonak csak a nyelvet kellene modositania nem az oldalt").
    const pageId = location.hash.slice(1) || 'overview'
    if (typeof switchPage === 'function') switchPage(pageId)
  }
})()

// === Dashboard auth bootstrap ===
// The server prints an URL like http://127.0.0.1:3420/?token=XXX on startup
// ONLY when it runs in a terminal (src/web.ts gates that line on
// process.stderr.isTTY). Under a service install (systemd/launchd) the log has
// no token in it at all -- there the token lives in store/.dashboard-token.
// On first visit we pluck the token out of the URL, store it in localStorage,
// strip it from the visible URL, and then inject it into every /api/* fetch
// as a Bearer header so the server lets us through.

// The main (channels) agent's real id. The backend /api/marveen route returns
// the configured MAIN_AGENT_ID (NOT the literal "marveen") in window._marveen;
// use this everywhere an agent id is sent to /api/agents/... or compared to a
// fleet name, so the dashboard works on non-"marveen" installs. Falls back to
// "marveen" only before /api/marveen has resolved (or on a legacy backend).
function mainAgentId() {
  // window._marveen only populates on pages that happen to call loadAgents()/
  // ensureMarveenLoaded() (Agents, Kanban, Messages) -- on any OTHER page
  // (Activity notably) it's still undefined when this runs, so this used to
  // fall straight to the literal 'marveen', breaking the id-vs-display-name
  // comparison in chatDisplayName() and showing the raw agent id ("lackor2-
  // bot") instead of the configured display name in e.g. the Terminal modal
  // title (Boss, 2026-08-06/07: reported 3 separate times, always from the
  // Activity page). window._brandTokens.agentId is set unconditionally on
  // EVERY page by initSidebarBrand() -- same data, already loaded everywhere,
  // just never consulted here before.
  return window._marveen?.agentId || window._brandTokens?.agentId || 'marveen'
}

(() => {
  const TOKEN_KEY = 'marveen-dashboard-token'
  const urlParams = new URLSearchParams(window.location.search)
  const urlToken = urlParams.get('token')
  // Keep the token in memory for the whole session in addition to localStorage.
  // Some iOS/Safari privacy modes purge or block localStorage (especially over
  // plain http / non-primary origins); an in-memory copy keeps the session
  // authenticated even when the persisted copy is unavailable.
  let sessionToken = urlToken || ''
  if (urlToken) {
    try { localStorage.setItem(TOKEN_KEY, urlToken) } catch { /* storage blocked */ }
    urlParams.delete('token')
    const clean = window.location.pathname + (urlParams.toString() ? '?' + urlParams : '') + window.location.hash
    window.history.replaceState({}, '', clean)
  } else {
    try { sessionToken = localStorage.getItem(TOKEN_KEY) || '' } catch { /* storage blocked */ }
  }

  const originalFetch = window.fetch.bind(window)
  window.fetch = async (input, init) => {
    const url = typeof input === 'string' ? input : (input instanceof Request ? input.url : String(input))
    // Only attach the token to same-origin API calls. Relative paths always
    // resolve to same-origin; absolute URLs must match the current origin.
    const isSameOriginApi =
      url.startsWith('/api/') ||
      (url.startsWith(window.location.origin + '/api/'))
    if (isSameOriginApi) {
      let token = sessionToken
      if (!token) { try { token = localStorage.getItem(TOKEN_KEY) } catch { token = '' } }
      if (token) {
        init = init || {}
        const headers = new Headers(init.headers || (input instanceof Request ? input.headers : undefined))
        headers.set('Authorization', 'Bearer ' + token)
        init.headers = headers
      }
    }
    const res = await originalFetch(input, init)
    if (res.status === 401 && isSameOriginApi) {
      // Token missing, wrong, or revoked. Wipe and prompt once per page load.
      // Keep a URL-provided session token so a transient 401 does not lock out
      // a session whose localStorage copy was purged.
      try { localStorage.removeItem(TOKEN_KEY) } catch { /* storage blocked */ }
      if (!urlToken) sessionToken = ''
      if (!window.__marveenAuthPrompted) {
        window.__marveenAuthPrompted = true
        handleAuthFailure()
      }
    }
    return res
  }

  // On a 401, ask the public status probe whether a username+password login is
  // available on this instance. If so, show the login overlay; otherwise fall
  // back to the existing token flows (PWA paste field or the console-URL alert).
  async function handleAuthFailure() {
    let status = null
    try {
      const r = await originalFetch('/api/auth/status')
      if (r.ok) status = await r.json()
    } catch { /* offline or probe failed -- fall through to token flows */ }
    if (status && status.login_available) {
      showLoginOverlay(status)
      return
    }
    // An installed (home-screen) PWA has its own localStorage, separate from
    // Safari's, and the manifest start_url has no ?token=, so the very first
    // standalone launch is token-less and 401s. There is no address bar to paste
    // a ?token= URL into either. Offer an in-app paste field that writes the
    // token to the app's own storage, then reload.
    const isStandalone = window.navigator.standalone === true ||
      (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)
    if (isStandalone) {
      showStandaloneTokenPrompt(TOKEN_KEY)
    } else {
      // A szoveg NEM hivatkozhat a szerver naplojara. A ?token= linket a
      // szerver csak akkor irja ki, ha terminalbol indult (src/web.ts:
      // `process.stderr.isTTY`) -- egy systemd/launchd telepitesnel az a sor
      // SOSEM keletkezik, tehat a regi tanacs egy frissen telepitett rendszeren
      // olyan helyre kuldte a felhasznalot, ahol nincs is mit megnezni. A token
      // helye viszont mindig ugyanaz: store/.dashboard-token.
      const uzenet = (typeof window.t === 'function')
        ? window.t('auth.notoken.alert', { url: location.origin })
        : 'Dashboard access failed. The access token is in store/.dashboard-token ' +
          'inside the install folder. Open: ' + location.origin + '/?token=<token>'
      alert(uzenet)
    }
  }

  // Drop the access token from this browser: the persisted copy AND the
  // in-memory one. Signing out has to go through here, because a browser that
  // still holds a token is waved straight back in by the fetch wrapper on the
  // next page load -- so "log out" that only ends the session cookie does
  // nothing visible in a token-carrying browser.
  window.__marveenForgetToken = function forgetToken() {
    sessionToken = ''
    try { localStorage.removeItem(TOKEN_KEY) } catch { /* storage blocked */ }
  }

  // Accept either a bare token or the whole startup URL (people paste the
  // full https://host/?token=... link). Returns the token, or '' if there is
  // nothing usable. Shared by the login overlay's recovery box and the PWA
  // paste prompt.
  function extractToken(raw) {
    let token = (raw || '').trim()
    if (!token) return ''
    if (token.includes('token=')) {
      let extracted = null
      try { extracted = new URL(token).searchParams.get('token') } catch { /* not a full URL */ }
      if (!extracted) {
        // covers ?token=, &token=, and the hash form (/#...?token=...)
        const m = token.match(/[?&#]token=([^&#\s]+)/)
        if (m) extracted = m[1]
      }
      if (extracted) { try { token = decodeURIComponent(extracted) } catch { token = extracted } }
    }
    return token.trim()
  }

  // Full-screen username+password login overlay. Posts to /api/auth/login; on
  // success the browser has the mv_session cookie and we reload authenticated.
  // `status` is the /api/auth/status payload that decided to show this overlay.
  // When it carries forced_logout, the screen must SAY why the browser was
  // thrown out -- an unexplained logout reads as a broken dashboard, and the
  // owner then hunts for a fault instead of for the password reset that
  // actually happened.
  function showLoginOverlay(status) {
    if (document.getElementById('mv-login-overlay')) return
    const tr = (k, fallback) => (typeof window.t === 'function' ? window.t(k) : fallback) || fallback
    const forced = status && status.forced_logout
    let forcedHtml = ''
    if (forced) {
      // Only the reason we actually recorded is named. An unknown reason code
      // gets the generic sentence rather than a guessed cause.
      const when = forced.at ? new Date(forced.at * 1000).toLocaleString() : ''
      const who = forced.username || tr('auth.forced.unknown_user', 'a user')
      const body = forced.reason === 'break_glass_password_reset'
        ? tr('auth.forced.break_glass', 'The password was reset with the access token, so every session was signed out.')
        : tr('auth.forced.generic', 'Your session was ended on the server.')
      forcedHtml = '<div class="mv-auth-forced" id="mv-login-forced">' +
        '<strong>' + tr('auth.forced.title', 'You were signed out') + '</strong>' +
        '<p>' + body + '</p>' +
        '<p class="mv-auth-forced-meta">' + who + (when ? ' \u00b7 ' + when : '') + '</p>' +
        '<p>' + tr('auth.forced.next', 'Sign in with the NEW password. If you did not do this, change the password now and check who has the access token.') + '</p>' +
      '</div>'
    }
    const overlay = document.createElement('div')
    overlay.id = 'mv-login-overlay'
    overlay.className = 'mv-auth-overlay'
    overlay.innerHTML =
      '<form class="mv-auth-card" id="mv-login-form">' +
        '<h2>' + tr('auth.login.title', 'Sign in') + '</h2>' +
        '<p class="mv-auth-desc">' + tr('auth.login.desc', 'Enter your dashboard username and password.') + '</p>' +
        forcedHtml +
        '<input id="mv-login-user" type="text" autocomplete="username" autocapitalize="off" autocorrect="off" spellcheck="false" placeholder="' + tr('auth.login.username', 'Username') + '">' +
        '<input id="mv-login-pass" type="password" autocomplete="current-password" placeholder="' + tr('auth.login.password', 'Password') + '">' +
        '<button type="submit" id="mv-login-submit">' + tr('auth.login.submit', 'Sign in') + '</button>' +
        '<div class="mv-auth-err" id="mv-login-err"></div>' +
        // The way back in when the password is gone. Hidden behind one click so
        // the ordinary login stays a two-field screen, but ALWAYS present: an
        // install whose only recovery path is a terminal command is locked for
        // a non-technical owner (Boss, 2026-08-20: could not get in on the
        // desktop, and there was no "forgot password" anywhere).
        '<button type="button" class="mv-auth-link" id="mv-login-forgot">' +
          tr('auth.login.forgot', "I don't know my password") + '</button>' +
        '<div class="mv-auth-recover" id="mv-login-recover" hidden>' +
          '<p>' + tr('auth.recover.desc', 'You can get in with the access token instead of the password, and set a new password once inside.') + '</p>' +
          '<ol>' +
            '<li>' + tr('auth.recover.step_phone', 'On your phone (where the dashboard is already open): Settings -> Security -> mobile login QR. The token is in that code.') + '</li>' +
            '<li>' + tr('auth.recover.step_file', 'Or on this machine, in the file store/.dashboard-token inside the install folder.') + '</li>' +
            '<li>' + tr('auth.recover.step_server', 'Or in the server startup log: the "Dashboard access URL" line, the part after ?token=.') + '</li>' +
          '</ol>' +
          '<textarea id="mv-login-token" rows="3" autocapitalize="off" autocorrect="off" spellcheck="false" placeholder="' +
            tr('auth.recover.placeholder', 'Paste the token or the whole ?token=... link here') + '"></textarea>' +
          '<button type="button" id="mv-login-token-btn">' + tr('auth.recover.submit', 'Sign in with token') + '</button>' +
          '<div class="mv-auth-err" id="mv-login-token-err"></div>' +
          '<p class="mv-auth-recover-cli">' + tr('auth.recover.cli', 'No token either? Run this in a terminal in the install folder:') +
            '<code>npm run dashboard-user -- reset-password &lt;username&gt;</code></p>' +
        '</div>' +
      '</form>'
    document.body.appendChild(overlay)
    const form = overlay.querySelector('#mv-login-form')
    const userEl = overlay.querySelector('#mv-login-user')
    const passEl = overlay.querySelector('#mv-login-pass')
    const errEl = overlay.querySelector('#mv-login-err')
    const submitEl = overlay.querySelector('#mv-login-submit')
    const recoverEl = overlay.querySelector('#mv-login-recover')
    overlay.querySelector('#mv-login-forgot').addEventListener('click', () => {
      recoverEl.hidden = !recoverEl.hidden
      if (!recoverEl.hidden) overlay.querySelector('#mv-login-token').focus()
    })
    const tokenBtn = overlay.querySelector('#mv-login-token-btn')
    tokenBtn.addEventListener('click', async () => {
      const tokenErr = overlay.querySelector('#mv-login-token-err')
      tokenErr.textContent = ''
      const token = extractToken(overlay.querySelector('#mv-login-token').value || '')
      if (!token) { tokenErr.textContent = tr('auth.recover.err_empty', 'Paste the token first.'); return }
      // Verify BEFORE storing. A wrong token would otherwise be saved, 401 on
      // the next call, get wiped, and drop the user back on the same login
      // screen with no idea what went wrong.
      tokenBtn.disabled = true
      try {
        const r = await originalFetch('/api/auth/status', { headers: { Authorization: 'Bearer ' + token } })
        const data = r.ok ? await r.json().catch(() => null) : null
        if (!data || !data.authenticated) {
          tokenErr.textContent = tr('auth.recover.err_invalid', 'This token is not valid.')
          return
        }
      } catch {
        tokenErr.textContent = tr('auth.login.err_network', 'Network error.')
        return
      } finally {
        tokenBtn.disabled = false
      }
      try { localStorage.setItem(TOKEN_KEY, token) } catch { /* storage blocked */ }
      window.location.reload()
    })
    form.addEventListener('submit', async (e) => {
      e.preventDefault()
      errEl.textContent = ''
      const username = (userEl.value || '').trim()
      const password = passEl.value || ''
      if (!username || !password) { errEl.textContent = tr('auth.login.err_empty', 'Enter a username and password.'); return }
      submitEl.disabled = true
      try {
        const r = await originalFetch('/api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ username, password }),
        })
        if (r.ok) { window.location.reload(); return }
        if (r.status === 429) {
          let retry = 0
          try { retry = (await r.json()).retry_after_s || 0 } catch { /* ignore */ }
          errEl.textContent = tr('auth.login.err_throttled', 'Too many attempts. Try again later.') + (retry ? ' (' + retry + 's)' : '')
        } else {
          errEl.textContent = tr('auth.login.err_invalid', 'Invalid credentials.')
        }
      } catch {
        errEl.textContent = tr('auth.login.err_network', 'Network error.')
      } finally {
        submitEl.disabled = false
      }
    })
    setTimeout(() => userEl.focus(), 50)
  }

  // Full-screen, one-time token paste for installed PWAs (see the 401 handler).
  // The user pastes the access token (the value after ?token= in the server's
  // startup URL, or from the dashboard Settings / mobile-login QR); it is saved
  // to this app instance's localStorage and the page reloads authenticated.
  function showStandaloneTokenPrompt(tokenKey) {
    if (document.getElementById('mv-token-overlay')) return
    // Lang files are not yet loaded here; use a local inline lookup so EN mode works.
    const _lang = localStorage.getItem('marveen.lang') || 'hu'
    const _pwa = {
      hu: {
        title: 'Hozzáférés szükséges',
        desc: 'A home-screen app saját tárhelye még üres. Illeszd be a dashboard access tokent (a szerver indítási URL-jében a ?token= utáni rész, vagy a Beállítások / mobil-login QR), és elmentődik ehhez az apphoz.',
        btn: 'Mentés és újratöltés',
        empty_token: 'Üres token.'
      },
      en: {
        title: 'Access Required',
        desc: "The home-screen app's own storage is empty. Paste the dashboard access token (the part after ?token= in the server startup URL, or from Settings / mobile-login QR), and it will be saved for this app.",
        btn: 'Save & Reload',
        empty_token: 'Empty token.'
      }
    }
    const _p = _pwa[_lang] || _pwa.hu
    const overlay = document.createElement('div')
    overlay.id = 'mv-token-overlay'
    overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#1a1917;color:#faf9f5;' +
      'display:flex;align-items:center;justify-content:center;padding:24px;' +
      'font-family:system-ui,-apple-system,sans-serif'
    overlay.innerHTML =
      '<div style="max-width:420px;width:100%;display:flex;flex-direction:column;gap:14px">' +
        '<h2 style="margin:0;font-size:18px;text-align:center">' + _p.title + '</h2>' +
        '<p style="margin:0;font-size:14px;opacity:0.8;line-height:1.5;text-align:center">' +
          _p.desc + '</p>' +
        '<textarea id="mv-token-input" rows="3" autocapitalize="off" autocorrect="off" spellcheck="false" ' +
          'style="width:100%;box-sizing:border-box;padding:10px;border-radius:8px;border:1px solid #555;' +
          'background:#0f0e0d;color:#faf9f5;font-size:14px;font-family:monospace" placeholder="token..."></textarea>' +
        '<button id="mv-token-save" style="padding:12px;border:0;border-radius:8px;background:#10b981;' +
          'color:#fff;font-size:15px;font-weight:600">' + _p.btn + '</button>' +
        '<div id="mv-token-err" style="color:#f87171;font-size:13px;min-height:16px;text-align:center"></div>' +
      '</div>'
    document.body.appendChild(overlay)
    const input = overlay.querySelector('#mv-token-input')
    const errEl = overlay.querySelector('#mv-token-err')
    const submit = () => {
      const token = extractToken(input.value || '')
      if (!token) { errEl.textContent = _p.empty_token; return }
      localStorage.setItem(tokenKey, token)
      window.location.reload()
    }
    overlay.querySelector('#mv-token-save').addEventListener('click', submit)
    setTimeout(() => input.focus(), 50)
  }
})()

// === Theme ===
const html = document.documentElement
// Hard refresh, for the installed-app window that has no browser controls.
//
// JavaScript cannot press Ctrl+Shift+R, and location.reload() may serve the
// cached copy -- which is the whole problem. What it CAN do is what the
// shortcut does underneath: throw away the stored copies, then load again.
// (index.html azota ?v= verziot ir a /app.js es /style.css hivatkozasaba, de ez
// a gomb marad a vegso mento: egy makacsul beragadt lapot is kitisztit.)
//
// Both layers are cleared: any Cache Storage left behind by the retired service
// worker, and the ordinary HTTP cache, by re-fetching the shell with
// cache:'reload' (which forces a trip to the server) before reloading.
async function hardRefresh() {
  const btn = document.getElementById('hardRefreshBtn')
  if (btn) btn.disabled = true
  try {
    if (window.caches) {
      const keys = await caches.keys()
      await Promise.all(keys.map(k => caches.delete(k)))
    }
  } catch { /* best-effort: a failure here must not block the reload */ }
  try {
    await Promise.all(['/', '/app.js', '/style.css'].map(u => fetch(u, { cache: 'reload' }).catch(() => {})))
  } catch { /* same */ }
  location.reload()
}
document.getElementById('hardRefreshBtn')?.addEventListener('click', hardRefresh)

// === "Frissult a felulet" csik ==============================================
//
// Boss, 2026-08-20: "A mi valtozott tetel lista gomb nem mukodik." A gomb jo
// volt, a szerver is: a nyitva hagyott lapja futtatta a TEGNAPI app.js-t. Az
// index.html frissult (no-cache), tehat az UJ gombot megkapta -- a hozza tartozo
// kodot nem. Kattintasra igy nem tortent semmi, es ezt kivulrol semmi nem
// arulta el. Pontosan ez a legrosszabb hibafajta: nem hibauzenet, hanem CSEND.
//
// Innentol a lap maga veszi eszre. Ket ellenorzes fut:
//   1. a betoltott app.js ?v= cimkeje a script-tagbol -- ez a betoltes
//      pillanatat rogziti, tehat akkor is helyes, ha a telepites a betoltes es
//      az elso lekerdezes koze esik;
//   2. a teljes felulet-belyeg (app.js + style.css + a ket nyelvi fajl), hogy
//      egy CSAK stilus- vagy CSAK szoveg-valtozas se maradjon eszrevetlen.
//
// 2026-08-21 ota MAGUNKTOL toltunk ujra. A Boss kerese: "ez ne jelenjen meg
// tobbet! ha kell toltse ujra de automatikusan". A fekete csik ugyanis csak
// egy tovabbi kattintas volt ugyanarra, amit a lap maga is el tud vegezni.
//
// EGY dolgot vedunk: a felig beirt szoveget. Ha eppen egy mezoben all a
// kurzor, vagy nyitva van egy ablak, VARUNK a betoltessel, es par
// masodpercenkent ujraprobaljuk -- az ujratoltes elveszitene a begepelt
// szoveget, es azt semmilyen frissesseg nem eri meg. Amint a mezo elveszti a
// fokuszt, a lap magatol frissul.
const APP_VERSION_POLL_MS = 120000
let appVersionBaseline = null
let appUpdateNoticeShown = false

/** A betoltott app.js verzio-cimkeje a sajat script-tagunkbol. Ha az index.html
 *  valamiert nem verziozott, null -- akkor csak a 2. ellenorzes marad. */
function loadedAppVersion() {
  const el = document.querySelector('script[src*="/app.js"]')
  const src = el ? el.getAttribute('src') || '' : ''
  const m = src.match(/[?&]v=([^&"]+)/)
  return m ? m[1] : null
}

/**
 * Eppen olyasmit csinal a felhasznalo, amit egy ujratoltes tonkretenne?
 *
 * Ket eset: (1) szoveges mezoben all a kurzor -- ott begepelt szoveg lehet;
 * (2) nyitva van egy ablak (modal) -- ott felig kitoltott urlap allhat.
 * Barmelyik igaz, varunk.
 */
function reloadWouldInterrupt() {
  const el = document.activeElement
  if (el) {
    const tag = (el.tagName || '').toLowerCase()
    if (tag === 'input' || tag === 'textarea' || tag === 'select') return true
    if (el.isContentEditable) return true
  }
  const modal = document.querySelector('.modal-overlay:not([hidden])')
  return !!modal
}

const APP_UPDATE_RETRY_MS = 4000

/** Ujratoltes az uj verziora -- magatol, gomb nelkul. */
function showAppUpdateNotice() {
  if (appUpdateNoticeShown) return
  appUpdateNoticeShown = true
  const go = () => {
    if (reloadWouldInterrupt()) { setTimeout(go, APP_UPDATE_RETRY_MS); return }
    hardRefresh()
  }
  go()
}

async function checkAppVersion() {
  // Rejtett lapon nincs mit kozolni, es felesleges is kerdezni.
  if (document.hidden) return
  try {
    const res = await fetch('/api/app-version', { cache: 'no-store' })
    if (!res.ok) return
    const data = await res.json()
    if (!data || typeof data.v !== 'string') return
    const loaded = loadedAppVersion()
    if (loaded && typeof data.app === 'string' && data.app !== loaded) { showAppUpdateNotice(); return }
    if (appVersionBaseline === null) { appVersionBaseline = data.v; return }
    if (data.v !== appVersionBaseline) showAppUpdateNotice()
  } catch { /* halozati hiba: a kovetkezo kor ujra probalja */ }
}

document.addEventListener('DOMContentLoaded', () => {
  checkAppVersion()
  setInterval(checkAppVersion, APP_VERSION_POLL_MS)
  // A visszateres a leggyakoribb pillanat, amikor mar reg kiment az uj verzio.
  document.addEventListener('visibilitychange', () => { if (!document.hidden) checkAppVersion() })
})

const themeToggle = document.getElementById('themeToggle')
const savedTheme = localStorage.getItem('cc-theme')
if (savedTheme) {
  html.setAttribute('data-theme', savedTheme)
} else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
  html.setAttribute('data-theme', 'dark')
}
themeToggle.addEventListener('click', () => {
  const next = html.getAttribute('data-theme') === 'dark' ? 'light' : 'dark'
  html.setAttribute('data-theme', next)
  localStorage.setItem('cc-theme', next)
})

// === Language toggle ===
;(() => {
  const btn = document.getElementById('langToggle')
  if (!btn) return
  function syncLangBtn() {
    btn.textContent = (window._lang || 'hu').toUpperCase()
  }
  syncLangBtn()
  btn.addEventListener('click', () => {
    const next = (window._lang || 'hu') === 'hu' ? 'en' : 'hu'
    window.setLang(next)
    syncLangBtn()
  })
  // Keep button in sync when setLang is called from elsewhere (e.g. /api/settings async load).
  const _origSetLang = window.setLang
  window.setLang = function setLang(lang) {
    _origSetLang(lang)
    syncLangBtn()
  }
})()

// === Page switching ===
const navLinks = document.querySelectorAll('.sb-link[data-page], .nav-link[data-page]')
const pages = document.querySelectorAll('.page')

function confirmSettingsLeave() {
  if (settingsDirty.size === 0) return true
  return window.confirm(t('settings.unsaved_warning'))
}

// Nem surgos munka: akkor fusson, amikor a bongeszo eppen rerer -- de a
// timeout garantalja, hogy ne maradjon el. Boss, 2026-08-19: "ami nem fontos
// azt a hatterben kesobb is be lehet tolteni." A dashboard szervere EGY szalon
// fut, tehat minden indulaskor kilott kereses a latszo oldal elol eszi el az
// idot: merve az email 1. oszlopa egy 282 ms-os lekeresre 579 ms-ot vart.
function runLater(fn, timeout = 1500) {
  let done = false
  const once = () => { if (done) return; done = true; fn() }
  // A requestIdleCallback ONMAGABAN nem eleg: merve (Playwright/Chromium,
  // 2026-08-19) 6 masodperc alatt EGYSZER SEM sult el, es hattertabon eleve
  // nem fut. Ezert mindig van mellette egy sima idozito is -- amelyik elobb
  // jon, az inditja, a masik utana mar nem csinal semmit.
  if (typeof requestIdleCallback === 'function') requestIdleCallback(once, { timeout })
  setTimeout(once, timeout)
}

function switchPage(pageId) {
  // 'team' is merged into 'agents'; any internal call still passing 'team' redirects.
  if (pageId === 'team') { _agentsActiveView = 'tree'; pageId = 'agents' }
  // A Kod-hid mar NEM kulon lap a bal menuben, hanem a VS Code ugynok
  // kartyaja alatt nyilo ablak -- ugyanott, ahol minden mas ugynok
  // beallitasa (Boss, 2026-08-22: "miert kivetelezunk vele?"). A regi
  // mely-hivatkozasok (#codeBridge hash, az Attekintes onellenorzes-sorai)
  // valtozatlanul ide erkeznek: az Ugynokok lapra visszuk, es kinyitjuk.
  if (pageId === 'codeBridge') { switchPage('agents'); openCodeBridgeModal(); return }
  // A Raktar (regi neven Depo) sem kulon lap tobbe: a beallitasai az Iroda ->
  // Beallitasok ala kerultek, a Raktar menupont alatt pedig a TARTALOM (Drive,
  // Fotok) all (Boss, 2026-08-27). A regi #depo mely-hivatkozasok -- a lapon
  // belul maradt gombok, a konyvjelzok -- valtozatlanul ide erkeznek.
  if (pageId === 'depo') { switchPage('irodaSettings'); openIrodaDepotSettings(); return }
  // Guard unsaved settings before leaving the settings page
  if (!document.getElementById('settingsPage').hidden && pageId !== 'settings' && !confirmSettingsLeave()) return
  pages.forEach((p) => (p.hidden = p.id !== pageId + 'Page'))
  // Re-queried live, NOT the module-level `navLinks` snapshot -- that const
  // was captured once at script load, before dynamically-rendered nav links
  // (each email account's own sidebar entry, added later by
  // renderEmailAccountNav()) existed, so it can never clear THEIR .active
  // class and they'd stay visually "active" forever after first being
  // selected once, regardless of which page is actually open.
  document.querySelectorAll('.sb-link[data-page], .nav-link[data-page]').forEach((l) => l.classList.toggle('active', l.dataset.page === pageId))
  // A csoport-fejlec is mutassa, ha a csoporton BELUL all az aktiv oldal.
  // Enelkul egy csukott csoport elnyeli a "hol vagyok" jelzest, es nyitottnal
  // sem derul ki, hogy az az oldal ODA tartozik (Boss, 2026-08-29).
  document.querySelectorAll('.sb-group').forEach((g) => {
    g.classList.toggle('has-active-child', !!g.querySelector('.sb-group-items .sb-link.active'))
  })
  openSidebarGroupForPage(pageId)
  // A Raktar csoport a #navIroda-ban van, ahova a SIDEBAR_GROUPS gepezet
  // szandekosan nem lat el (az csak a #navMarvin csoportjait sopri). Ha a
  // Drive vagy a Fotok az aktiv lap, a csoport nem maradhat csukva: a "hol
  // vagyok" jelzes nem bujhat el egy osszecsukott menu mogott.
  if (pageId === 'drive' || pageId === 'photos') {
    const depotGroup = document.querySelector('.sb-group[data-group="depot-content"]')
    if (depotGroup && !depotGroup.classList.contains('open')) {
      depotGroup.classList.add('open')
      document.getElementById('depotNavToggle')?.setAttribute('aria-expanded', 'true')
    }
  }
  // Kanban and Email need full-width layout (overrides main's max-width: 1200px)
  document.querySelector('main').classList.toggle('kanban-active', pageId === 'kanban')
  document.querySelector('main').classList.toggle('email-active', pageId === 'email')
  // Activity page runs a live poll; stop it whenever we navigate away.
  if (pageId !== 'activity') stopActivityPoll()
  if (pageId === 'activity') startActivityPoll()
  // The 3s working/idle poll itself (source for the Agents page's Terminal
  // button tint AND the sidebar's global working badge) runs unconditionally,
  // started once at page load -- see startGlobalActivityPoll() below. It used
  // to start/stop with the Agents page, which is exactly why the green
  // indicator "disappeared" on every other page (Boss, 2026-08-17, 5th report
  // of the same complaint). Only the slower full-card data refresh stays
  // page-scoped, since redrawing the whole grid is only useful while it's visible.
  if (pageId !== 'agents') stopAgentsDataRefresh()
  // Kanban auto-refresh: start on enter, stop on leave.
  if (pageId !== 'kanban') stopKanbanRefresh()
  // A Fotok engedely-folyamata 2 masodpercenkent kerdezi a szervert. Ha
  // elnavigalunk, nincs kinek mutatni az eredmenyt -- allitsuk le. Maga a
  // bejelentkeztetes a szerveren fut tovabb, es a Kapcsolatok oldalon (vagy
  // ide visszaterve) ugyanugy befejezheto.
  if (pageId !== 'photos') _photosConsentReset()
  if (pageId === 'overview') loadOverview()
  if (pageId === 'kanban') { if (typeof _initGanttViewSwitcher === 'function') _initGanttViewSwitcher(); loadKanban(); startKanbanRefresh() }
  if (pageId === 'tasks') loadSchedules()
  if (pageId === 'agents') { loadAgents().then(() => _setAgentsView(_agentsActiveView || 'grid')); startAgentsDataRefresh() }
  if (pageId === 'memories') { loadMemAgents(); loadMemStats(); loadMemories() }
  if (pageId === 'skills') loadGlobalSkills()
  if (pageId === 'connectors') loadConnectors()
  if (pageId === 'migrate') loadMigrateAgents()
  if (pageId === 'docs') loadDocs()
  if (pageId === 'research') loadResearch()
  if (pageId === 'status') loadStatus()
  if (pageId === 'recall') loadRecallPage()
  if (pageId === 'bgTasks') loadBgTasksPage()
  if (pageId === 'vault') loadVaultPage()
  if (pageId === 'drive') loadDrivePage()
  // A Depo oldal kerdezgeti a szervert, amig egy koltoztetes vagy szinkron fut.
  // Elnavigalva nincs kinek mutatni -- de a MUNKA a szerveren fut tovabb, es
  // ide visszaterve a poll magatol ujraindul (lasd _depoRefresh).
  if (pageId !== 'irodaSettings') _depoStopPoll()
  if (pageId === 'intezo') loadIntezoPage()
  // Elhagyva a Fotok oldalt: a kepek blob URL-jei feleslegesen ulnek a
  // memoriaban, es egy futo Picker-lekerdezes sem szolhat bele mas lapba.
  if (pageId !== 'photos') { _photosStopPoll(); _photosReleaseBlobs() }
  if (pageId === 'photos') loadPhotosPage()
  if (pageId === 'accounts') loadAccountsPage()
  if (pageId === 'approvals') loadApprovalsPage()
  if (pageId === 'debate') loadDebatePage()
  if (pageId === 'openrouter') loadOpenRouterPage()
  if (pageId !== 'settings') stopRunningIndicatorPoll()
  if (pageId === 'settings') loadSettings()
  if (pageId === 'updates') loadUpdates()
  // 'team' page is merged into 'agents' -- redirect for any lingering deep-links
  if (pageId === 'messages') loadMessagesPage()
  if (pageId === 'tokenUsage') loadTokenUsage()
  if (pageId === 'costs') loadCosts()
  if (pageId === 'ideas') loadIdeasPage()
  // These two loaders live in IIFEs further down this file, so a DIRECT load of
  // their hash (a refresh, or a link straight to #naplo / #archived) reaches
  // switchPage before the definition has been parsed: that threw a
  // ReferenceError and left the page blank -- found 2026-08-10 while checking
  // where card references lead. callPageLoader retries once parsing is done.
  if (pageId === 'archived') callPageLoader('loadArchivedPage')
  if (pageId === 'naplo') callPageLoader('loadNaplo')
  if (pageId === 'federation') loadFederationPage()
  if (pageId === 'email') loadEmailPage()
  if (pageId === 'irodaSettings') loadIrodaSettings()
}

// Calls a page loader that may not be defined yet (see the naplo/archived note
// in switchPage). Runs it immediately when it exists, otherwise once the
// document has finished parsing -- by which point every IIFE in this file has.
function _cbStopPoll() {
  if (typeof window.__cbStopPollImpl === 'function') window.__cbStopPollImpl()
}

function callPageLoader(name) {
  if (typeof window[name] === 'function') { window[name](); return }
  document.addEventListener('DOMContentLoaded', () => {
    if (typeof window[name] === 'function') window[name]()
  }, { once: true })
}

// Mobile off-canvas sidebar toggle. No-op visual effect on desktop (the
// hamburger/backdrop are display:none there); on narrow screens it slides the
// sidebar in over a backdrop.
const sidebarEl = document.querySelector('.sidebar')
const sidebarBackdrop = document.getElementById('sidebarBackdrop')
const mobileMenuBtn = document.getElementById('mobileMenuBtn')
function setSidebarOpen(open) {
  if (sidebarEl) sidebarEl.classList.toggle('open', open)
  if (sidebarBackdrop) sidebarBackdrop.classList.toggle('open', open)
  if (mobileMenuBtn) mobileMenuBtn.setAttribute('aria-expanded', open ? 'true' : 'false')
}
if (mobileMenuBtn) mobileMenuBtn.addEventListener('click', () => setSidebarOpen(!sidebarEl.classList.contains('open')))
if (sidebarBackdrop) sidebarBackdrop.addEventListener('click', () => setSidebarOpen(false))

navLinks.forEach((link) => {
  link.addEventListener('click', (e) => {
    e.preventDefault()
    const pageId = link.dataset.page
    // Same hash won't fire 'hashchange', so re-render manually; otherwise let the
    // hashchange listener drive switchPage so the URL stays the single source of truth.
    if (location.hash.slice(1) === pageId) switchPage(pageId)
    else location.hash = pageId
    setSidebarOpen(false) // close the drawer after navigating on mobile
  })
})

// === Workspace switch (Marvin / Iroda) ===
// Two fully separate <nav> trees so Iroda-side additions (email today, more
// later) never touch the upstream Szotász sidebar markup -- a future
// `git pull` from upstream can't conflict with anything added here.
const WORKSPACE_LS_KEY = 'marveen.workspace'
// A Drive is ide tartozik: enelkul az Iroda-ra valtas a Drive oldalrol
// atdobna a #email-re (a lenti 'nem ehhez a munkateruletehez tartozik' ag).
// A MARKUPBOL olvassuk ki, nem kezzel tartjuk karban. Ez a lista korabban egy
// beirt objektum volt, es KETSZER csuszott el: eloszor a Drive maradt ki,
// most a Fotok es a Dokumentumok (Boss, 2026-08-15: "a ctrl shift r re az
// email jon be. a fotokon allok akkor miert nem a fotok jon be? elugrik
// frisiteskor."). A tunet mindig ugyanaz: az oldal betolt, majd egy pillanat
// mulva atdob az Emailre -- mert a munkatereulet-visszaallitas ugy latja, hogy
// ez az oldal "nem ide tartozik". Igy uj Iroda-oldal felvetelekor nincs mit
// elfelejteni: eleg az oldalsavba betenni.
function irodaPages() {
  // Az Email kezzel: nem statikus link, hanem a fiokonkenti almenu (a
  // ensureEmailAccountNav() rakja be), ami a munkateruleten kivul meg nem letezik.
  // A `depo` szinten kezzel: a Raktar beallitasai atkerultek az Iroda ->
  // Beallitasok ala, ezert nincs sajat data-page="depo" linkje. Enelkul a
  // munkateruelet-visszaallitas "nem irodai"-nak latna, es a #depo hivatkozas
  // az Emailre dobna -- pontosan az a hiba, amit 2026-08-15-en jeleztel.
  const set = { email: true, depo: true }
  document.querySelectorAll('#navIroda [data-page]').forEach((l) => { set[l.dataset.page] = true })
  return set
}
function setWorkspace(ws, opts) {
  const persist = !opts || opts.persist !== false
  const navMarvinEl = document.getElementById('navMarvin')
  const navIrodaEl = document.getElementById('navIroda')
  if (navMarvinEl) navMarvinEl.hidden = ws !== 'marvin'
  if (navIrodaEl) navIrodaEl.hidden = ws !== 'iroda'
  if (ws === 'iroda') ensureEmailAccountNav()
  document.getElementById('wsBtnMarvin')?.classList.toggle('active', ws === 'marvin')
  document.getElementById('wsBtnIroda')?.classList.toggle('active', ws === 'iroda')
  if (persist) { try { localStorage.setItem(WORKSPACE_LS_KEY, ws) } catch {} }
  // Switching workspace while the visible page belongs to the OTHER one would
  // leave an orphaned page on screen with no matching nav link lit up --
  // land on that workspace's first page instead.
  //
  // `opts.page`: az induló visszaállítás megmondhatja, MELYIK oldalra tartunk.
  // A `.active` osztályt ugyanis a switchPage() teszi ki, és induláskor az még
  // meg sem történt -- ilyenkor "egyik oldal sem irodai"-t látnánk, és a lap
  // az Emailre ugrana, pedig épp a Raktárra tartott (Boss, 2026-08-15: "az iroda
  // Depo alatti resz nem mukodik").
  const activeLink = document.querySelector('.sb-link.active[data-page]')
  const activePage = (opts && opts.page) || activeLink?.dataset?.page
  const activeIsIroda = !!irodaPages()[activePage]
  if (ws === 'iroda' && !activeIsIroda) location.hash = 'email'
  if (ws === 'marvin' && activeIsIroda) location.hash = 'overview'
}
document.getElementById('wsBtnMarvin')?.addEventListener('click', () => setWorkspace('marvin'))
document.getElementById('wsBtnIroda')?.addEventListener('click', () => setWorkspace('iroda'))

// Email sidebar accordion (Iroda -> Email): click toggles the account submenu
// open/closed, same visual language as the Marvin-side .sb-group sections but
// kept independent of SIDEBAR_GROUPS since it lists dynamic accounts, not a
// fixed set of pages.
document.getElementById('emailNavToggle')?.addEventListener('click', () => {
  const group = document.querySelector('.sb-group[data-group="email-accounts"]')
  if (!group) return
  const open = !group.classList.contains('open')
  group.classList.toggle('open', open)
  document.getElementById('emailNavToggle')?.setAttribute('aria-expanded', open ? 'true' : 'false')
})

// Raktar-almenu (Iroda -> Raktar): a Depo TARTALMA, azaz a Drive es a Fotok.
// Ugyanaz a kezi kezeles, mint az Emailnel, ugyanabbol az okbol: a
// SIDEBAR_GROUPS gepezet szandekosan csak a #navMarvin csoportjaira fut.
document.getElementById('depotNavToggle')?.addEventListener('click', () => {
  const group = document.querySelector('.sb-group[data-group="depot-content"]')
  if (!group) return
  const open = !group.classList.contains('open')
  group.classList.toggle('open', open)
  document.getElementById('depotNavToggle')?.setAttribute('aria-expanded', open ? 'true' : 'false')
})
{
  let savedWs = 'marvin'
  try { savedWs = localStorage.getItem(WORKSPACE_LS_KEY) || 'marvin' } catch {}
  // Deferred to a macrotask: this runs very early in the script (line ~460s),
  // but setWorkspace('iroda') now calls ensureEmailAccountNav(), which reads
  // the module-level `let emailAccounts` declared thousands of lines further
  // down. `let` is hoisted but stays in the temporal dead zone until its own
  // declaration line executes -- reading it this early throws
  // "Cannot access 'emailAccounts' before initialization", silently breaking
  // this whole restore call for anyone whose saved workspace is 'iroda'
  // (Boss, 2026-08-05: exactly this -- the Email account list never
  // appeared, on desktop OR phone, because this is the common case: he'd
  // been on Iroda most of the day). setTimeout(...,0) runs after the
  // rest of this script has finished executing top-to-bottom, by which
  // point every top-level declaration -- emailAccounts included -- is safely
  // initialized.
  setTimeout(() => {
    // Ha az URL KONKRET oldalt nevez meg -- frissites, konyvjelzo, megosztott
    // link --, akkor az oldal dont a munkateruletrol, nem forditva. Enelkul a
    // mentett munkaterulet felulbiralja azt, amit a user epp nez, es a lap
    // betoltes utan egy pillanattal elugrik (Boss, 2026-08-15: a Fotokon allva
    // Ctrl+Shift+R utan az Email jott be). A mentett ertek marad az
    // alapertelmezes, ha az URL nem mond semmit -- es persist:false, tehat ez
    // az egyszeri kovetes nem irja felul a user valasztasat sem.
    let ws = savedWs
    const named = decodeURIComponent((location.hash || '').replace(/^#/, ''))
      || new URLSearchParams(window.location.search).get('page') || ''
    if (named && document.getElementById(named + 'Page')) ws = irodaPages()[named] ? 'iroda' : 'marvin'
    setWorkspace(ws, { persist: false, page: named || undefined })
  }, 0)
}

// === Collapsible sidebar groups ===
// Open/closed state lives in localStorage (marveen.sidebarGroups) as a JSON
// array of open group keys. Missing or corrupt state means everything starts
// collapsed -- that is the designed default, not an error.
const SIDEBAR_GROUPS_LS_KEY = 'marveen.sidebarGroups'
// Declarative single source of truth for the group -> pages mapping. The markup
// order is only the default snapshot: at boot the static links are re-parented
// into their group containers per this map, so regrouping a page (say, moving
// naplo under system) or relabeling a group is a one-line change right here.
const SIDEBAR_GROUPS = [
  // 'debate' (Vitaztatas) itt es nem a RENDSZER alatt: ez eszkoz amivel az
  // agenseket dolgoztatjuk egymas ellen egy jobb valaszert -- ugyanaz a fajta
  // dolog mint az Ugynokok/Aktivitas/Uzenetek, nem rendszer-adminisztracio
  // (Boss dontese, 2026-08-10).
  { key: 'team',        labelKey: 'nav.group.team',        pages: ['agents', 'activity', 'debate', 'messages', 'tasks', 'bgTasks'] },
  { key: 'knowledge',   labelKey: 'nav.group.knowledge',   pages: ['memories', 'skills', 'research', 'ideas'] },
  { key: 'stats',       labelKey: 'nav.group.stats',       pages: ['costs', 'tokenUsage'] },
  // 'drive' szandekosan NINCS itt: a Drive fajlbongeszo tartalom, nem
  // rendszer-adminisztracio, ezert az Iroda munkateruletre kerult (Boss,
  // 2026-08-10). Ha ide visszakerulne, a lenti re-parent ciklus visszarantana
  // a RENDSZER csoportba, fuggetlenul attol hova teszi az index.html.
  { key: 'system',      labelKey: 'nav.group.system',      pages: ['status', 'naplo', 'updates', 'settings', 'vault'] },
  { key: 'connections', labelKey: 'nav.group.connections', pages: ['connectors', 'federation', 'migrate'] },
]
// Scoped to #navMarvin: the Iroda-side email-accounts group (index.html:208)
// also matches a bare `.sb-group[data-group]` selector, but SIDEBAR_GROUPS
// above only knows the 5 Marvin groups. Unscoped, this collection silently
// swept up the email group too: the boot loop below (openKeys.includes(...))
// always resolves false for 'email-accounts' (nothing ever persists that key
// -- the dedicated toggle at line ~458 doesn't call setSidebarGroupOpen), so
// every load stripped the `open` class the HTML shipped with, and the click
// listener registered here doubled up with the dedicated #emailNavToggle
// listener, cancelling every click (open -> close -> open nets to no-op).
// Result: #emailAccountNavItems was correctly populated but `display:none`
// forever (Boss, 2026-08-06: "Email" header visible, nothing listed under it).
const sidebarGroupEls = document.querySelectorAll('#navMarvin .sb-group[data-group]')
// data-page -> group key, derived from the map (not the DOM) so the map wins.
const PAGE_SIDEBAR_GROUP = {}
SIDEBAR_GROUPS.forEach((def) => def.pages.forEach((p) => { PAGE_SIDEBAR_GROUP[p] = def.key }))
// Re-parent the 23 static links to match the map. Moving an existing DOM node
// does not invalidate the navLinks refs captured by querySelectorAll at boot.
SIDEBAR_GROUPS.forEach((def) => {
  const group = document.querySelector(`.sb-group[data-group="${def.key}"]`)
  if (!group) return
  const label = group.querySelector('.sb-group-label')
  if (label) label.dataset.i18n = def.labelKey
  const items = group.querySelector('.sb-group-items')
  if (!items) return
  def.pages.forEach((p) => {
    const link = document.querySelector(`.sb-link[data-page="${p}"]`)
    if (link) items.appendChild(link)
  })
})

function loadSidebarGroupState() {
  try {
    const arr = JSON.parse(localStorage.getItem(SIDEBAR_GROUPS_LS_KEY))
    return Array.isArray(arr) ? arr.filter((k) => typeof k === 'string') : []
  } catch { return [] }
}

function setSidebarGroupOpen(groupEl, open, persist = true) {
  groupEl.classList.toggle('open', open)
  const btn = groupEl.querySelector('.sb-group-header')
  if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false')
  if (persist) {
    const key = groupEl.dataset.group
    const state = loadSidebarGroupState().filter((k) => k !== key)
    if (open) state.push(key)
    try { localStorage.setItem(SIDEBAR_GROUPS_LS_KEY, JSON.stringify(state)) } catch {}
  }
}

// Called from switchPage: the active page's group must always be visible so the
// "where am I" highlight is never hidden inside a collapsed group.
function openSidebarGroupForPage(pageId) {
  const key = PAGE_SIDEBAR_GROUP[pageId]
  if (!key) return
  sidebarGroupEls.forEach((g) => {
    // persist=false: only user clicks may be remembered. Persisting the
    // auto-open would let everyday navigation accumulate all 5 groups as
    // saved-open and quietly bring back the flat 23-item menu.
    if (g.dataset.group === key && !g.classList.contains('open')) setSidebarGroupOpen(g, true, false)
  })
}

{
  const openKeys = loadSidebarGroupState()
  sidebarGroupEls.forEach((g) => setSidebarGroupOpen(g, openKeys.includes(g.dataset.group), false))
}
sidebarGroupEls.forEach((g) => {
  const btn = g.querySelector('.sb-group-header')
  if (btn) btn.addEventListener('click', () => setSidebarGroupOpen(g, !g.classList.contains('open')))
})


