// === Avatar Gallery ===
function populateAvatarGrid() {
  const grid = document.getElementById('avatarGrid')
  grid.innerHTML = ''
  for (const avatar of AVATARS) {
    const item = document.createElement('div')
    item.className = 'avatar-grid-item'
    item.dataset.avatar = avatar
    item.innerHTML = `<img src="/avatars/${avatar}" alt="${avatar.replace(/^\d+_/, '').replace('.png', '')}">`
    item.addEventListener('click', () => {
      grid.querySelectorAll('.avatar-grid-item').forEach(i => i.classList.remove('selected'))
      item.classList.add('selected')
      selectedAvatar = avatar
      // Gallery pick and custom upload are mutually exclusive.
      selectedAvatarFile = null
      resetCreateAvatarUpload()
    })
    grid.appendChild(item)
  }
}

// === Wizard logic ===
let cachedProfiles = null
async function loadProfiles() {
  if (cachedProfiles) return cachedProfiles
  try {
    const res = await fetch('/api/profiles')
    if (res.ok) cachedProfiles = await res.json()
  } catch {}
  return cachedProfiles || []
}

function populateProfileSelect(selectEl, descEl, selected) {
  loadProfiles().then((profiles) => {
    selectEl.innerHTML = ''
    for (const p of profiles) {
      const opt = document.createElement('option')
      opt.value = p.id
      const tag = p.permissionMode === 'strict' ? ` (${t('agents.strict_mode')})` : ''
      opt.textContent = `${p.label}${tag}`
      if (p.id === selected) opt.selected = true
      selectEl.appendChild(opt)
    }
    const updateDesc = () => {
      const p = profiles.find(x => x.id === selectEl.value)
      descEl.textContent = p ? p.description : ''
    }
    selectEl.onchange = updateDesc
    updateDesc()
  })
}

// Populate the per-agent Claude subscription plan dropdown from the named
// registry (/api/claude-plans). The empty value means "no named plan" -> the
// agent keeps its raw config-dir / host default. The description line shows the
// plan type + config dir and flags a Channels-forbidden plan so the operator
// sees the guardrail context before saving.
function populatePlanSelect(selectEl, descEl, selected) {
  if (!selectEl) return
  fetch('/api/claude-plans')
    .then(res => (res.ok ? res.json() : []))
    .catch(() => [])
    .then((plans) => {
      const known = plans.some(p => p.id === selected)
      const opts = [`<option value="">${escapeHtml(t('agents.settings.plan_default'))}</option>`]
      for (const p of plans) {
        opts.push(`<option value="${escapeHtml(p.id)}">${escapeHtml(p.label)}</option>`)
      }
      // Preserve an already-assigned plan id that is NOT in the loaded registry
      // (registry edited/renamed, OR /api/claude-plans transiently failed and
      // returned []). Without this the dropdown would resolve to '' and a save
      // would silently wipe the real assignment.
      if (selected && !known) {
        opts.push(`<option value="${escapeHtml(selected)}">${escapeHtml(selected)}${escapeHtml(t('agents.settings.plan_not_found_suffix'))}</option>`)
      }
      selectEl.innerHTML = opts.join('')
      selectEl.value = selected || ''
      const updateDesc = () => {
        if (!descEl) return
        const val = selectEl.value
        if (!val) {
          descEl.textContent = t('agents.settings.plan_default_desc')
          return
        }
        const p = plans.find(x => x.id === val)
        if (!p) {
          descEl.textContent = t('agents.settings.plan_unresolved_desc', { id: val })
          return
        }
        const warn = p.channelsAllowed ? '' : t('agents.settings.plan_no_channels')
        descEl.textContent = `${p.planType} · ${p.configDir}${warn}`
      }
      selectEl.onchange = updateDesc
      updateDesc()
    })
}

// Paints (or clears) the step-3 notice from wizardPersonalityPending. Called from
// resetWizard() too, so a later successful run can never inherit a stale banner.
function renderWizardPendingBanner() {
  const banner = document.getElementById('wizardPendingBanner')
  if (!banner) return
  if (!wizardPersonalityPending) {
    banner.hidden = true
    return
  }
  document.getElementById('wizardPendingTitle').textContent = t('agents.wizard.pending_title')
  document.getElementById('wizardPendingBody').textContent = t('agents.wizard.pending_body')
  const detailEl = document.getElementById('wizardPendingDetail')
  const detail = wizardPersonalityPending.detail
  // The cause is shown, but only when the server actually sent one: an empty
  // string here would render "A hiba oka: " with nothing after it, which reads
  // like the UI lost something.
  if (detail) {
    detailEl.textContent = t('agents.wizard.pending_detail', { detail })
    detailEl.hidden = false
  } else {
    detailEl.textContent = ''
    detailEl.hidden = true
  }
  banner.hidden = false
}

function resetWizard() {
  wizardStep = 1
  agentName.value = ''
  agentDesc.value = ''
  agentModel.value = 'inherit'
  loadAvailableModels()
  selectedAvatar = null
  selectedAvatarFile = null
  // Az avatar-racs indulaskor mar csak kesleltetve epul fel (a sok kis PNG a
  // latszo oldal elol ette az idot) -- ha valaki az elso masodpercben nyitja
  // meg a varazslot, itt epul fel, nem marad ures.
  if (!document.querySelector('#avatarGrid .avatar-grid-item')) populateAvatarGrid()
  document.querySelectorAll('#avatarGrid .avatar-grid-item').forEach(i => i.classList.remove('selected'))
  resetCreateAvatarUpload()
  generatedClaudeMd = ''
  generatedSoulMd = ''
  wizardCreatedName = ''
  wizardPersonalityPending = null
  renderWizardPendingBanner()
  document.getElementById('wizardClaudeMd').value = ''
  document.getElementById('wizardSoulMd').value = ''
  populateProfileSelect(
    document.getElementById('agentProfile'),
    document.getElementById('agentProfileDesc'),
    'default',
  )
  updateWizardUI()
}

function updateWizardUI() {
  // Steps indicator
  document.querySelectorAll('#wizardSteps .wizard-step').forEach((s) => {
    const step = parseInt(s.dataset.step)
    s.classList.toggle('active', step === wizardStep)
    s.classList.toggle('done', step < wizardStep)
  })
  // Panels
  document.getElementById('wizardStep1').hidden = wizardStep !== 1
  document.getElementById('wizardStep2').hidden = wizardStep !== 2
  document.getElementById('wizardStep3').hidden = wizardStep !== 3
}

// Step 1 -> Step 2 (generate)
document.getElementById('wizardNextBtn').addEventListener('click', async () => {
  const name = agentName.value.trim()
  const desc = agentDesc.value.trim()
  if (!name) { agentName.focus(); return }
  if (!desc) { agentDesc.focus(); return }

  wizardStep = 2
  updateWizardUI()

  const statusEl = document.getElementById('wizardGenStatus')
  statusEl.textContent = t('agents.claude_md_generating')

  try {
    // Create agent via API (returns generated content)
    const res = await fetch('/api/agents', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name,
        description: desc,
        model: agentModel.value,
        profile: document.getElementById('agentProfile').value,
      }),
    })

    if (!res.ok) {
      const err = await res.json()
      throw new Error(err.error || 'Ismeretlen hiba')
    }

    const result = await res.json()
    // Backend sanitizes the name (lowercase ASCII, NFD-stripped accents).
    // Use the sanitized form for every follow-up request so accented input
    // like "étrendíró" still resolves to the real agent dir "etrendiro".
    const createdName = result.name || name
    wizardCreatedName = createdName
    // 200 + personalityPending means the agent was created but its personality
    // came from a template. Captured here and painted when step 3 opens, where
    // the operator both sees the placeholder text and can rewrite it.
    wizardPersonalityPending = result.personalityPending
      ? { detail: result.detail || '', warning: result.warning || '' }
      : null
    statusEl.textContent = t('agents.soul_md_generating')

    // Fetch full agent details to get generated content
    const detailRes = await fetch(`/api/agents/${encodeURIComponent(createdName)}`)
    if (detailRes.ok) {
      const detail = await detailRes.json()
      generatedClaudeMd = detail.claudeMd || detail.content || ''
      generatedSoulMd = detail.soulMd || ''
    }

    statusEl.textContent = t('kanban.breakdown.running')

    // Apply the chosen avatar. Custom upload wins over a gallery pick; both go
    // to the same endpoint (FormData for a file, JSON for a gallery name).
    if (selectedAvatarFile) {
      const form = new FormData()
      form.append('avatar', selectedAvatarFile, selectedAvatarFile.name)
      await fetch(`/api/agents/${encodeURIComponent(createdName)}/avatar`, {
        method: 'POST',
        body: form,
      })
    } else if (selectedAvatar) {
      await fetch(`/api/agents/${encodeURIComponent(createdName)}/avatar`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ galleryAvatar: selectedAvatar }),
      })
    }

    // Auto-advance to step 3
    setTimeout(() => {
      wizardStep = 3
      document.getElementById('wizardClaudeMd').value = generatedClaudeMd
      document.getElementById('wizardSoulMd').value = generatedSoulMd
      renderWizardPendingBanner()
      updateWizardUI()
    }, 600)
  } catch (err) {
    showToast(`Hiba: ${err.message}`)
    wizardStep = 1
    updateWizardUI()
  }
})

// Step 3 -> back to step 1
document.getElementById('wizardBackBtn').addEventListener('click', () => {
  wizardStep = 1
  updateWizardUI()
})

// Step 3 -> Create (finalize with edits)
document.getElementById('wizardCreateBtn').addEventListener('click', async () => {
  // Use the backend-sanitized name stored in wizardCreatedName, not the raw
  // input field -- accents in the input would miss the real agent dir.
  const name = wizardCreatedName || agentName.value.trim()
  const claudeMd = document.getElementById('wizardClaudeMd').value
  const soulMd = document.getElementById('wizardSoulMd').value
  const createBtn = document.getElementById('wizardCreateBtn')

  createBtn.disabled = true
  createBtn.querySelector('.btn-text').hidden = true
  createBtn.querySelector('.btn-loading').hidden = false

  try {
    // Update with edited content
    const res = await fetch(`/api/agents/${encodeURIComponent(name)}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ claudeMd, soulMd }),
    })

    if (!res.ok) {
      const err = await res.json()
      throw new Error(err.error || 'Ismeretlen hiba')
    }

    closeModal(agentWizardOverlay)
    // Boss 2026-08-08: the generic success toast looked identical whether the
    // personality was really generated or is still the unedited placeholder
    // template -- the only warning was the banner one screen earlier in step
    // 3, easy to click past straight to "Létrehozás". Say it again, louder,
    // right when the flow actually closes.
    if (wizardPersonalityPending) {
      showToast(t('agents.wizard.created_template_warning'), 6000, true)
    } else {
      showToast('Ugynok letrehozva. Kosd be a csatornat a parosatashoz.')
    }
    await loadAgents()
    // Drop the operator straight into the Telegram tab of the new agent so
    // the pairing step is in front of them -- easy to miss otherwise.
    try {
      await openAgentDetail(name)
      switchAgentTab('channel')
    } catch { /* detail open failed, list refresh already happened */ }
  } catch (err) {
    showToast(`Hiba: ${err.message}`)
  } finally {
    createBtn.disabled = false
    createBtn.querySelector('.btn-text').hidden = false
    createBtn.querySelector('.btn-loading').hidden = true
  }
})

// === Toast ===
// Boss 2026-08-15: "annyira hamar eltunik hogy el sem lehet olvasni". Harom
// valodi hiba volt egyszerre: (1) fix 3 masodperc, fuggetlenul attol hogy az
// uzenet 8 vagy 111 karakter, (2) a CSS egyetlen sorba kenyszeritette a
// szoveget, tehat a hosszu uzenet kilogott a kepernyorol, (3) tiz hivo rosszul
// adta at a masodik parametert (true, illetve 'error'), amibol a setTimeout
// 1 ms-ot, illetve NaN-t csinalt -- azok a csikok gyakorlatilag felvillantak.
// Azota: az ido a szoveg hosszabol szamolodik, minden csikon van bezaro X, a
// hibauzenet magatol EL SEM tunik, es az eger alatt megall a visszaszamlalas.
let toastTimer = null
let toastAutoMs = 0

// Kb. 15 karakter/masodperc olvasasi tempo, 4 mp also es 20 mp felso hatarral.
// A 111 karakteres vektor-uzenet igy ~7 mp-ig lathato 3 helyett.
function toastReadingMs(text) {
  return Math.min(20000, Math.max(4000, 1200 + text.length * 55))
}

function hideToast() {
  if (toastTimer) { clearTimeout(toastTimer); toastTimer = null }
  toastAutoMs = 0
  toast.classList.remove('visible')
}

// A masodik parameter tortenelmi okokbol sokfele lehet: szam (ido), true
// (nagy csik), 'error' (hibauzenet), vagy egy opcio-objektum. Mindet elfogadjuk,
// mert 400+ hivo van, es egy rosszul atadott parameter soha tobbe ne
// eredmenyezzen lathatatlan uzenetet.
//
// `opts.action = { label, onClick }` eseten a csikra egy GOMB is kerul.
// Boss, 2026-08-16: "ez a link jo. de a szoveggel is legyen azert kiirva hogy
// hol van." -- vagyis a SZOVEG mondja meg a helyet (hogy legkozelebb magatol is
// megtalalja), a GOMB pedig vigye oda egy kattintassal. A ketto egyutt, nem
// egymas helyett.
function showToast(msg, opts, big = false) {
  let duration = 0
  let sticky = false
  let type = ''
  let action = null
  if (opts === true) big = true
  else if (typeof opts === 'number' && Number.isFinite(opts)) duration = opts
  else if (typeof opts === 'string') type = opts
  else if (opts && typeof opts === 'object') {
    duration = Number.isFinite(opts.duration) ? opts.duration : 0
    sticky = opts.sticky === true
    type = opts.type || ''
    if (opts.big != null) big = opts.big === true
    // Csak akkor gomb, ha van MIT csinalnia es MI kiirni ra: egy felig atadott
    // akciobol inkabb ne legyen semmi, mint egy nevtelen vagy halott gomb.
    if (opts.action && typeof opts.action.onClick === 'function' && opts.action.label) action = opts.action
  }
  // A hiba es a figyelmeztetes addig marad amig a felhasznalo el nem tunteti:
  // pont ezeket kell elolvasnia, es pont ezek villantak fel eddig.
  if (type === 'error' || type === 'warn') sticky = true
  // Egy gombos csik sem tunhet el az alol a kez alol, amelyik meg nem ert oda.
  if (action) sticky = true

  const text = String(msg ?? '')
  // Egy korabbi csik idozitoje nem olthatja el a most megjelenot.
  if (toastTimer) { clearTimeout(toastTimer); toastTimer = null }
  toast.textContent = ''
  const span = document.createElement('span')
  span.className = 'toast-text'
  span.textContent = text
  const closeBtn = document.createElement('button')
  closeBtn.type = 'button'
  closeBtn.className = 'toast-close'
  // A bezaro gomb cimkeje soha ne buktathasson el egy hibauzenetet: ha az i18n
  // meg nem allt fel, marad a nyers szo.
  closeBtn.setAttribute('aria-label', (typeof t === 'function' ? t('common.close') : '') || 'Close')
  closeBtn.textContent = '×'
  closeBtn.addEventListener('click', hideToast)
  if (action) {
    const actionBtn = document.createElement('button')
    actionBtn.type = 'button'
    actionBtn.className = 'toast-action'
    actionBtn.textContent = String(action.label)
    actionBtn.addEventListener('click', () => {
      // Eloszor eltunik a csik, csak AZUTAN nyilik az ablak: kulonben a csik
      // ottmaradna a megnyitott ablak elott, es a telefonon eppen az takarna
      // ki, amit meg akartunk mutatni (Boss, 2026-08-16 -- ez volt az eredeti
      // panasz is: a bennragadt csik ala esett a gomb).
      hideToast()
      try { action.onClick() } catch (e) { /* egy hibas akcio ne dontse el a csikot */ }
    })
    toast.append(span, actionBtn, closeBtn)
  } else {
    toast.append(span, closeBtn)
  }
  toast.classList.toggle('toast-big', big)
  toast.classList.toggle('toast-error', type === 'error')
  toast.classList.toggle('toast-warn', type === 'warn')
  toast.classList.toggle('toast-sticky', sticky)
  toast.classList.add('visible')
  if (sticky) { toastAutoMs = 0; return }
  toastAutoMs = Math.max(duration > 0 ? duration : 0, toastReadingMs(text))
  toastTimer = setTimeout(hideToast, toastAutoMs)
}

// Az eger alatt ne tunjon el olvasas kozben. Elhagyva ujraindul, de csak rovid
// idore -- addigra a szoveget mar latta.
toast.addEventListener('mouseenter', () => {
  if (toastTimer) { clearTimeout(toastTimer); toastTimer = null }
})
toast.addEventListener('mouseleave', () => {
  if (toastAutoMs > 0 && !toastTimer && toast.classList.contains('visible')) {
    toastTimer = setTimeout(hideToast, 2500)
  }
})

// === Agents API ===
async function loadAgents() {
  try {
    // The federation status fetch is deliberately failure-proof (.catch ->
    // null): it must NEVER take down the Agents page -- including on an
    // older backend where the route 404s.
    const [agentsRes, marveenRes, fedStatus, gateStatus, brokerStatus] = await Promise.all([
      fetch('/api/agents'),
      fetch('/api/marveen'),
      fetch('/api/federation/status').then((r) => (r.ok ? r.json() : null)).catch(() => null),
      // Failure-proof like fedStatus: an older backend without the gate config
      // route must never break the Agents page -- the controls just fall back to
      // "off" everywhere.
      fetch('/api/context-restart-gate').then((r) => (r.ok ? r.json() : null)).catch(() => null),
      fetch('/api/context-broker').then((r) => (r.ok ? r.json() : null)).catch(() => null),
      // Sajat betolto, mert ket vegpontbol all ossze; a hibat maga nyeli le.
      loadCodeBridgeCards().catch(() => {}),
    ])
    agents = await agentsRes.json()
    if (fedStatus && Array.isArray(fedStatus.peers)) federatedPeerStatus = fedStatus.peers
    gateCfgByAgent.clear()
    if (gateStatus && Array.isArray(gateStatus.agents)) {
      for (const a of gateStatus.agents) gateCfgByAgent.set(a.agent, a)
    }
    if (gateStatus && Number.isFinite(gateStatus.autocompactTokens)) {
      ctxLimits = {
        autocompactTokens: gateStatus.autocompactTokens,
        autocompactFiresAt: gateStatus.autocompactFiresAt ?? 0,
        maxGateTokens: gateStatus.maxGateTokens ?? 0,
        minGateTokens: gateStatus.minGateTokens ?? 30000,
      }
    }
    // Nobody designated is a valid, working state (everyone prepares their own
    // context), so an older backend answering null renders as exactly that
    // rather than as an error.
    brokerState = brokerStatus && typeof brokerStatus === 'object'
      ? brokerStatus
      : { designated: null, effective: null, reason: 'unset', steppedOver: null, config: null }
    if (marveenRes.ok) {
      window._marveen = await marveenRes.json()
      // A backend CHANNEL_PROVIDER-éhez igazitsuk a kliens-default-ot,
      // hogy ne 'telegram' jelenjen meg amikor a backend discord-on van.
      if (window._marveen?.channelProvider) {
        currentChannelProvider = window._marveen.channelProvider
        const sel = document.getElementById('chProviderSelect')
        if (sel) sel.value = currentChannelProvider
        if (typeof updateProviderUI === 'function') updateProviderUI()
      }
    }
    renderAgents()
    // Failure-proof like the fetches above: an older backend without the route
    // must not break the Agents page.
    loadDeletedAgents().catch(() => {})
  } catch (err) {
    console.error('Betöltés hiba:', err)
  }
}

// A törölt ügynökök doboza. Egy törlés nem semmisíti meg az ügynököt: a mappája
// a store/deleted-agents alá kerül, és innen, a felületről tehető vissza --
// terminál nélkül. (2026-08-23: egy meg nem nevezett ügynök végleg elveszett,
// mert a törlés visszafordíthatatlan volt.)
async function loadDeletedAgents() {
  const box = document.getElementById('deletedAgentsBox')
  const list = document.getElementById('deletedAgentsList')
  if (!box || !list) return
  let data = null
  try {
    const r = await fetch('/api/agents/deleted')
    if (!r.ok) { box.hidden = true; return }
    data = await r.json()
  } catch { box.hidden = true; return }

  const entries = Array.isArray(data?.entries) ? data.entries : []
  // A nulla két dolgot jelenthet: tényleg nincs törölt ügynök, vagy nem látunk
  // bele a mappába. A másodikat KI KELL mondani, különben a csend hazudik.
  if (data && data.readable === false) {
    box.hidden = false
    list.innerHTML = `<p class="error-text">${escapeHtml(t('agents.deleted.unreadable'))}${data.error ? ' — ' + escapeHtml(String(data.error)) : ''}</p>`
    return
  }
  if (!entries.length) { box.hidden = true; return }

  box.hidden = false
  list.innerHTML = entries.map((e) => {
    const when = e.deletedAtMs ? new Date(e.deletedAtMs).toLocaleString() : (e.deletedAt || '—')
    const model = e.model ? escapeHtml(e.model) : t('agents.deleted.unknown_model')
    const profile = e.profile ? escapeHtml(e.profile) : t('agents.deleted.unknown_profile')
    const blocked = e.exists
    return `<div class="list-row" style="display:flex;align-items:center;gap:12px;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border)">
      <div>
        <strong>${escapeHtml(e.name)}</strong>
        <div style="color:var(--text-muted);font-size:12px">${escapeHtml(when)} · ${model} · ${profile}</div>
        ${blocked ? `<div class="error-text" style="font-size:12px">${escapeHtml(t('agents.deleted.name_taken'))}</div>` : ''}
      </div>
      <button class="btn-secondary btn-compact" data-restore-entry="${escapeHtml(e.entry)}"${blocked ? ' disabled' : ''}>${escapeHtml(t('agents.deleted.restore_btn'))}</button>
    </div>`
  }).join('')

  list.querySelectorAll('[data-restore-entry]').forEach((btn) => {
    btn.addEventListener('click', async () => {
      const entry = btn.getAttribute('data-restore-entry')
      btn.disabled = true
      try {
        const r = await fetch(`/api/agents/deleted/${encodeURIComponent(entry)}/restore`, { method: 'POST' })
        const body = await r.json().catch(() => ({}))
        if (!r.ok) {
          // A tényleges hibaüzenetet mutatjuk, nem egy találgatott okot.
          showToast(body.error || t('agents.deleted.restore_failed'), 'error')
          btn.disabled = false
          return
        }
        showToast(t('agents.deleted.restored').replace('{name}', body.name || entry), 'success')
        await loadAgents()
      } catch (err) {
        showToast(String(err && err.message ? err.message : err), 'error')
        btn.disabled = false
      }
    })
  })
}

// Format a context-token count for display (e.g. 699884 -> "≈700k token").
function formatContextTokens(n) {
  if (typeof n !== 'number' || !isFinite(n) || n <= 0) return '-'
  if (n < 1000) return `${n} token`
  const k = n / 1000
  return `≈${k < 10 ? k.toFixed(1) : Math.round(k)}k token`
}

// Populate the auto-restart controls + context display from an agent payload.
// Works for sub-agents (agent.name) and the main session (agent.autoRestartId).
function setupAutoRestartUI(agent) {
  const ctxEl = document.getElementById('agentDetailContext')
  if (ctxEl) ctxEl.textContent = formatContextTokens(agent && agent.contextTokens)

  const ar = (agent && agent.autoRestart) || { enabled: false, mode: 'continue', dailyTime: null, intervalHours: null }
  const enabled = document.getElementById('arEnabled')
  const mode = document.getElementById('arMode')
  const schedKind = document.getElementById('arSchedKind')
  const dailyWrap = document.getElementById('arDailyWrap')
  const dailyTime = document.getElementById('arDailyTime')
  const intervalWrap = document.getElementById('arIntervalWrap')
  const intervalHours = document.getElementById('arIntervalHours')
  if (!enabled || !mode || !schedKind) return

  enabled.checked = ar.enabled === true
  mode.value = ar.mode === 'fresh' ? 'fresh' : 'continue'
  if (ar.intervalHours) {
    schedKind.value = 'interval'
    intervalHours.value = ar.intervalHours
  } else {
    schedKind.value = 'daily'
    if (ar.dailyTime) dailyTime.value = ar.dailyTime
  }
  const syncSched = () => {
    const isInterval = schedKind.value === 'interval'
    intervalWrap.hidden = !isInterval
    dailyWrap.hidden = isInterval
  }
  syncSched()
  // Attach the show/hide listener once.
  if (schedKind.dataset.wired !== '1') {
    schedKind.addEventListener('change', syncSched)
    schedKind.dataset.wired = '1'
  }
}

async function openMarveenDetail() {
  const m = window._marveen
  if (!m) return

  // Reuse the agent detail modal for Marveen
  currentAgent = { ...m, name: mainAgentId(), claudeMd: '', soulMd: '', mcpJson: '', skills: [] }
  setupAutoRestartUI(currentAgent)
  // A fo agens UGYANAZT a Beallitasok fulet kapja, tehat a kijelentkeztetes is
  // ugyanoda kerul. "Nincs megkulonboztetes agent es agent kozott" (Boss).
  renderAgentLogoutSetting(currentAgent)

  const displayName = m.name || 'Marveen'
  document.getElementById('agentDetailTitle').textContent = displayName
  const avatar = document.getElementById('agentDetailAvatar')
  avatar.className = 'detail-avatar'
  avatar.innerHTML = `<img src="/api/marveen/avatar${avatarBust()}" alt="${escapeHtml(displayName)}">`
  document.getElementById('agentDetailName').textContent = displayName
  document.getElementById('agentDetailDesc').textContent = m.description || ''
  document.getElementById('agentDetailModel').textContent = m.model || '-'
  document.getElementById('agentDetailChStatus').innerHTML = `<span class="tg-status"><span class="tg-dot connected"></span>${t('agents.channel.connected')}</span>`
  // Marveen's own name goes through the self-rename skill, not this PUT route.
  document.getElementById('agentNameEditBtn').hidden = true
  document.getElementById('agentDetailNameEdit').hidden = true
  // Populate the Skills tab for the main agent too: the endpoint returns the
  // global ~/.claude/skills under its real id (agentId), which every agent
  // inherits. Previously this was hard-set to '-' and loadSkills was never
  // called, so the main agent's Skills tab always looked empty.
  loadSkills(agentApiName())

  // Process control for Marveen - nincs start/stop, de az allapotot MERJUK
  // (lasd marveenProcessState): a "mindig fut" felirat 2026-08-24-ig akkor is
  // ott volt, amikor a folyamat epp ujraindult vagy egyaltalan nem letezett.
  const mState = marveenProcessState(m)
  document.getElementById('processDot').className = 'process-dot '
    + (mState === 'running' ? 'running' : mState === 'unseen' ? 'restarting' : 'stopped')
  document.getElementById('processLabel').textContent =
    mState === 'running' ? t('agents.status.running')
      : mState === 'unseen' ? t('agents.marveen_process_unseen')
      : mState === 'stopped' ? t('agents.status.stopped')
      : t('agents.marveen_process_unknown')
  document.getElementById('processUptime').textContent = `tmux: ${m.tmuxSession || '-'}`
  document.getElementById('agentStartBtn').hidden = true
  document.getElementById('agentStopBtn').hidden = true
  // Sync the settings tab model select with Marveen's actual model so it
  // doesn't carry over the previously opened sub-agent's selection.
  const marveenModelSelect = document.getElementById('editAgentModel')
  if (marveenModelSelect) {
    // The main agent's real model (e.g. 'claude-opus-4-8') may not match any
    // static option verbatim (the option is 'claude-opus-4-8[1m]'), so a plain
    // .value assignment finds no match and the select silently displays the
    // first option (Fable 5), misrepresenting what the agent actually runs.
    // Inject the real id as an option so the (read-only) select shows the truth
    // -- same trick as the sub-agent panel's dynamic-model-opt.
    const mv = m.activeModel || m.model || ''
    Array.from(marveenModelSelect.querySelectorAll('option.dynamic-model-opt')).forEach(o => o.remove())
    if (mv && !Array.from(marveenModelSelect.options).some(o => o.value === mv)) {
      const opt = document.createElement('option')
      opt.value = mv
      opt.className = 'dynamic-model-opt'
      opt.textContent = mv
      marveenModelSelect.appendChild(opt)
    }
    marveenModelSelect.value = mv
  }
  // Populate the model dropdown groups (auto/manual) AND surface the OpenRouter
  // curation button -- this is the main agent, the only place curation lives.
  loadAvailableModels()
  // Surface the "channels restart" button -- destructive, but mobile-safe
  // when the Telegram plugin wedges and you're away from a terminal.
  document.getElementById('marveenRestartBtn').hidden = false

  // Settings tab - load real CLAUDE.md / SOUL.md / .mcp.json (read-only).
  // Editing the main agent's identity files via the dashboard is intentionally
  // not allowed: a leaked dashboard token would otherwise let a remote user
  // rewrite the live agent's instructions. Edit via filesystem or by asking
  // Marveen on Telegram instead.
  let mFull = m
  try {
    const claudeRes = await fetch('/api/marveen')
    if (claudeRes.ok) {
      mFull = await claudeRes.json()
      document.getElementById('editClaudeMd').value = mFull.claudeMd || ''
      document.getElementById('editSoulMd').value = mFull.soulMd || ''
      document.getElementById('editMcpJson').value = mFull.mcpJson || ''
    }
  } catch {}
  applyMarveenReadonlyMode(true)

  // Telegram tab -- without this the tab stays in the default "not connected"
  // view even though the bot is running and receiving messages.
  updateChannelTab({
    name: mainAgentId(),
    hasTelegram: mFull.hasTelegram !== undefined ? mFull.hasTelegram : true,
    hasDiscord: mFull.hasDiscord,
    hasSlack: mFull.hasSlack,
    telegramBotUsername: mFull.telegramBotUsername,
    running: true,
  })

  // Delete button - hide for Marveen
  document.getElementById('deleteAgentBtn').style.display = 'none'

  document.getElementById('detailAvatarGallery').hidden = true
  switchAgentTab('overview')
  openModal(agentDetailOverlay)
}

// `readOnly` is really "this modal is showing the MAIN agent" -- it is called
// with true from openMarveenDetail and false from openAgentDetail, which makes
// it the one hook both open-paths share. Anything that must differ for the main
// agent belongs here; putting it in openAgentDetail alone silently no-ops for
// the main agent, whose panel never runs that function.
function applyMarveenReadonlyMode(readOnly) {
  // The Team tab describes a SUB-agent's place in the hierarchy: role
  // (leader | member), who it reports to, who it delegates to. None of it
  // applies to the main agent, which has no team record and cannot have one.
  // Its role is 'main', a tier ABOVE leader, and it is an implicit trusted peer
  // of every agent (see isTrustedPeer), so there is nothing to configure. Shown
  // anyway, the tab printed the literal fallback "member" and invited the
  // operator to promote the main agent to 'leader' -- a demotion, and one that
  // cannot be saved either way: the PUT targets /api/agents/<main>/team, which
  // 404s because no agents/<main>/ directory exists. Hide the whole tab, same
  // reasoning as claudePlanGroup.
  const teamTabBtn = document.querySelector('#agentTabNav .tab-btn[data-tab="team"]')
  if (teamTabBtn) teamTabBtn.hidden = readOnly
  const textareaIds = ['editClaudeMd', 'editSoulMd', 'editMcpJson']
  // saveModelBtn stays VISIBLE but disabled for Marveen, so the settings tab
  // doesn't look like the row is missing -- the other save buttons (tied to
  // readonly textareas) are hidden because the textareas are also hidden by
  // the readonly note flow.
  const hideButtonIds = ['saveClaudeMdBtn', 'saveSoulMdBtn', 'saveMcpJsonBtn', 'saveAuthModeBtn']
  const disableButtonIds = ['saveModelBtn']
  for (const id of textareaIds) {
    const el = document.getElementById(id)
    if (!el) continue
    if (readOnly) el.setAttribute('readonly', 'readonly')
    else el.removeAttribute('readonly')
  }
  const modelSelect = document.getElementById('editAgentModel')
  if (modelSelect) modelSelect.disabled = readOnly
  for (const id of hideButtonIds) {
    const btn = document.getElementById(id)
    if (btn) btn.hidden = readOnly
  }
  for (const id of disableButtonIds) {
    const btn = document.getElementById(id)
    if (btn) { btn.hidden = false; btn.disabled = readOnly }
  }
  const authModeGroup = document.getElementById('authModeGroup')
  if (authModeGroup) authModeGroup.hidden = readOnly
  const memoryIsolationGroup = document.getElementById('memoryIsolationGroup')
  if (memoryIsolationGroup) memoryIsolationGroup.hidden = readOnly
  const note = document.getElementById('marveenReadonlyNote')
  if (note) note.hidden = !readOnly
}


// Tint for the monogram shown instead of a missing avatar image. Shared, so the
// same agent gets the same colour in the chat list and in the team view.
const MONOGRAM_COLORS = ['#d97757', '#00C2A8', '#818cf8', '#22c55e', '#f59e0b', '#ec4899']
function monogramColor(name) {
  return MONOGRAM_COLORS[name.split('').reduce((a, c) => a + c.charCodeAt(0), 0) % MONOGRAM_COLORS.length]
}

// Tooltip text for the "Fut" / "Leállva" footer indicator (process state).
//
// Boss, 2026-08-29: a kartyan egyszerre allt a piros "Bejelentkezes" sav es a
// zold "Fut" + "Online" -- ami mind a harom IGAZ, csak harom KULONBOZO dolgot
// mer (folyamat / csatorna-token / Claude-auth), es egyutt olvasva ellentmondas.
// A jelzo szovege marad, de hover-en megmondjuk, mit jelent EBBEN az allapotban:
// fut, csak epp egyetlen kerest sem tud kiszolgalni.
function processTip(isRunning, needsReauth) {
  if (isRunning && needsReauth) return t('agents.running_reauth_tip')
  return isRunning
    ? t('agents.running_tip')
    : t('agents.stopped_tip')
}

// Tooltip text for the "Online" / "Offline" footer indicator (channel state).
function channelTip(isConnected, needsReauth) {
  if (isConnected && needsReauth) return t('agents.online_reauth_tip')
  return isConnected
    ? t('agents.online_tip')
    : t('agents.offline_tip')
}

// A kartyan a nev alatti leiras BEFEJEZETT mondat legyen, ne fel szo.
//
// Boss, 2026-08-23: "oda olyat tegyel ki irast aminek van vege. olyat nem jo
// latni hogy bot)... es talalja ki a user mi van utana.. nem. csak annyit irj
// amennyi kifer. es roviden tomoren. az osszes kartyan."
//
// Ezert NEM a CSS vagja el a szoveget: eloszor az ELSO MONDATOT probaljuk (az
// keszen van, es rendszerint az mondja meg, mi ez), es csak ha az sem fer ki,
// akkor vagunk -- akkor is SZOHATARON. A teljes szoveg a tooltipben marad, igy
// nem vesz el semmi.
function shortDesc(text, max = 110) {
  const full = String(text ?? '').replace(/\s+/g, ' ').trim()
  if (!full) return ''
  if (full.length <= max) return full
  const firstSentence = /^[^.!?]*[.!?](?=\s|$)/.exec(full)
  if (firstSentence && firstSentence[0].length <= max) return firstSentence[0].trim()
  const cut = full.slice(0, max)
  const lastSpace = cut.lastIndexOf(' ')
  return (lastSpace > max * 0.5 ? cut.slice(0, lastSpace) : cut).replace(/[\s.,;:(-]+$/, '') + '…'
}

// Build the copy-paste tmux attach command for an agent live session. A local
// agent session runs on the orchestrator host (a direct `tmux attach`); a remote
// agent session runs on its configured remoteHost, reached over ssh. Only
// meaningful for running agents.
function tmuxAttachCommand(agent) {
  const session = agent.session || ('agent-' + agent.name)
  const direct = 'tmux attach -t ' + session
  const remoteHost = agent.remoteHost || null
  return remoteHost ? 'ssh ' + remoteHost + " -t '" + direct + "'" : direct
}

// A "tmux attach parancs vagolapra" gomb. 2026-08-23-ig minden futo ugynok
// KARTYAJAN ott ult, de a hetkoznapi hasznalathoz semmi koze -- a Terminal-ablak
// ugyanazt a panelt megmutatja bongeszoben. Boss: "szedd le. nem kell az oda.
// (...) de beteheted. had legyen ott." -- azota a Terminal-ablak fejleceben van.
function attachTmuxCopyButtons(host, agent) {
  const cmd = tmuxAttachCommand(agent)
  const row = document.createElement('div')
  row.className = 'agent-tmux-cmds'
  const btn = document.createElement('button')
  btn.type = 'button'
  btn.className = 'tmux-copy-btn'
  btn.setAttribute('aria-label', t('agents.tmux_copy_aria'))
  btn.title = cmd
  btn.innerHTML = '<span class="tmux-copy-ico">⧉</span>tmux'
  btn.addEventListener('click', (e) => {
    e.stopPropagation()
    navigator.clipboard.writeText(cmd).then(() => {
      const orig = btn.innerHTML
      btn.classList.add('copied')
      btn.innerHTML = '<span class="tmux-copy-ico">✓</span>' + t('agents.tmux_copied')
      setTimeout(() => { btn.innerHTML = orig; btn.classList.remove('copied') }, 1400)
    }).catch(() => showToast(t('agents.tmux_copy_failed')))
  })
  row.appendChild(btn)
  host.appendChild(row)
}

// A model id like "google/gemma-4-31b-it:free" is a free-tier OpenRouter
// model; anything else (including 'inherit'/'opus'/undefined for Claude-auth
// agents) counts as paid/unrestricted.
function isFreeModel(model) {
  return typeof model === 'string' && model.toLowerCase().endsWith(':free')
}

// Green "$X.XX/M" badge for a paid agent's card (Agents grid only -- Boss
// 2026-08-08: wants to see at a glance which paid agent "eats" how much).
// Only rendered when the backend actually knows the price (costPerMInput is
// a known Claude-tier lookup, never a guess) -- omitted entirely rather than
// showing a wrong number for an OpenRouter/unknown paid model.
function costBadgeHtml(costPerMInput) {
  if (typeof costPerMInput !== 'number') return ''
  const label = '$' + costPerMInput.toFixed(2) + '/M'
  return `<span class="agent-cost-badge" title="${escapeAttr(t('agents.cost_badge_tip'))}">${escapeHtml(label)}</span>`
}

// Plan id -> human label, from the /api/claude-plans registry. Cached because
// the badge renders once per agent card. Populated opportunistically; until it
// arrives the badge falls back to the raw plan id, which is still this
// install's own identifier rather than a guess.
let _planLabelCache = null
function primePlanLabels() {
  if (_planLabelCache) return
  _planLabelCache = {}
  fetch('/api/claude-plans')
    .then(res => (res.ok ? res.json() : []))
    .catch(() => [])
    .then((plans) => { for (const p of plans) _planLabelCache[p.id] = p.label })
}

// Neutral-grey account badge: which Claude/OpenRouter login the agent runs
// under, so the card shows the ACCOUNT, not just the model. Sits to the LEFT of
// the $/M cost badge in the same top-right corner (both wrapped in
// .agent-card-badges).
//
// The plan names come from this install's own registry. They used to be an
// if-chain of three literals from the author's machine, which on anyone else's
// install labelled every agent with accounts they do not have.
// A model name baked into a registry label ("Usalackor (Opus 4.8)") is wrong on
// this badge twice over: the card already shows the LIVE model right below it,
// and the baked one goes stale the moment the account is re-pointed -- Boss saw
// "Lackor3 (Haiku)" on a card whose live badge said CLAUDE-OPUS-5, minutes after
// he switched it (2026-08-11). Only a MODEL-looking parenthetical is dropped:
// stripping every "(...)" would erase deliberate distinctions like
// "Account (personal)" vs "Account (work)".
const MODEL_SUFFIX_RE = /\s*\((?:claude[\s-]*)?(?:opus|sonnet|haiku|fable|gpt|gemini|llama|mistral|grok|deepseek|qwen|nemotron)[^)]*\)\s*$/i
function stripModelSuffix(label) {
  return String(label || '').replace(MODEL_SUFFIX_RE, '').trim() || label
}

// The main agent's ACCOUNT name, derived from its agent id -- never the persona.
// The badge said "Marvin" on a card already titled "Marvin" (Boss, 2026-08-11:
// "minek ketszer kiirni a marvint?"), which also hid the one thing the badge is
// for: WHICH LOGIN this agent runs on. The id is the install's own
// (MAIN_AGENT_ID, e.g. "lackor2-bot"); the "-bot" suffix is plumbing, so it is
// dropped and the first letter raised -> "Lackor2". Nothing here is hardcoded to
// one install's names.
function mainAccountLabel() {
  const id = (window._marveen && window._marveen.agentId) || ''
  const base = String(id).replace(/[-_]?bot$/i, '').trim()
  if (!base) return mainAgentDisplayName()
  return base.charAt(0).toUpperCase() + base.slice(1)
}

// A Claude-bejelentkezesek allapota, hogy az ugynok kartyaja tudja: van-e mit
// kijelentkeztetni rajta, es KI az.
//
// Boss, 2026-08-29: "ted ra a kartyara is!" -- a kijelentkeztetes gombja ne
// csak a Fiokok oldalon legyen. A kartya NEM szamolja ujra, melyik ugynok fut
// Claude-bejelentkezessel: azt a szerver mondja meg (agent.claudeAccount), ez
// itt csak az ALLAPOTOT (be van-e jelentkezve, milyen e-maillel) fuzi hozza.
// Az osszefuzes kulcsa a configDir, nem a terv-azonosito: egy nyers
// claudeConfigDir-rel futo ugynoknek nincs sora a listaban, es ilyenkor a
// helyes valasz a "nem tudom", nem az, hogy odaertjuk az alapertelmezettet.
let _claudeAccountRows = null
let _claudeAccountsPending = false
function primeClaudeAccounts(onLoaded) {
  if (_claudeAccountRows || _claudeAccountsPending) return
  _claudeAccountsPending = true
  fetch('/api/accounts/claude')
    .then(res => (res.ok ? res.json() : null))
    .catch(() => null)
    .then((data) => {
      _claudeAccountsPending = false
      _claudeAccountRows = (data && Array.isArray(data.accounts)) ? data.accounts : []
      _claudeIdentityCollisions = (data && Array.isArray(data.identityCollisions)) ? data.identityCollisions : []
      if (typeof onLoaded === 'function') onLoaded()
    })
}

// KI VAN EBBEN A SLOTBAN -- a felulet oldala.
//
// Boss, 2026-08-29: "ne legyen ugyanabba a fiokba bejelentkezve. hat hiszen a
// lackor3 az egy kulon email klon fiokkal... mit keres az az usalackorban?"
// Ket kulon nevu elofizetes csendben ugyanarra a Claude-fiokra mutatott: ketten
// ettek ugyanannak az egy fioknak a kereteit, a masik meg allt hasznalatlanul.
// A szerver ket dolgot ad: slotonkenti iteletet (`identityVerdict`) es a
// cimenkenti utkozeseket.
let _claudeIdentityCollisions = []

// A sor, amit a fiok mellett latni KELL, vagy ures sztring. Az ures itt azt
// jelenti, hogy nincs baj -- a "nem latok oda" kulon itelet ('blind'), es azt
// is kiirjuk, nehogy egy nema sor "rendben"-nek latsszon.
function accountIdentityWarningHtml(row) {
  if (!row) return ''
  const v = row.identityVerdict || null
  const cim = (row.identity && row.identity.email) || ''
  const utkozes = (_claudeIdentityCollisions || []).find(c => Array.isArray(c.ids)
    && c.ids.some(id => (id || '') === (row.id || '')))
  if (utkozes) {
    const tarsak = (utkozes.labels || []).filter(l => l && l !== (row.label || row.id || ''))
    const szoveg = t('accounts.identity.collision', {
      email: utkozes.email,
      others: tarsak.length ? tarsak.join(', ') : t('accounts.identity.host_account'),
    })
    return `<div class="agent-account-identity-warn">⚠️ ${escapeHtml(szoveg)}</div>`
  }
  if (v && v.kind === 'drift') {
    const szoveg = t('accounts.identity.drift', { expected: v.expected, actual: v.actual })
    return `<div class="agent-account-identity-warn">⚠️ ${escapeHtml(szoveg)}
      <button type="button" class="btn-secondary btn-compact agent-account-pin-btn"
        data-plan="${escapeAttr(row.id || '')}" data-email="${escapeAttr(cim)}">${escapeHtml(t('accounts.identity.accept_new'))}</button>
    </div>`
  }
  if (v && v.kind === 'blind') {
    return `<div class="agent-account-identity-warn">⚠️ ${escapeHtml(t('accounts.identity.blind'))}</div>`
  }
  return ''
}

// A megtalalt fiok sora, vagy null. A null itt "nem lattam oda" (meg nem jott
// meg a lista, vagy nincs ilyen sor) -- ilyenkor a kartya inkabb NEM mutat
// gombot, mint hogy rosszra mutasson.
// A GYORSITOTAR EMLEK, NEM FORRAS.
//
// Boss, 2026-08-29 este: bejelentkezett a kartyarol, majd megnyitotta ugyanannak
// az ugynoknek a Beallitasok fulet, es ott tovabbra is "Bejelentkezes (Usalackor)"
// allt -- "ott mar a kijelentkezest kellene latnom". A `_claudeAccountRows`
// lapbetolteskor egyszer tolt fel, es csak KIjelentkezes utan urult; a
// BEjelentkezes utan nem. Igy a gomb arrol az allapotrol beszelt, ami a lekerdezes
// pillanataban volt igaz.
//
// Ket kulon dolgot javit ez: (a) minden bejelentkezes vegen urul a tar (lasd a
// _claudeAuthTick "kesz" agat), (b) a doboz kirajzolasakor MINDIG fut egy friss
// lekerdezes is, es csak akkor rajzolunk ujra, ha az allapot tenyleg valtozott --
// igy nincs villogas, es nem kell kitalalni, mikor avult el a tar.
function claudeAccountsFingerprint(rows) {
  return (rows || []).map(r => [
    r.id || '', r.configDir || '',
    (r.identity && r.identity.loggedIn) ? '1' : '0',
    (r.identity && r.identity.email) || '',
    (r.identityVerdict && r.identityVerdict.kind) || '',
  ].join('|')).join(';')
}

// Sikertelen lekerdezesnel a REGI adat marad, es nem hivjuk a visszahivast: a
// "nem lattam oda" nem azonos azzal, hogy "nincs fiok".
function refreshClaudeAccounts(onChanged) {
  fetch('/api/accounts/claude')
    .then(res => (res.ok ? res.json() : null))
    .catch(() => null)
    .then((data) => {
      if (!data || !Array.isArray(data.accounts)) return
      const before = claudeAccountsFingerprint(_claudeAccountRows)
      const after = claudeAccountsFingerprint(data.accounts)
      _claudeAccountRows = data.accounts
      _claudeIdentityCollisions = Array.isArray(data.identityCollisions) ? data.identityCollisions : []
      _claudeAccountsPending = false
      if (before !== after && typeof onChanged === 'function') onChanged()
    })
}

// EGY hely, ahol a fiok-allapot valtozasa utan ujrarajzolunk: a kartyalista ES
// a nyitott modal doboza. A kijelentkeztetes es a bejelentkezes vege ugyanezt
// hivja -- ket masolat elobb-utobb elcsuszna egymastol (ezt szamolja meg az
// agent-card-logout-ui teszt is).
function reloadAccountsAndRedraw() {
  _claudeAccountRows = null
  _claudeAccountsPending = false
  primeClaudeAccounts(() => {
    renderAgents()
    // A doboz a nyitott modalban ul: ha csak a kartyakat rajzolnank ujra, a
    // gomb ott maradna egy mar elavult allapotra mutatva.
    if (currentAgent) renderAgentLogoutSetting(currentAgent)
  })
}

function claudeAccountRowFor(claudeAccount) {
  if (!claudeAccount || !_claudeAccountRows) return null
  const want = claudeAccount.configDir === undefined ? null : claudeAccount.configDir
  return _claudeAccountRows.find(r => (r.configDir ?? null) === want) || null
}

// A kartyara kerulo kijelentkeztetes/bejelentkezes-gomb. Csak akkor van, ha
// az ugynok tenylegesen Claude-bejelentkezessel dolgozik -- ha nincs ilyen
// sora (peldaul API-kulccsal fut), a doboz nem jelenik meg.
//
// Boss, 2026-08-29: kijelentkeztetett egy ugynokot INNEN, es utana nem
// tudta visszahozni -- a doboz teljesen eltunt, mert ez a fuggveny csak a
// "bejelentkezve van" agra adott vissza gombot. A "Vissza a Bejelentkezes
// gombbal... johet" szoveg (agents.settings.logout_desc) mar akkor is ezt
// igerte, csak nem volt hozza gomb. A visszautat a mar letezo
// _claudeAuthStartFlow adja (ugyanaz, amit a Fiokok oldal relogin gombja
// hasznal), csak innen, a kartya sajat Beallitasok fulerol indul.
function agentLogoutButtonHtml(agent) {
  const row = claudeAccountRowFor(agent && agent.claudeAccount)
  if (!row || !row.identity) return ''
  // A figyelmeztetes a gomb FOLE kerul: eloszor azt kell latni, KI van a
  // fiokban, es csak utana a gombot, ami vele csinal valamit.
  const warn = accountIdentityWarningHtml(row)
  if (row.identity.loggedIn) {
    const who = row.identity.email || (row.isDefault ? mainAccountLabel() : (row.label || row.id || ''))
    const label = t('agents.btn.account_logout', { account: row.isDefault ? mainAccountLabel() : stripModelSuffix(row.label || row.id || '') })
    return `${warn}<button class="btn-secondary btn-compact agent-account-logout-btn" data-plan="${escapeAttr(row.isDefault ? '' : (row.id || ''))}" data-who="${escapeAttr(who)}" title="${escapeAttr(t('agents.btn.account_logout_tip'))}">${escapeHtml(label)}</button>`
  }
  const name = row.isDefault ? mainAccountLabel() : (row.label || row.id || '')
  const label = t('agents.btn.account_relogin', { account: stripModelSuffix(name) })
  return `${warn}<button type="button" class="btn-primary btn-compact agent-account-relogin-btn" data-plan="${escapeAttr(row.isDefault ? '' : (row.id || ''))}" data-default="${row.isDefault ? '1' : '0'}" data-who="${escapeAttr(name)}" title="${escapeAttr(t('agents.btn.account_relogin_tip'))}">${escapeHtml(label)}</button>`
}

/**
 * A gomb bekotese -- EGY helyen. Boss, 2026-08-29: "ne kivulre tedd. hanem
 * belulre a beallitasok ala." A gomb ezert mar nem a kartya elejen ul, hanem
 * az ugynok sajat Beallitasok fulen, a Claude-elofizetes alatt -- es mivel a
 * fo agens UGYANEZT a modalt hasznalja, egyetlen helyen keletkezik, nem ket,
 * egymastol elcsuszo masolatban ("nincs megkulonboztetes agent es agent
 * kozott").
 */
function wireAccountLogoutButton(cardEl) {
  // "Mostantol EZ a cim tartozzon ehhez az elofizeteshez." Csak kifejezett
  // dontesre, megerositessel: a bejelentkezes magatol SOSE irja felul.
  cardEl.querySelector('.agent-account-pin-btn')?.addEventListener('click', (e) => {
    e.stopPropagation()
    const b = e.currentTarget
    const email = b.dataset.email || ''
    if (!confirm(t('accounts.identity.accept_confirm', { email }))) return
    fetch('/api/accounts/claude/pin-email', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ planId: b.dataset.plan || '', email }),
    })
      .then(res => res.json())
      .catch(() => null)
      .then((data) => {
        if (!data || !data.ok) { showToast((data && data.error) || t('common.error_save'), 8000, true); return }
        showToast(t('accounts.identity.accept_done', { email }), 6000)
        reloadAccountsAndRedraw()
      })
  })
  cardEl.querySelector('.agent-account-logout-btn')?.addEventListener('click', (e) => {
    e.stopPropagation()
    const b = e.currentTarget
    _claudeAuthLogout(b.dataset.plan || '', b.dataset.who || '').then(() => {
      reloadAccountsAndRedraw()
    })
  })
  // A visszaut a #claudeAuthFlow dobozt nyitja meg es indit pollingot -- az
  // viszont a Fiokok lap sajat DOM-agan lakik (#accountsPage), ami `hidden`,
  // amig a kartya-modal masik lapon van nyitva. Ha csak a dobozt nyitnank
  // meg (mint a Fiokok oldal sajat relogin gombja teszi), a felhasznalo
  // semmit nem latna -- pontosan az a nema "lattam-e oda" hiba, ami miatt
  // Boss nem talalta a Bejelentkezes gombot. Ezert elobb at kell valtani a
  // Fiokok lapra ES be kell csukni a kartya-modalt, csak utana nyithat a doboz.
  cardEl.querySelector('.agent-account-relogin-btn')?.addEventListener('click', (e) => {
    e.stopPropagation()
    const b = e.currentTarget
    const payload = b.dataset.default === '1' ? { target: 'default' } : { planId: b.dataset.plan }
    // Se lapvaltas, se modal-bezaras: a doboz IDE jon, a gomb ala.
    const host = document.getElementById('agentLogoutGroup') || b.parentNode
    _claudeAuthStartFlow(payload, host)
  })
}

/**
 * A Beallitasok ful kijelentkeztetes-doboza. Ugyanaz a szabaly, mint a
 * kartyan volt: csak akkor latszik, ha az ugynok tenylegesen
 * Claude-bejelentkezessel dolgozik ES az a fiok be is van jelentkezve.
 * A fioklista aszinkron jon, ezert ha meg nincs meg, megkerjuk, es a
 * megerkezesekor ujrarajzoljuk -- a hianyzo lista "nem lattam oda", nem
 * "nincs fiok", tehat addig nem allitunk semmit.
 */
function renderAgentLogoutSetting(agent) {
  const group = document.getElementById('agentLogoutGroup')
  const slot = document.getElementById('agentLogoutSlot')
  if (!group || !slot) return
  if (!_claudeAccountRows) {
    group.hidden = true
    slot.innerHTML = ''
    primeClaudeAccounts(() => {
      // Csak akkor rajzolunk ujra, ha kozben nem valtottal masik ugynokre.
      if (currentAgent && agent && currentAgent.name === agent.name) renderAgentLogoutSetting(agent)
    })
    return
  }
  const html = agentLogoutButtonHtml(agent)
  slot.innerHTML = html
  group.hidden = !html
  if (html) wireAccountLogoutButton(group)
  // Kirajzoltuk abbol, amink van (nincs varakozas), es KOZBEN megkerdezzuk a
  // szervert. Ha kozben mas lett az allapot -- masik fulon, a varazsloban vagy
  // eppen az iment, a kartya gombjarol --, ez rajzolja at.
  refreshClaudeAccounts(() => {
    if (currentAgent && agent && currentAgent.name === agent.name) renderAgentLogoutSetting(agent)
  })
}

function accountBadgeHtml(claudePlan, isMain) {
  primePlanLabels()
  let label
  if (isMain) label = mainAccountLabel()
  else if (claudePlan) label = stripModelSuffix((_planLabelCache && _planLabelCache[claudePlan]) || claudePlan)
  else label = 'OpenRouter'
  return `<span class="agent-account-badge" title="${escapeAttr(t('agents.account_badge_tip'))}">${escapeHtml(label)}</span>`
}

// Kanban 502005f0: 0-10 "can this free agent actually be reached" gauge --
// NOT a quality/trust score, purely dispatch-success (see agent-reliability.ts
// on the backend). null/no-sample agents render nothing rather than a
// misleading "0" for an agent that simply has no history yet.
function reliabilityBadgeHtml(reliability) {
  if (!reliability || reliability.score === null) return ''
  const pct = Math.round((reliability.score / 10) * 100)
  const cls = reliability.score <= 2 ? 'reliability-low' : reliability.score <= 6 ? 'reliability-mid' : 'reliability-high'
  const tip = t('agents.reliability_tip', { score: reliability.score, n: reliability.sampleSize })
  return `
    <span class="agent-reliability-badge ${cls}" title="${escapeAttr(tip)}">
      <span class="agent-reliability-track"><span class="agent-reliability-fill" style="width:${pct}%"></span></span>
      <span class="agent-reliability-num">${reliability.score}</span>
    </span>
  `
}

// === Per-agent context controls (Agents cards) ===
// Manual "compact" (/compact -- summarize, keep info) and "clear" (/clear -- wipe
// the conversation) buttons, plus the automatic-clear gate toggle + threshold.
// Backed by /api/agents/:name/context-action and /api/context-restart-gate. The
// gate config comes from gateCfgByAgent (loaded in loadAgents); a missing entry
// renders as "off" at the documented 400k default.
// The two context buttons live in the card's EXISTING action row, next to
// Conversation and Terminal, rather than in a second row of their own: Boss,
// 2026-08-12, looking at the live card -- "ezt csinal ugy, hogy ferjen ki egy
// sorban, ne kettoben". Only the auto-clear switch stays on its own line, since
// it is a setting rather than an action.
function contextButtonsHtml(name) {
  return `
        <button class="btn-secondary btn-compact ctx-compact-btn" title="${escapeAttr(t('agents.ctx.compact_tip'))}">${escapeHtml(t('agents.ctx.compact'))}</button>
        <button class="btn-secondary btn-compact ctx-clear-btn" title="${escapeAttr(t('agents.ctx.clear_tip'))}">${escapeHtml(t('agents.ctx.clear'))}</button>`
}

// Human-readable reset instant for a quota wall, in the viewer's own locale.
// Returns the "should already have reopened" wording when the moment has passed
// but the transcript still ends on a rejection: saying "reopens 14:00" at 15:00
// would read as a working clock reporting the past.
function quotaResetText(resetsAt) {
  if (typeof resetsAt !== 'number' || !isFinite(resetsAt) || resetsAt <= 0) return null;
  if (resetsAt <= Date.now()) return t('agents.ctx.quota_reset_now');
  try {
    return new Date(resetsAt).toLocaleString(undefined, {
      weekday: 'short', hour: '2-digit', minute: '2-digit',
    });
  } catch { return new Date(resetsAt).toISOString(); }
}

function contextControlsHtml(name, contextTokens = null, running = true, contextState = null, contextQuota = null) {
  const cfg = gateCfgByAgent.get(name) || { enabled: false, thresholdTokens: 400000 }
  const kThreshold = Math.max(1, Math.round((cfg.thresholdTokens || 400000) / 1000))
  // Show the live context size next to the threshold so the owner can pick a
  // sensible cut-off (Boss, 2026-08-12). For a RUNNING agent we always print a
  // line: a real value when known, or an explicit "0 (fresh session)" when the
  // context is empty -- e.g. right after a Clear, whose new transcript carries
  // no usage yet. Boss, 2026-08-12: a blank line looked like the number was
  // missing, so a completed Clear was indistinguishable from "unknown". Only a
  // stopped agent (no live session at all) hides the line entirely.
  //
  // "0 (fresh session)" is only true when the session really has not run a turn.
  // An agent whose every turn died on a usage limit has no numbers either, and
  // printing 0 for its 113 KB session read as "empty" when it was simply not
  // measurable (Boss, 2026-08-12). The backend now says which case it is.
  //
  // "not measurable" and "rejected at the door" both produce no number, and for
  // months the card printed the same sentence for both. They mean opposite
  // things to the owner: one is a reader we should fix, the other is an agent
  // that cannot do ANY work until a stated moment. Boss, 2026-08-24: the
  // Segedmunkas card was green and "running" from 07:49 while every turn it
  // took died on the weekly wall. The backend now reads the rejection (and the
  // reset instant) straight out of the transcript, so the card can say it.
  const hasValue = typeof contextTokens === 'number' && contextTokens > 0
  const resetText = contextQuota ? quotaResetText(contextQuota.resetsAt) : null
  let currentHtml = ''
  if (hasValue) {
    currentHtml = `<div class="ctx-current">${escapeHtml(t('agents.ctx.current'))} ${escapeHtml(formatContextTokens(contextTokens))}</div>`
    // A measured session can be walled right now too -- the size is real, the
    // agent still cannot use it. Both facts, not whichever one we picked.
    if (contextQuota && resetText) {
      currentHtml += `<div class="ctx-quota-warn">${escapeHtml(t('agents.ctx.quota_blocked_measured', { when: resetText }))}</div>`
    }
  } else if (running && contextState === 'quota-blocked') {
    currentHtml = `<div class="ctx-current ctx-quota-blocked">${escapeHtml(resetText
      ? t('agents.ctx.current_quota_blocked', { when: resetText })
      : t('agents.ctx.current_quota_blocked_unknown'))}</div>`
  } else if (running && (contextState === 'no-usage' || contextState === 'unknown')) {
    currentHtml = `<div class="ctx-current">${escapeHtml(t('agents.ctx.current_unmeasured'))}</div>`
  } else if (running) currentHtml = `<div class="ctx-current">${escapeHtml(t('agents.ctx.current_empty'))}</div>`
  // A stopped agent used to show NOTHING here, and a missing line reads as a
  // missing feature: Boss, 2026-08-12, seeing it on one card but not another --
  // "es akor ez miert nem mukodik a szakertonel?? nem globalisan oldottad meg?"
  // It works everywhere; a stopped session simply has no context. Say so.
  else currentHtml = `<div class="ctx-current">${escapeHtml(t('agents.ctx.current_stopped'))}</div>`
  // The threshold's own limits come from the backend. Below the floor the gate
  // fires so often the agent never gets a turn's work done; above the ceiling
  // the CLI's autocompact reaches the context first and the gate never runs at
  // all. Both ends are settings that LOOK saved and silently do nothing, which
  // is the failure this whole exercise started from.
  const kMin = Math.max(1, Math.round((ctxLimits.minGateTokens || 30000) / 1000))
  const kMax = ctxLimits.maxGateTokens > 0 ? Math.floor(ctxLimits.maxGateTokens / 1000) : 1000
  const outOfRange = cfg.enabled && (kThreshold > kMax || kThreshold < kMin)
  const rangeNote = outOfRange
    ? `<div class="ctx-gate-warn">${escapeHtml(t('agents.ctx.gate_range_warn', { min: kMin, max: kMax }))}</div>`
    : ''
  return `
    <div class="agent-context-controls">
      <label class="ctx-gate-row" title="${escapeAttr(t('agents.ctx.auto_tip'))}">
        <input type="checkbox" class="ctx-gate-toggle"${cfg.enabled ? ' checked' : ''}>
        <span class="ctx-gate-text">${escapeHtml(t('agents.ctx.auto'))}</span>
        <input type="number" class="ctx-gate-threshold" min="${kMin}" max="${kMax}" step="10" value="${kThreshold}"${cfg.enabled ? '' : ' disabled'}>
        <span class="ctx-gate-unit">${escapeHtml(t('agents.ctx.unit'))}</span>
      </label>
      ${rangeNote}
      ${brokerRowHtml(name)}
      ${roleRowHtml(name)}
      ${cliRowHtml(name)}
      ${currentHtml}
      ${contextHelpHtml()}
    </div>`
}

// === 3rd mechanism: the CLI's own autocompact ===
// Read-only on purpose. It is one --autocompact value for the whole fleet (.env,
// AUTOCOMPACT_TOKENS), so a per-card control would imply an independence that
// does not exist. It is shown because leaving it invisible is what let the other
// three be configured around a number nobody could see.
//
// Both numbers are printed: what is configured, and where it ACTUALLY fires.
// Measured on this install at ~69% of the setting (46 compactions, mean 69207
// tokens at a 100k setting), and that gap is the whole reason the gates never
// ran -- thresholds of 50k-200k sat above a CLI that was compacting at 69k.
//
// The value is passed to the CLI at LAUNCH, so a running agent keeps the one it
// started with -- for days. Raising the setting and watching usalackor go on
// compacting every 2-3 minutes (its process still on the old 100k) is what
// added the second line: when the live process disagrees with the setting, the
// card says so, instead of showing a number the agent is not using.
function cliRowHtml(name) {
  if (!ctxLimits.autocompactTokens) return ''
  const running = gateCfgByAgent.get(name)?.autocompactRunning
  const drifted = Number.isFinite(running) && running !== ctxLimits.autocompactTokens
  return `
      <div class="ctx-cli-row" title="${escapeAttr(t('agents.ctx.cli_tip'))}">
        ${escapeHtml(t('agents.ctx.cli', {
          set: formatContextTokens(ctxLimits.autocompactTokens),
          fires: formatContextTokens(ctxLimits.autocompactFiresAt),
        }))}
        ${drifted ? `<div class="ctx-gate-warn">${escapeHtml(t('agents.ctx.cli_drift', {
          running: formatContextTokens(running),
          fires: formatContextTokens(gateCfgByAgent.get(name)?.autocompactRunningFiresAt ?? 0),
        }))}</div>` : ''}
      </div>`
}

// === Roles: who is what in the pipeline ===
// Boss, 2026-08-14: "a kartyan van jelolonegyzet amin ki lehet jelolni hogy ki
// legyen kicsoda. az hogy a kartya alatt milyen model van az ne szamitson."
//
// So eligibility is never inferred from the model. Each role is held by at most
// one agent -- the backend stores one name per role, so ticking a box here takes
// it away from whoever had it, and the re-render is what makes that visible.
// Unassigned is the normal state: the generator then decides per task.
function roleRowHtml(name) {
  const roles = brokerState.config?.roles || {}
  const boxes = ['planner', 'implementer', 'checker'].map((id) => `
        <label class="ctx-role" title="${escapeAttr(t(`agents.ctx.role_${id}_tip`))}">
          <input type="checkbox" class="ctx-role-toggle" data-role="${id}"${roles[id] === name ? ' checked' : ''}>
          <span>${escapeHtml(t(`agents.ctx.role_${id}`))}</span>
        </label>`).join('')
  return `
      <div class="ctx-role-row" title="${escapeAttr(t('agents.ctx.roles_tip'))}">${boxes}
      </div>`
}

// === The full explanation, folded away ===
// Boss asked for every explanation to be written out -- what each does, when it
// starts, what happens if you use it, which ones must not be combined. That is
// more text than a card can carry open, and tooltips only reach one control at a
// time, so it goes in a <details> that starts closed: present for whoever wants
// it, costing no space for everyone else.
function contextHelpHtml() {
  const rows = ['manual', 'gate', 'cli', 'broker']
    .map((id) => `<p><b>${escapeHtml(t(`agents.ctx.help_${id}_title`))}</b><br>${escapeHtml(t(`agents.ctx.help_${id}`))}</p>`)
    .join('')
  // The checkpoint is NOT a fifth mechanism to choose between -- it runs before
  // whichever one fires -- so it sits after the ordering rule, not in the list.
  const checkpoint = `<p><b>${escapeHtml(t('agents.ctx.help_checkpoint_title'))}</b><br>${escapeHtml(t('agents.ctx.help_checkpoint'))}</p>`
  return `
      <details class="ctx-help">
        <summary>${escapeHtml(t('agents.ctx.help_summary'))}</summary>
        ${rows}
        <p class="ctx-help-rule">${escapeHtml(t('agents.ctx.help_order'))}</p>
        ${checkpoint}
      </details>`
}

// === Context generator (broker) checkbox ===
// Boss, 2026-08-13: "a kartyakra tenni kell egy kapcsolot hogy ha bejelolom
// mint itt az automata tomorites nel, akkor az lesz a kontextusgenerator. ha
// egy masikat jelolok be akkor ennel eltunik a jeloles es a masiknal lesz
// bejelolve. egyszerre csak egynel legyen." The exclusivity is enforced by the
// BACKEND (one field in store/context-broker.json), not by clearing the other
// boxes here -- this only re-renders after the save so the display follows.
//
// The role is optional, so it is an EXTRA, never an error: with nobody
// designated every agent simply prepares its own context, exactly as before
// this feature existed. Nothing here goes red.
function brokerRowHtml(name) {
  const isDesignated = brokerState.designated === name
  const isStandIn = brokerState.effective === name && brokerState.designated !== name
  let noteHtml = ''
  // Only the two cards involved say anything: the designated one explains why
  // it is not doing the job right now, the stand-in explains why it is.
  if (isDesignated && brokerState.effective !== name) {
    const who = brokerState.effective ? chatDisplayName(brokerState.effective) : ''
    let key = 'agents.ctx.broker_paused_none'
    if (brokerState.reason === 'fallback-stopped') key = 'agents.ctx.broker_paused_stopped'
    else if (brokerState.reason === 'fallback-quota') key = 'agents.ctx.broker_paused_quota'
    noteHtml = `<div class="ctx-broker-note">${escapeHtml(t(key, { agent: who }))}</div>`
  } else if (isStandIn) {
    const who = brokerState.designated ? chatDisplayName(brokerState.designated) : ''
    noteHtml = `<div class="ctx-broker-note">${escapeHtml(t('agents.ctx.broker_standin', { agent: who }))}</div>`
  }
  // The two policy settings appear ONLY on the designated card. They describe
  // how that agent hands work out, so on any other card they would be asking
  // about a role the agent does not have -- and cleanStart in particular reads
  // as "wipe me", which is the opposite of what it does.
  let optsHtml = ''
  if (isDesignated) {
    const cfg = brokerState.config || {}
    const secs = Number.isFinite(cfg.handBackAfterSeconds) ? cfg.handBackAfterSeconds : 0
    optsHtml = `
      <div class="ctx-broker-opts">
        <label class="ctx-broker-opt" title="${escapeAttr(t('agents.ctx.clean_start_tip'))}">
          <input type="checkbox" class="ctx-clean-start"${cfg.cleanStart ? ' checked' : ''}>
          <span>${escapeHtml(t('agents.ctx.clean_start'))}</span>
        </label>
        <label class="ctx-broker-opt" title="${escapeAttr(t('agents.ctx.handback_tip'))}">
          <span>${escapeHtml(t('agents.ctx.handback'))}</span>
          <input type="number" class="ctx-handback" min="0" max="3600" step="10" placeholder="30" value="${secs}">
          <span>${escapeHtml(t('agents.ctx.handback_unit'))}</span>
        </label>
        <p class="ctx-broker-hint">${escapeHtml(t('agents.ctx.handback_hint'))}</p>
      </div>`
  }
  return `
      <label class="ctx-gate-row ctx-broker-row" title="${escapeAttr(t('agents.ctx.broker_tip'))}">
        <input type="checkbox" class="ctx-broker-toggle"${isDesignated ? ' checked' : ''}>
        <span class="ctx-gate-text">${escapeHtml(t('agents.ctx.broker'))}</span>
      </label>
      ${noteHtml}
      ${optsHtml}`
}

function wireContextControls(card, name) {
  const root = card.querySelector('.agent-context-controls')
  if (!root) return
  // The card itself opens the detail modal on click; keep control clicks local.
  root.addEventListener('click', (e) => e.stopPropagation())
  // The buttons now sit in the card's action row, not inside root, so they are
  // looked up on the CARD -- and each stops propagation on its own, the same
  // way the Conversation and Terminal buttons beside them do.
  card.querySelector('.ctx-compact-btn')?.addEventListener('click', (e) => { e.stopPropagation(); doContextAction(name, 'compact') })
  card.querySelector('.ctx-clear-btn')?.addEventListener('click', (e) => { e.stopPropagation(); doContextAction(name, 'clear') })
  const toggle = root.querySelector('.ctx-gate-toggle')
  const threshold = root.querySelector('.ctx-gate-threshold')
  toggle?.addEventListener('change', () => {
    if (threshold) threshold.disabled = !toggle.checked
    saveGateConfig(name, toggle.checked, threshold)
  })
  threshold?.addEventListener('change', () => saveGateConfig(name, !!toggle?.checked, threshold))
  const broker = root.querySelector('.ctx-broker-toggle')
  broker?.addEventListener('change', () => saveBrokerConfig(name, broker.checked))
  // A role tick is an independent edit: it must not disturb the designation, so
  // it posts only {role, agent} and the backend leaves `designated` alone.
  root.querySelectorAll('.ctx-role-toggle').forEach((box) => {
    box.addEventListener('change', () => saveBrokerRole(name, box.dataset.role, box.checked))
  })
  const cleanStart = root.querySelector('.ctx-clean-start')
  cleanStart?.addEventListener('change', () => {
    // Confirm before switching ON, never before switching off. This one wipes
    // conversations -- of OTHER agents, which is why the card it sits on cannot
    // show the consequence by itself.
    if (cleanStart.checked && !confirm(t('agents.ctx.clean_start_confirm'))) {
      cleanStart.checked = false
      return
    }
    saveBrokerOptions(name, { cleanStart: cleanStart.checked })
  })
  const handback = root.querySelector('.ctx-handback')
  handback?.addEventListener('change', () => {
    const v = parseInt(handback.value, 10)
    saveBrokerOptions(name, { handBackAfterSeconds: Number.isFinite(v) && v > 0 ? v : 0 })
  })
}

// Give this agent a role, or take it away. `enabled:false` clears the role
// entirely rather than handing it to nobody-in-particular, so unticking the last
// box returns the pipeline to "the generator decides per task".
async function saveBrokerRole(name, role, checked) {
  try {
    const res = await fetch('/api/context-broker', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ role, agent: checked ? name : null, enabled: checked }),
    })
    const data = await res.json().catch(() => ({}))
    if (data.ok) {
      if (data.config) brokerState = { ...brokerState, ...data, config: data.config }
      showToast(t('agents.ctx.saved'))
      // Redraw every card: the role just moved off whichever card held it.
      renderAgents()
    } else showToast(t('agents.ctx.failed'))
  } catch { showToast(t('agents.ctx.failed')) }
}

// Change how the designated generator behaves. `agent` is re-sent unchanged so
// the POST does not read as an un-designation.
async function saveBrokerOptions(name, options) {
  try {
    const res = await fetch('/api/context-broker', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agent: name, enabled: true, ...options }),
    })
    const data = await res.json().catch(() => ({}))
    if (data.ok) {
      if (data.config) brokerState = { ...brokerState, ...data, config: data.config }
      showToast(t('agents.ctx.saved'))
    } else showToast(t('agents.ctx.failed'))
  } catch { showToast(t('agents.ctx.failed')) }
}

// Designate (or un-designate) the context generator. The POST replaces the
// single stored name, so the previously-checked card loses its tick -- but only
// the re-render below makes that VISIBLE, which is why this redraws every card
// instead of just this one.
async function saveBrokerConfig(name, checked) {
  try {
    const res = await fetch('/api/context-broker', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agent: checked ? name : null, enabled: checked }),
    })
    const data = await res.json().catch(() => ({}))
    if (data.ok) {
      brokerState = {
        designated: data.designated ?? null,
        effective: data.effective ?? null,
        reason: data.reason || 'unset',
        steppedOver: data.steppedOver ?? null,
        // Roles and the two policy settings survive a designation change on the
        // server (writeBrokerConfig preserves what the caller did not mention),
        // so they must survive it here too -- dropping them would blank every
        // role checkbox until the next full page load.
        config: data.config ?? brokerState.config ?? null,
      }
      showToast(t('agents.ctx.saved'))
      renderAgents()
    } else showToast(t('agents.ctx.failed'))
  } catch { showToast(t('agents.ctx.failed')) }
}

async function doContextAction(name, action, force = false) {
  // /clear is irreversible for the conversation -- always confirm before the
  // first attempt, and a second time (with the count) if the backend reports
  // unprocessed inbound that the clear would eat.
  if (action === 'clear' && !force && !confirm(t('agents.ctx.clear_confirm'))) return
  try {
    const res = await fetch(`/api/agents/${encodeURIComponent(name)}/context-action`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action, force }),
    })
    const data = await res.json().catch(() => ({}))
    if (data.needsConfirm) {
      if (confirm(t('agents.ctx.clear_confirm_pending', { n: data.pending }))) return doContextAction(name, action, true)
      return
    }
    if (data.busy) { showToast(t('agents.ctx.busy')); return }
    if (data.ok) {
      showToast(t(action === 'clear' ? 'agents.ctx.cleared' : 'agents.ctx.compacted'))
      // The backend returns as soon as the slash command is typed, NOT when it
      // finishes. /clear wipes instantly, but /compact runs ~1 min and only then
      // writes the new (smaller) size. There is no periodic agents refresh, so
      // pull fresh cards a few times to let the number drop on its own -- no
      // manual page reload needed. Guard on the hash so we don't refetch after
      // the operator has navigated away.
      const delays = action === 'clear' ? [1500] : [8000, 20000, 45000, 75000, 95000]
      for (const ms of delays) {
        setTimeout(() => { if ((location.hash.slice(1) || 'overview') === 'agents') loadAgents() }, ms)
      }
      return
    }
    showToast(t('agents.ctx.failed'))
  } catch { showToast(t('agents.ctx.failed')) }
}

async function saveGateConfig(name, enabled, thresholdEl) {
  const kv = thresholdEl ? parseInt(thresholdEl.value, 10) : NaN
  const thresholdTokens = Number.isFinite(kv) && kv > 0 ? kv * 1000 : undefined
  try {
    const res = await fetch('/api/context-restart-gate', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agent: name, enabled: !!enabled, thresholdTokens }),
    })
    const data = await res.json().catch(() => ({}))
    if (data.ok && data.config) { gateCfgByAgent.set(name, data.config); showToast(t('agents.ctx.saved')) }
    else if (data.issue && Number.isFinite(data.suggestedThresholdTokens)) {
      // The backend refused a threshold that could never fire. Say what the
      // usable value is instead of a bare "failed" -- and put it in the box, so
      // the fix is one keystroke away rather than a calculation.
      showToast(t('agents.ctx.gate_rejected', { max: Math.floor(data.suggestedThresholdTokens / 1000) }))
      if (thresholdEl) thresholdEl.value = Math.floor(data.suggestedThresholdTokens / 1000)
    }
    else showToast(t('agents.ctx.failed'))
  } catch { showToast(t('agents.ctx.failed')) }
}

function renderAgents() {
  // A fiokok allapota kell a kartyara kerulo kijelentkeztetes-gombhoz. Egyszer
  // toltodik be, es amikor megjott, egyszer ujrarajzolunk -- addig a kartya
  // gomb nelkul all, mert egy talalgatott gomb rosszabb, mint egy kesobb
  // megjeleno.
  primeClaudeAccounts(() => renderAgents())
  // Hide for the duration of THIS render too (not just the very first paint,
  // covered by the `hidden` attribute already on the static HTML) -- while
  // it's mid-reparent below (briefly a plain last child of agentsGrid again,
  // still carrying last render's positioning class) a repaint landing in
  // that window would show it full-size top-left before it snaps onto the
  // divider (Boss, 2026-08-08, second report -- still flashed after the
  // first fix, which only covered the initial pageload case).
  addBtn.hidden = true
  agentsGrid.querySelectorAll('.agent-card:not(.add-card)').forEach((el) => el.remove())
  // The divider (and addBtn re-parented into it, see below) survive from the
  // previous render -- clear it before rebuilding, and move addBtn back to
  // being a direct child of agentsGrid first. Every insertBefore(x, addBtn)
  // call below requires addBtn to be a DIRECT child of agentsGrid; leaving it
  // nested inside a stale divider throws (NotFoundError) on the very first
  // insertBefore call, aborting the whole render with an empty grid -- this
  // silently wiped every agent card on the second render pass (Boss,
  // 2026-08-08, screenshot: only the "+" button visible, 7 agents in the
  // data but zero cards on screen).
  agentsGrid.appendChild(addBtn)
  agentsGrid.querySelectorAll('.agent-tier-divider').forEach((el) => el.remove())

  // Marveen card (always first)
  if (window._marveen) {
    const m = window._marveen
    const displayName = m.name || 'Marveen'
    // The model is no longer hardcoded: /api/marveen reports the configured
    // model (readActiveModelFromProjectDir). Mirror the sub-agent card, which
    // uses the model value as both the badge label and class. Fall back to
    // 'opus' only before /api/marveen has resolved (or on a legacy backend).
    const mainModelLabel = m.model || 'opus'
    const mainModelClass = m.model || 'opus'
    const mCard = document.createElement('div')
    mCard.className = 'agent-card marveen-card'
    mCard.innerHTML = `
      <div class="agent-card-badges">${accountBadgeHtml(null, true)}${costBadgeHtml(m.costPerMInput)}</div>
      <div class="agent-card-top">
        <div class="agent-avatar"><img src="/api/marveen/avatar${avatarBust()}" alt="${escapeHtml(displayName)}"></div>
        <div class="agent-card-info">
          <div class="agent-name">${escapeHtml(displayName)} <span class="marveen-badge">${t('agents.main_badge')}</span></div>
          <div class="agent-desc" title="${escapeAttr(m.description || '')}">${escapeHtml(shortDesc(m.description))}</div>
        </div>
      </div>
      <div class="agent-card-footer">
        <span class="agent-model-badge ${escapeHtml(mainModelClass)}">${escapeHtml(mainModelLabel)}</span>
        ${marveenProcessHtml(m)}
        <span class="tg-status" title="${t('agents.marveen_channel_tip')}"><span class="tg-dot connected"></span>${t('agents.status.online')}</span>
      </div>
      <div class="agent-card-actions">
        <button class="btn-secondary btn-compact agent-conversation-btn" title="${t('agents.btn.conversation')}">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
          ${t('agents.btn.conversation')}
        </button>
        <button class="btn-secondary btn-compact agent-terminal-btn" title="Terminal">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="4 17 10 11 4 5"/><line x1="12" y1="19" x2="20" y2="19"/></svg>
          Terminal
        </button>
        ${contextButtonsHtml(mainAgentId())}
      </div>
      ${contextControlsHtml(mainAgentId(), m.contextTokens, true, m.contextState, m.contextQuota)}
    `
    mCard.querySelector('.agent-terminal-btn')?.addEventListener('click', (e) => {
      e.stopPropagation(); openTerminalModal(mainAgentId())
    })
    mCard.querySelector('.agent-conversation-btn')?.addEventListener('click', (e) => {
      e.stopPropagation(); openConversationModal(mainAgentId(), t('agents.marveen_boss'))
    })
    mCard.addEventListener('click', () => openMarveenDetail())
    wireContextControls(mCard, mainAgentId())
    agentsGrid.insertBefore(mCard, addBtn)
  }

  // A VS Code vegrehajto kartyai KOZVETLENUL Marveen utan allnak, meg a
  // szintvalaszto csik elott. Eloszor a federalt kartyakkal egyutt a sor
  // vegere kerultek -- az pedig az INGYENES sav ala tette oket (Boss,
  // 2026-08-22). A besorolas a lap egyetlen jelzese arrol, mi megy kozos,
  // limitalt ingyen-poolon: a kod-hid a sajat Claude Code elofizetesedet
  // hasznalja, tehat a felso savba tartozik.
  renderCodeBridgeAgentCards(agentsGrid, addBtn)

  // Paid/unrestricted agents first, then a divider, then free-tier OpenRouter
  // agents -- otherwise the two tiers render interleaved and there's no way
  // to tell at a glance which cards are on a shared, rate-limited free pool.
  const paidAgents = agents.filter(a => !isFreeModel(a.model))
  const freeAgents = agents.filter(a => isFreeModel(a.model))
  const sortedAgents = [...paidAgents, ...freeAgents]
  let dividerEl = null
  for (const agent of sortedAgents) {
    if (!dividerEl && freeAgents.length && agent === freeAgents[0]) {
      dividerEl = document.createElement('div')
      dividerEl.className = 'agent-tier-divider'
      dividerEl.innerHTML = `<span>${escapeHtml(t('agents.tier_divider.free'))}</span>`
      agentsGrid.insertBefore(dividerEl, addBtn)
    }
    // agent.name is the sanitized id (API/filesystem); displayName keeps the
    // original accented/cased input the user typed.
    const label = agent.displayName || agent.name
    const card = document.createElement('div')
    card.className = 'agent-card'
    card.dataset.name = agent.name
    const hasImg = agent.hasImage || agent.hasAvatar
    const avatarHtml = hasImg
      ? `<img src="/api/agents/${encodeURIComponent(agent.name)}/avatar${avatarBust()}" alt="${escapeHtml(label)}">`
      : label.charAt(0).toUpperCase()
    // No image -> the same coloured monogram the team view and the chat list
    // use, keyed off the agent id so one agent keeps one colour everywhere.
    const avatarClass = hasImg ? 'agent-avatar' : 'agent-avatar avatar-mono'
    const avatarStyle = hasImg ? '' : ` style="background:${monogramColor(agent.name)}"`

    const modelClass = agent.model && agent.model !== 'inherit' ? agent.model : ''
    const modelLabel = agent.model || 'inherit'
    const chConnected = agentIsConnected(agent)
    const chDotClass = chConnected ? 'connected' : 'disconnected'
    const chLabel = chConnected ? t('agents.status.online') : t('agents.status.offline')
    const isRunning = agent.running || false
    const runDotClass = isRunning ? 'running' : 'stopped'
    const runLabel = isRunning ? t('agents.status.running') : t('agents.status.stopped')

    card.innerHTML = `
      <div class="agent-card-badges">${accountBadgeHtml(agent.claudePlan, false)}${costBadgeHtml(agent.costPerMInput)}${reliabilityBadgeHtml(agent.reliability)}</div>
      <div class="agent-card-top">
        <div class="${avatarClass}"${avatarStyle}>${avatarHtml}</div>
        <div class="agent-card-info">
          <div class="agent-name">${escapeHtml(label)}</div>
          <div class="agent-desc" title="${escapeAttr(agent.description || '')}">${escapeHtml(shortDesc(agent.description))}</div>
        </div>
      </div>
      <div class="agent-card-footer">
        <span class="agent-model-badge ${escapeHtml(modelClass)}">${escapeHtml(modelLabel)}</span>
        <span class="process-indicator" title="${escapeHtml(processTip(isRunning, agent.needsReauth))}"><span class="process-dot ${runDotClass}"></span>${runLabel}</span>
        <span class="tg-status" title="${escapeHtml(channelTip(chConnected, agent.needsReauth))}"><span class="tg-dot ${chDotClass}"></span>${chLabel}</span>
      </div>
      ${agent.needsReauth ? `
        <div class="agent-reauth-banner">
          <span class="agent-reauth-reason" title="${escapeAttr(agent.reauthReason ? t('agents.reauth.raw_tip', { raw: agent.reauthReason }) : '')}">${escapeHtml(agent.reauthReasonKey ? t(agent.reauthReasonKey) : t('agents.reauth.reason'))}</span>
          <button class="btn-danger btn-compact agent-login-btn" data-phase="start">${t('agents.btn.login')}</button>
        </div>` : ''}
      <div class="agent-card-actions">
        <button class="btn-secondary btn-compact agent-conversation-btn" title="${t('agents.btn.conversation')}">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
          ${t('agents.btn.conversation')}
        </button>
        <button class="btn-secondary btn-compact agent-terminal-btn" title="Terminal">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="4 17 10 11 4 5"/><line x1="12" y1="19" x2="20" y2="19"/></svg>
          Terminal
        </button>
        ${contextButtonsHtml(agent.name)}
      </div>
      ${contextControlsHtml(agent.name, agent.contextTokens, isRunning, agent.contextState, agent.contextQuota)}
    `
    // Login button handler (start → confirm flow)
    card.querySelectorAll('.agent-login-btn').forEach(btn => {
      btn.addEventListener('click', (e) => { e.stopPropagation(); handleAgentLogin(agent.name, btn, agent.claudePlan || null, card, isRunning) })
    })
    // Terminal button
    card.querySelector('.agent-terminal-btn')?.addEventListener('click', (e) => {
      e.stopPropagation(); openTerminalModal(agent.name)
    })
    // Conversation (readable transcript) button
    card.querySelector('.agent-conversation-btn')?.addEventListener('click', (e) => {
      e.stopPropagation(); openConversationModal(agent.name, label)
    })
    card.addEventListener('click', () => openAgentDetail(agent.name))
    // Only running agents have a live session to look at, so only they get the
    // copy-the-tmux-command buttons.
    // A tmux-masolo gomb 2026-08-23 ota NEM a kartyan van (Boss: "szedd le.
    // nem kell az oda. (...) de terminalba is minek? de beteheted."): a
    // Terminal-ablak fejlecebe kerult, oda, ahol amugy is a panelt nezed.
    wireContextControls(card, agent.name)
    agentsGrid.insertBefore(card, addBtn)
  }
  renderFederatedAgentCards(agentsGrid, addBtn)
  // Straddle the "+ new agent" button on the divider line itself (half in the
  // paid section, half in the free one) -- otherwise it only ever lands after
  // the last card in DOM order, i.e. visually inside the free section, which
  // reads as "new agents can only be added there" (Boss, 2026-08-08).
  // insertBefore(card, addBtn) above needs addBtn to stay a direct child of
  // agentsGrid for the whole loop, so it can only be re-parented onto the
  // divider afterwards, once nothing else is anchoring off it.
  if (dividerEl) {
    addBtn.classList.add('add-card-on-divider')
    dividerEl.appendChild(addBtn)
  } else {
    addBtn.classList.remove('add-card-on-divider')
  }
  // Starts `hidden` in the static HTML so a page load/refresh doesn't flash
  // it full-size in its default top-left slot before this function has had a
  // chance to size and position it (Boss, 2026-08-08: saw it "land big, then
  // snap into place"). Reveal only now that it's correctly classed/placed.
  addBtn.hidden = false
  // Re-apply the live busy tint right after a re-render (renderAgents rebuilds
  // the cards from scratch, dropping the class), so it never blinks off while
  // the page is open. The poll itself now runs unconditionally from load, so
  // no timer guard is needed here any more.
  refreshAgentTerminalBusy()
}

// === Agents: live "working" tint on Terminal buttons ===
// Reuse the Activity page's data source (/api/agents/activity, same 3s poll,
// same working/idle state derived from the tmux pane) to turn an agent card's
// Terminal button green while that agent is actively working, and clear it when
// it goes idle or stops. No new backend -- just a second consumer of the same
// endpoint. The main (Marveen) card matches on mainAgentId(); sub-agent cards
// match on their data-name.
let globalActivityTimer = null
// A legutobbi 3 masodperces meres allapotai, nev -> allapot. A "mindent
// ujraindit" megerosito kerdese olvassa (lasd refreshAgentTerminalBusy).
let lastActivityStateByName = new Map()
// Card data (context size, model, run state) refreshed on its own slower beat.
// Boss, 2026-08-12: the gate compacted his session from 195k to 59k and the card
// kept showing 195k until he pressed Ctrl-Shift-R. "a tokenokat azonnal a
// legfrissebbet akarom latni." A page that only loads once is a page that lies
// as soon as anything changes.
let agentsDataTimer = null
const AGENTS_DATA_REFRESH_MS = 60000
// Agents seen mid-compaction on the previous 3s poll. When one drops off the
// list the compaction just landed, so the new (smaller) number exists NOW --
// that is the moment to refresh, rather than waiting out the minute.
let compactingAgents = new Set()
function startAgentsDataRefresh() {
  if (agentsDataTimer) clearInterval(agentsDataTimer)
  agentsDataTimer = setInterval(() => {
    // Skip while the tab is hidden: a background tab polling forever is how a
    // laptop fan and a rate limit meet.
    if (document.hidden) return
    if ((location.hash.slice(1) || 'overview') !== 'agents') return
    // Never redraw under someone's hands: the cards carry a threshold input, and
    // a refresh mid-typing would swallow the number being entered.
    if (agentsGrid && agentsGrid.contains(document.activeElement)) return
    loadAgents()
  }, AGENTS_DATA_REFRESH_MS)
}
function stopAgentsDataRefresh() {
  if (agentsDataTimer) { clearInterval(agentsDataTimer); agentsDataTimer = null }
}
// The 3s working/idle poll -- source for the Agents page's Terminal button
// tint AND the sidebar's global "someone is working" badge (visible on every
// page). Started ONCE at load, unconditionally, and never stopped by page
// navigation: Boss reported five times that the green indicator went dark
// while an agent (visible in its own terminal window) kept working, because
// the poll used to run only while the Agents page itself was open
// (2026-08-17). `agentsGrid.querySelectorAll(...)` still finds the Terminal
// buttons even while the Agents page is hidden -- pages stay in the DOM,
// `switchPage` only toggles the `hidden` attribute.
function startGlobalActivityPoll() {
  if (globalActivityTimer) return
  refreshAgentTerminalBusy()
  globalActivityTimer = setInterval(refreshAgentTerminalBusy, 3000)
}
async function refreshAgentTerminalBusy() {
  let entries
  try {
    const res = await fetch('/api/agents/activity')
    if (!res.ok) return
    entries = await res.json()
  } catch { return }
  if (!Array.isArray(entries)) return
  const stateByName = new Map(entries.map((e) => [e.name, e.state]))
  // A "mindent ujraindit" megerosito kerdese ugyanezt a merest hasznalja, hogy
  // ne KETFELE "dolgozik" fogalom legyen a feluleten. A kiszolgalo a szigoru
  // jelet adja (biztosan futo munka), ez itt a tagabbat -- Boss szerint "ha
  // barmit is csinal vagy futtat, akor is dolgozik". Az ijesztobb (tagabb)
  // olvasat a helyes, amikor arrol kerdezunk, megszakitsuk-e.
  lastActivityStateByName = stateByName
  // A compaction that finished since the last poll: pull the fresh numbers now.
  const nowCompacting = new Set(entries.filter((e) => e.compacting).map((e) => e.name))
  let justFinished = false
  for (const name of compactingAgents) if (!nowCompacting.has(name)) justFinished = true
  compactingAgents = nowCompacting
  if (justFinished && (location.hash.slice(1) || 'overview') === 'agents'
      && !(agentsGrid && agentsGrid.contains(document.activeElement))) loadAgents()
  if (agentsGrid) {
    const mainId = mainAgentId()
    agentsGrid.querySelectorAll('.agent-card:not(.add-card)').forEach((card) => {
      const btn = card.querySelector('.agent-terminal-btn')
      if (!btn) return
      const id = card.classList.contains('marveen-card') ? mainId : card.dataset.name
      const working = !!id && stateByName.get(id) === 'working'
      btn.classList.toggle('agent-terminal-btn--busy', working)
    })
  }
  const workingCount = entries.filter((e) => e.state === 'working').length
  const badge = document.getElementById('agentsWorkingBadge')
  if (badge) {
    badge.hidden = workingCount === 0
    badge.textContent = String(workingCount)
    badge.title = t('nav.agents_working_tip', { count: workingCount })
  }
}

// Federated (remote-system) agents from the manifest-poller cache. Kept in a
// SEPARATE array from `agents`: that global feeds the team editor and the
// create-wizard, where qualified ids would be selectable-and-invalid.
// "remote" already means SSH agents in this codebase -- these are FEDERATED.
// === Kod-hid (VS Code Claude Code) a Csapat lapon ===
// A vegrehajto egy KULSO csapattag: nem tmux-agent, nincs sajat process a
// gepen, es sosem szerepelt az /api/agents listaban -- ezert a Csapat lapon
// eddig NEM latszott sehol, pedig ez az egyetlen tag, aki valoban kodot ir.
// A kartya read-only: a beallitasok a Kod-hid ablakban vannak, mert a
// feladatkuldes ott lakik, a projekt-valasztoval egyutt.
let codeBridgeCards = { state: 'loading', projects: [], workerOnline: false, queued: 0, running: 0 }

// Nulla projekt eseten a kartya a KOVETKEZO LEPEST mondja meg, nem csak azt,
// hogy nincs semmi. Harom kulon allapot, harom kulon teendo -- aki eloszor
// tolti le a Marveent, ebbol tudja meg, hol tart es merre menjen tovabb.
function cbIdleCardEntry(off) {
  if (off) {
    return {
      title: 'VS Code Claude Code',
      desc: 'A kód-híd ki van kapcsolva. Kattints a kártyára — a Működés dobozban kapcsolható be.',
      online: false,
      note: 'kikapcsolva',
    }
  }
  if (!codeBridgeCards.workerOnline) {
    return {
      title: 'VS Code Claude Code',
      desc: 'Nincs futó Windows-végrehajtó. Kattints a kártyára — a Beüzemelés lista végigvezet a telepítésén.',
      online: false,
      note: 'nincs végrehajtó',
    }
  }
  // A vegrehajto MAR latja a mappat: ilyenkor nem uj projektet kell nyitni,
  // hanem felvenni (vagy feloldani) azt, ami ott van a listaban.
  const cand = codeBridgeCards.candidates || { free: 0, excluded: 0, dismissed: 0 }
  // ELOSZOR a levett mappa: ez a leggyakoribb oka annak, hogy egy mukodo
  // kartyarol "eltunt minden". Ha itt a "meg egyik sincs felveve" allna, a
  // tulaj a felderitest hibaztatna egy sajat kattintas helyett.
  if (cand.dismissed > 0) {
    return {
      title: 'VS Code Claude Code',
      desc: t('cb.idle.dismissed', { n: cand.dismissed }),
      online: false,
      note: t('cb.idle.dismissed_note', { n: cand.dismissed }),
    }
  }
  if (cand.free > 0) {
    return {
      title: 'VS Code Claude Code',
      desc: 'A végrehajtó ' + cand.free + ' mappát talált a gépeden, de még egyik sincs felvéve. Kattints a kártyára — a listából egy kattintás.',
      online: false,
      note: cand.free + ' felvehető mappa',
    }
  }
  if (cand.excluded > 0) {
    return {
      title: 'VS Code Claude Code',
      desc: 'A végrehajtó ' + cand.excluded + ' mappát lát a gépeden, de mind ki van zárva. Kattints a kártyára — a listában feloldhatod.',
      online: false,
      note: cand.excluded + ' kizárt mappa',
    }
  }
  return {
    title: 'VS Code Claude Code',
    desc: 'A végrehajtó fut, de még egy projekt sincs regisztrálva — nyiss meg egy projektet VS Code-ban Claude Code-dal.',
    online: false,
    note: 'nincs projekt',
  }
}

// Mit csinal EPPEN a hid. A bal menu jelvenye megszunt a Kod-hid-lappal
// egyutt, es a "3 sorban" onmagaban is ertekesebb informacio, mint egy szam
// egy menupont mellett: itt latszik, amikor a kartyat nezed.
function cbCardNote() {
  // ELOSZOR a fuggoben levo le-/bekapcsolas: ez a kartyan KIVUL eddig sehol nem
  // latszott, pedig ez valtoztatja meg leginkabb, hogy mire szamit az ember.
  if (codeBridgeCards.savedEnabled === false && codeBridgeCards.state !== 'disabled') {
    return t('cb.card.stop_pending')
  }
  if (!codeBridgeCards.workerOnline) return t('cb.card.worker_off')
  const busy = codeBridgeCards.queued + codeBridgeCards.running
  if (codeBridgeCards.running) return t('cb.card.busy', { n: codeBridgeCards.running, q: codeBridgeCards.queued })
  if (busy) return t('cb.card.queued', { n: busy })
  return t('cb.card.worker_on')
}

// A kartya CIME. A Csapat lapon minden mas ugynok a sajat Telegram-nevet
// viseli; a VS Code kartya sokaig a workspace mappanevet mutatta ("fejlesztes"),
// ami kilogott a sorbol. Ha van kod-bot, az a nev.
//
// Ha nincs: NEM irunk oda hamis nevet, es nem is hallgatunk el semmit -- a
// projekt aliasa marad a cim (a hid kod-bot nelkul is mukodik, Marvinon at),
// a hianyt pedig a leiras-sor mondja ki. A "nem tudtam lekerdezni" kulon eset,
// ott a Telegram sajat hibauzenete latszik, nem egy tipp.
function cbCardTitle(fallback) {
  const bot = codeBridgeCards.bot
  if (bot && bot.reason === 'ok' && bot.name) return bot.name
  return fallback
}

// A szerepek (tervezo / megvalosito / ellenorzo) gazdaja egy NEV a broker
// beallitasaban. A kod-hid nem ugynok, nincs ugynok-neve, ezert a projektjebol
// kepzunk egyet: `vscode:<projekt>`.
//
// Miert projektenkent, es nem egy kozos "vscode" nev: mert egy szerepet
// egyszerre EGY gazda tarthat. Ha minden VS Code kartya ugyanazt a nevet
// hasznalna, a "megvalosito" bepipalasa az egyik projekten nemán levenne a
// masikrol, holott ket kulon workspace-rol van szo.
//
// A ketospont szandekos: ugynok-nev soha nem tartalmazhat ilyet, igy egy
// projekt nem tudja elvenni a szerepet egy azonos nevu ugynoktol.
function cbRoleHolder(project) {
  return project ? 'vscode:' + project : ''
}

function cbCardBotNote() {
  const bot = codeBridgeCards.bot
  if (!bot || bot.reason === 'ok') return ''
  if (bot.reason === 'not-configured') return t('cb.card.bot_missing')
  return t('cb.card.bot_unresolved', { msg: bot.error || t('cb.card.bot_no_reason') })
}

/** Kontextus-sor a kartyan: mennyi tokent hasznal EPPEN ez a beszelgetes, es a
 *  ket karbantarto gomb (Boss, 2026-08-23: "egy torles es tomorites gombot is
 *  kellene tenni ra. meg kiiratni hogy jelenleg mennyi a token").
 *
 *  A `null` nem 0: olyankor azt irjuk ki, hogy nem latunk ra (regi worker, meg
 *  nincs valasz a beszelgetesben), nem azt, hogy ures. */
/** Token-szam ezresre kerekitve, egy helyen. Harom helyrol hivjuk (kontextus-sor,
 *  ful-sor, ures-lista-uzenet), es ha kulon-kulon formaznank, elobb-utobb
 *  ugyanaz a szam ket alakban allna a kartyan. */
function cbFmtKTokens(n) {
  return (n / 1000).toFixed(n >= 10000 ? 0 : 1).replace('.', ',')
}

function cbContextRowHtml(e) {
  const n = e.contextTokens
  const val = n === null
    ? t('cb.card.ctx_unknown')
    : t('cb.card.ctx_value', { n: cbFmtKTokens(n) })
  // Ugyanaz a sor, mint a tobbi ugynok-kartyan (`ctx-current`), hogy ne egy
  // masik dobozban, mas meretben alljon ugyanaz az informacio.
  return `
    <div class="ctx-current" title="${escapeHtml(n === null ? t('cb.card.ctx_unknown_help') : t('cb.card.ctx_help', { n: String(n) }))}">${escapeHtml(val)}</div>`
}

/** ELO BESZELGETESEK a kartyan (Boss, 2026-08-23: "nem lenne celszeru oda
 *  kitenni a elo chateket? es egy jelolonegyzetet eleje tenni? amelyik be van
 *  jelolve az az aktualis elo. azt hasznlaja eppen.").
 *
 *  A lista CSAK azokat a fuleket mutatja, amiket a Windows-munkas nyitottkent
 *  MERT (`live === true`) -- a bezart beszelgetes transcriptje a lemezen marad,
 *  de a kartyan nincs helye. A bejelolt sor az, ahova a feladat megy.
 *
 *  Az ures lista ket dolgot jelenthet, ezert nem hallgatunk el:
 *    * `tabsReason === 'ok' | 'empty'` -> tenyleg nincs nyitott beszelgetes;
 *    * barmi mas (a munkas sose jelentkezett / elavult) -> NEM LATUNK ODA,
 *      es ezt ki is irjuk, nehogy a csend "nincs"-nek latsszon. */
/** A kiirhato ful-sorok.
 *
 *  ★ A BEKOTOTT SOR SOSEM ESIK KI. A szerver kifejezetten MEGTARTJA a bekotott
 *  beszelgetest a listaban akkor is, ha mar nem fut (`filterLive`,
 *  code-bridge-store.ts) -- pont azert, hogy a kartya ne latsszon
 *  cimezhetetlennek. A felulet viszont 2026-08-28-ig meg egyszer szurt, es ez a
 *  masodik szures kivetel nelkuli volt: eldobta azt, amit a szerver megorzott.
 *
 *  Igy allt elo a mondat, amire a Boss rakerdezett: "Nincs NYITVA beszelgetes
 *  -- a bekototte viszont megvan: 112k token. (...) hat ha me van a bekototte,
 *  akor miert nem jeleniti meg?" A kartya TUDOTT a beszelgetesrol, es megsem
 *  mutatta meg. Mostantol megmutatja -- kiirva, hogy nem fut. */
function cbTabRows(e) {
  // A NYITOTTSAG KET FORRASBOL JON, es barmelyik eleg.
  //
  // Ez a szuro EDDIG csak a futo folyamatot ismerte, es ezzel MASODSZOR is
  // kiszurte azt, amit a szerver mar atengedett -- ugyanaz a hiba ket helyen.
  // Boss, 2026-08-28 (Telegram 649): "viszont a 47 es kanban kartya nevu chat
  // az elo, az nincs bezarva. az kellene." Merve ugyanekkor: a fulhoz nem
  // futott claude.exe, kozben a VS Code panelen nyitva volt.
  //
  //   * `live !== false`       : fut, vagy nem latunk oda (regi worker);
  //   * `vscodeOpen === true`  : ott van a VS Code sajat listajaban -- ezt LATJA
  //     a felhasznalo, tehat a kartyan is ott a helye;
  //   * `current`              : a bekotott beszelgetes sosem tunhet el.
  return (e.tabs || []).filter(function (tb) {
    return tb.live !== false || tb.vscodeOpen === true || tb.current
  })
}
/** Van-e legalabb egy kiirhato ful-sor? Ha van, a kontextus szama MAR OTT all
 *  a bejelolt sor vegen, es a kulon "kontextus: 94k token" sor csak ismetles. */
function cbHasTabRows(e) {
  return cbTabRows(e).length > 0
}

/** Igaz, ha nincs kiirhato ful-sor, DE a bekotott beszelgetesnek van mert
 *  kontextusa. Ez a ketto egyutt mondott korabban ellentmondast a kartyan:
 *  "Nincs nyitott beszelgetes ebben a mappaban." + alatta "kontextus: 108k
 *  token" (Boss, 2026-08-24: "ha nincs beszelgetes akor nem kellene lennie
 *  tokennek sem").
 *
 *  Nem ellentmondas, csak ket KULONBOZO kerdesre valasz volt: a ful-lista azt
 *  mutatja, mi van EPPEN NYITVA a VS Code-ban, a token pedig a mappahoz kotott
 *  beszelgetes naploja, ami a lemezen marad a ful bezarasa utan is. Ezt a
 *  kartyanak KI KELL MONDANIA, nem eleg a tooltipbe rejteni. */
function cbTabsEmptyHasCtx(e) {
  return !cbHasTabRows(e) && typeof e.contextTokens === 'number' && e.contextTokens > 0
}

// Ennyi ora nemasag utan mondjuk ki a fulrol, hogy valoszinuleg mar nincs
// nyitott fule -- csak a folyamata el. Nem talalgatas: a mertek maga a jelzes,
// a szoveg az orak szamat mondja, es a dontest a felhasznalora hagyja.
const CB_TAB_IDLE_HOURS = 3

/** Egy beszelgetes bezarasa a vezerlopultrol. A transcript MEGMARAD -- csak a
 *  futo Claude Code folyamat all le. */
async function cbCloseTab(sessionId, label) {
  if (!confirm(t('cb.card.tab_close_confirm', { name: label || sessionId }))) return
  try {
    const res = await fetch('/api/code/tabs/' + encodeURIComponent(sessionId) + '/close', { method: 'POST' })
    const body = await res.json().catch(function () { return null })
    if (!res.ok) {
      // A szerver GEPI okot ad; mindegyiknek sajat, emberi mondata van, ami a
      // KOVETKEZO LEPEST mondja. Ismeretlen kodra a nyers uzenetet mutatjuk --
      // tippelt okot nem irunk oda.
      const code = body && body.error
      const msg = code === 'worker-offline' ? t('cb.card.tab_close_worker_off')
        : code === 'no-pid' ? t('cb.card.tab_close_no_pid')
        : code === 'unknown session' ? t('cb.card.tab_close_unknown')
        : (code || ('HTTP ' + res.status))
      showToast(t('cb.card.tab_close_failed', { msg: msg }), 'error')
      return
    }
    // A folyamatot a WORKER allitja le a kovetkezo jelentesekor, ezert nem azt
    // allitjuk, hogy kesz: azt mondjuk, mi tortenik es mikor latszik.
    showToast(t('cb.card.tab_close_queued'), 'success')
  } catch (err) {
    showToast(t('cb.card.tab_close_failed', { msg: String(err && err.message ? err.message : err) }), 'error')
  }
}

// A hid FUTASI allapota a kartyan -- ugyanazzal a `process-indicator`
// elemmel, mint minden mas ugynoknel. Harom allapot, mert a kapcsolo csak a
// vezerlopult ujraindulasakor lep eletbe, es a ketto kozott a kartya eddig a
// REGI allapotot mutatta.
//   * mentve KI, elesben MEG megy  -> sarga: valtasra var
//   * mentve BE, elesben mar megy   -> zold: fut
//   * mentve BE, elesben meg nem    -> sarga: valtasra var
//   * `savedEnabled` hianyzik (regi backend) -> nem talalgatunk: az ELES
//     allapotot mutatjuk, ahogy eddig is.
function cbRunPending() {
  if (codeBridgeCards.savedEnabled === null || codeBridgeCards.savedEnabled === undefined) return false
  return codeBridgeCards.savedEnabled !== (codeBridgeCards.state !== 'disabled')
}
function cbRunOn() {
  return codeBridgeCards.savedEnabled === null || codeBridgeCards.savedEnabled === undefined
    ? codeBridgeCards.state !== 'disabled'
    : codeBridgeCards.savedEnabled
}
function cbRunDotClass() { return cbRunPending() ? 'restarting' : (cbRunOn() ? 'running' : 'stopped') }
function cbRunLabel() { return cbRunOn() ? t('agents.status.running') : t('agents.status.stopped') }
function cbRunTip() {
  return cbRunPending()
    ? t('cb.card.stop_pending_help')
    : (cbRunOn() ? t('cb.card.run_on_help') : t('cb.card.run_off_help'))
}

/** A "beszelgetes megnyitasa" gomb egy ful-sorhoz.
 *
 *  CSAK akkor all ki, ha a worker elkuldte a napló utjat (`hasTranscript`).
 *  Egy regi worker mellett nem lenne mit megnyitni -- olyankor a hallgatas a
 *  helyes valasz, nem egy gomb, ami hibauzenettel jutalmaz. */
function cbTabOpenBtn(tb, label) {
  if (!tb || !tb.hasTranscript) return ''
  return '<button type="button" class="cb-tab-open" data-session="' + escapeAttr(tb.sessionId) + '"'
    + ' data-label="' + escapeAttr(label || '') + '"'
    + ' title="' + escapeAttr(t('cb.card.tab_open') + ' — ' + t('cb.card.tab_open_help')) + '"'
    + ' aria-label="' + escapeAttr(t('cb.card.tab_open')) + '">☰</button>'
}

/** A MAPPA TOBBI BESZELGETESE -- azok, amiknek a folyamata mar nem fut.
 *
 *  Boss, 2026-08-28: "a kartyan csak eg chat van megjelenitve, most, de a
 *  vscode ban van vagy 3 beszelgetes." Mert allapot ugyanekkor: egyetlen futo
 *  Claude Code folyamat volt a gepen, a masik ket ful NYITVA volt a VS Code
 *  panelen, de nem futott (aznap egy sort sem irtak). A ketto nem mond ellent
 *  egymasnak: a "nyitott ful" es a "futo folyamat" ket kulonbozo dolog.
 *
 *  Ezek a sorok ezert NEM a fo listaba valok (oda a cimezheto, futo
 *  beszelgetesek mennek -- 2026-08-23: "amit a vscode ban kitorolnek azt a
 *  maveen kartyaja se mutassa"), de elerhetonek KELL lenniuk: osszecsukott
 *  reszletezoben ulnek, es a tartalmuk ugyanugy megnyithato. */
function cbClosedTabsHtml(e) {
  const closed = (e.closedTabs || [])
  if (closed.length === 0) return ''
  const rows = closed.map(function (tb) {
    const label = tb.title || tb.shortId || ''
    const ctxN = (typeof tb.contextTokens === 'number' && tb.contextTokens > 0) ? cbFmtKTokens(tb.contextTokens) : null
    const ctx = ctxN === null ? ''
      : '<span class="cb-tab-ctx" title="' + escapeAttr(t('cb.card.ctx_value', { n: ctxN })) + '">'
        + escapeHtml(t('cb.card.ctx_short', { n: ctxN })) + '</span>'
    // Az "utoljara irt" a legfontosabb adat egy nem futo beszelgetesnel: ebbol
    // ismered fel, melyik volt a tegnapi. Ha nem tudjuk megnezni a naplo idejet,
    // inkabb semmit nem irunk oda -- egy kitalalt "regen" rosszabb a semminel.
    const when = (typeof tb.mtime === 'number' && tb.mtime > 0)
      ? '<span class="cb-tab-when" title="' + escapeAttr(t('cb.card.tab_last_write')) + '">'
        + escapeHtml(formatRelative(tb.mtime)) + '</span>'
      : ''
    return '<div class="cb-tab-row cb-tab-row-closed">'
      + '<span class="cb-tab-title" title="' + escapeAttr(label) + '">' + escapeHtml(label) + '</span>'
      + ctx
      + when
      + cbTabOpenBtn(tb, label)
      + '</div>'
  }).join('')
  return '<details class="cb-tabs-closed">'
    + '<summary title="' + escapeAttr(t('cb.card.tabs_closed_help')) + '">'
    + escapeHtml(t('cb.card.tabs_closed', { n: closed.length })) + '</summary>'
    + rows + '</details>'
}

function cbTabsPickHtml(e) {
  const tabs = cbTabRows(e)
  if (tabs.length === 0) {
    const known = e.tabsReason === 'ok' || e.tabsReason === 'empty'
    // Harom allapot, mert harom kulonbozo dolog tortent -- es mindharomnak mas
    // a kovetkezo lepese:
    //   * nem latunk oda (a munkas nem jelentkezett)      -> inditsd el a munkast
    //   * a munkas latja, hogy nincs nyitva, es nincs napló -> nyiss egyet
    //   * a munkas latja, hogy nincs nyitva, DE van napló   -> nyisd meg ujra
    const withCtx = known && cbTabsEmptyHasCtx(e)
    const kTok = withCtx ? cbFmtKTokens(e.contextTokens) : ''
    const msg = !known ? t('cb.card.tabs_blind')
      : withCtx ? t('cb.card.tabs_none_ctx', { n: kTok })
      : t('cb.card.tabs_none')
    const tip = !known ? t('cb.card.tabs_blind_help')
      : withCtx ? t('cb.card.tabs_none_ctx_help', { n: String(e.contextTokens) })
      : t('cb.card.tabs_none_help')
    return '<div class="cb-tabs-pick"><div class="cb-tabs-empty" title="'
      + escapeAttr(tip) + '">' + escapeHtml(msg) + '</div></div>'
  }
  const rows = tabs.map(function (tb) {
    const label = tb.title || tb.shortId || ''
    const ctxN = (typeof tb.contextTokens === 'number' && tb.contextTokens > 0)
      ? cbFmtKTokens(tb.contextTokens)
      : null
    const ctx = ctxN === null ? '' : t('cb.card.ctx_short', { n: ctxN })
    const ctxFull = ctxN === null ? '' : t('cb.card.ctx_value', { n: ctxN })
    // NEMA FUL: nyitott folyamat, de oraк ota nem irt semmit. Ez az az eset,
    // amit a VS Code-ban mar nem talalsz meg (a fule bezarult, a folyamat el),
    // ezert kulon mondjuk ki -- es ezert van mellette bezaras-gomb.
    const idleMs = (typeof tb.mtime === 'number' && tb.mtime > 0) ? (Date.now() - tb.mtime) : null
    const idleH = idleMs === null ? null : Math.floor(idleMs / 3600000)
    const idle = (idleH !== null && idleH >= CB_TAB_IDLE_HOURS && !tb.current)
      ? '<span class="cb-tab-idle" title="' + escapeAttr(t('cb.card.tab_idle', { h: idleH }) + ' \u2014 ' + t('cb.card.tab_idle_help', { h: idleH })) + '"'
        + ' aria-label="' + escapeAttr(t('cb.card.tab_idle', { h: idleH })) + '">\u25cf</span>'
      : ''
    // A gomb CSAK akkor all ki, ha tudjuk, mit allitanank le (van PID). A
    // hianyzo PID nem "nincs mit bezarni", hanem "nem latok oda" -- olyankor
    // nem kinalunk gombot, amirol nem tudjuk, hatna-e.
    const closeBtn = (typeof tb.pid === 'number' && tb.pid > 0)
      ? '<button type="button" class="cb-tab-close" data-session="' + escapeAttr(tb.sessionId) + '"'
        + ' data-label="' + escapeAttr(label) + '"'
        + ' title="' + escapeAttr(t('cb.card.tab_close') + ' \u2014 ' + t('cb.card.tab_close_help', { pid: tb.pid })) + '"'
        + ' aria-label="' + escapeAttr(t('cb.card.tab_close')) + '">\u00d7</button>'
      : ''
    // NEM FUT, DE ITT VAN. A bekotott beszelgetes akkor is a listaban marad, ha
    // a folyamata mar nem el -- ide megy a feladat, tehat latnod kell. A cimke
    // nem talalgat: azt mondja, amit MERTUNK (a worker `live` merese).
    // KET KULONBOZO ALLAPOT, es a felhasznalo pontosan az egyiket latja.
    //
    // Boss, 2026-08-28: a "47-es kanban kartya" nyitva volt a VS Code panelen,
    // kozben a folyamata nem futott. Ha ilyenkor csak annyit irnank ki, hogy
    // "nem fut", az szemben allna azzal, amit a sajat kepernyojen lat. A
    // nyitottsagot a VS Code sajat listajabol MERJUK -- ha megvan, mondjuk is.
    const notRunningKey = tb.vscodeOpen === true ? 'cb.card.tab_open_not_running' : 'cb.card.tab_not_running'
    const notRunning = tb.live === false
      ? '<span class="cb-tab-closed" title="' + escapeAttr(t(notRunningKey + '_help')) + '">'
        + escapeHtml(t(notRunningKey)) + '</span>'
      : ''
    return '<label class="cb-tab-row" title="' + escapeAttr(t('cb.card.tabs_pick_help', { s: tb.sessionId })) + '">'
      + '<input type="radio" class="cb-tab-radio" name="cbtab-' + escapeAttr(e.project || '') + '"'
      + ' value="' + escapeAttr(tb.sessionId) + '"'
      // A PID nem dísz: ebbol tudja a Tomorites/Torles gomb, hogy a ful EPP
      // NYITVA van a VS Code-ban -- egy futo beszelgetesre a headless `/clear`
      // nem hat, es a gombnak ezt meg kell mondania, nem sikert jelentenie.
      + (typeof tb.pid === 'number' && tb.pid > 0 ? ' data-pid="' + escapeAttr(String(tb.pid)) + '"' : '')
      + ' data-label="' + escapeAttr(label) + '"'
      + (tb.current ? ' checked' : '') + '>'
      + '<span class="cb-tab-title" title="' + escapeAttr(label) + '">' + escapeHtml(label) + '</span>'
      + (ctx ? '<span class="cb-tab-ctx" title="' + escapeAttr(ctxFull) + '">' + escapeHtml(ctx) + '</span>' : '')
      + notRunning
      + idle
      + cbTabOpenBtn(tb, label)
      + closeBtn
      + '</label>'
  }).join('')
  return '<div class="cb-tabs-pick"><div class="cb-tabs-head">' + escapeHtml(t('cb.card.tabs_title')) + '</div>' + rows + '</div>'
}

/** A valasztott beszelgetes ROGZITESE. `pinned: true` nelkul a felderites egy
 *  percen belul visszaallitana a legfrissebb fulre, es a valasztas hatastalannak
 *  latszana -- ugyanaz a csapda, mint a kartya-levetelnel volt. */
async function cbPickSession(project, workspacePath, sessionId) {
  try {
    const res = await fetch('/api/code/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ project: project, workspacePath: workspacePath, sessionId: sessionId, pinned: true }),
    })
    const body = await res.json().catch(function () { return null })
    if (!res.ok) { showToast(t('cb.card.tabs_pick_failed', { msg: (body && body.error) || ('HTTP ' + res.status) }), 'error'); return }
    showToast(t('cb.card.tabs_pick_done'), 'success')
    await loadCodeBridgeCards()
    renderAgents()
  } catch (err) {
    // A TENYLEGES hibat mondjuk, nem tippet arrol, mi lehetett.
    showToast(t('cb.card.tabs_pick_failed', { msg: String(err && err.message ? err.message : err) }), 'error')
  }
}

/** A kartya levetele. NEM torol se mappat, se beszelgetest -- csak a Marveen
 *  bekoteset szunteti meg, es megjegyzi, hogy a felderites ne kosse be ujra
 *  (kulonben egy percen belul visszajonne, es a gomb hatastalannak latszana).
 *  Visszahozni a kod-hid ablakabol lehet, ugyanonnan, ahonnan be lett kotve. */
async function cbDeleteProject(project) {
  if (!confirm(t('cb.card.delete_confirm', { p: project }))) return
  try {
    const res = await fetch('/api/code/projects/' + encodeURIComponent(project), { method: 'DELETE' })
    const body = await res.json().catch(() => null)
    if (!res.ok) { showToast(t('cb.card.delete_failed', { msg: (body && body.error) || ('HTTP ' + res.status) }), 'error'); return }
    showToast(t('cb.card.delete_done', { p: project }), 'success')
    await loadCodeBridgeCards()
    renderAgents()
  } catch (err) {
    // A TENYLEGES hibat mondjuk, nem tippet arrol, mi lehetett.
    showToast(t('cb.card.delete_failed', { msg: String(err && err.message ? err.message : err) }), 'error')
  }
}

/** A ket gomb ugyanazon az uton megy, mint barmelyik mas feladat: a hid
 *  `/compact` illetve `/clear` prompttal indit egy feladatot a projekt eppen
 *  aktualis beszelgetesebe. Merve (2026-08-23, `claude -p --resume`): mindketto
 *  ervenyes parancs headless modban is -- a `/compact` valasza pl. "Not enough
 *  messages to compact.", a `/clear` pedig UJ session-t nyit (a regi transcript
 *  megmarad), amit a worker a kovetkezo jelentesnel (~1 perc) atvesz. */
async function cbMaintenance(project, action, target) {
  // `target` = a kartyan KIJELOLT chat ful: { id, label, pid }. Eddig a gomb
  // nem adta at, es a feladat mindig a projekt eppen aktualis beszelgetesebe
  // ment. Ez ketto dolog miatt volt rossz: aki kijelolt egy fulet, mast vart --
  // es amikor a ketto veletlenul egybeesett, akkor sem latszott semmi, amit a
  // felulet nem magyarazott meg.
  //
  // A NYITOTT ful a masodik fele. Merve (2026-08-26, task 139b9c8f): a `/clear`
  // headless folyamatban HIBATLANUL lefutott (ok=True, 8,1 mp, 0 fordulo), a
  // VS Code-ban nyitva levo beszelgetes pedig valtozatlanul ment tovabb -- egy
  // futo ful a sajat folyamataban tartja a kontextust, oda a `--resume` nem
  // szol bele. A felulet viszont "sorba allitva" uzenetet mutatott: a
  // sikeresen lefutott feladat itt semminek NEM volt bizonyiteka.
  //
  // Ezert ha a cel-ful el, a gomb NEM tesz sorba hatastalan feladatot, hanem
  // megmondja, mi a kovetkezo lepes (zard be a fulet az x gombbal).
  if (target && target.pid) {
    alert(t('cb.card.maint_live', { name: target.label || target.id.slice(0, 8), pid: target.pid }))
    return
  }
  // KIJELOLES NELKUL NEM INDITUNK.
  //
  // A MERT ESET (2026-08-26, task 30077448 es e51a1038): mindket `/compact`
  // `target_session_id = null`-lal ment el, vagyis a cel nem a kijelolt ful volt,
  // hanem a projekt eppen aktualis beszelgetese -- a tulaj viszont azt latta,
  // hogy "nem a kijelolt chatet tomoriti". Boss: "de ez a tomorites sem a
  // kijelolt chatet tomoriti".
  //
  // Az ok utolag nem volt szetvalaszthato (regi lap vagy egyetlen bejelolt
  // radio sem -- ha a bekotott beszelgetes nincs a listazott fulek kozott,
  // alapbol egyik sincs kijelolve), ezert nem az OKOT talalgatjuk, hanem az
  // egesz hibaosztalyt szuntetjuk meg: cel nelkul a gomb NEM valaszt magatol.
  // Egy kitalalt celpont rosszabb, mint a semmi -- penzbe kerul (a ket futas
  // 1,09 es 0,42 USD volt) es mast tomorit, mint amit kertek.
  if (!target || !target.id) {
    alert(t('cb.card.maint_no_target'))
    return
  }
  const cel = t('cb.card.maint_target', { name: target.label || target.id.slice(0, 8) })
  const q = (action === 'clear' ? t('cb.card.clear_confirm', { p: project }) : t('cb.card.compact_confirm', { p: project }))
    + '\n\n' + cel
  if (!confirm(q)) return
  try {
    const res = await fetch('/api/code/tasks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      // A megcimzett ful a szerveren `target_session_id`-ba kerul, es a claim
      // ezt hasznalja a projekt aktualis beszelgetese HELYETT. A `null` nem
      // hiba: cimzes nelkul marad a regi viselkedes.
      body: JSON.stringify({
        project,
        prompt: '/' + action,
        origin: 'dashboard',
        requestedBy: 'dashboard',
        sessionId: (target && target.id) ? target.id : null,
      }),
    })
    const body = await res.json().catch(() => null)
    if (!res.ok) { showToast(t('cb.card.maint_failed', { msg: (body && body.error) || ('HTTP ' + res.status) }), 'error'); return }
    showToast(action === 'clear' ? t('cb.card.clear_queued') : t('cb.card.compact_queued'), 'success')
  } catch (err) {
    // A TENYLEGES hibat mondjuk, nem tippet arrol, mi lehetett.
    showToast(t('cb.card.maint_failed', { msg: String(err && err.message ? err.message : err) }), 'error')
  }
}

/** Egy `/api/code/projects` sorbol a kartya-bejegyzes -- KULON, TISZTA
 *  fuggveny, hogy a huzalozas is merheto legyen, ne csak a rajzolo segedek.
 *
 *  Boss, 2026-08-28 (kepernyokeppel): a VS Code panelen ott allt a "47-es
 *  kanban kartya" beszelgetes, a Marveen kartyajan nem -- "ugyanannak kellene
 *  latszania!". A szerver kuldte (`/api/code/projects` -> `closedTabs`), a
 *  rajzolo (`cbClosedTabsHtml`) ki is irta volna, csak eppen ez a
 *  bejegyzes-keszito nem masolta at: `e.closedTabs` mindig `undefined` lett,
 *  a lista pedig nemakent maradt ki. A ket veget kulon tesztelte a suite, a
 *  kozottuk levo masolast senki -- ezert maradt vegig zold.
 *
 *  Amit a hivo ad hozza (`ctx`), az nem a soré, hanem a kartyae: az allapot,
 *  a szerep-gazda es a "miert ures" indok. */
function cbEntryFromProject(r, ctx) {
  const c = ctx || {}
  return {
    title: r.project,
    desc: r.workspacePath || '',
    online: Boolean(c.online),
    note: c.note,
    roleHolder: c.roleHolder,
    project: r.project,
    // Lehet `null` = nem latunk ra. A kettot a kiiras kulon mondja el.
    contextTokens: (typeof r.contextTokens === 'number' && r.contextTokens > 0) ? r.contextTokens : null,
    // NEM fix "claude code": az, amivel a beszelgetes eppen valaszolt.
    // `null` = nem latunk oda -- olyankor sem talalunk ki egyet.
    model: (typeof r.model === 'string' && r.model.trim()) ? r.model.trim() : null,
    // Az elo beszelgetesek valasztojahoz: a POST-hoz kell a mappa utja is.
    workspacePath: r.workspacePath || '',
    tabs: Array.isArray(r.tabs) ? r.tabs : [],
    // A mappa TOBBI beszelgetese (nem fut a folyamatuk, de a fuluk nyitva
    // lehet a VS Code-ban). Regi backend nem kuldi -> ures lista, nem
    // `undefined`: a rajzolo igy sem talal ki semmit, csak nem ir ki sort.
    closedTabs: Array.isArray(r.closedTabs) ? r.closedTabs : [],
    tabsReason: c.tabsReason,
  }
}

function renderCodeBridgeAgentCards(agentsGrid, addBtn) {
  // Amig az elso lekeres be nem futott, nem rakunk ki felrevezeto kartyat.
  if (codeBridgeCards.state === 'loading' || codeBridgeCards.state === 'absent') return

  const off = codeBridgeCards.state === 'disabled'
  const rows = off ? [] : codeBridgeCards.projects
  // Nulla projekt mellett is KELL egy kartya. Enelkul a lap ugy nez ki,
  // mintha a kod-hid nem is letezne -- pontosan ez volt a panasz.
  const entries = rows.length
    ? rows.map(function (r) {
        return cbEntryFromProject(r, {
          online: codeBridgeCards.workerOnline,
          note: cbCardNote(),
          // Szerepet csak VALODI projekthez lehet rendelni: a "meg nincs
          // projekt" kartya nem cimezheto, igy jelolonegyzetet sem kap.
          roleHolder: cbRoleHolder(r.project),
          tabsReason: codeBridgeCards.tabsReason,
        })
      })
    : [cbIdleCardEntry(off)]

  const botNote = cbCardBotNote()
  for (const e of entries) {
    const card = document.createElement('div')
    card.className = 'agent-card code-bridge-agent-card'
    // A szinkulcs SZANDEKOSAN a projekt aliasa marad: egy projekt egy szin,
    // akkor is, ha kozben botot cserelsz.
    const name = cbCardTitle(e.title)
    // A projektet nem nyeljuk el: ha a cim mar a bot neve, a mappa aliasa a
    // leiras elso sorara kerul -- kulonben ket azonos nevu kartya megkulonboz-
    // tethetetlen lenne.
    // A teljes utvonal ket sort enne el a kartyan, es a vegen ugyis elvagodna.
    // A sorba a MAPPA NEVE kerul (azt keresi a szem), a teljes ut a tooltipbe.
    //
    // A gepi alias (`fejlesztes`) NEM megy ki a kartyara: a mappa neve mellett
    // csak zaj, es 2026-08-23-ig meg hibasan is latszott (`fejleszts`) --
    // Boss: "mi ez? es miert van hibasan a fejleszts.. ts?". Cimezni tovabbra
    // is az aliassal lehet, ezert ott van a tooltipben es a beallitasokban.
    //
    // Boss, 2026-08-23: "kell az a Fejlesztes szo oda? nem eleg a kulso
    // programozo?" -> "szerintem torold onnan azt a szot". A mappa NEVE tehat
    // nem all ki a kartyara. Az informacio nem vesz el: a teljes ut ott van a
    // nev tooltipjeben (nem foglal helyet), es a beallitas-ablakban is.
    const subFull = [e.title, e.desc].filter(Boolean).join(' · ')
    // A leiras-sor MAR CSAK akkor all ki, ha van mondanivaloja (bot-hiba).
    const sub = shortDesc(botNote)
    card.innerHTML = `
      <div class="agent-card-top">
        ${codeBridgeCards.avatar
          ? `<div class="agent-avatar"><img src="/api/code/avatar${avatarBust()}" alt=""></div>`
          : `<div class="agent-avatar avatar-mono" style="background:${monogramColor('vscode-' + e.title)}">${escapeHtml(name.replace(/^@/, '').charAt(0).toUpperCase())}</div>`}
        <div class="agent-card-info">
          <div class="agent-name" title="${escapeAttr(subFull)}">${escapeHtml(name)} <span class="federated-badge">VS Code</span></div>
          <div class="cb-external-badge" title="${escapeAttr(t('cb.card.external_note'))}">${escapeHtml(t('cb.card.external_badge'))}</div>
          ${sub ? `<div class="agent-desc" title="${escapeAttr(subFull)}">${escapeHtml(sub)}</div>` : ''}
        </div>
      </div>
      <div class="agent-card-footer">
        <span class="agent-model-badge ${escapeHtml(e.model || '')}" title="${escapeAttr(e.model ? t('cb.card.model_help') : t('cb.card.model_unknown_help'))}">${escapeHtml(e.model || t('cb.card.model_unknown'))}</span>
        <!-- Tulajdonosi kikotes, 2026-08-23: a modell-magyarazat NEM a kartyan van, hanem a
             reszletes ablak MODELL csempeje alatt (web/index.html,
             #cbTileModelNote) -- a kartyan mar eleg informacio all, ott az
             allapot ("fut"/"leallitva" + "online"/"offline") a fontos. -->
        <span class="process-indicator" title="${escapeAttr(cbRunTip())}"><span class="process-dot ${cbRunDotClass()}"></span>${escapeHtml(cbRunLabel())}</span>
        <span class="tg-status"><span class="tg-dot ${e.online ? 'connected' : 'disconnected'}"></span> ${escapeHtml(e.note)}</span>
      </div>
      <div class="agent-card-actions">
        <button class="btn-secondary btn-compact code-bridge-open-btn">${escapeHtml(t('cb.card.settings'))}</button>
        ${e.roleHolder ? `
        <button class="btn-secondary btn-compact cb-delete-btn" title="${escapeHtml(t('cb.card.delete_help'))}">${escapeHtml(t('cb.card.delete'))}</button>` : ''}
      </div>
      ${e.roleHolder ? cbTabsPickHtml(e) : ''}
      ${e.roleHolder ? cbClosedTabsHtml(e) : ''}
      ${e.roleHolder && !cbHasTabRows(e) && !cbTabsEmptyHasCtx(e) ? cbContextRowHtml(e) : ''}
      ${e.roleHolder ? roleRowHtml(e.roleHolder) : ''}`
    card.querySelector('.code-bridge-open-btn').addEventListener('click', (ev) => {
      ev.stopPropagation()
      openCodeBridgeModal()
    })
    // A jelolonegyzet ugyanoda ment, ahova az ugynok-kartyaka -- a kulonbseg
    // csak a "gazda" neve (`vscode:<projekt>`). A stopPropagation azert kell,
    // mert a kartyara kattintva kulonben kinyilna a beallitas-ablak is.
    card.querySelectorAll('.ctx-role-toggle').forEach((box) => {
      box.addEventListener('click', (ev) => ev.stopPropagation())
      box.addEventListener('change', () => saveBrokerRole(e.roleHolder, box.dataset.role, box.checked))
    })
    card.querySelectorAll('.cb-tab-row').forEach((row) => row.addEventListener('click', (ev) => ev.stopPropagation()))
    card.querySelectorAll('.cb-tab-close').forEach((btn) => {
      btn.addEventListener('click', (ev) => {
        // A gomb egy <label>-en belul all: kattintasra kulonben a radiogomb is
        // atvaltana, vagyis a bezaras MELLE at is allitana a cel-beszelgetest.
        ev.preventDefault()
        ev.stopPropagation()
        cbCloseTab(btn.dataset.session, btn.dataset.label)
      })
    })
    // A BESZELGETES MEGNYITASA. Ugyanaz az ablak, mint az ugynokoknel -- csak a
    // forras mas. A `preventDefault` itt is kell: a fo lista gombjai egy
    // <label>-en belul allnak, es kattintasra kulonben ATALLITANA a cel-fult.
    card.querySelectorAll('.cb-tab-open').forEach((btn) => {
      btn.addEventListener('click', (ev) => {
        ev.preventDefault()
        ev.stopPropagation()
        openCodeConversationModal(btn.dataset.session, btn.dataset.label)
      })
    })
    // A "tobbi beszelgetes" reszletezo kinyitasa nem nyithatja ki a
    // beallitas-ablakot is.
    card.querySelector('.cb-tabs-closed')?.addEventListener('click', (ev) => ev.stopPropagation())
    card.querySelectorAll('.cb-tab-radio').forEach((box) => {
      box.addEventListener('change', () => {
        if (box.checked) cbPickSession(e.project, e.workspacePath, box.value)
      })
    })
    card.querySelector('.ctx-role-row')?.addEventListener('click', (ev) => ev.stopPropagation())
    card.querySelector('.ctx-current')?.addEventListener('click', (ev) => ev.stopPropagation())
    card.querySelector('.cb-delete-btn')?.addEventListener('click', (ev) => { ev.stopPropagation(); cbDeleteProject(e.project) })
    // A TOMORITES ES A TORLES GOMB IS KIVEVE A KARTYAROL.
    //
    // Boss, 2026-08-26: "hat magat a torles gombot torold ki onnan. akkor minek
    // az oda?" -- majd 2026-08-27: "ez nem tomorit semmit. szar az egesz."
    //
    // A MERES, ami eldontotte. A `/clear` SEMMIT nem torol: uj, ures
    // beszelgetest nyit (a tulaj a VS Code-ban meg is latta "/clear" nevu
    // chatkent), a regi naplo sertetlenul a lemezen marad. A `/compact`
    // ezzel szemben valodi munkat vegez -- de CSAK olyan beszelgetesen, amelyik
    // NINCS nyitva a VS Code-ban: a futo ablak a sajat folyamataban tartja a
    // kontextust, oda a headless `--resume` nem szol bele.
    //
    // 2026-08-27-en a `/api/code/tabs` mind a HAROM fulre `live=true`-t adott, es
    // mind a harom PID valoban futo `claude.exe` volt (2124 / 19196 / 19964).
    // Vagyis nem volt egyetlen olyan ful sem, amelyiken a gomb dolgozni tudott
    // volna -- barmelyiket jelolte ki a tulaj, elutasitas jott. Egy gomb, ami a
    // gyakorlatban mindig nemet mond, nem gomb.
    //
    // Ami MARAD: a `cbMaintenance` fuggveny es a szovegek erintetlenek, es a
    // `/api/code/tasks` vegponton at (Telegramrol is) tovabbra is kuldheto
    // `/compact` -- csak a kartyan nem kinaljuk fel. Ha egyszer lesz mod egy
    // NYITOTT ablak vezerlesere (pl. a VS Code kiterjesztesen keresztul), akkor
    // johet vissza a gomb -- addig nem.
    card.addEventListener('click', () => openCodeBridgeModal())
    agentsGrid.insertBefore(card, addBtn)
  }
}

// A kartya alatt nyilik, mint barmelyik masik ugynok beallitasa. A poll
// csak addig fut, amig az ablak nyitva van -- zarva nincs kinek mutatni.
function openCodeBridgeModal() {
  const overlay = document.getElementById('cbOverlay')
  if (!overlay) return
  // Mint barmelyik masik ugynok-ablak: nyitaskor az Attekintes all elol.
  // Enelkul a masodik megnyitas ott folytatna, ahol az elozo abbamaradt, es a
  // "hol vagyok?" kerdes minden korben ujra feltevodne.
  if (typeof window.cbSwitchTab === 'function') window.cbSwitchTab('overview')
  openModal(overlay)
  callPageLoader('loadCodeBridgePage')
}

;(function wireCodeBridgeModal() {
  const overlay = document.getElementById('cbOverlay')
  if (!overlay) return
  const close = () => { closeModal(overlay); _cbStopPoll() }
  document.getElementById('cbModalClose')?.addEventListener('click', close)
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close() })
})()

/** Failure-proof, mint a fooderacios lekeres: egy regi backend 404-je sem
 *  boritja fel a Csapat lapot, csak nem lesz kod-hid kartya. */
async function loadCodeBridgeCards() {
  const [projects, health] = await Promise.all([
    fetch('/api/code/projects').then((r) => (r.ok ? r.json() : null)).catch(() => null),
    fetch('/api/code/health').then((r) => (r.ok ? r.json() : null)).catch(() => null),
  ])
  if (!health) { codeBridgeCards = { state: 'absent', projects: [], workerOnline: false, avatar: false, queued: 0, running: 0, candidates: { free: 0, excluded: 0 } } ; return }
  codeBridgeCards = {
    state: health.enabled === false ? 'disabled' : 'on',
    projects: (projects && Array.isArray(projects.projects)) ? projects.projects : [],
    workerOnline: Boolean(health.workerOnline),
    // Regi backend nem kuldi -> `false` -> monogram. Ez a helyes visszaeses:
    // nem talalunk ki ikont, amirol nem tudjuk, hogy letezik-e.
    avatar: Boolean(health.avatar),
    queued: Number(health.queued) || 0,
    running: Number(health.running) || 0,
    // A MENTETT ki/be kapcsolas. Regi backend nem kuldi -> `null`, es akkor a
    // kartya nem allit semmit rola (a hallgatas jobb, mint egy kitalalt allapot).
    savedEnabled: typeof health.savedEnabled === 'boolean' ? health.savedEnabled : null,
    // Regi backend nem kuldi -- olyankor a kartya a korabbi szoveget mondja.
    candidates: {
      free: Number(health.candidates && health.candidates.free) || 0,
      excluded: Number(health.candidates && health.candidates.excluded) || 0,
      dismissed: Number(health.candidates && health.candidates.dismissed) || 0,
    },
    // A kartya NEVE a kod-bot Telegram-neve, mint minden mas ugynok-kartyan.
    // Regi backend nem kuldi -> null, es marad a projekt-alias.
    bot: health.codeBot || null,
    // Enelkul az ures ful-lista nemakent latszana: a felulet nem tudna
    // megkulonboztetni a "nincs nyitott beszelgetes"-t a "nem latunk oda"-tol.
    tabsReason: (projects && typeof projects.tabsReason === 'string') ? projects.tabsReason : null,
  }
}

let federatedPeerStatus = []

// System/plumbing agent names never shown as message targets.
const FEDERATED_HIDDEN_AGENTS = new Set(['heartbeat', 'telegram-coordinator', 'channel-coordinator'])

function federatedAgentEntries() {
  const out = []
  for (const peer of federatedPeerStatus) {
    const manifest = peer && peer.manifest
    if (!manifest || !Array.isArray(manifest.agents)) continue
    for (const a of manifest.agents) {
      if (!a || typeof a.id !== 'string' || FEDERATED_HIDDEN_AGENTS.has(a.id.split('/').pop())) continue
      out.push({ peer: peer.id, peerState: peer.state, qualified: `${peer.id}/${a.id}`, displayName: a.displayName || a.id, model: a.model || '' })
    }
  }
  return out
}

function renderFederatedAgentCards(agentsGrid, addBtn) {
  for (const fa of federatedAgentEntries()) {
    const card = document.createElement('div')
    card.className = 'agent-card federated-agent-card'
    const reachable = fa.peerState === 'ok'
    // SECURITY: every manifest-derived string is peer-controlled. Text nodes
    // go through escapeHtml; NOTHING peer-controlled may land in an attribute
    // (escapeHtml does not encode quotes). The model badge is a plain text
    // span WITHOUT a model-derived class.
    // monogramColor returns one of our own fixed hex values, so nothing
    // peer-controlled reaches the style attribute.
    card.innerHTML = `
      <div class="agent-card-top">
        <div class="agent-avatar avatar-mono" style="background:${monogramColor(fa.qualified)}">${escapeHtml(fa.displayName.charAt(0).toUpperCase())}</div>
        <div class="agent-card-info">
          <div class="agent-name">${escapeHtml(fa.displayName)} <span class="federated-badge">${t('federation.badge', { peer: fa.peer })}</span></div>
          <div class="agent-desc" title="${escapeAttr(fa.qualified)}">${escapeHtml(shortDesc(fa.qualified))}</div>
        </div>
      </div>
      <div class="agent-card-footer">
        <span class="agent-model-badge">${escapeHtml(fa.model)}</span>
        <span class="tg-status"><span class="tg-dot ${reachable ? 'connected' : 'disconnected'}"></span> ${reachable ? t('federation.peer_state.ok') : t('federation.peer_state.' + (fa.peerState || 'unknown'))}</span>
      </div>
      <div class="agent-card-actions">
        <button class="btn-secondary btn-compact federated-message-btn">${t('federation.btn.message')}</button>
      </div>`
    card.querySelector('.federated-message-btn').addEventListener('click', (e) => {
      e.stopPropagation()
      openFederatedThread(fa.qualified)
    })
    agentsGrid.insertBefore(card, addBtn)
  }
}

function openFederatedThread(qualifiedId) {
  chatSelectedAgent = qualifiedId
  if (location.hash === '#messages') switchPage('messages')
  else location.hash = 'messages'
}

// === Agent Detail ===
async function openAgentDetail(agentName) {
  if (agentName === mainAgentId()) {
    return openMarveenDetail()
  }

  try {
    const res = await fetch(`/api/agents/${encodeURIComponent(agentName)}`)
    if (!res.ok) throw new Error('Not found')
    currentAgent = await res.json()
  } catch (err) {
    showToast(t('agents.toast.load_failed'))
    return
  }

  const detailLabel = currentAgent.displayName || currentAgent.name

  // Title
  document.getElementById('agentDetailTitle').textContent = detailLabel

  // Overview tab
  const detailHasImg = currentAgent.hasImage || currentAgent.hasAvatar
  const avatar = document.getElementById('agentDetailAvatar')
  avatar.className = detailHasImg ? 'detail-avatar' : 'detail-avatar avatar-mono'
  avatar.style.background = detailHasImg ? '' : monogramColor(currentAgent.name)
  avatar.innerHTML = detailHasImg
    ? `<img src="/api/agents/${encodeURIComponent(currentAgent.name)}/avatar" alt="${escapeHtml(detailLabel)}">`
    : detailLabel.charAt(0).toUpperCase()
  document.getElementById('agentDetailName').textContent = detailLabel
  document.getElementById('agentDetailDesc').textContent = currentAgent.description || ''
  document.getElementById('agentDetailModel').textContent = currentAgent.activeModel || currentAgent.model || 'inherit'
  document.getElementById('agentDetailModelRestarting').hidden = true
  document.getElementById('agentNameEditBtn').hidden = false
  document.getElementById('agentDetailNameEdit').hidden = true
  document.getElementById('agentDetailNameRow').hidden = false

  const chConnected = agentIsConnected(currentAgent)
  document.getElementById('agentDetailChStatus').innerHTML = `<span class="tg-status"><span class="tg-dot ${chConnected ? 'connected' : 'disconnected'}"></span>${chConnected ? t('agents.channel.connected') : t('agents.channel.disconnected')}</span>`

  // Settings tab - load Ollama + DeepSeek models then set value
  loadAvailableModels()
  loadOllamaModels().then(() => {
    const sel = document.getElementById('editAgentModel')
    const mv = currentAgent.activeModel || currentAgent.model || 'claude-opus-4-8[1m]'
    // The model <select> is one shared element reused per agent. A manual
    // OpenRouter id (or openrouter-auto:tier) may not be among the static/auto
    // options, so setting .value would silently show nothing. Inject THIS
    // agent's model as a selectable option (cleaning any stale injected ones
    // first) so every agent always displays its own model, per-agent.
    Array.from(sel.querySelectorAll('option.dynamic-model-opt')).forEach(o => o.remove())
    if (!Array.from(sel.options).some(o => o.value === mv)) {
      const opt = document.createElement('option')
      opt.value = mv
      opt.className = 'dynamic-model-opt'
      opt.textContent = mv.startsWith('openrouter-auto:') ? `🔀 ${mv}` : `🔀 ${mv}`
      sel.appendChild(opt)
    }
    sel.value = mv
  })
  populateProfileSelect(
    document.getElementById('editAgentProfile'),
    document.getElementById('editAgentProfileDesc'),
    currentAgent.securityProfile || 'default',
  )
  // The main agent's Claude login is managed via channels.sh, not the per-agent
  // config path, so plan selection does not apply to it. Hide the whole group.
  const planGroup = document.getElementById('claudePlanGroup')
  if (planGroup) planGroup.hidden = currentAgent.role === 'main'
  populatePlanSelect(
    document.getElementById('editAgentPlan'),
    document.getElementById('editAgentPlanDesc'),
    currentAgent.claudePlan || '',
  )
  renderAgentLogoutSetting(currentAgent)
  renderTeamEditor(currentAgent, agents)
  updateAuthModeUI(currentAgent.authMode || 'shared', currentAgent.hasApiKey || false)
  const memIsoToggle = document.getElementById('memoryIsolationToggle')
  if (memIsoToggle) memIsoToggle.checked = currentAgent.memoryIsolation === true
  loadVoiceConfig(currentAgent.name)
  document.getElementById('editClaudeMd').value = currentAgent.claudeMd || currentAgent.content || ''
  document.getElementById('editSoulMd').value = currentAgent.soulMd || ''
  document.getElementById('editMcpJson').value = currentAgent.mcpJson || ''

  // Auto-restart settings + live context size
  setupAutoRestartUI(currentAgent)

  // Telegram tab
  updateChannelTab(currentAgent)

  // Skills tab
  await loadSkills(currentAgent.name)

  // Process control
  updateProcessControl(currentAgent)

  // Channels restart button is Marveen-only -- hide on normal agents.
  document.getElementById('marveenRestartBtn').hidden = true

  // Restore editable Settings (Marveen detail flips this to read-only).
  applyMarveenReadonlyMode(false)

  // Delete button (restore visibility for normal agents)
  document.getElementById('deleteAgentBtn').style.display = ''
  document.getElementById('deleteAgentBtn').onclick = async () => {
    if (!confirm(t('agents.confirm.delete', { name: currentAgent.name }))) return
    try {
      await fetch(`/api/agents/${encodeURIComponent(currentAgent.name)}`, { method: 'DELETE' })
      closeModal(agentDetailOverlay)
      showToast(t('agents.toast.deleted'))
      loadAgents()
    } catch (err) {
      showToast(t('common.error_delete'))
    }
  }

  // Export button: download a portable .tar.gz bundle of this agent. Offers to
  // include channel tokens (off by default -- the safe-to-share variant).
  // The download goes through the auth-wrapped fetch (the global fetch shim
  // injects the Bearer header) and is turned into a Blob download, rather than
  // a plain navigation -- a window.location download cannot carry the
  // Authorization header and the API would 401 it.
  document.getElementById('exportAgentBtn').onclick = async () => {
    if (!currentAgent) return
    const withSecrets = confirm(
      'Belevegyük a titkokat (channel bot token, párosítási állapot)?\n\n' +
      'OK = igen, csak saját gépek közötti átvitelhez.\n' +
      'Mégse = nem, biztonságosan megosztható (csak identitás + viselkedés).'
    )
    const name = currentAgent.name
    const url = `/api/agents/${encodeURIComponent(name)}/export${withSecrets ? '?secrets=1' : ''}`
    try {
      const res = await fetch(url)
      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        showToast(data.error || 'Hiba az exportálás során')
        return
      }
      const blob = await res.blob()
      const objectUrl = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = objectUrl
      a.download = `marveen-agent-${name}.tar.gz`
      document.body.appendChild(a)
      a.click()
      a.remove()
      URL.revokeObjectURL(objectUrl)
      showToast(`Ügynök exportálva${withSecrets ? ' (titkokkal)' : ''}`)
    } catch {
      showToast('Hiba az exportálás során')
    }
  }

  // Reset to first tab, hide avatar gallery
  document.getElementById('detailAvatarGallery').hidden = true
  switchAgentTab('overview')
  openModal(agentDetailOverlay)
}

// === Detail avatar gallery ===
function populateDetailAvatarGrid() {
  const grid = document.getElementById('detailAvatarGrid')
  grid.innerHTML = ''
  for (const avatar of AVATARS) {
    const item = document.createElement('div')
    item.className = 'avatar-grid-item'
    item.dataset.avatar = avatar
    item.innerHTML = `<img src="/avatars/${avatar}" alt="${avatar.replace(/^\d+_/, '').replace('.png', '')}">`
    item.addEventListener('click', async () => {
      if (!currentAgent) return
      grid.querySelectorAll('.avatar-grid-item').forEach(i => i.classList.remove('selected'))
      item.classList.add('selected')
      try {
        const res = await fetch(`/api/agents/${encodeURIComponent(currentAgent.name)}/avatar`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ galleryAvatar: avatar }),
        })
        if (!res.ok) throw new Error()
        showToast(t('agents.toast.avatar_updated'))
        bumpAvatarEpoch()
        // Update the detail avatar display
        document.getElementById('agentDetailAvatar').innerHTML = `<img src="/api/agents/${encodeURIComponent(currentAgent.name)}/avatar${avatarBust()}" alt="">`
        document.getElementById('detailAvatarGallery').hidden = true
        loadAgents()
      } catch {
        showToast(t('agents.toast.avatar_error'))
      }
    })
    grid.appendChild(item)
  }
}

function showAgentNameEdit() {
  document.getElementById('agentDetailNameRow').hidden = true
  const editRow = document.getElementById('agentDetailNameEdit')
  editRow.hidden = false
  const input = document.getElementById('agentNameEditInput')
  input.value = (currentAgent && (currentAgent.displayName || currentAgent.name)) || ''
  input.focus()
  input.select()
}

function hideAgentNameEdit() {
  document.getElementById('agentDetailNameEdit').hidden = true
  document.getElementById('agentDetailNameRow').hidden = false
}

async function saveAgentNameEdit() {
  if (!currentAgent || !currentAgent.name) return
  const input = document.getElementById('agentNameEditInput')
  const newName = input.value.trim()
  if (!newName) { showToast(t('agents.detail.name_empty_error')); return }

  const saveBtn = document.getElementById('agentNameSaveBtn')
  saveBtn.disabled = true
  try {
    const res = await fetch(`/api/agents/${encodeURIComponent(currentAgent.name)}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ displayName: newName }),
    })
    if (!res.ok) {
      const err = await res.json().catch(() => ({}))
      throw new Error(err.error || t('agents.detail.name_save_error'))
    }
    currentAgent.displayName = newName
    document.getElementById('agentDetailTitle').textContent = newName
    document.getElementById('agentDetailName').textContent = newName
    hideAgentNameEdit()
    showToast(t('agents.detail.name_saved'))
    loadAgents()
  } catch (err) {
    showToast(err.message || t('agents.detail.name_save_error'))
  } finally {
    saveBtn.disabled = false
  }
}

document.getElementById('agentNameEditBtn').addEventListener('click', showAgentNameEdit)
document.getElementById('agentNameCancelBtn').addEventListener('click', hideAgentNameEdit)
document.getElementById('agentNameSaveBtn').addEventListener('click', saveAgentNameEdit)
document.getElementById('agentNameEditInput').addEventListener('keydown', (e) => {
  if (e.key === 'Enter') saveAgentNameEdit()
  else if (e.key === 'Escape') hideAgentNameEdit()
})

document.getElementById('avatarChangeBtn').addEventListener('click', () => {
  const gallery = document.getElementById('detailAvatarGallery')
  gallery.hidden = !gallery.hidden
  if (!gallery.hidden) {
    const isMarveen = currentAgent && currentAgent.role === 'main'
    const avatarEndpoint = isMarveen ? '/api/marveen/avatar' : `/api/agents/${encodeURIComponent(currentAgent.name)}/avatar`

    const grid = document.getElementById('detailAvatarGrid')
    grid.innerHTML = ''
    for (const avatar of AVATARS) {
      const item = document.createElement('div')
      item.className = 'avatar-grid-item'
      item.innerHTML = `<img src="/avatars/${avatar}" alt="${avatar.replace(/^\d+_/, '').replace('.png', '')}">`
      item.addEventListener('click', async () => {
        try {
          const res = await fetch(avatarEndpoint, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ galleryAvatar: avatar }),
          })
          if (!res.ok) throw new Error()
          showToast(t('agents.toast.avatar_updated'))
          bumpAvatarEpoch()
          const imgUrl = isMarveen ? `/api/marveen/avatar${avatarBust()}` : `/api/agents/${encodeURIComponent(currentAgent.name)}/avatar${avatarBust()}`
          document.getElementById('agentDetailAvatar').innerHTML = `<img src="${imgUrl}" alt="">`
          gallery.hidden = true
          loadAgents()
        } catch {
          showToast(t('agents.toast.avatar_error'))
        }
      })
      grid.appendChild(item)
    }
  }
})

// === Avatar file upload ===
;(() => {
  const zone = document.getElementById('avatarUploadZone')
  const fileInput = document.getElementById('avatarFileInput')
  const content = document.getElementById('avatarUploadContent')
  const preview = document.getElementById('avatarUploadPreview')
  const previewImg = document.getElementById('avatarPreviewImg')
  const clearBtn = document.getElementById('avatarPreviewClear')
  const MAX_SIZE = 1024 * 1024

  zone.addEventListener('click', (e) => {
    if (e.target === clearBtn || clearBtn.contains(e.target)) return
    fileInput.click()
  })
  zone.addEventListener('dragover', (e) => { e.preventDefault(); zone.classList.add('drag-over') })
  zone.addEventListener('dragleave', () => zone.classList.remove('drag-over'))
  zone.addEventListener('drop', (e) => {
    e.preventDefault()
    zone.classList.remove('drag-over')
    const file = e.dataTransfer.files[0]
    if (file) handleAvatarFile(file)
  })
  fileInput.addEventListener('change', () => {
    if (fileInput.files[0]) handleAvatarFile(fileInput.files[0])
  })
  clearBtn.addEventListener('click', (e) => {
    e.stopPropagation()
    resetAvatarUpload()
  })

  function resetAvatarUpload() {
    fileInput.value = ''
    content.hidden = false
    preview.hidden = true
  }

  async function handleAvatarFile(file) {
    if (!file.type.match(/^image\/(png|jpe?g|webp)$/)) {
      showToast(t('agents.toast.avatar_format'))
      return
    }
    if (file.size > MAX_SIZE) {
      showToast(t('agents.toast.avatar_size'))
      return
    }
    previewImg.src = URL.createObjectURL(file)
    content.hidden = true
    preview.hidden = false
    await uploadAvatarFile(file)
  }

  async function uploadAvatarFile(file) {
    if (!currentAgent) return
    const isMarveen = currentAgent.role === 'main'
    const endpoint = isMarveen ? '/api/marveen/avatar' : `/api/agents/${encodeURIComponent(currentAgent.name)}/avatar`
    const form = new FormData()
    form.append('avatar', file, file.name)
    try {
      const res = await fetch(endpoint, { method: 'POST', body: form })
      if (!res.ok) throw new Error()
      showToast(t('agents.toast.avatar_uploaded'))
      bumpAvatarEpoch()
      const imgUrl = isMarveen ? `/api/marveen/avatar${avatarBust()}` : `/api/agents/${encodeURIComponent(currentAgent.name)}/avatar${avatarBust()}`
      document.getElementById('agentDetailAvatar').innerHTML = `<img src="${imgUrl}" alt="">`
      document.getElementById('detailAvatarGallery').hidden = true
      resetAvatarUpload()
      loadAgents()
    } catch {
      showToast(t('common.error_save'))
      resetAvatarUpload()
    }
  }
})()

// === Create-wizard avatar upload ===
// Mirrors the detail-modal uploader, but the agent does not exist yet, so the
// file is held in `selectedAvatarFile` and POSTed after creation (see the
// wizard create flow). Hoisted so populateAvatarGrid()/resetWizard() can reset.
function resetCreateAvatarUpload() {
  const fileInput = document.getElementById('createAvatarFileInput')
  const content = document.getElementById('createAvatarUploadContent')
  const preview = document.getElementById('createAvatarUploadPreview')
  if (!fileInput || !content || !preview) return
  fileInput.value = ''
  content.hidden = false
  preview.hidden = true
}
;(() => {
  const zone = document.getElementById('createAvatarUploadZone')
  if (!zone) return
  const fileInput = document.getElementById('createAvatarFileInput')
  const content = document.getElementById('createAvatarUploadContent')
  const preview = document.getElementById('createAvatarUploadPreview')
  const previewImg = document.getElementById('createAvatarPreviewImg')
  const clearBtn = document.getElementById('createAvatarPreviewClear')
  const MAX_SIZE = 1024 * 1024

  zone.addEventListener('click', (e) => {
    if (e.target === clearBtn || clearBtn.contains(e.target)) return
    fileInput.click()
  })
  zone.addEventListener('dragover', (e) => { e.preventDefault(); zone.classList.add('drag-over') })
  zone.addEventListener('dragleave', () => zone.classList.remove('drag-over'))
  zone.addEventListener('drop', (e) => {
    e.preventDefault()
    zone.classList.remove('drag-over')
    const file = e.dataTransfer.files[0]
    if (file) handleCreateAvatarFile(file)
  })
  fileInput.addEventListener('change', () => {
    if (fileInput.files[0]) handleCreateAvatarFile(fileInput.files[0])
  })
  clearBtn.addEventListener('click', (e) => {
    e.stopPropagation()
    selectedAvatarFile = null
    resetCreateAvatarUpload()
  })

  function handleCreateAvatarFile(file) {
    if (!file.type.match(/^image\/(png|jpe?g|webp)$/)) {
      showToast(t('agents.toast.avatar_format'))
      return
    }
    if (file.size > MAX_SIZE) {
      showToast(t('agents.toast.avatar_size'))
      return
    }
    // Custom upload and gallery pick are mutually exclusive.
    selectedAvatar = null
    document.querySelectorAll('#avatarGrid .avatar-grid-item').forEach(i => i.classList.remove('selected'))
    selectedAvatarFile = file
    previewImg.src = URL.createObjectURL(file)
    content.hidden = true
    preview.hidden = false
  }
})()

// === Process control ===
function updateProcessControl(agent) {
  const running = agent.running || false
  const dot = document.getElementById('processDot')
  const label = document.getElementById('processLabel')
  const uptime = document.getElementById('processUptime')
  const startBtn = document.getElementById('agentStartBtn')
  const stopBtn = document.getElementById('agentStopBtn')

  dot.className = 'process-dot ' + (running ? 'running' : 'stopped')
  label.textContent = running ? t('agents.status.running') : t('agents.status.stopped')
  startBtn.hidden = running
  stopBtn.hidden = !running

  if (running && agent.session) {
    uptime.textContent = `tmux: ${agent.session}`
  } else {
    uptime.textContent = ''
  }
}

document.getElementById('marveenRestartBtn').addEventListener('click', async () => {
  if (!confirm(t('agents.confirm.hard_restart'))) return
  const btn = document.getElementById('marveenRestartBtn')
  btn.disabled = true
  try {
    const res = await fetch('/api/marveen/restart', { method: 'POST' })
    if (!res.ok) {
      const err = await res.json().catch(() => ({}))
      throw new Error(err.error || t('agents.toast.restart_failed'))
    }
    showToast(t('agents.toast.marveen_restarted'))
  } catch (err) {
    showToast(`Hiba: ${err.message}`)
  } finally {
    btn.disabled = false
  }
})

document.getElementById('agentStartBtn').addEventListener('click', async () => {
  if (!currentAgent) return
  const btn = document.getElementById('agentStartBtn')
  btn.disabled = true
  btn.querySelector('.btn-text').hidden = true
  btn.querySelector('.btn-loading').hidden = false

  try {
    const res = await fetch(`/api/agents/${encodeURIComponent(currentAgent.name)}/start`, { method: 'POST' })
    if (!res.ok) {
      const err = await res.json()
      throw new Error(err.error || t('agents.toast.start_failed'))
    }
    showToast(t('agents.toast.started'))
    // Refresh
    const detailRes = await fetch(`/api/agents/${encodeURIComponent(currentAgent.name)}`)
    if (detailRes.ok) {
      currentAgent = await detailRes.json()
      updateProcessControl(currentAgent)
    }
    loadAgents()
  } catch (err) {
    showToast(`Hiba: ${err.message}`)
  } finally {
    btn.disabled = false
    btn.querySelector('.btn-text').hidden = false
    btn.querySelector('.btn-loading').hidden = true
  }
})

document.getElementById('agentStopBtn').addEventListener('click', async () => {
  if (!currentAgent) return
  if (!confirm(t('agents.confirm.stop'))) return

  try {
    const res = await fetch(`/api/agents/${encodeURIComponent(currentAgent.name)}/stop`, { method: 'POST' })
    if (!res.ok) {
      const err = await res.json()
      throw new Error(err.error || t('agents.toast.stop_failed'))
    }
    showToast(t('agents.toast.stopped'))
    const detailRes = await fetch(`/api/agents/${encodeURIComponent(currentAgent.name)}`)
    if (detailRes.ok) {
      currentAgent = await detailRes.json()
      updateProcessControl(currentAgent)
    }
    loadAgents()
  } catch (err) {
    showToast(`Hiba: ${err.message}`)
  }
})

