// Default TRUE: if we never successfully read /api/connectors/status
// (endpoint missing on older backends, network error, non-2xx response)
// the safe assumption is that the cache has not populated yet. That
// way an empty list renders as "warming" rather than the misleading
// "no connectors" the F2 round-3 fix was meant to eliminate.
let connectorCacheWarming = true
let connectorCacheError = ''

async function loadConnectors() {
  connectorGrid.innerHTML = `<div class="connector-loading"><span class="spinner"></span> ${t('connectors.loading')}</div>`
  connectorStats.innerHTML = ''
  // Reset pessimistic state at the top of every load. Only an authoritative
  // positive signal (status endpoint reports cacheLastRefreshed > 0) flips
  // it to false, so a later status-fetch failure cannot leave a stale
  // `false` that regresses into "no connectors" again.
  connectorCacheWarming = true
  connectorCacheError = ''
  try {
    // Fetch both in parallel: the list itself and a lightweight status
    // readout that tells us whether the server-side cache has ever run.
    // Without the status, a cold-start hit on the page would render
    // "Nincsenek MCP connectorok" -- contradicting the info-box that
    // says "A lista a dashboard indulasakor toltodik be".
    const [listRes, statusRes] = await Promise.all([
      fetch('/api/connectors'),
      fetch('/api/connectors/status').catch(() => null),
    ])
    connectors = await listRes.json()
    if (statusRes && statusRes.ok) {
      const s = await statusRes.json().catch(() => ({}))
      if (s && s.cacheLastRefreshed > 0) connectorCacheWarming = false
      if (s && s.cacheError) connectorCacheError = String(s.cacheError)
    }
    renderConnectors()
    loadExternalPaths()
    loadGitHubRepos()
    loadVault()
  } catch (err) {
    console.error('Connector betöltés hiba:', err)
    connectorGrid.innerHTML = `<div class="connector-loading">${t('connectors.load_error')}</div>`
  }
}

// Built-in MCPs: features that live inside the Claude Code binary or
// app rather than as a registered MCP server. They cannot be detected
// via `claude mcp list`, so the "Aktív / Kikapcsolva" label used to
// always read "Kikapcsolva" regardless of the real state. Replace the
// misleading state badge with a "Részletek" button that opens a modal
// carrying the real enable instructions (which previously hid inside
// a `title` tooltip the user had to hover to discover).
const BUILTIN_MCPS = [
  {
    name: 'computer-use',
    label: 'Computer Use',
    desc: () => t('connectors.builtin.computer_use'),
    get detailHtml() { return t('connectors.builtin.computer_use_html') },
  },
  {
    name: 'chrome',
    label: 'Claude in Chrome',
    desc: () => t('connectors.builtin.chrome'),
    get detailHtml() { return t('connectors.builtin.chrome_html') },
  },
]

function openBuiltinDetail(item) {
  const overlay = document.getElementById('builtinDetailOverlay')
  if (!overlay) return
  document.getElementById('builtinDetailTitle').textContent = item.label
  document.getElementById('builtinDetailDesc').textContent = typeof item.desc === 'function' ? item.desc() : item.desc
  // Static strings only. Never interpolate user or server input here
  // without passing it through escapeHtml first -- detailHtml is a
  // raw HTML sink.
  document.getElementById('builtinDetailBody').innerHTML = item.detailHtml
  openModal(overlay)
  // Move focus into the dialog so keyboard users land inside the new
  // surface instead of keeping the Részletek button focused behind
  // the overlay. Same pattern the other modals in this file skip, but
  // cheap to add for accessibility.
  const closeBtn = document.getElementById('builtinDetailClose')
  if (closeBtn) setTimeout(() => closeBtn.focus(), 50)
}

// Wire close paths for the built-in detail modal once per load. Guarded
// so a future refactor that moves the script tag above the modal HTML
// (e.g. deferred <head> load) does not fire a silent null-ref here.
function wireBuiltinDetailModal() {
  const overlay = document.getElementById('builtinDetailOverlay')
  const closeBtn = document.getElementById('builtinDetailClose')
  if (!overlay || !closeBtn) return
  closeBtn.addEventListener('click', () => closeModal(overlay))
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closeModal(overlay)
  })
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', wireBuiltinDetailModal, { once: true })
} else {
  wireBuiltinDetailModal()
}

function renderConnectors() {
  // Detach panels that live inside connectorGrid before innerHTML wipes them
  const _extPathsPanel = document.getElementById('externalPathsSection')
  if (_extPathsPanel) _extPathsPanel.remove()

  // Stats
  if (connectors.length === 0 && connectorCacheWarming) {
    connectorStats.innerHTML = ''
  } else {
    const connected = connectors.filter(c => c.status === 'connected').length
    // 'configured' = declared in a .mcp.json (not health-checked, the backend
    // never spawns them). These are known-good, not broken -- surface them in a
    // positive count so file-defined servers (e.g. gmail-egov) do not look
    // un-ready just because they never went through the claude mcp list cache.
    const configured = connectors.filter(c => c.status === 'configured').length
    const needsAuth = connectors.filter(c => c.status === 'needs_auth').length
    const failed = connectors.filter(c => c.status === 'failed').length
    connectorStats.innerHTML = `
      <div class="stat-card"><div class="stat-value">${connectors.length}</div><div class="stat-label">${t('connectors.stat.total')}</div></div>
      <div class="stat-card"><div class="stat-value" style="color:var(--success)">${connected}</div><div class="stat-label">${t('connectors.stat.active')}</div></div>
      ${configured ? `<div class="stat-card"><div class="stat-value" style="color:var(--info)">${configured}</div><div class="stat-label">${t('connectors.stat.configured')}</div></div>` : ''}
      ${needsAuth ? `<div class="stat-card"><div class="stat-value" style="color:var(--accent)">${needsAuth}</div><div class="stat-label">${t('connectors.stat.needs_auth')}</div></div>` : ''}
      ${failed ? `<div class="stat-card"><div class="stat-value" style="color:var(--danger)">${failed}</div><div class="stat-label">${t('connectors.stat.failed')}</div></div>` : ''}
    `
  }

  connectorGrid.innerHTML = ''
  const hasClaudeAiEntries = connectors.some(c => c.source === 'claude.ai')
  if (connectors.length > 0 && !connectorCacheWarming && connectorCacheError && hasClaudeAiEntries) {
    const banner = document.createElement('div')
    banner.className = 'connector-stale-banner'
    banner.innerHTML = t('connectors.stale_banner', { msg: escapeHtml(connectorCacheError) })
    connectorGrid.appendChild(banner)
  }
  if (connectors.length === 0 && !BUILTIN_MCPS.length) {
    if (connectorCacheWarming && connectorCacheError) {
      connectorGrid.innerHTML = `<div class="connector-loading">${t('connectors.mcp_load_failed', { msg: escapeHtml(connectorCacheError) })}</div>`
    } else if (connectorCacheWarming) {
      connectorGrid.innerHTML = `<div class="connector-loading">${t('connectors.mcp_not_loaded')}</div>`
    } else {
      connectorGrid.innerHTML = `<div class="connector-loading">${t('connectors.no_mcps')}</div>`
    }
    return
  }

  // Group by scope
  const groups = new Map()
  for (const c of connectors) {
    const scope = c.scope || 'global'
    if (!groups.has(scope)) groups.set(scope, [])
    groups.get(scope).push(c)
  }

  const globalScopes = ['global', 'plugin']
  const agentScopes = []
  const internalProjectScopes = []
  const externalProjectScopes = []
  for (const scope of groups.keys()) {
    if (scope.startsWith('agent:')) agentScopes.push(scope)
    else if (scope.startsWith('project:external/')) externalProjectScopes.push(scope)
    else if (scope.startsWith('project:')) internalProjectScopes.push(scope)
    else if (!globalScopes.includes(scope)) globalScopes.push(scope)
  }
  agentScopes.sort()
  internalProjectScopes.sort()
  externalProjectScopes.sort()

  const sourceLabels = {
    'claude.ai': 'claude.ai',
    'plugin': 'plugin',
    'local-user': 'local (user)',
    'local-project': 'local (project)',
    'local': 'local',
    'agent': 'agent',
    'agent-project': 'project',
    'external-project': 'external',
  }

  function renderCard(c, container) {
    const card = document.createElement('div')
    card.className = 'connector-card'
    const sourceTag = c.source ? `<span class="connector-source-badge">${escapeHtml(sourceLabels[c.source] || c.source)}</span>` : ''
    const readOnly = c.source === 'claude.ai'
    if (readOnly) card.classList.add('connector-card-readonly')
    const readonlyHint = readOnly ? `<div class="connector-readonly-hint">${t('connectors.readonly_hint')}</div>` : ''
    card.innerHTML = `
      <div class="connector-status-dot ${c.status}"></div>
      <div class="connector-info">
        <div class="connector-name">${escapeHtml(c.name)} ${sourceTag}</div>
        <div class="connector-endpoint">${escapeHtml(c.endpoint || '')}</div>
        ${readonlyHint}
      </div>
      <span class="connector-type-badge ${c.type}">${c.type}</span>
    `
    if (!readOnly) card.addEventListener('click', () => openConnectorDetail(c))
    container.appendChild(card)
  }

  function renderCollapsible(label, icon, items, container) {
    const section = document.createElement('div')
    section.className = 'connector-scope-section'
    const header = document.createElement('div')
    header.className = 'connector-scope-header collapsible'
    header.innerHTML = `<span class="connector-scope-toggle">▶</span> ${icon} ${escapeHtml(label)} <span class="connector-scope-count">${items.length}</span>`
    header.addEventListener('click', () => {
      const grid = section.querySelector('.connector-scope-grid')
      const toggle = header.querySelector('.connector-scope-toggle')
      if (grid.hidden) { grid.hidden = false; toggle.textContent = '▼' }
      else { grid.hidden = true; toggle.textContent = '▶' }
    })
    section.appendChild(header)
    const grid = document.createElement('div')
    grid.className = 'connector-scope-grid'
    grid.hidden = true
    for (const c of items) renderCard(c, grid)
    section.appendChild(grid)
    container.appendChild(section)
  }

  // === Claude globális ===
  const globalHeading = document.createElement('div')
  globalHeading.className = 'connector-group-heading'
  globalHeading.textContent = t('connectors.heading.global')
  connectorGrid.appendChild(globalHeading)

  const builtinGrid = document.createElement('div')
  builtinGrid.className = 'connector-builtin-grid'
  for (const b of BUILTIN_MCPS) {
    const div = document.createElement('div')
    div.className = 'connector-builtin'
    div.innerHTML = `
      <div class="connector-status-dot unknown" title="${t('connectors.tooltip.auto_detect')}"></div>
      <div class="connector-builtin-name">${escapeHtml(b.label)}<br><span style="font-size:11px;color:var(--text-muted);font-weight:400">${escapeHtml(typeof b.desc === 'function' ? b.desc() : b.desc)}</span></div>
      <button type="button" class="connector-builtin-action btn-link" data-builtin="${escapeHtml(b.name)}">${t('connectors.builtin.details')}</button>
    `
    const btn = div.querySelector('button[data-builtin]')
    if (btn) btn.addEventListener('click', () => openBuiltinDetail(b))
    builtinGrid.appendChild(div)
  }
  connectorGrid.appendChild(builtinGrid)

  const globalGrid = document.createElement('div')
  globalGrid.className = 'connector-scope-grid'
  for (const scope of globalScopes) {
    for (const c of (groups.get(scope) || [])) renderCard(c, globalGrid)
  }
  if (globalGrid.children.length > 0) connectorGrid.appendChild(globalGrid)

  // === Ügynökök ===
  if (agentScopes.length > 0) {
    const agentHeading = document.createElement('div')
    agentHeading.className = 'connector-group-heading'
    agentHeading.textContent = t('connectors.heading.agents')
    connectorGrid.appendChild(agentHeading)

    for (const ag of agentScopes) {
      const agentName = ag.slice('agent:'.length)
      renderCollapsible(agentName, '🤖', groups.get(ag), connectorGrid)
    }
  }

  // === Projektek (belső) ===
  if (internalProjectScopes.length > 0) {
    const projectHeading = document.createElement('div')
    projectHeading.className = 'connector-group-heading'
    projectHeading.textContent = t('connectors.heading.projects')
    connectorGrid.appendChild(projectHeading)

    for (const ps of internalProjectScopes) {
      const parts = ps.slice('project:'.length).split('/')
      const projLabel = parts[parts.length - 1]
      renderCollapsible(projLabel, '📁', groups.get(ps), connectorGrid)
    }
  }

  // === Külső projektek ===
  if (externalProjectScopes.length > 0 || _extPathsPanel) {
    const extHeading = document.createElement('div')
    extHeading.className = 'connector-group-heading'
    extHeading.textContent = t('connectors.heading.external')
    connectorGrid.appendChild(extHeading)

    if (_extPathsPanel) connectorGrid.appendChild(_extPathsPanel)

    for (const ps of externalProjectScopes) {
      const projLabel = ps.slice('project:external/'.length)
      renderCollapsible(projLabel, '📂', groups.get(ps), connectorGrid)
    }
  }
}

// --- GitHub repo management ---
async function loadGitHubRepos() {
  try {
    const res = await fetch('/api/connectors/github-repos')
    const data = await res.json()
    const repos = data.repos || []
    document.getElementById('githubRepoCount').textContent = String(repos.length)
    const list = document.getElementById('githubRepoList')
    list.innerHTML = ''
    for (const r of repos) {
      const item = document.createElement('div')
      item.className = 'connector-external-item github-repo-item'
      const date = new Date(r.installedAt).toLocaleDateString('hu-HU')
      item.innerHTML = `<div class="github-repo-info"><span class="github-repo-name">${escapeHtml(r.name.replace('--', '/'))}</span><span class="github-repo-date">${date}</span></div><div class="github-repo-actions"><button class="github-repo-update" title="Frissites">&#x21bb;</button><button class="github-repo-delete" title="Torles">&times;</button></div>`
      item.querySelector('.github-repo-update').addEventListener('click', async (e) => {
        const btn = e.currentTarget
        btn.disabled = true
        btn.textContent = '...'
        try {
          const res = await fetch(`/api/connectors/github-repos/${encodeURIComponent(r.name)}`, { method: 'PATCH' })
          const data = await res.json()
          if (data.error) { alert(data.error); return }
          loadConnectors()
        } finally { btn.disabled = false; btn.innerHTML = '&#x21bb;' }
      })
      item.querySelector('.github-repo-delete').addEventListener('click', async () => {
        if (!confirm(`Torlod: ${r.name.replace('--', '/')}?`)) return
        await fetch(`/api/connectors/github-repos/${encodeURIComponent(r.name)}`, { method: 'DELETE' })
        loadGitHubRepos()
        loadExternalPaths()
        loadConnectors()
      })
      list.appendChild(item)
    }
  } catch { /* ignore */ }
}

;(function wireGitHubRepos() {
  const toggle = document.getElementById('githubReposToggle')
  const body = document.getElementById('githubReposBody')
  if (!toggle || !body) return
  toggle.addEventListener('click', () => {
    const arrow = toggle.querySelector('.connector-scope-toggle')
    if (body.hidden) { body.hidden = false; arrow.textContent = '▼' }
    else { body.hidden = true; arrow.textContent = '▶' }
  })
  const addBtn = document.getElementById('githubRepoAddBtn')
  const input = document.getElementById('githubRepoInput')
  const status = document.getElementById('githubRepoStatus')
  addBtn.addEventListener('click', async () => {
    const val = input.value.trim()
    if (!val) return
    addBtn.disabled = true
    addBtn.textContent = 'Telepites...'
    status.hidden = false
    status.className = 'github-repo-status loading'
    status.textContent = t('connectors.cloning')
    try {
      const res = await fetch('/api/connectors/github-repos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: val }),
      })
      const data = await res.json()
      if (data.error) {
        status.className = 'github-repo-status error'
        status.textContent = data.error
        return
      }
      if (data.requiredEnvVars && data.requiredEnvVars.length > 0) {
        status.className = 'github-repo-status loading'
        status.textContent = t('connectors.api_keys_needed')
        const envValues = await showEnvVarModal(data.requiredEnvVars)
        if (envValues && Object.keys(envValues).length > 0) {
          let vaultAllOk = true
          for (const [key, value] of Object.entries(envValues)) {
            const r = await fetch('/api/vault', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ id: `github-env-${data.repo.name}-${key}`, label: `${key} (${data.repo.name.replace('--', '/')})`, value }),
            })
            if (!r.ok) vaultAllOk = false
          }
          if (vaultAllOk) {
            status.className = 'github-repo-status success'
            status.textContent = 'Telepitve, kulcsok mentve a Vault-ba!'
          } else {
            status.className = 'github-repo-status error'
            status.textContent = 'Telepitve, de néhány kulcs mentése sikertelen. Add meg újra a Vault-ban.'
          }
          loadVault()
        } else {
          status.className = 'github-repo-status success'
          status.textContent = 'Telepitve (kulcsok kihagyva)'
        }
      } else {
        status.className = 'github-repo-status success'
        status.textContent = 'Telepitve!'
      }
      input.value = ''
      loadGitHubRepos()
      loadExternalPaths()
      loadConnectors()
      setTimeout(() => { status.hidden = true }, 4000)
    } catch (err) {
      status.className = 'github-repo-status error'
      status.textContent = 'Hiba: ' + err.message
    } finally {
      addBtn.disabled = false
      addBtn.textContent = 'Telepites'
    }
  })
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') addBtn.click() })
})()

// --- Vault management ---
async function loadVault() {
  try {
    const res = await fetch('/api/vault')
    const data = await res.json()
    const secrets = data.secrets || []
    document.getElementById('vaultCount').textContent = String(secrets.length)
    const list = document.getElementById('vaultList')
    list.innerHTML = ''
    for (const s of secrets) {
      const item = document.createElement('div')
      item.className = 'connector-external-item'
      const date = new Date(s.updatedAt).toLocaleDateString('hu-HU')
      item.innerHTML = `<div class="github-repo-info"><span class="github-repo-name">${escapeHtml(s.label)}</span><span class="github-repo-date">${escapeHtml(s.id)} &middot; ${date}</span></div><button title="Torles" style="background:none;border:none;color:var(--danger);cursor:pointer;font-size:14px;padding:2px 6px">&times;</button>`
      item.querySelector('button').addEventListener('click', async () => {
        if (!confirm(`Torlod: ${s.label}?`)) return
        const res = await fetch(`/api/vault/${encodeURIComponent(s.id)}`, { method: 'DELETE' })
        if (!res.ok) { showToast('Törlés sikertelen'); return }
        loadVault()
      })
      list.appendChild(item)
    }
  } catch { /* ignore */ }
}

;(function wireVault() {
  const toggle = document.getElementById('vaultToggle')
  const body = document.getElementById('vaultBody')
  if (!toggle || !body) return
  toggle.addEventListener('click', () => {
    const arrow = toggle.querySelector('.connector-scope-toggle')
    if (body.hidden) { body.hidden = false; arrow.textContent = '▼' }
    else { body.hidden = true; arrow.textContent = '▶' }
  })
  const addBtn = document.getElementById('vaultAddBtn')
  const idInput = document.getElementById('vaultIdInput')
  const valInput = document.getElementById('vaultValueInput')
  addBtn.addEventListener('click', async () => {
    const id = idInput.value.trim()
    const val = valInput.value
    if (!id || !val) return
    const res = await fetch('/api/vault', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, label: id, value: val }),
    })
    if (!res.ok) {
      const e = await res.json().catch(() => ({}))
      showToast('Mentés sikertelen: ' + (e.error || res.status))
      return
    }
    idInput.value = ''
    valInput.value = ''
    loadVault()
  })
  valInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') addBtn.click() })
})()

// --- Env var modal for GitHub repo install ---
let _envVarResolve = null
function showEnvVarModal(envVars) {
  return new Promise((resolve) => {
    _envVarResolve = resolve
    const modal = document.getElementById('envVarModal')
    const fields = document.getElementById('envVarFields')
    fields.innerHTML = ''
    for (const v of envVars) {
      const row = document.createElement('div')
      row.className = 'env-var-row'
      row.innerHTML = `<label class="env-var-label">${escapeHtml(v)}</label><input type="password" class="input env-var-input" data-key="${escapeHtml(v)}" placeholder="Ertek...">`
      fields.appendChild(row)
    }
    modal.hidden = false
  })
}

;(function wireEnvVarModal() {
  const modal = document.getElementById('envVarModal')
  if (!modal) return
  document.getElementById('envVarModalClose').addEventListener('click', () => {
    modal.hidden = true
    if (_envVarResolve) { _envVarResolve(null); _envVarResolve = null }
  })
  document.getElementById('envVarSkipBtn').addEventListener('click', () => {
    modal.hidden = true
    if (_envVarResolve) { _envVarResolve(null); _envVarResolve = null }
  })
  document.getElementById('envVarSaveBtn').addEventListener('click', () => {
    const inputs = document.querySelectorAll('#envVarFields .env-var-input')
    const env = {}
    for (const inp of inputs) {
      const key = inp.getAttribute('data-key')
      const val = inp.value.trim()
      if (key && val) env[key] = val
    }
    modal.hidden = true
    if (_envVarResolve) { _envVarResolve(env); _envVarResolve = null }
  })
})()

// --- SSH Vault ---
let _sshServers = []
let _sshKeys = []
let _sshView = 'table'
let _sshEditingId = null

async function loadSshServers() {
  try {
    const res = await fetch('/api/vault/ssh-servers')
    const data = await res.json()
    _sshServers = data.servers || []
    renderSshServers()
  } catch { /* ignore */ }
}

async function loadSshKeys() {
  try {
    const res = await fetch('/api/vault/ssh-keys')
    if (!res.ok) return
    const data = await res.json()
    _sshKeys = data.keys || []
    renderSshKeys()
    _refreshKeySelects()
  } catch { /* ignore */ }
}

function renderSshKeys() {
  const tbody = document.getElementById('sshKeysTableBody')
  const keysView = document.getElementById('sshKeysView')
  const emptyEl = document.getElementById('sshKeysEmpty')
  if (!tbody) return
  if (_sshKeys.length === 0) {
    keysView.hidden = true
    emptyEl.hidden = false
    return
  }
  keysView.hidden = false
  emptyEl.hidden = true
  tbody.innerHTML = _sshKeys.map(k => `
    <tr>
      <td class="ssh-table-name">${escapeHtml(k.label || k.id)}</td>
      <td class="ssh-table-mono">${escapeHtml(k.username || '')}</td>
      <td class="ssh-table-mono">${escapeHtml(k.keyType || 'ed25519')}</td>
      <td class="ssh-table-mono" style="font-size:11px">${k.fingerprint ? escapeHtml(k.fingerprint.slice(0,28)) + '…' : ''}</td>
      <td class="ssh-table-mono">${k.createdAt ? new Date(k.createdAt).toLocaleDateString('hu-HU') : ''}</td>
      <td><div class="ssh-table-actions">
        <button class="btn-secondary btn-compact ssh-key-copy-btn" data-id="${escapeHtml(k.id)}" title="Publikus kulcs másolása">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
        </button>
        <button class="btn-secondary btn-compact ssh-key-delete-btn" data-id="${escapeHtml(k.id)}" title="Törlés">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg>
        </button>
      </div></td>
    </tr>
  `).join('')
  tbody.querySelectorAll('.ssh-key-copy-btn').forEach(btn => {
    btn.addEventListener('click', async () => {
      const key = _sshKeys.find(k => k.id === btn.dataset.id)
      if (!key) return
      try {
        const res = await fetch(`/api/vault/ssh-keys/${encodeURIComponent(btn.dataset.id)}/public-key`)
        if (res.ok) {
          const data = await res.json()
          await navigator.clipboard.writeText(data.publicKey || '')
          btn.textContent = '✓'
          setTimeout(() => { btn.innerHTML = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>' }, 1500)
        }
      } catch { /* ignore */ }
    })
  })
  tbody.querySelectorAll('.ssh-key-delete-btn').forEach(btn => {
    btn.addEventListener('click', async () => {
      if (!confirm('Biztosan törlöd ezt a kulcsot?')) return
      await fetch(`/api/vault/ssh-keys/${encodeURIComponent(btn.dataset.id)}`, { method: 'DELETE' })
      await loadSshKeys()
    })
  })
}

function _refreshKeySelects() {
  const opts = ['<option value="">-- Nincs kulcs --</option>',
    ..._sshKeys.map(k => `<option value="${escapeHtml(k.id)}">${escapeHtml(k.label || k.id)} (${escapeHtml(k.username || '')})</option>`)
  ].join('')
  document.querySelectorAll('.ssh-key-select').forEach(sel => {
    const prev = sel.value
    sel.innerHTML = opts
    sel.value = prev
  })
}

function _sshKeyBadge(status) {
  const labels = { ok: 'OK', missing: 'Hiányzó', expired: 'Lejárt' }
  const icons = {
    ok: '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>',
    missing: '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>',
    expired: '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>',
  }
  return `<span class="ssh-key-badge ${status}">${icons[status] || ''} ${labels[status] || status}</span>`
}

function _sshKeyAssignSelect(s) {
  const currentKeyId = s.sshKeyId || s.assignedKeyId || s.vaultKeyId || ''
  const opts = ['<option value="">-- Nincs kulcs --</option>',
    ..._sshKeys.map(k => {
      const sel = (currentKeyId && currentKeyId === k.id) ? ' selected' : ''
      return `<option value="${escapeHtml(k.id)}"${sel}>${escapeHtml(k.label || k.id)}</option>`
    })
  ].join('')
  return `<select class="ssh-key-assign ssh-key-select" data-id="${escapeHtml(s.id)}" title="Kulcs hozzárendelése">${opts}</select>`
}

function _sshInfoBtn(s) {
  return `<button class="ssh-info-btn" data-id="${escapeHtml(s.id)}" data-user="${escapeHtml(s.user)}" title="Telepítési útmutató">i</button>`
}

function renderSshServers() {
  const cardsEl = document.getElementById('sshCardsView')
  const tableView = document.getElementById('sshTableView')
  const tableBody = document.getElementById('sshTableBody')
  const emptyEl = document.getElementById('sshEmpty')
  if (!cardsEl || !tableBody || !emptyEl) return

  // Sync view state with _sshView
  const isTable = _sshView === 'table'
  cardsEl.hidden = isTable
  if (tableView) tableView.hidden = !isTable
  document.getElementById('sshViewCards')?.classList.toggle('active', !isTable)
  document.getElementById('sshViewTable')?.classList.toggle('active', isTable)

  if (_sshServers.length === 0) {
    cardsEl.innerHTML = ''
    tableBody.innerHTML = ''
    emptyEl.hidden = false
    return
  }
  emptyEl.hidden = true

  // Cards
  cardsEl.innerHTML = _sshServers.map(s => `
    <div class="ssh-card" data-id="${escapeHtml(s.id)}">
      <div class="ssh-card-head">
        <div class="ssh-card-icon">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="2" width="20" height="8" rx="2" ry="2"/><rect x="2" y="14" width="20" height="8" rx="2" ry="2"/><line x1="6" y1="6" x2="6.01" y2="6"/><line x1="6" y1="18" x2="6.01" y2="18"/></svg>
        </div>
        <div class="ssh-card-title">
          <div class="ssh-card-name">${escapeHtml(s.name)}</div>
          ${s.desc ? `<div class="ssh-card-desc">${escapeHtml(s.desc)}</div>` : ''}
        </div>
      </div>
      <div class="ssh-card-meta">
        <div class="ssh-card-row">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>
          <span>${escapeHtml(s.host)}</span>
        </div>
        <div class="ssh-card-row">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
          <span>${escapeHtml(s.user)}${s.port !== 22 ? ` :${s.port}` : ''}</span>
        </div>
        ${s.fingerprint ? `<div class="ssh-card-row"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg><span>${escapeHtml(s.keyType || '')} ${escapeHtml(s.fingerprint.slice(0,24))}…</span></div>` : ''}
      </div>
      <div class="ssh-card-footer">
        <div style="display:flex;align-items:center;gap:4px;width:100%">
          ${_sshKeyAssignSelect(s)}
          <div class="ssh-card-actions">
            <button class="btn-secondary btn-compact ssh-edit-btn" data-id="${escapeHtml(s.id)}" title="Szerkesztés">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </button>
            <button class="btn-secondary btn-compact ssh-delete-btn" data-id="${escapeHtml(s.id)}" title="Törlés">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2"/></svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  `).join('')

  // Table
  tableBody.innerHTML = _sshServers.map(s => `
    <tr data-id="${escapeHtml(s.id)}">
      <td class="ssh-table-name">${escapeHtml(s.name)}</td>
      <td class="ssh-table-mono">${escapeHtml(s.host)}</td>
      <td class="ssh-table-mono">${escapeHtml(s.user)}</td>
      <td class="ssh-table-mono">${s.port}</td>
      <td>${_sshKeyAssignSelect(s)}</td>
      <td style="color:var(--text-muted)">${escapeHtml(s.desc || '')}</td>
      <td><div class="ssh-table-actions">
        <button class="btn-secondary btn-compact ssh-edit-btn" data-id="${escapeHtml(s.id)}" title="Szerkesztés">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
        </button>
        <button class="btn-secondary btn-compact ssh-delete-btn" data-id="${escapeHtml(s.id)}" title="Törlés">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2"/></svg>
        </button>
      </div></td>
    </tr>
  `).join('')

  // Delete handlers
  document.querySelectorAll('.ssh-delete-btn').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id = btn.getAttribute('data-id')
      if (!confirm(`Törlöd: ${id}?`)) return
      try {
        await fetch(`/api/vault/ssh-servers/${encodeURIComponent(id)}`, { method: 'DELETE' })
        await loadSshServers()
      } catch { showToast('Törlés sikertelen') }
    })
  })

  // Edit handlers -- open the add-server panel pre-filled, switch it to edit mode
  document.querySelectorAll('.ssh-edit-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const id = btn.getAttribute('data-id')
      const server = _sshServers.find(s => s.id === id)
      if (!server) return
      _sshEditingId = id

      document.getElementById('sshNameInput').value = server.name || ''
      document.getElementById('sshHostInput').value = server.host || ''
      document.getElementById('sshUserInput').value = server.user || ''
      document.getElementById('sshPortInput').value = server.port || 22
      document.getElementById('sshDescInput').value = server.desc || ''
      const keySel = document.getElementById('sshKeySelectInput')
      if (keySel) keySel.value = server.sshKeyId || server.assignedKeyId || server.vaultKeyId || ''

      const titleEl = document.getElementById('sshAddPanelTitle')
      if (titleEl) titleEl.textContent = `Szerver szerkesztése – ${server.name}`

      const panel = document.getElementById('sshAddPanel')
      panel.hidden = false
      document.getElementById('sshNameInput').focus()
    })
  })

  // Key assign select handlers
  document.querySelectorAll('.ssh-key-assign').forEach(sel => {
    sel.addEventListener('change', async () => {
      const id = sel.getAttribute('data-id')
      const sshKeyId = sel.value || null
      try {
        await fetch(`/api/vault/ssh-servers/${encodeURIComponent(id)}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ sshKeyId }),
        })
        await loadSshServers()
      } catch { /* ignore */ }
    })
  })

}

// --- SSH Keygen modal (standalone key creation for Kulcstároló) ---
let _sshKeygenCallback = null  // called with new key after successful generation

function openSshKeygenModal(callback) {
  const overlay = document.getElementById('sshKeygenOverlay')
  document.getElementById('sshKeygenLabelInput').value = ''
  document.getElementById('sshKeygenUserInput').value = ''
  document.getElementById('sshKeygenSpinner').hidden = true
  document.getElementById('sshKeygenResult').hidden = true
  document.getElementById('sshKeygenFooter').hidden = false
  document.getElementById('sshKeygenForm').hidden = false
  document.getElementById('sshKeygenPubkeyBox').value = ''
  _sshKeygenCallback = callback || null
  openModal(overlay)
  document.getElementById('sshKeygenLabelInput').focus()
}

;(function wireSshKeygenModal() {
  const overlay = document.getElementById('sshKeygenOverlay')
  const closeBtn = document.getElementById('sshKeygenClose')
  const submitBtn = document.getElementById('sshKeygenSubmitBtn')
  const copyBtn = document.getElementById('sshKeygenCopyBtn')
  if (!overlay) return

  overlay.addEventListener('click', e => { if (e.target === overlay) closeModal(overlay) })
  closeBtn.addEventListener('click', () => closeModal(overlay))

  submitBtn.addEventListener('click', async () => {
    const label = document.getElementById('sshKeygenLabelInput').value.trim()
    const username = document.getElementById('sshKeygenUserInput').value.trim()
    if (!label || !username) { showToast('Cimke és felhasználónév megadása kötelező'); return }

    document.getElementById('sshKeygenForm').hidden = true
    document.getElementById('sshKeygenSpinner').hidden = false
    document.getElementById('sshKeygenResult').hidden = true
    document.getElementById('sshKeygenFooter').hidden = true

    try {
      const res = await fetch('/api/vault/ssh-keys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ label, username }),
      })
      const data = await res.json()
      if (!res.ok) { showToast(data.error || 'Generálás sikertelen'); resetKeygenForm(); return }

      const pubkey = data.publicKey || (data.key && data.key.publicKey) || ''
      document.getElementById('sshKeygenPubkeyBox').value = pubkey
      document.getElementById('sshKeygenSpinner').hidden = true
      document.getElementById('sshKeygenResult').hidden = false

      await loadSshKeys()
      if (_sshKeygenCallback) _sshKeygenCallback(data.key || data)
    } catch { showToast('Hálózati hiba'); resetKeygenForm() }
  })

  copyBtn?.addEventListener('click', () => {
    const val = document.getElementById('sshKeygenPubkeyBox').value
    navigator.clipboard.writeText(val).then(() => {
      copyBtn.textContent = 'Másolva!'
      setTimeout(() => { copyBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg> Másolás' }, 2000)
    }).catch(() => {})
  })

  function resetKeygenForm() {
    document.getElementById('sshKeygenForm').hidden = false
    document.getElementById('sshKeygenSpinner').hidden = true
    document.getElementById('sshKeygenResult').hidden = true
    document.getElementById('sshKeygenFooter').hidden = false
  }
})()

// --- SSH Info modal ---
let _sshInfoServerId = null

async function _sshInfoLoadKey(keyId, serverUser) {
  const installSection = document.getElementById('sshInfoInstallSection')
  const noKeyEl = document.getElementById('sshInfoNoKey')
  if (!keyId) {
    installSection.hidden = true
    noKeyEl.hidden = false
    return
  }
  installSection.hidden = false
  noKeyEl.hidden = true

  let pubkey = ''
  try {
    const res = await fetch(`/api/vault/ssh-keys/${encodeURIComponent(keyId)}/public-key`)
    if (res.ok) { const d = await res.json(); pubkey = d.publicKey || '' }
  } catch {}

  const targetUser = serverUser || 'root'
  document.getElementById('sshInfoUser').textContent = targetUser

  // root always exists -- only show the "create user" step for a real,
  // non-root target user (e.g. a fresh server that needs the account first).
  const step0 = document.getElementById('sshInfoStep0')
  if (targetUser === 'root') {
    step0.hidden = true
  } else {
    step0.hidden = false
    document.getElementById('sshInfoCmd0').textContent = `useradd -m -s /bin/bash ${targetUser}`
  }

  const cmd2text = pubkey
    ? `echo "${pubkey}" >> ~/.ssh/authorized_keys`
    : `echo "<publikus kulcs ide>" >> ~/.ssh/authorized_keys`
  document.getElementById('sshInfoCmd2').textContent = cmd2text
  document.getElementById('sshInfoPubkey').textContent = pubkey || '(kulcs nem elérhető)'

  const overlay = document.getElementById('sshInfoOverlay')
  overlay.querySelectorAll('.ssh-code-copy').forEach(btn => {
    const clone = btn.cloneNode(true)
    btn.parentNode.replaceChild(clone, btn)
    clone.addEventListener('click', () => {
      const text = document.getElementById(clone.getAttribute('data-target'))?.textContent || ''
      navigator.clipboard.writeText(text).then(() => {
        clone.classList.add('copied')
        setTimeout(() => clone.classList.remove('copied'), 2000)
      }).catch(() => {})
    })
  })
}

function _sshInfoLoadServer(serverId) {
  _sshInfoServerId = serverId
  const server = _sshServers.find(s => s.id === serverId)

  document.getElementById('sshInfoServerName').textContent = server ? server.name : (serverId || '')

  const keySel = document.getElementById('sshInfoKeySelect')
  keySel.innerHTML = ['<option value="">-- Nincs kulcs --</option>',
    ..._sshKeys.map(k => `<option value="${escapeHtml(k.id)}">${escapeHtml(k.label || k.id)} (${escapeHtml(k.username || '')})</option>`)
  ].join('')
  const assignedKeyId = (server && (server.sshKeyId || server.assignedKeyId || server.vaultKeyId)) || ''
  keySel.value = assignedKeyId
  return { server, assignedKeyId }
}

function openSshInfoModal(preselectedServerId, { keyOnly = false } = {}) {
  const overlay = document.getElementById('sshInfoOverlay')
  const serverSection = overlay.querySelector('.ssh-info-server-section')

  if (keyOnly) {
    // Key-only mode: hide server selector, reset server context
    serverSection.hidden = true
    _sshInfoServerId = null
    document.getElementById('sshInfoServerName').textContent = 'Új szerver'

    // Populate key selector without a pre-selected key
    const keySel = document.getElementById('sshInfoKeySelect')
    keySel.innerHTML = ['<option value="">-- Válassz kulcsot --</option>',
      ..._sshKeys.map(k => `<option value="${escapeHtml(k.id)}">${escapeHtml(k.label || k.id)} (${escapeHtml(k.username || '')})</option>`)
    ].join('')
    // Pre-select whatever is chosen in the form's key dropdown
    const formKeyId = document.getElementById('sshKeySelectInput')?.value || ''
    keySel.value = formKeyId

    // Use the username typed into the new-server form, not a hardcoded root
    const formUser = document.getElementById('sshUserInput')?.value.trim() || 'root'

    openModal(overlay)
    _sshInfoLoadKey(formKeyId, formUser)
  } else {
    // Normal mode: show server selector, pick first server by default
    serverSection.hidden = false
    const serverSel = document.getElementById('sshInfoServerSelect')
    serverSel.innerHTML = ['<option value="">-- Válassz szervert --</option>',
      ..._sshServers.map(s => `<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)} (${escapeHtml(s.host)})</option>`)
    ].join('')

    const firstId = preselectedServerId || (_sshServers[0] && _sshServers[0].id) || ''
    serverSel.value = firstId

    const { server, assignedKeyId } = _sshInfoLoadServer(firstId)
    const targetUser = (server && server.user) || 'root'

    openModal(overlay)
    _sshInfoLoadKey(assignedKeyId, targetUser)
  }
}

;(function wireSshInfoModal() {
  const overlay = document.getElementById('sshInfoOverlay')
  const closeBtn = document.getElementById('sshInfoClose')
  const serverSel = document.getElementById('sshInfoServerSelect')
  const keySel = document.getElementById('sshInfoKeySelect')
  if (!overlay) return

  overlay.addEventListener('click', e => { if (e.target === overlay) closeModal(overlay) })
  closeBtn.addEventListener('click', () => closeModal(overlay))

  serverSel?.addEventListener('change', () => {
    const { server, assignedKeyId } = _sshInfoLoadServer(serverSel.value)
    _sshInfoLoadKey(assignedKeyId, (server && server.user) || 'root')
  })

  keySel?.addEventListener('change', async () => {
    const keyId = keySel.value || null
    // Key-only mode (new-server flow) has no _sshInfoServerId -- read the
    // username from the new-server form instead of falling back to root.
    const targetUser = _sshInfoServerId
      ? ((_sshServers.find(s => s.id === _sshInfoServerId) || {}).user || 'root')
      : (document.getElementById('sshUserInput')?.value.trim() || 'root')

    if (_sshInfoServerId) {
      try {
        await fetch(`/api/vault/ssh-servers/${encodeURIComponent(_sshInfoServerId)}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ sshKeyId: keyId }),
        })
        await loadSshServers()
      } catch { /* ignore */ }
    }
    await _sshInfoLoadKey(keyId, targetUser)
  })
})()

;(function wireSshSection() {
  const newBtn = document.getElementById('sshNewBtn')
  const panel = document.getElementById('sshAddPanel')
  const closeBtn = document.getElementById('sshAddPanelClose')
  const addBtn = document.getElementById('sshAddBtn')
  const cardViewBtn = document.getElementById('sshViewCards')
  const tableViewBtn = document.getElementById('sshViewTable')
  const cardsView = document.getElementById('sshCardsView')
  const tableView = document.getElementById('sshTableView')

  if (!newBtn) return

  function resetSshAddForm() {
    _sshEditingId = null
    const titleEl = document.getElementById('sshAddPanelTitle')
    if (titleEl) titleEl.textContent = 'Szerver hozzáadása'
    document.getElementById('sshNameInput').value = ''
    document.getElementById('sshHostInput').value = ''
    document.getElementById('sshUserInput').value = ''
    document.getElementById('sshPortInput').value = '22'
    document.getElementById('sshDescInput').value = ''
    if (document.getElementById('sshKeySelectInput')) document.getElementById('sshKeySelectInput').value = ''
  }

  newBtn.addEventListener('click', () => {
    if (panel.hidden) resetSshAddForm()
    panel.hidden = !panel.hidden
    if (!panel.hidden) document.getElementById('sshNameInput').focus()
  })
  closeBtn?.addEventListener('click', () => { panel.hidden = true; resetSshAddForm() })

  // (i) install guide button inside the "new server" form -- key-only mode
  document.getElementById('sshKeyInstallFromFormBtn')?.addEventListener('click', () => {
    openSshInfoModal(null, { keyOnly: true })
  })

  // "+ Új kulcs" button inside the "new server" form
  document.getElementById('sshKeyNewFromFormBtn')?.addEventListener('click', () => {
    openSshKeygenModal(newKey => {
      // After key created, select it in the form dropdown
      if (newKey && newKey.id) {
        const sel = document.getElementById('sshKeySelectInput')
        if (sel) sel.value = newKey.id
      }
    })
  })

  addBtn?.addEventListener('click', async () => {
    const name = document.getElementById('sshNameInput').value.trim()
    const host = document.getElementById('sshHostInput').value.trim()
    const user = document.getElementById('sshUserInput').value.trim()
    const port = parseInt(document.getElementById('sshPortInput').value, 10) || 22
    const desc = document.getElementById('sshDescInput').value.trim()
    const sshKeyId = document.getElementById('sshKeySelectInput')?.value || null
    if (!name || !host || !user) { showToast('Név, IP és felhasználó megadása kötelező'); return }
    const isEdit = !!_sshEditingId
    try {
      const res = await fetch(
        isEdit ? `/api/vault/ssh-servers/${encodeURIComponent(_sshEditingId)}` : '/api/vault/ssh-servers',
        {
          method: isEdit ? 'PUT' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name, host, user, port, desc, sshKeyId: sshKeyId || undefined }),
        }
      )
      if (!res.ok) {
        const err = await res.json().catch(() => ({}))
        showToast(err.error || 'Hiba a mentéskor'); return
      }
      resetSshAddForm()
      panel.hidden = true
      await loadSshServers()
      showToast(isEdit ? 'Szerver frissítve' : 'Szerver hozzáadva')
    } catch { showToast('Hálózati hiba') }
  })

  cardViewBtn?.addEventListener('click', () => {
    _sshView = 'cards'
    cardViewBtn.classList.add('active')
    tableViewBtn.classList.remove('active')
    cardsView.hidden = false
    tableView.hidden = true
  })

  tableViewBtn?.addEventListener('click', () => {
    _sshView = 'table'
    tableViewBtn.classList.add('active')
    cardViewBtn.classList.remove('active')
    cardsView.hidden = true
    tableView.hidden = false
  })

  // Kulcstároló "Új kulcs generálása" button
  document.getElementById('sshKeyNewBtn')?.addEventListener('click', () => {
    openSshKeygenModal()
  })

  // Global (i) info button in section header
  document.getElementById('sshInfoGlobalBtn')?.addEventListener('click', () => {
    openSshInfoModal()
  })
})()

// --- Vault Page ---
let _vaultSecrets = []
// Every tag already in use, served alongside the list. The editor offers these
// to pick from instead of asking for them to be retyped -- typing "szemelyes"
// next to an existing "Személyes" silently forks the group, and a filter row
// with fifty near-duplicate chips is worse than no tags at all (Boss,
// 2026-08-10: "ha lesz 50 cimke, vagy csak 15, az mar problema").
let _vaultAllTags = []

let _vaultBindings = []

async function loadVaultPage() {
  try {
    const [secretsRes, bindingsRes] = await Promise.all([
      fetch('/api/vault'),
      fetch('/api/vault/bindings'),
    ])
    const secretsData = await secretsRes.json()
    const bindingsData = await bindingsRes.json()
    _vaultSecrets = secretsData.secrets || []
    _vaultAllTags = secretsData.allTags || []
    _vaultBindings = bindingsData.bindings || []
    document.getElementById('vaultStatTotal').textContent = String(_vaultSecrets.length)
    document.getElementById('vaultStatBindings').textContent = String(_vaultBindings.length)
    renderVaultCategoryFilter(_vaultSecrets)
    renderVaultGrid(_vaultSecrets)
    renderVaultKnownIntegrations()
    await Promise.all([loadSshKeys(), loadSshServers()])
  } catch { /* ignore */ }
}

// === Drive fajlbongeszo (kanban aa55180c) ===
// Az OAuth/token-kezeles mar megvan (scripts/google-auth.py, tobb-fiokos) --
// ez a panel csak a mar bekotott fiok(ok) Drive-tartalmat listazza/kezeli a
// src/web/routes/drive-browser.ts vegpontokon keresztul. Torles = kosarba
// helyezes (trashed=true), soha nem vegleges -- lasd az info-box szoveget.
let _driveAccount = ''
let _driveFolderStack = [{ id: 'root', name: '' }]

/**
 * A KIVALASZTOTT fiok megjegyzese, lap szerint -- Boss, 2026-08-15: "a fotoknal
 * amikor frissitek mindig a lackor2 re valt. maradjon azon ahol eppen vagyok.
 * ha usalackor akor azon maradjon."
 *
 * Lapfrissiteskor (F5) a modul-szintu valtozok elvesznek, es a lap az elso
 * hasznalhato fiokot valasztotta -- az pedig ABC-sorrendben a lackor2. Tiz
 * bekotott fioknal ez minden frissites utan ujra-kattintast jelentene. A
 * valasztas ezert localStorage-ba kerul. Ha a bongeszo tiltja a tarolast
 * (privat mod), a regi viselkedes marad -- hiba nelkul, mert a Marveen ettol
 * meg hasznalhato.
 *
 * Lapokent kulon kulcs: a Drive-on mas fiokot nezhet az ember, mint a Fotokban.
 */
function _rememberAccount(page, name) {
  try { localStorage.setItem('marveen.account.' + page, name || '') } catch { /* tiltott tarolo */ }
}
function _recallAccount(page) {
  try { return localStorage.getItem('marveen.account.' + page) || '' } catch { return '' }
}

// --- "Osszes fiok" nezet (Boss 2026-08-14) -----------------------------------
// Tobb Google-cim van bekotve, es a kerdes rendszerint nem az, hogy "mi van a
// lackor2 Drive-jan", hanem hogy "hol van ez a fajl". A legordulo fiokvalaszto
// erre valaszolni csak vaktaban kattintgatva tud. Ebben a nezetben minden fiok
// egy-egy hasab, SAJAT mappaveremmel: az egyikben lehet harom mappaval bentebb,
// mikozben a masik a gyokeret mutatja.
//
// A vegpontok mar fiok-parameteresek (routes/drive-browser.ts), szerveroldali
// valtoztatas nelkul. Egy hasab hibaja (lejart token) csak azt a hasabot rontja
// el -- tiz fioknal az "egy rossz fiok elviszi az egesz oldalt" a leggyakoribb
// hibamod.
let _driveAllMode = false
let _driveAccountsAll = []
let _driveHidden = new Set()   // amit a felhasznalo kikapcsolt (fiok-azonositok)
const _driveStacks = {}        // fiok -> sajat mappaverem

const DRIVE_LS_MODE = 'marveen.drive.allmode'
const DRIVE_LS_HIDDEN = 'marveen.drive.hidden'
/** Ennyi hasab tolti be egyszerre a tartalmat. Tiz parhuzamos kerés tiz
 *  python-inditast jelentene a szerveren -- ez nem gyorsabb, csak nehezebb. */
const DRIVE_MULTI_CONCURRENCY = 4

function _driveStack(account) {
  if (!_driveStacks[account]) _driveStacks[account] = [{ id: 'root', name: t('drive.root_label') }]
  return _driveStacks[account]
}

function _driveShownAccounts() {
  return _driveAccountsAll.filter(a => !_driveHidden.has(a))
}

/** Egyszerre legfeljebb `limit` feladat fut. */
async function _drivePool(items, limit, worker) {
  const queue = [...items]
  const runners = Array.from({ length: Math.min(limit, queue.length) }, async () => {
    while (queue.length) await worker(queue.shift())
  })
  await Promise.all(runners)
}

function _driveApplyMode() {
  const single = document.getElementById('driveSingleTools')
  const multi = document.getElementById('driveMulti')
  const bar = document.getElementById('driveMultiBar')
  const toggle = document.getElementById('driveAllToggle')
  const label = document.getElementById('driveAllToggleLabel')
  if (single) single.style.display = _driveAllMode ? 'none' : 'flex'
  for (const id of ['driveBreadcrumb', 'driveList', 'driveEmpty', 'driveError']) {
    const el = document.getElementById(id)
    if (el) el.style.display = _driveAllMode ? 'none' : ''
  }
  if (multi) multi.hidden = !_driveAllMode
  if (bar) bar.hidden = !_driveAllMode
  if (toggle) toggle.setAttribute('aria-pressed', String(_driveAllMode))
  if (label) label.textContent = t(_driveAllMode ? 'drive.single_account_btn' : 'drive.all_accounts_btn')
}

function _driveRenderChips() {
  const box = document.getElementById('driveMultiChips')
  if (!box) return
  box.innerHTML = _driveAccountsAll.map(a => {
    const on = !_driveHidden.has(a)
    return `<button class="drive-chip${on ? ' drive-chip-on' : ''}" data-acc="${escapeHtml(a)}" aria-pressed="${on}">${escapeHtml(a)}</button>`
  }).join('')
  box.querySelectorAll('.drive-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      const acc = chip.getAttribute('data-acc')
      if (_driveHidden.has(acc)) _driveHidden.delete(acc)
      else _driveHidden.add(acc)
      // Az utolso hasabot nem lehet elrejteni: ures oldal nem valasz.
      if (_driveShownAccounts().length === 0) { _driveHidden.delete(acc); return }
      try { localStorage.setItem(DRIVE_LS_HIDDEN, JSON.stringify([..._driveHidden])) } catch { /* ignore */ }
      _driveRenderChips()
      renderDriveMulti()
    })
  })
}

/** Egy hasab vaza. A tartalmat a loadDriveColumn tolti bele. */
function driveColumnHtml(account) {
  return `<section class="drive-col" data-acc="${escapeHtml(account)}">
    <header class="drive-col-head">
      <span class="drive-col-name" title="${escapeHtml(account)}">${escapeHtml(account)}</span>
      <span class="drive-col-tools">
        <button class="btn-icon" data-col-action="upload" title="${escapeHtml(t('drive.upload_btn'))}"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg></button>
        <button class="btn-icon" data-col-action="mkdir" title="${escapeHtml(t('drive.new_folder_btn'))}"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/><line x1="12" y1="11" x2="12" y2="17"/><line x1="9" y1="14" x2="15" y2="14"/></svg></button>
        <button class="btn-icon" data-col-action="refresh" title="${escapeHtml(t('drive.refresh_btn'))}"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg></button>
      </span>
    </header>
    <div class="drive-breadcrumb drive-col-crumbs"></div>
    <div class="drive-list drive-col-list"></div>
  </section>`
}

function renderDriveColumnCrumbs(col, account) {
  const bc = col.querySelector('.drive-col-crumbs')
  const stack = _driveStack(account)
  bc.innerHTML = stack.map((f, i) => {
    const isLast = i === stack.length - 1
    return `<span class="drive-crumb${isLast ? ' drive-crumb-current' : ''}" data-idx="${i}">${escapeHtml(f.name)}</span>`
      + (isLast ? '' : '<span class="drive-crumb-sep">/</span>')
  }).join('')
  bc.querySelectorAll('.drive-crumb:not(.drive-crumb-current)').forEach(el => {
    el.addEventListener('click', () => {
      const idx = Number(el.getAttribute('data-idx'))
      _driveStacks[account] = stack.slice(0, idx + 1)
      loadDriveColumn(account)
    })
  })
}

async function loadDriveColumn(account) {
  const col = document.querySelector(`.drive-col[data-acc="${CSS.escape(account)}"]`)
  if (!col) return
  const list = col.querySelector('.drive-col-list')
  const stack = _driveStack(account)
  const folder = stack[stack.length - 1]
  renderDriveColumnCrumbs(col, account)
  list.innerHTML = `<div class="drive-loading">${escapeHtml(t('drive.loading'))}</div>`
  try {
    const res = await fetch(`/api/drive/list?folderId=${encodeURIComponent(folder.id)}&account=${encodeURIComponent(account)}`)
    const data = await res.json()
    if (!res.ok) {
      // Csak EZ a hasab romlik el. A hibauzenet a fiok nevevel egyutt all ott,
      // kulonben tiz hasabnal talalgatas, melyik fiokkal van baj.
      list.innerHTML = `<div class="drive-col-error">${escapeHtml(data.error || t('drive.load_error'))}</div>`
      return
    }
    const files = data.files || []
    if (files.length === 0) {
      list.innerHTML = `<div class="drive-col-empty">${escapeHtml(t('drive.empty_msg'))}</div>`
      return
    }
    list.innerHTML = files.map(f => driveRowHtml(f)).join('')
    bindDriveRowActions(list, account, stack, () => loadDriveColumn(account))
  } catch {
    list.innerHTML = `<div class="drive-col-error">${escapeHtml(t('drive.load_error'))}</div>`
  }
}

function renderDriveMulti() {
  const wrap = document.getElementById('driveMulti')
  if (!wrap) return
  const accounts = _driveShownAccounts()
  wrap.innerHTML = accounts.map(a => driveColumnHtml(a)).join('')
  wrap.querySelectorAll('.drive-col').forEach(col => {
    const account = col.getAttribute('data-acc')
    col.querySelectorAll('[data-col-action]').forEach(btn => {
      btn.addEventListener('click', async () => {
        const action = btn.getAttribute('data-col-action')
        if (action === 'refresh') { loadDriveColumn(account); return }
        if (action === 'mkdir') {
          const name = prompt(t('drive.prompt.new_folder'))
          if (!name) return
          const stack = _driveStack(account)
          const res = await fetch('/api/drive/mkdir', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name, parentId: stack[stack.length - 1].id, account }),
          })
          if (!res.ok) { const d = await res.json().catch(() => ({})); alert(d.error || t('drive.error.generic')); return }
          loadDriveColumn(account)
          return
        }
        if (action === 'upload') {
          // Egy rejtett fajlmezot hasznal minden hasab; a cel fiokot a
          // gomb allitja be, mielott megnyitja a valasztot.
          const input = document.getElementById('driveMultiUploadInput')
          if (!input) return
          input.dataset.account = account
          input.click()
        }
      })
    })
  })
  _drivePool(accounts, DRIVE_MULTI_CONCURRENCY, acc => loadDriveColumn(acc))
}

document.getElementById('driveMultiUploadInput')?.addEventListener('change', async (ev) => {
  const file = ev.target.files[0]
  const account = ev.target.dataset.account
  ev.target.value = ''
  if (!file || !account) return
  const stack = _driveStack(account)
  const form = new FormData()
  form.append('file', file)
  form.append('parentId', stack[stack.length - 1].id)
  form.append('account', account)
  const res = await fetch('/api/drive/upload', { method: 'POST', body: form })
  if (!res.ok) { const d = await res.json().catch(() => ({})); alert(d.error || t('drive.error.generic')); return }
  loadDriveColumn(account)
})

document.getElementById('driveAllToggle')?.addEventListener('click', () => {
  _driveAllMode = !_driveAllMode
  try { localStorage.setItem(DRIVE_LS_MODE, _driveAllMode ? '1' : '0') } catch { /* ignore */ }
  _driveApplyMode()
  if (_driveAllMode) { _driveRenderChips(); renderDriveMulti() }
  // Vissza egy-fiokos nezetbe: loadDrivePage() kell, nem loadDriveFolder().
  // Ha az oldal a hasabos nezetben nyilt meg (a valasztas tullel egy
  // ujratoltest), akkor a fiok-legordulo meg ures es a _driveAccount is ures --
  // a loadDriveFolder() ilyenkor account= nelkul kerne le a listat, es a
  // felhasznalo egy hibauzenetet kapna a sajat Drive-ja helyett.
  else loadDrivePage()
})

async function loadDrivePage() {
  _driveFolderStack = [{ id: 'root', name: t('drive.root_label') }]
  try { _driveAllMode = localStorage.getItem(DRIVE_LS_MODE) === '1' } catch { _driveAllMode = false }
  try {
    const saved = JSON.parse(localStorage.getItem(DRIVE_LS_HIDDEN) || '[]')
    _driveHidden = new Set(Array.isArray(saved) ? saved : [])
  } catch { _driveHidden = new Set() }
  try {
    const accRes = await fetch('/api/drive/accounts')
    const accData = await accRes.json()
    const select = document.getElementById('driveAccountSelect')
    const accounts = accData.accounts || []
    _driveAccountsAll = accounts
    // Egy fioknal a hasabos nezet ertelmetlen -- a kapcsolo is felesleges.
    const toggle = document.getElementById('driveAllToggle')
    if (toggle) toggle.hidden = accounts.length < 2
    if (accounts.length < 2) _driveAllMode = false
    // Egy kozben eltavolitott fiok nem tarthatja rejtve magat orokre, es nem
    // is tuntetheti el az osszes hasabot.
    _driveHidden = new Set([..._driveHidden].filter(a => accounts.includes(a)))
    if (accounts.length && _driveShownAccounts().length === 0) _driveHidden = new Set()
    _driveApplyMode()
    if (_driveAllMode) {
      _driveRenderChips()
      renderDriveMulti()
      return
    }
    if (accounts.length === 0) {
      select.innerHTML = ''
      document.getElementById('driveList').innerHTML = ''
      document.getElementById('driveEmpty').hidden = true
      renderDriveError(t('drive.no_account'))
      return
    }
    if (!_driveAccount || !accounts.includes(_driveAccount)) {
      // Elobb a Boss legutobbi valasztasa (frissites utan is az maradjon),
      // csak azutan az alapertelmezett fiok.
      const saved = _recallAccount('drive')
      _driveAccount = accounts.includes(saved)
        ? saved
        : ((accData.default && accounts.includes(accData.default)) ? accData.default : accounts[0])
    }
    select.innerHTML = accounts.map(a => `<option value="${escapeHtml(a)}" ${a === _driveAccount ? 'selected' : ''}>${escapeHtml(a)}</option>`).join('')
    select.onchange = () => {
      _driveAccount = select.value
      _rememberAccount('drive', _driveAccount)
      _driveFolderStack = [{ id: 'root', name: t('drive.root_label') }]
      loadDriveFolder()
    }
    await loadDriveFolder()
  } catch {
    renderDriveError(t('drive.load_error'))
  }
}

function currentDriveFolder() {
  return _driveFolderStack[_driveFolderStack.length - 1]
}

async function loadDriveFolder() {
  const folder = currentDriveFolder()
  renderDriveBreadcrumb()
  const list = document.getElementById('driveList')
  const empty = document.getElementById('driveEmpty')
  renderDriveError('')
  list.innerHTML = `<div class="drive-loading">${escapeHtml(t('drive.loading'))}</div>`
  try {
    const res = await fetch(`/api/drive/list?folderId=${encodeURIComponent(folder.id)}&account=${encodeURIComponent(_driveAccount)}`)
    const data = await res.json()
    if (!res.ok) { renderDriveError(data.error || t('drive.load_error')); list.innerHTML = ''; return }
    const files = data.files || []
    if (files.length === 0) {
      list.innerHTML = ''
      empty.hidden = false
      return
    }
    empty.hidden = true
    list.innerHTML = files.map(f => driveRowHtml(f)).join('')
    bindDriveRowActions(list, _driveAccount, _driveFolderStack, loadDriveFolder)
  } catch {
    renderDriveError(t('drive.load_error'))
    list.innerHTML = ''
  }
}

function renderDriveError(msg) {
  const box = document.getElementById('driveError')
  if (!box) return
  if (!msg) { box.hidden = true; box.innerHTML = ''; return }
  box.hidden = false
  box.innerHTML = `<p>${escapeHtml(msg)}</p>`
}

function renderDriveBreadcrumb() {
  const bc = document.getElementById('driveBreadcrumb')
  bc.innerHTML = _driveFolderStack.map((f, i) => {
    const isLast = i === _driveFolderStack.length - 1
    return `<span class="drive-crumb${isLast ? ' drive-crumb-current' : ''}" data-idx="${i}">${escapeHtml(f.name)}</span>`
      + (isLast ? '' : '<span class="drive-crumb-sep">/</span>')
  }).join('')
  bc.querySelectorAll('.drive-crumb:not(.drive-crumb-current)').forEach(el => {
    el.addEventListener('click', () => {
      const idx = Number(el.getAttribute('data-idx'))
      _driveFolderStack = _driveFolderStack.slice(0, idx + 1)
      loadDriveFolder()
    })
  })
}

function fmtDriveSize(bytes) {
  if (bytes === null || bytes === undefined) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MB`
  return `${(bytes / 1024 / 1024 / 1024).toFixed(1)} GB`
}

function driveRowHtml(f) {
  const icon = f.isFolder
    ? '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>'
    : '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>'
  const modified = f.modifiedTime ? new Date(f.modifiedTime).toLocaleDateString() : ''
  return `<div class="drive-row" data-id="${escapeHtml(f.id)}" data-folder="${f.isFolder ? '1' : '0'}" data-name="${escapeHtml(f.name)}" data-mime="${escapeHtml(f.mimeType || '')}">
    <div class="drive-row-name">${icon}<span>${escapeHtml(f.name)}</span></div>
    <div class="drive-row-meta">${escapeHtml(modified)}</div>
    <div class="drive-row-meta">${escapeHtml(fmtDriveSize(f.size))}</div>
    <div class="drive-row-actions">
      ${f.isFolder ? '' : `<button class="btn-icon" data-action="download" title="${escapeHtml(t('drive.action.download'))}"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg></button>`}
      <button class="btn-icon" data-action="rename" title="${escapeHtml(t('drive.action.rename'))}"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg></button>
      <button class="btn-icon" data-action="move" title="${escapeHtml(t('drive.action.move'))}"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 9l-3 3 3 3"/><path d="M9 5l3-3 3 3"/><path d="M15 19l3 3 3-3"/><path d="M19 9l3 3-3 3"/><line x1="2" y1="12" x2="22" y2="12"/><line x1="12" y1="2" x2="12" y2="22"/></svg></button>
      <button class="btn-icon btn-icon-danger" data-action="trash" title="${escapeHtml(t('drive.action.trash'))}"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>
    </div>
  </div>`
}

/**
 * Download one Drive file.
 *
 * NOT window.open(): the dashboard authenticates with an `Authorization:
 * Bearer` header that the fetch wrapper attaches (web/app.js, TOKEN_KEY), and a
 * plain navigation carries no headers -- the download tab came back with
 * {"error":"Unauthorized"} (Boss, 2026-08-14). The query-string ?token= lane is
 * scoped to the SSE pane stream on the server and would leak the token into
 * history anyway, so the file is fetched here and handed to the browser as a
 * blob -- the same idiom the agent/fleet exports already use.
 */
async function downloadDriveFile(fileId, name, account, mimeType) {
  // A big file is minutes of silence otherwise: no tab opens, nothing moves.
  showToast(t('drive.download.started', { name }))
  let res
  try {
    res = await fetch('/api/drive/download?fileId=' + encodeURIComponent(fileId)
      + '&account=' + encodeURIComponent(account)
      + '&name=' + encodeURIComponent(name)
      + '&mimeType=' + encodeURIComponent(mimeType || ''))
  } catch {
    showToast(t('drive.download.failed', { name }))
    return
  }
  if (!res.ok) {
    const d = await res.json().catch(() => ({}))
    // Google Docs/Sheets have no bytes to download; the server says so with a
    // code so this reads in the user's own language.
    showToast(d.code === 'unsupported_google_type' ? t('drive.download.unsupported') : (d.error || t('drive.download.failed', { name })))
    return
  }
  const blob = await res.blob()
  // The server sends both filename= and filename*=UTF-8''... -- the starred one
  // is the only one that survives accented names, so it wins. Docs exports also
  // gain an extension there (".docx") that the Drive listing does not have.
  const cd = res.headers.get('Content-Disposition') || ''
  const star = /filename\*=UTF-8''([^;]+)/i.exec(cd)
  let filename = name
  if (star) { try { filename = decodeURIComponent(star[1]) } catch { /* keep name */ } }
  const objectUrl = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = objectUrl
  a.download = filename
  document.body.appendChild(a)
  a.click()
  a.remove()
  URL.revokeObjectURL(objectUrl)
}

/**
 * Row actions for ONE account's file list.
 *
 * Takes the account and its folder stack instead of reading the page-wide
 * globals: in the "all accounts" view every column is a different account at a
 * different folder, and a shared global would have every column's buttons
 * acting on whichever account was selected last -- renaming or trashing a file
 * in the wrong Drive.
 */
function bindDriveRowActions(list, account, stack, reload) {
  list.querySelectorAll('.drive-row').forEach(row => {
    const id = row.getAttribute('data-id')
    const name = row.getAttribute('data-name')
    const isFolder = row.getAttribute('data-folder') === '1'
    const mimeType = row.getAttribute('data-mime') || ''
    row.querySelector('.drive-row-name').addEventListener('click', () => {
      if (isFolder) {
        stack.push({ id, name })
        reload()
      }
    })
    row.querySelectorAll('[data-action]').forEach(btn => {
      btn.addEventListener('click', async (ev) => {
        ev.stopPropagation()
        const action = btn.getAttribute('data-action')
        if (action === 'download') {
          await downloadDriveFile(id, name, account, mimeType)
          return
        }
        if (action === 'rename') {
          const newName = prompt(t('drive.prompt.rename'), name)
          if (!newName || newName === name) return
          const res = await fetch('/api/drive/rename', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ fileId: id, name: newName, account }) })
          if (!res.ok) { const d = await res.json().catch(() => ({})); alert(d.error || t('drive.error.generic')); return }
          reload()
          return
        }
        if (action === 'move') {
          const targetId = prompt(t('drive.prompt.move'))
          if (!targetId) return
          const res = await fetch('/api/drive/move', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ fileId: id, newParentId: targetId.trim(), account }) })
          if (!res.ok) { const d = await res.json().catch(() => ({})); alert(d.error || t('drive.error.generic')); return }
          reload()
          return
        }
        if (action === 'trash') {
          // The account is named in the question: with three columns open,
          // "Töröljem a szerzodes.pdf-et?" is not enough information to say yes to.
          if (!confirm(t('drive.confirm.trash_account', { name, account }))) return
          const res = await fetch('/api/drive/trash', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ fileId: id, account }) })
          if (!res.ok) { const d = await res.json().catch(() => ({})); alert(d.error || t('drive.error.generic')); return }
          reload()
        }
      })
    })
  })
}

document.getElementById('driveNewFolderBtn')?.addEventListener('click', async () => {
  const name = prompt(t('drive.prompt.new_folder'))
  if (!name) return
  const res = await fetch('/api/drive/mkdir', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, parentId: currentDriveFolder().id, account: _driveAccount }) })
  if (!res.ok) { const d = await res.json().catch(() => ({})); alert(d.error || t('drive.error.generic')); return }
  loadDriveFolder()
})

document.getElementById('driveUploadInput')?.addEventListener('change', async (ev) => {
  const file = ev.target.files[0]
  if (!file) return
  const form = new FormData()
  form.append('file', file)
  form.append('parentId', currentDriveFolder().id)
  form.append('account', _driveAccount)
  ev.target.value = ''
  const res = await fetch('/api/drive/upload', { method: 'POST', body: form })
  if (!res.ok) { const d = await res.json().catch(() => ({})); alert(d.error || t('drive.error.generic')); return }
  loadDriveFolder()
})

// ============================================================================
// Fotok oldal -- KIZAROLAG Google Fotok
//
// Boss, 2026-08-14: "a fotok alatt a google fotokat akarom latni. csakis
// azokat." Ezen az oldalon Drive-fajl SOHA nem jelenik meg; a /api/photos/*
// vegpontok csak a Google Fotokbol behozott kepeket ismerik.
//
// Miert kell "hozzaadni" oket, miert nem latszik magatol az egesz konyvtar:
// a Google a konyvtar-bongeszest 2025-03-31-en megszuntette (a
// photoslibrary.readonly scope-ot visszavonta). Ami maradt, az a Picker: a
// felhasznalo a Google sajat lapjan valaszt, es mi a valasztottakat kapjuk
// meg. Azokat viszont AZONNAL lementjuk a gepre, mert a Google linkje 60 perc
// mulva halott -- igy a kepek utana itt maradnak, halozat nelkul is.
// ============================================================================
let _photosAccount = ''
let _photosAccountsReady = {}
let _photoBlobUrls = []
let _photosPollTimer = null
/** Ennyivel a lathato sav ELOTT kezdjuk el hozni a kepet (gorgetesnel keszen all). */
const PHOTOS_PRELOAD_PX = 800
/** A bongeszo sajat tara: ide kerulnek a mar egyszer lehozott kepek. */
const PHOTOS_CACHE = 'marveen-fotok-v1'

let _photosTileObserver = null

function _photosReleaseBlobs() {
  for (const u of _photoBlobUrls) { try { URL.revokeObjectURL(u) } catch { /* mar nincs */ } }
  _photoBlobUrls = []
  if (_photosTileObserver) { _photosTileObserver.disconnect(); _photosTileObserver = null }
}

/**
 * A bongeszo tarolt valasza egy kepre -- ha van.
 *
 * Boss, 2026-08-15: "ezt cache be nem lehet eltarolni, hogy legkozelebb ne
 * toltse be? [...] mindig amikor atmegyek majd visszajovok ugyanabba a fiokba
 * akkor ujra betolti."
 *
 * A Cache Storage a lapvaltast ES a bongeszo ujrainditasat is tulel. Nem
 * mindenhol van (csak biztonsagos eredetnel: localhost vagy https) -- ha
 * hianyzik, a kepek ugyanugy latszanak, csak halozatrol jonnek.
 */
async function _photosCache() {
  try {
    if (!('caches' in window)) return null
    return await caches.open(PHOTOS_CACHE)
  } catch {
    return null
  }
}

/** A Google "5s" alakban mondja meg a lekerdezes-suruseget. */
function _photosPollMs(raw) {
  const m = /^([0-9]+(?:\.[0-9]+)?)s$/.exec(String(raw || '').trim())
  const secs = m ? Number(m[1]) : 5
  // Also hatar, hogy egy hibas "0.001s" ne verje szet a szervert; felso, hogy
  // egy elgepelt "600s" ne tunjon lefagyasnak.
  return Math.min(30000, Math.max(2000, Math.round(secs * 1000)))
}

// "A projektben nincs bekapcsolva a Picker API" -- sajat doboz, mert ez MAS
// hiba, mint az engedely-hiany: ujra-bejelentkezessel sosem oldodik meg.
// A linket a szerver csupa szamjegybol epiti, de itt is ellenorizzuk a
// gazdagepet: a hibauzenet a Google-tol jovo KULSO adat, es egy hibas
// felismeresbol soha ne lehessen tetszoleges cimre mutato link a felulunkon.
function _photosShowApiDisabled(data) {
  const box = document.getElementById('photosApiDisabledBox')
  if (!box) return false
  const url = String(data.enableUrl || '')
  if (!url.startsWith('https://console.cloud.google.com/')) return false
  document.getElementById('photosApiDisabledLink').href = url
  const proj = document.getElementById('photosApiDisabledProject')
  if (proj) proj.textContent = data.projectNumber ? t('photos.apidisabled_project', { id: data.projectNumber }) : ''
  box.hidden = false
  return true
}

function _photosHideApiDisabled() {
  const box = document.getElementById('photosApiDisabledBox')
  if (box) box.hidden = true
}

// "Ehhez a fiokhoz nincs Google Fotok" -- megint MAS teendo: se ujra-belepes,
// se Console-kapcsolo, hanem egyszer meg kell nyitni a photos.google.com-ot
// azzal a fiokkal. A link a HTML-ben all beegetve, nem a szerver valaszabol
// jon: a Google hibauzenete kulso adat, es abbol semmi nem lesz link.
/**
 * A depo hianya NEM egy hibauzenet, hanem egy elvegzendo beallitas.
 *
 * Ezert nem a piros hiba-dobozba megy: sajat mondattal es egy GOMBBAL jelenik
 * meg, ami atviszi a Depo oldalra. A ket eset kulon szoveget kap, mert kulon a
 * teendo -- a "nincs beallitva" egy egyszeri valasztas, a "nem erheto el" egy
 * javitas, amihez a Depo oldal vezetett helyreallitasa tartozik.
 */
function _photosShowNeedDepot(data) {
  const box = document.getElementById('photosError')
  if (!box) return false
  const unreachable = data && data.code === 'depot_unreachable'
  const cim = unreachable ? t('photos.depot_unreachable.title') : t('photos.need_depot.title')
  // Elerhetetlen depo eseten a KISZOLGALO mondja meg, mi tortent (a WSL-lel, a
  // lemezzel) -- azt idezzuk, nem talalgatunk helyette.
  const szoveg = unreachable ? String((data && data.error) || '') : t('photos.need_depot.body')
  const gomb = unreachable ? t('photos.depot_unreachable.btn') : t('photos.need_depot.btn')
  box.hidden = false
  box.innerHTML = ''
  const h = document.createElement('p')
  h.innerHTML = '<strong></strong>'
  h.firstChild.textContent = cim
  const p2 = document.createElement('p')
  p2.textContent = szoveg
  const b = document.createElement('button')
  b.className = 'btn-primary btn-compact'
  b.textContent = gomb
  b.addEventListener('click', () => switchPage('depo'))
  box.appendChild(h)
  box.appendChild(p2)
  box.appendChild(b)
  return true
}

function _photosShowNoPhotosAccount(data) {
  const box = document.getElementById('photosNoPhotosBox')
  if (!box) return false
  const who = document.getElementById('photosNoPhotosAccount')
  // Tiz bekotott fioknal a "melyikrol van szo" nem reszletkerdes.
  if (who) who.textContent = t('photos.nophotos_account', { name: String(data.account || _photosAccount || '?') })
  box.hidden = false
  return true
}

function _photosHideNoPhotosAccount() {
  const box = document.getElementById('photosNoPhotosBox')
  if (box) box.hidden = true
}

function _photosSetError(msg) {
  const box = document.getElementById('photosError')
  if (!box) return
  if (!msg) { box.hidden = true; box.innerHTML = ''; return }
  box.hidden = false
  box.innerHTML = `<p>${escapeHtml(msg)}</p>`
}

/**
 * Egy lementett kep bajtjai.
 *
 * fetch + blob, nem `<img src="/api/...">`: a dashboard `Authorization: Bearer`
 * fejleccel hitelesit, amit a fetch-burkolo tesz ra -- egy sima <img> keres
 * fejlec nelkul menne, es a 401 JSON-t kapna kep helyett.
 */
function _photosMediaUrl(id, account, thumb) {
  return '/api/photos/media?id=' + encodeURIComponent(id)
    + '&account=' + encodeURIComponent(account)
    + (thumb ? '&size=thumb' : '')
}

/**
 * Egy kep bajtjai -- eloszor a bongeszo sajat tarabol.
 *
 * Ha egyszer mar lehoztuk, a visszateres a fiokba NEM jelent ujabb letoltest:
 * a valasz a Cache Storage-bol jon. Ha megis a halozatrol kell, a valaszt
 * eltesszuk oda. A szerver ezen kivul ETag-et kuld, tehat meg a tar melloti
 * ellenorzo kerés is 304 (nulla bajt).
 */
async function _photosFetchMedia(url) {
  const store = await _photosCache()
  if (store) {
    const hit = await store.match(url)
    if (hit) return hit
    const res = await fetch(url)
    // Csak a sikeres valasz kerul a tarba; a hibauzenet nem ragadhat be.
    if (res.ok) { try { await store.put(url, res.clone()) } catch { /* megtelt a tar */ } }
    return res
  }
  return fetch(url)
}

async function _photosLoadImage(img, id, account) {
  try {
    // A RACSBA bolyegkep kell. Merve (2026-08-15): egy vegiggorgetes eddig
    // 7096 MB volt, mert a 36 videot is teljes hosszaban lehozta -- koztuk egy
    // 1,8 GB-osat. Bolyegkeppel ugyanez ~16 MB.
    const res = await _photosFetchMedia(_photosMediaUrl(id, account, true))
    if (!res.ok) { img.closest('.photo-tile')?.classList.add('photo-tile-nothumb'); return }
    const objectUrl = URL.createObjectURL(await res.blob())
    _photoBlobUrls.push(objectUrl)
    img.src = objectUrl
  } catch {
    img.closest('.photo-tile')?.classList.add('photo-tile-nothumb')
  }
}

/**
 * A kepek csak akkor toltodnek le, amikor a kepernyo koze ernek.
 *
 * Boss, 2026-08-15: "a fotok alatt lejebb tekertem [...] nem latszottak a
 * fotok. csak egy ido mulva." Mert a regi kod MINDEN kepet elindított egyszerre
 * (negyesevel), igy a lap aljara gorgetve az ottani kepek a sor vegen alltak.
 * Igy viszont ami a szemed elott van, az indul eloszor.
 */
function _photosObserveTiles(grid) {
  if (_photosTileObserver) { _photosTileObserver.disconnect(); _photosTileObserver = null }
  const tiles = Array.from(grid.querySelectorAll('.photo-tile'))
  const start = (tile) => {
    if (tile.dataset.loading) return
    tile.dataset.loading = '1'
    const img = tile.querySelector('img')
    if (img) _photosLoadImage(img, tile.dataset.id, tile.dataset.account)
  }
  // Regi bongeszo figyelo nelkul: inkabb toltson mindent, mint semmit.
  if (typeof IntersectionObserver !== 'function') { tiles.forEach(start); return }
  _photosTileObserver = new IntersectionObserver((entries, obs) => {
    for (const e of entries) {
      if (!e.isIntersecting) continue
      obs.unobserve(e.target)
      start(e.target)
    }
  }, { rootMargin: `${PHOTOS_PRELOAD_PX}px 0px` })
  tiles.forEach((tile) => _photosTileObserver.observe(tile))
}

function _photosTileHtml(p) {
  const when = p.createdTime ? new Date(p.createdTime).toLocaleDateString() : ''
  return `<div class="photo-tile" data-id="${escapeHtml(p.id)}" data-account="${escapeHtml(p.account)}" data-video="${p.isVideo ? '1' : '0'}">
    <div class="photo-tile-thumb">
      <img alt="${escapeHtml(when || t('photos.page_title'))}" loading="lazy">
      ${p.isVideo ? '<span class="photo-tile-badge"><svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg></span>' : ''}
    </div>
    <div class="photo-tile-name">${escapeHtml(when)}</div>
  </div>`
}

// === Fotok-engedely EGY GOMBBAL ===
//
// Boss, 2026-08-15: "nem tudnad ezt megcsinalni ugy hogy a marveen ban
// automatan megcsinalja ezt a parancsfuttatast [...] es a usernak odaadja a
// linket amit generalt a rendszer?"
//
// Eddig ez a doboz egy terminal-parancsot irt ki (`python3 scripts/
// google-auth.py auth <fiok>`) -- amit a Boss a Windows PowerShellbe masolt be,
// ahol nincs is python3. A szerver-oldali gepezet viszont mar megvolt: a
// Kapcsolatok oldal ugyanezt a scriptet inditja, es a linket adja vissza.
// Itt most ugyanazokat a vegpontokat hasznaljuk -- uj szerver-kod nincs.
let _photosConsentPoll = null
let _photosConsentFor = null

/**
 * A jovahagyo link beallitasa vagy TORLESE.
 *
 * Boss, 2026-08-15, a bongeszoben: "ez a jovahagyas egy KORABBI
 * bejelentkeztetesbol jott, ezert nem hasznalhato". A horgony megtartotta az
 * ELOZO folyamat linkjet, a doboz pedig inditaskor azonnal megjelent -- mire a
 * friss link megjott (1-2 masodperc), a kattintas mar megtortent a regire. A
 * Google szempontjabol az egy masik folyamat: a kod nem hasznalhato, es a
 * felhasznalo ott all, hogy "megint nem sikerult".
 *
 * Ezert: url nelkul TOROLJUK a href-et. Egy `href` nelkuli horgonyra kattintani
 * nem lehet -- ezt a bongeszo garantalja, nem egy altalunk irt orzo.
 */
function _setConsentLink(id, url) {
  const link = document.getElementById(id)
  if (!link) return
  if (url) {
    link.href = url
    link.dataset.url = url
    link.removeAttribute('aria-disabled')
    link.classList.remove('link-waiting')
  } else {
    link.removeAttribute('href')
    delete link.dataset.url
    link.setAttribute('aria-disabled', 'true')
    link.classList.add('link-waiting')
  }
}

function _photosConsentReset() {
  if (_photosConsentPoll) { clearInterval(_photosConsentPoll); _photosConsentPoll = null }
  _photosConsentFor = null
  const flow = document.getElementById('photosConsentFlow')
  if (flow) flow.hidden = true
  const paste = document.getElementById('photosConsentPaste')
  if (paste) paste.value = ''
  // A regi link nem maradhat a dobozban: a kovetkezo inditasnal az jelenne meg
  // elsonek, es egy KORABBI folyamat jovahagyasat nyitna meg.
  _setConsentLink('photosConsentLink', '')
  _connSetState('photosConsentState', '', null)
}

// Az INDITAS bukott el -- tipikusan azert, mert a bejelentkeztetes egyszerre
// csak egy lehet, es epp masik fut ("Mar fut egy Google-bejelentkeztetes
// (usalackor). Fejezd be, vagy szakitsd meg."). Ilyenkor a folyamat-dobozt be
// KELL csukni: link nincs benne, a "Megse" gombja viszont a MASIK, jogosan
// futo folyamatot lone ki. A hibat buborekban mondjuk el, mert az a becsukott
// doboz mellett is latszik.
function _photosConsentFail(msg) {
  _photosConsentReset()
  showToast(msg, 8000, true)
}

// A `force` SZANDEKOSAN szigoru osszehasonlitas: ez a fuggveny egy click-kezelo
// is, es az Event objektum igaz erteku lenne -- ugy minden elso kattintas
// eldobna egy masik, jogosan futo bejelentkeztetest.
async function _photosConsentStart(force) {
  const account = _photosAccount
  if (!account) return
  const forced = force === true
  _photosConsentFor = account
  // ELOSZOR torlunk, csak AZUTAN mutatjuk a dobozt -- kulonben egy pillanatra
  // (es egy kattintasnyi idore) az elozo folyamat linkje latszana.
  _setConsentLink('photosConsentLink', '')
  document.getElementById('photosConsentFlow').hidden = false
  _connSetState('photosConsentState', t('gconn.state_starting'), null)
  try {
    // `id`, nem `name`: a fiok MAR letezik, csak egy scope hianyzik rola. A
    // nev-agon a szerver de-duplikal, es "lackor2_2" nevre jelentkeztetne be --
    // a Fotok oldal meg tovabbra is az ures "lackor2"-t nezne.
    const res = await fetch('/api/connections/google/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(forced ? { id: account, force: true } : { id: account }),
    })
    const data = await res.json()
    if (!data.ok) {
      // "Mar fut egy Google-bejelentkeztetes (X)" -- eddig ez zsakutca volt:
      // igaz mondat, amire ezen az oldalon nem lehetett reagalni. Most a
      // szerver `code:'busy'`-t kuld a MASIK fiok nevevel, es a user egyetlen
      // kerdesre valaszol: megszakitsam-e azt, es inditsam ezt.
      if (data.code === 'busy' && !forced) {
        _photosConsentReset()
        const who = data.busyAccountId || '?'
        if (confirm(t('photos.consent_busy', { who, me: account }))) return _photosConsentStart(true)
        return
      }
      _photosConsentFail(data.error || t('common.error_save')); return
    }
  } catch (err) {
    _photosConsentFail(String(err.message || err)); return
  }
  _photosConsentPoll = setInterval(_photosConsentTick, 2000)
  _photosConsentTick()
}

async function _photosConsentTick() {
  let s
  try {
    const res = await fetch('/api/connections/google/login')
    s = await res.json()
  } catch { return }
  // Kozben mar lezarult a folyamat (egy korabbi, meg futo lekerdezes latta a
  // 'done'-t, es leallitotta a pollozast). Egy lassu valasz ne csinalja meg
  // megegyszer ugyanazt: dupla ertesites, dupla ujratoltes lenne belole.
  if (!_photosConsentPoll) return

  if (s.url) _setConsentLink('photosConsentLink', s.url)
  if (s.phase === 'consent' || s.phase === 'starting') {
    _connSetState('photosConsentState', t(s.url ? 'gconn.state_consent' : 'gconn.state_starting'), null)
  }

  if (s.phase === 'done') {
    _photosConsentReset()
    showToast(t('photos.consent_done'), 8000, true)
    // Ha a Google MAS cimre lepett be, a token nem ahhoz a fiokhoz kerult,
    // amelyiket a user nezi -- a lista ujratoltese ezt is megmutatja.
    if (s.savedAs) { _photosAccount = s.savedAs; _rememberAccount('photos', _photosAccount) }
    await loadPhotosPage()
    return
  }
  if (s.phase === 'failed') {
    if (_photosConsentPoll) { clearInterval(_photosConsentPoll); _photosConsentPoll = null }
    _connSetState('photosConsentState', t('gconn.state_failed', { msg: s.error || '' }), 'bad')
  }
}

async function _photosConsentSendPaste() {
  const input = document.getElementById('photosConsentPaste')
  const value = (input?.value || '').trim()
  if (!value) { input?.focus(); return }
  _connSetState('photosConsentState', t('photos.consent_exchanging'), null)
  try {
    const res = await fetch('/api/connections/google/login/paste', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ value }),
    })
    const data = await res.json()
    if (!data.ok) { _connSetState('photosConsentState', data.error || t('common.error_save'), 'bad'); return }
    // A bemasolt link egyszer hasznalhato -- ne maradjon a mezoben.
    if (input) input.value = ''
    if (data.savedAs) { _photosAccount = data.savedAs; _rememberAccount('photos', _photosAccount) }
    _photosConsentReset()
    showToast(t('photos.consent_done'), 8000, true)
    await loadPhotosPage()
  } catch (err) {
    _connSetState('photosConsentState', String(err.message || err), 'bad')
  }
}

// Nyilas fuggveny, hogy a click-Event ne csusszon be a `force` helyere.
document.getElementById('photosConsentBtn')?.addEventListener('click', () => _photosConsentStart())
document.getElementById('photosConsentPasteBtn')?.addEventListener('click', _photosConsentSendPaste)
document.getElementById('photosConsentCopyBtn')?.addEventListener('click', () => {
  const url = document.getElementById('photosConsentLink')?.dataset.url
  if (url) { navigator.clipboard?.writeText(url); showToast(t('gconn.copied')) }
})
document.getElementById('photosConsentCancelBtn')?.addEventListener('click', async () => {
  try { await fetch('/api/connections/google/login/cancel', { method: 'POST' }) } catch { /* ignore */ }
  _photosConsentReset()
})

async function loadPhotosPage() {
  _photosReleaseBlobs()
  const select = document.getElementById('photosAccountSelect')
  if (!select) return
  try {
    const res = await fetch('/api/photos/accounts')
    const data = await res.json()
    const accounts = data.accounts || []
    if (accounts.length === 0) {
      select.innerHTML = ''
      _photosSetError(t('photos.no_account'))
      return
    }
    _photosAccountsReady = {}
    for (const a of accounts) _photosAccountsReady[a.name] = a.ready
    if (!_photosAccount || !(_photosAccount in _photosAccountsReady)) {
      // 1. Amit a Boss legutobb kivalasztott. Ez SAJAT dontes volt, tehat
      //    erosebb minden alapertelmezesnel -- frissites utan is ez marad.
      const saved = _recallAccount('photos')
      if (saved && saved in _photosAccountsReady) {
        _photosAccount = saved
      } else {
        // 2. Kulonben olyan fiok, aminel mar megvan az engedely -- kulonben a
        //    Boss elso latasra a "nincs engedely" dobozt kapna akkor is, ha van
        //    mar hasznalhato fiokja.
        const ready = accounts.find(a => a.ready)
        _photosAccount = ready ? ready.name : (data.default || accounts[0].name)
      }
    }
    select.innerHTML = accounts.map(a =>
      `<option value="${escapeHtml(a.name)}" ${a.name === _photosAccount ? 'selected' : ''}>${escapeHtml(a.name)}${a.ready ? '' : ' - ' + escapeHtml(t('photos.account_no_scope'))}</option>`).join('')
    select.onchange = () => { _photosAccount = select.value; _rememberAccount('photos', _photosAccount); _photosRefresh() }
    await _photosRefresh()
  } catch {
    _photosSetError(t('photos.load_error'))
  }
}

/** Az oldal ujrarajzolasa a KIVALASZTOTT fiokra. */
async function _photosRefresh() {
  const grid = document.getElementById('photosGrid')
  const empty = document.getElementById('photosEmpty')
  const consent = document.getElementById('photosConsentBox')
  const addBtn = document.getElementById('photosAddBtn')
  if (!grid) return
  _photosReleaseBlobs()
  _photosSetError('')
  _photosHideApiDisabled()
  _photosHideNoPhotosAccount()

  // Nincs meg engedely ehhez a fiokhoz: itt allunk meg, es a doboz egyetlen
  // gombbal el is inditja az engedelykerest -- terminal nem kell hozza.
  const ready = !!_photosAccountsReady[_photosAccount]
  consent.hidden = ready
  addBtn.disabled = !ready
  if (!ready) {
    // Fiokot valtott, mikozben egy masikra ment az engedelykeres: a folyamat
    // reszletei akkor mar nem ehhez a fiokhoz tartoznak, ezert becsukjuk.
    if (_photosConsentFor && _photosConsentFor !== _photosAccount) _photosConsentReset()
    grid.innerHTML = ''
    empty.hidden = true
    document.getElementById('photosUsage').textContent = ''
    return
  }
  _photosConsentReset()

  grid.innerHTML = `<div class="drive-loading">${escapeHtml(t('photos.loading'))}</div>`
  try {
    const res = await fetch('/api/photos/list?account=' + encodeURIComponent(_photosAccount))
    const data = await res.json()
    if (!res.ok) { _photosSetError(data.error || t('photos.load_error')); grid.innerHTML = ''; return }
    const photos = data.photos || []
    document.getElementById('photosUsage').textContent =
      photos.length ? t('photos.usage', { count: photos.length, size: _photosHuman(data.totalBytes) }) : ''
    if (photos.length === 0) { grid.innerHTML = ''; empty.hidden = false; return }
    empty.hidden = true
    grid.innerHTML = photos.map(_photosTileHtml).join('')
    _photosBindTiles(grid)
    // A racs mar all; a kepek akkor jonnek, amikor a kepernyo koze ernek.
    _photosObserveTiles(grid)
  } catch {
    _photosSetError(t('photos.load_error'))
    grid.innerHTML = ''
  }
}

function _photosHuman(n) {
  const v = Number(n) || 0
  if (v < 1024 * 1024) return `${Math.round(v / 1024)} KB`
  if (v < 1024 * 1024 * 1024) return `${(v / (1024 * 1024)).toFixed(1)} MB`
  return `${(v / (1024 * 1024 * 1024)).toFixed(2)} GB`
}

function _photosBindTiles(grid) {
  grid.querySelectorAll('.photo-tile').forEach(tile => {
    tile.addEventListener('click', () => {
      _photosOpenLightbox(tile.getAttribute('data-id'), tile.getAttribute('data-account'),
        tile.querySelector('img')?.src || '', tile.dataset.video === '1')
    })
  })
}

/**
 * A teljes meretu kep betoltese a nagy nezetbe.
 *
 * Boss, 2026-08-15: "csak ha megnyitom nagyba akkor hasznalja a teljes
 * minoseget?" -- pontosan igy: a racs bolyegkepet kap, es a teljes fajl CSAK
 * akkor mozdul meg, amikor tenylegesen megnyitod. Kozben a mar meglevo bolyeg
 * latszik, hogy ne legyen ures a kepernyo.
 */
async function _photosLoadFull(img, id, account) {
  try {
    const res = await _photosFetchMedia(_photosMediaUrl(id, account, false))
    if (!res.ok) return
    const objectUrl = URL.createObjectURL(await res.blob())
    _photoBlobUrls.push(objectUrl)
    // Kozben a felhasznalo mar becsukhatta a nagy nezetet.
    if (img.isConnected) img.src = objectUrl
  } catch { /* marad a bolyegkep -- az is jobb, mint az ures negyzet */ }
}

function _photosOpenLightbox(id, account, alreadyLoadedUrl, isVideo) {
  const box = document.getElementById('photoLightbox')
  const stage = document.getElementById('photoLightboxStage')
  if (!box || !stage) return
  box.hidden = false
  document.getElementById('photoLightboxName').textContent = account
  stage.innerHTML = '<img alt="">'
  const img = stage.querySelector('img')
  // Eloszor a racsbol mar meglevo bolyeg: azonnal latszik valami.
  if (alreadyLoadedUrl) img.src = alreadyLoadedUrl
  // Videot NEM toltunk le egeszben. A legnagyobb sajat fajlunk 1,8 GB -- az a
  // bongeszo memoriajaba tolve osszeomlast jelentene, nem lejatszast. Marad a
  // kimerevitett kocka. (Lejatszas: kesobb, darabolt kiszolgalassal.)
  if (isVideo) return
  _photosLoadFull(img, id, account)

  const remove = document.getElementById('photoLightboxRemove')
  remove.onclick = async () => {
    if (!confirm(t('photos.remove_confirm'))) return
    try {
      const res = await fetch('/api/photos/remove', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, account }),
      })
      if (!res.ok) { showToast(t('photos.remove_failed')); return }
      // A bongeszo tarabol is ki kell venni, kulonben a torolt kep bajtjai ott
      // maradnak a gepen -- egy torles maradjon torles.
      const store = await _photosCache()
      if (store) {
        for (const thumb of [true, false]) {
          try { await store.delete(_photosMediaUrl(id, account, thumb)) } catch { /* nem volt benne */ }
        }
      }
      _photosCloseLightbox()
      showToast(t('photos.remove_done'))
      _photosRefresh()
    } catch {
      showToast(t('photos.remove_failed'))
    }
  }
}

function _photosCloseLightbox() {
  const box = document.getElementById('photoLightbox')
  if (!box || box.hidden) return
  box.hidden = true
  document.getElementById('photoLightboxStage').innerHTML = ''
}

/**
 * Kepek hozzaadasa: session a Google-nel, a valaszto uj lapon, aztan varunk.
 *
 * A pickerUri-t NEM lehet iframe-be tenni (a Google tiltja), ezert nyilik uj
 * lapon. A bajtok lehozasat a SZERVER vegzi, amint a felhasznalo vegzett --
 * mert a Google linkje 60 perc mulva halott.
 */
async function _photosStartPicker() {
  const addBtn = document.getElementById('photosAddBtn')
  addBtn.disabled = true
  // Az ELOZO probalkozas uzenetei tunjenek el, mielott elindulunk: kulonben a
  // felhasznalo egy mar megoldott hibat lat, es azt hiszi, megint elszallt.
  // (Ugyanaz a hibafajta, mint a regi jovahagyo link: a felulet emlekezett.)
  _photosHideApiDisabled()
  _photosHideNoPhotosAccount()
  _photosSetError('')
  try {
    const res = await fetch('/api/photos/session', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ account: _photosAccount }),
    })
    const data = await res.json()
    if (!res.ok) {
      addBtn.disabled = false
      if (data.code === 'no_depot' || data.code === 'depot_unreachable') {
        if (_photosShowNeedDepot(data)) return
      }
      if (data.code === 'no_scope') { _photosAccountsReady[_photosAccount] = false; _photosRefresh(); return }
      // Ha a linket nem ismerjuk fel biztonsagosnak, NEM nyelunk el semmit:
      // jojjon a nyers uzenet, az tobbet er a nemasagnal.
      if (data.code === 'api_disabled' && _photosShowApiDisabled(data)) return
      if (data.code === 'no_photos_account' && _photosShowNoPhotosAccount(data)) return
      _photosSetError(data.error || t('photos.session_failed'))
      return
    }
    // Elobb nyitjuk meg a lapot, csak utana valtunk varakozo allapotba: ha a
    // bongeszo blokkolja a felugrot, a felhasznalo ne egy vegtelen porgo
    // karikat nezzen.
    const win = window.open(data.pickerUri, '_blank')
    if (!win) {
      addBtn.disabled = false
      _photosSetError(t('photos.popup_blocked'))
      return
    }
    document.getElementById('photosWaiting').hidden = false
    _photosPoll(data.sessionId, _photosPollMs(data.pollInterval))
  } catch {
    addBtn.disabled = false
    _photosSetError(t('photos.session_failed'))
  }
}

/**
 * Varakozas a valasztasra.
 *
 * KET vedelem van benne, es mindketto egy MERT hibabol szuletett (Boss,
 * 2026-08-15: "Picker API 404: The entity you requested does not exist"):
 *
 * 1. ATFEDES. A `setInterval` nem varja meg az elozo kort. Amikor a valasztas
 *    kesz, a valasz mar nem masodpercek alatt jon: a szerver ekkor tolti le a
 *    kepeket. Sok kepnel ez tovabb tart, mint a kerdezes koze -- igy KETTO (majd
 *    harom...) keres futott egyszerre ugyanarra a session-re. Az elso vegzett es
 *    elengedte a session-t, a masodik pedig a mar nem letezo session-t kerdezte:
 *    ez a 404. Ezert egyszerre csak EGY kor lehet a levegoben.
 * 2. ELAVULT VALASZ. Ami mar elindult, azt nem lehet visszahivni: a leallitas
 *    utan beeso valasz kulonben felulirna a kesz allapotot (vagy hibat mutatna
 *    egy mar SIKERES behozatal utan). Ezert minden kornek sorszama van, es a
 *    nem az aktualis korbol erkezo valasz a szemetbe megy.
 */
let _photosPollGen = 0

/**
 * Mi tortent a behozatalkor -- emberi mondatban, TELJES elszamolassal.
 *
 * A "duplikatum" nem hiba, es nem is elhagyhato reszlet: ha a Boss kivalaszt
 * tiz kepet es csak harom jon be, tudnia kell, hogy a tobbi mar itt volt, nem
 * pedig elveszett. (Boss, 2026-08-15: "duplikatumokat ne toltson le".)
 *
 * 2026-08-16: a regi valtozat NEM szamolt el a kijelolessel. 194 kijelolt kepbol
 * nulla jott le, es a felulet ebbol annyit mondott, hogy kesz -- a Boss meg azt
 * latta, hogy "a fotokba nem jott le semmilyen foto". Ezert most a kijelolt
 * darabszambol INDUL az uzenet, es minden szal el van szamolva:
 *   kijelolt = uj + mar megvolt + egyforma + nem sikerult.
 * Ha ez nem jon ki, a maradek is kiirodik -- inkabb legyen csunya a mondat,
 * mint hazug.
 */
function _photosAddedMsg(data) {
  const selected = Number(data.selected) || 0
  const saved = Number(data.saved) || 0
  const already = Number(data.already) || 0
  const dup = Number(data.duplicates) || 0
  const failed = Number(data.failed) || 0
  const cleaned = Number(data.cleaned) || 0
  if (!selected && !saved && !already && !dup && !failed) return t('photos.added_none')
  const parts = []
  parts.push(saved ? t('photos.result.saved', { count: saved }) : t('photos.result.nothing_new'))
  if (already) parts.push(t('photos.result.already', { count: already }))
  if (dup) parts.push(t('photos.result.duplicates', { count: dup }))
  if (failed) parts.push(t('photos.result.failed', { count: failed }))
  // Ami egyik szalba sem fert bele: sosem hallgatjuk el. Ha ez nem nulla, az
  // magaban is hibajelzes -- valami elveszett a szamolas kozben.
  const rest = selected - saved - already - dup - failed
  if (rest > 0) parts.push(t('photos.result.unaccounted', { count: rest }))
  let msg = selected
    ? `${t('photos.result.head', { selected })} ${parts.join(', ')}.`
    : `${parts.join(', ')}.`
  if (cleaned) msg += ` ${t('photos.cleaned', { count: cleaned })}`
  // A lista nem jott vegig: a `selected` KEVESEBB, mint amit kijeloltek.
  if (data.partial) msg += ` ${t('photos.result.partial')}`
  return msg
}

function _photosPoll(sessionId, intervalMs) {
  const account = _photosAccount
  _photosStopPoll()
  const gen = ++_photosPollGen
  let inFlight = false
  _photosPollTimer = setInterval(async () => {
    if (inFlight) return
    inFlight = true
    try {
      const res = await fetch('/api/photos/session?sessionId=' + encodeURIComponent(sessionId)
        + '&account=' + encodeURIComponent(account))
      const data = await res.json()
      if (gen !== _photosPollGen) return
      if (!res.ok) {
        _photosStopPoll()
        if (data.code === 'api_disabled' && _photosShowApiDisabled(data)) return
        if (data.code === 'no_photos_account' && _photosShowNoPhotosAccount(data)) return
        // A valaszto ablak lejart vagy elveszett: ez nem elromlott rendszer,
        // csak ujra kell kezdeni -- emberi mondattal, nem a Google 404-evel.
        if (data.code === 'session_gone') { _photosSetError(t('photos.session_gone')); return }
        _photosSetError(data.error || t('photos.session_failed'))
        return
      }
      if (!data.done) return
      _photosStopPoll()
      showToast(_photosAddedMsg(data))
      _photosRefresh()
    } catch {
      if (gen !== _photosPollGen) return
      _photosStopPoll()
      _photosSetError(t('photos.session_failed'))
    } finally {
      inFlight = false
    }
  }, intervalMs)
}

function _photosStopPoll() {
  // A sorszam emelese az, amitol a mar uton levo valasz nem szol bele tobbe.
  _photosPollGen++
  if (_photosPollTimer) { clearInterval(_photosPollTimer); _photosPollTimer = null }
  const w = document.getElementById('photosWaiting')
  if (w) w.hidden = true
  const b = document.getElementById('photosAddBtn')
  if (b) b.disabled = !_photosAccountsReady[_photosAccount]
}

document.getElementById('photosAddBtn')?.addEventListener('click', _photosStartPicker)
// Ujraprobalas: ugyanaz, mint a "Kepek hozzaadasa", csak elobb eltunik a doboz
// -- ha a Google mar atallt, egybol a kepvalaszto nyilik; ha meg nem, a doboz
// visszajon, es a user latja, hogy meg varni kell.
document.getElementById('photosApiDisabledRetryBtn')?.addEventListener('click', () => {
  _photosHideApiDisabled()
  _photosStartPicker()
})
// Ugyanez a "meg nincs Google Fotok" doboznal: ha a felhasznalo kozben
// megnyitotta a photos.google.com-ot, egybol a kepvalaszto nyilik.
document.getElementById('photosNoPhotosRetryBtn')?.addEventListener('click', () => {
  _photosHideNoPhotosAccount()
  _photosStartPicker()
})
document.getElementById('photosCancelBtn')?.addEventListener('click', _photosStopPoll)
document.getElementById('photoLightboxClose')?.addEventListener('click', _photosCloseLightbox)
document.getElementById('photoLightbox')?.addEventListener('click', (e) => {
  // Csak a hatterre kattintva zar: a kepen belul a kattintas ne tuntesse el.
  if (e.target.id === 'photoLightbox' || e.target.id === 'photoLightboxStage') _photosCloseLightbox()
})
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') _photosCloseLightbox() })

// Self-documenting list of integrations Marveen knows about that live in the
// Vault, so landing here (e.g. from the Overview "unused capabilities" box)
// explains WHAT each key is for instead of a bare free-text field. Reuses
// CAPABILITY_INFO -- add new entries there (with a vaultId) and they show
// up here automatically.
function renderVaultKnownIntegrations() {
  const panel = document.getElementById('vaultKnownPanel')
  if (!panel) return
  // A key can live as a top-level entry OR as a bound field on a card -- that
  // is the whole point of bindings, and it is how the three openrouter-* keys
  // now sit on one "OpenRouter" card. Checking entry ids alone reported the
  // fleet key as missing while it was right there and working (Boss:
  // "openruternel meg mindig api kulcsot hianyol"). An empty bound field does
  // NOT count as configured: the binding exists, the key does not.
  const configuredIds = new Set(_vaultSecrets.flatMap(s => [
    s.id,
    ...(s.fields || []).filter(f => f.bindingId && f.hasValue).map(f => f.bindingId),
  ]))
  const items = Object.values(CAPABILITY_INFO).map(info => {
    const configured = configuredIds.has(info.vaultId)
    const help = configured ? '' : `<div class="vault-known-help">
        <div class="vault-known-steps">${escapeHtml(t(info.stepsKey))}</div>
        <a class="vault-known-link" href="${info.helpUrl}" target="_blank" rel="noopener noreferrer">${escapeHtml(t('vault.known.get_key_link'))} →</a>
      </div>`
    return `<div class="vault-known-item" data-vault-id="${escapeHtml(info.vaultId)}" data-label-key="${escapeHtml(info.labelKey)}">
      <div class="vault-known-row">
        <div class="vault-known-text">
          <div class="vault-known-label">${escapeHtml(t(info.labelKey))}</div>
          <div class="vault-known-desc">${escapeHtml(t(info.descKey))}</div>
        </div>
        <div class="vault-known-status ${configured ? 'vault-known-status-ok' : 'vault-known-status-missing'}">${configured ? t('vault.known.configured') : t('vault.known.missing')}</div>
      </div>
      ${help}
    </div>`
  }).join('')
  panel.innerHTML = `<div class="vault-known-title">${escapeHtml(t('vault.known.title'))}</div><div class="vault-known-list">${items}</div>`
  panel.querySelectorAll('.vault-known-item').forEach(el => {
    el.addEventListener('click', () => {
      const id = el.getAttribute('data-vault-id')
      if (configuredIds.has(id)) return
      const labelKey = el.getAttribute('data-label-key')
      const addPanel = document.getElementById('vaultAddPanel')
      addPanel.hidden = false
      document.getElementById('vaultPageIdInput').value = id
      document.getElementById('vaultPageLabelInput').value = t(labelKey)
      document.getElementById('vaultPageValueInput').focus()
    })
  })
}


