// Whole-card starting points. A card is a PLACE, and most places come in a few
// familiar shapes -- Boss: "ott kerheto, csak kivalaszthato minden ... azt adja
// meg, amit eppen meg tud adni". A template just adds the usual rows; every one
// of them can be renamed, removed or added to afterwards.
const VAULT_TEMPLATES = [
  { key: 'website',  i18n: 'vault.tpl.website',  fields: ['link', 'username', 'password', 'totp'] },
  { key: 'bank',     i18n: 'vault.tpl.bank',     fields: ['link', 'username', 'password', 'account', 'pin'] },
  { key: 'card',     i18n: 'vault.tpl.card',     fields: ['cardnum', 'cardexp', 'cvc', 'pin', 'iban'] },
  { key: 'api',      i18n: 'vault.tpl.api',      fields: ['link', 'apikey', 'token', 'expires'] },
  { key: 'wallet',   i18n: 'vault.tpl.wallet',   fields: ['link', 'password', 'seed', 'recovery'] },
  { key: 'wifi',     i18n: 'vault.tpl.wifi',     fields: ['username', 'wifi'] },
  { key: 'software', i18n: 'vault.tpl.software', fields: ['license', 'contact', 'link'] },
]

function _vaultFieldRowHtml(field) {
  const f = field || { label: '', kind: 'text', value: '', note: '' }
  const kinds = ['text', 'secret', 'url', 'date']
  return `
    <div class="vault-field-row">
      <div class="vault-field-row-top">
        <input type="text" class="input vault-f-label" value="${escapeAttr(f.label || '')}" placeholder="${escapeAttr(t('vault.field.row_name'))}">
        <select class="input vault-f-kind">
          ${kinds.map(k => `<option value="${k}"${(f.kind || 'text') === k ? ' selected' : ''}>${escapeHtml(t('vault.kind.' + k))}</option>`).join('')}
        </select>
        <button type="button" class="btn-secondary btn-compact vault-f-remove" title="${escapeAttr(t('vault.field.remove'))}">✕</button>
      </div>
      <div class="vault-field-row-value">
        <input type="${(f.kind || 'text') === 'secret' ? 'password' : 'text'}" class="input vault-f-value" value="${escapeAttr(f.value || '')}" placeholder="${escapeAttr(t('vault.field.row_value'))}">
        <button type="button" class="btn-secondary btn-compact vault-f-eye" title="${escapeAttr(t('vault.btn.show'))}">👁</button>
        <button type="button" class="btn-secondary btn-compact vault-f-copy" title="${escapeAttr(t('vault.field.copy'))}">⧉</button>
      </div>
      <input type="text" class="input vault-f-note" value="${escapeAttr(f.note || '')}" placeholder="${escapeAttr(t('vault.field.row_note'))}">
      <input type="text" class="input vault-f-binding" value="${escapeAttr(f.bindingId || '')}" placeholder="${escapeAttr(t('vault.field.row_binding'))}" title="${escapeAttr(t('vault.field.row_binding_tip'))}">
    </div>`
}

// Wires one editor instance: preset buttons append rows, each row can be
// revealed, copied and removed. Kept per-container so the add panel and any
// open card editor never fight over the same handlers.

// ---- tag picker -------------------------------------------------------------
// Chips for what this card carries, one click to apply a tag that already
// exists, and a deliberate "add" step for a genuinely new one -- with a warning
// when the new one looks like a mistyping of an existing tag. The server snaps
// case/accent variants onto the spelling already in use regardless; this is the
// part that stops a typo from becoming a permanent second group.

function _vaultTagKey(tag) {
  return (tag || '').normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
}

// Damerau-Levenshtein: a swapped pair of letters is one typo, not two.
function _vaultEditDistance(a, b) {
  if (a === b) return 0
  if (Math.abs(a.length - b.length) > 2) return 3
  const d = Array.from({ length: a.length + 1 }, (_, i) =>
    Array.from({ length: b.length + 1 }, (_, j) => (i === 0 ? j : j === 0 ? i : 0)))
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost)
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1)
    }
  }
  return d[a.length][b.length]
}

function _vaultSimilarTags(tag, known) {
  const key = _vaultTagKey(tag)
  if (key.length < 3) return []
  return known.filter(k => {
    const other = _vaultTagKey(k)
    return other && other !== key && _vaultEditDistance(key, other) <= (key.length <= 5 ? 1 : 2)
  })
}

function _vaultTagEditorHtml(tags) {
  const current = tags || []
  return `
    <div class="vault-tag-editor" data-tags="${escapeAttr(JSON.stringify(current))}">
      <div class="vault-tag-chips"></div>
      <div class="vault-tag-known"></div>
      <div class="vault-tag-add">
        <input type="text" class="input vault-tag-input" placeholder="${escapeAttr(t('vault.tag.new_ph'))}">
        <button type="button" class="btn-secondary btn-compact vault-tag-add-btn">+ ${escapeHtml(t('vault.tag.add'))}</button>
      </div>
      <div class="vault-tag-warn" hidden></div>
    </div>`
}

function _initVaultTagEditor(container) {
  const root = container.querySelector('.vault-tag-editor')
  if (!root) return
  let tags = []
  try { tags = JSON.parse(root.dataset.tags || '[]') } catch { tags = [] }

  const chips = root.querySelector('.vault-tag-chips')
  const known = root.querySelector('.vault-tag-known')
  const input = root.querySelector('.vault-tag-input')
  const warn = root.querySelector('.vault-tag-warn')

  const has = (tag) => tags.some(x => _vaultTagKey(x) === _vaultTagKey(tag))
  const render = () => {
    root.dataset.tags = JSON.stringify(tags)
    chips.innerHTML = tags.length
      ? tags.map(tag => `<span class="vault-tag-chip">${escapeHtml(tag)}<button type="button" class="vault-tag-chip-x" data-tag="${escapeAttr(tag)}">✕</button></span>`).join('')
      : `<span class="vault-tag-none">${escapeHtml(t('vault.tag.none'))}</span>`
    const available = _vaultAllTags.filter(x => !has(x))
    known.innerHTML = available.length
      ? `<span class="vault-tag-known-hint">${escapeHtml(t('vault.tag.pick'))}</span>` +
        available.map(x => `<button type="button" class="vault-tag-known-btn" data-tag="${escapeAttr(x)}">${escapeHtml(x)}</button>`).join('')
      : ''
  }
  const add = (raw) => {
    const tag = (raw || '').trim()
    if (!tag || has(tag)) { input.value = ''; warn.hidden = true; return }
    // Snap to an existing spelling when it is the same tag written differently.
    const existing = _vaultAllTags.find(x => _vaultTagKey(x) === _vaultTagKey(tag))
    if (existing) { tags.push(existing); input.value = ''; warn.hidden = true; render(); return }
    const close = _vaultSimilarTags(tag, _vaultAllTags)
    if (close.length) {
      // Never rewrite silently: offer the existing one, and let the new one
      // through only if it is confirmed by pressing Add again.
      warn.hidden = false
      warn.innerHTML = `${escapeHtml(t('vault.tag.similar'))} ` +
        close.map(c => `<button type="button" class="vault-tag-known-btn" data-tag="${escapeAttr(c)}">${escapeHtml(c)}</button>`).join('') +
        ` <button type="button" class="vault-tag-known-btn vault-tag-force" data-tag="${escapeAttr(tag)}">${escapeHtml(t('vault.tag.keep_new'))}</button>`
      return
    }
    tags.push(tag); input.value = ''; warn.hidden = true; render()
  }

  root.addEventListener('click', (e) => {
    const x = e.target.closest('.vault-tag-chip-x')
    if (x) { tags = tags.filter(tag => tag !== x.dataset.tag); render(); return }
    const pick = e.target.closest('.vault-tag-known-btn')
    if (pick) {
      if (!has(pick.dataset.tag)) tags.push(pick.dataset.tag)
      input.value = ''; warn.hidden = true; render(); return
    }
    if (e.target.closest('.vault-tag-add-btn')) add(input.value)
  })
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); add(input.value) }
  })
  render()
}

function _collectVaultTags(container) {
  const root = container.querySelector('.vault-tag-editor')
  if (!root) return []
  try { return JSON.parse(root.dataset.tags || '[]') } catch { return [] }
}

// A card's fields live in named GROUPS. A flat list cannot answer the question
// that matters when you read the card back (Boss, 2026-08-10): "azon a jelszo
// mihez tartozik?" -- a password under a bank card and a password under a
// website login look identical in one column. A template now creates a box with
// its name on it, and the fields it adds live inside that box; extra fields are
// added into a specific box too, so "Jelszó" is always visibly the password OF
// something. This is the same "sections" idea the big managers use.

function _vaultSectionHtml(section, fields) {
  return `
    <div class="vault-section">
      <div class="vault-section-head">
        <input type="text" class="input vault-section-name" value="${escapeAttr(section || '')}" placeholder="${escapeAttr(t('vault.section.name_ph'))}">
        <button type="button" class="btn-secondary btn-compact vault-section-remove" title="${escapeAttr(t('vault.section.remove'))}">✕</button>
      </div>
      <div class="vault-fields-rows">${(fields || []).map(f => _vaultFieldRowHtml(f)).join('')}</div>
      <div class="vault-field-presets">
        ${VAULT_FIELD_PRESETS.map(p => `<button type="button" class="btn-secondary btn-compact" data-preset="${p.key}">+ ${escapeHtml(t(p.i18n))}</button>`).join('')}
      </div>
    </div>`
}

/** Group stored fields the way they were arranged, unnamed group first. */
function _vaultGroupFields(fields) {
  const order = []
  const bySection = new Map()
  for (const f of (fields || [])) {
    const key = f.section || ''
    if (!bySection.has(key)) { bySection.set(key, []); order.push(key) }
    bySection.get(key).push(f)
  }
  if (order.length === 0) order.push('') , bySection.set('', [])
  return order.map(section => ({ section, fields: bySection.get(section) }))
}

function _vaultUniqueSectionName(base, existing) {
  const taken = new Set(existing.map(x => (x || '').toLowerCase()))
  if (!taken.has(base.toLowerCase())) return base
  for (let n = 2; n < 100; n++) {
    const c = `${base} ${n}`
    if (!taken.has(c.toLowerCase())) return c
  }
  return `${base} ${Date.now()}`
}

function _vaultSectionNames(container) {
  return [...container.querySelectorAll('.vault-section-name')].map(i => i.value.trim())
}

function _initVaultFieldEditor(container) {
  const sections = container.querySelector('.vault-sections')

  // Templates create a WHOLE box, named after the template, so the fields it
  // brings are visibly the fields of that thing.
  container.querySelector('.vault-field-templates')?.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-template]')
    if (!btn) return
    const tpl = VAULT_TEMPLATES.find(x => x.key === btn.dataset.template)
    if (!tpl) return
    const name = _vaultUniqueSectionName(t(tpl.i18n), _vaultSectionNames(container))
    const rows = tpl.fields
      .map(k => VAULT_FIELD_PRESETS.find(p => p.key === k))
      .filter(Boolean)
      .map(p => ({ label: t(p.i18n), kind: p.kind, value: '', note: '' }))
    sections.insertAdjacentHTML('beforeend', _vaultSectionHtml(name, rows))
    sections.lastElementChild.scrollIntoView({ block: 'nearest' })
  })

  container.querySelector('.vault-add-section')?.addEventListener('click', () => {
    sections.insertAdjacentHTML('beforeend', _vaultSectionHtml('', []))
    sections.lastElementChild.querySelector('.vault-section-name').focus()
  })

  sections?.addEventListener('click', (e) => {
    const section = e.target.closest('.vault-section')
    if (!section) return
    // Add a single field INTO this box, not into a shared pile.
    const presetBtn = e.target.closest('[data-preset]')
    if (presetBtn) {
      const preset = VAULT_FIELD_PRESETS.find(p => p.key === presetBtn.dataset.preset)
      if (!preset) return
      const label = preset.key === 'custom' ? '' : t(preset.i18n)
      const rows = section.querySelector('.vault-fields-rows')
      rows.insertAdjacentHTML('beforeend', _vaultFieldRowHtml({ label, kind: preset.kind, value: '', note: '' }))
      rows.lastElementChild.querySelector(preset.key === 'custom' ? '.vault-f-label' : '.vault-f-value')?.focus()
      return
    }
    if (e.target.closest('.vault-section-remove')) {
      // Removing a box removes its fields with it, so require the box to be
      // empty of values first -- deleting a password by tidying up a group
      // would be a nasty surprise.
      const hasValue = [...section.querySelectorAll('.vault-f-value')].some(i => i.value)
      if (hasValue && !confirm(t('vault.section.remove_confirm'))) return
      section.remove()
      if (!sections.querySelector('.vault-section')) sections.insertAdjacentHTML('beforeend', _vaultSectionHtml('', []))
      return
    }
    const row = e.target.closest('.vault-field-row')
    if (!row) return
    if (e.target.closest('.vault-f-remove')) { row.remove(); return }
    if (e.target.closest('.vault-f-eye')) {
      const inp = row.querySelector('.vault-f-value')
      inp.type = inp.type === 'password' ? 'text' : 'password'
      return
    }
    if (e.target.closest('.vault-f-copy')) {
      navigator.clipboard?.writeText(row.querySelector('.vault-f-value').value)
      showToast(t('vault.field.copied'))
    }
  })

  sections?.addEventListener('change', (e) => {
    if (!e.target.classList?.contains('vault-f-kind')) return
    const row = e.target.closest('.vault-field-row')
    row.querySelector('.vault-f-value').type = e.target.value === 'secret' ? 'password' : 'text'
  })

  container.querySelector('.vault-history')?.addEventListener('click', (e) => {
    const row = e.target.closest('.vault-history-row')
    if (!row) return
    if (e.target.closest('.vault-h-eye')) {
      const inp = row.querySelector('.vault-history-value')
      inp.type = inp.type === 'password' ? 'text' : 'password'
    } else if (e.target.closest('.vault-h-copy')) {
      navigator.clipboard?.writeText(row.querySelector('.vault-history-value').value)
      showToast(t('vault.field.copied'))
    }
  })
}

function _collectVaultFields(container) {
  const out = []
  for (const section of container.querySelectorAll('.vault-section')) {
    const name = section.querySelector('.vault-section-name').value.trim()
    for (const row of section.querySelectorAll('.vault-field-row')) {
      const f = {
        label: row.querySelector('.vault-f-label').value.trim(),
        kind: row.querySelector('.vault-f-kind').value,
        value: row.querySelector('.vault-f-value').value,
        note: row.querySelector('.vault-f-note').value.trim(),
        bindingId: row.querySelector('.vault-f-binding').value.trim(),
        section: name,
      }
      if (f.label || f.value || f.note) out.push(f)
    }
  }
  return out
}

function _vaultHistoryHtml(history) {
  if (!history || !history.length) return ''
  return `
    <div class="vault-history">
      <div class="vault-fields-title">${escapeHtml(t('vault.history.title'))}</div>
      ${history.map(h => `
        <div class="vault-history-row">
          <span class="vault-history-label">${escapeHtml(h.label)}</span>
          <span class="vault-history-at">${escapeHtml((h.at || '').slice(0, 16).replace('T', ' '))}</span>
          <input type="password" class="input vault-history-value" value="${escapeAttr(h.value)}" readonly>
          <button type="button" class="btn-secondary btn-compact vault-h-eye">👁</button>
          <button type="button" class="btn-secondary btn-compact vault-h-copy">⧉</button>
        </div>`).join('')}
    </div>`
}

function _vaultFieldEditorHtml(fields) {
  const groups = _vaultGroupFields(fields)
  return `
    <div class="vault-fields-editor">
      <div class="vault-fields-title">${escapeHtml(t('vault.fields.title'))}</div>
      <div class="vault-sections">${groups.map(g => _vaultSectionHtml(g.section, g.fields)).join('')}</div>
      <div class="vault-field-templates">
        <span class="vault-tpl-hint">${escapeHtml(t('vault.tpl.hint'))}</span>
        ${VAULT_TEMPLATES.map(tp => `<button type="button" class="btn-secondary btn-compact" data-template="${tp.key}">${escapeHtml(t(tp.i18n))}</button>`).join('')}
        <button type="button" class="btn-secondary btn-compact vault-add-section">+ ${escapeHtml(t('vault.section.add'))}</button>
      </div>
    </div>`
}


function renderVaultGrid(secrets) {
  const list = document.getElementById('vaultPageList')
  const empty = document.getElementById('vaultPageEmpty')
  list.innerHTML = ''
  if (secrets.length === 0) { empty.hidden = false; return }
  empty.hidden = true
  for (const s of secrets) {
    const card = document.createElement('div')
    card.className = 'vault-card'
    card.dataset.id = s.id
    const date = new Date(s.updatedAt).toLocaleDateString('hu-HU')
    const bindingCount = _vaultBindings.filter(b => b.vaultSecretId === s.id).length
    const bindingBadge = bindingCount > 0 ? `<span class="vault-binding-badge" title="${bindingCount} kotes">${bindingCount} kotes</span>` : ''
    const categoryBadge = s.category ? `<span class="vault-category-badge">${escapeHtml(s.category)}</span>` : ''
    const urlLine = s.url ? `<a class="vault-card-url" href="${escapeAttr(/^https?:\/\//i.test(s.url) ? s.url : 'https://' + s.url)}" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation()">${escapeHtml(s.url)}</a>` : ''
    const notesLine = s.notes ? `<div class="vault-card-notes">${escapeHtml(s.notes)}</div>` : ''
    // Field STRUCTURE on the closed card: what this entry holds and why, with
    // no values -- the list endpoint never sends them. Open the card to see or
    // change a value.
    const fieldsLine = (s.fields && s.fields.length)
      ? `<div class="vault-card-fields">${s.fields.map(f => `
          <span class="vault-card-field" title="${escapeAttr(f.note || '')}">
            <span class="vault-card-field-name">${escapeHtml(f.label || t('vault.field.unnamed'))}</span>
            ${f.hasValue ? '' : `<span class="vault-card-field-empty">${escapeHtml(t('vault.field.empty'))}</span>`}
            ${f.bindingId ? `<span class="vault-card-field-binding">${escapeHtml(f.bindingId)}</span>` : ''}
            ${f.note ? '<span class="vault-card-field-note-dot">•</span>' : ''}
          </span>`).join('')}</div>`
      : ''
    card.innerHTML = `<div class="vault-card-header"><div class="vault-card-icon"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg></div><div class="vault-card-title"><div class="vault-card-id">${escapeHtml(s.id)} ${bindingBadge}${categoryBadge}</div>${s.label !== s.id ? `<div class="vault-card-label">${escapeHtml(s.label)}</div>` : ''}${urlLine}${notesLine}${fieldsLine}</div><div class="vault-card-meta">${date}</div></div><div class="vault-card-actions"><button class="btn-secondary btn-compact vault-card-reveal" data-id="${escapeHtml(s.id)}"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>${t('vault.btn.show')}</button><button class="btn-secondary btn-compact vault-card-edit" data-id="${escapeHtml(s.id)}" data-label="${escapeHtml(s.label)}"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>${t('vault.btn.edit')}</button><button class="btn-secondary btn-compact vault-card-delete" data-id="${escapeHtml(s.id)}"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2"/></svg>${t('vault.btn.delete')}</button></div>`
    list.appendChild(card)
  }
  list.querySelectorAll('.vault-card-reveal').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id = btn.getAttribute('data-id')
      const card = btn.closest('.vault-card')
      const existing = card.querySelector('.vault-card-value')
      if (existing) { existing.remove(); btn.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg> ${t('vault.btn.show')}`; return }
      const res = await fetch(`/api/vault/${encodeURIComponent(id)}`)
      const data = await res.json()
      // A place-card keeps its values in FIELDS and may have no primary value
      // at all -- this used to bail silently, so Mutat did nothing on exactly
      // the cards the new model encourages (Boss: "az openruter modositja es
      // mutatja nem mukodik"). Say so instead of doing nothing.
      {
        const valEl = document.createElement('div')
        valEl.className = 'vault-card-value'
        if (data.value) {
          valEl.textContent = data.value
        } else {
          valEl.classList.add('vault-card-value-empty')
          valEl.textContent = t('vault.value.in_fields')
        }
        card.appendChild(valEl)
        btn.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg> ${t('vault.btn.hide')}`
      }
    })
  })
  list.querySelectorAll('.vault-card-edit').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id = btn.getAttribute('data-id')
      const label = btn.getAttribute('data-label')
      const card = btn.closest('.vault-card')
      const existing = card.querySelector('.vault-card-edit-form')
      if (existing) { existing.remove(); return }
      card.querySelector('.vault-card-value')?.remove()
      const res = await fetch(`/api/vault/${encodeURIComponent(id)}`)
      const data = await res.json()
      // No `if (!data.value) return` here: a card with no primary value is now
      // normal, and refusing to open its editor made the whole card read-only.
      if (data.error) { showToast(data.error); return }
      const secret = _vaultSecrets.find(s => s.id === id) || {}
      const form = document.createElement('div')
      form.className = 'vault-card-edit-form'
      // Everything the entry holds, editable in place -- name, description,
      // category, link, notes, the primary value AND every extra field. Boss,
      // 2026-08-10: "ne csak azt lassam hogy a kulcsot lehet valtoztatni es
      // semmi mast ... barmit amit a felvetelkor bevittem lehessen modositani".
      form.innerHTML = `
        <label class="vault-field-label">${escapeHtml(t('vault.field.desc_label'))}</label>
        <input type="text" class="input vault-edit-label" value="${escapeAttr(secret.label || '')}" style="font-size:13px;margin-bottom:6px">
        <label class="vault-field-label">${escapeHtml(t('vault.field.value_label'))}</label>
        <div class="vault-field-row-value" style="margin-bottom:6px">
          <input type="password" class="input vault-edit-value" value="${escapeAttr(data.value)}" style="font-size:13px">
          <button type="button" class="btn-secondary btn-compact vault-edit-value-eye" title="${escapeAttr(t('vault.btn.show'))}">👁</button>
        </div>
        <label class="vault-field-label">${escapeHtml(t('vault.field.tags_label'))}</label>
        ${_vaultTagEditorHtml(_vaultTagsOf(secret))}
        <label class="vault-field-label">${escapeHtml(t('vault.field.url_label'))}</label>
        <input type="text" class="input vault-edit-url" value="${escapeAttr(secret.url || '')}" style="font-size:13px;margin-bottom:6px">
        <label class="vault-field-label">${escapeHtml(t('vault.field.notes_label'))}</label>
        <textarea class="input vault-edit-notes" rows="2" style="font-size:13px;margin-bottom:6px">${escapeHtml(secret.notes || '')}</textarea>
        ${_vaultFieldEditorHtml(data.fields || [])}
        ${_vaultHistoryHtml(data.history)}
        <button class="btn-primary btn-compact vault-edit-save">${t('vault.btn.save')}</button> <button class="btn-secondary btn-compact vault-edit-cancel">${t('vault.btn.cancel')}</button>`
      card.appendChild(form)
      _initVaultFieldEditor(form)
      _initVaultTagEditor(form)
      form.querySelector('.vault-edit-value-eye').addEventListener('click', () => {
        const inp = form.querySelector('.vault-edit-value')
        inp.type = inp.type === 'password' ? 'text' : 'password'
      })
      const input = form.querySelector('.vault-edit-value')
      input.focus()
      input.select()
      form.querySelector('.vault-edit-cancel').addEventListener('click', () => form.remove())
      form.querySelector('.vault-edit-save').addEventListener('click', async () => {
        const newVal = input.value
        const fieldsForCheck = _collectVaultFields(form)
        if (!newVal && !fieldsForCheck.some(f => f.value)) { showToast(t('vault.err.need_value')); return }
        const tags = _collectVaultTags(form)
        const url = form.querySelector('.vault-edit-url').value.trim()
        const notes = form.querySelector('.vault-edit-notes').value.trim()
        const newLabel = form.querySelector('.vault-edit-label').value.trim() || id
        const fields = fieldsForCheck
        const saveBtn = form.querySelector('.vault-edit-save')
        saveBtn.disabled = true
        saveBtn.textContent = '...'
        const res = await fetch('/api/vault', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id, label: newLabel, value: newVal, tags, url, notes, fields }),
        })
        if (!res.ok) {
          const e = await res.json().catch(() => ({}))
          showToast('Frissítés sikertelen: ' + (e.error || res.status))
          saveBtn.disabled = false
          saveBtn.textContent = 'Mentés'
          return
        }
        form.remove()
        showToast('Kulcs frissitve es szinkronizalva')
        loadVaultPage()
        loadVault()
      })
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') form.remove()
      })
    })
  })
  list.querySelectorAll('.vault-card-delete').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id = btn.getAttribute('data-id')
      if (!confirm(`Torlod: ${id}?`)) return
      const res = await fetch(`/api/vault/${encodeURIComponent(id)}`, { method: 'DELETE' })
      if (!res.ok) { showToast('Törlés sikertelen'); return }
      loadVaultPage()
      loadVault()
    })
  })
}

;(function wireVaultPage() {
  const newBtn = document.getElementById('vaultPageNewBtn')
  const panel = document.getElementById('vaultAddPanel')
  const closeBtn = document.getElementById('vaultAddPanelClose')
  const addBtn = document.getElementById('vaultPageAddBtn')
  if (!newBtn || !panel) return

  const fieldsHost = document.getElementById('vaultPageFields')
  if (fieldsHost) {
    fieldsHost.innerHTML = _vaultFieldEditorHtml([])
    _initVaultFieldEditor(fieldsHost)
  }
  const tagsHost = document.getElementById('vaultPageTags')
  const resetTagsHost = () => {
    if (!tagsHost) return
    tagsHost.innerHTML = _vaultTagEditorHtml([])
    _initVaultTagEditor(tagsHost)
  }
  resetTagsHost()

  newBtn.addEventListener('click', () => {
    panel.hidden = !panel.hidden
    if (!panel.hidden) {
      // Re-render on open: this panel is wired once at page init, before the
      // vault list (and with it the known-tag set) has been fetched, so a
      // picker built at that moment would offer nothing to pick from.
      resetTagsHost()
      document.getElementById('vaultPageIdInput').focus()
    }
  })
  closeBtn?.addEventListener('click', () => { panel.hidden = true })

  addBtn.addEventListener('click', async () => {
    const id = document.getElementById('vaultPageIdInput').value.trim()
    const label = document.getElementById('vaultPageLabelInput').value.trim() || id
    const value = document.getElementById('vaultPageValueInput').value
    const tags = tagsHost ? _collectVaultTags(tagsHost) : []
    const url = document.getElementById('vaultPageUrlInput').value.trim()
    const notes = document.getElementById('vaultPageNotesInput').value.trim()
    const fields = fieldsHost ? _collectVaultFields(fieldsHost) : []
    // A card is "one place", not "one key" (Boss 2026-08-10: an Erste Bank card
    // holds card number, PIN and a login, and no single value is THE value). So
    // a name plus at least one filled field is enough; the primary value stays
    // required only for the fleet-readable keys that getSecret() reads by id.
    if (!id) return
    if (!value && !fields.some(f => f.value)) { showToast(t('vault.err.need_value')); return }
    addBtn.disabled = true
    await fetch('/api/vault', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, label, value, tags, url, notes, fields }),
    })
    document.getElementById('vaultPageIdInput').value = ''
    document.getElementById('vaultPageLabelInput').value = ''
    document.getElementById('vaultPageValueInput').value = ''
    document.getElementById('vaultPageUrlInput').value = ''
    document.getElementById('vaultPageNotesInput').value = ''
    if (fieldsHost) { fieldsHost.innerHTML = _vaultFieldEditorHtml([]); _initVaultFieldEditor(fieldsHost) }
    resetTagsHost()
    addBtn.disabled = false
    panel.hidden = true
    loadVaultPage()
    loadVault()
  })
  document.getElementById('vaultPageValueInput')?.addEventListener('keydown', (e) => { if (e.key === 'Enter') addBtn.click() })

  document.getElementById('vaultSearchInput')?.addEventListener('input', applyVaultFilters)
})()

// --- Vault Binding modal ---
;(function wireVaultBind() {
  const bindBtn = document.getElementById('vaultBindBtn')
  const overlay = document.getElementById('vaultBindOverlay')
  const closeBtn = document.getElementById('vaultBindClose')
  const saveBtn = document.getElementById('vaultBindSaveBtn')
  const secretSelect = document.getElementById('vaultBindSecret')
  const serverSelect = document.getElementById('vaultBindServer')
  const envVarInput = document.getElementById('vaultBindEnvVar')
  const statusEl = document.getElementById('vaultBindStatus')
  if (!bindBtn || !overlay) return

  overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModal(overlay) })
  closeBtn.addEventListener('click', () => { closeModal(overlay) })

  bindBtn.addEventListener('click', async () => {
    try {
      statusEl.hidden = true
      envVarInput.value = ''

      const [secretsRes, connectorsRes] = await Promise.all([
        fetch('/api/vault'),
        fetch('/api/connectors'),
      ])
      const secrets = (await secretsRes.json()).secrets || []
      const connectors = await connectorsRes.json()

      secretSelect.innerHTML = ''
      for (const s of secrets) {
        const opt = document.createElement('option')
        opt.value = s.id
        opt.textContent = s.label !== s.id ? `${s.id} (${s.label})` : s.id
        secretSelect.appendChild(opt)
      }
      if (secrets.length === 0) {
        const opt = document.createElement('option')
        opt.textContent = '-- Nincs vault kulcs --'
        opt.disabled = true
        secretSelect.appendChild(opt)
      }

      const mcpConnectors = connectors.filter(c => c.source !== 'plugin' && c.source !== 'claude.ai')
      serverSelect.innerHTML = ''
      for (const c of mcpConnectors) {
        const opt = document.createElement('option')
        opt.value = c.name
        opt.textContent = c.scope !== 'global' ? `${c.name} (${c.scope})` : c.name
        serverSelect.appendChild(opt)
      }
      if (mcpConnectors.length === 0) {
        const opt = document.createElement('option')
        opt.textContent = '-- Nincs MCP szerver --'
        opt.disabled = true
        serverSelect.appendChild(opt)
      }

      openModal(overlay)
    } catch (err) {
      console.error('Vault bind modal error:', err)
      showToast('Hiba a hozzarendeles betoltesekor: ' + err.message)
    }
  })

  saveBtn.addEventListener('click', async () => {
    const vaultSecretId = secretSelect.value
    const serverName = serverSelect.value
    const envVar = envVarInput.value.trim()
    if (!vaultSecretId || !serverName || !envVar) {
      statusEl.textContent = 'Minden mezo kitoltese kotelezo'
      statusEl.className = 'vault-bind-status error'
      statusEl.hidden = false
      return
    }

    saveBtn.disabled = true
    saveBtn.textContent = t('connectors.save_btn')
    try {
      const res = await fetch('/api/vault/bindings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ vaultSecretId, envVar, serverName }),
      })
      const data = await res.json()
      if (data.ok) {
        statusEl.textContent = `Hozzarendelve! ${data.synced || 0} fajl frissitve.`
        statusEl.className = 'vault-bind-status success'
        statusEl.hidden = false
        loadVaultPage()
        loadVault()
        setTimeout(() => { closeModal(overlay) }, 1500)
      } else {
        statusEl.textContent = data.error || 'Hiba tortent'
        statusEl.className = 'vault-bind-status error'
        statusEl.hidden = false
      }
    } catch (err) {
      statusEl.textContent = 'Halozati hiba'
      statusEl.className = 'vault-bind-status error'
      statusEl.hidden = false
    } finally {
      saveBtn.disabled = false
      saveBtn.textContent = 'Hozzarendeles'
    }
  })
})()

// --- Vault Scan & Import ---
;(function wireVaultScan() {
  const scanBtn = document.getElementById('vaultScanBtn')
  const syncBtn = document.getElementById('vaultSyncBtn')
  const overlay = document.getElementById('vaultScanOverlay')
  const closeBtn = document.getElementById('vaultScanClose')
  const importBtn = document.getElementById('vaultScanImportBtn')
  if (!scanBtn || !overlay) return

  scanBtn.addEventListener('click', async () => {
    scanBtn.disabled = true
    scanBtn.textContent = 'Kereses...'
    try {
      const res = await fetch('/api/vault/scan')
      const data = await res.json()
      const findings = data.findings || []
      renderScanResults(findings)
      openModal(overlay)
    } finally {
      scanBtn.disabled = false
      scanBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg> Scan &amp; Import'
    }
  })

  closeBtn?.addEventListener('click', () => { closeModal(overlay) })
  overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModal(overlay) })

  syncBtn?.addEventListener('click', async () => {
    syncBtn.disabled = true
    syncBtn.textContent = 'Szinkron...'
    try {
      const res = await fetch('/api/vault/sync', { method: 'POST' })
      const data = await res.json()
      if (data.updated > 0) {
        showToast(`${data.updated} .mcp.json frissitve`)
      } else {
        showToast('Nincs szinkronizalando kotes')
      }
      if (data.errors?.length) {
        showToast('Hibak: ' + data.errors.join(', '))
      }
    } finally {
      syncBtn.disabled = false
      syncBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg> Szinkron'
    }
  })

  function renderScanResults(findings) {
    const results = document.getElementById('vaultScanResults')
    const empty = document.getElementById('vaultScanEmpty')
    const footer = document.getElementById('vaultScanFooter')
    results.innerHTML = ''

    const actionable = findings.filter(f => !f.alreadyInVault)
    if (actionable.length === 0) {
      empty.hidden = false
      footer.hidden = true
      if (findings.length > 0) {
        empty.textContent = `${findings.length} erzekeny ertek talalva, de mind mar a Vault-ban van.`
      }
      return
    }
    empty.hidden = true
    footer.hidden = false

    const grouped = new Map()
    for (const f of actionable) {
      const key = `${f.serverName}|${f.envVar}`
      if (!grouped.has(key)) grouped.set(key, { ...f, allTargets: [] })
      grouped.get(key).allTargets.push({ mcpFilePath: f.mcpFilePath, serverName: f.serverName })
    }

    for (const [key, f] of grouped) {
      const row = document.createElement('div')
      row.className = 'vault-scan-row'
      row.innerHTML = `
        <label class="vault-scan-check">
          <input type="checkbox" checked data-key="${escapeHtml(key)}">
        </label>
        <div class="vault-scan-info">
          <div class="vault-scan-server">${escapeHtml(f.serverName)}</div>
          <div class="vault-scan-env">${escapeHtml(f.envVar)} = <code>${escapeHtml(f.maskedValue)}</code></div>
          <div class="vault-scan-targets">${f.allTargets.length} fajlban</div>
        </div>
        <div class="vault-scan-id">
          <input type="text" class="input vault-scan-vault-id" value="${escapeHtml(f.suggestedVaultId)}" data-key="${escapeHtml(key)}" style="font-size:12px;width:180px">
        </div>
      `
      results.appendChild(row)
    }
  }

  importBtn?.addEventListener('click', async () => {
    const results = document.getElementById('vaultScanResults')
    const rows = results.querySelectorAll('.vault-scan-row')
    const imports = []

    const scanRes = await fetch('/api/vault/scan')
    const scanData = await scanRes.json()
    const allFindings = scanData.findings || []

    for (const row of rows) {
      const cb = row.querySelector('input[type="checkbox"]')
      if (!cb?.checked) continue
      const key = cb.getAttribute('data-key')
      const [serverName, envVar] = key.split('|')
      const vaultIdInput = row.querySelector('.vault-scan-vault-id')
      const vaultId = vaultIdInput?.value?.trim() || key

      const matchingFindings = allFindings.filter(
        f => f.serverName === serverName && f.envVar === envVar && !f.alreadyInVault,
      )
      if (matchingFindings.length === 0) continue

      imports.push({
        serverName,
        envVar,
        vaultId,
        label: `${envVar} (${serverName})`,
        createBinding: true,
        targets: matchingFindings.map(f => ({ mcpFilePath: f.mcpFilePath, serverName: f.serverName })),
      })
    }

    if (imports.length === 0) { showToast('Nincs kivalasztott elem'); return }

    importBtn.disabled = true
    importBtn.textContent = 'Importalas...'

    try {
      const res = await fetch('/api/vault/import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imports }),
      })
      const data = await res.json()
      if (data.imported > 0) {
        showToast(`${data.imported} kulcs importalva, ${data.bound} kotes letrehozva`)
      }
      if (data.errors?.length) {
        showToast('Hibak: ' + data.errors.join(', '))
      }
    } finally {
      importBtn.disabled = false
      importBtn.textContent = 'Kivalasztottak importalasa'
    }
    closeModal(overlay)
    loadVaultPage()
    loadVault()
  })
})()

// --- External project paths management ---
async function loadExternalPaths() {
  try {
    const res = await fetch('/api/connectors/external-paths')
    const data = await res.json()
    const paths = data.paths || []
    document.getElementById('externalPathCount').textContent = String(paths.length)
    const list = document.getElementById('externalPathList')
    list.innerHTML = ''
    for (const p of paths) {
      const item = document.createElement('div')
      item.className = 'connector-external-item'
      item.innerHTML = `<span>${escapeHtml(p)}</span><button title="Torles">&times;</button>`
      item.querySelector('button').addEventListener('click', async () => {
        await fetch('/api/connectors/external-paths', {
          method: 'DELETE',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ path: p }),
        })
        loadExternalPaths()
        loadConnectors()
      })
      list.appendChild(item)
    }
  } catch { /* ignore */ }
}

;(function wireExternalPaths() {
  const toggle = document.getElementById('externalPathsToggle')
  const body = document.getElementById('externalPathsBody')
  if (!toggle || !body) return
  toggle.addEventListener('click', () => {
    const arrow = toggle.querySelector('.connector-scope-toggle')
    if (body.hidden) { body.hidden = false; arrow.textContent = '▼' }
    else { body.hidden = true; arrow.textContent = '▶' }
  })
  const addBtn = document.getElementById('externalPathAddBtn')
  const input = document.getElementById('externalPathInput')
  addBtn.addEventListener('click', async () => {
    const val = input.value.trim()
    if (!val) return
    const res = await fetch('/api/connectors/external-paths', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ path: val }),
    })
    const data = await res.json()
    if (data.error) { alert(data.error); return }
    input.value = ''
    loadExternalPaths()
    loadConnectors()
  })
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') addBtn.click() })
})()

async function openConnectorDetail(connector) {
  document.getElementById('connectorDetailTitle').textContent = connector.name

  // Fetch detailed info
  try {
    const res = await fetch(`/api/connectors/${encodeURIComponent(connector.name)}`)
    const detail = await res.json()

    const statusLabels = { connected: t('connectors.status.connected'), needs_auth: t('connectors.status.needs_auth'), failed: t('connectors.status.failed'), unknown: t('connectors.status.unknown') }
    const statusColors = { connected: 'var(--success)', needs_auth: 'var(--accent)', failed: 'var(--danger)', unknown: 'var(--text-muted)' }

    document.getElementById('connectorDetailInfo').innerHTML = `
      <div class="connector-detail-row">
        <span class="meta-label">Statusz</span>
        <span class="meta-value" style="color:${statusColors[detail.status] || ''}">${statusLabels[detail.status] || detail.status}</span>
      </div>
      <div class="connector-detail-row">
        <span class="meta-label">Hatokor</span>
        <span class="meta-value">${escapeHtml(detail.scope || '-')}</span>
      </div>
      ${detail.type ? `<div class="connector-detail-row"><span class="meta-label">Tipus</span><span class="meta-value">${escapeHtml(detail.type)}</span></div>` : ''}
      ${detail.command ? `<div class="connector-detail-row"><span class="meta-label">Parancs</span><span class="meta-value" style="font-family:monospace;font-size:12px">${escapeHtml(detail.command)} ${escapeHtml(detail.args || '')}</span></div>` : ''}
      ${Object.keys(detail.env || {}).length ? `<div class="connector-detail-row"><span class="meta-label">Env</span><span class="meta-value" style="font-family:monospace;font-size:11px">${Object.entries(detail.env).map(([k,v]) => `${k}=${v}`).join(', ')}</span></div>` : ''}
    `
  } catch {
    document.getElementById('connectorDetailInfo').innerHTML = `<p>${t('connectors.detail_error')}</p>`
  }

  try {
    const [agentsRes, connectorsRes] = await Promise.all([
      fetch('/api/schedules/agents'),
      fetch('/api/connectors'),
    ])
    const allAgents = await agentsRes.json()
    const allConnectors = await connectorsRes.json()
    const assignedAgents = new Set()
    for (const c of allConnectors) {
      if (c.name === connector.name && c.source === 'agent') {
        assignedAgents.add(c.scope.replace('agent:', ''))
      }
    }
    const mainAgent = allAgents.find(a => a.name === mainAgentId())
    const subAgents = allAgents.filter(a => a.name !== mainAgentId())

    const listEl = document.getElementById('connectorAgentList')
    listEl.innerHTML = ''
    if (mainAgent) {
      const item = document.createElement('div')
      item.className = 'connector-agent-item connector-agent-auto'
      item.innerHTML = `
        <input type="checkbox" checked disabled title="${t('connectors.tooltip.global')}">
        <label>${escapeHtml(mainAgent.label || mainAgent.name)} <span class="tag-auto">automatikus</span></label>
      `
      listEl.appendChild(item)
    }
    for (const agent of subAgents) {
      const isAssigned = assignedAgents.has(agent.name)
      const item = document.createElement('div')
      item.className = 'connector-agent-item'
      item.innerHTML = `
        <input type="checkbox" id="assign-${agent.name}" value="${agent.name}" ${isAssigned ? 'checked' : ''}>
        <label for="assign-${agent.name}">${escapeHtml(agent.label || agent.name)}</label>
      `
      listEl.appendChild(item)
    }
    if (subAgents.length === 0 && !mainAgent) {
      listEl.innerHTML = `<p style="color:var(--text-muted);font-size:13px">${t('connectors.no_agents')}</p>`
    }
  } catch {
    document.getElementById('connectorAgentList').innerHTML = ''
  }

  // Delete button
  document.getElementById('connectorDeleteBtn').onclick = async () => {
    if (!confirm(`Biztosan torlod: ${connector.name}?`)) return
    try {
      await fetch(`/api/connectors/${encodeURIComponent(connector.name)}`, { method: 'DELETE' })
      closeModal(connectorDetailOverlay)
      showToast(t('connectors.toast.deleted'))
      loadConnectors()
    } catch {
      showToast(t('common.error_delete'))
    }
  }

  // Assign button
  document.getElementById('connectorAssignBtn').onclick = async () => {
    const checked = [...document.querySelectorAll('#connectorAgentList input:checked:not(:disabled)')].map(i => i.value)
    const allVisible = [...document.querySelectorAll('#connectorAgentList input:not(:disabled)')].map(i => i.value)
    try {
      await fetch(`/api/connectors/${encodeURIComponent(connector.name)}/assign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ agents: checked, allAgents: allVisible }),
      })
      showToast(t('connectors.toast.assignment_updated'))
      closeModal(connectorDetailOverlay)
      loadConnectors()
    } catch {
      showToast(t('connectors.toast.assignment_error'))
    }
  }

  openModal(connectorDetailOverlay)
}

