// Save new connector
document.getElementById('saveConnectorBtn').addEventListener('click', async () => {
  const name = document.getElementById('connectorName').value.trim()
  const type = document.getElementById('connectorType').value
  const scope = document.getElementById('connectorScope').value

  if (!name) { document.getElementById('connectorName').focus(); return }

  const data = { name, type, scope }
  if (type === 'http' || type === 'sse') {
    data.url = document.getElementById('connectorUrl').value.trim()
    if (!data.url) { document.getElementById('connectorUrl').focus(); return }
  } else {
    data.command = document.getElementById('connectorCmd').value.trim()
    data.args = document.getElementById('connectorArgs').value.trim()
    if (!data.command) { document.getElementById('connectorCmd').focus(); return }
    const envRows = document.querySelectorAll('#connectorEnvList .connector-env-row')
    if (envRows.length > 0) {
      const env = {}
      for (const row of envRows) {
        const k = row.querySelector('.env-key').value.trim()
        const v = row.querySelector('.env-val').value.trim()
        if (k) env[k] = v
      }
      if (Object.keys(env).length > 0) data.env = env
    }
  }

  const btn = document.getElementById('saveConnectorBtn')
  btn.disabled = true
  btn.querySelector('.btn-text').hidden = true
  btn.querySelector('.btn-loading').hidden = false

  try {
    const res = await fetch('/api/connectors', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    })
    if (!res.ok) {
      const err = await res.json()
      throw new Error(err.error || 'Hiba')
    }
    const result = await res.json()
    const savedName = result.name || name

    const checkedAgents = Array.from(document.querySelectorAll('#connectorNewAssignList input[type=checkbox]:checked')).map(cb => cb.value)
    const allAgents = Array.from(document.querySelectorAll('#connectorNewAssignList input[type=checkbox]')).map(cb => cb.value)
    if (checkedAgents.length > 0) {
      await fetch(`/api/connectors/${encodeURIComponent(savedName)}/assign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ agents: checkedAgents, allAgents }),
      }).catch(() => {})
    }

    closeModal(connectorModalOverlay)
    if (result.nameChanged) {
      showToast(t('connectors.toast.added', { name: savedName }))
    } else {
      showToast(t('connectors.toast.created'))
    }
    loadConnectors()
  } catch (err) {
    showToast(`Hiba: ${err.message}`)
  } finally {
    btn.disabled = false
    btn.querySelector('.btn-text').hidden = false
    btn.querySelector('.btn-loading').hidden = true
  }
})

// === Helpers ===
function escapeHtml(str) {
  const d = document.createElement('div')
  d.textContent = str
  // textContent->innerHTML escapes & < > but NOT quotes. Encode quotes too so
  // the result is safe in ATTRIBUTE contexts as well as text nodes -- several
  // renderers interpolate escapeHtml() output into data-*/title/value="..."
  // attributes, where a surviving " would allow an attribute breakout.
  return d.innerHTML.replace(/"/g, '&quot;').replace(/'/g, '&#39;')
}

// Card ids as they REALLY appear in text. Measured on live data (2026-08-10):
// of the card references in the approvals list, 8 of 9 were written WITHOUT a
// leading '#' -- "Kartya 16911a38", "kanban b380afac", or just the bare id --
// while the linkifier only matched '#<id>'. That is why references were
// clickable "sometimes" (Boss: "kaotikus"): the pattern matched a form almost
// nobody writes. So an 8-hex token is linked when it is marked as a reference
// (# or a card word in front of it) OR when it is a REAL card id -- the id set
// below is the only reliable way to tell a card id from any other hex blob
// (git sha, colour, hash), and it also catches the bare and mistyped forms.
// Two shapes, because both are written in practice. The 8-hex id is the
// canonical one; "#46" is the BOARD NUMBER, and it is what a human reaches for
// first -- proven the hard way five minutes after this linker shipped, when the
// autofill card was cross-referenced as "#46" and therefore linked to nothing
// (Boss caught it: "az autofill kulonkartyan be van linkelve ebbe a kartyaba,
// igaz?"). A bare number only becomes a link when a card with that seq exists,
// so a price or a version number is left alone.
const KANBAN_REF_RE = /(#|\b(?:kanban|k[áa]rtya|card)\s+)?\b([0-9a-f]{8})\b|#(\d{1,4})\b/gi
let kanbanKnownIds = new Set()
// id -> { seq, title, status }, so a reference can be rendered with its SUBJECT
// and not as a bare "e88fd8e2" that tells the reader nothing (Boss 2026-08-10:
// "minden egyes szam utan legyen egy targymezo leiras"). Populated from the
// same endpoint as the id set, so labels work on the pages that linkify
// references without ever loading the kanban board itself.
let kanbanRefMeta = new Map()

async function loadKanbanCardIds() {
  try {
    const r = await fetch('/api/kanban/card-ids')
    if (!r.ok) return
    const rows = await r.json()
    kanbanKnownIds = new Set(rows.map(c => c.id))
    kanbanRefMeta = new Map(rows.map(c => [c.id, { seq: c.seq, title: c.title, status: c.status }]))
  } catch { /* links fall back to the marked forms only */ }
}

// "#23 Level kereses a postafiokban" instead of "e88fd8e2". Falls back to the
// raw id whenever the card is unknown (a git sha, a deleted card) -- rewriting
// text we cannot explain would be worse than leaving it alone.
/** The card carrying a given board number, or null. */
function kanbanRefBySeq(seq) {
  if (!Number.isFinite(seq)) return null
  for (const [id, meta] of kanbanRefMeta) {
    if (meta.seq === seq) return { id, ...meta }
  }
  return null
}

function kanbanRefLabel(id) {
  const meta = kanbanRefMeta.get(id)
  if (!meta) return id
  const seq = meta.seq != null ? '#' + meta.seq + ' ' : ''
  return seq + meta.title
}

function linkifyKanbanRefs(str) {
  if (!str) return ''
  const escaped = escapeHtml(str)
  return escaped.replace(KANBAN_REF_RE, (match, marker, id, seq) => {
    if (seq !== undefined) {
      const bySeq = kanbanRefBySeq(Number(seq))
      return bySeq
        ? `<span class="kanban-link" data-card-id="${bySeq.id}" role="link" tabindex="0" title="${escapeAttr(kanbanRefLabel(bySeq.id) + ' — ' + (t('kanban.status.' + bySeq.status) || bySeq.status))}">${escapeHtml(kanbanRefLabel(bySeq.id))}</span>`
        : match
    }
    const known = kanbanKnownIds.has(id.toLowerCase())
    if (!marker && !known) return match
    const prefix = marker || ''
    const lc = id.toLowerCase()
    const meta = kanbanRefMeta.get(lc)
    const label = escapeHtml(kanbanRefLabel(lc))
    const tip = meta ? escapeAttr(kanbanRefLabel(lc) + ' — ' + (t('kanban.status.' + meta.status) || meta.status)) : ''
    return `${prefix}<span class="kanban-link" data-card-id="${lc}" role="link" tabindex="0"${tip ? ` title="${tip}"` : ''}>${label}</span>`
  })
}

// Every known card id mentioned in a piece of text. Same 8-hex token rule the
// linkifier uses, restricted to ids that are actually cards -- a git sha or a
// colour must not become a relation.
function kanbanRefIdsIn(text) {
  if (!text) return []
  const re = new RegExp(KANBAN_REF_RE.source, 'gi')
  const out = new Set()
  for (const m of text.matchAll(re)) {
    if (m[3] !== undefined) {
      // Board number: only a reference if a card actually wears that number.
      const bySeq = kanbanRefBySeq(Number(m[3]))
      if (bySeq) out.add(bySeq.id)
      continue
    }
    const id = (m[2] || '').toLowerCase()
    if (kanbanKnownIds.has(id)) out.add(id)
  }
  return [...out]
}

// "Kapcsolodo kartyak": the cards this one mentions in prose, plus the cards
// that mention it. Boss asked for this after noticing one id tying together
// five cards with no way to see them from each other -- and specifically NOT
// as an automatic merge: #22 is still waiting while its four siblings are
// done, and a merged card cannot show that. Parent and children are excluded
// because the board already draws those; what was invisible is exactly the
// free-text connection.
function renderCardRelated(card) {
  const el = document.getElementById('cardDetailRelated')
  if (!el) return
  const skip = new Set([card.id, card.parent_id].filter(Boolean))
  for (const c of kanbanCards) if (c.parent_id === card.id) skip.add(c.id)

  const related = new Map()
  for (const id of kanbanRefIdsIn((card.title || '') + ' ' + (card.description || ''))) {
    if (!skip.has(id)) related.set(id, true)
  }
  for (const c of kanbanCards) {
    if (skip.has(c.id) || c.id === card.id || c.archived_at) continue
    if (kanbanRefIdsIn((c.title || '') + ' ' + (c.description || '')).includes(card.id)) related.set(c.id, true)
  }

  if (related.size === 0) { el.hidden = true; el.innerHTML = ''; return }
  const byId = new Map(kanbanCards.map(c => [c.id, c]))
  const rows = [...related.keys()]
    .map(id => byId.get(id))
    .filter(Boolean)
    .sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0))
  if (rows.length === 0) { el.hidden = true; el.innerHTML = ''; return }
  el.hidden = false
  el.innerHTML = `
    <div class="card-detail-related-title">${escapeHtml(t('kanban.related.title'))} (${rows.length})</div>
    ${rows.map(c => `
      <div class="card-detail-related-row kanban-link" data-card-id="${escapeAttr(c.id)}" role="link" tabindex="0">
        <span class="card-detail-related-seq">${c.seq != null ? '#' + c.seq : ''}</span>
        <span class="card-detail-related-name">${escapeHtml(c.title || '')}</span>
        <span class="card-detail-related-status status-${escapeAttr(c.status)}">${escapeHtml(t('kanban.status.' + c.status) || c.status)}</span>
      </div>`).join('')}
  `
}

// linkifyKanbanRefs() injects .kanban-link spans via innerHTML in many places
// (activity feed, approvals, card titles/descriptions/comments) -- a single
// delegated listener on document covers all of them without re-wiring after
// every re-render. Reuses the existing approvals-page jump/flash behavior
// (switchPage + scrollIntoView + flash) instead of a real <a href> nav target,
// since this is a hash-routed SPA with no server-side /kanban/:id route.
document.addEventListener('click', (e) => {
  const el = e.target.closest('.kanban-link')
  if (el) _openKanbanCardFromApproval(el.dataset.cardId)
})
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Enter' && e.key !== ' ') return
  const el = e.target.closest('.kanban-link')
  if (el) { e.preventDefault(); _openKanbanCardFromApproval(el.dataset.cardId) }
})

