// Holds the last successfully parsed fleet JSON text (for apply after dry-run)
let fleetLastBody = null

document.getElementById('fleetExportBtn').addEventListener('click', async () => {
  const btn = document.getElementById('fleetExportBtn')
  const password = document.getElementById('fleetExportPassword').value.trim()

  btn.disabled = true
  btn.querySelector('.btn-text').hidden = true
  btn.querySelector('.btn-loading').hidden = false

  try {
    const headers = {}
    if (password) headers['X-Vault-Password'] = password

    const res = await fetch('/api/fleet/export', { headers })
    if (!res.ok) {
      const data = await res.json().catch(() => ({}))
      showToast(data.error || t('fleet.export.error'))
      return
    }

    const blob = await res.blob()
    const cd = res.headers.get('Content-Disposition') || ''
    const nameMatch = cd.match(/filename="?([^";\s]+)"?/)
    const filename = nameMatch ? nameMatch[1] : `fleet-export-${new Date().toISOString().slice(0, 10)}.json`

    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = filename
    document.body.appendChild(a)
    a.click()
    a.remove()
    URL.revokeObjectURL(url)

    showToast(t('fleet.export.success'))
  } catch (err) {
    showToast(`${t('fleet.export.error')}: ${err.message}`)
  } finally {
    btn.disabled = false
    btn.querySelector('.btn-text').hidden = false
    btn.querySelector('.btn-loading').hidden = true
  }
})

document.getElementById('fleetDryRunBtn').addEventListener('click', async () => {
  const fileInput = document.getElementById('fleetImportFile')
  if (!fileInput.files.length) {
    showToast(t('fleet.import.no_file'))
    return
  }

  const btn = document.getElementById('fleetDryRunBtn')
  btn.disabled = true
  btn.querySelector('.btn-text').hidden = true
  btn.querySelector('.btn-loading').hidden = false

  const applyBtn = document.getElementById('fleetApplyBtn')
  applyBtn.disabled = true
  fleetLastBody = null

  const resultEl = document.getElementById('fleetDryRunResult')
  resultEl.hidden = true
  resultEl.innerHTML = ''

  try {
    const text = await fileInput.files[0].text()
    // Validate JSON client-side first
    try { JSON.parse(text) } catch { showToast(t('fleet.import.invalid_json')); return }

    const password = document.getElementById('fleetImportPassword').value.trim()
    const headers = { 'Content-Type': 'application/json' }
    if (password) headers['X-Vault-Password'] = password

    const res = await fetch('/api/fleet/import', { method: 'POST', headers, body: text })
    const data = await res.json()

    const wc = data.wouldCreate || {}
    const hasErrors = data.errors && data.errors.length > 0
    const hasWarnings = data.warnings && data.warnings.length > 0

    resultEl.className = `fleet-dry-run-result ${hasErrors ? 'has-errors' : 'ok'}`
    resultEl.hidden = false

    const agentNames = Array.isArray(wc.agents) ? wc.agents : []
    const agentLabel = agentNames.length
      ? `${agentNames.length} (${agentNames.join(', ')})`
      : '0'

    resultEl.innerHTML = `
      <div class="fleet-dry-run-title">${hasErrors ? '❌ ' + t('fleet.import.dryrun_errors') : '✅ ' + t('fleet.import.dryrun_ok')}</div>
      ${!hasErrors ? `
      <div class="fleet-dry-run-grid">
        <div class="fleet-dry-run-stat">
          <div class="fleet-dry-run-stat-value">${wc.mainAgent ? '✓' : '—'}</div>
          <div class="fleet-dry-run-stat-label">${t('fleet.stat.main_agent')}</div>
        </div>
        <div class="fleet-dry-run-stat">
          <div class="fleet-dry-run-stat-value">${agentNames.length}</div>
          <div class="fleet-dry-run-stat-label">${t('fleet.stat.agents')}</div>
        </div>
        <div class="fleet-dry-run-stat">
          <div class="fleet-dry-run-stat-value">${wc.memories ?? 0}</div>
          <div class="fleet-dry-run-stat-label">${t('fleet.stat.memories')}</div>
        </div>
        <div class="fleet-dry-run-stat">
          <div class="fleet-dry-run-stat-value">${wc.kanbanCards ?? 0}</div>
          <div class="fleet-dry-run-stat-label">${t('fleet.stat.kanban')}</div>
        </div>
        <div class="fleet-dry-run-stat">
          <div class="fleet-dry-run-stat-value">${wc.globalSkills ?? 0}</div>
          <div class="fleet-dry-run-stat-label">${t('fleet.stat.skills')}</div>
        </div>
        <div class="fleet-dry-run-stat">
          <div class="fleet-dry-run-stat-value">${wc.scheduledTasks ?? 0}</div>
          <div class="fleet-dry-run-stat-label">${t('fleet.stat.tasks')}</div>
        </div>
      </div>
      ${agentNames.length ? `<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px">${t('fleet.stat.agent_names')}: ${escapeHtml(agentNames.join(', '))}</div>` : ''}
      ` : ''}
      ${hasErrors ? `<div class="fleet-dry-run-errors">${data.errors.map(e => escapeHtml(e)).join('<br>')}</div>` : ''}
      ${hasWarnings ? `<div class="fleet-dry-run-warnings">⚠️ ${data.warnings.map(w => escapeHtml(w)).join('<br>')}</div>` : ''}
    `

    if (!hasErrors) {
      fleetLastBody = text
      applyBtn.disabled = false
    }
  } catch (err) {
    showToast(`${t('fleet.import.error')}: ${err.message}`)
  } finally {
    btn.disabled = false
    btn.querySelector('.btn-text').hidden = false
    btn.querySelector('.btn-loading').hidden = true
  }
})

document.getElementById('fleetApplyBtn').addEventListener('click', async () => {
  if (!fleetLastBody) return

  if (!confirm(t('fleet.import.apply_confirm'))) return

  const btn = document.getElementById('fleetApplyBtn')
  btn.disabled = true
  btn.querySelector('.btn-text').hidden = true
  btn.querySelector('.btn-loading').hidden = false

  const resultEl = document.getElementById('fleetDryRunResult')

  try {
    const password = document.getElementById('fleetImportPassword').value.trim()
    const headers = { 'Content-Type': 'application/json' }
    if (password) headers['X-Vault-Password'] = password

    const res = await fetch('/api/fleet/import?apply=true', { method: 'POST', headers, body: fleetLastBody })
    const data = await res.json()

    if (!res.ok) throw new Error(data.error || t('fleet.import.error'))

    const imp = data.imported || {}
    const agentNames = Array.isArray(imp.agents) ? imp.agents : []

    resultEl.className = 'fleet-apply-result'
    resultEl.hidden = false
    resultEl.innerHTML = `
      <div class="fleet-apply-result-title">✅ ${t('fleet.import.apply_success')}</div>
      <div>
        ${imp.mainAgent ? `<div>${t('fleet.stat.main_agent')}: ✓</div>` : ''}
        ${agentNames.length ? `<div>${t('fleet.stat.agents')}: ${escapeHtml(agentNames.join(', '))}</div>` : ''}
        <div>${t('fleet.stat.memories')}: ${imp.memories ?? 0}</div>
        <div>${t('fleet.stat.kanban')}: ${imp.kanbanCards ?? 0}</div>
        <div>${t('fleet.stat.skills')}: ${imp.globalSkills ?? 0}</div>
        <div>${t('fleet.stat.tasks')}: ${imp.scheduledTasks ?? 0}</div>
      </div>
    `

    fleetLastBody = null
    btn.disabled = true
  } catch (err) {
    showToast(`${t('fleet.import.error')}: ${err.message}`)
    btn.disabled = false
    btn.querySelector('.btn-text').hidden = false
    btn.querySelector('.btn-loading').hidden = true
  } finally {
    btn.querySelector('.btn-text').hidden = false
    btn.querySelector('.btn-loading').hidden = true
  }
})

// ============================================================
// === Skills Page ===
// ============================================================

const skillsGrid = document.getElementById('skillsGrid')
const skillsStats = document.getElementById('skillsStats')
const skillsEmpty = document.getElementById('skillsEmpty')
const skillDetailOverlay = document.getElementById('skillDetailOverlay')

let globalSkills = []
let localAgentSkills = []
let skillsActiveFilter = 'all'
let skillsSearchQuery = ''
let skillsActiveCategory = 'all'

function deriveSkillCategory(name) {
  // Use the first dash-separated segment as the category group.
  // "fleet-dashboard-api" -> "fleet", "morning-chain" -> "morning",
  // "handoff" -> "handoff"
  const seg = name.split(':').pop() || name  // strip plugin prefix
  return seg.split('-')[0] || seg
}

function formatMtime(ms) {
  if (!ms) return ''
  const d = new Date(ms)
  const pad = n => String(n).padStart(2, '0')
  return `${d.getFullYear()}.${pad(d.getMonth() + 1)}.${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`
}

document.getElementById('skillDetailClose').addEventListener('click', () => closeModal(skillDetailOverlay))
skillDetailOverlay.addEventListener('click', (e) => { if (e.target === skillDetailOverlay) closeModal(skillDetailOverlay) })

// Scope for the next skill create/import action. 'global' means the
// Skills page opened the modal (write to ~/.claude/skills/); any other
// value (or null) falls back to the legacy per-agent flow keyed off
// `currentAgent`. Reset on modal close so a subsequent per-agent open
// cannot inherit the global scope.
let skillModalScope = null

// Wire the Skills-page "Új skill" button to reuse the same skillModalOverlay
// the per-agent Skill list uses. The save/import handlers branch on
// skillModalScope so we don't have to duplicate the modal markup.
const skillsPageNewBtn = document.getElementById('skillsPageNewBtn')
if (skillsPageNewBtn) {
  skillsPageNewBtn.addEventListener('click', () => {
    skillModalScope = 'global'
    document.getElementById('skillName').value = ''
    document.getElementById('skillDescription').value = ''
    skillFile = null
    document.getElementById('skillFileName').textContent = ''
    document.querySelectorAll('.skill-tab-btn').forEach(b => b.classList.toggle('active', b.dataset.skillTab === 'create'))
    document.getElementById('skillTabCreate').hidden = false
    document.getElementById('skillTabImport').hidden = true
    openModal(skillModalOverlay)
    setTimeout(() => document.getElementById('skillName').focus(), 200)
  })
}

async function loadGlobalSkills() {
  skillsGrid.innerHTML = `<div class="connector-loading"><span class="spinner"></span> ${t('skills.loading')}</div>`
  skillsStats.innerHTML = ''
  try {
    const [globalRes, localRes] = await Promise.all([
      fetch('/api/skills'),
      fetch('/api/skills/local'),
    ])
    globalSkills = await globalRes.json()
    localAgentSkills = localRes.ok ? await localRes.json() : []
    renderGlobalSkills()
  } catch (err) {
    console.error('Skills betoltes hiba:', err)
    skillsGrid.innerHTML = `<div class="connector-loading">${t('skills.error')}</div>`
  }
}

// Wire search, filter, and export controls once DOM is ready
;(() => {
  const searchEl = document.getElementById('skillsSearch')
  if (searchEl) {
    searchEl.addEventListener('input', () => {
      skillsSearchQuery = searchEl.value.toLowerCase().trim()
      renderSkillsSidebar()
      renderGlobalSkillsGrid()
    })
  }

  const filterBtns = document.getElementById('skillsFilterBtns')
  if (filterBtns) {
    filterBtns.addEventListener('click', (e) => {
      const btn = e.target.closest('.skills-filter-btn')
      if (!btn) return
      filterBtns.querySelectorAll('.skills-filter-btn').forEach(b => b.classList.remove('active'))
      btn.classList.add('active')
      skillsActiveFilter = btn.dataset.filter || 'all'
      skillsActiveCategory = 'all'
      renderSkillsSidebar()
      renderGlobalSkillsGrid()
    })
  }

  const exportBtn = document.getElementById('skillsExportBtn')
  if (exportBtn) {
    exportBtn.addEventListener('click', () => {
      const a = document.createElement('a')
      a.href = '/api/skills/export'
      a.download = 'skills-export.zip'
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
    })
  }
})()

function getSkillIcon(name) {
  if (name.includes('factory') || name.includes('creator')) return '\u{1F3ED}'
  if (name.includes('blog') || name.includes('post')) return '\u{1F4DD}'
  if (name.includes('image') || name.includes('thumbnail') || name.includes('fal')) return '\u{1F3A8}'
  if (name.includes('frontend') || name.includes('design')) return '\u{1F58C}\uFE0F'
  if (name.includes('youtube') || name.includes('video') || name.includes('seo')) return '\u{1F3AC}'
  if (name.includes('docx') || name.includes('doc')) return '\u{1F4C4}'
  if (name.includes('skool')) return '\u{1F393}'
  if (name.includes('skill')) return '\u{1F9E9}'
  return '\u2699\uFE0F'
}

function renderSkillsSidebar() {
  const sidebar = document.getElementById('skillsCategorySidebar')
  if (!sidebar) return

  // For the 'agent' filter, category counts come from localAgentSkills so the
  // sidebar stays populated. All other filters draw from globalSkills as before.
  const sourceFiltered = skillsActiveFilter === 'agent'
    ? localAgentSkills
    : skillsActiveFilter === 'all'
      ? globalSkills
      : globalSkills.filter(s => s.source === skillsActiveFilter)

  const catCounts = new Map()
  for (const s of sourceFiltered) {
    const cat = deriveSkillCategory(s.name)
    catCounts.set(cat, (catCounts.get(cat) || 0) + 1)
  }

  const cats = [...catCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]))

  sidebar.innerHTML = `
    <div class="skills-cat-title">${t('skills.category.title')}</div>
    <button class="skills-cat-btn${skillsActiveCategory === 'all' ? ' active' : ''}" data-cat="all">
      ${t('skills.filter.all')} <span class="skills-cat-count">${sourceFiltered.length}</span>
    </button>
    ${cats.map(([cat, count]) => `
      <button class="skills-cat-btn${skillsActiveCategory === cat ? ' active' : ''}" data-cat="${escapeHtml(cat)}">
        ${escapeHtml(cat)} <span class="skills-cat-count">${count}</span>
      </button>
    `).join('')}
  `

  sidebar.addEventListener('click', (e) => {
    const btn = e.target.closest('.skills-cat-btn')
    if (!btn) return
    skillsActiveCategory = btn.dataset.cat || 'all'
    renderSkillsSidebar()
    renderGlobalSkillsGrid()
  })
}

function renderGlobalSkills() {
  const userCount = globalSkills.filter(s => s.source === 'user').length
  const pluginCount = globalSkills.filter(s => s.source === 'plugin').length

  skillsStats.innerHTML = `
    <div class="stat-card"><div class="stat-value">${globalSkills.length}</div><div class="stat-label">${t('skills.stat.total')}</div></div>
    <div class="stat-card"><div class="stat-value" style="color:var(--info)">${userCount}</div><div class="stat-label">${t('skills.stat.user')}</div></div>
    ${pluginCount ? `<div class="stat-card"><div class="stat-value" style="color:var(--accent)">${pluginCount}</div><div class="stat-label">${t('skills.stat.plugin')}</div></div>` : ''}
    ${localAgentSkills.length ? `<div class="stat-card"><div class="stat-value" style="color:var(--warning)">${localAgentSkills.length}</div><div class="stat-label">${t('skills.stat.agent_local')}</div></div>` : ''}
  `

  skillsActiveCategory = 'all'
  renderSkillsSidebar()
  renderGlobalSkillsGrid()
}

function renderGlobalSkillsGrid() {
  skillsGrid.innerHTML = ''

  const isAgentFilter = skillsActiveFilter === 'agent'

  // When 'agent' filter is active, show only local agent skills; otherwise show global/plugin.
  const filteredGlobal = isAgentFilter ? [] : globalSkills.filter(s => {
    if (skillsActiveFilter !== 'all' && s.source !== skillsActiveFilter) return false
    if (skillsActiveCategory !== 'all' && deriveSkillCategory(s.name) !== skillsActiveCategory) return false
    if (!skillsSearchQuery) return true
    const haystack = [s.name, s.label, s.description, ...(s.keywords || [])].join(' ').toLowerCase()
    return haystack.includes(skillsSearchQuery)
  })

  // Local agent skills: always merged in for 'all' or filtered to 'agent'.
  const filteredLocal = (skillsActiveFilter === 'all' || isAgentFilter) ? localAgentSkills.filter(s => {
    if (skillsActiveCategory !== 'all' && deriveSkillCategory(s.name) !== skillsActiveCategory) return false
    if (!skillsSearchQuery) return true
    const haystack = [s.name, s.label, s.description, s.agentId, ...(s.keywords || [])].join(' ').toLowerCase()
    return haystack.includes(skillsSearchQuery)
  }) : []

  const allFiltered = [...filteredGlobal, ...filteredLocal]

  if (allFiltered.length === 0) {
    skillsEmpty.hidden = false
    return
  }
  skillsEmpty.hidden = true

  const sourceLabels = { user: 'user', plugin: 'plugin', agent: t('skills.filter.agent') }

  const renderCard = (skill, isLocal) => {
    const card = document.createElement('div')
    card.className = isLocal ? 'skills-card skills-card--local' : 'skills-card'
    const icon = getSkillIcon(skill.name)
    const sourceBadge = isLocal
      ? `<span class="connector-source-badge skills-badge--agent">${escapeHtml(chatDisplayName(skill.agentId))}</span>`
      : (skill.source ? `<span class="connector-source-badge">${escapeHtml(sourceLabels[skill.source] || skill.source)}</span>` : '')

    const hasDesc = !!skill.description
    const healthClass = hasDesc ? 'skill-health-ok' : 'skill-health-warn'
    const healthTitle = hasDesc ? t('skills.health.ok') : t('skills.health.nodesc')

    const kws = (skill.keywords || []).slice(0, 3)
    const kwTags = kws.map(k => `<span class="skill-keyword-tag">${escapeHtml(k)}</span>`).join('')

    const agents = skill.agents || []
    const agentBadges = agents.length > 0
      ? `<span class="skills-agent-badge skill-agent-count" title="${escapeHtml(agents.map(chatDisplayName).join(', '))}">&#x1F916; ${agents.length} ${t('skills.agents.count')}</span>`
      : ''

    const mtimeStr = skill.mtime ? formatMtime(skill.mtime) : ''

    const displayName = skill.label || skill.name
    card.innerHTML = `
      <div class="skills-card-header">
        <div class="skills-card-icon">${icon}</div>
        <div class="skills-card-info">
          <div class="skills-card-name">
            ${escapeHtml(displayName)} ${sourceBadge}
            <span class="skill-health-dot ${healthClass}" title="${escapeHtml(healthTitle)}"></span>
          </div>
          <div class="skills-card-desc">${escapeHtml(skill.description || t('skills.no_description'))}</div>
        </div>
      </div>
      ${(kwTags || agentBadges || mtimeStr) ? `
      <div class="skills-card-footer">
        ${kwTags}
        ${agentBadges}
        ${mtimeStr ? `<span class="skill-card-mtime" title="${t('skills.mtime.title')}">${escapeHtml(mtimeStr)}</span>` : ''}
      </div>` : ''}
    `
    card.addEventListener('click', () => openSkillDetail(skill.name, skill.label, skill.agentId || null))
    skillsGrid.appendChild(card)
  }

  for (const skill of filteredGlobal) renderCard(skill, false)
  for (const skill of filteredLocal) renderCard(skill, true)
}

let _skillDetailCurrentName = null
let _skillDetailCurrentAgentId = null
let _skillDetailIsPlugin = false

function _skillDetailExitEdit() {
  const editor = document.getElementById('skillDetailEditor')
  const contentEl = document.getElementById('skillDetailContent')
  const editActions = document.getElementById('skillDetailEditActions')
  const editBtn = document.getElementById('skillDetailEditBtn')
  editor.hidden = true
  contentEl.hidden = false
  editActions.hidden = true
  editBtn.disabled = false
}

async function openSkillDetail(skillName, displayLabel, agentId = null) {
  _skillDetailCurrentName = skillName
  _skillDetailCurrentAgentId = agentId
  _skillDetailExitEdit()

  document.getElementById('skillDetailTitle').textContent = displayLabel || skillName

  const editBtn = document.getElementById('skillDetailEditBtn')
  if (editBtn) {
    editBtn.hidden = false
    editBtn.disabled = false
  }

  try {
    const detailUrl = agentId
      ? `/api/skills/${encodeURIComponent(skillName)}?agent=${encodeURIComponent(agentId)}`
      : `/api/skills/${encodeURIComponent(skillName)}`
    const res = await fetch(detailUrl)
    if (!res.ok) throw new Error('Failed to fetch skill detail')
    const detail = await res.json()
    _skillDetailIsPlugin = detail.source === 'plugin'

    // Hide edit button for plugin skills
    if (editBtn) editBtn.hidden = _skillDetailIsPlugin

    // Description
    const descEl = document.getElementById('skillDetailDesc')
    descEl.textContent = detail.description || t('skills.no_description')

    // Meta: source + mtime
    const metaEl = document.getElementById('skillDetailMeta')
    if (metaEl) {
      const sourceLabel = detail.source === 'plugin'
        ? `plugin${detail.pluginPackage ? ' (' + escapeHtml(detail.pluginPackage) + ')' : ''}`
        : detail.source === 'user'
        ? t('skills.source.user')
        : t('skills.source.unknown')
      const mtimeStr = detail.mtime ? formatMtime(detail.mtime) : ''
      metaEl.innerHTML = `
        <div class="skill-detail-source">${t('skills.detail.source_label')} <strong>${sourceLabel}</strong>${mtimeStr ? ` &middot; <span title="${escapeHtml(t('skills.mtime.title'))}">${escapeHtml(mtimeStr)}</span>` : ''}</div>
        <div class="skill-detail-note">${t('skills.detail.auto_available')}</div>
      `
    }

    // Keywords
    const kwEl = document.getElementById('skillDetailKeywords')
    if (kwEl) {
      const kws = detail.keywords || []
      if (kws.length > 0) {
        kwEl.hidden = false
        kwEl.innerHTML = `<span class="skill-kw-label">${t('skills.keywords.label')}</span> ` +
          kws.map(k => `<span class="skill-keyword-tag">${escapeHtml(k)}</span>`).join(' ')
      } else {
        kwEl.hidden = true
      }
    }

    // Agent coverage
    const agentsEl = document.getElementById('skillDetailAgentsCoverage')
    if (agentsEl) {
      const agents = detail.agents || []
      if (agents.length > 0) {
        agentsEl.hidden = false
        agentsEl.innerHTML = `<span class="skill-kw-label">${t('skills.agents.label')}</span> ` +
          agents.map(a => `<span class="skills-agent-badge">${escapeHtml(a)}</span>`).join(' ')
      } else {
        agentsEl.hidden = true
      }
    }

    // Health indicator
    const healthEl = document.getElementById('skillDetailHealth')
    if (healthEl) {
      const hasDesc = !!detail.description
      const hasContent = !!detail.content
      if (hasDesc && hasContent) {
        healthEl.className = 'skill-health-label skill-health-ok'
        healthEl.textContent = t('skills.health.ok')
      } else if (hasContent) {
        healthEl.className = 'skill-health-label skill-health-warn'
        healthEl.textContent = t('skills.health.nodesc')
      } else {
        healthEl.className = 'skill-health-label skill-health-err'
        healthEl.textContent = t('skills.health.empty')
      }
    }

    // Content: render as markdown
    const contentEl = document.getElementById('skillDetailContent')
    const rawContent = detail.content || t('skills.content_not_found')
    contentEl.innerHTML = renderMarkdown(rawContent)

    // Prefill editor
    const editor = document.getElementById('skillDetailEditor')
    if (editor) editor.value = rawContent

  } catch (err) {
    console.error('Skill detail hiba:', err)
    document.getElementById('skillDetailDesc').textContent = t('connectors.error_list')
    document.getElementById('skillDetailContent').innerHTML = ''
    const metaEl = document.getElementById('skillDetailMeta')
    if (metaEl) metaEl.innerHTML = ''
    if (editBtn) editBtn.hidden = true
  }

  openModal(skillDetailOverlay)
}

// Inline edit wiring
;(() => {
  const editBtn = document.getElementById('skillDetailEditBtn')
  const saveBtn = document.getElementById('skillDetailSaveBtn')
  const cancelBtn = document.getElementById('skillDetailCancelEditBtn')
  const editor = document.getElementById('skillDetailEditor')
  const contentEl = document.getElementById('skillDetailContent')
  const editActions = document.getElementById('skillDetailEditActions')

  if (editBtn) {
    editBtn.addEventListener('click', () => {
      if (_skillDetailIsPlugin) return
      contentEl.hidden = true
      editor.hidden = false
      editActions.hidden = false
      editBtn.disabled = true
      editor.focus()
    })
  }

  if (cancelBtn) {
    cancelBtn.addEventListener('click', _skillDetailExitEdit)
  }

  if (saveBtn) {
    saveBtn.addEventListener('click', async () => {
      if (!_skillDetailCurrentName || _skillDetailIsPlugin) return
      const newContent = editor.value
      saveBtn.disabled = true
      try {
        const putUrl = _skillDetailCurrentAgentId
          ? `/api/skills/${encodeURIComponent(_skillDetailCurrentName)}?agent=${encodeURIComponent(_skillDetailCurrentAgentId)}`
          : `/api/skills/${encodeURIComponent(_skillDetailCurrentName)}`
        const res = await fetch(putUrl, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ content: newContent }),
        })
        if (!res.ok) throw new Error('PUT failed: ' + res.status)
        contentEl.innerHTML = renderMarkdown(newContent)
        _skillDetailExitEdit()
        showToast(t('skills.toast.saved'))
        // Refresh list to pick up new description/keywords
        loadGlobalSkills()
      } catch (err) {
        console.error('Skill mentés hiba:', err)
        showToast(t('skills.toast.save_error'))
      } finally {
        saveBtn.disabled = false
      }
    })
  }
})()

// === Team org-chart (now embedded in Agents page, tree view) ===
async function loadTeamGraph() {
  const container = document.getElementById('teamGraph')
  if (!container) return
  container.innerHTML = '<div class="team-empty">' + t('team.loading') + '</div>'
  try {
    const res = await fetch('/api/team/graph')
    if (!res.ok) throw new Error('HTTP ' + res.status)
    const data = await res.json()
    renderTeamGraph(container, data, { editable: true })
  } catch (err) {
    container.innerHTML = `<div class="team-empty">${t('team.error', { msg: err.message || err })}</div>`
  }
}

// Persist a drag-and-drop reporting change: `childId` now reports to `parentId`.
// Guards (also enforced server-side) keep the caller from creating a cycle or
// writing a no-op. On success the graph is reloaded so the tree re-lays-out.
async function saveTeamReportsTo(childId, parentId, ctx) {
  const { byId, parentOf, descendantsOf, mainAgentId } = ctx
  if (!childId || childId === parentId || childId === mainAgentId) return
  if (parentOf.get(childId) === parentId) return  // already the parent
  if (descendantsOf(childId).has(parentId)) { showToast(t('team.drop.cycle')); return }
  try {
    const r = await fetch(`/api/agents/${encodeURIComponent(childId)}/team`, {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ reportsTo: parentId }),
    })
    if (!r.ok) throw new Error('HTTP ' + r.status)
    const result = await r.json().catch(() => ({}))
    if (result.cycleRejected) { showToast(t('team.drop.cycle')); return }
    const childLabel = (byId.get(childId) || {}).label || childId
    const parentLabel = (byId.get(parentId) || {}).label || parentId
    showToast(t('team.drop.saved', { child: childLabel, parent: parentLabel }))
    loadTeamGraph()
  } catch {
    showToast(t('team.drop.error'))
  }
}

function renderTeamGraph(container, data, opts = {}) {
  const editable = !!opts.editable
  const { nodes, edges, mainAgentId } = data
  container.innerHTML = ''
  const byId = new Map(nodes.map(n => [n.id, n]))
  const childrenOf = new Map()
  const parentOf = new Map()
  for (const n of nodes) childrenOf.set(n.id, [])
  for (const e of edges) {
    if (childrenOf.has(e.from)) childrenOf.get(e.from).push(e.to)
    parentOf.set(e.to, e.from)
  }
  // Transitive reports of `id` (its whole subtree). Used to reject dropping a
  // manager onto one of its own reports, which would orphan the subtree.
  const descendantsOf = (id) => {
    const out = new Set()
    const walk = (x) => {
      for (const c of (childrenOf.get(x) || [])) {
        if (!out.has(c)) { out.add(c); walk(c) }
      }
    }
    walk(id)
    return out
  }
  const dropCtx = { byId, parentOf, descendantsOf, mainAgentId }
  // A single dragged id shared across all nodes' dragover handlers so they can
  // validate the target (dataTransfer payload is unreadable during dragover).
  let draggingId = null
  const renderNode = (node) => {
    const div = document.createElement('div')
    div.className = 'team-node'
    if (node.role === 'main') div.classList.add('main')
    else if (node.role === 'leader') div.classList.add('leader')
    const roleLabel = node.role === 'main' ? t('team.role.main') : (node.role === 'leader' ? t('team.role.leader') : t('team.role.member'))
    const running = node.running ? t('team.running') : t('team.stopped')
    const avatarUrl = node.id === mainAgentId
      ? `/api/marveen/avatar${avatarBust()}`
      : `/api/agents/${encodeURIComponent(node.id)}/avatar${avatarBust()}`
    // Only request an avatar the agent actually has. An agent with no avatar
    // file 404s, and this view asked for every node unconditionally -- one dead
    // request per avatar-less agent on every load (11 of them on this install),
    // each leaving an empty grey disc behind. hasAvatar rides along on the
    // /api/team/graph node; a payload without the field (older server, cached
    // response) is treated as "has one", i.e. the previous behaviour.
    const nodeLabel = node.label || node.id
    const avatarInner = node.hasAvatar === false
      ? `<span class="team-node-mono" style="background:${monogramColor(node.id)}">${escapeHtml(nodeLabel.charAt(0).toUpperCase())}</span>`
      : `<img src="${avatarUrl}" alt="${escapeHtml(nodeLabel)}" onerror="this.style.display='none'">`
    const isFreeNode = isFreeModel(node.model)
    div.innerHTML = `
      ${isFreeNode ? `<span class="team-node-free-badge">${escapeHtml(t('agents.free_badge'))}</span>` : costBadgeHtml(node.costPerMInput)}
      <div class="team-node-avatar">${avatarInner}</div>
      <div class="team-node-name">${escapeHtml(node.label || node.id)}</div>
      <div class="team-node-meta">${escapeHtml(roleLabel)}</div>
      <div class="team-node-meta">${running}</div>
      ${node.external ? `<div class="team-node-meta team-node-external">${escapeHtml(t('cb.card.external_badge'))}</div>` : ''}
    `
    if (node.external) {
      // Kulso vegrehajto: nincs `agents/<id>` mappaja, tehat sem az ugynok-
      // reszletek, sem az atszervezes nem ertelmezheto ra -- olyan gombot,
      // ami 404-gyel vegzodne, nem kinalunk. A sajat beallitasai a kod-hid
      // ablakban vannak, oda visszuk.
      div.classList.add('team-node-external-card')
      div.addEventListener('click', () => openCodeBridgeModal())
    } else if (node.id !== mainAgentId) {
      div.addEventListener('click', () => openAgentDetail(node.id))
    }
    // Drag-and-drop reporting edit (Team page only). Any agent except the main
    // one can be dragged; any node can be a drop target (dropping onto the main
    // agent makes the report a direct report of it).
    if (editable) {
      if (node.id !== mainAgentId && !node.external) {
        div.draggable = true
        div.classList.add('team-draggable')
        div.addEventListener('dragstart', (e) => {
          draggingId = node.id
          e.dataTransfer.setData('text/plain', node.id)
          e.dataTransfer.effectAllowed = 'move'
          div.classList.add('team-dragging')
        })
        div.addEventListener('dragend', () => {
          draggingId = null
          div.classList.remove('team-dragging')
        })
      }
      // Kulso vegrehajto nem lehet FONOK sem: nincs hova bejegyezni, hogy ki
      // jelent neki -- a dobas nemaan elveszne.
      const isValidTarget = () =>
        !node.external &&
        draggingId && draggingId !== node.id &&
        parentOf.get(draggingId) !== node.id &&
        !descendantsOf(draggingId).has(node.id)
      div.addEventListener('dragover', (e) => {
        if (!isValidTarget()) return  // no preventDefault -> shows "no drop"
        e.preventDefault()
        e.dataTransfer.dropEffect = 'move'
        div.classList.add('team-drop-target')
      })
      div.addEventListener('dragleave', () => div.classList.remove('team-drop-target'))
      div.addEventListener('drop', (e) => {
        e.preventDefault()
        div.classList.remove('team-drop-target')
        const childId = e.dataTransfer.getData('text/plain') || draggingId
        saveTeamReportsTo(childId, node.id, dropCtx)
      })
    }
    return div
  }
  // Render as a nested tree so each report sits directly under its own
  // manager. A flat BFS-by-row layout made a leader's reports look like they
  // belonged to whichever node happened to be above them in the row.
  const seen = new Set([mainAgentId])
  const renderSubtree = (id) => {
    const node = byId.get(id)
    if (!node) return null
    const col = document.createElement('div')
    col.className = 'team-subtree'
    col.appendChild(renderNode(node))
    const kids = (childrenOf.get(id) || []).filter(c => !seen.has(c) && byId.has(c))
    for (const c of kids) seen.add(c)
    if (kids.length) {
      const conn = document.createElement('div')
      conn.className = 'team-connector'
      col.appendChild(conn)
      const row = document.createElement('div')
      row.className = 'team-children'
      for (const c of kids) {
        const sub = renderSubtree(c)
        if (sub) row.appendChild(sub)
      }
      col.appendChild(row)
    }
    return col
  }
  // Main on top, then a row of its direct reports (each carrying its own
  // subtree beneath it).
  const mainNode = byId.get(mainAgentId)
  if (mainNode) {
    const mainRow = document.createElement('div')
    mainRow.className = 'team-level'
    mainRow.appendChild(renderNode(mainNode))
    container.appendChild(mainRow)
  }
  const directs = (childrenOf.get(mainAgentId) || []).filter(c => !seen.has(c) && byId.has(c))
  for (const c of directs) seen.add(c)
  if (directs.length) {
    const conn = document.createElement('div')
    conn.className = 'team-connector'
    container.appendChild(conn)
    const row = document.createElement('div')
    row.className = 'team-children team-roots'
    for (const c of directs) {
      const sub = renderSubtree(c)
      if (sub) row.appendChild(sub)
    }
    container.appendChild(row)
  }
  // Orphans (nodes not reachable from main, shouldn't happen with the auto
  // fallback on the backend but guard just in case) go to a trailing row.
  const orphans = nodes.filter(n => !seen.has(n.id))
  if (orphans.length) {
    const row = document.createElement('div')
    row.className = 'team-level'
    for (const n of orphans) row.appendChild(renderNode(n))
    container.appendChild(row)
  }
  if (nodes.length === 1) {
    const empty = document.createElement('div')
    empty.className = 'team-empty'
    empty.textContent = t('team.empty')
    container.appendChild(empty)
  }
}

// === Agents page: grid / org-chart view toggle ===
// Persists the chosen view for the session so navigating away and back keeps
// the last selection. Defaults to 'grid'.
let _agentsActiveView = 'grid'

function _setAgentsView(view) {
  _agentsActiveView = view
  const gridView = document.getElementById('agentsGridView')
  const treeView = document.getElementById('agentsTreeView')
  const gridBtn  = document.getElementById('agentsViewGrid')
  const treeBtn  = document.getElementById('agentsViewTree')
  if (!gridView || !treeView) return
  const showGrid = view === 'grid'
  gridView.hidden = !showGrid
  treeView.hidden = showGrid
  if (gridBtn) gridBtn.classList.toggle('active', showGrid)
  if (treeBtn) treeBtn.classList.toggle('active', !showGrid)
  if (!showGrid) loadTeamGraph()
}

const _agentsViewGridBtn = document.getElementById('agentsViewGrid')
const _agentsViewTreeBtn = document.getElementById('agentsViewTree')
if (_agentsViewGridBtn) _agentsViewGridBtn.addEventListener('click', () => _setAgentsView('grid'))
if (_agentsViewTreeBtn) _agentsViewTreeBtn.addEventListener('click', () => _setAgentsView('tree'))

// === Team: inter-agent message log + compose ===
// View the /api/messages queue and let the operator send a message to an agent
// from the dashboard. Targets come from /api/schedules/agents (the same allowed
// agent list the scheduler uses) -- never a free-text target. The sender is the
// owner (resolved by type from /api/kanban/assignees), so the receiving agent
// sees a message from Gábor, not a spoofable string. /api/messages sits behind
// the dashboard bearer token + Cloudflare Access.
const MSG_STATUS_META = {
  pending: { label: () => t('messages.status.pending'), cls: 'badge-warm' },
  delivered: { label: () => t('messages.status.delivered'), cls: 'badge-active' },
  done: { label: () => t('messages.status.done'), cls: 'badge-active' },
  failed: { label: () => t('messages.status.failed'), cls: 'badge-paused' },
}
async function resolveOwnerName() {
  try {
    const res = await fetch('/api/kanban/assignees')
    if (res.ok) {
      const list = await res.json()
      const owner = Array.isArray(list) ? list.find(a => a.type === 'owner') : null
      if (owner && owner.name) return owner.name
    }
  } catch { /* fall through */ }
  return 'owner'
}

// === Messages page ===
// chatAgentHasAvatar: populated from /api/agents during loadChatAgentList
const chatAgentHasAvatar = new Map() // name -> true|false
let chatSelectedAgent = null

// The letter comes from the label the user sees, the colour from the agent id
// -- the same pairing the agent cards and the team tree use, so an avatar-less
// agent looks identical in all three.
function chatMonogramEl(agentName, size, label) {
  const letter = (label || agentName).charAt(0).toUpperCase()
  const color = monogramColor(agentName)
  return `<div class="chat-avatar chat-avatar-mono" style="width:${size}px;height:${size}px;background:${color};font-size:${Math.round(size*0.4)}px">${letter}</div>`
}

// Global onerror handler — avoids HTML-in-attribute escaping issues
window.chatImgError = function(img) {
  const name = img.getAttribute('data-agent-name') || img.alt || '?'
  const size = parseInt(img.width) || 32
  const letter = (img.getAttribute('data-agent-label') || name).charAt(0).toUpperCase()
  const color = monogramColor(name)
  const div = document.createElement('div')
  div.className = 'chat-avatar chat-avatar-mono'
  div.style.cssText = `width:${size}px;height:${size}px;background:${color};font-size:${Math.round(size*0.4)}px`
  div.textContent = letter
  img.replaceWith(div)
}

function chatAvatarHtml(agentName, size = 32) {
  const lower = agentName.toLowerCase()
  const hasAvatar = chatAgentHasAvatar.get(lower)
  if (!hasAvatar) return chatMonogramEl(agentName, size, chatDisplayName(agentName))
  const src = lower === mainAgentId().toLowerCase()
    ? `/api/marveen/avatar${avatarBust()}`
    : `/api/agents/${encodeURIComponent(lower)}/avatar${avatarBust()}`
  return `<img class="chat-avatar" src="${src}" width="${size}" height="${size}" alt="${escapeHtml(agentName)}" data-agent-name="${escapeHtml(agentName)}" data-agent-label="${escapeHtml(chatDisplayName(agentName))}" onerror="chatImgError(this)">`
}

// Guard against the boot race: the Messages page can be opened before the
// initial /api/marveen fetch resolves window._marveen. Until it does,
// mainAgentId() returns the literal 'marveen' FALLBACK, which IS a real agent
// id on a default install but is NOT one wherever the main agent was renamed
// -- composing to it creates a phantom "marveen" thread that sits pending
// forever and shows up as a duplicate of the true main agent (whatever id this
// install actually uses). Resolve _marveen before rendering any chat target.
async function ensureMarveenLoaded() {
  if (window._marveen?.agentId) return
  try {
    const r = await fetch('/api/marveen')
    if (r.ok) window._marveen = { ...(window._marveen || {}), ...(await r.json()) }
  } catch { /* sidebar falls back to the literal id -- best effort */ }
}

async function loadMessagesPage() {
  await ensureMarveenLoaded()
  await loadChatAgentList()
}

const CHAT_SYSTEM_AGENTS = new Set(['heartbeat','telegram-coordinator','channel-coordinator'])
// The owner's own message thread is pinned to the top and labelled "<name> (te)".
// The owner display name comes from the backend (OWNER_NAME via /api/marveen ->
// window._marveen.ownerName), not a hardcoded literal, so a renamed install
// recognizes its real owner. Empty until _marveen resolves (no false match).
function chatOwnerName() { return window._marveen?.ownerName || '' }

// The main agent's display name (BOT_NAME). mainAgentId() is the routing id
// (e.g. "marveen") used for matching, avatar lookups and API calls; this is
// what the user should SEE. Sourced from the backend (/api/marveen -> name,
// mirrored into _brandTokens.bot by initSidebarBrand), so a renamed install
// shows its real bot name. Falls back to the id before _marveen resolves.
// Regression #519/#520: keep the four Messages-view display points routing the
// main agent id through chatDisplayName -- a later refactor once stripped this
// and leaked the raw routing id again. Guarded by messages-view-display-name.test.ts.
function mainAgentDisplayName() {
  return window._marveen?.name || window._brandTokens?.bot || mainAgentId()
}
// Map a routing agent id to its user-facing label: the main agent's id becomes
// its BOT_NAME display name; every other agent is looked up in the fetched
// `agents` list (/api/agents, each entry has .name = raw id, .displayName =
// human name) and falls back to the raw id only if that agent isn't in the
// list (e.g. it's been removed since the page loaded).
// Regression #519/#520: keep the four Messages-view display points routing the
// main agent id through chatDisplayName -- a later refactor once stripped this
// and leaked the raw routing id again. Guarded by messages-view-display-name.test.ts.
// Boss, 2026-08-05: the old "every other agent's id IS its display name"
// assumption was wrong -- sub-agents (e.g. "lackor2-bot" itself shown from
// another agent's perspective, or any bot with a separate BRAND_NAME) leaked
// their raw routing id all over the Messages view.
function chatDisplayName(name) {
  if (name === mainAgentId()) return mainAgentDisplayName()
  return agents.find(a => a.name === name)?.displayName || name
}

// A nev-feloldas a modul-szintu `agents` listabol dolgozik, amit viszont CSAK
// az Ugynokok oldal betoltese tolt fel. Ezert barmelyik masik oldal, ami nevet
// akar mutatni (pl. a Jovahagyasok ellenorzes-oszlopa), a nyers azonositora
// esett vissza: Boss "usalackor"-t latott ott, ahol mellette "Szakerto" all
// (2026-08-10). Ez a helper behuzza a listat, ha meg ures -- egyetlen kis
// keres, es csak egyszer.
async function ensureAgentsLoaded() {
  if (agents.length) return
  try {
    const r = await fetch('/api/agents')
    if (r.ok) agents = await r.json()
  } catch { /* marad a nyers azonosito, ez csak megjelenites */ }
}

function chatLastSeenKey(agentName) { return 'chat_last_seen_' + agentName }
function chatGetLastSeen(agentName) { return parseInt(localStorage.getItem(chatLastSeenKey(agentName)) || '0', 10) }
function chatMarkSeen(agentName, maxId) {
  if (maxId > chatGetLastSeen(agentName)) localStorage.setItem(chatLastSeenKey(agentName), String(maxId))
}
function chatIsUnread(agentName, threadInfo) {
  const owner = chatOwnerName()
  if (!owner || agentName !== owner) return false
  if (!threadInfo?.lastMsg) return false
  return threadInfo.lastMsg.id > chatGetLastSeen(agentName)
}

async function loadChatAgentList() {
  const sidebar = document.getElementById('chatAgentList')
  if (!sidebar) return
  try {
    // Load fleet agents + threads in parallel (the federation status fetch is
    // failure-proof: it must never take down the Messages page)
    const [agentsRes, threadsRes, fedStatus] = await Promise.all([
      fetch('/api/agents'),
      fetch('/api/messages/threads'),
      fetch('/api/federation/status').then((r) => (r.ok ? r.json() : null)).catch(() => null),
    ])
    const agentsRaw = agentsRes.ok ? await agentsRes.json() : []
    const threads = threadsRes.ok ? await threadsRes.json() : []
    if (fedStatus && Array.isArray(fedStatus.peers)) federatedPeerStatus = fedStatus.peers

    // Build fleet list: API agents + marveen, minus system agents; plus
    // federated agents from the poller cache so a remote conversation can be
    // STARTED without prior history. The system-agent filter runs on the
    // unqualified segment too ('teodor/heartbeat' is just as much noise).
    const fleetNames = [mainAgentId(), ...agentsRaw.map(a => a.name || a)]
      .filter(n => !CHAT_SYSTEM_AGENTS.has(n))
      .filter((n, i, arr) => arr.indexOf(n) === i)
    for (const fa of federatedAgentEntries()) {
      if (!fleetNames.includes(fa.qualified) && !CHAT_SYSTEM_AGENTS.has(fa.qualified.split('/').pop())) {
        fleetNames.push(fa.qualified)
      }
    }

    // Populate avatar map from API data
    chatAgentHasAvatar.clear()
    chatAgentHasAvatar.set(mainAgentId(), true)
    for (const a of agentsRaw) {
      if (a.name) chatAgentHasAvatar.set(a.name, !!a.hasAvatar)
    }

    // Build index from /api/messages/threads (per-agent, no global-window bug)
    const threadIndex = new Map() // agentName -> {lastMessage, count}
    for (const t of threads) {
      if (t.agent) threadIndex.set(t.agent, { lastMsg: t.lastMessage, count: t.count || 0 })
    }
    // Also include thread agents not in fleet (e.g. the owner's own direct msgs).
    // Suppress the literal 'marveen' fallback id when it is NOT the real main
    // agent: a stale phantom thread (from the boot-race bug) would otherwise
    // render as a duplicate of the true main agent.
    for (const t of threads) {
      if (t.agent === 'marveen' && mainAgentId() !== 'marveen') continue
      if (t.agent && !fleetNames.includes(t.agent) && !CHAT_SYSTEM_AGENTS.has(t.agent)) {
        fleetNames.push(t.agent)
      }
    }

    // Sort: owner pinned first, then agents with messages by recency, rest alphabetical
    const owner = chatOwnerName()
    const sorted = [...fleetNames].sort((a, b) => {
      if (owner && a === owner) return -1
      if (owner && b === owner) return 1
      const aHas = threadIndex.has(a), bHas = threadIndex.has(b)
      if (aHas && !bHas) return -1
      if (!aHas && bHas) return 1
      if (aHas && bHas) {
        const aTime = threadIndex.get(a).lastMsg?.created_at || 0
        const bTime = threadIndex.get(b).lastMsg?.created_at || 0
        return bTime - aTime
      }
      return a.localeCompare(b)
    })

    sidebar.innerHTML = sorted.map(name => {
      const info = threadIndex.get(name)
      const lm = info?.lastMsg
      const when = lm?.created_at ? new Date(lm.created_at * 1000).toLocaleTimeString('hu-HU', {hour:'2-digit',minute:'2-digit'}) : ''
      const preview = lm ? (lm.content || '').replace(/\n/g,' ').slice(0, 60) : t('messages.empty')
      const isSelected = name === chatSelectedAgent ? ' selected' : ''
      const dimmed = info ? '' : ' style="opacity:0.5"'
      const unread = chatIsUnread(name, info)
      const displayName = owner && name === owner ? owner + ' (te)' : chatDisplayName(name)
      return `<div class="chat-agent-item${isSelected}${unread ? ' unread' : ''}" data-agent="${escapeHtml(name)}"${dimmed}>
        <div class="chat-agent-avatar">${chatAvatarHtml(name, 40)}</div>
        <div class="chat-agent-info">
          <div class="chat-agent-name">${escapeHtml(displayName)}${unread ? '<span class="chat-unread-dot"></span>' : ''}</div>
          <div class="chat-agent-preview ${unread ? 'unread-preview' : ''}">${escapeHtml(preview)}</div>
        </div>
        <div class="chat-agent-time">${when}</div>
      </div>`
    }).join('')

    sidebar.querySelectorAll('.chat-agent-item').forEach(el => {
      el.addEventListener('click', () => {
        sidebar.querySelectorAll('.chat-agent-item').forEach(x => x.classList.remove('selected'))
        el.classList.add('selected')
        chatSelectedAgent = el.dataset.agent
        loadChatThread(chatSelectedAgent)
      })
    })

    if (chatSelectedAgent && chatThreadState.agent !== chatSelectedAgent) {
      // Preselected target (e.g. the federated card's message button): open
      // its thread. Direct loadChatThread fallback covers targets with no
      // sidebar entry yet (composer + history render for any id).
      const el = sidebar.querySelector(`.chat-agent-item[data-agent="${CSS.escape(chatSelectedAgent)}"]`)
      if (el) el.click()
      else loadChatThread(chatSelectedAgent)
    } else if (!chatSelectedAgent) {
      const first = sidebar.querySelector('.chat-agent-item')
      if (first) first.click()
    }
  } catch (e) {
    sidebar.innerHTML = `<div class="chat-sidebar-empty">${t('messages.sidebar_error', { msg: escapeHtml(String(e.message||e)) })}</div>`
  }
}

// Pagination state for the open thread
const chatThreadState = { agent: null, minLoadedId: null, hasMore: true, loading: false }
const CHAT_PAGE_SIZE = 10
const CHAT_LOAD_MORE = 20

async function loadChatThread(agentName) {
  const panel = document.getElementById('chatThreadPanel')
  if (!panel) return

  chatThreadState.agent = agentName
  chatThreadState.minLoadedId = null
  chatThreadState.hasMore = true
  chatThreadState.loading = false

  const owner = chatOwnerName()
  const threadDisplayName = owner && agentName === owner ? owner + ' (te)' : chatDisplayName(agentName)

  panel.innerHTML = `
    <div class="chat-thread-header">
      ${chatAvatarHtml(agentName, 32)}
      <span class="chat-thread-title">${escapeHtml(threadDisplayName)}</span>
      <button class="btn-secondary btn-compact" style="margin-left:auto" onclick="loadChatThread('${escapeHtml(agentName)}')">
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>
      </button>
    </div>
    <div class="chat-bubbles" id="chatBubbles"><div class="chat-loading-indicator" id="chatLoadingTop" style="display:none;text-align:center;padding:8px;font-size:11px;color:var(--text-muted)">${t('messages.loading')}</div></div>
    <div class="chat-compose">
      <div class="chat-compose-row">
        <textarea id="chatComposeText" class="chat-compose-input" rows="2" placeholder="${t('messages.placeholder', { agent: escapeHtml(chatDisplayName(agentName)) })}"></textarea>
        <button class="btn-primary btn-compact chat-send-btn" id="chatSendBtn">${t('messages.send_btn')}</button>
      </div>
    </div>
  `

  document.getElementById('chatSendBtn')?.addEventListener('click', () => sendChatMessage(agentName))
  document.getElementById('chatComposeText')?.addEventListener('keydown', e => {
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); sendChatMessage(agentName) }
  })

  // Initial load
  await fetchChatPage(agentName, null, CHAT_PAGE_SIZE, 'replace')
  // Mark thread as read (localStorage last-seen)
  const threadData = (await fetch('/api/messages/threads').then(r => r.ok ? r.json() : []).catch(() => []))
    .find(t => t.agent === agentName)
  if (threadData?.lastMessage?.id) {
    chatMarkSeen(agentName, threadData.lastMessage.id)
    // Remove unread indicator from sidebar item
    document.querySelector(`.chat-agent-item[data-agent="${CSS.escape(agentName)}"]`)?.classList.remove('unread')
    const dot = document.querySelector(`.chat-agent-item[data-agent="${CSS.escape(agentName)}"] .chat-unread-dot`)
    if (dot) dot.remove()
    const preview = document.querySelector(`.chat-agent-item[data-agent="${CSS.escape(agentName)}"] .unread-preview`)
    if (preview) preview.classList.remove('unread-preview')
  }

  // Scroll-up pagination handler
  const bubbles = document.getElementById('chatBubbles')
  if (bubbles) {
    bubbles.addEventListener('scroll', () => {
      if (bubbles.scrollTop < 80 && chatThreadState.hasMore && !chatThreadState.loading
          && chatThreadState.agent === agentName) {
        fetchChatPage(agentName, chatThreadState.minLoadedId, CHAT_LOAD_MORE, 'prepend')
      }
    })
  }
}

function buildBubbleHtml(m) {
  const isOutgoing = m.from_agent === mainAgentId()
  // senderName stays the routing id (avatar lookup keys off it); senderLabel is
  // what the user sees, so the main agent reads as its BOT_NAME, not "marveen".
  const senderName = isOutgoing ? mainAgentId() : m.from_agent
  const senderLabel = chatDisplayName(senderName)
  const when = m.created_at ? new Date(m.created_at * 1000).toLocaleString('hu-HU', {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : ''
  const statusMetaRaw = MSG_STATUS_META[m.status] || { label: m.status || '', cls: 'badge' }
  const statusMeta = { ...statusMetaRaw, label: typeof statusMetaRaw.label === 'function' ? statusMetaRaw.label() : statusMetaRaw.label }
  return `<div class="chat-bubble-row ${isOutgoing ? 'outgoing' : 'incoming'}" data-msg-id="${m.id}">
    ${!isOutgoing ? `<div class="chat-bubble-avatar">${chatAvatarHtml(senderName, 28)}</div>` : ''}
    <div class="chat-bubble ${isOutgoing ? 'bubble-out' : 'bubble-in'}">
      <div class="bubble-meta">
        ${!isOutgoing ? `<span class="bubble-sender">${escapeHtml(senderLabel)}</span>` : ''}
        <span class="bubble-id-chip">#${m.id}</span>
        <span class="badge ${statusMeta.cls}" style="font-size:10px">${escapeHtml(statusMeta.label)}</span>
        ${m.status === 'pending' && m.to_agent === mainAgentId() ? `<span style="font-size:10px;color:var(--text-muted)">${escapeHtml(t('messages.pending_main_hint'))}</span>` : ''}
        ${m.origin_note ? `<span class="badge" style="font-size:10px" title="Self-declared by the sender, not verified (card 06f062e4)">origin: ${escapeHtml(m.origin_note)}</span>` : ''}
      </div>
      <div class="bubble-text">${linkifyKanbanRefs(m.content || '')}</div>
      <div class="bubble-time">${when}</div>
    </div>
    ${isOutgoing ? `<div class="chat-bubble-avatar">${chatAvatarHtml(mainAgentId(), 28)}</div>` : ''}
  </div>`
}

async function fetchChatPage(agentName, beforeId, limit, mode) {
  if (chatThreadState.loading) return
  chatThreadState.loading = true
  const container = document.getElementById('chatBubbles')
  const loadingIndicator = document.getElementById('chatLoadingTop')
  if (!container) { chatThreadState.loading = false; return }
  if (loadingIndicator && mode === 'prepend') loadingIndicator.style.display = 'block'
  try {
    let url = `/api/messages?agent=${encodeURIComponent(agentName)}&limit=${limit}`
    if (beforeId) url += `&before=${beforeId}`
    const res = await fetch(url)
    if (!res.ok) throw new Error('HTTP ' + res.status)
    const msgs = await res.json()
    const sorted = Array.isArray(msgs) ? [...msgs].sort((a, b) => (a.created_at || 0) - (b.created_at || 0)) : []

    if (mode === 'replace') {
      if (sorted.length === 0) {
        container.innerHTML = '<p class="activity-empty">' + t('messages.empty_thread') + '</p>'
      } else {
        container.innerHTML = '<div class="chat-loading-indicator" id="chatLoadingTop" style="display:none;text-align:center;padding:8px;font-size:11px;color:var(--text-muted)">' + t('messages.loading') + '</div>'
        container.insertAdjacentHTML('beforeend', sorted.map(buildBubbleHtml).join(''))
        container.scrollTop = container.scrollHeight
      }
      if (sorted.length < limit) chatThreadState.hasMore = false
    } else { // prepend
      if (loadingIndicator) loadingIndicator.style.display = 'none'
      if (!sorted.length) { chatThreadState.hasMore = false; chatThreadState.loading = false; return }
      if (sorted.length < limit) chatThreadState.hasMore = false
      const prevHeight = container.scrollHeight
      const indicator = document.getElementById('chatLoadingTop')
      const html = sorted.map(buildBubbleHtml).join('')
      if (indicator) {
        indicator.insertAdjacentHTML('afterend', html)
      } else {
        container.insertAdjacentHTML('afterbegin', html)
      }
      // Restore scroll position so view doesn't jump
      container.scrollTop = container.scrollHeight - prevHeight
    }

    if (sorted.length > 0) {
      const minId = Math.min(...sorted.map(m => m.id))
      if (chatThreadState.minLoadedId === null || minId < chatThreadState.minLoadedId) {
        chatThreadState.minLoadedId = minId
      }
    }
  } catch (e) {
    if (loadingIndicator) loadingIndicator.style.display = 'none'
    if (mode === 'replace') {
      container.innerHTML = `<p class="activity-empty">Hiba: ${escapeHtml(String(e.message||e))}</p>`
    }
  } finally {
    chatThreadState.loading = false
  }
}

function renderChatBubbles(msgs, agentName) {
  const container = document.getElementById('chatBubbles')
  if (!container) return
  if (!msgs || msgs.length === 0) {
    container.innerHTML = '<p class="activity-empty">' + t('messages.empty_thread') + '</p>'
    return
  }
  const sorted = [...msgs].sort((a,b) => (a.created_at||0) - (b.created_at||0))
  container.innerHTML = sorted.map(buildBubbleHtml).join('')
  container.scrollTop = container.scrollHeight
}

async function sendChatMessage(toAgent) {
  const textarea = document.getElementById('chatComposeText')
  const btn = document.getElementById('chatSendBtn')
  const content = textarea?.value?.trim()
  if (!content) { textarea?.focus(); return }
  if (btn) btn.disabled = true
  try {
    const from = await resolveOwnerName()
    const res = await fetch('/api/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ from, to: toAgent, content }),
    })
    if (!res.ok) { const err = await res.json(); throw new Error(err.error || 'Hiba') }
    if (textarea) textarea.value = ''
    showToast(t('messages.sent'))
    await loadChatThread(toAgent)
    await loadChatAgentList()
  } catch (e) {
    showToast(t('messages.error_send', { msg: e.message || e }))
  } finally {
    if (btn) btn.disabled = false
  }
}

document.getElementById('chatRefreshBtn')?.addEventListener('click', () => {
  loadChatAgentList()
  if (chatSelectedAgent) loadChatThread(chatSelectedAgent)
})

function renderTeamEditor(agent, allAgents) {
  const team = agent.team || { role: 'member', reportsTo: null, delegatesTo: [], autoDelegation: false, trustFrom: [] }
  document.getElementById('editTeamRole').value = team.role || 'member'
  const reportsSel = document.getElementById('editTeamReportsTo')
  reportsSel.innerHTML = ''
  const emptyOpt = document.createElement('option')
  emptyOpt.value = ''
  emptyOpt.textContent = t('team.reports_to_empty')
  reportsSel.appendChild(emptyOpt)
  for (const other of allAgents) {
    if (other.name === agent.name) continue
    const opt = document.createElement('option')
    opt.value = other.name
    opt.textContent = other.displayName || other.name
    if (team.reportsTo === other.name) opt.selected = true
    reportsSel.appendChild(opt)
  }
  const buildCheckboxList = (boxId, selected) => {
    const box = document.getElementById(boxId)
    box.innerHTML = ''
    for (const other of allAgents) {
      if (other.name === agent.name) continue
      const label = document.createElement('label')
      label.style.cssText = 'display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px'
      const cb = document.createElement('input')
      cb.type = 'checkbox'
      cb.value = other.name
      cb.checked = !!(selected && selected.includes(other.name))
      label.appendChild(cb)
      const span = document.createElement('span')
      span.textContent = other.displayName || other.name
      label.appendChild(span)
      box.appendChild(label)
    }
  }
  buildCheckboxList('editTeamDelegatesList', team.delegatesTo)
  buildCheckboxList('editTeamTrustFromList', team.trustFrom)
  document.getElementById('editTeamAutoDelegation').checked = !!team.autoDelegation
  // Only leaders make sense to delegate from -- hide the lists for members.
  const updateLeaderVisibility = () => {
    const isLeader = document.getElementById('editTeamRole').value === 'leader'
    document.getElementById('editTeamDelegatesGroup').style.display = isLeader ? '' : 'none'
    document.getElementById('editTeamAutoGroup').style.display = isLeader ? '' : 'none'
  }
  document.getElementById('editTeamRole').onchange = updateLeaderVisibility
  updateLeaderVisibility()
}

document.getElementById('saveTeamBtn').addEventListener('click', async () => {
  if (!currentAgent || currentAgent.role === 'main') return
  const btn = document.getElementById('saveTeamBtn')
  const role = document.getElementById('editTeamRole').value
  const reportsToRaw = document.getElementById('editTeamReportsTo').value
  const delegates = Array.from(document.querySelectorAll('#editTeamDelegatesList input[type=checkbox]:checked')).map(cb => cb.value)
  const trustFrom = Array.from(document.querySelectorAll('#editTeamTrustFromList input[type=checkbox]:checked')).map(cb => cb.value)
  const autoDelegation = document.getElementById('editTeamAutoDelegation').checked
  const originalText = btn.textContent
  btn.disabled = true
  btn.textContent = t('team.save_saving')
  try {
    const res = await fetch(`/api/agents/${encodeURIComponent(currentAgent.name)}/team`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        role,
        reportsTo: reportsToRaw || null,
        delegatesTo: role === 'leader' ? delegates : [],
        trustFrom,
        autoDelegation: role === 'leader' ? autoDelegation : false,
      }),
    })
    if (!res.ok) throw new Error()
    // The server sanitizes the team config (strips self-references and
    // unknown agent ids) and reports what it dropped in `warnings`. Surface
    // that to the operator so a mistyped name isn't silently lost.
    let warningMsg = ''
    try {
      const body = await res.json()
      const w = body && body.warnings
      if (w) {
        const parts = []
        if (Array.isArray(w.droppedSelf) && w.droppedSelf.length) {
          parts.push(`${t('team.dropped_self')}: ${w.droppedSelf.join(', ')}`)
        }
        if (Array.isArray(w.droppedUnknown) && w.droppedUnknown.length) {
          parts.push(`${t('team.dropped_unknown')}: ${w.droppedUnknown.join(', ')}`)
        }
        if (parts.length) warningMsg = parts.join(' · ')
      }
    } catch { /* body already consumed or not JSON -- OK, no warnings to show */ }
    showToast(warningMsg ? t('team.save_warning', { detail: warningMsg }) : t('team.save_ok'))
    btn.textContent = t('team.save_done')
    setTimeout(() => { btn.textContent = originalText; btn.disabled = false }, 1800)
    loadAgents()
  } catch {
    showToast(t('team.save_error'))
    btn.textContent = originalText
    btn.disabled = false
  }
})

// === Overview page ===
function formatRelative(ts) {
  const diff = Math.max(0, Date.now() - ts)
  const min = Math.floor(diff / 60000)
  if (min < 1) return t('common.time.now_abbr')
  if (min < 60) return t('common.time.min_abbr', { n: min })
  const hr = Math.floor(min / 60)
  if (hr < 24) return t('common.time.hour_abbr', { h: hr })
  const day = Math.floor(hr / 24)
  return t('common.time.day_abbr', { n: day })
}

// Overview "unused capabilities" widget: maps a capability id (as returned
// by /api/overview's unconfiguredCapabilities) to its display strings and
// the page it should link to. Add new opt-in integrations here as they gain
// a CAPABILITY_CHECKS entry server-side (src/web/routes/overview.ts).
const CAPABILITY_INFO = {
  openrouter: {
    labelKey: 'overview.capability.openrouter.label', descKey: 'overview.capability.openrouter.desc', vaultId: 'openrouter-fleet-key',
    stepsKey: 'vault.known.openrouter.steps', helpUrl: 'https://openrouter.ai/keys',
  },
  'groq-stt': {
    labelKey: 'overview.capability.groq_stt.label', descKey: 'overview.capability.groq_stt.desc', vaultId: 'groq-stt-key',
    stepsKey: 'vault.known.groq_stt.steps', helpUrl: 'https://console.groq.com/keys',
  },
}

// Setup state on the Overview, because that is where you look first. The card
// is coloured by the WORST missing tier, not by "something is missing":
// three unset EXTRAS used to paint this blood-red with a black button, which
// read as "the system is broken" when nothing was wrong. Alarm colours spent
// on convenience features teach the operator to ignore alarm colours.
// Silent once nothing is missing -- a permanent green banner is noise.
async function renderOverviewSetupStatus() {
  const box = document.getElementById('overviewSetupStatus')
  const list = document.getElementById('overviewSetupStatusList')
  if (!box || !list) return
  let d
  try {
    const res = await fetch('/api/setup-wizard')
    if (!res.ok) throw new Error('fetch failed')
    d = await res.json()
  } catch { box.hidden = true; return }

  const worst = d.worstTier || 'none'
  if (worst === 'none') { box.hidden = true; list.innerHTML = ''; return }

  // descFg is set explicitly per tone because .overview-capability-desc carries
  // a hardcoded light grey (#ccc) from when this card was always dark-on-red.
  // On the calm backgrounds it became grey-on-grey -- Boss could see that text
  // was there and could not read it.
  const TONE = {
    essential: { bg: 'var(--danger)', fg: '#fff', descFg: 'rgba(255,255,255,.85)', itemBg: 'rgba(0,0,0,.25)' },
    recommended: { bg: '#f59e0b', fg: '#111', descFg: 'rgba(0,0,0,.75)', itemBg: 'rgba(255,255,255,.45)' },
    extra: { bg: 'var(--card-bg, rgba(127,127,127,.10))', fg: 'var(--text)', descFg: 'var(--text-muted)', itemBg: 'rgba(127,127,127,.12)' },
  }[worst]

  const n = d.missingByTier ? d.missingByTier[worst] : 0
  const headline = worst === 'essential'
    ? t('wizard.summary.missing_required', { n })
    : t('wizard.summary.available', { n: (d.availableUnused || n) })

  // The card names the WORST tier only, which is right for tone and wrong as a
  // total: Boss filled in the 3 essentials, two lower-tier items surfaced, and
  // the honest question followed -- "ezt miert nem jelezte az elejen mar? hogy
  // nem 3 hanem 5 javitanivalo van?" (2026-08-15). Say the rest out loud on the
  // same card instead of revealing it one tier at a time.
  const byTier = d.missingByTier || {}
  const outstanding = (byTier.essential || 0) + (byTier.recommended || 0) + (byTier.extra || 0)
  const rest = Math.max(0, outstanding - n)
  const desc = worst === 'extra' ? t('wizard.tier.extra_note') : t('overview.setup.open_wizard')
  const descText = rest > 0 ? `${desc} ${t('overview.setup.also_later', { n: rest })}` : desc

  box.hidden = false
  box.style.background = TONE.bg
  box.style.border = worst === 'extra' ? '1px solid var(--border)' : 'none'
  const titleEl = box.querySelector('.overview-capabilities-title')
  if (titleEl) titleEl.style.color = TONE.fg
  list.innerHTML = `<a href="#" class="overview-capability-item"
      style="background:${TONE.itemBg};color:${TONE.fg}"
      onclick="switchPage('settings');activateSettingsTab('wizard');return false">
      <div class="overview-capability-label">${escapeHtml(headline)}</div>
      <div class="overview-capability-desc" style="color:${TONE.descFg}">${escapeHtml(descText)}</div>
    </a>`
}

function renderOverviewCapabilities(ids) {
  const box = document.getElementById('overviewCapabilities')
  const list = document.getElementById('overviewCapabilitiesList')
  const known = (ids || []).filter(id => CAPABILITY_INFO[id])
  if (!known.length) { box.hidden = true; list.innerHTML = ''; return }
  box.hidden = false
  list.innerHTML = known.map(id => {
    const info = CAPABILITY_INFO[id]
    return `<a href="#" class="overview-capability-item" onclick="switchPage('accounts');return false">
      <div class="overview-capability-label">${escapeHtml(t(info.labelKey))}</div>
      <div class="overview-capability-desc">${escapeHtml(t(info.descKey))}</div>
    </a>`
  }).join('')
}

// Rate-limit / usage-window widget (kanban ef06b18d): shows the main
// assistant's Claude plan usage (5h + 7d windows) captured by
// scripts/hooks/statusline.py, zero token cost since it's a local CLI tick,
// not a model turn. Boss's own thresholds: >=90% only small tasks, >=95% no
// programming, info/search only (see src/rate-limit-status.ts).
let _rateLimitLast = null
let _rateLimitTicker = null

function renderOverviewRateLimit(rateLimit, openrouterCredits, claudeAccounts) {
  // The rows count DOWN to each reset, so they go wrong just by sitting there --
  // and the overview only fetches when the page is opened. Redraw once a minute
  // from the data already in hand (no network, skipped while hidden).
  _rateLimitLast = { rateLimit, openrouterCredits, claudeAccounts }
  if (!_rateLimitTicker) {
    // Two cadences share one timer. Every minute: redraw from the data in hand
    // so the "resets in X" countdown stays right (no network). Every ~3 minutes,
    // while the Overview is the open page: RE-FETCH /api/overview so the numbers
    // themselves refresh. Boss 2026-08-27 (msg 579) watched the widget sit on a
    // 2-hour-old 15% while a live VS Code session on the same account showed
    // 45%: the old ticker only re-rendered the snapshot captured when the page
    // opened, so an idle agent's frozen percentage never moved on its own. A
    // redraw cannot fix a stale number -- only a re-fetch can. (It still cannot
    // be fresher than that agent's last statusLine tick, which is why the
    // "X perce mérve"/stale label stays; but a new tick is now picked up within
    // 3 minutes automatically, without the user reopening the page.)
    let _secsSinceRefetch = 0
    _rateLimitTicker = setInterval(async () => {
      if (document.hidden || !_rateLimitLast) return
      renderOverviewRateLimit(_rateLimitLast.rateLimit, _rateLimitLast.openrouterCredits, _rateLimitLast.claudeAccounts)
      _secsSinceRefetch += 60
      if (_secsSinceRefetch >= 180 && (location.hash.slice(1) || 'overview') === 'overview') {
        _secsSinceRefetch = 0
        try {
          const res = await fetch('/api/overview')
          if (res.ok) {
            const d = await res.json()
            renderOverviewRateLimit(d.rateLimit, d.openrouterCredits, d.claudeAccounts)
          }
        } catch { /* transient network error: keep showing the last good numbers */ }
      }
    }, 60_000)
  }
  const box = document.getElementById('overviewRateLimit')
  const bars = document.getElementById('overviewRateLimitBars')
  const meta = document.getElementById('overviewRateLimitMeta')
  const hasRateLimit = rateLimit && (rateLimit.fiveHour || rateLimit.sevenDay)
  const accounts = Array.isArray(claudeAccounts) ? claudeAccounts : []
  // Whether to show the box at all is a question about DATA; which rows to draw
  // is a question about CONFIGURED ACCOUNTS. Conflating the two is what made an
  // account disappear from the list the moment its numbers went missing.
  const anyAccountData = accounts.some(a => a.fiveHourPct !== null || a.sevenDayPct !== null)
  if (!hasRateLimit && !openrouterCredits && !anyAccountData) { box.hidden = true; return }
  box.hidden = false

  const locale = (window._lang === 'en') ? 'en-US' : 'hu-HU'
  // Boss 2026-08-10: a clock time answers the wrong question here -- "visszaall
  // 4:30" leaves you working out whether that is tonight or the day after. What
  // he wants to read off the row is HOW LONG he still has to wait, the way the
  // AI consoles put it. The absolute moment stays as the title tooltip.
  const fmtResetIn = (ms) => {
    if (!ms) return ''
    const mins = Math.round((ms - Date.now()) / 60_000)
    if (mins <= 0) return t('overview.ratelimit.resets_now')
    const d = Math.floor(mins / 1440)
    const h = Math.floor((mins % 1440) / 60)
    const m = mins % 60
    if (d) return h ? t('overview.ratelimit.in_days_hours', { d, h }) : t('overview.ratelimit.in_days', { d })
    if (h) return m ? t('overview.ratelimit.in_hours_mins', { h, m }) : t('overview.ratelimit.in_hours', { h })
    return t('overview.ratelimit.in_mins', { m })
  }
  const fmtResetAt = (ms) => ms ? t('overview.ratelimit.resets', { time: new Date(ms).toLocaleString(locale, { weekday: 'short', hour: '2-digit', minute: '2-digit' }) }) : ''
  const tierOf = (pct) => pct >= 95 ? 'critical' : (pct >= 90 ? 'caution' : 'normal')

  const row = (labelKey, win) => {
    if (!win || win.usedPct === null) return ''
    const pct = Math.max(0, Math.min(100, Math.round(win.usedPct)))
    return `<div class="overview-ratelimit-row">
      <div class="overview-ratelimit-row-head">
        <span>${escapeHtml(t(labelKey))}</span>
        <span><strong>${pct}%</strong>${win.resetsAt ? ` · <span title="${escapeHtml(fmtResetAt(win.resetsAt))}">${escapeHtml(fmtResetIn(win.resetsAt))}</span>` : ''}</span>
      </div>
      <div class="overview-ratelimit-track"><div class="overview-ratelimit-fill ${tierOf(pct)}" style="width:${pct}%"></div></div>
    </div>`
  }

  // Boss 2026-08-09 (multi-account project): one row per named Claude account
  // (main + every store/claude-plans.json entry), each labelled with the
  // account name and its currently active model -- not just a single
  // "the assistant" bar. Falls back to the old single-account row set when no
  // plans are registered, so an install with only the main agent is unchanged.
  // One bar per usage window. A window with no number keeps its bar (empty
  // track + "nincs adat") instead of being dropped: the account list has to
  // stay the same height whether or not the data happens to be there.
  // Boss 2026-08-10: while an account is actively working the live "used X%"
  // banner can scroll out of the scrape window, so the server falls back to
  // the last successfully read value (see scrapeClaudeAccountUsage's cache and
  // the stale-snapshot fallback) -- marked with a "~" so it does not read as a
  // fresh number.
  const windowBar = (labelKey, pct, resetsAt, stale) => {
    const label = escapeHtml(t(labelKey))
    if (pct === null || pct === undefined) {
      return `<div class="overview-ratelimit-row">
        <div class="overview-ratelimit-row-head">
          <span>${label}</span>
          <span class="overview-ratelimit-nodata">${escapeHtml(t('overview.ratelimit.no_data'))}</span>
        </div>
        <div class="overview-ratelimit-track"></div>
      </div>`
    }
    // A window whose reset time has PASSED no longer describes reality: the
    // allowance has rolled over, but our percentage is whatever was last
    // scraped from the agent's pane, and an idle agent never produces a fresh
    // one. Left alone this shows a stale 100% next to "bármelyik pillanatban"
    // indefinitely -- Boss watched exactly that all morning (2026-08-11) and
    // reasonably read it as the limit never resetting.
    if (resetsAt && resetsAt <= Date.now()) {
      return `<div class="overview-ratelimit-row">
        <div class="overview-ratelimit-row-head">
          <span>${label}</span>
          <span class="overview-ratelimit-nodata">${escapeHtml(t('overview.ratelimit.reset_done'))}</span>
        </div>
        <div class="overview-ratelimit-track"></div>
      </div>`
    }
    const p = Math.max(0, Math.min(100, Math.round(pct)))
    const resetSuffix = resetsAt
      ? ` · <span title="${escapeHtml(fmtResetAt(resetsAt))}">${escapeHtml(fmtResetIn(resetsAt))}</span>`
      : ''
    return `<div class="overview-ratelimit-row">
      <div class="overview-ratelimit-row-head">
        <span>${label}</span>
        <span><strong>${stale ? '~' : ''}${p}%</strong>${resetSuffix}</span>
      </div>
      <div class="overview-ratelimit-track"><div class="overview-ratelimit-fill ${tierOf(p)}" style="width:${p}%"></div></div>
    </div>`
  }

  // Boss 2026-08-10: the weekly window was missing from the per-account view --
  // only the 5-hour one was drawn, even though the 7-day number is what says
  // whether an account can work at all tomorrow. Every account now shows both.
  // Boss 2026-08-15: a "~" egy nem-muszaki felhasznalonak semmit nem mond -- a
  // VS Code 81%-ot irt, a Marveen ugyanarra a fiokra 11%-ot, es a kepernyon
  // semmi nem arulta el, hogy az a 11% harom oras meres. Mostantol a fiok neve
  // mellett ott all, MIKOR mertuk.
  // Boss 2026-08-17 (Telegram msg 370, "jah. lassuk mindig"): korabban csak
  // stale meresnel irtuk ki -- friss adatnal Boss szerint eddig is latszott
  // ez az info, es hianyzott amikor eltunt. Mostantol mindig kiirjuk, ha van
  // mikor mertuk adat, fuggetlenul attol hogy stale-e.
  const measuredAgo = (acc) => {
    if (!acc.measuredAt) return ''
    const mins = Math.max(0, Math.round((Date.now() - acc.measuredAt) / 60000))
    const txt = mins < 60
      ? t('overview.ratelimit.measured_mins', { m: mins })
      : t('overview.ratelimit.measured_hours', { h: Math.round(mins / 60) })
    return ` <span class="overview-ratelimit-age">${escapeHtml(txt)}</span>`
  }
  const accountBlock = (acc) => `<div class="overview-ratelimit-acct">
      <div class="overview-ratelimit-acct-head">${escapeHtml(acc.label)}${acc.model ? ' · ' + escapeHtml(acc.model) : ''}${measuredAgo(acc)}</div>
      ${windowBar('overview.ratelimit.five_hour', acc.fiveHourPct, acc.fiveHourResetsAt, acc.stale)}
      ${windowBar('overview.ratelimit.seven_day', acc.sevenDayPct, acc.sevenDayResetsAt, acc.stale)}
    </div>`

  let html = accounts.length
    ? accounts.map(accountBlock).join('')
    : (hasRateLimit ? (row('overview.ratelimit.five_hour', rateLimit.fiveHour) + row('overview.ratelimit.seven_day', rateLimit.sevenDay)) : '')

  // OpenRouter remaining balance (Boss, 2026-08-08: "ugyanaz mint a keret-%,
  // meddig dolgozhatok") -- same bar treatment, but $ instead of a plan window.
  if (openrouterCredits) {
    const pct = Math.max(0, Math.min(100, Math.round(openrouterCredits.usedPct ?? 0)))
    const fmtUsd = (n) => '$' + n.toFixed(2)
    html += `<div class="overview-ratelimit-row">
      <div class="overview-ratelimit-row-head">
        <span>${escapeHtml(t('overview.ratelimit.openrouter_balance'))}</span>
        <span><strong>${escapeHtml(fmtUsd(openrouterCredits.remaining))}</strong> ${escapeHtml(t('overview.ratelimit.openrouter_of', { total: fmtUsd(openrouterCredits.totalCredits) }))}</span>
      </div>
      <div class="overview-ratelimit-track"><div class="overview-ratelimit-fill ${tierOf(pct)}" style="width:${pct}%"></div></div>
    </div>`
  }
  bars.innerHTML = html

  meta.textContent = (hasRateLimit && rateLimit.stale) ? t('overview.ratelimit.stale') : t('overview.meta.live')
  // Boss 2026-08-10: dropped the on-page caution/critical banner -- with 3+
  // accounts shown in this same box it read as ambiguous (which account did
  // it mean?), and it's now redundant with the proactive Telegram alert
  // (store/ratelimit-telegram-alert.sh) that fires at 90%/99% per account.
}

// Non-Vault entries for the Fiokok (Accounts) page: core items that always
// run (no setup action possible/needed) and the two OAuth/CLI-driven
// integrations that -- unlike OpenRouter/Groq -- have no self-service
// dashboard flow yet, so the honest instruction is "ask Marvin in chat"
// rather than a broken "Connect" button. See CAPABILITY_INFO above for the
// Vault-backed entries (openrouter, groq-stt) this page also lists.
const ACCOUNT_EXTRA_INFO = {
  'claude-code': { labelKey: 'accounts.claude_code.label', descKey: 'accounts.claude_code.desc' },
  telegram: { labelKey: 'accounts.telegram.label', descKey: 'accounts.telegram.desc' },
  google: { labelKey: 'accounts.google.label', descKey: 'accounts.google.desc', flow: 'agent', agentHintKey: 'accounts.google.agent_hint' },
  github: { labelKey: 'accounts.github.label', descKey: 'accounts.github.desc', flow: 'agent', agentHintKey: 'accounts.github.agent_hint' },
}

function _accountInfoFor(id) {
  const vaultInfo = CAPABILITY_INFO[id]
  return vaultInfo ? { ...vaultInfo, flow: 'vault' } : ACCOUNT_EXTRA_INFO[id]
}

// The page used to draw two lists of its own here ("core" and "optional") out
// of _renderAccountItem, and the panel below drew a third -- so the same
// service, and the same Gmail address, stood on one screen up to three times
// (Boss, 2026-08-14: "van 3 panel es mind a 3 ugyanazt mutatja"). Both lists
// and their row builder are gone; the fetch stays, because the single panel
// feeds on the very same payload.
async function loadAccountsPage() {
  try {
    const res = await fetch('/api/accounts')
    _lastAccountsData = await res.json()
  } catch { /* ignore */ }
  renderClaudeAccountPanel(_keyServicesFromAccounts(_lastAccountsData))
  renderConnectionsPanel()
}

// The key-backed services the Accounts payload already reports, paired with the
// "where do I get this" metadata the setup wizard defined -- reused rather than
// restated, so a new integration is described in exactly one place.
let _lastAccountsData = null

// Every service the page knows about, in ONE list. The Accounts page used to
// carry two of its own ("core" and "optional") and this panel added a third,
// so OpenRouter and Groq appeared twice on the same screen -- the exact
// duplication the merge was supposed to remove. The old sections are gone; this
// is the list now.
//
// claude-code is excluded because the login rows above already ARE the Claude
// accounts, and by name rather than as one yes/no.
//
// `addable` marks the ones this page can genuinely set up here: a pasted key.
// Telegram, Google and GitHub are configured by their own flows elsewhere, so
// they are LISTED (you want to see them) but not offered in the add dropdown --
// a menu entry that cannot finish the job is worse than its absence.
function _keyServicesFromAccounts(data) {
  if (!data) return []
  const all = (data.core || []).concat(data.optional || [])
  return all
    .filter(item => item.id !== 'claude-code')
    .map(item => {
      const info = _accountInfoFor(item.id) || {}
      const vaultInfo = CAPABILITY_INFO[item.id]
      // What KIND of thing this is, in the operator's words rather than ours.
      // Calling Google and GitHub "kulcs" was wrong -- Boss said it plainly:
      // "a telegram is csak egy fiok... a github is! a google is". Only the
      // pasted-key ones are keys; the rest are accounts you sign in to.
      const kind = vaultInfo ? 'key' : 'account'
      return {
        id: item.id,
        kind,
        // The names, not just "configured": GitHub already carries three
        // accounts here and Google is multi-account too, and a single yes/no
        // row hid that completely (Boss, 2026-08-12: "tobb fiokosak vagyunk").
        accounts: Array.isArray(item.accounts) ? item.accounts : [],
        defaultAccount: item.defaultAccount || null,
        vaultId: vaultInfo ? vaultInfo.vaultId : null,
        label: info.labelKey ? t(info.labelKey) : item.id,
        helpUrl: info.helpUrl || null,
        stepsKey: info.stepsKey || null,
        configured: !!item.configured,
        addable: !!vaultInfo,
      }
    })
}

// --- Claude accounts (kanban #52) -------------------------------------------
// PARALLEL logins, not a switch (Boss, 2026-08-12): every account keeps its own
// credentials directory, so adding one leaves the others signed in. The flow the
// CLI imposes: it prints an authorize URL and then WAITS for a code that
// Anthropic's page shows the user. There is no callback we can intercept, so one
// paste is unavoidable -- but the waiting, the detecting and the registering all
// happen here instead of in a terminal, which is what the card was about.
let _claudeAuthPoll = null
// Decided once per flow, not on every 2s poll tick -- otherwise a manual box
// the operator opened by hand (because they ARE on another device) would snap
// shut again the next time the auto link is (re)read. Mirrors _wizClaudeManualDecided.
let _claudeAuthManualDecided = false
// A kattintas gesztusaban megnyitott, meg URES ful. A felugro-blokkolo CSAK a
// kattintashoz kotott window.open-t engedi at; az auth-cim viszont csak
// masodpercekkel kesobb all elo (a CLI-nek el kell indulnia). Ezert nyitunk
// elore egy ures fulet, es KESOBB iranyitjuk a cimre.
let _claudeAuthPendingTab = null
// Amit a bejelentkezes VEGEN kell elvegezni (az ugynok kartyajarol indulva: a
// friss hitelesitest a mar futo CLI nem olvassa be magatol -> ujrainditas).
let _claudeAuthOnDone = null

function _claudeAuthSetState(text, kind) {
  const el = document.getElementById('claudeAuthState')
  if (!el) return
  el.textContent = text || ''
  el.className = 'claude-auth-state' + (kind ? ' claude-auth-state-' + kind : '')
}

// One place for both kinds of account. A login and a key are not the same
// thing -- one is a browser sign-in that yields credentials on disk, the other
// is a string you paste -- but from the operator's side they answer the same
// question ("what is Marveen connected to?"), and having them on two different
// pages was one concept in two places (Boss, 2026-08-12: "jo otlet, csinald ugy").
let _claudeAuthKeyServices = []

// The Claude half no longer draws a list of its own: the same address was being
// listed here, in the Google section and in the connector section, three times
// on one screen (Boss, 2026-08-14: "van 3 panel es mind a 3 ugyanazt mutatja").
// It hands its accounts to the one place that draws them.
function _claudeAuthRenderList(accounts) {
  _hubClaude = accounts || []
  _hubSeen.claude = true
  renderAccountsHub()
}

// The keys stay a list, and stay SEPARATE from the account cards: a key is a
// pasted string, not a person -- a card with a "disconnect" button on it would
// promise something that makes no sense for a key.
function _accHubRenderKeys() {
  const el = document.getElementById('accountsKeyList')
  if (!el) return
  // Google is left OUT on purpose: its row here would name the very same
  // addresses the cards above already show, one by one -- which is the
  // duplication this rebuild removed ("az elsoben felsorolod a gmail fiokokat
  // es a masodikban is"). Telegram and GitHub have no card, so they stay.
  el.innerHTML = _claudeAuthKeyServices.filter(k => k.id !== 'google').map(k => {
    let who
    if (!k.configured) {
      who = `<span class="claude-auth-empty">${escapeHtml(t('claudeauth.key_unset'))}</span>`
    } else if (k.accounts.length) {
      // Name them, marking which one is used by default when there is a choice.
      who = k.accounts.map(name => {
        const mark = name === k.defaultAccount && k.accounts.length > 1
          ? ` <span class="claude-auth-plan">${escapeHtml(t('claudeauth.acct_default'))}</span>` : ''
        return escapeHtml(name) + mark
      }).join(', ')
    } else {
      who = `<span class="claude-auth-plan">${escapeHtml(t('claudeauth.key_set'))}</span>`
    }
    return `<div class="claude-auth-row">
      <span class="claude-auth-rowlabel">${escapeHtml(k.label)}</span>
      <span class="claude-auth-rowwho">${who}</span>
      <span class="claude-auth-kind">${escapeHtml(t(k.kind === 'key' ? 'claudeauth.kind_key' : 'claudeauth.kind_account'))}</span>
    </div>`
  }).join('')
}

// --- ONE panel, one card per account -----------------------------------------
//
// Boss, 2026-08-14: "nem lehetne ezeket egy panelre tenni? mindennel egyutt?
// levalasztas ellenorzes stb egy panal egy helyen mutatna? kell ez hogy
// szetszorni sok fele?"
//
// The three sources know three DIFFERENT things about the same address (is it
// signed in / does its mail-Drive-calendar work / are its Claude Code connectors
// authorized), and the operator had to hold all three lists in their head to see
// that it is ONE account. Here the three payloads flow in and one card per
// identity comes out.
//
// Each loader answers at its own pace -- a ten-address Google probe can take
// minutes -- so every one of them only DROPS its data and asks for a redraw.
// None waits for the others, and none can wipe another's half of a card.
let _hubClaude = []
let _hubGoogle = []
let _hubMcp = []
const _hubSeen = { claude: false, google: false, mcp: false }

function _hubEmailKey(email) { return String(email || '').trim().toLowerCase() }

/**
 * Fold the three lists into one card per identity.
 *
 * The key is the lower-cased e-mail address: that is the only thing all three
 * sources can carry for the same account. Where there is no address (a Google
 * account nobody has checked yet, a Claude login registered under a nickname),
 * the record's own id becomes the key WITH a prefix -- otherwise two different
 * kinds of "no address" would collapse onto one card.
 *
 * Pure on purpose: no DOM, no t(), so the merge rules can be tested directly.
 */
function _accHubMerge(claudeAccounts, googleAccounts, mcpAccounts) {
  const cards = []
  const byKey = new Map()
  const card = (key, title) => {
    let c = byKey.get(key)
    if (!c) {
      c = { key, title: title || '', email: '', isDefault: false, claude: [], google: [], mcp: [] }
      byKey.set(key, c)
      cards.push(c)
    }
    return c
  }

  // The Google addresses form the backbone: this is the "10 email" list, and an
  // address is the most recognisable name a card can carry.
  for (const g of googleAccounts || []) {
    const email = _hubEmailKey(g.email)
    const c = card(email || 'google:' + g.id, g.email || g.id)
    if (!c.email && g.email) c.email = g.email
    if (g.isDefault) c.isDefault = true
    c.google.push(g)
  }

  // A Claude login joins the SAME card when the address matches.
  //
  // Boss, 2026-08-29: kijelentkezes utan a Claude-resz ATKOLTOZOTT egy sajat,
  // arva kartyara a lap aljara ("minek ezeket itt lentebb is ujra odatenni?
  // igy atlathatatlan"). Ok: az e-mail cimet CSAK a bejelentkezett fioktol
  // tudjuk, tehat kijelentkezeskor a kulcs az e-mail cimrol a fiok sajat
  // azonositojara ("claude:<id>") valt -- ugyanaz a fiok, ket kulonbozo kartyan,
  // aszerint hogy epp be van-e lepve. A "Bejelentkezes" gomb megvolt, csak
  // nem ott, ahol elotte a "Kijelentkezes" allt.
  //
  // Ha nincs e-mail, a fiok SAJAT NEVE (id/label) donti el, melyik kartyara
  // tartozik: a Google-sorok ugyanezt a nevet viselik (usalackor), es azok a
  // kartyak mar allnak. Tudatosan csak PONTOS nev-egyezesre lep: ha nincs
  // ilyen nevu Google-sor, marad a sajat kartya, mert a "nem talalom" nem
  // ugyanaz, mint a "biztosan kulon fiok".
  const googleKeyByName = new Map()
  for (const c of cards) {
    for (const g of c.google) {
      const n = _hubEmailKey(g.id)
      if (n && !googleKeyByName.has(n)) googleKeyByName.set(n, c.key)
    }
  }
  const claudeCardKey = new Map()
  let defaultClaudeKey = null
  for (const a of claudeAccounts || []) {
    const id = a.identity || {}
    const email = _hubEmailKey(id.email)
    const byName = email ? null : (googleKeyByName.get(_hubEmailKey(a.label || a.id || '')) || null)
    const key = email || byName || 'claude:' + (a.id || '')
    const c = card(key, id.email || a.label || a.id || '')
    if (!c.email && id.email) c.email = id.email
    c.claude.push(a)
    claudeCardKey.set(a.id, key)
    if (a.isDefault) defaultClaudeKey = key
  }

  // Connectors belong to a CLAUDE account, not to a Google address. accountId
  // === null means "the default account" -- it goes onto whichever card holds
  // the default Claude login, instead of floating namelessly on its own.
  for (const m of mcpAccounts || []) {
    const key = (m.accountId === null || m.accountId === undefined)
      ? (defaultClaudeKey || 'claude:default')
      : (claudeCardKey.get(m.accountId) || 'claude:' + m.accountId)
    const c = card(key, m.label || m.accountId || '')
    c.mcp.push(m)
  }

  // Default first: that is the one Marveen uses when you do not say which.
  cards.sort((a, b) => (b.isDefault ? 1 : 0) - (a.isDefault ? 1 : 0))
  return cards
}

function _accHubPart(labelKey, body) {
  return `<div class="acc-part">
    <div class="acc-part-label">${escapeHtml(t(labelKey))}</div>
    <div class="conn-rows">${body}</div>
  </div>`
}

// One place that opens the login flow box and starts polling, whether the
// operator is ADDING an account (name typed above) or bringing a signed-out one
// BACK (button on its row). Two copies of this drifted apart once already.
// Hova tartozik alapbol a bejelentkezes-doboz (a Fiokok lap sajat aga).
// Egy dobozunk van, nem ketto: a masodik peldany elobb-utobb elcsuszna az
// elsotol -- pontosan ez szulte a 2026-08-29-i hibasorozatot. Ezert a MEGLEVO
// elemet mozgatjuk oda, ahonnan inditottak, majd vissza.
let _claudeAuthHome = null

function _claudeAuthMoveFlowTo(host) {
  const box = document.getElementById('claudeAuthFlow')
  if (!box) return null
  if (!_claudeAuthHome) _claudeAuthHome = { parent: box.parentNode, next: box.nextSibling }
  const target = host || _claudeAuthHome.parent
  if (host) {
    host.appendChild(box)
  } else if (_claudeAuthHome.parent) {
    _claudeAuthHome.parent.insertBefore(box, _claudeAuthHome.next)
  }
  return target ? box : box
}

/** Vissza a helyere -- a kartya bezarasakor, kulonben a doboz a modallal
 *  egyutt tunne el a DOM-bol, es a Fiokok lapon soha tobbe nem jelenne meg. */
function _claudeAuthReturnFlowHome() {
  if (!_claudeAuthHome) return
  const box = document.getElementById('claudeAuthFlow')
  if (box && _claudeAuthHome.parent) _claudeAuthHome.parent.insertBefore(box, _claudeAuthHome.next)
}

// `host`: az az elem, amelyen BELUL a doboznak meg kell jelennie. Ha nincs
// megadva, a doboz a sajat helyen (Fiokok lap) nyilik.
//
// Boss, 2026-08-29: "ne hozzon engem onnan sehova sem. ott helyben
// jelentkezzen be es maradjon is ott!" -- eddig a kartya gombja atvitt a
// Fiokok lapra ES becsukta a kartyat, mert a doboz csak ott letezett.
// A szerver kuldhet i18n-KULCSOT is a hiba melle: igy a mondat a felulet
// nyelven jelenik meg, nem mindig magyarul. A magyar `error` a tartalek.
function _claudeAuthErrorText(data) {
  if (data && data.errorKey) return t(data.errorKey, data.errorParams || {})
  return (data && data.error) || t('common.error_save')
}

async function _claudeAuthStartFlow(payload, host) {
  _claudeAuthMoveFlowTo(host || null)
  // Ugyanaz a hibaosztaly, mint a Google-jovahagyasnal: a horgony megtartja az
  // ELOZO folyamat linkjet, es a doboz elobb jelenik meg, mint a friss link.
  _setConsentLink('claudeAuthLink', '')
  _claudeAuthManualDecided = false
  const box = document.getElementById('claudeAuthFlow')
  if (box) {
    box.hidden = false
    // Boss, 2026-08-29: a kartyarol ide navigalva ("bejelentkezes" gomb) a doboz
    // lattavatlan messze lent ul, a "Uj Claude-fiok hozzaadasa" panel alatt -- a
    // gepnek unhide-olva volt, a felhasznalonak semmi nem tortent, mert a lap
    // tetejen allt. Ugyanez a mintakov, mint a _gconnOpenBlocked-nal.
    box.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
  }
  _claudeAuthSetState(t('claudeauth.state_starting'), null)
  try {
    const res = await fetch('/api/accounts/claude/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })
    const data = await res.json()
    if (!data.ok) { _claudeAuthSetState(_claudeAuthErrorText(data), 'bad'); return false }
  } catch (err) { _claudeAuthSetState(String(err.message || err), 'bad'); return false }
  _claudeAuthStopPoll()
  _claudeAuthPoll = setInterval(_claudeAuthTick, 2000)
  _claudeAuthTick()
  return true
}

// Signing out is the one irreversible button on this page, so it says WHO it
// stops before it does it -- by name, asked from the server, not guessed here.
async function _claudeAuthLogout(planId, who) {
  let preview = null
  try {
    const res = await fetch('/api/accounts/claude/logout-preview?planId=' + encodeURIComponent(planId || ''))
    preview = await res.json()
  } catch { /* a failed preview must not silently become a logout */ }
  if (!preview || !preview.ok) {
    showToast((preview && preview.error) || t('claudeauth.logout_preview_failed'), 8000, true)
    return
  }
  const agents = Array.isArray(preview.agents) ? preview.agents : []
  const msg = agents.length
    ? t('claudeauth.logout_confirm_agents', { who, agents: agents.join(', ') })
    : t('claudeauth.logout_confirm_none', { who })
  if (!confirm(msg)) return
  try {
    const res = await fetch('/api/accounts/claude/logout', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ planId: planId || null }),
    })
    const data = await res.json()
    if (!data.ok) { showToast(data.error || t('common.error_save'), 10000, true); return }
    showToast(t('claudeauth.logout_done', { who: data.email || who }), 9000, true)
  } catch (err) { showToast(String(err.message || err), 10000, true); return }
  // A Fiokok oldal listajat csak akkor frissitjuk innen, ha ott is vagyunk: az
  // ugynok kartyajarol hivva azok az elemek nincsenek a lapon, es egy hianyzo
  // doboz nem borithatja fel a mar sikeres kijelentkeztetest.
  if (document.getElementById('claudeAccountPanel')) _claudeAuthTick()
}

function _accHubClaudePart(rows) {
  const body = rows.map(a => {
    const id = a.identity || {}
    const who = id.loggedIn && id.email
      ? escapeHtml(id.email) + (id.subscriptionType ? ` <span class="claude-auth-plan">${escapeHtml(id.subscriptionType)}</span>` : '')
      : `<span class="claude-auth-empty">${escapeHtml(t('claudeauth.row_empty'))}</span>`
    // The default row is NAMED here rather than by the backend: the server
    // should not be shipping a Hungarian word to an English dashboard.
    const name = a.isDefault ? t('claudeauth.row_default') : (a.label || a.id || '')
    // Boss, 2026-08-29: sign out and back in has to be doable HERE. Without the
    // first button the only route was `claude auth logout` in a terminal, and
    // without the second a signed-out account could not be repaired at all --
    // typing its name into the "add account" box opened a SECOND directory
    // under a "-2" name while the agent stayed pinned to the first one.
    const plan = a.isDefault ? '' : (a.id || '')
    const btn = id.loggedIn
      ? `<button type="button" class="btn-secondary btn-compact acc-claude-logout" data-plan="${escapeAttr(plan)}" data-who="${escapeAttr(id.email || name)}">${escapeHtml(t('claudeauth.logout_btn'))}</button>`
      : `<button type="button" class="btn-secondary btn-compact acc-claude-relogin" data-plan="${escapeAttr(plan)}" data-default="${a.isDefault ? '1' : '0'}" data-who="${escapeAttr(name)}">${escapeHtml(t('claudeauth.relogin_btn'))}</button>`
    return `<div class="conn-row">
      <div class="conn-row-main">
        <span class="conn-row-name">${escapeHtml(name)}</span>
        <span class="conn-row-sub">${who}</span>
      </div>
      <div class="conn-row-actions">${btn}</div>
    </div>`
  }).join('')
  return _accHubPart('acchub.part_claude', body)
}

function _accHubGooglePart(rows, title) {
  const body = rows.map(a => {
    const svc = a.services || {}
    // Per SERVICE, not one yes/no: with ten addresses "one of them is broken"
    // is not an answer anybody can act on. An unchecked account shows no chips
    // at all rather than three grey ones that look like three failures.
    const chips = a.checkedAt === null ? '' : [
      ['gmail', 'gconn.svc_gmail'], ['calendar', 'gconn.svc_calendar'], ['drive', 'gconn.svc_drive'],
    ].map(([k, key]) => `<span class="conn-chip ${svc[k] ? 'conn-chip-on' : 'conn-chip-off'}">${escapeHtml(t(key))}</span>`).join('')
    // "invalid_grant" is what an unverified (Testing-status) app's refresh token
    // turns into after 7 days. The raw python message says nothing an operator
    // can use; the plain-language one says what to press.
    const state = a.kind === 'expired'
      ? `<span class="conn-note conn-note-bad">${escapeHtml(t('gconn.expired_note'))}</span>`
      : a.error
        ? `<span class="conn-note conn-note-bad">${escapeHtml(a.error)}</span>`
        : a.checkedAt === null
          ? `<span class="conn-note">${escapeHtml(t('gconn.never_checked'))}</span>`
          : `<span class="conn-note">${escapeHtml(t('gconn.checked_ago', { ago: formatRelative(a.checkedAt) }))}</span>`
    const id = escapeAttr(a.id)
    // The card heading already says the address; repeating it underneath is
    // noise. The nickname is only shown when it differs from the heading.
    const name = a.id === title ? '' : `<span class="conn-row-name">${escapeHtml(a.id)}</span>`
    return `<div class="conn-row">
      <div class="conn-row-main">${name}</div>
      <div class="conn-row-chips">${chips}${state}</div>
      <div class="conn-row-actions">
        <button class="btn-secondary btn-compact" data-gact="probe" data-id="${id}">${escapeHtml(t('gconn.check'))}</button>
        ${a.error ? `<button class="btn-primary btn-compact" data-gact="reauth" data-id="${id}">${escapeHtml(t('gconn.reauth'))}</button>` : ''}
        ${a.isDefault ? '' : `<button class="btn-secondary btn-compact" data-gact="default" data-id="${id}">${escapeHtml(t('gconn.make_default'))}</button>`}
        <button class="btn-secondary btn-compact" data-gact="remove" data-id="${id}">${escapeHtml(t('gconn.remove'))}</button>
      </div>
    </div>`
  }).join('')
  return _accHubPart('acchub.part_google', body)
}

function _accHubMcpServerHtml(acct, s) {
  // 'agent-managed' is NOT a failure: the probe cannot start a channel plugin
  // the way the agent does, so it reports a dead server while the real poller is
  // running. Saying "hibás" there sent Boss looking for a fault in a Telegram
  // he uses daily (2026-08-15) -- so it gets its own, calm wording.
  const statusKey = s.status === 'connected' ? 'mconn.status_ok'
    : s.status === 'pending' ? 'mconn.status_pending'
      : s.fix === 'agent-managed' ? 'mconn.status_agent'
        : s.fix === 'login' ? 'mconn.status_login' : 'mconn.status_broken'
  const pillClass = s.status === 'connected' ? 'conn-pill-ok'
    : s.fix === 'agent-managed' ? 'conn-pill-neutral'
      : s.fix === 'login' ? 'conn-pill-warn' : 'conn-pill-bad'
  // One button only where a button can genuinely finish the job. The measured
  // dead end (a second Google identity) gets a sentence that points at the half
  // of the page that CAN do it.
  let action = ''
  if (s.fix === 'login') {
    action = `<button class="btn-primary btn-compact" data-mact="login"
      data-account="${escapeAttr(acct.accountId === null || acct.accountId === undefined ? '' : acct.accountId)}"
      data-server="${escapeAttr(s.name)}">${escapeHtml(t('mconn.fix_login'))}</button>`
  } else if (s.fix === 'unsupported') {
    action = `<span class="conn-note">${escapeHtml(t('mconn.fix_unsupported'))}</span>`
  } else if (s.fix === 'approve') {
    action = `<span class="conn-note">${escapeHtml(t('mconn.fix_approve'))}</span>`
  } else if (s.fix === 'agent-managed') {
    action = `<span class="conn-note">${escapeHtml(t('mconn.fix_agent'))}</span>`
  } else if (s.fix === 'broken') {
    action = `<span class="conn-note conn-note-bad">${escapeHtml(t('mconn.fix_broken', { msg: s.reason || '' }))}</span>`
  }
  const what = _connWhat(s.name)
  return `<div class="conn-row">
    <div class="conn-row-main">
      <span class="conn-row-name">${escapeHtml(_connLabel(s.name))}</span>
      <span class="conn-pill ${pillClass}">${escapeHtml(t(statusKey))}</span>
      ${what ? `<span class="conn-row-sub">${escapeHtml(what)}</span>` : ''}
    </div>
    <div class="conn-row-actions">${action}</div>
  </div>`
}

function _accHubMcpPart(rows) {
  const many = rows.length > 1
  const body = rows.map(acct => {
    // The agent names are what make a config directory concrete: nobody thinks
    // "store/accounts/lackor3", everybody thinks "north".
    const who = (acct.agents && acct.agents.length)
      ? t('mconn.used_by', { agents: acct.agents.join(', ') })
      : t('mconn.used_by_none')
    let inner
    if (acct.error) {
      inner = `<div class="conn-note conn-note-bad">${escapeHtml(acct.error)}</div>`
    } else if (!acct.servers || !acct.servers.length) {
      inner = `<div class="conn-empty">${escapeHtml(t('mconn.empty'))}</div>`
    } else {
      inner = acct.servers.map(s => _accHubMcpServerHtml(acct, s)).join('')
    }
    // Only worth naming when one card carries more than one config directory --
    // otherwise it just repeats the card heading.
    const head = many
      ? `<div class="conn-note">${escapeHtml(acct.label || acct.accountId || t('mconn.default_account'))}</div>`
      : ''
    return `${head}${inner}<div class="conn-note">${escapeHtml(who)}</div>`
  }).join('')
  return _accHubPart('acchub.part_mcp', body)
}

function _accHubCardHtml(c) {
  const title = c.title || t('mconn.default_account')
  const parts = []
  if (c.claude.length) parts.push(_accHubClaudePart(c.claude))
  if (c.google.length) parts.push(_accHubGooglePart(c.google, title))
  if (c.mcp.length) parts.push(_accHubMcpPart(c.mcp))
  // `conn-account` + `conn-account-name` are not decoration: the connector flow
  // reads the account's name out of the card it was clicked in
  // (closest('.conn-account')), so the title of "authorize Drive for WHICH
  // account" stays correct.
  return `<div class="conn-account acc-card">
    <div class="acc-card-head">
      <span class="conn-account-name">${escapeHtml(title)}</span>
      ${c.isDefault ? `<span class="conn-badge">${escapeHtml(t('gconn.default_badge'))}</span>` : ''}
      ${c.email && c.email !== title ? `<span class="conn-row-sub">${escapeHtml(c.email)}</span>` : ''}
    </div>
    ${parts.join('')}
  </div>`
}

// Boss, 2026-08-29: a hozzaadas fent van, de osszecsukva. Az EGYETLEN eset,
// amikor magatol kinyilik: nincs meg egy kartya sem -- friss telepitesen ott
// ez az egyetlen ertelmes teendo, es egy osszecsukott sor mogott elrejtve
// ugyanaz a nema zsakutca volna, mint a bejelentkezes-gombnal.
//
// A NULLA ket dolgot jelenthet: "meg nincs fiok" vagy "meg nem jott meg a
// lista". Ezert nem a kartyak szamabol dontunk, hanem megkerdezzuk a
// forrasokat: amig egyik loader sem valaszolt (_hubSeen), nem nyitunk ki
// semmit -- a betoltes kozbeni villanas ugyanolyan hazugsag volna.
function _accHubSyncAddOpen(cardCount) {
  const det = document.getElementById('accountsAddDetails')
  if (!det) return
  if (det.dataset.wired !== '1') {
    det.dataset.wired = '1'
    // Amint o maga hozzanyul, a gep nem allitgatja tovabb: semmi nem csukja
    // ossze az orra elott azt, amit epp kinyitott.
    det.addEventListener('toggle', () => { det.dataset.userTouched = '1' })
  }
  if (det.dataset.userTouched === '1') return
  const answered = _hubSeen.claude || _hubSeen.google || _hubSeen.mcp
  if (!answered) return
  det.open = cardCount === 0
}

function renderAccountsHub() {
  _accHubRenderKeys()
  const el = document.getElementById('accountsHubList')
  if (!el) return
  const cards = _accHubMerge(_hubClaude, _hubGoogle, _hubMcp)
  if (!cards.length) {
    // Two different states, two different sentences: "still loading" is not the
    // same as "nothing is connected", and saying the second one during the first
    // makes the operator think everything was lost.
    const loading = !_hubSeen.claude && !_hubSeen.google && !_hubSeen.mcp
    el.innerHTML = `<div class="conn-empty">${escapeHtml(t(loading ? 'acchub.loading' : 'acchub.empty'))}</div>`
    _accHubSyncAddOpen(0)
    return
  }
  el.innerHTML = cards.map(_accHubCardHtml).join('')
  _accHubSyncAddOpen(cards.length)
  // Delegated, because this list is rebuilt on every poll tick: a listener put
  // on the buttons themselves would be thrown away two seconds later.
  if (el.dataset.wired !== '1') {
    el.dataset.wired = '1'
    el.addEventListener('click', (e) => {
      const out = e.target.closest('.acc-claude-logout')
      if (out) { _claudeAuthLogout(out.dataset.plan || '', out.dataset.who || ''); return }
      const back = e.target.closest('.acc-claude-relogin')
      if (back) {
        // The install's own account is repaired through the 'default' target;
        // a named one by its id. Neither asks the operator to type a name.
        const payload = back.dataset.default === '1' ? { target: 'default' } : { planId: back.dataset.plan }
        _claudeAuthStartFlow(payload)
      }
    })
  }
}

// Which services can be added, and how. A login entry needs the provider's own
// CLI on this machine, which is why only the one we can actually drive is
// offered rather than a row of buttons that would fail on click.
function _claudeAuthServices() {
  const out = [{ value: 'claude', kind: 'login', label: t('claudeauth.svc_claude') }]
  for (const k of _claudeAuthKeyServices) {
    // Listed-but-not-addable services (Telegram, Google, GitHub) are configured
    // by their own flows elsewhere; offering them here would be a menu entry
    // that cannot finish the job.
    if (!k.addable) continue
    out.push({ value: 'key:' + k.vaultId, kind: 'key', label: k.label, vaultId: k.vaultId, helpUrl: k.helpUrl, stepsKey: k.stepsKey })
  }
  return out
}

function _claudeAuthSyncServiceUi() {
  const sel = document.getElementById('claudeAuthService')
  if (!sel) return
  const services = _claudeAuthServices()
  const current = sel.value
  sel.innerHTML = services.map(sv => `<option value="${escapeAttr(sv.value)}">${escapeHtml(sv.label)}</option>`).join('')
  if (services.some(sv => sv.value === current)) sel.value = current
  const chosen = services.find(sv => sv.value === sel.value) || services[0]
  const isKey = chosen && chosen.kind === 'key'
  document.getElementById('claudeAuthLoginMode').hidden = !!isKey
  document.getElementById('claudeAuthKeyMode').hidden = !isKey
  if (isKey) {
    const help = document.getElementById('claudeAuthKeyHelp')
    help.href = chosen.helpUrl || '#'
    document.getElementById('claudeAuthKeySteps').textContent = chosen.stepsKey ? t(chosen.stepsKey) : ''
    document.getElementById('claudeAuthKeyMode').dataset.vaultId = chosen.vaultId
    document.getElementById('claudeAuthKeyMode').dataset.label = chosen.label
  }
}

function _claudeAuthStopPoll() {
  if (_claudeAuthPoll) { clearInterval(_claudeAuthPoll); _claudeAuthPoll = null }
}

async function _claudeAuthTick() {
  let s
  try {
    const res = await fetch('/api/accounts/claude')
    s = await res.json()
  } catch { return }
  _claudeAuthRenderList(s.accounts)

  // KET cim tartozik ugyanahhoz a bejelentkezeshez, es nem mindegy, melyiket
  // adjuk oda -- ugyanaz a minta, mint a wizClaude dobozon (lasd ott a bovebb
  // magyarazatot). A `browserUrl` a gep sajat kapujara ter vissza es magatol
  // befejezodik; `url` egy oldalra visz, ami kodot ir ki, amit kezzel kell
  // visszahozni. Ez a doboz eddig CSAK a masodikat mutatta -- a HTML/CSS/i18n
  // mar keszen allt az elsohoz, csak ide nem volt bekotve (Boss, 2026-08-29:
  // "old meg automatikusan").
  const autoUrl = s.browserUrl || null
  const autoWrap = document.getElementById('claudeAuthAutoWrap')
  const autoLink = document.getElementById('claudeAuthAutoLink')
  if (autoWrap && autoLink) {
    if (autoUrl) { autoLink.href = autoUrl; autoWrap.hidden = false }
    else { autoWrap.hidden = true }
  }
  if (autoUrl && _claudeAuthPendingTab) {
    // Megjott a cim -> a kattintaskor nyitott ures ful MOST megy oda. Igy a
    // felhasznalonak egyetlen kattintas az egesz, es a bejelentkezes a
    // localhost-kapun magatol fejezodik be (nincs masolando kod).
    try { _claudeAuthPendingTab.location.href = autoUrl } catch { /* a fulet bezarhattak */ }
    _claudeAuthPendingTab = null
  }
  if (s.url) _setConsentLink('claudeAuthLink', s.url)
  // A kodos resz csak akkor NYITOTT alapbol, ha nincs automata ut -- egyszer
  // dontunk rola folyamatonkent, hogy ne csukjuk vissza a user orra elott,
  // ha o maga nyitotta ki (masik gepen van).
  const manualBox = document.getElementById('claudeAuthManual')
  if (manualBox && !_claudeAuthManualDecided && (autoUrl || s.url)) {
    _claudeAuthManualDecided = true
    manualBox.open = !autoUrl
  }

  if (s.done) {
    _claudeAuthStopPoll()
    document.getElementById('claudeAuthFlow').hidden = true
    _setConsentLink('claudeAuthLink', '')
    document.getElementById('claudeAuthLabel').value = ''
    document.getElementById('claudeAuthEmail').value = ''
    _claudeAuthSetState('', null)
    // A visszavont bejelentkezes NEM siker: ilyenkor a "Hozzaadva" pont az
    // ellenkezojet allitana annak, ami tortent.
    const _driftBlocked = !!(s.identityDrift && s.identityDrift.reverted)
    if (s.error) showToast(s.error, 10000, true)
    // "Hozzaadva" is a false sentence after a repair: the account was already
    // in the list, it just had no credentials.
    else if (!_driftBlocked) showToast(t(s.reused ? 'claudeauth.done_back' : 'claudeauth.done', { label: s.label || '' }), 8000, true)
    _claudeAuthPendingTab = null
    // MAS FIOK JOTT BE, MINT AMIT IDE ROGZITETTUNK. A bongeszo azt a fiokot
    // hagyja jova, amelyik eppen be van benne jelentkezve -- ezt a
    // felhasznalonak latnia kell, mert kulonben ket elofizetes csendben egy
    // fiok kereteit eszi.
    if (s.identityDrift) {
      const d = s.identityDrift
      // Harom kulon mondat, mert harom kulon allapot: visszavontam / nem
      // sikerult visszavonni / regi valasz, amiben meg nincs is visszavonas.
      const key = d.reverted ? 'accounts.identity.drift_blocked'
        : (d.revertError ? 'accounts.identity.drift_block_failed' : 'accounts.identity.drift_after_login')
      showToast(t(key, { expected: d.expected, actual: d.actual, err: d.revertError || '' }), 25000, true)
    }
    // A sikeres bejelentkezes elavultta teszi a kartyak fiok-gyorsitotarat.
    // Enelkul a Beallitasok fulon tovabbra is "Bejelentkezes" allna egy mar
    // bejelentkezett fiokon.
    reloadAccountsAndRedraw()
    if (_claudeAuthOnDone) { const cb = _claudeAuthOnDone; _claudeAuthOnDone = null; cb(s) }
    return
  }
  if (!s.active) {
    _claudeAuthStopPoll()
    // A folyamat vege sikertelenul: a horog NEM sulhet el (kulonben egy meg
    // nem bejelentkezett ugynokot inditanank ujra), es az ures ful sem marad
    // felfuggesztve egy cimre, ami mar nem jon.
    _claudeAuthPendingTab = null
    _claudeAuthOnDone = null
    if (s.error) _claudeAuthSetState(s.error, 'bad')
    return
  }
  // A rogzitett cim MEG A KATTINTAS ELOTT: a bongeszo azt a fiokot hagyja
  // jova, amelyik eppen be van benne jelentkezve, es utana mar csak visszavonni
  // lehet. Olcsobb elore szolni, mint utana kijavitani.
  const _expectHint = s.expectedEmail ? ' ' + t('claudeauth.expect_hint', { email: s.expectedEmail }) : ''
  if (s.phase === 'starting') _claudeAuthSetState(t('claudeauth.state_starting') + _expectHint, null)
  else if (s.phase === 'awaiting-code') _claudeAuthSetState(t(autoUrl ? 'claudeauth.state_awaiting_auto' : 'claudeauth.state_awaiting') + _expectHint, null)
  else if (s.phase === 'working') _claudeAuthSetState(t('claudeauth.state_working'), null)
  else if (s.phase === 'failed') _claudeAuthSetState(s.error || t('claudeauth.state_failed'), 'bad')
}

async function renderClaudeAccountPanel(keyServices) {
  const panel = document.getElementById('claudeAccountPanel')
  if (!panel) return
  _claudeAuthKeyServices = keyServices || []
  _claudeAuthSyncServiceUi()
  // The key list is part of the one panel now, and it changes here rather than
  // when an account payload arrives -- so it is redrawn here too.
  _accHubRenderKeys()
  if (panel.dataset.wired === '1') { _claudeAuthTick(); return }
  panel.dataset.wired = '1'

  document.getElementById('claudeAuthStartBtn').addEventListener('click', async () => {
    const label = document.getElementById('claudeAuthLabel').value.trim()
    const email = document.getElementById('claudeAuthEmail').value.trim()
    if (!label) { showToast(t('claudeauth.need_label'), 6000, true); return }
    // UJ FIOK = SAJAT CIM, kotelezoen. Boss, 2026-08-30: "mindenfelekeppen ahhoz
    // az emailhez kell kotni, amivel regisztralni akar. nem egy meglevohoz!!!"
    // A cim nelkuli felvetel ugyanis a bongeszoben EPPEN bent levo fiokba
    // csuszik bele -- igy ult ket kulon nevu elofizetes egyetlen fiokon.
    if (!email) { showToast(t('claudeauth.need_email'), 8000, true); return }
    await _claudeAuthStartFlow({ label, email })
  })

  document.getElementById('claudeAuthService').addEventListener('change', _claudeAuthSyncServiceUi)

  // The page itself says where the OTHER accounts go, instead of that answer
  // living only in a chat message.
  document.getElementById('claudeAuthVaultLink')?.addEventListener('click', (e) => {
    e.preventDefault()
    switchPage('vault')
  })

  document.getElementById('claudeAuthKeySaveBtn').addEventListener('click', async () => {
    const host = document.getElementById('claudeAuthKeyMode')
    const input = document.getElementById('claudeAuthKeyValue')
    const value = input.value.trim()
    const id = host.dataset.vaultId
    if (!value || !id) return
    try {
      const res = await fetch('/api/vault', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, label: host.dataset.label || id, value }),
      })
      if (!res.ok) throw new Error('HTTP ' + res.status)
      input.value = ''
      showToast(t('claudeauth.key_saved', { label: host.dataset.label || id }), 6000, true)
      loadAccountsPage()
    } catch (err) { showToast(`${t('common.error_save')}: ${err.message}`) }
  })

  document.getElementById('claudeAuthCopyBtn').addEventListener('click', () => {
    const url = document.getElementById('claudeAuthLink').dataset.url
    if (!url) return
    navigator.clipboard?.writeText(url)
    showToast(t('claudeauth.copied'), 3000, true)
  })

  document.getElementById('claudeAuthCodeBtn').addEventListener('click', async () => {
    const input = document.getElementById('claudeAuthCode')
    const code = input.value.trim()
    if (!code) return
    _claudeAuthSetState(t('claudeauth.state_working'), null)
    try {
      const res = await fetch('/api/accounts/claude/login/code', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code }),
      })
      const data = await res.json()
      if (!data.ok) { _claudeAuthSetState(data.error || t('common.error_save'), 'bad'); return }
      input.value = ''
    } catch (err) { _claudeAuthSetState(String(err.message || err), 'bad') }
  })

  document.getElementById('claudeAuthCancelBtn').addEventListener('click', async () => {
    _claudeAuthStopPoll()
    try { await fetch('/api/accounts/claude/login/cancel', { method: 'POST' }) } catch { /* ignore */ }
    document.getElementById('claudeAuthFlow').hidden = true
    _claudeAuthSetState('', null)
    _claudeAuthTick()
  })

  _claudeAuthTick()
}

// --- Connections: Google accounts + Claude Code connectors -------------------
//
// Boss, 2026-08-14, on being told to run `claude mcp login` in a terminal:
// "hogy fogja ezt megcsinalni egy user aki komuves? [...] ezt a marveen ban
// kellene megoldani". So both flows live here, on a page, with the terminal
// steps hidden behind two buttons.
//
// The two halves are NOT the same thing and the page must not pretend they are:
//
//   Google accounts -- Marveen's own logins. Genuinely many at once; ten
//     addresses can be live together, each keeping mail + Drive + calendar.
//     This is where "10 email, mind mukodjon" is answered.
//   Claude Code connectors -- per Claude ACCOUNT, and measured: a second Google
//     identity cannot be added under another name (the endpoint refuses dynamic
//     client registration). So this half is shown honestly, not as a second
//     place to add addresses.
//
// The connector one-liners are translated HERE rather than sent by the server:
// the backend should not be shipping a Hungarian sentence to an English
// dashboard (same rule as the default-account row above).
const CONNECTOR_WHAT = [
  { match: /google drive/i, key: 'conn.what.drive' },
  { match: /\bgmail\b/i, key: 'conn.what.gmail' },
  { match: /google calendar|naptar|naptár/i, key: 'conn.what.calendar' },
  { match: /canva/i, key: 'conn.what.canva' },
  { match: /github/i, key: 'conn.what.github' },
  { match: /notion/i, key: 'conn.what.notion' },
  { match: /slack/i, key: 'conn.what.slack' },
]

const CONNECTOR_LABELS = [
  { match: /google drive/i, label: 'Google Drive' },
  { match: /\bgmail\b/i, label: 'Gmail' },
  { match: /google calendar/i, label: 'Google Calendar' },
  { match: /canva/i, label: 'Canva' },
  { match: /github/i, label: 'GitHub' },
  { match: /notion/i, label: 'Notion' },
  { match: /slack/i, label: 'Slack' },
]

function _connLabel(name) {
  const hit = CONNECTOR_LABELS.find(c => c.match.test(name))
  if (hit) return hit.label
  const cleaned = String(name || '').replace(/^claude\.ai\s+/i, '').trim()
  if (cleaned.startsWith('plugin:')) return cleaned.split(':').pop() || cleaned
  return cleaned || name
}

function _connWhat(name) {
  const hit = CONNECTOR_WHAT.find(c => c.match.test(name))
  return hit ? t(hit.key) : ''
}

let _gconnPoll = null
let _mconnLoginPoll = null
let _mconnStatusPoll = null

function _connSetState(id, text, kind) {
  const el = document.getElementById(id)
  if (!el) return
  el.textContent = text || ''
  el.className = 'claude-auth-state' + (kind ? ' claude-auth-state-' + kind : '')
}

// --- Google half -------------------------------------------------------------

function _gconnRenderList(accounts, clientPresent) {
  // Kept up to date even when there is no list element to draw into: the start
  // helper reads it to decide whether a value is an EXISTING account id (reuse
  // that token slot) or a new name (let the server de-duplicate it).
  _gconnKnownIds = new Set((accounts || []).map(a => a.id))
  const warn = document.getElementById('gconnNoClient')
  if (warn) warn.hidden = clientPresent !== false
  // The rows themselves are drawn by the account cards -- see renderAccountsHub.
  _hubGoogle = accounts || []
  _hubSeen.google = true
  renderAccountsHub()
}

async function _gconnLoad(probe) {
  try {
    const res = await fetch('/api/connections/google' + (probe ? '?probe=1&force=1' : ''))
    if (!res.ok) return
    const d = await res.json()
    _gconnApplyProjectId(d.projectId)
    _gconnRenderList(d.accounts, d.clientPresent)
    if (!probe) _gconnAutoProbe(d.accounts)
  } catch { /* the page keeps what it had */ }
}

let _gconnProbing = false

/**
 * Check, by ourselves, the accounts nobody has checked yet.
 *
 * Boss: "tehat emailt drivot fotokat stb lassuk egyszerre!" -- a list of ten
 * names, each saying "not checked yet" until the operator clicks Check ten
 * times, is not that. So the page does the clicking.
 *
 * One at a time and never forced: each probe is a process plus three Google
 * calls on the server, the answers are cached there for five minutes, and the
 * row is re-drawn after every one, so the list fills in visibly instead of
 * arriving in one late lump.
 */
async function _gconnAutoProbe(accounts) {
  if (_gconnProbing) return
  const pending = (accounts || []).filter(a => a && a.checkedAt === null).map(a => a.id)
  if (!pending.length) return
  _gconnProbing = true
  try {
    for (const id of pending) {
      // Gone from the DOM (page swapped, section re-rendered) -- stop rather
      // than keep spawning probes for a list nobody is looking at.
      if (!document.getElementById('accountsHubList')) return
      let res
      try {
        res = await fetch('/api/connections/google/probe', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id, force: false }),
        })
      } catch { return }  // network down: stop, do not hammer it
      // A dropped session would otherwise mean ten 401s in a row for nothing.
      if (res.status === 401 || res.status === 403) return
      if (!res.ok) continue  // one bad account must not stop the other nine
      // Re-read the whole list rather than patching one row: it is a cache hit
      // on the server now, and it keeps one source of truth for what is drawn.
      try {
        const r = await fetch('/api/connections/google')
        if (!r.ok) continue
        const d = await r.json()
        _gconnRenderList(d.accounts, d.clientPresent)
      } catch { return }
    }
  } finally {
    _gconnProbing = false
  }
}

function _gconnStopPoll() {
  if (_gconnPoll) { clearInterval(_gconnPoll); _gconnPoll = null }
}

// --- when GOOGLE is the one saying no ----------------------------------------
//
// Boss, 2026-08-14: "probaltam goggle fiokot hozzaadni de nem engedte a google
// [...] Hiba (403): access_denied [...] szoval ezen a folyamaton is vezesd
// vegig a usert hulyebiztosan!"
//
// The OAuth app is in "Testing" status, so Google admits only the addresses on
// its test-user list. Nothing on this machine can fix it and retrying never
// will -- the operator has to add the address in the Cloud Console. All this
// code does is notice, open the walkthrough, and put the right link and the
// right address in front of them.

/** Whatever was last typed into the name box -- what "try again" re-runs. */
let _gconnLastName = ''
/** The Cloud Console project, so the link lands in the right project. */
let _gconnProjectId = null
/** Ids of the accounts already on file -- see _gconnRenderList. */
let _gconnKnownIds = new Set()

/**
 * "You signed in as somebody else, so it became its own account."
 *
 * Silence here would be the dangerous answer: the operator pressed "sign in
 * again" on `munka`, picked a different address in the Google chooser, and
 * would otherwise see a second row appear with no explanation -- while
 * believing `munka` had been repaired.
 */
function _gconnNoteSavedAs(savedAs) {
  if (!savedAs) return
  showToast(t('gconn.saved_as_other', { id: savedAs }), 12000, true)
}

function _gconnApplyProjectId(projectId) {
  if (projectId) _gconnProjectId = projectId
  const link = document.getElementById('gconnConsoleLink')
  if (!link) return
  link.href = _gconnProjectId
    ? 'https://console.cloud.google.com/auth/audience?project=' + encodeURIComponent(_gconnProjectId)
    : 'https://console.cloud.google.com/auth/audience'
}

/**
 * Open the walkthrough, and name the address if we know it.
 *
 * Naming it matters more than it looks: step 4 is "type the address you want to
 * connect", and the operator who is three browser tabs deep has to be told
 * WHICH one, exactly, character for character.
 */
function _gconnOpenBlocked(address) {
  const box = document.getElementById('gconnBlocked')
  if (!box) return
  _gconnApplyProjectId(null)
  const guess = address || (_gconnLastName.includes('@') ? _gconnLastName : '')
  const row = document.getElementById('gconnBlockedAddrRow')
  const slot = document.getElementById('gconnBlockedAddr')
  if (row && slot) {
    slot.textContent = guess
    row.hidden = !guess
  }
  box.hidden = false
  box.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
}

async function _gconnStartAuth(name, force) {
  if (!name) { showToast(t('gconn.need_name'), 6000, true); return }
  const forced = force === true
  _gconnLastName = name
  // An existing account goes back as `id`, which skips the server-side
  // de-duplication. Otherwise "try again" on an account whose token expired
  // would quietly authorize `munka_2` and leave the broken `munka` behind.
  const body = _gconnKnownIds.has(name) ? { id: name } : { name }
  if (forced) body.force = true
  const flowBox = document.getElementById('gconnFlow')
  // Ugyanaz, mint a Fotok oldalon: a regi link torlese MEGELOZI a doboz
  // megjeleniteset, kulonben egy korabbi folyamat linkjere lehetne kattintani.
  _setConsentLink('gconnLink', '')
  if (flowBox) flowBox.hidden = false
  _connSetState('gconnState', t('gconn.state_starting'), null)
  try {
    const res = await fetch('/api/connections/google/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })
    const data = await res.json()
    if (!data.ok) {
      // Ugyanaz a megnevezett kiut, mint a Fotok oldalon -- ket helyen jelenhet
      // meg a "mar fut egy masik", es egyik helyen sem lehet zsakutca.
      if (data.code === 'busy' && !forced) {
        if (flowBox) flowBox.hidden = true
        _connSetState('gconnState', '', null)
        const who = data.busyAccountId || '?'
        if (confirm(t('photos.consent_busy', { who, me: name }))) return _gconnStartAuth(name, true)
        return
      }
      _connSetState('gconnState', data.error || t('common.error_save'), 'bad'); return
    }
  } catch (err) { _connSetState('gconnState', String(err.message || err), 'bad'); return }
  _gconnStopPoll()
  _gconnPoll = setInterval(_gconnTick, 2000)
  _gconnTick()
}

async function _gconnTick() {
  let s
  try {
    const res = await fetch('/api/connections/google/login')
    s = await res.json()
  } catch { return }
  _gconnApplyProjectId(s.projectId)
  // Survives a page reload mid-flow: the server knows which account is being
  // authorized, and "try again" needs that name after the operator has spent
  // ten minutes in the Google console and come back to a fresh page.
  if (s.accountId && !_gconnLastName) _gconnLastName = s.accountId
  _gconnRenderList(s.accounts, s.clientPresent)

  if (s.url) _setConsentLink('gconnLink', s.url)

  if (s.phase === 'done') {
    _gconnStopPoll()
    // Guarded: this fires from an interval, and by then the operator may have
    // switched pages or the panel may have been re-rendered under it.
    const flowBox = document.getElementById('gconnFlow')
    if (flowBox) flowBox.hidden = true
    const nameInput = document.getElementById('gconnName')
    if (nameInput) nameInput.value = ''
    _connSetState('gconnState', '', null)
    showToast(t('gconn.state_done', { id: s.accountId || '' }), 8000, true)
    _gconnNoteSavedAs(s.savedAs)
    // A new address changes what the Overview should be saying.
    renderOverviewConnections()
    // And it arrives unchecked: check it now, so the operator sees the address
    // and its three services instead of "not checked yet" on the row they just
    // spent two minutes authorizing.
    _gconnAutoProbe(s.accounts)
    return
  }
  if (s.phase === 'failed') {
    _gconnStopPoll()
    // A refusal by Google is not "didn't work" -- it has one specific cause and
    // one specific fix, and saying anything vaguer leaves the operator retrying
    // a thing that cannot succeed.
    if (s.blocked === 'test-user') {
      _connSetState('gconnState', t('gconn.blocked_state'), 'bad')
      _gconnOpenBlocked(null)
      return
    }
    _connSetState('gconnState', t('gconn.state_failed', { msg: s.error || '' }), 'bad')
    return
  }
  if (!s.active) { _gconnStopPoll(); return }
  if (s.phase === 'consent') _connSetState('gconnState', t('gconn.state_consent'), null)
  else _connSetState('gconnState', t('gconn.state_starting'), null)
}

// --- Claude Code connector half ----------------------------------------------

function _mconnRenderStatus(d) {
  // "Checking" is said out loud: one probe health-checks every connector on
  // every account (measured 8-20s each), and an empty matrix during that time
  // would read as "nothing is connected", which is the opposite of the truth.
  _connSetState('mconnState',
    d.refreshing ? t('mconn.checking')
      : d.checkedAt ? t('mconn.checked_ago', { ago: formatRelative(d.checkedAt) })
        : t('mconn.never'),
    null)

  // The connectors are drawn on the account card they belong to -- a connector
  // is not a thing of its own, it is something ONE Claude account has.
  _hubMcp = d.accounts || []
  _hubSeen.mcp = true
  renderAccountsHub()
}

function _mconnStopStatusPoll() {
  if (_mconnStatusPoll) { clearInterval(_mconnStatusPoll); _mconnStatusPoll = null }
}

async function _mconnLoadStatus(force) {
  let d
  try {
    const res = await fetch('/api/connections/mcp' + (force ? '?force=1' : ''))
    if (!res.ok) return
    d = await res.json()
  } catch { return }
  _mconnRenderStatus(d)
  // Poll only while a refresh is actually running, and stop the moment it is
  // not: a status page that keeps hitting the server forever is how a "check"
  // button turns into a background job nobody asked for.
  if (d.refreshing && !_mconnStatusPoll) {
    _mconnStatusPoll = setInterval(() => {
      if (document.hidden) return
      _mconnLoadStatus(false)
    }, 3000)
  } else if (!d.refreshing) {
    _mconnStopStatusPoll()
  }
}

function _mconnStopLoginPoll() {
  if (_mconnLoginPoll) { clearInterval(_mconnLoginPoll); _mconnLoginPoll = null }
}

async function _mconnLoginTick() {
  let s
  try {
    const res = await fetch('/api/connections/mcp/login')
    s = await res.json()
  } catch { return }

  if (s.url) _setConsentLink('mconnLink', s.url)
  const pasteRow = document.getElementById('mconnPasteRow')
  if (pasteRow) pasteRow.hidden = s.phase !== 'awaiting-paste'

  if (s.phase === 'failed') {
    _mconnStopLoginPoll()
    _connSetState('mconnFlowState', t('mconn.state_failed', { msg: s.error || '' }), 'bad')
    return
  }
  if (s.phase === 'awaiting-paste') { _connSetState('mconnFlowState', t('mconn.state_paste'), null); return }
  if (s.phase === 'visit') { _connSetState('mconnFlowState', t('mconn.state_visit'), null); return }
  if (s.phase === 'done') {
    // The CLI has exited; nothing on that pane will change again. Stop asking
    // -- every poll is two tmux calls on the server, and the operator can take
    // as long as they like over the browser half.
    _mconnStopLoginPoll()
    _connSetState('mconnFlowState', t('mconn.state_visit'), null)
    return
  }
  _connSetState('mconnFlowState', t('mconn.state_starting'), null)
}

// The one sentence this whole flow stands or falls on. The CLI says it plainly:
// the connector becomes available "the next time you start Claude Code". Without
// this, the operator authorizes, sees no change, and concludes it failed.
async function _mconnFinish() {
  let agents = []
  try {
    const res = await fetch('/api/connections/mcp/login')
    const s = await res.json()
    agents = s.restartAgents || []
  } catch { /* the hint degrades, the flow does not */ }
  _mconnStopLoginPoll()
  try { await fetch('/api/connections/mcp/login/finish', { method: 'POST' }) } catch { /* ignore */ }
  document.getElementById('mconnFlow').hidden = true
  _setConsentLink('mconnLink', '')
  _connSetState('mconnFlowState', '', null)
  showToast(agents.length ? t('mconn.restart_hint', { agents: agents.join(', ') }) : t('mconn.restart_hint_none'), 14000, true)
  _mconnLoadStatus(true)
  renderOverviewConnections()
}

// --- wiring ------------------------------------------------------------------

function renderConnectionsPanel() {
  const gsec = document.getElementById('googleConnSection')
  const msec = document.getElementById('mcpConnSection')
  if (!gsec || !msec) return

  if (gsec.dataset.wired !== '1') {
    gsec.dataset.wired = '1'

    document.getElementById('gconnAddBtn').addEventListener('click', () => {
      _gconnStartAuth(document.getElementById('gconnName').value.trim())
    })

    // The walkthrough is reachable at ANY time, not only after a refusal: the
    // operator who was just told "Access blocked" by Google is looking at a
    // Google error page, not at this one, and comes back here to find out what
    // happened. A button they can see beats a message they missed.
    document.getElementById('gconnBlockedToggle').addEventListener('click', () => {
      const box = document.getElementById('gconnBlocked')
      if (box.hidden) _gconnOpenBlocked(null)
      else box.hidden = true
    })

    document.getElementById('gconnBlockedClose').addEventListener('click', () => {
      document.getElementById('gconnBlocked').hidden = true
    })

    document.getElementById('gconnConsoleCopyBtn').addEventListener('click', () => {
      const url = document.getElementById('gconnConsoleLink').href
      if (!url) return
      navigator.clipboard?.writeText(url)
      showToast(t('gconn.copied'), 3000, true)
    })

    // "I added it, try again": start the SAME account over. Not a resume --
    // the old consent link is bound to a request Google already refused, so
    // re-opening it would refuse it again.
    document.getElementById('gconnRetryBtn').addEventListener('click', async () => {
      const name = _gconnLastName || document.getElementById('gconnName').value.trim()
      if (!name) { showToast(t('gconn.need_name'), 6000, true); return }
      document.getElementById('gconnBlocked').hidden = true
      // A flow left open by the refusal would make the new one refuse to start
      // ("one authorization at a time"), which reads as the retry not working.
      _gconnStopPoll()
      try { await fetch('/api/connections/google/login/cancel', { method: 'POST' }) } catch { /* ignore */ }
      _gconnStartAuth(name)
    })

    document.getElementById('gconnCopyBtn').addEventListener('click', () => {
      const url = document.getElementById('gconnLink').dataset.url
      if (!url) return
      navigator.clipboard?.writeText(url)
      showToast(t('gconn.copied'), 3000, true)
    })

    document.getElementById('gconnPasteBtn').addEventListener('click', async () => {
      const input = document.getElementById('gconnPaste')
      const value = input.value.trim()
      if (!value) return
      try {
        const res = await fetch('/api/connections/google/login/paste', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ value }),
        })
        const data = await res.json()
        if (!data.ok) {
          _connSetState('gconnState', data.error || t('common.error_save'), 'bad')
          // The operator pasted the Google error page instead of a redirect
          // link -- which is exactly what step 3 told them to do. Answer the
          // question they actually have.
          if (data.blocked === 'test-user') _gconnOpenBlocked(null)
          return
        }
        input.value = ''
        _gconnNoteSavedAs(data.savedAs)
      } catch (err) { _connSetState('gconnState', String(err.message || err), 'bad') }
    })

    document.getElementById('gconnCancelBtn').addEventListener('click', async () => {
      _gconnStopPoll()
      try { await fetch('/api/connections/google/login/cancel', { method: 'POST' }) } catch { /* ignore */ }
      document.getElementById('gconnFlow').hidden = true
      _connSetState('gconnState', '', null)
      _gconnLoad(false)
    })

    // Delegated: the rows are re-rendered on every poll, and re-binding ten
    // accounts' worth of buttons each time is how listeners pile up. The root
    // is the card list, because that is where the buttons live now -- the two
    // halves of this panel share it, each filtering for its own attribute.
    document.getElementById('accountsHubList').addEventListener('click', async (e) => {
      const btn = e.target.closest('[data-gact]')
      if (!btn) return
      const id = btn.dataset.id
      const act = btn.dataset.gact
      if (act === 'probe') {
        btn.disabled = true
        btn.textContent = t('gconn.checking')
        try {
          await fetch('/api/connections/google/probe', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id }),
          })
        } catch { /* ignore */ }
        _gconnLoad(false)
        renderOverviewConnections()
        return
      }
      // Sign this address in again, into the SAME slot. `id` (not `name`) makes
      // the server reuse the exact key instead of deriving a new one, so a
      // re-authorized account replaces its own token rather than appearing
      // twice as "munka" and "munka_2".
      if (act === 'reauth') {
        // Only one authorization can run at a time; drop a stale one rather
        // than answering "one is already running" to a button the operator
        // just pressed.
        _gconnStopPoll()
        try { await fetch('/api/connections/google/login/cancel', { method: 'POST' }) } catch { /* ignore */ }
        _gconnKnownIds.add(id)
        await _gconnStartAuth(id)
        return
      }
      if (act === 'default') {
        try {
          await fetch('/api/connections/google/default', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id }),
          })
        } catch { /* ignore */ }
        _gconnLoad(false)
        return
      }
      if (act === 'remove') {
        // Losing an address by a misclick is not recoverable from here -- the
        // consent has to be granted again in a browser.
        if (!confirm(t('gconn.remove_confirm', { id }))) return
        try {
          const res = await fetch('/api/connections/google/remove', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id }),
          })
          const data = await res.json()
          if (!data.ok) { showToast(data.error || t('common.error_delete'), 8000, true); return }
          showToast(t('gconn.removed', { id }), 6000, true)
        } catch (err) { showToast(`${t('common.error_delete')}: ${err.message}`); return }
        _gconnLoad(false)
        renderOverviewConnections()
      }
    })
  }

  if (msec.dataset.wired !== '1') {
    msec.dataset.wired = '1'

    document.getElementById('mconnRefreshBtn').addEventListener('click', async () => {
      _connSetState('mconnState', t('mconn.checking'), null)
      try { await fetch('/api/connections/mcp/refresh', { method: 'POST' }) } catch { /* ignore */ }
      _mconnLoadStatus(false)
    })

    document.getElementById('mconnCopyBtn').addEventListener('click', () => {
      const url = document.getElementById('mconnLink').dataset.url
      if (!url) return
      navigator.clipboard?.writeText(url)
      showToast(t('gconn.copied'), 3000, true)
    })

    document.getElementById('mconnDoneBtn').addEventListener('click', _mconnFinish)

    document.getElementById('mconnPasteBtn').addEventListener('click', async () => {
      const input = document.getElementById('mconnPaste')
      const value = input.value.trim()
      if (!value) return
      try {
        const res = await fetch('/api/connections/mcp/login/paste', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ value }),
        })
        const data = await res.json()
        if (!data.ok) { _connSetState('mconnFlowState', data.error || t('common.error_save'), 'bad'); return }
        input.value = ''
      } catch (err) { _connSetState('mconnFlowState', String(err.message || err), 'bad') }
    })

    document.getElementById('mconnCancelBtn').addEventListener('click', async () => {
      _mconnStopLoginPoll()
      try { await fetch('/api/connections/mcp/login/finish', { method: 'POST' }) } catch { /* ignore */ }
      document.getElementById('mconnFlow').hidden = true
      _setConsentLink('mconnLink', '')
      _connSetState('mconnFlowState', '', null)
    })

    document.getElementById('accountsHubList').addEventListener('click', async (e) => {
      const btn = e.target.closest('[data-mact="login"]')
      if (!btn) return
      const accountId = btn.dataset.account || null
      const server = btn.dataset.server
      const flow = document.getElementById('mconnFlow')
      document.getElementById('mconnFlowTitle').textContent = t('mconn.flow_title', {
        connector: _connLabel(server),
        account: btn.closest('.conn-account')?.querySelector('.conn-account-name')?.textContent || '',
      })
      document.getElementById('mconnPasteRow').hidden = true
      // Az elozo csatlakoztatas linkje nem maradhat kattinthatoan a dobozban.
      _setConsentLink('mconnLink', '')
      flow.hidden = false
      _connSetState('mconnFlowState', t('mconn.state_starting'), null)
      try {
        const res = await fetch('/api/connections/mcp/login', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ accountId, server }),
        })
        const data = await res.json()
        if (!data.ok) { _connSetState('mconnFlowState', data.error || t('common.error_save'), 'bad'); return }
      } catch (err) { _connSetState('mconnFlowState', String(err.message || err), 'bad'); return }
      _mconnStopLoginPoll()
      _mconnLoginPoll = setInterval(_mconnLoginTick, 2000)
      _mconnLoginTick()
    })
  }

  _gconnLoad(false)
  _mconnLoadStatus(false)
}

// A vegigvezeto allapota. SZANDEKOSAN a rajzolo fuggveny ELOTT all: `let`
// eseten a deklaracio elotti hasznalat nem undefined, hanem kivetel (TDZ), es
// az Attekintes rajzolasa barmikor elindulhat -- egy kesobbi `let` egy
// korabban futo rajzolasnal az egesz kartyat kiloné.
let _selfCheckProjectId = null
let _selfCheckGuideTarget = null
let _selfCheckGuideTab = 'quick'

// The Overview self-check. Connections BREAK on their own (a Google token
// expires, a connector was never authorized on this machine), which is why this
// is a card of its own rather than a line in the install wizard -- the wizard is
// about one-off setup and goes quiet once done.
//
// Boss, 2026-08-19: "csinald ugy hogy allandoan megjelenjen az attekintes
// menupont alatt. ne tunjon el. ha nincs semmi baj akkor azt is irja ki."
// So the card NEVER hides. A card that vanishes when healthy is unreadable in
// the only way that matters: you cannot tell "everything is fine" from "the
// check is broken" or "the check never ran", and the operator is left guessing
// at a blank spot. It now has a green state, and even the unreachable case is
// stated instead of hidden. Click-through lands on the page that can fix it.
// Az "Egyebb" doboz ki-be nyitasa. Kulon fuggveny, mert a doboz HTML-je
// ujrarajzolodik minden onellenorzesnel, es egy onclick-attributum tullep
// minden ujrarajzolast -- egy addEventListener nem.
//
// A kartya MEREVEN ket soros. Boss, 2026-08-22: "csak kizarolag 2 sor lehet.
// nem megyunk ezekel a sok zold csikokkal a lap aljara" es "ezeket tedd az
// egyebbe. ennyi". Ez a fuggveny a kapu: barhany sort ad at a hivo, legfeljebb
// `max` doboz keletkezik, mert a maradek EGY doboz leirasaba kerul.
function selfCheckBoxes(rows, max) {
  if (rows.length <= max) return { shown: rows, extra: [] }
  // A utolso hely az "Egyeb" doboze -- ezert `max - 1` fer ki teljes sorral.
  return { shown: rows.slice(0, max - 1), extra: rows.slice(max - 1) }
}

async function renderOverviewConnections() {
  const box = document.getElementById('overviewConnections')
  const list = document.getElementById('overviewConnectionsList')
  if (!box || !list) return

  // Tones. Amber = something is out; grey = worth knowing; green = checked and
  // fine. Same scale as the setup card on purpose: two cards on one screen
  // shouting in two colour languages is how colour stops meaning anything.
  const TONES = {
    recommended: { bg: '#f59e0b', fg: '#111', descFg: 'rgba(0,0,0,.75)', itemBg: 'rgba(255,255,255,.45)', border: 'none' },
    extra: { bg: 'var(--card-bg, rgba(127,127,127,.10))', fg: 'var(--text)', descFg: 'var(--text-muted)', itemBg: 'rgba(127,127,127,.12)', border: '1px solid var(--border)' },
    ok: { bg: 'var(--card-bg, rgba(127,127,127,.10))', fg: 'var(--text)', descFg: 'var(--text-muted)', itemBg: 'rgba(34,197,94,.14)', border: '1px solid rgba(34,197,94,.45)' },
  }

  // A kartya legfeljebb KET soros lehet, ket oszloppal: negy doboz. Boss,
  // 2026-08-21: "az onellenorzes zold gombjai maximum ketto sorban lehetnek!
  // nem 3! [...] osszesen max 4 ilyen zold kis dobozka lehet. a 4. az legyen az
  // egyebb. es abba bele lehet tenni minden mast. igy nem lesz soha 5 dik!"
  //
  // Elsore ez a negyedik doboz KINYILT a racs alatt -- es ezzel pont az
  // tortent, ami ellen a szabaly szol: mentek a csikok a lap aljara. Boss,
  // 2026-08-22: "ezeket tedd az egyebbe. ennyi". A maradek tehat nem lenyilik,
  // hanem BELEKERUL az "Egyeb" doboz sajat leirasaba, felsorolva: nem tunik
  // el, de a kartya sem tud lefele nyulni. Igy a magassag nem a checkek
  // szamatol fugg -- barmennyi lehet belolluk.
  const MAX_ITEMS = 4

  const itemHtml = (r, tone) => `<a href="#" class="overview-capability-item"
        style="background:${tone.itemBg};color:${tone.fg}"
        ${r.onclick
          ? `onclick="${r.onclick};return false"`
          : r.guide
            ? `onclick="openSelfCheckGuide(${JSON.stringify(r.guide).replace(/"/g, '&quot;')});return false"`
            : 'onclick="switchPage(\'accounts\');return false"'}>
        <div class="overview-capability-label">${escapeHtml(r.label)}</div>
        <div class="overview-capability-desc" style="color:${tone.descFg}">${escapeHtml(r.desc)}</div>
      </a>`

  const paint = (tone, rows) => {
    box.hidden = false
    box.style.background = tone.bg
    box.style.border = tone.border
    const titleEl = box.querySelector('.overview-capabilities-title')
    if (titleEl) titleEl.style.color = tone.fg
    // A lejarat-sorok NEM a Fiokok oldalra dobjak a felhasznalot, hanem
    // megnyitjak a vegigvezetot (Boss, 2026-08-19: "megnyom egy gombot es
    // vegigvezeti ezen a folyamaton a usert"). Az odadobas ugyanis pont a
    // nehez reszt hagyja ra: ott all az oldalon, es nem tudja, mit nyomjon.
    const { shown, extra } = selfCheckBoxes(rows, MAX_ITEMS)
    // A sorrend nem veletlen: a hivo a legfontosabbat teszi elore, tehat az
    // "Egyeb"-be mindig a lista kevesbe surgos vege kerul.
    //
    // A felsorolashoz a cimke ELEJE kell: a pipa es a gondolatjel utani
    // reszletezes ("... -- 9 tarolo, 0 napja futott") egy dobozba mar nem fer,
    // a lenyeg viszont igen. Ha nincs gondolatjel, marad a teljes cimke.
    const rovid = (r) => String(r.label).replace('\u2705 ', '').split(' \u2014 ')[0]
    const moreBox = extra.length
      ? itemHtml({
        label: t('conn.ov_more', { n: extra.length }),
        desc: extra.map(rovid).join(' \u00b7 '),
        onclick: extra[0].onclick || null,
        guide: extra[0].guide || null,
      }, tone)
      : ''
    list.innerHTML = shown.map(r => itemHtml(r, tone)).join('') + moreBox
  }

  let d
  try {
    const res = await fetch('/api/connections/summary')
    if (!res.ok) throw new Error('fetch failed')
    d = await res.json()
  } catch {
    // Say it. A silent card here would read exactly like a healthy one.
    paint(TONES.extra, [{ label: t('conn.ov_unreachable'), desc: t('conn.ov_unreachable_action') }])
    return
  }

  // An older dashboard build behind a newer page (or the other way round) must
  // not throw here: the Overview is the first thing the operator sees.
  if (!d || !d.google || !d.mcp) {
    paint(TONES.extra, [{ label: t('conn.ov_unreachable'), desc: t('conn.ov_unreachable_action') }])
    return
  }

  // A vegigvezeto ebbol tudja, melyik Cloud Console projektre linkeljen.
  _selfCheckProjectId = d.projectId || null

  const rows = []
  const act = t('conn.ov_action')
  const health = (d.health && Array.isArray(d.health.items)) ? d.health.items : []
  // Ha az ELO meres mar kimondta, hogy nem el a hozzaferes, akkor a
  // "hibas fiokok" sor ugyanazt allitana -- csak rosszabbul: nem nevezi meg a
  // fiokokat, es a Fiokok oldalra dob a vegigvezeto helyett. Ket sor egy
  // tenyrol egy dobozt venne el a negybol.
  const eloRossz = health.some(h => h.id === 'google_live_bad')
  if (d.google.broken > 0 && !eloRossz) rows.push({ label: t('conn.ov_google_broken', { n: d.google.broken }), desc: act })
  if (d.mcp.needsLogin > 0) rows.push({ label: t('conn.ov_mcp_login', { n: d.mcp.needsLogin }), desc: act })
  if (d.google.total === 0 && d.google.clientPresent) rows.push({ label: t('conn.ov_google_none'), desc: act })
  if (d.mcp.broken > 0) rows.push({ label: t('conn.ov_mcp_broken', { n: d.mcp.broken }), desc: act })

  // The clock. Each expiring credential gets its OWN line with its own name:
  // with ten addresses connected, "egy fiók lejárt" is not something you can
  // act on. The description is the instruction, not a restatement.
  const exp = (d.expiry && Array.isArray(d.expiry.items)) ? d.expiry.items : []
  for (const item of exp) {
    if (item.status === 'expired') {
      rows.push({
        label: t('conn.ov_expired', { name: item.label, d: Math.abs(item.daysLeft) }),
        desc: t('conn.ov_expired_action'),
        guide: { id: item.id, label: item.label, status: item.status },
      })
    } else if (item.status === 'soon') {
      rows.push({
        label: t('conn.ov_expires_soon', { name: item.label, d: Math.max(0, item.daysLeft) }),
        desc: t('conn.ov_expired_action'),
        guide: { id: item.id, label: item.label, status: item.status },
      })
    }
  }

  // Ami se nem probalhato, se nem oran jar, csak elrohad: a mentes tartalma, a
  // naplokba szivargo titok, a fogyo lemez. Az `ok` sorokat itt NEM irjuk ki
  // kulon -- a zold osszefoglalo mondja el oket egyben, kulonben a kartya
  // hosszu lenne akkor is, amikor semmi teendo nincs.
  for (const h of health) {
    if (h.status === 'ok') continue
    // A "nem el a Google-hozzaferes" sor MEGNEVEZI a fiokokat -- azokat kell
    // egyesevel ujracsatlakoztatni, es a vegigvezeto ezt HELYBEN elvegzi.
    // Boss, 2026-08-22: "es ha most ez problema akkor az onnellenorzes
    // szoljon es vezessen vegig a folyamaton hogy mit kell csinalni. linkek
    // kel. [...] csak vezesse vegig a komuvesunket a folyamaton.
    // hulyebiztosan!"
    const glNames = String((h.params && h.params.names) || '')
    rows.push({
      label: t('health.' + h.id, h.params || {}),
      desc: t('health.' + h.id + '_action'),
      // A bejelentkezes sora nem a Fiokok oldalra dob, hanem oda, ahol
      // ELVEGEZHETO: a varazslo bejelentkezteto lepesere. Ugyanez all a
      // "meg sosem futott / megallt" sorra: az nem teendo, hanem egy gomb --
      // itt helyben lefuttatjuk a merest.
      onclick: h.id.startsWith('claude_auth_')
        ? 'openClaudeLoginStep()'
        : (h.id === 'google_live_never' || h.id === 'google_live_stale')
          ? 'runGoogleLiveCheckNow()'
          // Az allo vegrehajto sora a KOD-HID lapra visz, mert ott all a
          // telepito parancs es a masolo gomb -- a Fiokok oldalan semmit nem
          // tudna kezdeni vele. Ugyanez all a VERZIO-sorokra (elavult / verzio
          // nelkuli / ismeretlen peldany): a teendo mindharomnal ugyanaz a
          // Kod-hid ablak. Enelkul ezek az alapertelmezett agra estek, es a
          // Fiokok oldalra dobtak a felhasznalot, ahol semmi dolga (Boss,
          // 2026-08-26: "miert a fiokokba visz amikor rakattintok?").
          : (h.id === 'code_bridge_dead' || h.id === 'code_bridge_never'
            || h.id === 'code_bridge_worker_stale' || h.id === 'code_bridge_worker_unversioned'
            || h.id === 'code_bridge_worker_unknown')
            ? "openCodeBridgeModal()"
            : null,
      guide: h.id === 'google_live_bad'
        ? {
          id: 'google:live',
          label: glNames,
          status: 'expired',
          live: true,
          accounts: glNames.split(',').map(x => x.trim()).filter(Boolean),
        }
        : null,
    })
    // Es ELORE. A kartya merev negy dobozos: tiz lejarat-sor melle szorulva
    // pont az a sor kerulne az "Egyeb"-be, amelyik a javitason vegigvezet --
    // holott ez tudja a legtobbet: az ora akkor is "rendben"-t mond, amikor a
    // Google mar mindent elutasit.
    if (h.id === 'google_live_bad') rows.unshift(rows.pop())
  }

  if (rows.length) {
    paint(TONES[d.tier] || TONES.extra, rows)
    return
  }

  // Nothing wrong -- and that gets SAID, with the numbers behind it, so the
  // green line is evidence rather than reassurance.
  const okCount = exp.filter(e => e.status === 'ok').length
  const greenRows = [{
    label: t('conn.ov_all_ok'),
    desc: okCount
      ? t('conn.ov_all_ok_detail', { n: okCount, d: Math.max(0, Math.min(...exp.map(e => e.daysLeft))) })
      : t('conn.ov_all_ok_plain'),
  }]
  // A Claude-bejelentkezes MINDIG kap sort, zolden is. Boss, 2026-08-20:
  // "ha az alatta levo zoldek egyike sem vonatkozik erre a hibara, akkor ez a
  // hiba miert nincs megjelenitve zolden hogy minden rendben ezzel is?" --
  // pontosan igy volt: a Beallitasok pirosan mondta hogy nincs bejelentkezes,
  // ez a kartya meg zolden hogy minden rendben, ugyanarrol a gepallapotrol.
  const cok = health.find(h => h.id === 'claude_auth_ok')
  if (cok) greenRows.push({ label: t('health.claude_auth_ok'), desc: t('health.claude_auth_ok_action') })
  // A mentes akkor is kap sort, ha rendben van: eppen az volt a baj, hogy
  // hetekig sikeresen futott, csak nem azt mentette, amit kellett volna --
  // egy nema "rendben" ott semmit nem arult volna el.
  const bok = health.find(h => h.id === 'backup_ok')
  if (bok) greenRows.push({ label: t('health.backup_ok', bok.params || {}), desc: t('health.backup_ok_action') })
  // Ugyanez all az upstream-meresre: eppen az volt a baj, hogy a szam
  // magabiztosan ott allt, kozben senki nem merte. A zold sor kimondja, hogy
  // MOST merte valaki, es mikor.
  const uok = health.find(h => h.id === 'upstream_ok')
  if (uok) greenRows.push({ label: t('health.upstream_ok', uok.params || {}), desc: t('health.upstream_ok_action') })
  // A napi git-lehuzas is kap zold sort. Ugyanaz a csapda: a repok a fan
  // akkor is ott vannak, ha hetek ota nem frissultek -- a "minden rendben"
  // magatol ertetodonek latszana, hiaba nem huzott le semmit senki.
  const dsok = health.find(h => h.id === 'drive_sync_ok')
  if (dsok) greenRows.push({ label: t('health.drive_sync_ok', dsok.params || {}), desc: t('health.drive_sync_ok_action') })
  const gok = health.find(h => h.id === 'git_pull_ok')
  if (gok) greenRows.push({ label: t('health.git_pull_ok', gok.params || {}), desc: t('health.git_pull_ok_action') })
  // Az elo Google-ellenorzes zold sora. Enelkul pontosan az az allapot allna
  // vissza, ami 2026-08-22-en egesz nap fennallt: tiz halott hozzaferes, es a
  // kartya zolden azt allitja, minden rendben. A zold sor kimondja, hogy
  // valaki TENYLEGESEN megkerdezte a Google-t, es mikor.
  const glok = health.find(h => h.id === 'google_live_ok')
  if (glok) greenRows.push({ label: t('health.google_live_ok', glok.params || {}), desc: t('health.google_live_ok_action') })
  // A kod-hid zold sora. Ugyanaz a csapda, mint a tobbinel: a hid "be van
  // kapcsolva" allapota semmit nem mond arrol, hogy a VEGREHAJTO el-e, es
  // pontosan ez a kulonbseg futott ki ket hetig eszrevetlenul.
  const cbok = health.find(h => h.id === 'code_bridge_ok')
  if (cbok) greenRows.push({ label: t('health.code_bridge_ok', cbok.params || {}), desc: t('health.code_bridge_ok_action'), onclick: "openCodeBridgeModal()" })
  paint(TONES.ok, greenRows)
}

// === "Mi valtozott az upstreamben?" ======================================
//
// Boss, 2026-08-19: "csak ezzel az a baj hogy ebbol nem latok semmit sem. azt
// kellene kiirnia hogy mit javitottak rajta!? erted? emberi nyelven. es hogy
// ezek kellenek e nekunk. [...] mert lesz biztos olyan amit nem akarok hogy
// bekeruljon."
//
// Ket dolgot kellett eldonteni. Az egyik: mi a lista EGYSEGE. Fajlt nem lehet
// kulon athuzni -- a valtozas egysege a commit, ezert a lista 112 tetelbol all,
// nem 169-bol (a 169 azoknak a fajloknak a szama, amiket ez a 112 commit
// utkozes nelkul erint). A masik: mi szerint van csoportositva. A javitasok
// kulon dobozban allnak, mert azokat a Boss szerint "valoszinu kellenek. mind",
// a fejlesztesek kulon, mert azok kozott lesz olyan, amit nem akar.
let upstreamChangesCache = null
// 'valtozas' = mit csinaltak (a commit az egyseg, 112 tetel)
// 'fajl'     = melyik fajl valtozott (191 tetel: 22 utkozo + 169 tiszta)
let upstreamChangesView = 'valtozas'

function upstreamChangeRow(c) {
  const meta = [
    c.date,
    c.scope ? `${c.type}(${c.scope})` : c.type,
    c.pr ? `#${c.pr}` : '',
    t('upstream.changes.files', { n: c.files.length }),
  ].filter(Boolean).join(' · ')
  const conflict = c.touchesConflict
    ? `<span class="upstream-change-conflict">${escapeHtml(t('upstream.changes.conflict'))}</span>`
    : ''
  // A magyar szoveg a fo mondat; az eredeti angol tárgysor alatta all kicsiben,
  // hogy a forditas ellenorizheto legyen, ne kelljen elhinni.
  const hu = c.hu ? escapeHtml(c.hu) : `<em>${escapeHtml(t('upstream.changes.nohu'))}</em>`
  return `
    <div class="upstream-change">
      <div class="upstream-change-text">${hu} ${conflict}</div>
      <div class="upstream-change-meta">${escapeHtml(meta)}</div>
      <div class="upstream-change-en" title="${escapeHtml(c.files.join('\n'))}">${escapeHtml(c.subject)}</div>
    </div>`
}

// A fajl-nezet egy sora. Boss, 2026-08-20: "hol vanak leirva mind a 169 tetel
// hogy azok mik?" -- itt all mind, a fajl felol nezve: mi a fajl, utkozik-e, es
// melyik valtozasok nyultak hozza (ugyanazzal a magyar mondattal, amit a masik
// nezet mutat, tehat a ketto nem mondhat mast).
function upstreamFileRow(f, huBySha) {
  // Sajat szoveg, nem a valtozas-nezete: ott a COMMIT 'utkozo fajlt erint', itt
  // viszont a fajl MAGA az utkozo. A kozos kulcstol '.gitignore utkozo fajlt
  // erint' lett volna -- ertelmetlen mondat a sajat nevere mutato fajl mellett.
  const conflict = f.conflict
    ? `<span class="upstream-change-conflict">${escapeHtml(t('upstream.files.conflict_badge'))}</span>`
    : ''
  const shas = f.shas || []
  // Nem sorolunk fel tizenot mondatot egy sokat piszkalt fajlnal: az elso
  // harom mutatja, mirol van szo, a tobbi szamkent all ott.
  const mondatok = shas.map(s => huBySha[s]).filter(Boolean)
  const shown = mondatok.slice(0, 3)
  const rest = mondatok.length - shown.length
  const lines = shown.map(hu => `<li>${escapeHtml(hu)}</li>`).join('')
  // Ures shas: a fajl csak osszefesulo commitban valtozott, azok nem sorolnak
  // fel fajlokat. Ezt kiirjuk, mert egy magyarazat nelkuli fajlnev pont az,
  // ami miatt az egesz lista keszult. A mondat viszont CSAK ekkor igaz: ha van
  // commitja, csak eppen nincs hozza magyar szoveg (a forditas kesobb keszul
  // el), akkor hallgatni kell rola -- hazudni nem.
  const inner = shas.length === 0
    ? `<div class="upstream-file-merge">${escapeHtml(t('upstream.files.merge_only'))}</div>`
    : lines
      ? `<ul class="upstream-file-changes">${lines}${rest > 0 ? `<li class="upstream-file-more">${escapeHtml(t('upstream.files.more', { n: rest }))}</li>` : ''}</ul>`
      : ''
  // Boss, 2026-08-23: "ossze kellene zarni! tul sok helyet foglalnak" -- a
  // fajlok a magyarazo mondataikkal egyutt kepernyonyi szalagga nyultak.
  // Osszecsukva a FAJLNEV marad kint (az kell a keresehez es a szemnek), a
  // mondatok kattintasra jonnek. Amelyik sornak nincs mit kibontania, az sima
  // div marad: ures nyil rosszabb a semminel -- ugy nezne ki, mintha lenne
  // mogotte valami, aztan nem nyilna ki.
  if (!inner) {
    return `
    <div class="upstream-file">
      <div class="upstream-file-path">${escapeHtml(f.path)} ${conflict}</div>
    </div>`
  }
  return `
    <details class="upstream-file">
      <summary class="upstream-file-path">${escapeHtml(f.path)} ${conflict}</summary>
      ${inner}
    </details>`
}

function renderUpstreamFiles(data, filter, body, intro) {
  const files = data.files || []
  if (!files.length) {
    body.innerHTML = `<p class="upstream-changes-empty">${escapeHtml(t('upstream.files.pending'))}</p>`
    if (intro) intro.textContent = ''
    return
  }
  // A csoportok kulcsait a szerver adja: ha egyszer uj kategoria kerul be, ez
  // magatol viszi. Bedrotozott listaval az uj kategoria commitjai csendben
  // kimaradnanak, es a fajljaik magyarazat nelkul allnanak.
  const huBySha = {}
  for (const kind of Object.keys(data.groups || {})) {
    for (const c of (data.groups[kind] || [])) huBySha[c.sha] = c.hu || c.subject
  }
  const q = (filter || '').trim().toLowerCase()
  const match = f => !q
    || f.path.toLowerCase().includes(q)
    || (f.shas || []).some(s => (huBySha[s] || '').toLowerCase().includes(q))
  const rows = files.filter(match)
  const utkozo = rows.filter(f => f.conflict)
  const tiszta = rows.filter(f => !f.conflict)
  let html = ''
  // Az UTKOZO doboz nyitva marad: az a nehany fajl, amivel dolgod van. A
  // TISZTA doboz alapbol csukva -- ott 150+ sor all, es epp az foglalta a fel
  // oldalt. A darabszam a cimsorban van, tehat csukva sem tunik ugy, mintha
  // nem lenne benne semmi. Keresesnel mindketto nyitva: a talalatot latni kell.
  const openAll = q ? ' open' : ''
  if (utkozo.length) {
    html += `<details class="upstream-box upstream-box-conflict" open>
      <summary><h4>${escapeHtml(t('upstream.files.conflicting', { n: utkozo.length }))}</h4></summary>
      ${utkozo.map(f => upstreamFileRow(f, huBySha)).join('')}</details>`
  }
  if (tiszta.length) {
    html += `<details class="upstream-box upstream-box-clean"${openAll}>
      <summary><h4>${escapeHtml(t('upstream.files.clean', { n: tiszta.length }))}</h4></summary>
      ${tiszta.map(f => upstreamFileRow(f, huBySha)).join('')}</details>`
  }
  body.innerHTML = html || `<p class="upstream-changes-empty">${escapeHtml(t('upstream.changes.nomatch'))}</p>`
  if (intro) {
    const fc = data.fileCounts || { total: files.length, conflict: 0, clean: files.length }
    intro.textContent = t('upstream.files.intro', { n: fc.total, u: fc.conflict, c: fc.clean })
  }
}

function renderUpstreamChanges(data, filter) {
  const body = document.getElementById('upstreamChangesBody')
  const intro = document.getElementById('upstreamChangesIntro')
  if (!body) return
  if (!data || !data.available) {
    body.innerHTML = `<p class="upstream-changes-empty">${escapeHtml(t('upstream.changes.none'))}</p>`
    if (intro) intro.textContent = ''
    return
  }
  if (upstreamChangesView === 'fajl') { renderUpstreamFiles(data, filter, body, intro); return }
  const q = (filter || '').trim().toLowerCase()
  const match = c => !q
    || (c.hu || '').toLowerCase().includes(q)
    || (c.subject || '').toLowerCase().includes(q)
    || (c.files || []).some(f => f.toLowerCase().includes(q))
  const boxes = [
    ['javitas', 'upstream.changes.fixes', 'upstream-box-fix'],
    ['fejlesztes', 'upstream.changes.feats', 'upstream-box-feat'],
    ['egyeb', 'upstream.changes.other', 'upstream-box-other'],
  ]
  let html = ''
  for (const [key, labelKey, cls] of boxes) {
    const items = (data.groups[key] || []).filter(match)
    if (!items.length) continue
    html += `
      <section class="upstream-box ${cls}">
        <h4>${escapeHtml(t(labelKey, { n: items.length }))}</h4>
        ${items.map(upstreamChangeRow).join('')}
      </section>`
  }
  body.innerHTML = html || `<p class="upstream-changes-empty">${escapeHtml(t('upstream.changes.nomatch'))}</p>`
  if (intro) {
    // Az egyseg itt is ki van mondva, mert pont ez volt a felreertes forrasa.
    intro.textContent = t('upstream.changes.intro', {
      n: data.total,
      f: data.counts.javitas,
      u: data.counts.fejlesztes,
      e: data.counts.egyeb,
      local: data.localRef || '?',
      upstream: data.upstreamRef || '?',
    })
  }
}

async function openUpstreamChanges() {
  const overlay = document.getElementById('upstreamChangesModal')
  if (!overlay) return
  overlay.hidden = false
  openModal(overlay)
  const body = document.getElementById('upstreamChangesBody')
  if (!upstreamChangesCache) {
    if (body) body.innerHTML = `<p class="upstream-changes-empty">${escapeHtml(t('upstream.changes.loading'))}</p>`
    try {
      const res = await fetch('/api/upstream/changes')
      upstreamChangesCache = await res.json()
    } catch (e) {
      upstreamChangesCache = { available: false }
    }
  }
  const filterEl = document.getElementById('upstreamChangesFilter')
  labelUpstreamViewTabs(upstreamChangesCache)
  renderUpstreamChanges(upstreamChangesCache, filterEl ? filterEl.value : '')
}

/** Nezetvaltas a listan belul. A szuro szandekosan MEGMARAD: aki rakeresett
 *  valamire, az valoszinuleg ugyanarra kivancsi a masik nezetben is. */
function setUpstreamChangesView(view) {
  upstreamChangesView = view
  const tabChanges = document.getElementById('upstreamViewChanges')
  const tabFiles = document.getElementById('upstreamViewFiles')
  if (tabChanges) tabChanges.classList.toggle('active', view === 'valtozas')
  if (tabFiles) tabFiles.classList.toggle('active', view === 'fajl')
  const filterEl = document.getElementById('upstreamChangesFilter')
  renderUpstreamChanges(upstreamChangesCache, filterEl ? filterEl.value : '')
}

/** A ket fulre a SZAMOK is kikerulnek, mert pont a szamok ertelmezese volt a
 *  felreertes forrasa: 112 valtozas -- 191 fajl, ket kulon mertekegyseg. */
function labelUpstreamViewTabs(data) {
  const tabChanges = document.getElementById('upstreamViewChanges')
  const tabFiles = document.getElementById('upstreamViewFiles')
  const fc = (data && data.fileCounts) || null
  if (tabChanges) tabChanges.textContent = t('upstream.view.changes', { n: (data && data.total) || 0 })
  if (tabFiles) tabFiles.textContent = t('upstream.view.files', { n: fc ? fc.total : 0 })
}

document.addEventListener('DOMContentLoaded', () => {
  const btn = document.getElementById('overviewUpstreamChangesBtn')
  if (btn) btn.addEventListener('click', openUpstreamChanges)
  const close = document.getElementById('upstreamChangesClose')
  const overlay = document.getElementById('upstreamChangesModal')
  if (close && overlay) close.addEventListener('click', () => closeModal(overlay))
  const filterEl = document.getElementById('upstreamChangesFilter')
  if (filterEl) {
    filterEl.addEventListener('input', () => renderUpstreamChanges(upstreamChangesCache, filterEl.value))
  }
  const tabChanges = document.getElementById('upstreamViewChanges')
  const tabFiles = document.getElementById('upstreamViewFiles')
  if (tabChanges) tabChanges.addEventListener('click', () => setUpstreamChangesView('valtozas'))
  if (tabFiles) tabFiles.addEventListener('click', () => setUpstreamChangesView('fajl'))
})

// === Onellenorzes -> vegigvezeto ===========================================
//
// Boss, 2026-08-19: "vegig kell vezetni a folyamaton. [...] ha kiirja ezt a
// hianyossagot, akkor ott megnyom egy gombot es vegigvezeti ezen a folyamaton a
// usert." Egy "Teendo: csatlakoztasd ujra" mondat epp a nehez reszt hagyja a
// felhasznalora. Ket ut van, es MINDKETTO kell:
//
//   GYORS      -- most ujra csatlakoztatjuk a fiokot. Egy hetig ujra megy.
//   VEGLEGES   -- a Google-alkalmazas "Testing" allapotbol "Production"-ba
//                 teteles ("elesites"). Testing alatt a Google 7 naponta
//                 KOTELEZOEN eldobja a tokent (refresh_token_expires_in:
//                 604799), tehat amig ez all, hetente ujra ide jutunk.
//
// A ket ut nem alternativa: az elesites utan is kell EGY ujracsatlakoztatas,
// mert a mar kiadott token a sajat regi hataridejevel el tovabb. Ez a
// vegigvezetoben ki is van irva, kulonben a user elesit, majd ket nap mulva
// megint itt all, es azt hiszi, nem mukodott.
function _guideOverlay() { return document.getElementById('selfCheckGuideOverlay') }

// === "Futtasd le most" =======================================================
//
// A "meg sosem futott" / "megallt" sor nem teendo, hanem gomb. Ha a
// felhasznalot ilyenkor a Fiokok oldalra dobnank, pont azt kellene kitalalnia,
// amit mi mar tudunk: hogy mit kell megnyomni.
let _googleLiveCheckRunning = false

async function runGoogleLiveCheckNow() {
  if (_googleLiveCheckRunning) { showToast(t('conn.live_running'), 4000); return }
  _googleLiveCheckRunning = true
  // Tiz fiok tiz python-inditas: ez fel percig is eltarthat, es a hallgatas
  // pont ugy nezne ki, mint egy nem mukodo gomb.
  showToast(t('conn.live_running'), 30000)
  let d
  try {
    const res = await fetch('/api/connections/google/live-check', { method: 'POST' })
    d = await res.json()
  } catch (err) {
    _googleLiveCheckRunning = false
    showToast(t('conn.live_failed', { msg: String(err.message || err) }), 8000)
    return
  }
  _googleLiveCheckRunning = false
  if (!d || !d.ok) {
    showToast(t('conn.live_failed', { msg: (d && d.error) || '' }), 8000)
    return
  }
  const accounts = (d.result && Array.isArray(d.result.accounts)) ? d.result.accounts : []
  const rossz = accounts.filter(a => a && a.ok === false)
  showToast(rossz.length
    ? t('conn.live_done_bad', { n: rossz.length, all: accounts.length })
    : t('conn.live_done_ok', { n: accounts.length }), 8000, rossz.length === 0)
  renderOverviewConnections()
}

// === Helyben elvegzett ujracsatlakoztatas =====================================
//
// Boss, 2026-08-22: "vagy ha auth tal akor adjon kodot linket amit a
// bongeszobe kell megnyitni es visszakapok kodot. mindegy. csak vezesse vegig
// a komuvesunket a folyamaton. hulyebiztosan!"
//
// Ezert a "Gyors megoldas" ful mar NEM azt mondja, hogy menj at a Fiokok
// oldalra es keresd meg a sort -- hanem itt, ebben az ablakban vegigviszi az
// egeszet: indit, ad egy linket, elveszi a visszakapott cimet, es a vegen
// megkerdezi a szervert, hogy tenyleg sikerult-e. Tobb fiok eseten egyesevel,
// szamlaloval, mert tiz halott hozzaferesnel a "csatlakoztasd ujra" onmagaban
// nem elvegezheto utasitas.
let _guideAuth = null
let _guideAuthPoll = null

/** Melyik fiokokat kell ujracsatlakoztatni ehhez a sorhoz. Ures lista =
 *  ez a sor nem fiokrol szol (pl. a regi, egyfiokos levelkuldo token). */
function _guideAccountIds(target) {
  if (!target) return []
  if (Array.isArray(target.accounts) && target.accounts.length) {
    return target.accounts.map(x => String(x).trim()).filter(Boolean)
  }
  const id = String(target.id || '')
  if (id === 'google:legacy' || !id.startsWith('google:')) return []
  return [id.slice('google:'.length)]
}

function _guideAuthStopPoll() {
  if (_guideAuthPoll) { clearInterval(_guideAuthPoll); _guideAuthPoll = null }
}

function _guideAuthPanelHtml() {
  const st = _guideAuth
  if (!st) return ''
  const id = st.accounts[st.idx] || ''
  const name = escapeHtml(id)
  const total = st.accounts.length
  const head = total > 1
    ? `<div class="guide-auth-progress">${escapeHtml(t('guide.auth_progress', { i: st.idx + 1, n: total, name: id }))}</div>`
    : ''

  if (st.phase === 'done') {
    const doneMsg = st.savedAs && st.savedAs !== id
      ? t('guide.auth_done_saved', { name: st.savedAs })
      : t('guide.auth_done_one', { name: id })
    const btn = (st.idx + 1 < total) ? t('guide.auth_next_btn') : t('guide.auth_verify_btn')
    return `${head}<div class="guide-result good">${escapeHtml(doneMsg)}</div>
      <div class="guide-auth-actions"><button class="btn-primary" onclick="guideAuthNext()">${escapeHtml(btn)}</button></div>`
  }

  if (st.phase === 'failed') {
    // A Google elutasitasa nem "nem sikerult": egy oka van es egy javitasa,
    // es barmi altalanosabbat mondani azt jelenti, hogy a felhasznalo olyat
    // probal ujra, ami nem tud sikerulni.
    const body = st.blocked === 'test-user'
      ? `<div class="guide-result bad">${t('guide.auth_blocked')}</div>
         <div class="guide-auth-actions">
           <a class="btn-primary" href="${escapeHtml(_guideConsoleUrl())}" target="_blank" rel="noopener">${escapeHtml(t('guide.auth_blocked_btn'))}</a>
           <button onclick="guideAuthStart(false)">${escapeHtml(t('guide.auth_retry_btn'))}</button>
         </div>`
      : `<div class="guide-result bad">${escapeHtml(t('guide.auth_failed', { msg: st.error || '' }))}</div>
         <div class="guide-auth-actions">
           <button class="btn-primary" onclick="guideAuthStart(false)">${escapeHtml(t('guide.auth_retry_btn'))}</button>
           ${st.canForce ? `<button onclick="guideAuthStart(true)">${escapeHtml(t('guide.auth_force_btn'))}</button>` : ''}
         </div>`
    return head + body
  }

  if (st.phase === 'consent' && st.url) {
    // A link HAROM alakban all ott: gomb (egy kattintas), masolas gomb, es egy
    // kijelolheto mezo. A masolas gomb ugyanis nem biztonsagos kapcsolaton nem
    // mukodik, es egy nem mukodo gomb itt zsakutca lenne.
    return `${head}
      <div class="guide-auth-lead">${t('guide.auth_link_lead', { name })}</div>
      <div class="guide-auth-actions">
        <a class="btn-primary" href="${escapeHtml(st.url)}" target="_blank" rel="noopener">${escapeHtml(t('guide.auth_open_btn'))}</a>
        <button onclick="guideAuthCopy()">${escapeHtml(t('guide.auth_copy_btn'))}</button>
      </div>
      <input id="guideAuthUrl" class="guide-auth-url" readonly value="${escapeHtml(st.url)}" onclick="this.select()">
      <div class="guide-auth-lead">${t('guide.auth_paste_lead')}</div>
      <div class="guide-auth-actions">
        <input id="guideAuthPasteInput" class="guide-auth-input" placeholder="${escapeHtml(t('guide.auth_paste_ph'))}">
        <button class="btn-primary" onclick="guideAuthPasteSubmit()">${escapeHtml(t('guide.auth_paste_btn'))}</button>
      </div>`
  }

  if (st.phase === 'starting' || st.phase === 'saving') {
    const msg = st.phase === 'saving' ? t('guide.auth_saving') : t('guide.auth_starting')
    return `${head}<div class="guide-auth-lead">${escapeHtml(msg)}</div>`
  }

  return `${head}<div class="guide-auth-actions">
      <button class="btn-primary" onclick="guideAuthStart(false)">${escapeHtml(t('guide.auth_start_btn'))}</button>
    </div>`
}

function _renderGuideAuth() {
  const el = document.getElementById('guideAuthPanel')
  if (!el) return
  // A beirt szoveget nem szabad ujrarajzolassal elvenni: a poll masodpercenkent
  // fut, a beillesztes meg eltarthat.
  const keep = document.getElementById('guideAuthPasteInput')
  const kept = keep ? keep.value : ''
  el.innerHTML = _guideAuthPanelHtml()
  const inp = document.getElementById('guideAuthPasteInput')
  if (inp && kept) inp.value = kept
}

async function guideAuthStart(force) {
  const st = _guideAuth
  if (!st || st.busy) return
  const id = st.accounts[st.idx]
  if (!id) return
  st.busy = true; st.phase = 'starting'; st.url = ''; st.error = ''; st.blocked = null; st.canForce = false
  _renderGuideAuth()
  let d
  try {
    const res = await fetch('/api/connections/google/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      // `force` SZIGORUAN logikai: egy atadott click-Event igaz-szeru lenne, es
      // minden elso kattintas kiloné valaki mas futo bejelentkeztetéset.
      body: JSON.stringify({ id, force: force === true }),
    })
    d = await res.json()
  } catch (err) {
    st.busy = false; st.phase = 'failed'; st.error = String(err.message || err); _renderGuideAuth(); return
  }
  st.busy = false
  if (!d || !d.ok) {
    st.phase = 'failed'
    if (d && d.code === 'busy') {
      // Megnevezett kiut, nem zsakutca: megmondjuk, KI futtat epp egyet, es
      // felajanljuk, hogy megszakitjuk.
      st.error = t('guide.auth_busy', { who: (d && d.busyAccountId) || '?' })
      st.canForce = true
    } else {
      st.error = (d && d.error) || t('common.error_save')
    }
    _renderGuideAuth(); return
  }
  _guideAuthStopPoll()
  _guideAuthPoll = setInterval(_guideAuthTick, 2000)
  _guideAuthTick()
}

async function _guideAuthTick() {
  const st = _guideAuth
  if (!st) { _guideAuthStopPoll(); return }
  let s
  try { s = await (await fetch('/api/connections/google/login')).json() } catch { return }
  if (s.projectId) _selfCheckProjectId = s.projectId
  if (s.url) st.url = s.url
  if (s.phase === 'done') {
    _guideAuthStopPoll()
    st.phase = 'done'; st.done[st.accounts[st.idx]] = true; st.savedAs = s.savedAs || null
    _renderGuideAuth(); renderOverviewConnections(); return
  }
  if (s.phase === 'failed') {
    _guideAuthStopPoll()
    st.phase = 'failed'; st.blocked = s.blocked || null; st.error = s.error || ''
    _renderGuideAuth(); return
  }
  if (!s.active) {
    // A szerver mar nem futtat semmit, es nem mondott se sikert, se hibat --
    // vissza a kiindulashoz, hogy legyen mit megnyomni.
    _guideAuthStopPoll()
    if (st.phase !== 'done') st.phase = 'idle'
    _renderGuideAuth(); return
  }
  st.phase = s.phase === 'consent' ? 'consent' : 'starting'
  _renderGuideAuth()
}

async function guideAuthCopy() {
  const st = _guideAuth
  if (!st || !st.url) return
  try {
    await navigator.clipboard.writeText(st.url)
    showToast(t('guide.auth_copied'), 4000, true)
  } catch {
    // Nem biztonsagos kapcsolaton nincs vagolap-API. Ilyenkor kijeloljuk a
    // mezot: onnan Ctrl+C-vel elviheto.
    const el = document.getElementById('guideAuthUrl')
    if (el) { el.focus(); el.select() }
  }
}

async function guideAuthPasteSubmit() {
  const st = _guideAuth
  const inp = document.getElementById('guideAuthPasteInput')
  if (!st || !inp || st.busy) return
  const value = inp.value.trim()
  if (!value) { inp.focus(); return }
  st.busy = true; st.phase = 'saving'; _renderGuideAuth()
  let d
  try {
    const res = await fetch('/api/connections/google/login/paste', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ value }),
    })
    d = await res.json()
  } catch (err) {
    st.busy = false; st.phase = 'failed'; st.error = String(err.message || err); _renderGuideAuth(); return
  }
  st.busy = false
  if (!d || !d.ok) {
    st.phase = 'failed'; st.blocked = (d && d.blocked) || null; st.error = (d && d.error) || ''
    _renderGuideAuth(); return
  }
  _guideAuthStopPoll()
  st.phase = 'done'; st.done[st.accounts[st.idx]] = true; st.savedAs = d.savedAs || null
  _renderGuideAuth()
  renderOverviewConnections()
}

function guideAuthNext() {
  const st = _guideAuth
  if (!st) return
  if (st.idx + 1 < st.accounts.length) {
    st.idx += 1
    st.phase = 'idle'; st.url = ''; st.error = ''; st.blocked = null; st.savedAs = null; st.canForce = false
    _renderGuideAuth()
    return
  }
  selfCheckGuideVerify()
}

/** A Cloud Console pontosan arra a projektre nyilik, amelyiket eleziteni kell. */
function _guideConsoleUrl() {
  return _selfCheckProjectId
    ? `https://console.cloud.google.com/auth/audience?project=${encodeURIComponent(_selfCheckProjectId)}`
    : 'https://console.cloud.google.com/auth/audience'
}

function _guideSteps() {
  // A lepesszovegek HTML-kent kerulnek be (gombfeliratokat emelnek ki), ezert a
  // fiok neve -- az egyetlen nem-forditasbol jovo darab -- escape-elve megy.
  const name = escapeHtml(_selfCheckGuideTarget ? _selfCheckGuideTarget.label : '')
  // A REGI, egyfiokos token nem a Fiokok oldal listajaban all: azt a
  // levelkuldes hasznalja, es sajat parancs ujitja meg. Ha ezt osszemosnank a
  // tobbivel, a user a Fiokok oldalon keresne egy sort, ami ott nincs.
  const legacy = !!(_selfCheckGuideTarget && _selfCheckGuideTarget.id === 'google:legacy')
  if (_selfCheckGuideTab === 'permanent') {
    return [
      { html: t('guide.perm_1'), btn: { label: t('guide.perm_open_btn'), href: _guideConsoleUrl() } },
      { html: t('guide.perm_2') },
      { html: t('guide.perm_3') },
      { html: t('guide.perm_4') },
      // A csapda, amibe enelkul mindenki belesetal: az elesites a MAR kiadott
      // hozzafereseket nem ujitja meg, azok a sajat regi hataridejukkel elnek
      // tovabb. Aki ezt nem tudja, ket nap mulva megint itt all, es azt hiszi,
      // nem mukodott az elesites.
      { html: t('guide.perm_5'), btn: { label: t('guide.perm_quick_btn'), tab: 'quick' } },
    ]
  }
  // Ha tudjuk, MELYIK fiokrol van szo, akkor nem kuldjuk sehova: itt helyben
  // vegigmegyunk a bejelentkeztetésen. Ez az egyetlen ut, ami egy olyan
  // felhasznalonak is vegigvihető, aki terminalt nem nyit meg.
  const ids = _guideAccountIds(_selfCheckGuideTarget)
  if (ids.length) {
    return [
      {
        html: ids.length > 1
          ? t('guide.auth_intro_many', { n: ids.length, name: escapeHtml(ids.join(', ')) })
          : t('guide.auth_intro_one', { name: escapeHtml(ids[0]) }),
        auth: true,
      },
    ]
  }
  return legacy
    ? [
      { html: t('guide.legacy_1') },
      { html: t('guide.legacy_2'), btn: { label: t('guide.quick_open_btn'), page: 'accounts' } },
      { html: t('guide.legacy_3') },
      { html: t('guide.quick_4') },
    ]
    : [
      { html: t('guide.quick_1', { name }), btn: { label: t('guide.quick_open_btn'), page: 'accounts' } },
      { html: t('guide.quick_2', { name }) },
      { html: t('guide.quick_3') },
      { html: t('guide.quick_4') },
    ]
}

/** Fulvaltas kodbol. A ket ut NEM alternativa: az elesites utan is kell EGY
 *  ujracsatlakoztatas, es az ujracsatlakoztatas utan is kell az elesites --
 *  ezert kell tudni a vegigvezetonek atkuldeni a masikra. */
function selfCheckGuideOpenTab(name) {
  _selfCheckGuideTab = name === 'permanent' ? 'permanent' : 'quick'
  _renderGuide()
}

function _renderGuide() {
  const lead = document.getElementById('selfCheckGuideLead')
  const stepsEl = document.getElementById('selfCheckGuideSteps')
  const result = document.getElementById('selfCheckGuideResult')
  if (!lead || !stepsEl) return
  result.hidden = true
  result.className = 'guide-result'
  document.querySelectorAll('#selfCheckGuideTabs .guide-tab').forEach((b) => {
    b.classList.toggle('active', b.dataset.guide === _selfCheckGuideTab)
  })
  const name = _selfCheckGuideTarget ? _selfCheckGuideTarget.label : ''
  lead.textContent = _selfCheckGuideTab === 'permanent'
    ? t('guide.lead_permanent')
    : _guideAuth
      ? t('guide.lead_auth')
      : t('guide.lead_quick', { name })
  const steps = _guideSteps()
  stepsEl.innerHTML = steps.map((s) => {
    // Az interaktiv lepes tartalma nem itt keletkezik: a poll masodpercenkent
    // frissiti, ezert sajat, ujrarajzolhato dobozt kap.
    if (s.auth) return `<li>${s.html}<div id="guideAuthPanel" class="guide-auth"></div></li>`
    let btn = ''
    if (s.btn && s.btn.href) {
      btn = `<a class="btn-primary" href="${escapeHtml(s.btn.href)}" target="_blank" rel="noopener">${escapeHtml(s.btn.label)}</a>`
    } else if (s.btn && s.btn.page) {
      btn = `<button class="btn-primary" onclick="switchPage('${s.btn.page}')">${escapeHtml(s.btn.label)}</button>`
    } else if (s.btn && s.btn.tab) {
      btn = `<button class="btn-primary" onclick="selfCheckGuideOpenTab('${s.btn.tab}')">${escapeHtml(s.btn.label)}</button>`
    }
    // A lepesszoveg forditasbol jon (nem felhasznaloi adat), es <b>/<span>
    // jeloli benne a kepernyon lathato gombfeliratot -- ezert megy be HTML-kent.
    return `<li>${s.html}${btn ? `<div>${btn}</div>` : ''}</li>`
  }).join('')
  if (steps.some(x => x.auth)) _renderGuideAuth()
}

function openSelfCheckGuide(target) {
  _selfCheckGuideTarget = target || null
  _selfCheckGuideTab = 'quick'
  // Minden nyitas tiszta lappal indul: egy felbehagyott korabbi folyamat
  // allapota a legrosszabbkor -- egy masik fioknal -- jonne vissza.
  _guideAuthStopPoll()
  const ids = _guideAccountIds(_selfCheckGuideTarget)
  _guideAuth = ids.length
    ? { accounts: ids, idx: 0, done: {}, phase: 'idle', url: '', error: '', blocked: null, savedAs: null, busy: false, canForce: false }
    : null
  const titleEl = document.getElementById('selfCheckGuideTitle')
  if (titleEl) {
    titleEl.textContent = (target && target.live)
      ? t('guide.title_live')
      : (target && target.status === 'soon')
        ? t('guide.title_soon', { name: target.label })
        : t('guide.title_expired', { name: target ? target.label : '' })
  }
  _renderGuide()
  const ov = _guideOverlay()
  if (!ov) return
  ov.hidden = false
  ov.classList.add('active')
  document.body.style.overflow = 'hidden'
}

function closeSelfCheckGuide() {
  // A szerveren futo bejelentkeztetést NEM szakitjuk meg: a bezaras lehet
  // veletlen is, es egy felig kesz folyamat eldobasa itt tobbet artana.
  // Csak a lekerdezest allitjuk le, kulonben a hattérben orokke ketmasodpercenkent
  // kerdezne a szervert egy lathatatlan ablak.
  _guideAuthStopPoll()
  const ov = _guideOverlay()
  if (!ov) return
  ov.hidden = true
  ov.classList.remove('active')
  document.body.style.overflow = ''
}

/**
 * A zaro lepes: NEM elhisszuk, hogy sikerult, hanem ujra megkerdezzuk a
 * szervert, es AZT mondjuk vissza, amit lat. Enelkul a vegigvezeto vege egy
 * "kesz vagy!" lenne, ami akkor is megjelenik, ha semmi nem valtozott.
 */
async function selfCheckGuideVerify() {
  const result = document.getElementById('selfCheckGuideResult')
  if (!result) return
  result.hidden = false
  result.className = 'guide-result'
  result.textContent = t('guide.checking')
  if (_selfCheckGuideTarget && _selfCheckGuideTarget.live) {
    // Eloszor UJRAMERUNK. A tarolt eredmeny akar egy oras is lehet -- eppen az
    // most csatlakoztatott fiokot mutatna halottnak.
    try { await fetch('/api/connections/google/live-check', { method: 'POST' }) } catch { /* a lenti osszefoglalo ugyis kimondja */ }
  }
  let d
  try {
    const res = await fetch('/api/connections/summary')
    if (!res.ok) throw new Error('fetch failed')
    d = await res.json()
  } catch {
    result.className = 'guide-result bad'
    result.textContent = t('conn.ov_unreachable')
    return
  }
  // A vegleges uton MAS a kerdes. Nem az, hogy el-e a hozzaferes (az a gyors
  // ut dolga), hanem az, hogy megszunt-e a 7 napos korlat. Ez MERHETO: a
  // "Testing" allapotban kiadott token `refresh_token_expires_in`-t kap
  // (604799 mp), es csak az ilyen fiokoknak keletkezik lejarat-soruk. Ha az
  // elesites megtortent ES a fiokot ujracsatlakoztattak, a sora eltunik.
  if (_selfCheckGuideTab === 'permanent') {
    const items = (d.expiry && Array.isArray(d.expiry.items)) ? d.expiry.items : []
    const korlatos = items.filter(i => String(i.id || '').startsWith('google:') && i.id !== 'google:legacy')
    const osszes = (d.google && typeof d.google.total === 'number') ? d.google.total : korlatos.length
    renderOverviewConnections()
    if (osszes === 0) {
      result.className = 'guide-result'
      result.textContent = t('guide.verify_perm_none')
      return
    }
    if (korlatos.length === 0) {
      result.className = 'guide-result good'
      result.textContent = t('guide.verify_perm_ok', { n: osszes })
      return
    }
    // Reszleges allapot: ez a NORMALIS a kozzetetel utan, es ha nem mondanank
    // ki, a felhasznalo azt hinne, hogy az elesites nem sikerult.
    result.className = 'guide-result bad'
    result.innerHTML = t('guide.verify_perm_partial', {
      n: korlatos.length,
      all: osszes,
      names: escapeHtml(korlatos.map(i => i.label).join(', ')),
    }) + `<div class="guide-auth-actions"><button class="btn-primary" onclick="selfCheckGuideOpenTab('quick')">${escapeHtml(t('guide.perm_quick_btn'))}</button></div>`
    return
  }

  // Az elo sor ellenorzese nem az orabol jon: ott eppen az volt a baj, hogy az
  // ora rendben volt, kozben a Google elutasitott mindent. Ezert itt UJRA
  // megkerdezzuk a Google-t, es azt mondjuk vissza, amit valaszolt.
  if (_selfCheckGuideTarget && _selfCheckGuideTarget.live) {
    const acc = (d.health && Array.isArray(d.health.items)) ? d.health.items : []
    const bad = acc.find(x => x.id === 'google_live_bad')
    const okrow = acc.find(x => x.id === 'google_live_ok')
    renderOverviewConnections()
    if (bad) {
      result.className = 'guide-result bad'
      result.textContent = t('guide.verify_live_bad', { n: (bad.params && bad.params.n) || 0, names: (bad.params && bad.params.names) || '' })
    } else {
      // A siker nem a vege. Amig az alkalmazas "teszt" allapotban van, ez 7 nap
      // mulva megint le fog jarni -- ezt itt kell kimondani, nem egy masik
      // fulon, amire senki nem kattint.
      result.className = 'guide-result good'
      result.innerHTML = escapeHtml(t('guide.verify_live_ok', { n: (okrow && okrow.params && okrow.params.n) || 0 }))
        + `<div class="guide-auth-nudge">${t('guide.auth_perm_nudge')}</div>`
        + `<div class="guide-auth-actions"><button class="btn-primary" onclick="selfCheckGuideOpenTab('permanent')">${escapeHtml(t('guide.auth_perm_btn'))}</button></div>`
    }
    return
  }
  const items = (d && d.expiry && Array.isArray(d.expiry.items)) ? d.expiry.items : []
  const mine = _selfCheckGuideTarget
    ? items.find((i) => i.id === _selfCheckGuideTarget.id)
    : null
  // Frissitjuk a kartyat is: a vegigvezeto es az Attekintes nem allithat ket
  // kulonbozot ugyanarrol a pillanatrol.
  renderOverviewConnections()
  if (!mine) {
    // Eltunt a listabol: nincs mar hatarideje (pl. elesitett app utan kiadott,
    // nem lejaro token) -- ez jo hir, de nem hallgatjuk el, hogy MIERT jo.
    result.className = 'guide-result good'
    result.textContent = t('guide.verify_gone')
    return
  }
  if (mine.status === 'ok') {
    result.className = 'guide-result good'
    result.innerHTML = escapeHtml(t('guide.verify_ok', { name: mine.label, d: Math.max(0, mine.daysLeft) }))
      + `<div class="guide-auth-nudge">${t('guide.auth_perm_nudge')}</div>`
      + `<div class="guide-auth-actions"><button class="btn-primary" onclick="selfCheckGuideOpenTab('permanent')">${escapeHtml(t('guide.auth_perm_btn'))}</button></div>`
  } else {
    result.className = 'guide-result bad'
    result.textContent = mine.status === 'expired'
      ? t('guide.verify_still_expired', { name: mine.label })
      : t('guide.verify_still_soon', { name: mine.label, d: Math.max(0, mine.daysLeft) })
  }
}

function _wireSelfCheckGuide() {
  const ov = _guideOverlay()
  if (!ov) return
  document.getElementById('selfCheckGuideClose').addEventListener('click', closeSelfCheckGuide)
  document.getElementById('selfCheckGuideDone').addEventListener('click', closeSelfCheckGuide)
  document.getElementById('selfCheckGuideCheck').addEventListener('click', selfCheckGuideVerify)
  ov.addEventListener('click', (e) => { if (e.target === ov) closeSelfCheckGuide() })
  document.getElementById('selfCheckGuideTabs').addEventListener('click', (e) => {
    const btn = e.target.closest('.guide-tab')
    if (!btn) return
    _selfCheckGuideTab = btn.dataset.guide
    _renderGuide()
  })
  // Az Esc a tobbi ablakot a .active osztaly levetelevel zarja; ez az ablak
  // [hidden]-nel is rejtozik, ezert kulon kell kezelni, kulonben a bezaras utan
  // egy lathatatlan, de kattintast nyelo reteg maradna a kepernyon.
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !ov.hidden) closeSelfCheckGuide()
  })
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _wireSelfCheckGuide)
} else {
  _wireSelfCheckGuide()
}

// Mihez kepest? Onallo fuggveny, mert a "naprakesz" es a "nem sikerult a
// meres" agnak is ki kell irnia: szam nelkul is tudni kell, melyik ket pontot
// vetettuk ossze.
function pairHtml(u) {
  return (u.localRef && u.upstreamRef)
    ? `<div class="upstream-sync-pair">${escapeHtml(t('overview.upstream.pair', { local: u.localRef, upstream: u.upstreamRef }))}</div>`
    : ''
}

function renderOverviewUpstreamSync(upstreamSync) {
  const box = document.getElementById('overviewUpstreamSync')
  const body = document.getElementById('overviewUpstreamBody')
  const meta = document.getElementById('overviewUpstreamMeta')
  if (!upstreamSync || upstreamSync.aheadCount === null && upstreamSync.behindCount === null) {
    box.hidden = true
    return
  }
  box.hidden = false
  const locale = (window._lang === 'en') ? 'en-US' : 'hu-HU'
  // A datum onmagaban nem mondja meg, hogy REGI-e.
  //
  // A 2026-08-10-i meres kilenc napig allt itt "08. 10. 03:21" felirattal, es
  // a kilencedik napon ugyanolyan hitelesnek latszott, mint az elsoen -- pedig
  // addigra a 63-bol 111 lett. Ezert all a datum mellett a KORA is, tiz nap
  // (ket kihagyott heti futas) folott pedig kiirjuk, hogy elavult.
  const age = Number.isFinite(Number(upstreamSync.ageDays)) && upstreamSync.ageDays !== null
    ? Number(upstreamSync.ageDays)
    : null
  const stamp = upstreamSync.checkedAt
    ? new Date(upstreamSync.checkedAt).toLocaleString(locale, { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })
    : ''
  let metaText = stamp
  if (age !== null) {
    const ageText = age === 0 ? t('overview.upstream.age_today') : t('overview.upstream.age', { d: age })
    metaText = stamp ? `${stamp} · ${ageText}` : ageText
    if (age > 10) metaText += ` · ${t('overview.upstream.stale')}`
  }
  meta.textContent = metaText
  // A "mi valtozott?" gomb mindig ott van, ha van mit mutatni. Boss: "ezert egy
  // lista kellene [...] es mind a 169-re egy rovid par soros leiras hogy mit
  // javitottak vagy fejlesztettek."
  const changesBtn = document.getElementById('overviewUpstreamChangesBtn')
  if (changesBtn) {
    changesBtn.hidden = false
    changesBtn.textContent = t('upstream.changes.open')
  }
  meta.classList.toggle('upstream-meta-stale', age !== null && age > 10)
  const behind = upstreamSync.behindCount ?? 0
  const conflicts = upstreamSync.conflictCount ?? upstreamSync.conflictingFiles.length
  // ★ A NULLA KET DOLGOT JELENTHET, es az upstream-doboz eddig nem valasztotta
  //   szet a kettot: a "0 fajl / 0 utkozes / 0 commit" ugyanugy nezett ki, ha
  //   NAPRAKESZEK vagyunk (a merge behuzta az egeszet), mint ha a meres el sem
  //   jutott az upstreamig. A kulonbseget nem a szamokbol talaljuk ki -- magat
  //   a forrast kerdezzuk meg: elhasalt-e a meres (`error`), es elerte-e a
  //   halozatot (`fetchOk`).
  const measureFailed = Boolean(upstreamSync.error)
  if (measureFailed) {
    // Az okot NEM talalgatjuk: a mero szkript sajat hibakodja megy ki, es
    // mellette a kovetkezo lepes.
    // Ismeretlen hibakodra a t() magat a kulcsot adja vissza -- azt nem irjuk
    // ki emberi okkent; ilyenkor a szkript nyers kodja megy ki valtozatlanul.
    const errKey = 'overview.upstream.err.' + upstreamSync.error
    const errText = t(errKey)
    const why = errText === errKey ? upstreamSync.error : errText
    body.innerHTML =
      '<div class="upstream-sync-offline">' + escapeHtml(t('overview.upstream.failed', { why })) + '</div>'
      + (pairHtml(upstreamSync) || '')
    if (changesBtn) changesBtn.hidden = true
    return
  }
  // ★ A KOMMIT-TAVOLSAG HAZUDIK EGY VISSZAVONT BEHUZAS UTAN, es ezt a mero
  //   szkript javitja ki: ha egy upstream-behuzast kesobb visszavontunk, a
  //   szamokat a behuzas ELOTTI allapotbol meri (kulonben 137 helyett 1 commit
  //   allna itt). A felulet dolga annyi, hogy ezt KI IS MONDJA -- egy szam, ami
  //   magyarazat nelkul ugrik 1-rol 137-re, ugyanolyan megbizhatatlan, mint egy
  //   rossz szam.
  const revertedNote = upstreamSync.revertedMerge
    ? '<div class="upstream-sync-commits">'
      + escapeHtml(t('overview.upstream.reverted', { sha: upstreamSync.revertedMerge }))
      + '</div>'
    : ''
  if (behind === 0) {
    // Ez a JO nulla -- de csak akkor mondhatjuk ki, ha a meres elerte a halot.
    // Halozat nelkul a nulla csak az utoljara letoltott allapotra igaz, es ezt
    // ki is mondjuk, nem naprakeszseget allitunk.
    const ahead = upstreamSync.aheadCount ?? null
    body.innerHTML =
      '<div class="upstream-sync-uptodate">'
      + escapeHtml(upstreamSync.fetchOk
          ? t('overview.upstream.uptodate')
          : t('overview.upstream.uptodate_stale'))
      + '</div>'
      + (ahead !== null && ahead > 0
          ? '<div class="upstream-sync-commits">' + escapeHtml(t('overview.upstream.ahead', { n: ahead })) + '</div>'
          : '')
      + revertedNote
      + (pairHtml(upstreamSync) || '')
    // Nincs mit felsorolni: a "Mi valtozott?" gomb ilyenkor ures listara nyilna.
    if (changesBtn) changesBtn.hidden = true
    return
  }
  // A harmadik szam MERT ertek, nem szamtani trukk.
  //
  // Elotte `behind - conflicts` allt itt, es ez ket KULONBOZO dolgot vont ki
  // egymasbol: a `behindCount` COMMIT-eket szamol, a `conflictCount` FAJLOKAT.
  // A merten `63 commit - 4 fajl = 59`, amit a doboz "59 konfliktusmentesen
  // athuzhato" nevvel mutatott a Bossnak -- egy szam, aminek semmi koze ahhoz,
  // hany valtozas huzhato at tenyleg. Ha a havi vizsgalat nem merte meg
  // (cleanFileCount: null), akkor gondolatjel all itt: a "nem tudjuk" mindig
  // jobb, mint egy magabiztos rossz szam.
  const cleanNum = Number(upstreamSync.cleanFileCount)
  const cleanKnown = upstreamSync.cleanFileCount !== null
    && upstreamSync.cleanFileCount !== undefined
    && Number.isFinite(cleanNum)
  const clean = cleanKnown ? String(cleanNum) : '–'
  const cleanTitle = cleanKnown ? '' : ` title="${escapeHtml(t('overview.upstream.clean_unmeasured'))}"`
  const badgeClass = conflicts === 0 ? 'upstream-badge-ok' : 'upstream-badge-warn'
  // Az utkozo fajlok NEVE nem itt all. Harmincnegy sornyi utvonal elnyomta azt
  // a harom szamot, ami miatt a doboz egyaltalan letezik -- a nevek helye a
  // "Mi valtozott?" teteles lista, ahol fajl-nezet es gorgetes is van. Itt csak
  // a SZAM marad, es a badge tooltipje megmondja, hol lathatoak.
  const conflictTitle = conflicts > 0
    ? ` title="${escapeAttr(t('overview.upstream.conflicts_where', { n: conflicts }))}"`
    : ''
  // Mihez kepest? A szamok csak akkor ellenorizhetok, ha kiirjuk, melyik ket
  // pontot vetettuk ossze: a sajat agunkat es az upstream fejlesztoi agat
  // (itt upstream/develop, nem a main -- a ketto kozott most 23 commit a
  // kulonbseg, tehat nem mindegy).
  const pair = pairHtml(upstreamSync)
  // Ha a meres nem ert el a halozathoz, az upstream oldal az utolso letoltott
  // allapot -- a szamok ekkor is igazak, csak nem a MOSTANI upstreamre.
  const offline = (upstreamSync.fetchOk === false)
    ? `<div class="upstream-sync-offline">${escapeHtml(t('overview.upstream.no_fetch'))}</div>`
    : ''
  // A sor egeszehez tartozo magyarazat: kimondja, hogy a commit es a fajl ket
  // kulon mertekegyseg, es osszerakja a ket fajlszamot. Csak akkor all ki, ha
  // a tiszta szam MERT -- kitalalt osszeget nem magyarazunk.
  const explain = cleanKnown
    ? `<div class="upstream-sync-explain">${escapeHtml(t('overview.upstream.explain', {
        c: behind, f: conflicts + cleanNum, x: conflicts, k: cleanNum,
      }))}</div>`
    : ''
  const total = cleanKnown ? String(conflicts + cleanNum) : '\u2013'
  const commitLine = `<div class="upstream-sync-commits">${escapeHtml(t('overview.upstream.commits', { c: behind }))}</div>`
  body.innerHTML = `
    <div class="upstream-sync-row">
      <span class="upstream-stat"${cleanTitle}><strong>${total}</strong> ${escapeHtml(t('overview.upstream.total'))}</span>
      <span class="upstream-stat ${badgeClass}"${conflictTitle}><strong>${conflicts}</strong> ${escapeHtml(t('overview.upstream.conflicts'))}</span>
      <span class="upstream-stat"${cleanTitle}><strong>${clean}</strong> ${escapeHtml(t('overview.upstream.clean'))}</span>
    </div>
    ${commitLine}
    ${explain}
    ${revertedNote}
    ${pair}
    ${offline}
  `
}

async function loadOverview() {
  try {
    const res = await fetch('/api/overview')
    if (!res.ok) throw new Error('HTTP ' + res.status)
    const d = await res.json()
    // Stats
    document.getElementById('statAgents').textContent = d.agents.running
    // A kulso (VS Code) kartyak nincsenek a Marveen-ugynokok kozott, de latszanak
    // a listaban -- ha van ilyen, kiirjuk, kulonben a szam es a kartyak szama
    // neman mond mast (Boss, 2026-08-23).
    document.getElementById('statAgentsSub').textContent = d.agents.external
      ? t('overview.stat.agents_sub_external', { n: d.agents.total, e: d.agents.external })
      : t('overview.stat.agents_sub', { n: d.agents.total })
    document.getElementById('statTasks').textContent = d.tasksToday
    const taskDiff = d.tasksToday - d.tasksYesterday
    document.getElementById('statTasksSub').textContent = taskDiff === 0 ? t('overview.stat.same_as_yesterday') : (taskDiff > 0 ? '+' + taskDiff + ' ' + t('overview.stat.change', { n: '' }).trim() : taskDiff + ' ' + t('overview.stat.change', { n: '' }).trim())
    document.getElementById('statMemories').textContent = d.memories.count.toLocaleString('hu-HU').replace(/,/g, ' ')
    document.getElementById('statMemoriesSub').textContent = `${t('overview.stat.sub.memories')} · ${d.memories.categories} category`
    document.getElementById('statSkills').textContent = d.skills.count
    document.getElementById('statSkillsSub').textContent = d.skills.today > 0 ? t('overview.stat.skills_today', { n: d.skills.today }) : ''
    renderOverviewCapabilities(d.unconfiguredCapabilities)
    renderOverviewSetupStatus()
    renderOverviewConnections()
    renderOverviewRateLimit(d.rateLimit, d.openrouterCredits, d.claudeAccounts)
    renderOverviewUpstreamSync(d.upstreamSync)
    // Team: reuse the hierarchy graph renderer so the overview card shows
    // exactly what the Csapat page does (avatars + reports-to tree).
    try {
      const tg = await fetch('/api/team/graph')
      if (tg.ok) {
        const graph = await tg.json()
        renderTeamGraph(document.getElementById('overviewTeamGrid'), graph)
      }
    } catch {}
    // Activity
    const act = document.getElementById('overviewActivity')
    act.innerHTML = ''
    if (!d.activity || d.activity.length === 0) {
      act.innerHTML = '<div style="color:var(--text-muted);font-size:13px">' + t('overview.no_activity') + '</div>'
    } else {
      for (const a of d.activity) {
        const icon = a.icon === 'delegate'
          ? '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>'
          : '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3C7.5 3 4 6.5 4 11v4l-2 3h4v2a3 3 0 0 0 3 3h6a3 3 0 0 0 3-3v-2h4l-2-3v-4c0-4.5-3.5-8-8-8z"/></svg>'
        const item = document.createElement('div')
        item.className = 'overview-activity-item'
        item.innerHTML = `
          <div class="overview-activity-icon">${icon}</div>
          <div class="overview-activity-body">
            <div class="overview-activity-title">${linkifyKanbanRefs(a.text)}</div>
            <div class="overview-activity-time">${formatRelative(a.at)}</div>
          </div>
        `
        act.appendChild(item)
      }
    }
  } catch (err) {
    document.getElementById('overviewActivity').innerHTML = '<div style="color:var(--text-muted);font-size:13px">' + t('overview.error', { msg: escapeHtml(String(err.message || err)) }) + '</div>'
  }
}

// Brand mark + product-brand chrome: pull the configured brand from
// /api/marveen and apply it to the dashboard chrome (tab title, mobile topbar,
// sidebar name, updates subtitle). brandName is the product/system name and is
// distinct from the main agent's display name; the backend defaults brandName to
// BOT_NAME, so a brand-unaware install keeps showing the agent name. If the
// field is absent (legacy backend) the existing HTML default text is kept.
async function initSidebarBrand() {
  try {
    const img = document.createElement('img')
    img.src = '/api/marveen/avatar' + avatarBust()
    img.onload = () => {
      const mark = document.getElementById('sidebarBrandMark')
      if (mark) { mark.textContent = ''; mark.appendChild(img) }
    }
    const res = await fetch('/api/marveen')
    if (res.ok) {
      const m = await res.json()
      const brand = m.brandName || m.name
      // Publish the brand tokens so every t() call ({brand}/{bot}/{agentId})
      // renders the configured names, then re-apply the static i18n so any
      // label painted before this fetch resolved picks up the real brand.
      window._brandTokens = {
        brand: brand || 'Marveen',
        bot: m.name || brand || 'Marveen',
        agentId: m.agentId || 'marveen',
        // {owner} alongside {bot}/{brand}: labels that name the operator must
        // render THIS install's OWNER_NAME. One of them used to ship the
        // author's own name as an English literal.
        owner: m.ownerName || '',
      }
      if (typeof renderStaticI18n === 'function') renderStaticI18n()
      if (brand) {
        document.title = brand
        const appleTitle = document.querySelector('meta[name="apple-mobile-web-app-title"]')
        if (appleTitle) appleTitle.setAttribute('content', brand)
        const topbar = document.getElementById('mobileTopbarTitle')
        if (topbar) topbar.textContent = brand
        const name = document.getElementById('sidebarBrandName')
        if (name) name.textContent = brand
        const subtitle = document.getElementById('updatesSubtitle')
        if (subtitle) subtitle.textContent = `${brand} ` + t('overview.updates_subtitle')
      }
    }
  } catch {}
}
initSidebarBrand()

// In an installed (standalone) PWA, lock the zoom: iOS otherwise auto-zooms when
// a small-text input is focused and allows stray pinch-zoom, neither of which
// suits an app-like control panel. Left untouched in a normal browser tab so
// page zoom / accessibility still work there.
if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone) {
  const vp = document.querySelector('meta[name="viewport"]')
  if (vp) vp.setAttribute('content', 'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover')
}

// === Updates page ===
function escapeHtmlUpdates(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]))
}

function renderUpdatesBadge(status) {
  const badge = document.getElementById('updatesBadge')
  if (!badge) return
  // Version-centric: show the number of NEW VERSIONS, not raw commits. Fall back
  // to the behind count only in the rare pre-release state (unreleased commits
  // but no new version tag yet).
  const versionCount = status && Array.isArray(status.releases)
    ? status.releases.filter((r) => r.version).length : 0
  const count = versionCount > 0 ? versionCount : ((status && status.behind) || 0)
  if (count > 0) {
    badge.textContent = String(count)
    badge.hidden = false
  } else {
    badge.hidden = true
  }
}

// === Branch-drift warning ===
// Installs that landed on a non-main branch (e.g. a branchless clone before
// the --branch main pin) keep receiving unreleased code from update.sh, which
// pulls the tracked branch. Two surfaces, both non-blocking: a dismissible
// top banner (dismissal persists per browser AND per branch, so a later switch
// to yet another branch re-warns) and a permanent notice on the Updates page.
// Dev machines follow develop on purpose; one dismissal silences the banner
// for them while the Updates-page notice stays as the quiet ground truth.
const BRANCH_DRIFT_DISMISS_PREFIX = 'marveen.branch-drift-dismissed.'
const BRANCH_HEAL_COMMAND = 'git checkout main && bash update.sh'

function branchDriftDismissed(branch) {
  try { return localStorage.getItem(BRANCH_DRIFT_DISMISS_PREFIX + branch) === '1' } catch { return false }
}

function updateBranchDriftUI(status) {
  const banner = document.getElementById('branchDriftBanner')
  if (!banner) return
  const branch = status && status.branch
  const drifted = !!branch && branch !== 'main'
  if (!drifted || branchDriftDismissed(branch)) {
    banner.hidden = true
    return
  }
  const textEl = document.getElementById('branchDriftBannerText')
  if (textEl) {
    textEl.innerHTML =
      `${t('branch_drift.banner.text', { branch: `<strong>${escapeHtmlUpdates(branch)}</strong>` })} ` +
      `<code>${BRANCH_HEAL_COMMAND}</code>`
  }
  banner.hidden = false
}

function wireBranchDriftBanner() {
  const dismiss = document.getElementById('branchDriftDismiss')
  if (!dismiss) return
  dismiss.addEventListener('click', () => {
    const banner = document.getElementById('branchDriftBanner')
    const branch = (window._updatesStatus && window._updatesStatus.branch) || ''
    try { if (branch) localStorage.setItem(BRANCH_DRIFT_DISMISS_PREFIX + branch, '1') } catch { /* storage blocked */ }
    if (banner) banner.hidden = true
  })
}

function renderBranchNotice(status) {
  const el = document.getElementById('updatesBranchNotice')
  if (!el) return
  const branch = status && status.branch
  if (!branch) { el.hidden = true; return }
  if (branch === 'main') {
    el.className = 'updates-branch-notice ok'
    el.innerHTML = `${t('branch_drift.notice.on_main')} (<code>main</code>)`
  } else {
    el.className = 'updates-branch-notice warn'
    el.innerHTML =
      `${t('branch_drift.notice.off_main', { branch: `<code>${escapeHtmlUpdates(branch)}</code>` })}<br>` +
      `${t('branch_drift.notice.heal')} <code>${BRANCH_HEAL_COMMAND}</code>`
  }
  el.hidden = false
}

async function pollUpdatesBadge() {
  try {
    const res = await fetch('/api/updates')
    if (!res.ok) return
    const data = await res.json()
    window._updatesStatus = data
    renderUpdatesBadge(data)
    updateBranchDriftUI(data)
  } catch {}
}

async function loadUpdates() {
  const summary = document.getElementById('updatesSummary')
  const list = document.getElementById('updatesCommitList')
  const applyBtn = document.getElementById('updatesApplyBtn')
  summary.textContent = t('updates.checking')
  summary.className = 'updates-summary'
  list.innerHTML = ''
  try {
    const res = await fetch('/api/updates')
    if (!res.ok) throw new Error('HTTP ' + res.status)
    const data = await res.json()
    window._updatesStatus = data
    renderUpdatesBadge(data)
    updateBranchDriftUI(data)
    renderBranchNotice(data)
    const cur = (data.current || '').slice(0, 7) || '–'
    const lat = (data.latest || '').slice(0, 7) || '–'
    if (data.error) {
      summary.className = 'updates-summary error'
      summary.innerHTML = `<strong>${t('updates.check_failed')}:</strong> ${escapeHtmlUpdates(data.error)}<br>${t('updates.current_label')} <code>${cur}</code>`
      applyBtn.hidden = true
    } else if (data.behind === 0) {
      summary.className = 'updates-summary up-to-date'
      summary.innerHTML = `<strong>${t('updates.up_to_date_html')}</strong> (<code>${cur}</code>). ${t('updates.no_changes')}`
      applyBtn.hidden = true
    } else {
      summary.className = 'updates-summary behind'
      const versions = (data.releases || []).filter((r) => r.version)
      if (versions.length > 0) {
        // Version-centric: "N uj verzio elerheto (v1.21.0)".
        summary.innerHTML = `<strong>${t('updates.versions_available', { n: versions.length })}</strong> <code>${escapeHtmlUpdates(versions[0].version)}</code>`
      } else {
        // Pre-release: unreleased commits but no new version tag yet.
        summary.innerHTML = `<strong>${t('updates.changes_available')}</strong> ${t('updates.available_on', { remote: `<code>${escapeHtmlUpdates(data.remote)}</code>` })}`
      }
      applyBtn.hidden = false
    }
    const commitCard = (c) => `
        <div class="updates-commit">
          <div class="updates-commit-head">
            <span>${escapeHtmlUpdates(c.short)} · ${escapeHtmlUpdates(c.author)}</span>
            <span>${escapeHtmlUpdates((c.date || '').slice(0, 10))}</span>
          </div>
          <div class="updates-commit-msg">${escapeHtmlUpdates(c.message)}</div>
        </div>`
    if (data.releases && data.releases.length) {
      // Version-centric: the human-language summary per version is the primary
      // content; the raw commit list (SHAs, conventional-commit prefixes, author
      // names) is tucked behind a collapsed "details" so it is never the first
      // thing the operator sees.
      list.innerHTML = data.releases.map((rel) => {
        const isUpcoming = !rel.version
        const label = isUpcoming ? t('updates.group.upcoming') : escapeHtmlUpdates(rel.version)
        const human = rel.summary
          ? escapeHtmlUpdates(rel.summary)
          : (isUpcoming ? t('updates.upcoming_note') : '')
        return `
        <div class="updates-version">
          <div class="updates-version-tag">${label}</div>
          ${human ? `<div class="updates-version-summary">${human}</div>` : ''}
          <details class="updates-version-details">
            <summary>${t('updates.details', { n: rel.commits.length })}</summary>
            <div class="updates-commit-list">${rel.commits.map(commitCard).join('')}</div>
          </details>
        </div>`
      }).join('')
    } else if (data.commits && data.commits.length) {
      list.innerHTML = data.commits.map(commitCard).join('')
    } else if (data.behind === 0) {
      list.innerHTML = `<p style="color:var(--text-muted);font-size:13px">${t('updates.no_changes')}</p>`
    }
  } catch (err) {
    summary.className = 'updates-summary error'
    summary.textContent = 'Hiba: ' + (err.message || err)
    applyBtn.hidden = true
  }
  renderDiagnoseOffer()
}

// Post-rollback diagnosis offer (PR-D). Reads /api/updates/status: if the last
// update failed/rolled-back and this host can run a Claude agent, offer the
// opt-in fixer; if it cannot (AVX), show a manual-intervention note instead.
async function renderDiagnoseOffer() {
  const box = document.getElementById('updatesDiagnose')
  if (!box) return
  let data
  try { data = await (await fetch('/api/updates/status')).json() } catch { box.hidden = true; return }
  if (data.needsHuman) {
    box.hidden = false
    box.className = 'updates-diagnose needs-human'
    box.innerHTML = `<strong>${escapeHtmlUpdates(t('updates.diagnose.title'))}</strong><p>${escapeHtmlUpdates(t('updates.diagnose.needs_human'))}</p>`
    return
  }
  if (!data.canDiagnose) { box.hidden = true; box.innerHTML = ''; return }
  box.hidden = false
  box.className = 'updates-diagnose'
  box.innerHTML = `<strong>${escapeHtmlUpdates(t('updates.diagnose.title'))}</strong>`
    + `<p>${escapeHtmlUpdates(t('updates.diagnose.body'))}</p>`
    + `<button class="btn-secondary btn-compact" id="updatesDiagnoseBtn">${escapeHtmlUpdates(t('updates.diagnose.btn'))}</button>`
  document.getElementById('updatesDiagnoseBtn').addEventListener('click', runDiagnose)
}

async function runDiagnose() {
  if (!confirm(t('updates.diagnose.consent'))) return
  const btn = document.getElementById('updatesDiagnoseBtn')
  if (btn) btn.disabled = true
  try {
    const res = await fetch('/api/updates/diagnose', { method: 'POST' })
    const data = await res.json().catch(() => ({}))
    if (!res.ok) {
      if (btn) btn.disabled = false
      showToast(t('updates.diagnose.failed', { msg: data.error || ('HTTP ' + res.status) }))
      return
    }
    showToast(data.already ? t('updates.diagnose.already') : t('updates.diagnose.started'))
    if (btn) { btn.hidden = true }
  } catch (err) {
    if (btn) btn.disabled = false
    showToast(t('updates.diagnose.failed', { msg: err.message || err }))
  }
}

document.getElementById('updatesCheckBtn').addEventListener('click', async () => {
  const btn = document.getElementById('updatesCheckBtn')
  btn.disabled = true
  try { await fetch('/api/updates/check', { method: 'POST' }) } catch {}
  await loadUpdates()
  btn.disabled = false
})

async function runUpdate(autoStash) {
  const btn = document.getElementById('updatesApplyBtn')
  btn.disabled = true
  btn.querySelector('.btn-text').hidden = true
  btn.querySelector('.btn-loading').hidden = false
  const resetBtn = () => {
    btn.disabled = false
    btn.querySelector('.btn-text').hidden = false
    btn.querySelector('.btn-loading').hidden = true
  }
  try {
    const res = await fetch('/api/updates/apply', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ autoStash: autoStash === true }),
    })
    // Parse the body regardless of status so preflight reasons
    // (not-on-main / dirty-tree / detached-head returned as 409 by
    // the backend) land in the toast instead of a bare "HTTP 409".
    const data = await res.json().catch(() => ({}))
    if (!res.ok) {
      resetBtn()
      // dirty-tree without autoStash: offer the auto-stash retry inline.
      if (data.reason === 'dirty-tree' && !autoStash) {
        if (confirm(t('updates.confirm.stash'))) {
          await runUpdate(true)
        }
        return
      }
      showToast(t('updates.toast.not_started', { msg: data.error || ('HTTP ' + res.status) }))
      return
    }
    showToast(t('updates.toast.applying'))
    // Poll the real outcome instead of a blind timed reload. update.sh (and its
    // detached finalizer) write store/update.last-result on exit, so we surface
    // success / rolled-back / failed rather than a false "done" that reloads
    // into an unchanged (or dead) dashboard.
    await pollUpdateOutcome(resetBtn)
  } catch (err) {
    resetBtn()
    showToast(t('updates.toast.error', {msg: err.message || err}))
  }
}

// Poll /api/updates/status until the run finishes (pidfile gone AND a fresh
// result is present), then show the true outcome. Reload only on success.
async function pollUpdateOutcome(resetBtn) {
  const startedAt = Date.now()
  const deadline = startedAt + 5 * 60_000   // hard cap: 5 min
  while (Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, 3000))
    let data
    try {
      const res = await fetch('/api/updates/status')
      data = await res.json()
    } catch {
      // Dashboard is mid-restart (expected): keep polling.
      continue
    }
    const result = data && data.result
    const fresh = result && typeof result.ts === 'number' && result.ts * 1000 >= startedAt - 5000
    if (data && !data.running && fresh) {
      const st = result.status
      if (st === 'success') {
        showToast(t('updates.toast.success', { old: result.old || '', new: result.new || '' }))
        setTimeout(() => window.location.reload(), 2000)
        return
      }
      if (st === 'rolled-back') {
        if (resetBtn) resetBtn()
        showToast(t('updates.toast.rolled_back', { old: result.old || '', msg: result.message || '' }))
        renderDiagnoseOffer()
        return
      }
      // failed
      if (resetBtn) resetBtn()
      showToast(t('updates.toast.failed', { phase: result.phase || '?', msg: result.message || ('code ' + result.code) }))
      renderDiagnoseOffer()
      return
    }
  }
  if (resetBtn) resetBtn()
  showToast(t('updates.toast.status_timeout'))
}

document.getElementById('updatesApplyBtn').addEventListener('click', async () => {
  if (!confirm(t('updates.confirm.apply'))) return
  await runUpdate(false)
})

// Poll the badge on startup and every 5 min so the nav link reflects
// the cached status even on tabs other than the Updates page.
pollUpdatesBadge()
setInterval(pollUpdatesBadge, 5 * 60_000)

// === First-run onboarding wizard ===
// Full-screen overlay shown when /api/onboarding/status reports the install
// still needs setup (pre-install-now / configure-later flow). Steps 2-3 reuse
// the existing channel-setup + pairing backend endpoints.
async function fetchOnboardingStatus() {
  try { return await (await fetch('/api/onboarding/status')).json() } catch { return null }
}
function onboardingCurrentStep(s) {
  if (!s.identityConfirmed) return 1
  if (!s.claudeAuthPresent || !s.agentsRunning) return 2
  if (!s.channelConfigured) return 3
  if (!s.paired) return 4
  return 0
}
// Operator can dismiss the wizard (skip/close). A false positive must never
// lock the dashboard, so the choice persists across reloads; normal UI still
// covers any real setup that remains.
const ONBOARDING_DISMISS_KEY = 'mvOnboardingDismissed'
function onboardingDismissed() {
  try { return localStorage.getItem(ONBOARDING_DISMISS_KEY) === '1' } catch { return false }
}
function dismissOnboarding() {
  try { localStorage.setItem(ONBOARDING_DISMISS_KEY, '1') } catch { /* private mode */ }
  const overlay = document.getElementById('onboardingOverlay')
  if (overlay) { overlay.classList.remove('active'); overlay.hidden = true }
  document.body.style.overflow = ''
}
async function initOnboarding() {
  if (onboardingDismissed()) return
  const s = await fetchOnboardingStatus()
  if (!s || !s.needsOnboarding) return
  renderOnboarding(s)
}
async function refreshOnboarding() {
  const s = await fetchOnboardingStatus()
  if (s) renderOnboarding(s)
}
function renderOnboarding(s) {
  if (onboardingDismissed()) return
  const overlay = document.getElementById('onboardingOverlay')
  if (!overlay) return
  const step = onboardingCurrentStep(s)
  if (step === 0) { overlay.classList.remove('active'); overlay.hidden = true; document.body.style.overflow = ''; return }
  overlay.hidden = false
  overlay.classList.add('active')
  document.body.style.overflow = 'hidden'
  document.querySelectorAll('#onboardingSteps .onboarding-step').forEach((el) => {
    const n = Number(el.dataset.ostep)
    el.classList.toggle('active', n === step)
    el.classList.toggle('done', n < step)
  })
  // The steps build on each other and the system only comes alive at the end
  // of step 4 -- say so, or a fresh installer reads step 2's "saved" as "done"
  // and every later "bot token not found" as a failure (BK bootcamp, 07-28).
  const flowNote = document.getElementById('onbFlowNote')
  if (flowNote) flowNote.textContent = step === 4 ? t('onboarding.flow_note_last') : t('onboarding.flow_note')
  const body = document.getElementById('onboardingBody')
  if (step === 1) body.innerHTML = onbIdentityHtml(s)
  else if (step === 2) body.innerHTML = onbStep1Html(s)
  else if (step === 3) body.innerHTML = onbStep2Html()
  else body.innerHTML = onbStep3Html(s)
  wireOnboarding(step)
}
function onbMsg(text, isErr) {
  const el = document.getElementById('onbMsg')
  if (el) { el.textContent = text; el.className = 'onb-msg' + (isErr ? ' err' : ' ok') }
}
function onbIdentityHtml(s) {
  return `<p>${escapeHtml(t('onboarding.identity.desc'))}</p>`
    + `<label class="form-label-sm">${escapeHtml(t('onboarding.identity.agent_label'))}</label>`
    + `<input id="onbAgentName" type="text" class="onb-input" maxlength="40" value="${escapeHtml(s.currentAgentName || '')}" autocomplete="off">`
    + `<label class="form-label-sm">${escapeHtml(t('onboarding.identity.owner_label'))}</label>`
    + `<input id="onbOwnerName" type="text" class="onb-input" maxlength="60" value="${escapeHtml(s.currentOwnerName || '')}" autocomplete="off">`
    + `<div class="onb-hint">${escapeHtml(t('onboarding.identity.hint'))}</div>`
    + `<button class="btn-primary btn-compact" id="onbIdentityBtn">${escapeHtml(t('onboarding.identity.save_btn'))}</button>`
    + `<div id="onbMsg" class="onb-msg"></div>`
}
function onbStep1Html(s) {
  return `<p>${escapeHtml(t('onboarding.step1.desc'))}</p>`
    + (s.claudeAuthPresent
      ? `<p class="onb-ok-line">${escapeHtml(t('onboarding.step1.auth_done'))}</p>`
      : `<label class="form-label-sm">${escapeHtml(t('onboarding.step1.token_label'))}</label>`
        + `<input id="onbToken" type="password" class="onb-input" placeholder="sk-ant-oat01-..." autocomplete="off">`
        + `<div class="onb-hint">${escapeHtml(t('onboarding.step1.token_hint'))}</div>`
        + `<button class="btn-primary btn-compact" id="onbAuthBtn">${escapeHtml(t('onboarding.step1.save_btn'))}</button>`)
    + (s.claudeAuthPresent && !s.agentsRunning
      ? `<button class="btn-primary btn-compact" id="onbLaunchBtn">${escapeHtml(t('onboarding.step1.launch_btn'))}</button>`
      : '')
    + `<div id="onbMsg" class="onb-msg"></div>`
}
function onbStep2Html() {
  return `<p>${escapeHtml(t('onboarding.step2.desc'))}</p>`
    + `<label class="form-label-sm">${escapeHtml(t('onboarding.step2.token_label'))}</label>`
    + `<input id="onbBotToken" type="password" class="onb-input" placeholder="123456:ABC..." autocomplete="off">`
    + `<div class="onb-hint">${escapeHtml(t('onboarding.step2.token_hint'))}</div>`
    + `<button class="btn-primary btn-compact" id="onbBotBtn">${escapeHtml(t('onboarding.step2.save_btn'))}</button>`
    + `<div id="onbMsg" class="onb-msg"></div>`
}
function onbStep3Html(s) {
  // Pairing needs the channels session up (the wizard restarted it after the
  // bot-token save) -- show its state so a not-yet-up service reads as
  // "starting", not as the user's failure.
  const svcLine = s && s.agentsRunning
    ? `<p class="onb-ok-line">${escapeHtml(t('onboarding.step3.svc_up'))}</p>`
    : `<p class="onb-hint">${escapeHtml(t('onboarding.step3.svc_starting'))}</p>`
  return `<p>${escapeHtml(t('onboarding.step3.desc'))}</p>`
    + svcLine
    + `<ol class="onb-list"><li>${escapeHtml(t('onboarding.step3.li1'))}</li><li>${escapeHtml(t('onboarding.step3.li2'))}</li></ol>`
    + `<div id="onbPending" class="onb-pending"></div>`
    + `<button class="btn-secondary btn-compact" id="onbRefreshBtn">${escapeHtml(t('onboarding.step3.refresh_btn'))}</button>`
    + `<div id="onbMsg" class="onb-msg"></div>`
}
function wireOnboarding(step) {
  if (step === 1) {
    const idBtn = document.getElementById('onbIdentityBtn')
    if (idBtn) idBtn.addEventListener('click', async () => {
      const agentName = (document.getElementById('onbAgentName').value || '').trim()
      const ownerName = (document.getElementById('onbOwnerName').value || '').trim()
      if (!agentName || !ownerName) { onbMsg(t('onboarding.identity.empty'), true); return }
      idBtn.disabled = true; onbMsg(t('onboarding.saving'))
      try {
        const res = await fetch('/api/onboarding/identity', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentName, ownerName }) })
        const d = await res.json().catch(() => ({}))
        if (!res.ok) { idBtn.disabled = false; onbMsg(d.error || t('onboarding.error'), true); return }
        // The name is live in the .env now -- repaint the chrome from
        // /api/marveen so the sidebar/title reflect it immediately, and
        // surface the automatic channels restart (same pattern as the
        // claude-auth step) instead of silently advancing.
        if (typeof initSidebarBrand === 'function') initSidebarBrand()
        if (d.restartError) { idBtn.disabled = false; onbMsg(t('onboarding.identity.saved_restart_failed'), true); setTimeout(refreshOnboarding, 6000); return }
        if (d.restarted) { onbMsg(t('onboarding.identity.saved_restarted')); setTimeout(refreshOnboarding, 2500); return }
        if (d.restartNeeded) { onbMsg(t('onboarding.identity.saved_restart_needed')); await refreshOnboarding(); return }
        onbMsg(t('onboarding.identity.saved'))
        await refreshOnboarding()
      } catch (e) { idBtn.disabled = false; onbMsg((e && e.message) || t('onboarding.error'), true) }
    })
    return
  }
  if (step === 2) {
    const authBtn = document.getElementById('onbAuthBtn')
    if (authBtn) authBtn.addEventListener('click', async () => {
      const token = (document.getElementById('onbToken').value || '').trim()
      if (!token) { onbMsg(t('onboarding.step1.token_empty'), true); return }
      authBtn.disabled = true; onbMsg(t('onboarding.saving'))
      try {
        const res = await fetch('/api/onboarding/claude-auth', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ token }) })
        const d = await res.json().catch(() => ({}))
        if (!res.ok) { authBtn.disabled = false; onbMsg(d.error || t('onboarding.error'), true); return }
        // Fresh-install path: the server restarts the (previously
        // unauthenticated) channels session right after the first auth save --
        // surface that, and on failure show the manual restart step instead of
        // silently advancing.
        if (d.restartError) { authBtn.disabled = false; onbMsg(t('onboarding.step1.saved_restart_failed'), true); setTimeout(refreshOnboarding, 6000); return }
        if (d.restarted) { onbMsg(t('onboarding.step1.saved_restarted')); setTimeout(refreshOnboarding, 2500); return }
        onbMsg(d.verified ? t('onboarding.step1.saved_verified') : t('onboarding.step1.saved_unverified'))
        await refreshOnboarding()
      } catch (e) { authBtn.disabled = false; onbMsg((e && e.message) || t('onboarding.error'), true) }
    })
    const launchBtn = document.getElementById('onbLaunchBtn')
    if (launchBtn) launchBtn.addEventListener('click', async () => {
      launchBtn.disabled = true; onbMsg(t('onboarding.step1.launching'))
      try {
        const res = await fetch('/api/onboarding/launch', { method: 'POST' })
        const d = await res.json().catch(() => ({}))
        if (!res.ok) { launchBtn.disabled = false; onbMsg(d.error || t('onboarding.error'), true); return }
        onbMsg(t('onboarding.step1.launched'))
        // On a fresh install the session is CREATED here (ONBTMUX1) and takes a
        // ~minute cold start via channels.sh. Poll until it is up so the wizard
        // advances on its own instead of stranding the user on step 2 after a
        // single 2.5s re-check. Bounded so a genuinely failed start still hands
        // control back rather than spinning forever.
        let up = false
        for (let i = 0; i < 40 && !up; i++) {  // ~40 x 3s = 2 min
          await new Promise((r) => setTimeout(r, 3000))
          const st = await fetchOnboardingStatus()
          if (st && st.agentsRunning) { up = true; break }
        }
        if (up) { await refreshOnboarding() }
        // Timeout is NOT success: on a slow machine the cold start can outlast
        // the 2-min bound while still being healthy, so the message must say
        // "still starting, check back / refresh" -- repeating the launched
        // message here would also mask a genuinely dead start (PR #779 review).
        else { launchBtn.disabled = false; onbMsg(t('onboarding.step1.launch_slow'), true) }
      } catch (e) { launchBtn.disabled = false; onbMsg((e && e.message) || t('onboarding.error'), true) }
    })
  } else if (step === 3) {
    const botBtn = document.getElementById('onbBotBtn')
    if (botBtn) botBtn.addEventListener('click', async () => {
      const botToken = (document.getElementById('onbBotToken').value || '').trim()
      if (!botToken) { onbMsg(t('onboarding.step2.token_empty'), true); return }
      botBtn.disabled = true; onbMsg(t('onboarding.saving'))
      try {
        const res = await fetch(`/api/agents/${encodeURIComponent(mainAgentId())}/channels/telegram`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ botToken }) })
        const d = await res.json().catch(() => ({}))
        if (!res.ok) { botBtn.disabled = false; onbMsg(d.error || t('onboarding.error'), true); return }
        // The server restarts the channels session so the new bot token goes
        // live -- say so, and give the respawn a beat before advancing so the
        // pairing step starts against the restarted service.
        onbMsg(d.restarted ? t('onboarding.step2.saved_restarted') : t('onboarding.step2.saved'))
        setTimeout(refreshOnboarding, d.restarted ? 4000 : 2000)
      } catch (e) { botBtn.disabled = false; onbMsg((e && e.message) || t('onboarding.error'), true) }
    })
  } else if (step === 4) {
    const refreshBtn = document.getElementById('onbRefreshBtn')
    // One sink for both failure paths. The box alone was not enough: it renders
    // in the same muted onb-hint slot as "no pending", so the very distinction
    // this fix is about -- "nobody is waiting" vs "I could not ask" -- stayed
    // invisible. onbMsg is the error channel this function already uses for the
    // approve step a few lines below.
    const showPendingError = (msg) => {
      const box = document.getElementById('onbPending')
      if (box) box.innerHTML = `<span class="onb-hint">${escapeHtml(msg)}</span>`
      onbMsg(msg, true)
    }
    const loadPending = async () => {
      try {
        // Same boot race the Messages page already guards against (see
        // ensureMarveenLoaded): until /api/marveen resolves window._marveen,
        // mainAgentId() returns the literal 'marveen' fallback. On a renamed
        // install that is not the main agent, so the backend takes the
        // sub-agent branch, finds no such agent dir and answers 404 -- and the
        // wizard rendered that as "no pending pairing" while the Channel view,
        // which uses the selected agent, listed the very same request.
        await ensureMarveenLoaded()
        const res = await fetch(`/api/agents/${encodeURIComponent(mainAgentId())}/channels/telegram/pending`)
        // Surface the failure instead of rendering it as an empty list. This is
        // a separate defect from the id race: without it a 404 or an auth error
        // reads as "nobody is waiting for approval", which is the one answer the
        // user cannot act on. A NETWORK failure does not land here at all -- the
        // fetch rejects -- so the outer catch carries the same message; see the
        // end of this function. The two together are what make the comment true.
        if (!res.ok) {
          const d = await res.json().catch(() => ({}))
          showPendingError(d.error || t('onboarding.error'))
          return
        }
        const p = await res.json()
        // Backend contract: [{code, senderId, chatId, createdAt, expiresAt}].
        // `code` is the approve key (the same code the bot sent the user) --
        // POSTing anything else gets a 400 and the pairing never completes.
        const now = Date.now()
        const list = (Array.isArray(p) ? p : (p.pending || [])).filter((x) => x && x.code && (!x.expiresAt || x.expiresAt > now))
        const box = document.getElementById('onbPending')
        if (!box) return
        if (!list.length) { box.innerHTML = `<span class="onb-hint">${escapeHtml(t('onboarding.step3.no_pending'))}</span>`; return }
        box.innerHTML = list.map((x) => {
          const code = escapeHtml(String(x.code))
          const label = escapeHtml(String(x.senderId || x.chatId || '?')) + ' · ' + code
          return `<div class="onb-pending-row"><span>${label}</span><button class="btn-primary btn-compact onb-approve" data-code="${code}">${escapeHtml(t('onboarding.step3.approve_btn'))}</button></div>`
        }).join('')
        box.querySelectorAll('.onb-approve').forEach((b) => b.addEventListener('click', async () => {
          b.disabled = true
          try {
            const res = await fetch(`/api/agents/${encodeURIComponent(mainAgentId())}/channels/telegram/approve`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ code: b.dataset.code }) })
            const d = await res.json().catch(() => ({}))
            if (!res.ok) { b.disabled = false; onbMsg(d.error || t('onboarding.error'), true); return }
            onbMsg(t('onboarding.step3.approved'))
            setTimeout(refreshOnboarding, 1500)
          } catch (e) { b.disabled = false; onbMsg((e && e.message) || t('onboarding.error'), true) }
        }))
      } catch (e) {
        // Network-level failure: the fetch rejected, so the !res.ok branch never
        // ran. Without this the box stays empty and the user reads it as "nobody
        // is waiting" -- the exact defect this change is about.
        showPendingError((e && e.message) || t('onboarding.error'))
      }
    }
    if (refreshBtn) refreshBtn.addEventListener('click', () => { refreshOnboarding() })
    loadPending()
  }
}

