// === Mobile login (QR of the ?token= bootstrap URL) ===
// The desktop is already authenticated, so the token lives in localStorage.
// We render it as a QR purely client-side and show it in a modal; the phone
// scans it and stores the token locally. The token never travels through chat.
(function setupMobileLogin() {
  const btn = document.getElementById('mobileLoginBtn')
  const overlay = document.getElementById('mobileLoginOverlay')
  if (!btn || !overlay) return
  const qrBox = document.getElementById('mobileLoginQr')
  const closeBtn = document.getElementById('mobileLoginClose')

  async function render() {
    const token = localStorage.getItem('marveen-dashboard-token')
    if (!token) {
      qrBox.innerHTML = `<p class="muted">${t('mobile_login.no_token')}</p>`
      return
    }
    if (typeof qrcode !== 'function') {
      qrBox.innerHTML = `<p class="muted">${t('mobile_login.cdn_error')}</p>`
      return
    }
    // The QR must encode a URL the phone can reach. If the desktop opened the
    // dashboard on localhost/127.0.0.1, window.location.origin would put
    // "localhost" in the QR and the phone would hit its OWN localhost. In that
    // case ask the server for its LAN IP and build the QR from that. If the
    // dashboard is already open on a LAN IP or a tunnel host, the origin works
    // as-is.
    let base = window.location.origin
    const host = window.location.hostname
    if (host === 'localhost' || host === '127.0.0.1') {
      qrBox.innerHTML = `<p class="muted">${t('mobile_login.generating')}</p>`
      try {
        const r = await fetch('/api/network-info', { headers: { 'Authorization': 'Bearer ' + token } })
        const info = r.ok ? await r.json() : {}
        // Prefer the Tailscale serve URL when one is configured -- under WSL2,
        // the LAN-IP guess below picks up the WSL-internal NAT adapter, not
        // the Windows host's real WiFi IP, so a phone on the same WiFi can
        // never reach it (Boss, 2026-08-05: QR scan just hung forever). The
        // Tailscale URL is the server's OWN confirmation that it's actually
        // reachable, not a guess.
        if (info.tailscale_url) {
          base = info.tailscale_url.replace(/\/$/, '')
        } else if (info.lan_ip) {
          base = 'http://' + info.lan_ip + ':' + (info.port || window.location.port || '3420')
        } else {
          qrBox.innerHTML = `<p class="mobile-login-warn">${t('mobile_login.localhost_warn')}</p>`
          return
        }
      } catch (e) {
        qrBox.innerHTML = `<p class="mobile-login-warn">${t('mobile_login.lan_error')}</p>`
        return
      }
    }
    const url = base + '/?token=' + token
    try {
      const qr = qrcode(0, 'M') // typeNumber 0 = auto-fit, ECC level M
      qr.addData(url)
      qr.make()
      qrBox.innerHTML = qr.createSvgTag({ cellSize: 6, margin: 4, scalable: true })
    } catch (e) {
      qrBox.innerHTML = `<p class="muted">${t('mobile_login.qr_error', { msg: escapeHtml(String(e && e.message || e)) })}</p>`
    }
  }

  btn.addEventListener('click', () => { render(); openModal(overlay) })
  if (closeBtn) closeBtn.addEventListener('click', () => closeModal(overlay))
  overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModal(overlay) })
})()

// === Archivalt kartyak ===
;(() => {
  let archivedInit = false

  const STATUS_LABELS = {
    planned:     () => t('kanban.status.planned'),
    in_progress: () => t('kanban.status.in_progress'),
    waiting:     () => t('kanban.status.waiting'),
    done:        () => t('kanban.status.done')
  }
  const STATUS_COLORS = { planned: '#6b7280', in_progress: '#3b82f6', waiting: '#f59e0b', done: '#10b981' }
  const PRIORITY_LABELS = {
    low:    () => t('kanban.priority.low'),
    normal: () => t('kanban.priority.normal'),
    high:   () => t('kanban.priority.high'),
    urgent: () => t('kanban.priority.urgent')
  }
  const PRIORITY_COLORS = { low: '#9ca3af', normal: '#6b7280', high: '#f59e0b', urgent: '#ef4444' }

  function fmtDate(unix) {
    if (!unix) return ''
    return new Date(unix * 1000).toLocaleString('hu-HU', { dateStyle: 'short', timeStyle: 'short' })
  }

  // Render an archived card with the same visual language as the live board:
  // project pill + #seq title + colored rounded priority/label chips, wrapped in
  // the .kanban-card frame. The whole card opens a read-only detail modal on
  // click; the restore button stops propagation so it doesn't also open it.
  function renderArchivedCard(card) {
    const prioColor = PRIORITY_COLORS[card.priority] || '#6b7280'
    const prioLabel = PRIORITY_LABELS[card.priority]?.() ?? card.priority
    const seqHtml = card.seq != null
      ? `<span class="kanban-card-seq" style="font-family:monospace;font-size:11px;color:var(--text-muted);margin-right:5px">#${card.seq}</span>`
      : ''
    const projectHtml = card.project
      ? `<span class="kanban-card-project">${esc(card.project)}</span>`
      : ''
    let labelsHtml = ''
    if (Array.isArray(card.labels) && card.labels.length > 0) {
      const pills = card.labels
        .map(l => `<span class="kanban-card-label-pill" style="--label-color:${esc(l.color)}">#${esc(l.name)}</span>`)
        .join('')
      labelsHtml = `<div class="kanban-card-labels">${pills}</div>`
    }
    const prioPill = `<span class="archived-prio-pill" style="--prio-color:${prioColor}">${prioLabel}</span>`
    return `<div class="kanban-card archived-card" data-id="${esc(card.id)}" data-priority="${esc(card.priority)}">
      ${projectHtml}
      <div class="kanban-card-title">${seqHtml}${esc(card.title)}</div>
      <div class="kanban-card-footer">${prioPill}</div>
      ${labelsHtml}
      <div class="archived-card-foot">
        <span class="archived-date">${t('archived.label.archived_at', {date: fmtDate(card.archived_at)})}</span>
        <button class="btn-secondary btn-compact archived-restore-btn" data-id="${esc(card.id)}" title="${t('archived.btn.restore_to_board')}" style="white-space:nowrap;flex-shrink:0;">${t('archived.btn.restore')}</button>
      </div>
    </div>`
  }

  // Read-only detail modal for an archived card: meta grid, labels, description,
  // comments -- no editing affordances. Restore button mirrors the card button.
  // Exposed so a #<id> reference elsewhere in the app can open an archived
  // card too (see _openArchivedCardById).
  window._showArchivedDetail = (card) => showArchivedDetail(card)
  async function showArchivedDetail(card) {
    const seqPrefix = card.seq != null ? `#${card.seq} ` : ''
    document.getElementById('archivedDetailTitle').innerHTML = linkifyKanbanRefs(`${seqPrefix}${card.title}`)
    const meta = document.getElementById('archivedDetailMeta')
    const idLabel = (card.seq != null ? `#${card.seq} · ` : '') + card.id
    meta.innerHTML = `
      <div class="meta-item"><span class="meta-label">${t('kanban.meta.id')}</span><span class="meta-value" style="font-family:monospace">${esc(idLabel)}</span></div>
      <div class="meta-item"><span class="meta-label">${t('kanban.meta.status')}</span><span class="meta-value">${STATUS_LABELS[card.status]?.() ?? card.status}</span></div>
      <div class="meta-item"><span class="meta-label">${t('kanban.meta.assignee')}</span><span class="meta-value">${card.assignee ? esc(card.assignee) : t('kanban.meta.none')}</span></div>
      <div class="meta-item"><span class="meta-label">${t('kanban.meta.priority')}</span><span class="meta-value">${PRIORITY_LABELS[card.priority]?.() ?? card.priority}</span></div>
      <div class="meta-item"><span class="meta-label">${t('kanban.meta.project')}</span><span class="meta-value">${card.project ? esc(card.project) : t('kanban.meta.none')}</span></div>
      <div class="meta-item"><span class="meta-label">${t('archived.meta.archived_at')}</span><span class="meta-value">${fmtDate(card.archived_at)}</span></div>
    `
    const labelsWrap = document.getElementById('archivedDetailLabelsWrap')
    const labelsBox = document.getElementById('archivedDetailLabels')
    if (Array.isArray(card.labels) && card.labels.length > 0) {
      labelsBox.innerHTML = card.labels
        .map(l => `<span class="kanban-card-label-pill" style="--label-color:${esc(l.color)}">#${esc(l.name)}</span>`)
        .join('')
      labelsWrap.style.display = ''
    } else {
      labelsWrap.style.display = 'none'
    }
    document.getElementById('archivedDetailDesc').innerHTML = linkifyKanbanRefs(card.description || '')

    const commentsWrap = document.getElementById('archivedDetailCommentsWrap')
    const commentsBox = document.getElementById('archivedDetailComments')
    commentsBox.innerHTML = ''
    try {
      const res = await fetch(`/api/kanban/${encodeURIComponent(card.id)}/comments`)
      const comments = res.ok ? await res.json() : []
      if (Array.isArray(comments) && comments.length > 0) {
        for (const c of comments) {
          const date = new Date(c.created_at * 1000).toLocaleString('hu-HU')
          const div = document.createElement('div')
          div.className = 'comment-item'
          div.innerHTML = `<div><span class="comment-author">${esc(c.author)}</span><span class="comment-date">${date}</span></div><div class="comment-body">${linkifyKanbanRefs(c.content)}</div>`
          commentsBox.appendChild(div)
        }
        commentsWrap.style.display = ''
      } else {
        commentsWrap.style.display = 'none'
      }
    } catch { commentsWrap.style.display = 'none' }

    const restoreBtn = document.getElementById('archivedDetailRestoreBtn')
    restoreBtn.disabled = false
    restoreBtn.textContent = t('archived.btn.restore_to_board')
    restoreBtn.onclick = async () => {
      restoreBtn.disabled = true
      restoreBtn.textContent = t('archived.btn.restoring')
      try {
        const resp = await fetch(`/api/kanban/${encodeURIComponent(card.id)}/unarchive`, { method: 'POST' })
        if (resp.ok) {
          closeModal(document.getElementById('archivedDetailOverlay'))
          doArchivedSearch()
        } else {
          restoreBtn.disabled = false
          restoreBtn.textContent = t('archived.btn.restore_to_board')
          showToast(t('archived.restore_error'))
        }
      } catch {
        restoreBtn.disabled = false
        restoreBtn.textContent = t('archived.btn.restore_to_board')
      }
    }
    openModal(document.getElementById('archivedDetailOverlay'))
  }

  async function populateArchivedProjects() {
    try {
      const r = await fetch('/api/kanban-projects')
      if (!r.ok) return
      const projects = await r.json()
      const sel = document.getElementById('archivedProject')
      const cur = sel.value
      sel.innerHTML = '<option value="">' + t('archived.filter.all_projects') + '</option>'
      for (const p of projects) {
        const opt = document.createElement('option')
        opt.value = p
        opt.textContent = p
        if (p === cur) opt.selected = true
        sel.appendChild(opt)
      }
    } catch { /* best-effort */ }
  }

  async function doArchivedSearch() {
    const list = document.getElementById('archivedList')
    const summary = document.getElementById('archivedSummary')
    list.className = ''
    list.innerHTML = '<p class="naplo-empty">' + t('common.loading') + '</p>'
    summary.textContent = ''

    const params = new URLSearchParams()
    const q = document.getElementById('archivedQ').value.trim()
    const project = document.getElementById('archivedProject').value
    const from = document.getElementById('archivedFrom').value
    const to = document.getElementById('archivedTo').value
    if (q) params.set('q', q)
    if (project) params.set('project', project)
    if (from) params.set('from', Math.floor(new Date(from).getTime() / 1000))
    if (to) params.set('to', Math.floor(new Date(to + 'T23:59:59').getTime() / 1000))

    try {
      const r = await fetch('/api/kanban/archived?' + params.toString())
      if (!r.ok) { list.innerHTML = '<p class="naplo-empty error">' + t('archived.error.http', {status: r.status}) + '</p>'; return }
      const data = await r.json()
      const cards = data.cards || []
      summary.textContent = t('archived.summary', {count: cards.length, limit: data.limit})
      if (cards.length === 0) { list.innerHTML = '<p class="naplo-empty">' + t('archived.empty') + '</p>'; return }
      list.className = 'archived-grid'
      list.innerHTML = cards.map(renderArchivedCard).join('')
      const byId = new Map(cards.map(c => [c.id, c]))
      // Whole card opens the read-only detail; restore button acts on its own.
      list.querySelectorAll('.archived-card').forEach(el => {
        el.addEventListener('click', () => {
          const card = byId.get(el.dataset.id)
          if (card) showArchivedDetail(card)
        })
      })
      list.querySelectorAll('.archived-restore-btn').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation()
          const id = btn.dataset.id
          btn.disabled = true
          btn.textContent = '...'
          try {
            const resp = await fetch(`/api/kanban/${id}/unarchive`, { method: 'POST' })
            if (resp.ok) {
              const cardEl = btn.closest('.archived-card')
              if (cardEl) cardEl.style.opacity = '0.4'
              btn.textContent = t('archived.btn.restored')
            } else {
              btn.disabled = false
              btn.textContent = t('archived.btn.restore')
              showToast(t('archived.restore_error'))
            }
          } catch {
            btn.disabled = false
            btn.textContent = t('archived.btn.restore')
          }
        })
      })
    } catch (err) {
      list.innerHTML = '<p class="naplo-empty error">' + t('common.error_network', {msg: err.message}) + '</p>'
    }
  }

  function loadArchivedPage() {
    if (!archivedInit) {
      archivedInit = true
      document.getElementById('archivedSearchBtn').addEventListener('click', doArchivedSearch)
      document.getElementById('archivedRefreshBtn').addEventListener('click', doArchivedSearch)
      document.getElementById('archivedQ').addEventListener('keydown', e => { if (e.key === 'Enter') doArchivedSearch() })
      // Back button mirrors the kanban row's Archivaltak entry point; explicit
      // switchPage (not history.back) so it works on direct-link arrivals too.
      const backBtn = document.getElementById('archivedBackToKanban')
      if (backBtn) backBtn.addEventListener('click', () => switchPage('kanban'))
      const adOverlay = document.getElementById('archivedDetailOverlay')
      document.getElementById('archivedDetailClose').addEventListener('click', () => closeModal(adOverlay))
      adOverlay.addEventListener('click', e => { if (e.target === adOverlay) closeModal(adOverlay) })
    }
    populateArchivedProjects()
    doArchivedSearch()
  }

  window.loadArchivedPage = loadArchivedPage
})()

// === Naplo (Audit Timeline) ===
;(() => {
  let naploInitialized = false
  let naploActiveSource = ''

  const SOURCE_LABELS = { config: () => t('naplo.source.config'), idea: () => t('naplo.source.idea'), store: () => t('naplo.source.store'), diary: () => t('naplo.source.diary') }
  const SOURCE_COLORS = { config: '#3b82f6', idea: '#10b981', store: '#f59e0b', diary: '#8b5cf6' }
  const DIARY_ENTRY_LABELS = { log: () => t('naplo.diary.log_badge'), memory: () => t('naplo.diary.memory_badge') }
  const DIARY_ENTRY_COLORS = { log: '#6b7280', memory: '#a78bfa' }

  function fmtTs(unix) {
    return new Date(unix * 1000).toLocaleString('hu-HU', { dateStyle: 'short', timeStyle: 'short' })
  }

  function renderEntry(e) {
    const sourceColor = SOURCE_COLORS[e.source] || '#6b7280'
    const sourceLabelRaw = SOURCE_LABELS[e.source]; const sourceLabel = sourceLabelRaw ? (typeof sourceLabelRaw === 'function' ? sourceLabelRaw() : sourceLabelRaw) : e.source
    const badge = `<span class="naplo-badge" style="background:${sourceColor}">${sourceLabel}</span>`
    const ts = `<span class="naplo-ts">${fmtTs(e.created_at)}</span>`
    let detail = ''
    if (e.source === 'config') {
      const oldV = e.old_value != null ? `<code>${esc(e.old_value)}</code>` : '<em>nincs</em>'
      const newV = e.new_value != null ? `<code>${esc(e.new_value)}</code>` : '<em>nincs</em>'
      detail = `<strong>${esc(e.key)}</strong> ${oldV} &rarr; ${newV} <span class="naplo-actor">${esc(e.actor || '')}</span>`
    } else if (e.source === 'idea') {
      const from = e.from_status ? `<code>${esc(e.from_status)}</code> &rarr; ` : ''
      detail = `<strong>${esc(e.idea_id)}</strong> ${from}<code>${esc(e.to_status)}</code>`
      if (e.note) detail += ` <span class="naplo-note">${esc(e.note)}</span>`
      if (e.actor) detail += ` <span class="naplo-actor">${esc(e.actor)}</span>`
    } else if (e.source === 'store') {
      const sizeStr = e.file_size != null ? ` (${(e.file_size / 1024).toFixed(1)} KB)` : ''
      const agentStr = e.agent ? ` <span class="naplo-actor">${esc(e.agent)}</span>` : ''
      const sens = e.is_sensitive ? ` <span class="naplo-sensitive">${t('naplo.entry.sensitive')}</span>` : ''
      detail = `<code>${esc(e.rel_path)}</code> <span class="naplo-event-type">${esc(e.event_type)}</span>${sizeStr}${agentStr}${sens}`
    } else if (e.source === 'diary') {
      const entryColor = DIARY_ENTRY_COLORS[e.entry_type] || '#6b7280'
      const entryLabelRaw = DIARY_ENTRY_LABELS[e.entry_type]; const entryLabel = entryLabelRaw ? (typeof entryLabelRaw === 'function' ? entryLabelRaw() : entryLabelRaw) : e.entry_type
      const entryBadge = `<span class="naplo-badge" style="background:${entryColor};font-size:10px">${entryLabel}</span>`
      const agentStr = e.agent_id ? ` <span class="naplo-actor">${esc(e.agent_id)}</span>` : ''
      // Slice the RAW text and escape after, via the reference linkifier: the
      // old order (escape, then slice at 200) could cut an HTML entity in half,
      // and it left card ids in diary entries unclickable.
      const rawContent = (e.content || '').replace(/\n/g, ' ')
      let contentSnippet = linkifyKanbanRefs(rawContent.slice(0, 200))
      if (rawContent.length > 200) contentSnippet += '…'
      const keywordsStr = e.keywords ? `<div class="naplo-note" style="margin-top:2px">Kulcsszavak: ${esc(e.keywords)}</div>` : ''
      const catStr = e.category ? ` <span class="naplo-event-type">${esc(e.category)}</span>` : ''
      detail = `${entryBadge}${catStr}${agentStr}<div class="naplo-diary-content">${contentSnippet}</div>${keywordsStr}`
    }
    return `<div class="naplo-entry"><div class="naplo-entry-meta">${ts}${badge}</div><div class="naplo-entry-detail">${detail}</div></div>`
  }

  async function doNaplo() {
    const timeline = document.getElementById('naplo-timeline')
    const summary = document.getElementById('naplo-summary')
    timeline.innerHTML = `<p class="naplo-empty">${t('naplo.loading')}</p>`
    summary.textContent = ''

    const params = new URLSearchParams()
    if (naploActiveSource) params.set('source', naploActiveSource)
    const from = document.getElementById('naplo-from').value
    const to = document.getElementById('naplo-to').value
    const q = document.getElementById('naplo-q').value.trim()
    const agentEl = document.getElementById('naplo-agent')
    const agentVal = agentEl ? agentEl.value.trim() : ''
    if (from) params.set('from', Math.floor(new Date(from).getTime() / 1000))
    if (to)   params.set('to', Math.floor(new Date(to + 'T23:59:59').getTime() / 1000))
    if (q)    params.set('q', q)
    if (agentVal) params.set('agent', agentVal)
    params.set('limit', '200')

    try {
      const res = await fetch('/api/audit-log?' + params.toString())
      if (!res.ok) { timeline.innerHTML = `<p class="naplo-empty error">Hiba: ${res.status}</p>`; return }
      const data = await res.json()
      const entries = data.entries || []
      summary.textContent = t('naplo.summary', { n: entries.length })
      if (entries.length === 0) { timeline.innerHTML = `<p class="naplo-empty">${t('naplo.empty')}</p>`; return }
      timeline.innerHTML = entries.map(renderEntry).join('')
    } catch (err) {
      timeline.innerHTML = `<p class="naplo-empty error">${t('naplo.error', { msg: err.message })}</p>`
    }
  }

  function loadNaplo() {
    if (!naploInitialized) {
      naploInitialized = true
      document.querySelectorAll('#naplo-source-tabs .naplo-tab').forEach((btn) => {
        btn.addEventListener('click', () => {
          document.querySelectorAll('#naplo-source-tabs .naplo-tab').forEach((b) => b.classList.remove('active'))
          btn.classList.add('active')
          naploActiveSource = btn.dataset.source
          const agentFilter = document.getElementById('naplo-agent-wrap')
          if (agentFilter) agentFilter.style.display = naploActiveSource === 'diary' ? '' : 'none'
          doNaplo()
        })
      })
      document.getElementById('naplo-search-btn').addEventListener('click', doNaplo)
      document.getElementById('naplo-q').addEventListener('keydown', (e) => { if (e.key === 'Enter') doNaplo() })
      document.getElementById('naplo-refresh-btn').addEventListener('click', doNaplo)
    }
    doNaplo()
  }

  window.loadNaplo = loadNaplo
})()

// === Kanban Gantt / timeline view ===
;(function () {
  // --- State ---
  let ganttPeriod = 'week'  // 'week' | 'month' | 'quarter'
  let ganttPeriodOffset = 0  // periods stepped from the current one (0 = current, -1 = prev, +1 = next)
  let ganttOverdueOnly = false
  let _initialized = false

  // --- Color map by status (vars from theme) ---
  const STATUS_COLOR = {
    planned:     { bg: 'var(--accent)',  border: 'var(--accent)' },
    in_progress: { bg: '#4f8ef7',        border: '#3a7be0' },
    waiting:     { bg: '#e8a838',        border: '#c88c20' },
    done:        { bg: '#3dbf79',        border: '#28a560' },
  }

  // Period window: returns { rangeStart: Date, rangeEnd: Date } (midnight boundaries)
  function periodWindow() {
    const now = new Date()
    const start = new Date(now)
    start.setHours(0, 0, 0, 0)
    const end = new Date(start)
    if (ganttPeriod === 'week') {
      // Mon..Sun of current week, shifted by ganttPeriodOffset weeks
      const dow = (start.getDay() + 6) % 7  // Mon=0
      start.setDate(start.getDate() - dow + ganttPeriodOffset * 7)
      end.setTime(start.getTime())
      end.setDate(start.getDate() + 7)
    } else if (ganttPeriod === 'month') {
      start.setDate(1)
      start.setMonth(start.getMonth() + ganttPeriodOffset)
      end.setFullYear(start.getFullYear(), start.getMonth() + 1, 1)
    } else {  // quarter
      const qStart = Math.floor(start.getMonth() / 3) * 3 + ganttPeriodOffset * 3
      start.setMonth(qStart, 1)
      end.setFullYear(start.getFullYear(), start.getMonth() + 3, 1)
    }
    return { rangeStart: start, rangeEnd: end }
  }

  // Format date as short label (e.g. "jún 15" / "Jun 15")
  function fmtDateShort(d) {
    return d.toLocaleDateString(typeof _lang !== 'undefined' && _lang === 'en' ? 'en-US' : 'hu-HU', { month: 'short', day: 'numeric' })
  }

  // Return header tick labels for the visible range
  function buildHeaderTicks(rangeStart, rangeEnd) {
    const ticks = []
    const totalMs = rangeEnd - rangeStart
    // Aim for ~5-8 ticks; snap to day boundaries
    let stepDays = 1
    if (ganttPeriod === 'month') stepDays = 7
    else if (ganttPeriod === 'quarter') stepDays = 14
    const cur = new Date(rangeStart)
    while (cur < rangeEnd) {
      ticks.push({
        date: new Date(cur),
        pct: (cur - rangeStart) / totalMs * 100,
      })
      cur.setDate(cur.getDate() + stepDays)
    }
    return ticks
  }

  // Group visible cards by project (or 'Nincs projekt' for null)
  function groupCardsByProject(cards) {
    const map = new Map()
    for (const c of cards) {
      const key = c.project || t('kanban.gantt.no_project')
      if (!map.has(key)) map.set(key, [])
      map.get(key).push(c)
    }
    return map
  }

  // Build and inject the Gantt DOM into #kanbanGanttView
  function renderGantt() {
    const container = document.getElementById('kanbanGanttView')
    if (!container) return
    container.innerHTML = ''

    const { rangeStart, rangeEnd } = periodWindow()
    const totalMs = rangeEnd - rangeStart
    const nowMs = Date.now()
    const todayPct = Math.max(0, Math.min(100, (nowMs - rangeStart) / totalMs * 100))

    // Filter: cards that have a due_date
    let cards = (Array.isArray(kanbanCards) ? kanbanCards : []).filter(c => c.due_date)

    if (ganttOverdueOnly) {
      // Keep cards that are overdue OR due within 7 days
      const cutoff = (nowMs + 7 * 86400000) / 1000
      cards = cards.filter(c => c.due_date <= cutoff / 1 && c.status !== 'done')
    }

    // Exclude cards whose entire bar lies outside the window
    cards = cards.filter(c => {
      const barStart = c.created_at ? c.created_at * 1000 : rangeStart.getTime()
      const barEnd   = c.due_date * 1000
      return barEnd >= rangeStart && barStart <= rangeEnd
    })

    if (cards.length === 0) {
      container.innerHTML = `<p style="color:var(--muted);padding:24px 0;text-align:center;">${t('kanban.gantt.no_cards')}</p>`
      return
    }

    const grouped = groupCardsByProject(cards)

    // --- Outer layout ---
    const wrap = document.createElement('div')
    wrap.className = 'gantt-wrap'
    wrap.style.cssText = 'display:flex;flex-direction:column;overflow:hidden;'

    // --- Header row: left label + tick strip ---
    const headerRow = document.createElement('div')
    headerRow.style.cssText = 'display:flex;border-bottom:1px solid var(--border);margin-bottom:4px;'

    const headerLabel = document.createElement('div')
    headerLabel.style.cssText = 'width:220px;min-width:220px;font-size:12px;color:var(--muted);padding:4px 8px;border-right:1px solid var(--border);'
    headerLabel.textContent = t('kanban.gantt.col_label')
    headerRow.appendChild(headerLabel)

    const headerTrack = document.createElement('div')
    headerTrack.style.cssText = 'flex:1;position:relative;height:28px;overflow:hidden;'
    const ticks = buildHeaderTicks(rangeStart, rangeEnd)
    for (const tick of ticks) {
      const el = document.createElement('div')
      el.style.cssText = `position:absolute;left:${tick.pct.toFixed(2)}%;transform:translateX(-50%);font-size:11px;color:var(--muted);top:6px;white-space:nowrap;`
      el.textContent = fmtDateShort(tick.date)
      headerTrack.appendChild(el)
    }
    // Today marker in header
    if (todayPct >= 0 && todayPct <= 100) {
      const todayHead = document.createElement('div')
      todayHead.style.cssText = `position:absolute;left:${todayPct.toFixed(2)}%;top:0;bottom:0;width:2px;background:var(--danger,#e05252);opacity:0.6;`
      headerTrack.appendChild(todayHead)
    }
    headerRow.appendChild(headerTrack)
    wrap.appendChild(headerRow)

    // --- Body rows ---
    const body = document.createElement('div')
    body.style.cssText = 'overflow-y:auto;max-height:70vh;'

    for (const [project, projCards] of grouped) {
      // Group header
      const groupHeader = document.createElement('div')
      groupHeader.style.cssText = 'display:flex;align-items:center;background:var(--bg2,var(--sidebar-bg));border-bottom:1px solid var(--border);'
      const ghLabel = document.createElement('div')
      ghLabel.style.cssText = 'width:220px;min-width:220px;font-size:12px;font-weight:600;color:var(--fg);padding:5px 8px;border-right:1px solid var(--border);'
      ghLabel.textContent = `${project} (${projCards.length})`
      groupHeader.appendChild(ghLabel)
      const ghStripe = document.createElement('div')
      ghStripe.style.cssText = 'flex:1;height:26px;background:var(--bg2,var(--sidebar-bg));'
      groupHeader.appendChild(ghStripe)
      body.appendChild(groupHeader)

      // Card rows
      for (const card of projCards) {
        const barStartMs = card.created_at ? card.created_at * 1000 : rangeStart.getTime()
        const barEndMs   = card.due_date * 1000
        const isOverdue  = card.status !== 'done' && barEndMs < nowMs

        // Clamp to window
        const clampedStart = Math.max(barStartMs, rangeStart.getTime())
        const clampedEnd   = Math.min(barEndMs,   rangeEnd.getTime())
        const leftPct  = (clampedStart - rangeStart) / totalMs * 100
        const widthPct = Math.max(0.5, (clampedEnd - clampedStart) / totalMs * 100)

        const col = isOverdue ? { bg: 'var(--danger,#e05252)', border: '#b83030' }
                              : (STATUS_COLOR[card.status] || STATUS_COLOR.planned)

        const row = document.createElement('div')
        row.style.cssText = 'display:flex;align-items:center;border-bottom:1px solid var(--border);min-height:32px;'

        const rowLabel = document.createElement('div')
        rowLabel.style.cssText = 'width:220px;min-width:220px;font-size:12px;color:var(--fg);padding:4px 8px;border-right:1px solid var(--border);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;cursor:pointer;'
        rowLabel.title = card.title
        // Show the running display number (#N, card.seq) like the board, not the hex id.
        const seqLabel = card.seq != null ? `#${card.seq}` : `#${card.id}`
        rowLabel.textContent = `${seqLabel} ${card.title}`
        rowLabel.addEventListener('click', () => { if (typeof openCardDetail === 'function') openCardDetail(card.id) })

        const rowTrack = document.createElement('div')
        rowTrack.style.cssText = 'flex:1;position:relative;height:32px;overflow:hidden;'

        // Today line (in each row)
        if (todayPct >= 0 && todayPct <= 100) {
          const tl = document.createElement('div')
          tl.style.cssText = `position:absolute;left:${todayPct.toFixed(2)}%;top:0;bottom:0;width:2px;background:var(--danger,#e05252);z-index:1;pointer-events:none;`
          rowTrack.appendChild(tl)
        }

        const bar = document.createElement('div')
        bar.style.cssText = [
          `position:absolute`,
          `left:${leftPct.toFixed(2)}%`,
          `width:${widthPct.toFixed(2)}%`,
          `top:5px`,
          `bottom:5px`,
          `background:${col.bg}`,
          `border:1px solid ${col.border}`,
          `border-radius:4px`,
          `overflow:hidden`,
          `white-space:nowrap`,
          `font-size:11px`,
          `color:#fff`,
          `display:flex`,
          `align-items:center`,
          `padding:0 6px`,
          `box-sizing:border-box`,
          `cursor:pointer`,
          `z-index:2`,
          isOverdue ? 'background-image:repeating-linear-gradient(45deg,rgba(0,0,0,.12) 0px,rgba(0,0,0,.12) 4px,transparent 4px,transparent 8px)' : '',
        ].filter(Boolean).join(';')
        bar.title = `${seqLabel} ${card.title}\n${fmtDateShort(new Date(barStartMs))} - ${fmtDateShort(new Date(barEndMs))}`
        bar.textContent = `${seqLabel} ${card.title}`
        bar.addEventListener('click', () => { if (typeof openCardDetail === 'function') openCardDetail(card.id) })
        rowTrack.appendChild(bar)
        row.appendChild(rowLabel)
        row.appendChild(rowTrack)
        body.appendChild(row)
      }
    }

    wrap.appendChild(body)

    // --- Legend ---
    const legend = document.createElement('div')
    legend.style.cssText = 'display:flex;align-items:center;gap:16px;margin-top:10px;font-size:12px;flex-wrap:wrap;'
    const legendItems = [
      { key: 'planned',     color: STATUS_COLOR.planned.bg },
      { key: 'in_progress', color: STATUS_COLOR.in_progress.bg },
      { key: 'waiting',     color: STATUS_COLOR.waiting.bg },
      { key: 'done',        color: STATUS_COLOR.done.bg },
      { key: 'overdue',     color: 'var(--danger,#e05252)' },
    ]
    for (const item of legendItems) {
      const dot = document.createElement('span')
      dot.innerHTML = `<span style="display:inline-block;width:12px;height:12px;border-radius:2px;background:${item.color};vertical-align:middle;margin-right:4px;"></span>${t('kanban.gantt.legend.' + item.key)}`
      legend.appendChild(dot)
    }
    const todayLegend = document.createElement('span')
    todayLegend.style.cssText = 'margin-left:auto;color:var(--muted);'
    todayLegend.innerHTML = `<span style="display:inline-block;width:12px;height:2px;background:var(--danger,#e05252);vertical-align:middle;margin-right:4px;"></span>${t('kanban.gantt.legend.today')}`
    legend.appendChild(todayLegend)
    wrap.appendChild(legend)

    container.appendChild(wrap)

    // --- Period stepper (below the timeline): step back/forward by one period unit ---
    const nav = document.createElement('div')
    nav.style.cssText = 'display:flex;align-items:center;justify-content:center;gap:10px;margin-top:12px;'
    const prevBtn = document.createElement('button')
    prevBtn.className = 'view-btn'
    prevBtn.style.cssText = 'width:auto;padding:0 14px;'
    prevBtn.textContent = '‹ ' + t('kanban.gantt.nav_prev')
    prevBtn.addEventListener('click', () => { ganttPeriodOffset--; renderGantt() })
    const rangeLbl = document.createElement('span')
    rangeLbl.style.cssText = 'font-size:12px;color:var(--muted);min-width:130px;text-align:center;'
    rangeLbl.textContent = `${fmtDateShort(rangeStart)} - ${fmtDateShort(new Date(rangeEnd.getTime() - 1))}`
    const nextBtn = document.createElement('button')
    nextBtn.className = 'view-btn'
    nextBtn.style.cssText = 'width:auto;padding:0 14px;'
    nextBtn.textContent = t('kanban.gantt.nav_next') + ' ›'
    nextBtn.addEventListener('click', () => { ganttPeriodOffset++; renderGantt() })
    nav.append(prevBtn, rangeLbl, nextBtn)
    container.appendChild(nav)
  }

  // --- View switcher init (called once after DOM ready) ---
  function initGanttViewSwitcher() {
    if (_initialized) return
    _initialized = true

    const boardBtn  = document.getElementById('kanbanViewBoard')
    const ganttBtn  = document.getElementById('kanbanViewGantt')
    const boardFilters = document.getElementById('kanbanBoardFilters')
    const ganttFilters = document.getElementById('kanbanGanttFilters')
    const boardEls  = [document.getElementById('kanbanBoard'), document.getElementById('kanbanSwimlaneBoard')]
    const ganttEl   = document.getElementById('kanbanGanttView')

    function activateBoard() {
      boardBtn.classList.add('active')
      ganttBtn.classList.remove('active')
      boardFilters.style.display = 'flex'
      ganttFilters.style.display = 'none'
      boardEls.forEach(el => { if (el) el.style.removeProperty('display') })
      ganttEl.style.display = 'none'
    }

    function activateGantt() {
      ganttBtn.classList.add('active')
      boardBtn.classList.remove('active')
      ganttFilters.style.display = 'flex'
      boardFilters.style.display = 'none'
      boardEls.forEach(el => { if (el) el.style.display = 'none' })
      ganttEl.style.display = 'block'
      renderGantt()
    }

    boardBtn.addEventListener('click', activateBoard)
    ganttBtn.addEventListener('click', activateGantt)

    // Archived button: navigates AWAY to the archived page (its sidebar entry
    // was removed -- this button is now the entry point). It never takes the
    // 'active' state here because leaving the kanban page hides the row.
    const archivedBtn = document.getElementById('kanbanViewArchived')
    if (archivedBtn) archivedBtn.addEventListener('click', () => switchPage('archived'))

    // Period buttons
    document.querySelectorAll('#kanbanGanttFilters [data-period]').forEach(btn => {
      btn.addEventListener('click', () => {
        ganttPeriod = btn.dataset.period
        ganttPeriodOffset = 0  // recenter on the current period when switching granularity
        document.querySelectorAll('#kanbanGanttFilters [data-period]').forEach(b => b.classList.remove('active'))
        btn.classList.add('active')
        renderGantt()
      })
    })

    // Overdue toggle
    const overdueChk = document.getElementById('ganttOverdueOnly')
    if (overdueChk) {
      overdueChk.addEventListener('change', () => {
        ganttOverdueOnly = overdueChk.checked
        renderGantt()
      })
    }

    // Re-render on data refresh (hook into global loadKanban completion)
    const _origRenderKanban = window.renderKanban
    if (typeof _origRenderKanban === 'function') {
      window.renderKanban = function () {
        _origRenderKanban.apply(this, arguments)
        if (ganttEl.style.display !== 'none') renderGantt()
      }
    }
  }

  window._initGanttViewSwitcher = initGanttViewSwitcher
  window.renderGantt = renderGantt
})()

// ============================ DEPO oldal ============================
//
// Ket dolgot csinal, amit a felhasznalo egyebkent csak parancssorbol tudna:
// atkoltoztet a depoba, es lehozza a Drive-mappait a gepre. Mindketto HOSSZU
// muvelet, ezert nem a gomb varja meg -- a szerver hatterben dolgozik, a lap
// pedig masodpercenkent megkerdezi, hol tart. Igy egy 8 GB-os koltoztetes
// kozben sem tunik ugy, mintha megallt volna a program.

// SZANDEKOSAN `var`, nem `let`: a switchPage() a fajl kozepen (routeFromHash)
// mar meghivja a _depoStopPoll()-t, mikozben ez a sor meg le sem futott. A
// `let` ilyenkor nem "undefined", hanem HIBAT dob ("Cannot access '_depoPoll'
// before initialization") -- es a hiba a Depo oldal betolteset a legelso soran
// megolte: egyetlen gomb sem kapott esemenykezelot. (Boss, 2026-08-15: "az
// iroda Depo alatti resz nem mukodik. gombok nem csinalnak semmit".) A `var`
// felkerul a fajl tetejere, ezert korai hivasnal is csak `undefined`.
var _depoPoll = null

function _depoStopPoll() {
  if (_depoPoll) { clearInterval(_depoPoll); _depoPoll = null }
}

async function _depoGet(url) {
  const res = await fetch(url)
  const data = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(data.message || data.error || ('hiba: ' + res.status))
  return data
}

async function _depoPost(url, body) {
  // Az Eletfa vegpontjai a valaszt a FELULET nyelven adjak vissza. Kozponti
  // hely, hogy egy uj hivas se felejtse el (a szoveg ket nyelven all a szerveren).
  if (url.indexOf('/api/life/') === 0 && url.indexOf('lang=') < 0) {
    url += (url.indexOf('?') < 0 ? '?' : '&') + 'lang=' + (window._lang || 'hu')
  }
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body || {}),
  })
  const data = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(data.error || data.message || ('hiba: ' + res.status))
  return data
}

function _depoBytes(n) {
  if (!n) return '0 B'
  const u = ['B', 'KB', 'MB', 'GB', 'TB']
  let i = 0
  let v = n
  while (v >= 1024 && i < u.length - 1) { v /= 1024; i++ }
  return v.toFixed(v >= 10 || i === 0 ? 0 : 1) + ' ' + u[i]
}

// ===========================================================================
// "Újraindítás most" gomb
//
// Boss: "Ujrainditas utan lep eletbe. sok helyen ez van. igen de a komuvesunk
// hogyan inditsa ujra es mit?" -- eddig a felulet kimondta a feltetelt, de nem
// adta hozza az eszkozt. Ez a ket fuggveny az eszkoz.
//
// Amit ujraindit: KIZAROLAG a vezerlopultot (a sajat szolgaltatasat). Az
// agensek munkamenetei ertintetlenek maradnak -- lasd a hosszu indoklast a
// src/self-restart.ts elejen.
//
// MELLETTE all a "Mindent ujraindit" (mountRestartAllButton lentebb), mert
// Boss 2026-08-16-an pontosan ezt kerte: "nem lenne sokal egyszerubb ha mindent
// ujrainditana ami letezik a marveen ban?". Az a gomb a sub-agenseket, a
// foagenst ES a vezerlopultot inditja ujra, ebben a sorrendben.
// ===========================================================================

/** Beteszi a gombot `host`-ba, ha ez a telepites egyaltalan tud ujraindulni. */
async function mountRestartButton(host, note) {
  if (!host) return
  host.innerHTML = ''
  let a = null
  try { a = await (await fetch('/api/system/restart')).json() } catch (e) { a = null }
  const wrap = document.createElement('div')
  wrap.style.cssText = 'margin-top:14px;padding-top:12px;border-top:1px solid var(--border)'
  if (!a || !a.possible) {
    // Nem hallgatunk rola: ha nem megy a gomb, MEGMONDJUK, mit csinaljon
    // helyette az ember -- egy eltunt gomb csak talalgatast szul.
    wrap.innerHTML = '<p class="subtitle" style="margin:0">'
      + escapeHtml(note || t('restart.note_default'))
      + ' ' + escapeHtml((a && a.reason) || t('restart.unavailable')) + '</p>'
    host.appendChild(wrap)
    // A vezerlopult nem tudja magat ujrainditani, de a TOBBIT meg igen: az
    // agensek ujrainditasa ettol fuggetlenul mukodik, es egy beallitas
    // tobbsegehez pont az kell. Ezert a "mindent" gomb itt is ott marad.
    mountRestartAllButton(wrap)
    return
  }
  wrap.innerHTML = '<p class="subtitle" style="margin:0 0 8px">'
    + escapeHtml(note || t('restart.note_default'))
    + ' ' + escapeHtml(t('restart.hint')) + '</p>'
    + '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
    + '<button class="btn-primary" data-restart-btn>' + escapeHtml(t('restart.btn')) + '</button>'
    + '<span class="subtitle" data-restart-status></span></div>'
  host.appendChild(wrap)
  const btn = wrap.querySelector('[data-restart-btn]')
  const status = wrap.querySelector('[data-restart-status]')
  btn.addEventListener('click', () => doSystemRestart(btn, status, a.startedAt))
  mountRestartAllButton(wrap)
}

// ===========================================================================
// "Mindent újraindít"
//
// Boss, 2026-08-16: "nem lenne sokal egyszerubb ha mindent ujrainditana ami
// letezik a marveen ban? az atyauristent is? ezzel meg lenne oldva a problema
// egyszeruen. nem?"
//
// De. A `restartTarget` szerinti celzott gomb tovabbra is ott van (az a
// gyorsabb es kevesbe romboló ut), de aki nem akar valasztani, annak itt van
// az EGY gomb. Ami mogotte tortenik: sub-agensek -> foagens -> vezerlopult,
// ebben a sorrendben (src/restart-all.ts).
//
// Az ara viszont valodi, ezert MEGKERDEZZUK: minden futo munka megszakad.
// A kerdes nem altalanossagban figyelmeztet, hanem MEGNEVEZI, ki dolgozik
// eppen -- kulonben a megerosites csak egy reflexbol elkattintott ablak.
// ===========================================================================

/** A "mindent ujraindit" gomb `wrap` ala. Sosem dobja el a hivo gombjat. */
function mountRestartAllButton(wrap) {
  if (!wrap) return
  const row = document.createElement('div')
  row.style.cssText = 'display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px'
  row.innerHTML = '<button class="btn-secondary" data-restart-all-btn>'
    + escapeHtml(t('restart.all_btn')) + '</button>'
    + '<span class="subtitle" data-restart-all-status></span>'
  const note = document.createElement('p')
  note.className = 'subtitle'
  note.style.cssText = 'margin:6px 0 0'
  note.textContent = t('restart.all_note', { bot: mainAgentDisplayName() })
  wrap.appendChild(row)
  wrap.appendChild(note)
  const btn = row.querySelector('[data-restart-all-btn]')
  const status = row.querySelector('[data-restart-all-status]')
  btn.addEventListener('click', () => doRestartAll(btn, status))
}

/**
 * A megerosito kerdes szovege a tervbol.
 *
 * Ket forrast fesulunk ossze: a kiszolgalo szigoru merese (biztosan futo
 * munka) es a felulet sajat 3 masodperces merese (Boss tagabb definicioja:
 * "ha barmit is csinal vagy futtat, akor is dolgozik"). Ha BARMELYIK azt
 * mondja, hogy dolgozik, akkor dolgozik -- egy megerosito kerdesnel a
 * pesszimista olvasat a helyes.
 */
function restartAllConfirmText(plan) {
  const steps = Array.isArray(plan && plan.steps) ? plan.steps : []
  const included = steps.filter((s) => s.included)
  const busy = included.filter((s) =>
    s.busy || lastActivityStateByName.get(s.id) === 'working')
  const skipped = steps.filter((s) => !s.included)
  const lines = [t('restart.all_confirm_head', { n: included.length })]
  if (busy.length) {
    lines.push('')
    lines.push(t('restart.all_confirm_busy', { names: busy.map((s) => s.label).join(', ') }))
  }
  if (skipped.length) {
    lines.push('')
    lines.push(t('restart.all_confirm_skipped', { names: skipped.map((s) => s.label).join(', ') }))
  }
  lines.push('')
  lines.push(t('restart.all_confirm_tail'))
  return lines.join('\n')
}

async function doRestartAll(btn, status) {
  const say = (s) => { if (status) status.textContent = s }
  btn.disabled = true
  say(t('restart.all_planning'))
  let plan = null
  try {
    const res = await fetch('/api/system/restart-all', { cache: 'no-store' })
    if (!res.ok) throw new Error('HTTP ' + res.status)
    plan = await res.json()
  } catch (e) {
    // Terv nelkul NEM inditunk el semmit: a megerosites ertelme pont az, hogy
    // a Boss lassa, mit szakit meg. Vaktaban ujrainditani rosszabb, mint nem.
    say(t('restart.all_plan_failed'))
    btn.disabled = false
    return
  }
  say('')
  if (!confirm(restartAllConfirmText(plan))) { btn.disabled = false; return }

  const oldStartedAt = plan.startedAt
  say(t('restart.all_running'))
  let data = null
  try {
    const res = await fetch('/api/system/restart-all', { method: 'POST' })
    data = await res.json().catch(() => ({}))
    if (!res.ok) throw new Error(data.error || t('restart.failed_start'))
  } catch (e) {
    say(e && e.message ? e.message : t('restart.failed_start'))
    btn.disabled = false
    return
  }

  // Az elbukott lepesek NEM vesznek el: a sor tovabbfut, de itt kimondjuk.
  const failed = (data.results || []).filter((r) => !r.ok)
  if (failed.length) {
    showToast(t('restart.all_partial', { names: failed.map((r) => r.label).join(', ') }), 'warn')
  }

  if (!data.dashboardRestarting) {
    // A vezerlopult nem indul ujra (nem systemd, vagy tiltott unit): az agensek
    // viszont igen. Ezt kimondjuk, nem varunk egy olyan ujrainditasra, ami el
    // sem indult.
    say(t('restart.all_done_no_dashboard'))
    showToast(data.dashboardReason || t('restart.unavailable'), 'warn')
    // Az agensek ATTOL MEG ujraindultak: a lapon levo sarga jelvenyek egy
    // resze mar nem igaz. Ujrarajzoljuk, kulonben ugyanaz a "hazudik a
    // kepernyo" helyzet all elo, mint a Marvin-gombnal.
    try { await loadSettings() } catch (e) { /* nem a Beallitasok lapon vagyunk */ }
    btn.disabled = false
    return
  }

  say(t('restart.waiting'))
  const deadline = Date.now() + 90000
  while (Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, 1000))
    let d = null
    try { d = await (await fetch('/api/system/restart', { cache: 'no-store' })).json() } catch (e) { d = null }
    if (d && d.startedAt && d.startedAt !== oldStartedAt) {
      say(t('restart.done'))
      setTimeout(() => location.reload(), 700)
      return
    }
  }
  say(t('restart.timeout'))
  btn.disabled = false
}

/**
 * Ujrainditja a vezerlopultot, es MEGVARJA, amig tenyleg visszajon.
 *
 * A "visszajott" nem azt jelenti, hogy valaszol valaki: a regi folyamat meg
 * egy masodpercig el. Ezert az indulasi idobelyeget nezzuk -- csak az UJ
 * folyamat ad uj idobelyeget.
 */
async function doSystemRestart(btn, status, oldStartedAt) {
  btn.disabled = true
  const say = (s) => { if (status) status.textContent = s }
  say(t('restart.starting'))
  try {
    const r = await fetch('/api/system/restart', { method: 'POST' })
    const d = await r.json().catch(() => ({}))
    if (!r.ok) throw new Error(d.error || t('restart.failed_start'))
    if (d.startedAt) oldStartedAt = d.startedAt
  } catch (e) {
    say(e && e.message ? e.message : t('restart.failed_start'))
    btn.disabled = false
    return
  }
  say(t('restart.waiting'))
  const deadline = Date.now() + 90000
  while (Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, 1000))
    let d = null
    try { d = await (await fetch('/api/system/restart', { cache: 'no-store' })).json() } catch (e) { d = null }
    if (d && d.startedAt && d.startedAt !== oldStartedAt) {
      say(t('restart.done'))
      setTimeout(() => location.reload(), 700)
      return
    }
  }
  // 90 masodperc utan sem jott vissza: ezt is kimondjuk, nem porgunk tovabb.
  say(t('restart.timeout'))
  btn.disabled = false
}

// ===========================================================================
// "Mit kell ujrainditani?" -- a Beallitasok sorainak sajat gombja
//
// Boss (2026-08-16): "tegyel egy gombot oda a beallitasokba illetve minden
// ilyen helyre ahol ezt irjatok ki hogy ujrainditas utan lep eletbe."
//
// Nem eleg EGY gomb: nem minden beallitas ugyanabban a folyamatban el. Az
// OLLAMA_URL-t a vezerlopult olvassa, a MAIN_AGENT_CONFIG_DIR-t viszont a fo
// agens sajat folyamata -- a vezerlopult ujrainditasa azon semmit nem valtoztat.
// Ezert minden sor a SAJAT celpontjahoz kap gombot, a `restartTarget` alapjan
// (src/config-registry.ts), es a gomb felirata megnevezi, mit indit ujra.
// ===========================================================================

/** A celpont ember-olvashato neve, a telepites sajat elnevezeseivel. */
function restartTargetName(target) {
  if (target === 'main-agent') return t('restart.target.main_agent', { bot: mainAgentDisplayName() })
  if (target === 'dashboard+agents') return t('restart.target.dashboard_agents')
  if (target === 'dashboard+heartbeat') return t('restart.target.dashboard_heartbeat')
  // Ismeretlen/hianyzo celpont eseten a vezerlopult a biztonsagos valasz: az
  // beallitasok tulnyomo tobbsege ott el, es a szoveg igy sem allit valotlant.
  return t('restart.target.dashboard')
}

/** A sorhoz tartozo ujrainditas-vezerlot teszi `slot`-ba, celpont szerint. */
async function mountSettingRestartAction(slot, def) {
  if (!slot) return
  const target = def.restartTarget || 'dashboard'
  const targetName = restartTargetName(target)

  if (target === 'main-agent') {
    slot.innerHTML = '<p class="subtitle" style="margin:0 0 8px">'
      + escapeHtml(t('restart.row_note', { target: targetName })) + '</p>'
      + '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
      + '<button class="btn-primary" data-agent-restart-btn>'
      + escapeHtml(t('restart.btn_target', { target: targetName })) + '</button>'
      + '<span class="subtitle" data-agent-restart-status></span></div>'
    const btn = slot.querySelector('[data-agent-restart-btn]')
    const status = slot.querySelector('[data-agent-restart-status]')
    const say = (m) => { if (status) status.textContent = m }
    btn.addEventListener('click', async () => {
      if (!confirm(t('agents.confirm.hard_restart'))) return
      btn.disabled = true
      say(t('restart.starting'))
      try {
        const res = await fetch('/api/marveen/restart', { method: 'POST' })
        if (!res.ok) {
          const err = await res.json().catch(() => ({}))
          throw new Error(err.error || t('agents.toast.restart_failed'))
        }
      } catch (err) {
        say('')
        showToast(err && err.message ? err.message : t('agents.toast.restart_failed'))
        btn.disabled = false
        return
      }
      // Boss (2026-08-18): "amit most idetettel main agent model
      // ujrainditottam es megis kiirja hogy ujrainditasra var!!?"
      //
      // A regi kod itt egy toastot dobott, es ennyi. A sarga jelveny viszont
      // a lap BETOLTESEKOR lekert allapotbol keszult, es azt senki nem kerte
      // le ujra -- igy a kepernyon ottmaradt egy figyelmeztetes, ami mar nem
      // volt igaz. Nem a szerver hazudott: a KEPERNYO volt elavult.
      //
      // Mostantol megvarjuk, amig maga a KISZOLGALO mondja azt, hogy ez a
      // kulcs mar nem var ujrainditasra -- pontosan abbol a forrasbol, amibol
      // a jelveny is keszul --, es utana ujrarajzoljuk a lapot. Igy a gomb
      // megnyomasa es a jelveny eltunese ugyanaz az esemeny.
      // Boss (2026-08-24): "at alitottam opus 5 re a beallitasokban. de meg
      // mindig sonett 5" ... "ohhh. na most valtott at opus 5 re. eleg lassu
      // a valtas!" -- MERVE ~7 perc telt el az ujrainditas kerese es az uj
      // modellel felallo folyamat kozott. A regi hatarido 90 masodperc volt,
      // vagyis a felulet KUDARCOT jelentett egy olyan muveletre, ami eppen
      // rendben zajlott. Az uj hatarido 12 perc, es amig varunk, kiirjuk az
      // eltelt idot -- a "meg megy" es a "elakadt" igy nem mosodik ossze.
      // MERVE (Boss, 2026-08-24): a mentes (`valueSavedAt`) es az uj folyamat
      // indulasa (`runningSince`) kozott 4,2 MASODPERC telt el -- a respawn-pane
      // azonnal cserel. Amit a Boss percekig varasnak latott, az NEM az
      // ujrainditas volt: a kartya modell-jelvenye ragadt be, mert a regi
      // transzkriptet olvasta (lasd main-agent-model.ts). Ezert a hatarido 60
      // masodperc -- bosegesen fedi a mert 4 mp-et --, a lekerdezes pedig
      // masodpercenkent fut, hogy a kesz allapot ne alljon egy hosszu alvasban.
      const started = Date.now()
      const deadline = started + 60000
      say(t('restart.waiting'))
      while (Date.now() < deadline) {
        await new Promise((r) => setTimeout(r, 1000))
        say(t('restart.waiting_progress', { sec: Math.round((Date.now() - started) / 1000) }))
        let rows = null
        try {
          const d = await (await fetch('/api/settings', { cache: 'no-store' })).json()
          rows = d && d.settings
        } catch (e) { rows = null }
        if (!rows) continue
        const fresh = rows.find((r) => r.key === def.key)
        if (fresh && !fresh.restartPending) {
          // Boss (2026-08-18): "ha frisiti akkor miert nem frisiti? megakadt?"
          // Jogos: a szoveg "Frissitem az oldalt"-ot igert, a kod viszont csak
          // egy csendes ujrarajzolast probalt (`loadSettings()`), es ha az
          // brmiert elhasalt, a hiba nemán elnyelodott -- a gomb orokre
          // letiltva maradt, a szoveg orokre "kesz"-et hazudott. A masik
          // ujrainditas-gomb (`doSystemRestart`) VALODI oldal-ujratoltest
          // csinal, es azt a Boss sose kifogasolta -- ugyanazt tesszuk itt is.
          say(t('restart.done'))
          showToast(t('agents.toast.marveen_restarted'))
          setTimeout(() => location.reload(), 700)
          return
        }
      }
      // 60 masodperc utan sem tisztult, holott a mert csere 4 mp. NEM allitjuk,
      // hogy elhasalt -- azt nem tudjuk; azt mondjuk meg, ameddig lattunk.
      say(t('restart.timeout'))
      btn.disabled = false
    })
    // A "mindent" gomb ITT is ott van: Boss szerint nem az o dolga fejben
    // tartani, melyik beallitas melyik folyamatban el. A celzott gomb a
    // gyorsabb ut, ez pedig a biztos.
    mountRestartAllButton(slot)
    return
  }

  // Minden mas celpont a vezerlopultot inditja ujra. Ahol ez nem eleg
  // (dashboard+agents), ott a MASODIK lepest is kimondjuk -- kulonben a
  // felhasznalo azt hinne, hogy a gomb utan mar kesz van.
  await mountRestartButton(slot, t('restart.row_note', { target: targetName }))
  if (target === 'dashboard+agents') {
    const second = document.createElement('p')
    second.className = 'subtitle'
    second.style.margin = '8px 0 0'
    second.textContent = t('restart.second_step_agents')
    slot.appendChild(second)
  }
}

// ===========================================================================
// Mappavalaszto
//
// Boss: "jobb lenne ha ki lehetne valasztani ugy mint amikor fel akarok
// tolteni egy filet vagy mappat. nem kezzel beirni meg per jel stb..."
//
// A bongeszo nem tudja megmondani egy mappa valodi utvonalat (a File System
// Access API szandekosan nem adja oda), ezert a KISZOLGALO sorolja fel a
// lemezeket es a mappakat -- a kiszolgalo ugyanis maga a gep.
// ===========================================================================
let _fpHere = null       // ahol allunk (linuxos alak), null = lemezlista
let _fpParent = null
let _fpOnPick = null     // mit csinaljunk a valasztassal

function openFolderPicker(onPick) {
  const modal = document.getElementById('folderPickModal')
  if (!modal) return
  _fpOnPick = onPick
  if (modal.parentElement !== document.body) document.body.appendChild(modal)
  modal.hidden = false
  modal.classList.add('active')
  // A lemezlista betoltese elott is a HELYES nyelven alljon a fejlec.
  _fpHere = null
  const here = document.getElementById('folderPickHere')
  if (here) here.textContent = t('picker.my_computer')
  _fpBind()
  _fpLoad(null)
}

function closeFolderPicker() {
  const modal = document.getElementById('folderPickModal')
  if (!modal) return
  modal.classList.remove('active')
  modal.hidden = true
}

function _fpBind() {
  const once = (id, fn) => {
    const el = document.getElementById(id)
    if (el && !el._fpBound) { el._fpBound = 1; el.addEventListener('click', fn) }
  }
  once('folderPickClose', closeFolderPicker)
  once('folderPickCancel', closeFolderPicker)
  once('folderPickUp', () => _fpLoad(_fpParent))
  once('folderPickOk', _fpConfirm)
  const name = document.getElementById('folderPickName')
  if (name && !name._fpBound) { name._fpBound = 1; name.addEventListener('input', _fpPreview) }
}

async function _fpLoad(path) {
  const list = document.getElementById('folderPickList')
  const here = document.getElementById('folderPickHere')
  const msg = document.getElementById('folderPickMsg')
  const up = document.getElementById('folderPickUp')
  const nameRow = document.getElementById('folderPickNameRow')
  const ok = document.getElementById('folderPickOk')
  if (list) list.innerHTML = '<p class="subtitle" style="padding:10px">' + escapeHtml(t('picker.loading')) + '</p>'
  let d = null
  try {
    d = await (await fetch('/api/depot/browse' + (path ? '?path=' + encodeURIComponent(path) : ''))).json()
  } catch (e) {
    if (list) list.innerHTML = '<p class="subtitle" style="padding:10px">' + escapeHtml(t('picker.open_failed')) + '</p>'
    return
  }
  _fpHere = d.path
  _fpParent = d.parent
  // A legfelso szinten a kiszolgalo is kuld feliratot ("Saját gép"), de az
  // MAGYAR -- angol felulet mellett az kilogna. A szintet a `path` donti el
  // (null = lemezlista), a nevet mi adjuk hozza.
  if (here) here.textContent = d.path ? (d.display || '') : t('picker.my_computer')
  if (msg) msg.textContent = d.message || ''
  // A legfelso szinten nincs hova visszalepni; a lemez gyokerebol a
  // lemezlistara megyunk (nem a /mnt-be -- az egy linuxos reszlet).
  if (up) up.disabled = !d.path
  // Mappat csak akkor lehet valasztani, ha mar egy konkret helyen allunk.
  if (nameRow) nameRow.hidden = !d.path
  if (ok) ok.disabled = !d.path

  const rows = []
  if (!d.path) {
    // Legfelso szint: a lemezek. Szabad hellyel egyutt -- 8 GB kepet nem
    // fogunk egy 2 GB-os pendrive-ra tenni, es ezt latni kell ELORE.
    for (const dr of (d.drives || [])) {
      rows.push('<button class="fp-row" data-fp-go="' + escapeHtml(dr.path) + '">'
        + '<span class="fp-ico">💽</span><span class="fp-name">' + escapeHtml(dr.label) + '</span>'
        + '<span class="fp-meta">' + escapeHtml(t('picker.free_of', { free: dr.freeHuman, total: dr.totalHuman })) + '</span></button>')
    }
    if (!rows.length) rows.push('<p class="subtitle" style="padding:10px">' + escapeHtml(t('picker.no_drives')) + '</p>')
  } else {
    for (const f of (d.folders || [])) {
      rows.push('<button class="fp-row" data-fp-go="' + escapeHtml(f.path) + '">'
        + '<span class="fp-ico">📁</span><span class="fp-name">' + escapeHtml(f.name) + '</span></button>')
    }
    if (!rows.length && !d.message) rows.push('<p class="subtitle" style="padding:10px">' + escapeHtml(t('picker.no_subfolders')) + '</p>')
  }
  if (list) {
    list.innerHTML = rows.join('')
    list.querySelectorAll('[data-fp-go]').forEach((b) => {
      b.addEventListener('click', () => _fpLoad(b.getAttribute('data-fp-go')))
    })
  }
  _fpPreview()
}

/** "Ide fog kerülni: D:\Marveen" -- lassa ELORE, mi lesz belole. */
function _fpPreview() {
  const el = document.getElementById('folderPickPreview')
  const here = document.getElementById('folderPickHere')
  const name = document.getElementById('folderPickName')
  if (!el || !here) return
  const n = ((name && name.value) || '').trim()
  // A legfelso szintet a _fpHere donti el, NEM a kiirt szoveg: a "Saját gép"
  // felirat forditva mas ("This computer"), egy szoveg-osszehasonlitas tehat
  // angolul csendben elromlana, es a lemezlistan is utvonalat igerne.
  const base = _fpHere ? here.textContent : ''
  el.textContent = !base ? '—' : (n ? base.replace(/\\+$/, '') + '\\' + n : base)
}

function _fpConfirm() {
  if (!_fpHere) return
  const name = ((document.getElementById('folderPickName') || {}).value || '').trim()
  const here = document.getElementById('folderPickHere')
  const base = ((here && here.textContent) || '').replace(/\\+$/, '')
  closeFolderPicker()
  // `display` a Windows-alak (ez megy a Beallitasok mezojebe), `parent`+`name`
  // pedig az, amibol a kiszolgalo dolgozik.
  if (_fpOnPick) _fpOnPick({ parent: _fpHere, name, display: name ? base + '\\' + name : base })
}

// ===========================================================================
// DRIVE-MAPPA VALASZTO
//
// Boss: "nem lehet azt is megoldani hogy ki lehessen valasztani a drive
// oldalrol a mappa azonositot meg a mappa nevet? miert kezzel kell beirnia a
// komuvesnek mindig mindent?"
//
// Igaza van: a mappa-azonosito (`1a2B3c...`) gepi adat, nem embernek valo. A
// Drive fajat ugyanaz a /api/drive/list szolgalja ki, mint a Drive oldalt,
// tehat csak vegig kell rajta setalni -- az azonositot es a nevet a valasztas
// adja, nem a billentyuzet.
//
// SZANDEKOSAN `var`: ezt a fajlt mar tobbszor megvagta, hogy egy korai
// hivas olyan `let`-hez nyult, ami meg nem futott le (lasd web-boot-order.test).
// ===========================================================================
var _dpStack = []        // a gyokertol lefele: [{ id, name }]
var _dpAccount = ''
var _dpOnPick = null
// Hanyadik lekerdezesnel tartunk. Ha valaki gyorsan kattint ket mappat, a KESON
// beeso valasz nem irhatja felul a frissebbet -- kulonben mas mappa tartalmat
// latna, mint amiben all.
var _dpSeq = 0

function openDrivePicker(account, onPick) {
  const modal = document.getElementById('drivePickModal')
  if (!modal) return
  _dpOnPick = onPick
  _dpAccount = account || ''
  _dpStack = []
  if (modal.parentElement !== document.body) document.body.appendChild(modal)
  modal.hidden = false
  modal.classList.add('active')
  const manual = document.getElementById('drivePickManualId')
  if (manual) manual.value = ''
  _dpBind()
  _dpEnter('root', t('dpick.my_drive'))
}

function closeDrivePicker() {
  const modal = document.getElementById('drivePickModal')
  if (!modal) return
  modal.classList.remove('active')
  modal.hidden = true
}

function _dpBind() {
  const once = (id, fn) => {
    const el = document.getElementById(id)
    if (el && !el._dpBound) { el._dpBound = 1; el.addEventListener('click', fn) }
  }
  once('drivePickClose', closeDrivePicker)
  once('drivePickCancel', closeDrivePicker)
  once('drivePickUp', () => { if (_dpStack.length > 1) { _dpStack.pop(); _dpLoad() } })
  once('drivePickOk', _dpConfirm)
  once('drivePickManualBtn', _dpOpenManual)
}

/**
 * Belepes egy mappaba: a verem adja a visszautat ES a kiirt utvonalat.
 * `manual`: azonositoval nyitottuk meg, tehat a mappa VALODI nevet nem tudjuk
 * -- ezt a valasztas is tovabbadja, hogy a nev-mezot fel lehessen kinalni
 * atirasra. (Jelzokent adjuk at, NEM a kiirt szoveg osszehasonlitasaval: az
 * angol feluleten mas szoveg allna ott, es csendben elromlana.)
 */
function _dpEnter(id, name, manual) {
  _dpStack.push({ id, name, manual: !!manual })
  _dpLoad()
}

/** A veremben legfelul allo mappa tartalma. */
async function _dpLoad() {
  const list = document.getElementById('drivePickList')
  const here = document.getElementById('drivePickHere')
  const msg = document.getElementById('drivePickMsg')
  const up = document.getElementById('drivePickUp')
  const ok = document.getElementById('drivePickOk')
  const cur = _dpStack[_dpStack.length - 1]
  if (!cur) return
  if (here) here.textContent = _dpStack.map((s) => s.name).join(' / ')
  if (up) up.disabled = _dpStack.length <= 1
  // A gyokeret magat nem lehet valasztani: az EGESZ Drive-ot huznank le vele.
  if (ok) ok.disabled = _dpStack.length <= 1
  if (list) list.innerHTML = '<p class="subtitle" style="padding:10px">' + escapeHtml(t('dpick.loading')) + '</p>'
  if (msg) msg.textContent = ''
  const seq = ++_dpSeq
  let d = null
  try {
    const r = await fetch('/api/drive/list?folderId=' + encodeURIComponent(cur.id)
      + '&account=' + encodeURIComponent(_dpAccount))
    d = await r.json()
    if (!r.ok || d.error) throw new Error(d.error || ('HTTP ' + r.status))
  } catch (e) {
    if (seq !== _dpSeq) return
    // A verembol ki kell venni a mappat, kulonben a "Vissza" egy olyan helyre
    // mutatna, ahova be sem jutottunk.
    if (_dpStack.length > 1) _dpStack.pop()
    if (list) list.innerHTML = ''
    if (msg) msg.textContent = t('dpick.open_failed', { error: (e && e.message) ? e.message : String(e) })
    if (here) here.textContent = _dpStack.map((s) => s.name).join(' / ')
    if (up) up.disabled = _dpStack.length <= 1
    if (ok) ok.disabled = _dpStack.length <= 1
    return
  }
  // Kozben mar egy ujabb mappaba leptunk: ez a valasz elavult.
  if (seq !== _dpSeq) return
  const files = d.files || []
  const folders = files.filter((f) => f.isFolder)
  const rows = folders.map((f) => '<button class="fp-row" data-dp-go="' + escapeHtml(f.id) + '"'
    + ' data-dp-name="' + escapeHtml(f.name) + '">'
    + '<span class="fp-ico">📁</span><span class="fp-name">' + escapeHtml(f.name) + '</span></button>')
  if (list) {
    list.innerHTML = rows.join('') || '<p class="subtitle" style="padding:10px">' + escapeHtml(t('dpick.no_subfolders')) + '</p>'
    list.querySelectorAll('[data-dp-go]').forEach((b) => {
      b.addEventListener('click', () => _dpEnter(b.getAttribute('data-dp-go'), b.getAttribute('data-dp-name')))
    })
  }
  // Hany fajl van ITT: enelkul vakon valasztana egy ures mappat. A kiszolgalo
  // 200 elemet ad vissza egy keresre -- ha ennyit kaptunk, elkepzelheto, hogy
  // van meg tovabb, es ezt ki KELL mondani: kulonben ugy tunne, hogy a hianyzo
  // mappa nem letezik.
  const reszek = []
  if (_dpStack.length > 1) reszek.push(t('dpick.file_count', { count: files.length - folders.length }))
  // A gyokerben a "Ez a mappa legyen" gomb tiltott. Ki KELL mondani, hogy miert
  // es mi a teendo -- kulonben csak egy szurke gombot lat, es nem tudja, mit
  // rontott el.
  else reszek.push(t('dpick.root_hint'))
  if (files.length >= 200) reszek.push(t('dpick.truncated'))
  if (msg) msg.textContent = reszek.join(' ')
}

/** "Ismerem az azonositot": beleptet, hogy LASSA is, mit valasztott. */
function _dpOpenManual() {
  const el = document.getElementById('drivePickManualId')
  const id = ((el && el.value) || '').trim()
  const msg = document.getElementById('drivePickMsg')
  if (!id) return
  // Ugyanaz a szabaly, mint a kiszolgalon (isSafeFolderId): igy a rossz beirast
  // rogton itt megmondjuk, nem egy 400-as valasz utan.
  if (!/^[A-Za-z0-9_-]{1,256}$/.test(id)) {
    if (msg) msg.textContent = t('dpick.bad_id')
    return
  }
  _dpEnter(id, t('dpick.manual_name'), true)
}

function _dpConfirm() {
  const cur = _dpStack[_dpStack.length - 1]
  if (!cur || _dpStack.length <= 1) return
  const path = _dpStack.map((s) => s.name).join(' / ')
  closeDrivePicker()
  if (_dpOnPick) _dpOnPick({ id: cur.id, name: cur.name, path, manual: !!cur.manual })
}

/**
 * A kiszolgalo `safeSegment()` fuggvenyenek masa (drive-sync.ts).
 * Azert kell ide is, hogy a felajanlott nev PONTOSAN az legyen, ami a lemezre
 * kerul -- kulonben a mezoben mast latna, mint a mappa nevet a gepen.
 * Az egyezest teszt orzi (drive-folder-picker.test.ts).
 */
function _dpSafeName(name) {
  const cleaned = String(name || '')
    .replace(/[\\/]/g, '_')
    .replace(/[\u0000-\u001f\u007f]/g, '')
    .replace(/[:*?"<>|]/g, '_')
    .replace(/^\.+$/, '_')
    .replace(/[. ]+$/, '')
    .trim()
  return cleaned.slice(0, 120) || 'nevtelen'
}

/** A Raktár oldal "Hely kiválasztása…" gombja. */
function _depoPickRoot() {
  openFolderPicker(async (choice) => {
    const st = document.getElementById('depoRootStatus')
    if (st) st.textContent = t('picker.saving')
    try {
      const r = await fetch('/api/depot/root', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        // Ha nem adott uj mappanevet, akkor MAGA a kivalasztott mappa a depo.
        body: JSON.stringify(choice.name ? { parent: choice.parent, name: choice.name } : { path: choice.parent }),
      })
      const d = await r.json().catch(() => ({}))
      if (!r.ok) throw new Error(d.error || t('picker.save_failed'))
      const disp = document.getElementById('depoRootDisplay')
      if (disp) disp.textContent = d.display
      if (st) {
        st.textContent = t('picker.saved', { free: d.freeHuman })
          + (d.existingEntries ? t('picker.saved_not_empty', { count: d.existingEntries }) : '')
      }
      // Itt a legfontosabb a gomb: a futo Marveen meg a REGI helyet ismeri.
      await mountRestartButton(document.getElementById('depoRestartSlot'),
        t('restart.note_depot'))
    } catch (e) {
      if (st) st.textContent = (e && e.message) ? e.message : t('picker.save_failed')
    }
  })
}

async function loadDepoPage() {
  _depoStopPoll()
  const bind = (id, fn) => {
    const el = document.getElementById(id)
    if (el && !el._depoBound) { el._depoBound = 1; el.addEventListener('click', fn) }
  }
  bind('depoRefreshBtn', () => _depoRefresh())
  bind('depoPickBtn', () => _depoPickRoot())
  bind('depoPhotosGoBtn', () => switchPage('photos'))
  bind('depoSyncWholeBtn', () => _depoAddWholeDrive())
  bind('depoSyncPickBtn', () => _depoPickDriveFolder())
  bind('depoSyncAddBtn', () => _depoAddSync())
  bind('depoSyncRunBtn', () => _depoRunSync())
  bind('depoBackupPreviewBtn', () => _depoBackupMeasure())
  bind('depoBackupAddBtn', () => _depoBackupAdd())
  // A valasztas MEGVALTOZASA ervenytelenne teszi a merest: a gomb ilyenkor
  // ujra szurke lesz. Kulonben a Boss megmerne az egyik agat, atvaltana egy
  // masikra, es a MASIKAT kotne be a latott szamok alapjan.
  ;['depoBackupBranch', 'depoBackupAccount'].forEach((id) => {
    const el = document.getElementById(id)
    if (el && !el._depoBound) { el._depoBound = 1; el.addEventListener('change', () => _depoBackupGombAllapot()) }
  })
  bind('storagesGitAddBtn', () => _storagesAddGit())
  bind('storagesGitSyncBtn', () => _storagesGitSync())
  // A tablazat gombjai delegalva: a sorok minden frissiteskor ujra keszulnek,
  // soronkent felkotott kezelo eseten az ujrarajzolas utan nemak lennenek.
  const storTbl = document.getElementById('storagesTable')
  if (storTbl && !storTbl._depoBound) {
    storTbl._depoBound = 1
    storTbl.addEventListener('click', (ev) => _storagesClick(ev))
  }
  // Enter a mezoben = ugyanaz, mint a gomb. Aki begepeli a nevet, nem fog
  // egerert nyulni.
  const gitInp = document.getElementById('storagesGitName')
  if (gitInp && !gitInp._depoBound) {
    gitInp._depoBound = 1
    gitInp.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') { ev.preventDefault(); _storagesAddGit() } })
  }

  // Fiokvaltaskor a korabbi valasztas ELAVUL: egy mappa-azonosito csak abban a
  // fiokban ervenyes, amelyikben kivalasztottuk. Ha bennemaradna, a masik fiok
  // neveben probalnank hozzaadni egy olyan mappat, amit az nem is lat.
  const acc = document.getElementById('depoSyncAccount')
  if (acc && !acc._depoBound) {
    acc._depoBound = 1
    acc.addEventListener('change', () => _depoClearDrivePick())
  }
  // A ket veszelyes kapcsolo. `change`, nem `click`: billentyuzetrol is jarhato.
  ;['depoSyncUpload', 'depoSyncDeleteUp'].forEach((id) => {
    const el = document.getElementById(id)
    if (el && !el._depoBound) {
      el._depoBound = 1
      el.addEventListener('change', () => _depoSaveSyncSettings())
    }
  })
  // KULSO TORLES ELLENI VEDELEM (6. pont).
  bind('depoGuardRefreshBtn', () => _depoGuardRefresh())
  bind('depoGuardClearBtn', () => _depoGuardClear())
  var grd = document.getElementById('depoGuardEnabled')
  if (grd && !grd._depoBound) {
    grd._depoBound = 1
    grd.addEventListener('change', () => _depoGuardToggle(grd.checked))
  }
  _depoClearDrivePick()
  await _depoRefresh()
}

/* ============ KULSO TORLES ELLENI VEDELEM (specifikacio 6. pont) ============
 *
 * A lenyeg a LATHATOSAG: a lefele menetben nincs torles, de eddig semmi nem
 * mutatta, ha a Drive-rol eltunt valami. Ez a harom fuggveny a kepernyore
 * hozza -- a helyi fajlhoz egyik sem nyul.
 *
 * A NULLA KET DOLGOT JELENTHET: az ures listahoz a MAGYARAZATOT a kiszolgalo
 * adja (`summary`), mert csak ott tudhato, letezik-e egyaltalan a naplo. A
 * bongeszo nem talalgat.
 */
async function _depoGuardRefresh() {
  var sum = document.getElementById('depoGuardSummary')
  var list = document.getElementById('depoGuardList')
  if (!sum && !list) return
  var d = null
  var hiba = ''
  try {
    d = await _depoGet('/api/drive/sync/external?lang=' + encodeURIComponent(window._lang || 'hu'))
  } catch (e) {
    // A TENYLEGES hibauzenet megy ki, nem tippelt ok.
    hiba = (e && e.message) ? e.message : String(e)
  }
  if (hiba) {
    if (sum) sum.textContent = t('dguard.load_failed') + ' ' + hiba
    if (list) list.innerHTML = ''
    return
  }
  var chk = document.getElementById('depoGuardEnabled')
  if (chk) chk.checked = d.enabled !== false
  if (sum) sum.textContent = d.summary || ''
  if (!list) return
  var sorok = d.changes || []
  if (!sorok.length) { list.innerHTML = ''; return }
  list.innerHTML = '<div class="ssh-table-wrap"><table class="ssh-table"><thead><tr>'
    + '<th>' + escapeHtml(t('dguard.col_when')) + '</th>'
    + '<th>' + escapeHtml(t('dguard.col_what')) + '</th>'
    + '<th>' + escapeHtml(t('dguard.col_file')) + '</th>'
    + '<th>' + escapeHtml(t('dguard.col_note')) + '</th></tr></thead><tbody>'
    + sorok.map(function (c) {
      return '<tr><td>' + escapeHtml(String(c.at || '').slice(0, 16).replace('T', ' ')) + '</td>'
        + '<td>' + escapeHtml(c.kind || '') + '</td>'
        // A TELJES helyi ut: ezt kell megnyitni, ha vissza akarod nezni a fajlt.
        + '<td>' + (c.localPath ? '<code>' + escapeHtml(c.localPath) + '</code>' : '<span class="subtitle">—</span>') + '</td>'
        + '<td>' + escapeHtml(c.note || '') + '</td></tr>'
    }).join('')
    + '</tbody></table></div>'
}

async function _depoGuardToggle(enabled) {
  try {
    await _depoPost('/api/drive/sync/external', { enabled: !!enabled })
  } catch (e) {
    alert(t('dguard.save_failed') + ' ' + ((e && e.message) ? e.message : String(e)))
  }
  await _depoGuardRefresh()
}

async function _depoGuardClear() {
  // A naplo uritese NEM torol fajlt -- de akkor is megkerdezzuk, mert a
  // feljegyzett esemenyek nem jonnek vissza.
  if (!confirm(t('dguard.clear_confirm'))) return
  try {
    await _depoPost('/api/drive/sync/external', { clear: true })
  } catch (e) {
    alert(t('dguard.clear_failed') + ' ' + ((e && e.message) ? e.message : String(e)))
  }
  await _depoGuardRefresh()
}

/**
 * A FO ut: a kivalasztott fiok TELJES Drive-ja jojjon le.
 *
 * Boss 2026-08-15: "mit akarok szinkronizalni. hat a lackor2 drivot
 * mindenestul! akkor itt nincs tovabb kerdes semmi." -- ezert nincs
 * mappavalasztas es nincs nevado mezo sem: a gyokeret (`root`) adjuk at, ures
 * nevvel. Ures nev = a fiok sajat mappaja MAGA a cel, vagyis a helyi mappa neve
 * a fiok neve (lackor2 -> lackor2), a fa pedig ugyanaz, mint a neten.
 */
async function _depoAddWholeDrive() {
  const account = (document.getElementById('depoSyncAccount') || {}).value || ''
  if (!account) { showToast(t('dsync.no_account')); return }
  if (!confirm(t('dsync.whole_confirm', { account: account }))) return
  const btn = document.getElementById('depoSyncWholeBtn')
  if (btn) btn.disabled = true
  const picked = document.getElementById('depoSyncPicked')
  try {
    await _depoPost('/api/drive/sync/add', { account: account, folderId: 'root', name: '' })
    if (picked) picked.textContent = t('dsync.whole_added', { account: account })
    await _depoRefresh()
  } catch (e) {
    showToast((e && e.message) ? e.message : t('dsync.add_failed'))
  } finally {
    if (btn) btn.disabled = false
  }
}

/** A "Mégis inkább csak EGY mappát" ut: Drive-mappa kivalasztasa. */
function _depoPickDriveFolder() {
  const account = (document.getElementById('depoSyncAccount') || {}).value || ''
  if (!account) { showToast(t('dsync.no_account')); return }
  openDrivePicker(account, (f) => {
    const idEl = document.getElementById('depoSyncFolderId')
    const nameEl = document.getElementById('depoSyncName')
    const picked = document.getElementById('depoSyncPicked')
    const add = document.getElementById('depoSyncAddBtn')
    if (idEl) idEl.value = f.id
    // A helyi nev MINDIG a Drive-mappa neve -- nem lehet atirni. Boss
    // 2026-08-15: "legyen csak ugyanaz mint fent a neten ... igy nincs
    // keveredes." Az azonositoval megnyitott mappa nevet nem ismerjuk, ezert
    // oda az azonosito eleje kerul: ket ilyen mappa igy sem eshet egymasra.
    if (nameEl) nameEl.value = f.manual ? _dpSafeName(f.name + '-' + String(f.id).slice(0, 8)) : _dpSafeName(f.name)
    if (picked) picked.textContent = t('dsync.picked', { account: account, path: f.path })
    if (add) add.disabled = false
  })
}

/** Nincs (mar) kivalasztott mappa: a "Hozzáadás" ilyenkor nem indulhat el. */
function _depoClearDrivePick() {
  const idEl = document.getElementById('depoSyncFolderId')
  const add = document.getElementById('depoSyncAddBtn')
  const picked = document.getElementById('depoSyncPicked')
  const nameEl = document.getElementById('depoSyncName')
  if (idEl) idEl.value = ''
  if (nameEl) nameEl.value = ''
  if (add) add.disabled = true
  if (picked) picked.textContent = ''
}

/**
 * A leszakadt depo helyreallitasa a Depo lapon.
 *
 * A MERT ESET (2026-08-26): a depo elerhetetlen volt, a doboz kimondta, hogy
 * "nem erheto el" -- es ott meg is allt. A javitas a fejlesztő fejeben lakott,
 * es a felhasznalo nem tudott mit kezdeni vele. Egy hibauzenet, ami nem mondja
 * meg a KOVETKEZO LEPEST, csak ijesztget.
 *
 * Ket utat kinalunk, a szakma sorrendjeben:
 *   1. `wsl --shutdown` Windowsbol -- ez az igazi javitas (MINDEN meghajto
 *      csatolasat ujraepiti), de leallitja a Marveent is, ezert nem indithatja
 *      el maga.
 *   2. Celzott ujracsatolas -- csak a depot erinti, uzem kozben is mehet.
 *
 * A parancsot a KISZOLGALO allitja ossze a MERT csatolasi beallitasokbol, nem
 * a bongeszo rakja ossze sablonbol. Ha egyetlen csatolast sem latott, azt a
 * lap KIMONDJA (`optionSource === 'unknown'`) -- nem ugy adja elo, mintha
 * biztos lenne benne.
 */
/**
 * A nyers kimenet. Nem szepitjuk es nem forditjuk le: ez az EGYETLEN hely, ahol
 * a felhasznalo (vagy aki segit neki) latja, mi tortent valojaban.
 */
function _depoShowOutput(txt) {
  const host = document.getElementById('depoRepair')
  if (!host || !txt) return
  const pre = document.createElement('pre')
  pre.className = 'depo-repair-cmd'
  pre.textContent = txt
  host.appendChild(pre)
}

/**
 * HELYBEN VEGIGVEZETO UTMUTATO a jogosultsag felvetelehez.
 *
 * A kapcsolo bekapcsolasa maga NEM ad jogot -- es ez igy helyes: egy dashboard
 * ne tudja magat rendszergazdava tenni. A jelszo nelkuli engedelyt egyetlen,
 * szuk hatokoru sor adja meg, amit A FELHASZNALO vesz fel. Ez a sor pontosan
 * azt a ket parancsot engedi, amit a Marveen futtat -- semmi tobbet --, es
 * ugyanabbol a mert tervbol keszul, mint maga a parancs, tehat nem tud
 * elcsuszni tole.
 *
 * Miert `visudo -f` es nem sima szerkesztes: a visudo ELLENORZI a fajlt mentes
 * elott. Egy elrontott sudoers-fajl az egesz sudo-t hasznalhatatlanna teszi.
 */
function _depoShowSudoers(d, r) {
  const host = document.getElementById('depoRepair')
  if (!host) return
  const doboz = document.createElement('div')
  doboz.className = 'depo-sudoers'

  const cim = document.createElement('p')
  cim.innerHTML = '<strong>' + escapeHtml(t('depot.sudoers.title')) + '</strong>'
  doboz.appendChild(cim)

  const mit = document.createElement('p')
  mit.className = 'subtitle'
  mit.textContent = t('depot.sudoers.why')
  doboz.appendChild(mit)

  const l = document.createElement('ol')
  l.className = 'depo-repair-steps'
  const l1 = document.createElement('li')
  l1.textContent = t('depot.sudoers.step_open', { f: r.sudoersFile || '/etc/sudoers.d/marveen-depot' })
  l.appendChild(l1)
  const l2 = document.createElement('li')
  l2.textContent = t('depot.sudoers.step_paste')
  l.appendChild(l2)
  const l3 = document.createElement('li')
  l3.textContent = t('depot.sudoers.step_retry')
  l.appendChild(l3)
  doboz.appendChild(l)

  const nyit = document.createElement('pre')
  nyit.className = 'depo-repair-cmd'
  nyit.textContent = 'sudo visudo -f ' + (r.sudoersFile || '/etc/sudoers.d/marveen-depot')
  doboz.appendChild(nyit)

  const sor = document.createElement('pre')
  sor.className = 'depo-repair-cmd'
  sor.textContent = r.sudoers || d.sudoers || ''
  doboz.appendChild(sor)

  const masol = document.createElement('button')
  masol.type = 'button'
  masol.className = 'btn-secondary btn-compact'
  masol.textContent = t('depot.sudoers.copy')
  masol.addEventListener('click', function () {
    navigator.clipboard.writeText(sor.textContent).then(function () {
      const o = masol.textContent
      masol.textContent = t('depot.repair.copied')
      setTimeout(function () { masol.textContent = o }, 1400)
    }).catch(function () { showToast(t('depot.repair.copy_failed')) })
  })
  doboz.appendChild(masol)

  host.appendChild(doboz)
  if (r.output) _depoShowOutput(r.output)
}

function _depoShowRepair(d) {
  const host = document.getElementById('depoRepair')
  if (!host) return
  const terv = d && d.repair
  // Ep depon nincs mit javitani. A `repair` akkor is kitoltott lehet, ha minden
  // rendben van, ezert az ALLAPOT dont, nem a terv megléte.
  if (!terv || !d.configured || d.writable) {
    host.hidden = true
    host.innerHTML = ''
    return
  }
  host.hidden = false
  host.innerHTML = ''

  const cim = document.createElement('p')
  cim.className = 'subtitle'
  cim.textContent = t('depot.repair.intro')
  host.appendChild(cim)

  const lista = document.createElement('ol')
  lista.className = 'depo-repair-steps'

  const l1 = document.createElement('li')
  l1.textContent = t('depot.repair.step_shutdown')
  lista.appendChild(l1)

  const l2 = document.createElement('li')
  l2.textContent = t('depot.repair.step_remount')
  lista.appendChild(l2)
  host.appendChild(lista)

  const pre = document.createElement('pre')
  pre.className = 'depo-repair-cmd'
  pre.textContent = terv.command
  host.appendChild(pre)

  const btn = document.createElement('button')
  btn.type = 'button'
  btn.className = 'btn-secondary btn-compact'
  btn.textContent = t('depot.repair.copy')
  btn.addEventListener('click', function () {
    navigator.clipboard.writeText(terv.command).then(function () {
      const orig = btn.textContent
      btn.textContent = t('depot.repair.copied')
      setTimeout(function () { btn.textContent = orig }, 1400)
    }).catch(function () { showToast(t('depot.repair.copy_failed')) })
  })
  host.appendChild(btn)

  // ONJAVITAS. Alapbol nincs itt semmi: kikapcsolt allapotban a gomb sem
  // jelenik meg, mert nem tudna mit csinalni. Bekapcsolva viszont EGY gomb
  // elvegzi -- es ha meg nincs meg a jogosultsag, a valasz nem hibakod, hanem
  // a pontos, ide kiirt teendo.
  if (d.autoRemount) {
    const fix = document.createElement('button')
    fix.type = 'button'
    fix.className = 'btn-primary btn-compact'
    fix.style.marginLeft = '8px'
    fix.textContent = t('depot.repair.auto_btn')
    fix.addEventListener('click', async function () {
      fix.disabled = true
      const eredeti = fix.textContent
      fix.textContent = t('depot.repair.auto_running')
      let r = null
      try {
        r = await (await fetch('/api/depot/remount', { method: 'POST' })).json()
      } catch (e) {
        r = { code: 'failed', error: String((e && e.message) || e) }
      }
      fix.disabled = false
      fix.textContent = eredeti
      if (r && r.ok) { showToast(t('depot.repair.auto_ok')); _depoRefresh(); return }
      // A HIBA OKAT NEM TALALGATJUK: amit a kiszolgalo latott, azt mutatjuk.
      if (r && r.code === 'needs_sudoers') { _depoShowSudoers(d, r); return }
      showToast((r && r.error) || t('depot.repair.auto_failed'), 'error')
      if (r && r.output) _depoShowOutput(r.output)
    })
    host.appendChild(fix)
  } else {
    const tipp = document.createElement('p')
    tipp.className = 'subtitle'
    tipp.textContent = t('depot.repair.auto_hint')
    host.appendChild(tipp)
  }

  // A NULLA KET DOLGOT JELENTHET, es a "nem tudom" sem lehet nemasag: ha a
  // csatolasi beallitasokat nem magarol a depo csatolasarol olvastuk le, azt
  // kimondjuk. A parancs igy is jo esellyel mukodik, de a felhasznalonak
  // tudnia kell, mennyire biztos.
  if (terv.optionSource !== 'measured') {
    const megj = document.createElement('p')
    megj.className = 'subtitle'
    megj.textContent = terv.optionSource === 'sibling'
      ? t('depot.repair.src_sibling')
      : t('depot.repair.src_unknown')
    host.appendChild(megj)
  }
}

async function _depoRefresh() {
  // ELSOKENT es a tobbitol fuggetlenul: a Drive-fioklista nem varhat a depo
  // allapotara (sem annak sikeressegere). Sajat hibakezelese van, ezert nem
  // varunk ra -- a lap tobbi resze ettol nem lassul.
  _depoLoadSyncAccounts()
  _depoBackupLoadBranches()
  // Ugyanezen okbol: a tarolo-tablazatnak sajat vegpontja van, ezert akkor is
  // megjelenik, ha a depo-allapot lekerdezese elhasal (ott lentebb `return` all).
  _storagesRefresh()
  _depoGet('/api/storages/git-sync').then(function (r) { _storagesShowSync(r && r.last) }).catch(function () {})
  const box = document.getElementById('depoHealthBox')
  const text = document.getElementById('depoHealthText')
  let d = null
  try {
    d = await _depoGet('/api/depot/status')
  } catch (e) {
    if (text) text.textContent = 'Nem sikerult lekerdezni a depo allapotat: ' + (e && e.message ? e.message : e)
    if (box) box.classList.add('depo-bad')
    return
  }
  if (text) text.textContent = d.message || ''
  _depoShowRepair(d)
  const rootDisp = document.getElementById('depoRootDisplay')
  if (rootDisp) {
    rootDisp.textContent = d.rootDisplay || t('picker.root_none')
  }
  // Egyetlen ranezesre lathato legyen, jo-e a helyzet. Ha a depo be van
  // allitva, de nem irhato, ez a doboz piros -- es a gombok sem indulnak el.
  if (box) box.classList.toggle('depo-bad', !!d.configured && !d.writable)

  const tbl = document.getElementById('depoPhotosTable')
  if (tbl) {
    const rows = (d.photos || []).filter((p) => p.count)
    if (!rows.length) {
      // A NULLA KET DOLGOT JELENTHET. Ha a depo nem erheto el, nem azt mondjuk,
      // hogy nincs kep -- azt mondjuk, hogy nem latunk oda.
      tbl.innerHTML = '<p class="subtitle">' + escapeHtml(
        d.configured && !d.writable ? t('depot.photos.unreadable') : t('depot.photos.none')) + '</p>'
    } else {
      tbl.innerHTML = '<div class="ssh-table-wrap"><table class="ssh-table"><thead><tr>'
        + '<th>' + escapeHtml(t('depot.photos.col_account')) + '</th>'
        + '<th>' + escapeHtml(t('depot.photos.col_in_depot')) + '</th></tr></thead><tbody>'
        + rows.map((p) => '<tr><td>' + escapeHtml(p.account) + '</td>'
          + '<td>' + p.count + ' db · ' + _depoBytes(p.bytes) + '</td></tr>').join('')
        + '</tbody></table></div>'
    }
  }

  let s = null
  try { s = await _depoGet('/api/drive/sync') } catch (e) { s = null }
  // A ket kapcsolo allasat a KISZOLGALO mondja meg, nem a HTML-be irt alapertek.
  // Kulonben minden oldalfrissites utan "be"-t mutatna, akkor is, ha ki van
  // kapcsolva -- es a user azt hinne, felmegy a munkaja, pedig nem.
  if (s) {
    const up = document.getElementById('depoSyncUpload')
    const del = document.getElementById('depoSyncDeleteUp')
    if (up) up.checked = s.upload !== false
    if (del) {
      del.checked = s.deleteUp !== false
      // A torles-atvitel a felmeno ag RESZE: ha az ki van kapcsolva, ez a
      // kapcsolo nem csinal semmit. Ne ugy alljon ott, mintha mukodne.
      del.disabled = s.upload === false
      const cim = del.closest('label')
      if (cim) cim.style.opacity = del.disabled ? '.5' : ''
    }
  }
  const list = document.getElementById('depoSyncList')
  if (list && s) {
    // A MENTES-parosok nem ide valok: ott a gep a forras es a Drive a masolat,
    // vagyis pont forditva, mint itt. Egy tablazatban a ket irany
    // osszekeverne, melyik torles hova hat -- sajat kartyajuk van alatta.
    const masolatok = (s.pairs || []).filter((p) => !p.backup)
    if (!masolatok.length) {
      list.innerHTML = '<p class="subtitle">Még egy Drive-mappa sincs kijelölve.</p>'
    } else {
      list.innerHTML = '<div class="ssh-table-wrap"><table class="ssh-table"><thead><tr>'
        + '<th>Fiók</th><th>Mappa</th><th>Hol a gépeden</th><th>Fájl</th><th>Utoljára</th><th></th></tr></thead><tbody>'
        // Ures nev = a TELJES Drive. Ures cella helyett ki KELL mondani, mi az.
        + masolatok.map((p) => '<tr><td>' + escapeHtml(p.account) + '</td>'
          + '<td>' + escapeHtml(p.name || t('dsync.whole_row')) + '</td>'
          // A HELYI utvonal. A kiszolgalo amugy is kiszamolja, es eppen ez az,
          // amit latni kell: "a lackor2 legyen lackor2. igy nincs keveredes."
          // Ha nincs depo, azt is kimondjuk -- nem hagyjuk uresen a cellat.
          + '<td>' + (p.localDir ? '<code>' + escapeHtml(p.localDir) + '</code>' : '<span class="subtitle">' + t('dsync.no_depot_cell') + '</span>') + '</td>'
          + '<td>' + p.files + '</td>'
          // A datum melle az EREDMENY is. Enelkul egy csonka ("részleges")
          // vagy elhasalt futas ugyanugy nezne ki, mint egy sikeres -- pedig
          // ez a mentesuk, es epp azt kell latni, megbizhatnak-e benne.
          + '<td>' + (p.lastRunAt ? escapeHtml(String(p.lastRunAt).slice(0, 16).replace('T', ' ')) : 'még soha')
          + (p.lastResult ? '<br><span class="subtitle">' + escapeHtml(p.lastResult) + '</span>' : '') + '</td>'
          + '<td><button class="btn-secondary btn-compact" data-depo-unsync="' + escapeHtml(p.id) + '">Leválasztás</button></td></tr>').join('')
        + '</tbody></table></div>'
      list.querySelectorAll('[data-depo-unsync]').forEach((b) => {
        b.addEventListener('click', () => _depoRemoveSync(b.getAttribute('data-depo-unsync')))
      })
    }
    _depoShowSyncJob(s.job)
    if (s.job && s.job.running) _depoStartPoll()
  }
  if (s) _depoRenderBackups(s)
  // KULON tolt, a `s`-tol fuggetlenul: ha a `/api/drive/sync` elhasal, a
  // vedelem allapotat akkor is latni kell -- eppen olyankor a legfontosabb.
  await _depoGuardRefresh()
  // Serult beallitas-fajl: a lista ilyenkor URESEN all. Magyarazat nelkul ez ugy
  // nez ki, mintha a felhasznalo maga valasztotta volna le a mappait. Ez a
  // figyelmeztetes a vészfék-doboz UTAN all be, hogy ne nyomja el a job-uzenet.
  if (s && s.configBroken) {
    const fek = document.getElementById('depoSyncBrake')
    if (fek) {
      fek.textContent = '⚠ A szinkron beállítás-fájlja sérült (drive-sync.json). '
        + 'A gépeden lévő fájlokhoz nem nyúltam, és a Drive-ra sem töltök fel semmit, '
        + 'amíg ez így van. A mappákat vedd fel újra — a régi fájlt megőrzöm.'
      fek.style.display = ''
    }
  }
}

/* ======================= TAROLOK (specifikacio 33. pont) =======================
 *
 * A Drive, a Fotok es a Git fiokjai EGY tablazatban. A lenyeg, amit sehol
 * masutt nem lehetett latni: hany tarolo van, melyik el, es melyikben van
 * egyaltalan valami.
 *
 * KULON tolt, a depo-allapottol fuggetlenul -- ugyanaz a tanulsag, mint a
 * fioklegordulonel: ha a /api/depot/status elhasal, ez a tablazat akkor is
 * megjelenik, mert sajat vegpontja van.
 */
var _storagesLoading = false

/** Fajta -> ember-olvashato nev + ikon. Egy helyen, hogy ne csusszon szet. */
var _STORAGE_KINDS = {
  drive: { label: 'Google Drive', icon: '☁' },
  photos: { label: 'Google Fotók', icon: '📷' },
  git: { label: 'Git', icon: '🔀' },
}

function _storageStateText(r) {
  // A sorrend szandekos: eloszor a BAJ, aztan a rendben-allapot. Aki csak
  // ranez, a problemas sorokat lassa meg.
  if (!r.connected) {
    return r.kind === 'git'
      ? '<span class="subtitle">nincs felvéve — csak a mappa van meg</span>'
      : '<span class="subtitle">nincs élő bejelentkezés</span>'
  }
  if (!r.active) return '<span class="subtitle">kikapcsolva</span>'
  if (!r.present) return '<span class="subtitle">még nincs letöltve ide semmi</span>'
  return 'aktív'
}

async function _storagesRefresh() {
  var tbl = document.getElementById('storagesTable')
  if (!tbl || _storagesLoading) return
  _storagesLoading = true
  var d = null
  try {
    d = await _depoGet('/api/storages')
  } catch (e) {
    tbl.innerHTML = '<p class="subtitle">Nem sikerült lekérdezni a tárolókat: '
      + escapeHtml(e && e.message ? e.message : String(e)) + '</p>'
    _storagesLoading = false
    return
  }
  _storagesLoading = false
  if (d.message) {
    tbl.innerHTML = '<p class="subtitle">' + escapeHtml(d.message) + '</p>'
    return
  }
  var rows = d.rows || []
  if (!rows.length) {
    tbl.innerHTML = '<p class="subtitle">Még nincs egyetlen tároló sem. '
      + 'Google-fiókot a Fiókok oldalon köss be; Git-fiókot lent tudsz felvenni.</p>'
    return
  }
  tbl.innerHTML = '<div class="ssh-table-wrap"><table class="ssh-table"><thead><tr>'
    + '<th>Azonosító</th><th>Fajta</th><th>Név</th><th>Hol van</th>'
    + '<th>Tartalom</th><th>Állapot</th><th></th></tr></thead><tbody>'
    + rows.map(function (r) {
      var k = _STORAGE_KINDS[r.kind] || { label: r.kind, icon: '' }
      return '<tr' + (r.active ? '' : ' style="opacity:.6"') + '>'
        + '<td><code>' + escapeHtml(r.id) + '</code></td>'
        + '<td>' + k.icon + ' ' + escapeHtml(k.label) + '</td>'
        + '<td>' + escapeHtml(r.name) + '</td>'
        + '<td><code>' + escapeHtml(r.rel) + '</code></td>'
        + '<td>' + (r.present ? (r.items + ' tétel') : '—') + '</td>'
        + '<td>' + _storageStateText(r)
        // A gh-bol atvett kulcs nem a mienk: ha ott kijelentkeznek, itt is
        // elfogy. Ezert nem hallgatjuk el, hogy honnan jon.
        // Honnan van a kulcs. A kolcsonzottet KULON mondjuk: az egy masik
        // fiok jogosultsaga, es ha ott kijelentkeznek, ez is elfogy.
        + (r.tokenSource === 'gh'
          ? '<br><span style="font-size:11px;opacity:.75">kulcs: a gépen lévő gh-fiókból ('
            + escapeHtml(r.tokenLogin || '') + ')</span>'
          : r.tokenSource === 'kolcson'
          ? '<br><span style="font-size:11px;opacity:.75">kulcs: kölcsön a(z) '
            + escapeHtml(r.tokenLogin || '') + ' fióktól (csak olvasás)</span>'
          : '')
        + '</td>'
        + '<td><div class="stor-acts">'
        + '<button class="btn-secondary btn-compact" data-stor-act="rename" data-kind="' + escapeHtml(r.kind)
        + '" data-account="' + escapeHtml(r.account) + '" data-name="' + escapeHtml(r.name) + '">Átnevezés</button> '
        + '<button class="btn-secondary btn-compact" data-stor-act="toggle" data-kind="' + escapeHtml(r.kind)
        + '" data-account="' + escapeHtml(r.account) + '" data-active="' + (r.active ? '1' : '0') + '">'
        + (r.active ? 'Kikapcsolás' : 'Bekapcsolás') + '</button> '
        + '<button class="btn-secondary btn-compact" data-stor-act="check" data-kind="' + escapeHtml(r.kind)
        + '" data-account="' + escapeHtml(r.account) + '">Ellenőrzés</button>'
        // A git-fiok nem kesz a nevfelvetellel: kell hozza kulcs, es le kell
        // huzni a repoit. Mindketto ITT, a soraban erheto el.
        + (r.kind === 'git'
          ? ' <button class="btn-secondary btn-compact" data-stor-act="token" data-kind="git" data-account="'
            + escapeHtml(r.account) + '">' + (r.connected ? '🔑 Kulcs' : '🔑 Kulcs kell') + '</button>'
            + ' <button class="btn-primary btn-compact" data-stor-act="pull" data-kind="git" data-account="'
            + escapeHtml(r.account) + '">⬇ Repók le</button>'
            // Fel lehetett venni fiokot, levenni nem -- csak kikapcsolni,
            // amitol a sor ott maradt. Ami feleslegesen ott all, azt egyszer
            // valaki osszekeveri azzal, ami kell.
            + ' <button class="btn-secondary btn-compact" data-stor-act="delete" data-kind="git" data-account="'
            + escapeHtml(r.account) + '" style="color:#c0392b">🗑 Fiók törlése</button>'
          : '')
        + '</div></td></tr>'
    }).join('')
    + '</tbody></table></div>'
}

function _storagesSay(msg) {
  var el = document.getElementById('storagesStatus')
  if (el) el.textContent = msg || ''
}

/**
 * Egy kattintas-kezelo az EGESZ tablazatra.
 *
 * Azert delegalva, mert a sorok minden frissiteskor ujra keszulnek: soronkent
 * felkotott kezelok eseten az ujrarajzolas utan a gombok nemak lennenek.
 */
async function _storagesClick(ev) {
  var btn = ev.target && ev.target.closest ? ev.target.closest('[data-stor-act]') : null
  if (!btn) return
  ev.preventDefault()
  var act = btn.getAttribute('data-stor-act')
  var kind = btn.getAttribute('data-kind')
  var account = btn.getAttribute('data-account')
  try {
    if (act === 'rename') {
      var mostani = btn.getAttribute('data-name') || account
      var uj = window.prompt('Mi legyen a tároló neve? (A mappa nem mozdul el.)', mostani)
      if (uj === null) return
      await _depoPost('/api/storages/rename', { kind: kind, account: account, name: uj })
      _storagesSay('Átnevezve.')
    } else if (act === 'toggle') {
      var aktiv = btn.getAttribute('data-active') === '1'
      var r = await _depoPost('/api/storages/active', { kind: kind, account: account, active: !aktiv })
      _storagesSay(r.message || '')
    } else if (act === 'check') {
      var c = await _depoPost('/api/storages/check', { kind: kind, account: account })
      _storagesSay(c.message || '')
    } else if (act === 'token') {
      // A kulcsot a szerver AZONNAL ellenorzi a GitHubnal, es csak akkor
      // menti, ha tenyleg mukodik. Egy elgepelt kulcs csendes eltarolasa a
      // legrosszabb: minden zoldnek latszana, es csak hetek mulva derulne ki.
      var tok = await _storagesAskToken(account)
      if (tok === null) return
      _storagesSay('Ellenőrzöm a kulcsot a GitHubnál…')
      var tr = await _depoPost('/api/storages/git-token',
        tok.trim() ? { account: account, token: tok.trim() } : { account: account, remove: true })
      _storagesSay(tr.message || 'Kész.')
    } else if (act === 'delete') {
      // KET KORBEN. Eloszor a szerver MEGMERI, mi van a fiok alatt, es azt
      // irja ki; a "biztos?" csak azutan jon, hogy latod, mit veszitesz.
      // Ha van bent fel nem toltott munka, a szerver force-szal sem torol.
      var d1 = await _depoPost('/api/storages/git-delete', { account: account })
      if (d1.ok) { _storagesSay(d1.message || 'Levéve.'); await _storagesRefresh(); return }
      if (!d1.needsConfirm) { _storagesSay(d1.message || 'Nem sikerült.'); return }
      if (!window.confirm(d1.message)) { _storagesSay('Rendben, nem törlöm.'); return }
      var d2 = await _depoPost('/api/storages/git-delete', { account: account, force: true })
      _storagesSay(d2.message || 'Kész.')
    } else if (act === 'pull') {
      _storagesSay('Lehúzás folyamatban… nagy repóknál ez percekig tarthat.')
      var pr = await _depoPost('/api/storages/git-pull', { account: account })
      _storagesSay(pr.message || 'Kész.')
    }
  } catch (e) {
    _storagesSay('Nem sikerült: ' + (e && e.message ? e.message : e))
  }
  await _storagesRefresh()
}

/**
 * Szinkron MOST, kezzel.
 *
 * Az automatikus futas 6 orankent jar, de aki eppen most tolt fel valamit a
 * masik gepen, ne varjon orakat. Ugyanaz a kod fut, ugyanazokkal a
 * ovintezkedesekkel -- nincs kulon "kezi" ut, amit kulon kellene hibazni.
 */
/**
 * A kulcs bekerese sajat ablakban.
 *
 * Miert nem `prompt`: abba nem lehet linket tenni, es a "menj a Settings ala,
 * onnan Developer settings, onnan..." utvonalat a felhasznalo minden
 * alkalommal ujra kikeresi. Itt egy kattintas, es pontosan a keszito lapon
 * van, `repo` jogosultsaggal elore bejelolve.
 *
 * A mezo `type=password`: a kulcs valaki mas kepernyojen vagy egy
 * kepernyokepen ne maradjon ott olvashatoan.
 *
 * @returns a beirt kulcs, '' ha torolni kell, vagy null ha megse.
 */
function _storagesAskToken(account) {
  return new Promise(function (resolve) {
    // A lap KET `.modal-overlay` szabalyt hordoz; a korabbi csak `.active`
    // mellett mutatja meg az ablakot. Ezert kell ide is az `active`.
    var ov = document.createElement('div')
    ov.className = 'modal-overlay active'
    var url = 'https://github.com/settings/tokens/new?scopes=repo&description=Marveen+-+'
      + encodeURIComponent(account)
    ov.innerHTML = '<div class="modal-content" style="max-width:560px;padding:18px">'
      + '<h3 style="margin:0 0 10px">🔑 Hozzáférési kulcs — ' + escapeHtml(account) + '</h3>'
      + '<p class="subtitle" style="margin:0 0 10px">A GitHub „Personal Access Token”-je. '
      + 'A gomb pontosan a készítő oldalra visz, a <code>repo</code> jogosultság előre bejelölve — '
      + 'ott csak a <b>Generate token</b> gombot kell megnyomnod, aztán a kapott kulcsot ide beilleszteni.</p>'
      + '<p style="margin:0 0 12px"><a class="btn-primary" href="' + url + '" target="_blank" rel="noopener noreferrer" '
      + 'style="display:inline-block;text-decoration:none">🔗 Kulcs készítése a GitHubon →</a></p>'
      + '<input type="password" id="storTokInput" placeholder="ghp_… vagy github_pat_…" autocomplete="off" '
      + 'style="width:100%;box-sizing:border-box;padding:8px;font-family:monospace">'
      + '<p style="margin:8px 0 0;font-size:12px;opacity:.75">A kulcs a Marveen zárt tárolójában marad: '
      + 'nem kerül az életfába, nem kerül a repó beállításai közé, és a felület sem kapja vissza. '
      + 'Üresen hagyva és mentve a meglévő kulcsot törlöm.</p>'
      + '<div style="margin-top:14px;text-align:right">'
      + '<button class="btn-secondary" id="storTokCancel">Mégse</button> '
      + '<button class="btn-primary" id="storTokOk">Mentés</button></div></div>'
    document.body.appendChild(ov)
    var inp = ov.querySelector('#storTokInput')
    if (inp) inp.focus()
    function close(val) { ov.remove(); resolve(val) }
    ov.querySelector('#storTokCancel').onclick = function () { close(null) }
    ov.querySelector('#storTokOk').onclick = function () { close(inp ? inp.value : '') }
    // A hattterre kattintas = megse. Elgepelt kulcs mentese rosszabb, mint
    // egy elvesztett gepeles, ezert a "veletlen" kimenet a megse.
    ov.onclick = function (e) { if (e.target === ov) close(null) }
    ov.onkeydown = function (e) {
      if (e.key === 'Escape') close(null)
      if (e.key === 'Enter' && e.target === inp) close(inp.value)
    }
  })
}

async function _storagesGitSync() {
  var el = document.getElementById('storagesGitSyncState')
  if (el) el.textContent = 'Szinkronizálás… nagy repóknál ez percekig tarthat.'
  try {
    var r = await _depoPost('/api/storages/git-sync', {})
    _storagesShowSync(r.last)
    _storagesSay(r.message || 'Kész.')
  } catch (e) {
    if (el) el.textContent = 'Nem sikerült: ' + (e && e.message ? e.message : e)
  }
  await _storagesRefresh()
}

/** Az utolso szinkron emberi osszefoglaloja -- a kihagyott repok INDOKKAL. */
function _storagesShowSync(last) {
  var el = document.getElementById('storagesGitSyncState')
  if (!el) return
  if (!last) { el.textContent = 'Automatikus szinkron: még nem futott (indulás után 5 perccel indul).'; return }
  var mikor = new Date(last.finishedAt).toLocaleString('hu-HU')
  var txt = 'Utolsó szinkron: ' + mikor + ' — ' + (last.results || []).length + ' repó, '
    + last.updated + ' frissült, ' + last.skipped + ' kimaradt, ' + last.errors + ' hibázott.'
  el.innerHTML = escapeHtml(txt)
  // A kimaradtakat es a hibakat KIIRJUK. Egy nema "3 kimaradt" arra tanitana a
  // felhasznalot, hogy ne is nezze meg -- pedig eppen ott van a tennivalo.
  var gond = (last.results || []).filter(function (r) { return r.state === 'skipped' || r.state === 'error' })
  if (gond.length) {
    el.innerHTML += '<br>' + gond.map(function (r) {
      return '<span style="opacity:.85">• ' + escapeHtml(r.rel) + ' — ' + escapeHtml(r.message) + '</span>'
    }).join('<br>')
  }
}

async function _storagesAddGit() {
  var inp = document.getElementById('storagesGitName')
  var name = inp ? inp.value.trim() : ''
  if (!name) { _storagesSay('Írd be a fiók nevét.'); return }
  try {
    await _depoPost('/api/storages/git-account', { account: name })
    if (inp) inp.value = ''
    // A puszta nevfelvetel meg semmit nem hoz le -- mondjuk is meg, mi jon.
    _storagesSay('Felvéve. Most add meg a hozzáférési kulcsot a sorában („Kulcs megadása”), '
      + 'utána a „Repók lehúzása” gombbal jönnek le a repói. Onnantól 6 óránként magától frissül.')
  } catch (e) {
    _storagesSay('Nem sikerült: ' + (e && e.message ? e.message : e))
  }
  await _storagesRefresh()
}

// Eppen tolt-e a fioklista? (`var`, hogy a korai hivas se dobjon hibat -- lasd
// a _depoPoll esetet a web-boot-order.test.ts-ben.)
var _depoAccountsLoading = false

/**
 * A Drive-fiokok legordulojet tolti fel.
 *
 * KULON fuggveny, es a depo-allapot lekerdezesetol FUGGETLENUL fut. Korabban ez
 * a _depoRefresh legvegen allt: ha a /api/depot/status hibara futott (ott
 * `return` all), a legordulo URESEN maradt, es a "Drive-mappa kiválasztása"
 * gomb csak annyit mondott, hogy "Előbb válaszd ki, melyik fiókból nézzük" --
 * miközben nem is volt mit valasztani. A ket dolognak semmi koze egymashoz.
 */
async function _depoLoadSyncAccounts() {
  const sel = document.getElementById('depoSyncAccount')
  // A mentes-kartya legorduloje UGYANEBBOL a listabol el: ket kulon lekerdezes
  // ket kulon pillanatot latna, es a ket kartya mas fiokokat kinalna.
  const sel2 = document.getElementById('depoBackupAccount')
  if (!sel || (sel.options.length && (!sel2 || sel2.options.length)) || _depoAccountsLoading) return
  // A _depoRefresh tobb helyrol is jon (Frissítés gomb, munka-figyelo, mentes
  // utan). Ket EGYSZERRE futo toltes ujrarajzolna a legordulot, ami VISSZAALLITJA
  // a kivalasztott fiokot az elsore -- eppen amikor a user mar mast valasztott.
  _depoAccountsLoading = true
  const picked = document.getElementById('depoSyncPicked')
  try {
    const acc = await _depoGet('/api/drive/accounts')
    const lista = acc.accounts || []
    const opciok = lista.map((a) => '<option value="' + escapeHtml(a) + '">' + escapeHtml(a) + '</option>').join('')
    sel.innerHTML = opciok
    if (sel2) sel2.innerHTML = opciok
    // Ha egyetlen fiok sincs bekotve, azt KI KELL MONDANI: ures legordulovel a
    // user azt hinne, elromlott valami.
    if (!lista.length && picked) picked.textContent = t('dsync.no_accounts')
  } catch (e) {
    // Nema nyeles helyett latszik a hiba oka -- kulonben csak egy ures
    // legordulot lat, es nincs mibol kitalalnia, mi a teendo.
    if (picked) picked.textContent = t('dsync.accounts_failed', { error: (e && e.message) ? e.message : String(e) })
  } finally {
    // Hiba utan is fel kell oldani, kulonben a Frissítés gomb sem probalna ujra.
    _depoAccountsLoading = false
  }
}

function _depoShowSyncJob(job) {
  const el = document.getElementById('depoSyncStatus')
  if (!el) return
  if (!job) { el.textContent = ''; return }
  // A szinkron 2026-08-15 ota KETIRANYU. Ha csak a letoltest mutatnank, a
  // felhasznalo nem latna, hogy a Marveen IRT is a Drive-jara -- pedig eppen
  // azt kell tudnia ellenorizni.
  const fel = job.uploaded || 0
  const kuka = job.trashed || 0
  if (job.running) {
    el.textContent = 'Szinkronizálás: ' + job.downloaded + ' lejött, ' + fel + ' felment · ' + _depoBytes(job.bytes)
      + (job.current ? ' · ' + job.current : '')
  } else {
    el.textContent = 'Kész: ' + job.downloaded + ' letöltve, ' + fel + ' feltöltve, '
      + job.upToDate + ' már naprakész volt'
      + (kuka ? ', ' + kuka + ' a Drive Kukájába került' : '')
      + (job.failed ? ', ' + job.failed + ' nem sikerült' : '')
  }
  // A vészfék NEM sikkadhat el a sor vegen: ilyenkor a Drive es a gep NEM
  // egyezik, es a felhasznalonak kozbe kell lepnie.
  const fek = document.getElementById('depoSyncBrake')
  if (fek) {
    if (job.deleteBrake) {
      fek.textContent = t('dsync.brake_warn', {
        n: job.deleteBrake.wouldDelete,
        tracked: job.deleteBrake.tracked,
      })
      fek.style.display = ''
    } else {
      fek.style.display = 'none'
    }
  }
}

// Amig fut valami, masodpercenkent kerdezunk. A poll leall, ha mindketto
// befejezodott -- egy uresen ketyego idozito feleslegesen ebreszti a gepet.
function _depoStartPoll() {
  if (_depoPoll) return
  _depoPoll = setInterval(async () => {
    let b = null
    try { b = (await _depoGet('/api/drive/sync')).job } catch (e) { /* atmeneti hiba: kovetkezo korben ujra */ }
    _depoShowSyncJob(b)
    if (!(b && b.running)) { _depoStopPoll(); _depoRefresh() }
  }, 1500)
}

async function _depoAddSync() {
  const account = (document.getElementById('depoSyncAccount') || {}).value || ''
  const folderId = ((document.getElementById('depoSyncFolderId') || {}).value || '').trim()
  // A nevet a valaszto tolti ki (a Drive-mappa nevevel), rejtett mezobe: senki
  // nem gepeli es nem is irja at.
  const name = ((document.getElementById('depoSyncName') || {}).value || '').trim()
  // Az azonositot mar nem gepeli senki: ha nincs, akkor a valasztas hianyzik.
  if (!folderId) { showToast(t('dsync.pick_first')); return }
  try {
    await _depoPost('/api/drive/sync/add', { account, folderId, name })
    _depoClearDrivePick()
    await _depoRefresh()
  } catch (e) {
    showToast((e && e.message) ? e.message : t('dsync.add_failed'))
  }
}

/* ============ A GEPEM MENTESE A DRIVE-RA (#47 kartya) =====================
 *
 * A masik irany. A Drive-kartya a felhot hozza LE, ez a munkadat viszi FEL.
 * MERVE 2026-08-28: a raktarban 9356 fajl / 11 GB all ugy, hogy sehol nincs
 * masodpeldanya -- a git-tarolok kulon agban (`Rendszer`) vannak, a szemelyes
 * ag pedig nem git-elheto.
 *
 * A BEKOTES NEM INDUL EL MERES NELKUL. Eloszor megmerjuk, hany fajl es mennyi
 * bajt menne fel, es megkerdezzuk a Google-tol, van-e ra szabad hely. Ezt a
 * funkciot nem lehet ugy elinditani, hogy a merteket a Boss csak utana latja
 * meg: bekotes utan a gep magatol kezd feltolteni, minden ejjel.
 */

/** Az UTOLSO sikeres meres -- mihez tartozott (ag + fiok). */
var _depoBackupMeres = null

function _depoBackupValaszt() {
  const b = document.getElementById('depoBackupBranch')
  const a = document.getElementById('depoBackupAccount')
  return { path: (b && b.value) || '', account: (a && a.value) || '' }
}

/** A "Mentés bekötése" CSAK a most megmert valasztasra ehet ra. */
function _depoBackupGombAllapot() {
  const btn = document.getElementById('depoBackupAddBtn')
  if (!btn) return
  const v = _depoBackupValaszt()
  const m = _depoBackupMeres
  btn.disabled = !(m && m.path === v.path && m.account === v.account)
}

/**
 * A raktar agai a legorduloben.
 *
 * A `Rendszer` ag BENNE VAN, de letiltva: ha egyszeruen kihagynank, a Boss azt
 * hinne, eltunt, es keresne. Igy latszik, hogy szandekosan nem menthető.
 */
async function _depoBackupLoadBranches() {
  const sel = document.getElementById('depoBackupBranch')
  if (!sel || sel.options.length) return
  const jel = document.getElementById('depoBackupNote')
  let d = null
  try {
    d = await _depoGet('/api/drive/sync/local-branches')
  } catch (e) {
    if (jel) jel.textContent = t('dbackup.branches_failed', { error: (e && e.message) ? e.message : String(e) })
    return
  }
  // HAROM eset, es MIND MAS teendo. Az ures legordulo onmagaban nem mondana
  // meg, hogy nincs raktar, vagy hogy van, csak nem latunk oda.
  if (!d.configured) { if (jel) jel.textContent = t('dbackup.no_depot'); return }
  if (!d.reachable) { if (jel) jel.textContent = t('dbackup.unreachable', { p: d.root || '' }); return }
  const opts = ['<option value="">' + escapeHtml(t('dbackup.whole')) + '</option>']
  ;(d.branches || []).forEach((b) => {
    if (b.blocked) {
      opts.push('<option value="' + escapeHtml(b.path) + '" disabled>'
        + escapeHtml(b.name) + ' — ' + escapeHtml(t('dbackup.blocked')) + '</option>')
      return
    }
    opts.push('<option value="' + escapeHtml(b.path) + '">' + escapeHtml(b.name) + '</option>')
    ;(b.children || []).forEach((c) => {
      opts.push('<option value="' + escapeHtml(c.path) + '">\u00a0\u00a0\u00a0\u00a0'
        + escapeHtml(c.name) + '</option>')
    })
  })
  sel.innerHTML = opts.join('')
  if (jel) jel.textContent = ''
  _depoBackupGombAllapot()
}

/** MERES a bekotes elott. Minden szam merve van, egy sincs becsulve. */
async function _depoBackupMeasure() {
  const v = _depoBackupValaszt()
  const box = document.getElementById('depoBackupPreview')
  const btn = document.getElementById('depoBackupPreviewBtn')
  _depoBackupMeres = null
  _depoBackupGombAllapot()
  if (box) box.innerHTML = '<p class="subtitle">' + escapeHtml(t('dbackup.measuring')) + '</p>'
  if (btn) btn.disabled = true
  let d = null
  try {
    d = await _depoGet('/api/drive/sync/local-preview?path=' + encodeURIComponent(v.path)
      + '&account=' + encodeURIComponent(v.account))
  } catch (e) {
    if (box) box.innerHTML = '<p class="subtitle">' + escapeHtml((e && e.message) ? e.message : String(e)) + '</p>'
    if (btn) btn.disabled = false
    return
  }
  if (btn) btn.disabled = false
  _depoBackupMeres = { path: v.path, account: v.account }
  _depoBackupGombAllapot()
  const sorok = []
  if (!d.files) {
    // A NULLA KET DOLGOT JELENTHET. Itt magat a forrast kerdeztuk meg: a mappa
    // LETEZIK es OLVASHATO (kulonben 404 vagy csonka jelzes jonne), tehat ez
    // valodi ures -- ezt ki is mondjuk, nem hagyjuk a "0 fájl" szamra.
    sorok.push(t('dbackup.empty'))
  } else {
    sorok.push(t('dbackup.sum', { n: String(d.files), b: _depoBytes(d.bytes), f: d.driveFolder }))
  }
  if (d.excluded) sorok.push(t('dbackup.excluded', { b: d.excluded }))
  if (d.files > d.perRun) sorok.push(t('dbackup.runs', { r: String(d.runs), p: String(d.perRun) }))
  if (d.tooBig) sorok.push(t('dbackup.too_big', { n: String(d.tooBig), m: String(d.maxFileMb) }))
  if (d.unreadable) sorok.push(t('dbackup.unreadable_files', { n: String(d.unreadable) }))
  if (d.truncated) sorok.push(t('dbackup.truncated'))
  const q = d.quota || {}
  if (q.fajta === 'ismert') {
    sorok.push(q.free >= d.bytes
      ? t('dbackup.quota_ok', { a: v.account, f: _depoBytes(q.free) })
      : t('dbackup.quota_short', { a: v.account, f: _depoBytes(q.free), n: _depoBytes(d.bytes - q.free) }))
  } else if (q.fajta === 'korlatlan') {
    sorok.push(t('dbackup.quota_unlimited', { a: v.account }))
  } else if (q.fajta === 'nem_kerdezheto') {
    // A HIBA OKAT NEM TALALGATJUK: amit a Google mondott, azt irjuk ki.
    sorok.push(t('dbackup.quota_error', { e: String(q.error || '') }))
  } else {
    sorok.push(t('dbackup.quota_no_account'))
  }
  if (box) box.innerHTML = sorok.map((x) => '<p class="subtitle" style="margin:2px 0">' + escapeHtml(x) + '</p>').join('')
}

async function _depoBackupAdd() {
  const v = _depoBackupValaszt()
  if (!v.account) { showToast(t('dbackup.need_account')); return }
  try {
    await _depoPost('/api/drive/sync/add-local', { account: v.account, path: v.path })
    _depoBackupMeres = null
    const box = document.getElementById('depoBackupPreview')
    if (box) box.innerHTML = ''
    _depoBackupGombAllapot()
    await _depoRefresh()
  } catch (e) {
    showToast((e && e.message) ? e.message : t('dbackup.add_failed'))
  }
}

function _depoRenderBackups(s) {
  const host = document.getElementById('depoBackupList')
  if (!host) return
  const mentesek = ((s && s.pairs) || []).filter((p) => p.backup)
  if (!mentesek.length) {
    host.innerHTML = '<p class="subtitle">' + escapeHtml(t('dbackup.none')) + '</p>'
    return
  }
  host.innerHTML = '<div class="ssh-table-wrap"><table class="ssh-table"><thead><tr>'
    + '<th>' + escapeHtml(t('dbackup.col_what')) + '</th>'
    + '<th>' + escapeHtml(t('dbackup.col_account')) + '</th>'
    + '<th>' + escapeHtml(t('dbackup.col_drive')) + '</th>'
    + '<th>' + escapeHtml(t('dbackup.col_files')) + '</th>'
    + '<th>' + escapeHtml(t('dbackup.col_last')) + '</th><th></th></tr></thead><tbody>'
    + mentesek.map((p) => '<tr>'
      + '<td><code>' + escapeHtml(p.localPath || t('dbackup.whole')) + '</code></td>'
      + '<td>' + escapeHtml(p.account) + '</td>'
      + '<td>' + escapeHtml(p.name || '') + '</td>'
      + '<td>' + p.files + '</td>'
      // A datum melle az EREDMENY is: egy felig felment ("folyamatban") vagy
      // elhasalt mentes kulonben ugyanugy nezne ki, mint egy kesz.
      + '<td>' + (p.lastRunAt ? escapeHtml(String(p.lastRunAt).slice(0, 16).replace('T', ' ')) : escapeHtml(t('dbackup.never')))
      + (p.lastResult ? '<br><span class="subtitle">' + escapeHtml(p.lastResult) + '</span>' : '') + '</td>'
      + '<td><button class="btn-secondary btn-compact" data-depo-unbackup="' + escapeHtml(p.id) + '">'
      + escapeHtml(t('dbackup.unbind')) + '</button></td></tr>').join('')
    + '</tbody></table></div>'
  host.querySelectorAll('[data-depo-unbackup]').forEach((b) => {
    b.addEventListener('click', () => _depoRemoveBackup(b.getAttribute('data-depo-unbackup')))
  })
}

async function _depoRemoveBackup(id) {
  // A megerosites KIMONDJA, mi marad meg: a Drive-on levo mentes NEM tunik el,
  // csak nem frissul tovabb. Enelkul a "Kivétel" gomb torlesnek latszana.
  if (!confirm(t('dbackup.unbind_confirm'))) return
  try {
    await _depoPost('/api/drive/sync/remove', { id })
    await _depoRefresh()
  } catch (e) {
    showToast((e && e.message) ? e.message : t('dbackup.unbind_failed'))
  }
}

async function _depoRemoveSync(id) {
  if (!confirm('Leválasztod ezt a mappát? A már letöltött fájlok a gépeden maradnak.')) return
  try {
    await _depoPost('/api/drive/sync/remove', { id })
    await _depoRefresh()
  } catch (e) {
    showToast((e && e.message) ? e.message : 'Nem sikerült leválasztani')
  }
}

/**
 * A ket veszelyes kapcsolo mentese.
 *
 * A felmeno ag IR a Drive-ra, a torles-atvitel pedig a Kukaba tesz odafent.
 * Amit nem lehet a kepernyon ellenorizni ES kikapcsolni, arrol a felhasznalo nem
 * tudja eldonteni, mit tesz a neveben -- ezert van ez a ket kapcsolo.
 *
 * Ha a mentes elhasal, VISSZAALLITJUK a jelolonegyzetet. Kulonben a kepernyon
 * "ki" allna, a kiszolgalon meg "be": pont az a hazugsag, ami ellen a kapcsolo van.
 */
async function _depoSaveSyncSettings() {
  const up = document.getElementById('depoSyncUpload')
  const del = document.getElementById('depoSyncDeleteUp')
  if (!up || !del) return
  const kert = { upload: !!up.checked, deleteUp: !!del.checked }
  try {
    await _depoPost('/api/drive/sync/settings', kert)
  } catch (e) {
    up.checked = !kert.upload
    del.checked = !kert.deleteUp
    showToast((e && e.message) ? e.message : 'Nem sikerült elmenteni a beállítást')
    return
  }
  // Nem toast-olunk sikernel: a jelolonegyzet allasa maga a visszajelzes.
  await _depoRefresh()
}

async function _depoRunSync() {
  const btn = document.getElementById('depoSyncRunBtn')
  if (btn) btn.disabled = true
  try {
    const r = await _depoPost('/api/drive/sync/run', {})
    _depoShowSyncJob(r.job)
    _depoStartPoll()
  } catch (e) {
    showToast((e && e.message) ? e.message : 'Nem sikerült elindítani a szinkronizálást')
  } finally {
    if (btn) btn.disabled = false
  }
}

// ===================== MARVIN INTEZO =====================
// Egy fajlkezelo a Marveen fajahoz, forrasjelvenyekkel.
//
// Boss, 2026-08-21: "mindig lathato legyen, hogy egy fajl vagy mappa
// fizikailag honnan szarmazik / hol van tarolva: helyi gep, Google Drive,
// Google Photos, Git stb. Es nem akarunk ebbol valami NASA-rendszert."
//
// Ezert nincs itt fa-panel, nincs tobb-ablakos elrendezes es nincs
// draggelheto oszlop: egy lista, morzsak felul, es a nev elott egy kicsi jel.

/** Hol allunk eppen a faban. Ures = a gyoker. */
let _intezoPath = ''
/** A kijelolt tetel (az informacios panel errol szol). */
let _intezoSelected = null
/** Az athelyezes celjat / a papir helyet valaszto mod, ha eppen fut. */
let _intezoSearchTimer = null

/**
 * A jelveny-mod a bongeszoben marad, mert ez NEZET, nem adat.
 * Alapertelmezes: ikon -- Boss valasztasa ("Alapertelmezeskent en az ikonos
 * jelolest hasznalnam").
 */
function _intezoBadgeMode() {
  try { return localStorage.getItem('intezoBadgeMode') || 'icon' } catch (e) { return 'icon' }
}
function _intezoSetBadgeMode(mode) {
  try { localStorage.setItem('intezoBadgeMode', mode) } catch (e) { /* privat mod: marad a memoriaban */ }
  _intezoRender()
}

async function _intezoGet(url) {
  if (url.indexOf('/api/life/') === 0 && url.indexOf('lang=') < 0) {
    url += (url.indexOf('?') < 0 ? '?' : '&') + 'lang=' + (window._lang || 'hu')
  }
  const res = await fetch(url)
  const data = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(data.message || data.error || ('hiba: ' + res.status))
  return data
}

async function loadIntezoPage() {
  const bind = (id, ev, fn) => {
    const el = document.getElementById(id)
    if (el && !el._intezoBound) { el._intezoBound = 1; el.addEventListener(ev, fn) }
  }
  bind('intezoRefreshBtn', 'click', () => _intezoOpen(_intezoPath))
  bind('intezoUpBtn', 'click', () => _intezoUp())
  bind('intezoEnsureBtn', 'click', () => _intezoEnsure())
  bind('intezoMkdirBtn', 'click', () => _intezoMkdir())
  bind('intezoMoveBtn', 'click', () => _intezoStartPick('move'))
  // A lefixalt fejlec muveletsava. Delegalt kezelo: a gombok ujrarajzolasa
  // (disabled allapot) nem szakitja el a figyelot.
  const abar = document.getElementById('intezoActionBar')
  if (abar && !abar._intezoBound) { abar._intezoBound = 1; abar.addEventListener('click', _intezoActionClick) }
  bind('intezoPhysPickBtn', 'click', () => _intezoStartPick('physical'))
  bind('intezoPhysSaveBtn', 'click', () => _intezoSavePhysical())
  bind('intezoConfigBtn', 'click', () => _intezoCfgOpen())
  bind('intezoConfigBtn2', 'click', () => _intezoCfgOpen())
  bind('intezoCfgCloseBtn', 'click', () => { const c = document.getElementById('intezoConfigCard'); if (c) c.hidden = true })
  bind('intezoAddPersonBtn', 'click', () => _intezoCfgAddPerson())
  bind('intezoAddCompanyBtn', 'click', () => _intezoCfgAddCompany())
  bind('intezoCfgSaveBtn', 'click', () => _intezoCfgSave())
  bind('intezoMountAddBtn', 'click', () => _intezoAddMount())
  bind('intezoMountDelBtn', 'click', () => _intezoRemoveMount())
  bind('intezoPhysHas', 'change', () => {
    const on = document.getElementById('intezoPhysHas').checked
    const f = document.getElementById('intezoPhysFields')
    if (f) f.hidden = !on
  })
  bind('intezoToDepoBtn', 'click', (e) => { e.preventDefault(); switchPage('depo') })
  bind('intezoSearch', 'input', () => {
    // Gepeles kozben nem inditunk minden betunel keresest: egy nagy fa
    // bejarasa igy tizszer futna le feleslegesen.
    clearTimeout(_intezoSearchTimer)
    _intezoSearchTimer = setTimeout(() => _intezoSearch(), 350)
  })
  document.querySelectorAll('input[name="intezoBadge"]').forEach((r) => {
    if (r._intezoBound) return
    r._intezoBound = 1
    r.addEventListener('change', () => _intezoSetBadgeMode(r.value))
  })
  const mode = _intezoBadgeMode()
  const active = document.querySelector('input[name="intezoBadge"][value="' + mode + '"]')
  if (active) active.checked = true

  // BEERKEZO-LANC (specifikacio 22-23.).
  bind('inboxRefreshBtn', 'click', () => _inboxRefresh())
  bind('inboxPreviewBtn', 'click', () => _inboxPreview())
  bind('inboxFileBtn', 'click', () => _inboxFile())
  var ibItems = document.getElementById('inboxItems')
  if (ibItems && !ibItems._intezoBound) {
    ibItems._intezoBound = 1
    // Delegalva: a lista minden frissiteskor ujra keszul.
    ibItems.addEventListener('change', () => _inboxSyncButtons())
  }
  var ibCh = document.getElementById('inboxChainChoices')
  if (ibCh && !ibCh._intezoBound) {
    ibCh._intezoBound = 1
    ibCh.addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-inbox-step]')
      if (b) _inboxChain(b.getAttribute('data-inbox-step'))
    })
  }

  await _intezoLegend()
  await _intezoMountOptions()
  await _intezoStatus()
  await _intezoOpen(_intezoPath)
  await _inboxRefresh()
}

/* ================ BEERKEZO-LANC (specifikacio 22-23. pont) ================
 *
 * A lanc lepeseit a KISZOLGALO adja, mert a lanc MAGA A FA. A bongeszo nem
 * tart sajat kategoria-listat: ha a fa bovul, a valasztek magatol kovetni
 * fogja.
 *
 * Amit ez a resz SOSEM tesz: nem valaszt gazdat a felhasznalo helyett (23.
 * pont 1. szabaly). A "Besorolás ide" gomb addig szurke, amig nincs kijelolt
 * tetel ES kivalasztott cel.
 */
var _inboxTarget = ''

async function _inboxRefresh() {
  var st = document.getElementById('inboxStatus')
  var box = document.getElementById('inboxItems')
  if (!st && !box) return
  var d = null
  try {
    d = await _intezoGet('/api/life/inbox/items?lang=' + (window._lang || 'hu'))
  } catch (e) {
    // A TENYLEGES hibauzenet. Nem talalgatunk okot.
    if (st) st.textContent = t('inbox.load_failed') + ' ' + ((e && e.message) ? e.message : String(e))
    if (box) box.innerHTML = ''
    return
  }
  // A kiszolgalo mondja meg, MIERT ures -- nincs depo / nincs fa / nem
  // olvashato / tenyleg ures. A bongeszo ezt nem tudja eldonteni.
  if (st) st.textContent = d.message || ''
  if (box) {
    var items = d.items || []
    box.innerHTML = !items.length ? '' : items.map(function (it) {
      return '<label style="display:flex;gap:8px;align-items:flex-start;padding:4px 0">'
        + '<input type="checkbox" class="inbox-item" value="' + escapeAttr(it.name) + '"'
        + (it.credentialWarning ? ' disabled' : '') + '>'
        + '<span><strong>' + escapeHtml(it.name) + '</strong>'
        + (it.sizeHuman ? ' <span class="subtitle">· ' + escapeHtml(it.sizeHuman) + '</span>' : '')
        + (it.credentialWarning
          ? '<br><span class="subtitle" style="color:var(--warning, #c77)">🔒 ' + escapeHtml(it.credentialWarning) + '</span>'
          : '')
        + '</span></label>'
    }).join('')
  }
  await _inboxChain(d.reason === 'ok' ? '' : null)
  _inboxSyncButtons()
}

async function _inboxChain(rel) {
  var box = document.getElementById('inboxChainBox')
  if (!box) return
  if (rel === null) { box.hidden = true; return }
  var d = null
  try {
    d = await _intezoGet('/api/life/inbox/chain?lang=' + (window._lang || 'hu')
      + '&rel=' + encodeURIComponent(rel || ''))
  } catch (e) {
    box.hidden = true
    return
  }
  box.hidden = false
  _inboxTarget = d.rel || ''
  var crumb = document.getElementById('inboxChainCrumb')
  var q = document.getElementById('inboxChainQuestion')
  var ch = document.getElementById('inboxChainChoices')
  var note = document.getElementById('inboxChainNote')
  if (crumb) {
    crumb.textContent = (_inboxTarget
      ? t('inbox.here') + ' ' + d.display
      : t('inbox.start'))
  }
  if (q) q.textContent = d.question || ''
  if (ch) {
    var vissza = _inboxTarget
      ? '<button class="btn-secondary btn-compact" data-inbox-step="' + escapeAttr(_inboxUpRel(_inboxTarget)) + '">↑ ' + escapeHtml(t('inbox.back')) + '</button>'
      : ''
    ch.innerHTML = vissza + (d.choices || []).map(function (c) {
      return '<button class="btn-secondary btn-compact" data-inbox-step="' + escapeAttr(c.rel) + '"'
        + (c.hint ? ' title="' + escapeAttr(c.hint) + '"' : '') + '>' + escapeHtml(c.name) + '</button>'
    }).join('')
  }
  if (note) note.textContent = d.message || ''
  _inboxSyncButtons()
}

function _inboxUpRel(rel) {
  var i = String(rel || '').lastIndexOf('/')
  return i < 0 ? '' : rel.slice(0, i)
}

function _inboxSelected() {
  var out = []
  document.querySelectorAll('.inbox-item:checked').forEach(function (c) { out.push(c.value) })
  return out
}

function _inboxSyncButtons() {
  var btn = document.getElementById('inboxFileBtn')
  if (!btn) return
  // Cel NELKUL nem sorolunk be: a gazdat nem talaljuk ki.
  btn.disabled = !(_inboxSelected().length && _inboxTarget)
}

async function _inboxPreview() {
  var box = document.getElementById('inboxPreview')
  if (!box) return
  var names = _inboxSelected()
  var d = null
  try {
    d = await _depoPost('/api/life/inbox/preview?lang=' + (window._lang || 'hu'),
      { names: names, target: _inboxTarget })
  } catch (e) {
    box.innerHTML = '<p class="subtitle">' + escapeHtml(t('inbox.preview_failed') + ' ' + ((e && e.message) ? e.message : String(e))) + '</p>'
    return
  }
  var sorok = d.plans || []
  box.innerHTML = '<p class="subtitle">' + escapeHtml(d.message || '') + '</p>'
    + (!sorok.length ? '' : '<div class="ssh-table-wrap"><table class="ssh-table"><thead><tr>'
      + '<th>' + escapeHtml(t('inbox.col_item')) + '</th>'
      + '<th>' + escapeHtml(t('inbox.col_target')) + '</th>'
      + '<th>' + escapeHtml(t('inbox.col_result')) + '</th></tr></thead><tbody>'
      + sorok.map(function (p) {
        return '<tr><td>' + escapeHtml(p.name) + '</td>'
          + '<td><code>' + escapeHtml(p.targetRel) + '</code></td>'
          + '<td>' + (p.status === 'ok'
            ? escapeHtml(t('inbox.ok'))
            : '<span style="color:var(--warning, #c77)">' + escapeHtml(p.message) + '</span>') + '</td></tr>'
      }).join('')
      + '</tbody></table></div>')
}

async function _inboxFile() {
  var names = _inboxSelected()
  if (!names.length || !_inboxTarget) return
  // A lemezre iro lepes elott megerosites -- a celt is kimondva.
  if (!confirm(t('inbox.confirm', { n: names.length, target: _inboxTarget }))) return
  var d = null
  try {
    d = await _depoPost('/api/life/inbox/file?lang=' + (window._lang || 'hu'),
      { names: names, target: _inboxTarget })
  } catch (e) {
    showToast(t('inbox.file_failed') + ' ' + ((e && e.message) ? e.message : String(e)))
    return
  }
  showToast(d.message || '')
  // Ami megallt, azt NEVEN NEVEZVE hagyjuk a kepernyon.
  var box = document.getElementById('inboxPreview')
  if (box && (d.failed || []).length) {
    box.innerHTML = '<div class="ssh-table-wrap"><table class="ssh-table"><thead><tr>'
      + '<th>' + escapeHtml(t('inbox.col_item')) + '</th>'
      + '<th>' + escapeHtml(t('inbox.col_result')) + '</th></tr></thead><tbody>'
      + d.failed.map(function (f) {
        return '<tr><td>' + escapeHtml(f.name) + '</td><td>' + escapeHtml(f.message) + '</td></tr>'
      }).join('')
      + '</tbody></table></div>'
  } else if (box) {
    box.innerHTML = ''
  }
  await _inboxRefresh()
  await _intezoOpen(_intezoPath)
}

/** A jelmagyarazat magabol a szolgaltato-regiszterbol jon: ha egyszer egy NAS
 *  bekerul, itt is MAGATOL megjelenik -- nincs kulon lista, amit karban kell tartani. */
async function _intezoLegend() {
  const el = document.getElementById('intezoLegend')
  if (!el) return
  try {
    const data = await _intezoGet('/api/life/sources')
    el.textContent = (data.kinds || []).map((k) => k.icon + ' ' + k.label).join('   ')
  } catch (e) { el.textContent = '' }
}

/** All-e mar a fa? Ha nem, ez az egyetlen dolog, amit kerdezunk. */
async function _intezoStatus() {
  const box = document.getElementById('intezoSetupBox')
  const txt = document.getElementById('intezoSetupText')
  const ensure = document.getElementById('intezoEnsureBtn')
  const toDepo = document.getElementById('intezoToDepoBtn')
  if (!box) return
  try {
    const st = await _intezoGet('/api/life/status')
    if (!st.root) {
      box.hidden = false
      txt.textContent = t('intezo.no_depot')
      if (ensure) ensure.hidden = true
      if (toDepo) toDepo.hidden = false
      return
    }
    if (ensure) ensure.hidden = false
    if (toDepo) toDepo.hidden = true
    if (!st.exists || (st.missing || []).length) {
      box.hidden = false
      txt.textContent = st.exists
        ? t('intezo.missing_n', { n: st.missing.length })
        : t('intezo.no_tree_yet')
    } else {
      box.hidden = true
    }
  } catch (e) {
    box.hidden = false
    if (txt) txt.textContent = (e && e.message) ? e.message : t('intezo.tree_check_failed')
    if (ensure) ensure.hidden = true
  }
}

async function _intezoEnsure() {
  const btn = document.getElementById('intezoEnsureBtn')
  if (btn) btn.disabled = true
  try {
    const r = await _depoPost('/api/life/ensure', {})
    showToast(r.message || t('intezo.done'))
    await _intezoStatus()
    await _intezoOpen(_intezoPath)
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.create_failed'))
  } finally {
    if (btn) btn.disabled = false
  }
}

let _intezoListing = null

async function _intezoOpen(rel) {
  const uj = rel || ''
  // Mashova leptunk -> a kijeloles es vele az adatlap megszunik.
  if (uj !== _intezoPath) _intezoClearSelection()
  _intezoPath = uj
  const search = document.getElementById('intezoSearch')
  if (search) search.value = ''
  try {
    await _faSugokBetolt()
    _intezoListing = await _intezoGet('/api/life/list?lang=' + (window._lang || 'hu')
      + '&path=' + encodeURIComponent(_intezoPath))
  } catch (e) {
    _intezoListing = { folders: [], files: [], breadcrumb: [], message: (e && e.message) ? e.message : t('intezo.open_failed') }
  }
  _intezoRender()
}

function _intezoUp() {
  if (!_intezoListing || _intezoListing.parent === null || _intezoListing.parent === undefined) return
  _intezoOpen(_intezoListing.parent)
}

async function _intezoSearch() {
  const q = (document.getElementById('intezoSearch') || {}).value || ''
  if (!q.trim()) { await _intezoOpen(_intezoPath); return }
  try {
    const r = await _intezoGet('/api/life/search?path=' + encodeURIComponent(_intezoPath) + '&q=' + encodeURIComponent(q))
    const entries = r.entries || []
    _intezoListing = Object.assign({}, _intezoListing, {
      folders: entries.filter((e) => e.isDir),
      files: entries.filter((e) => !e.isDir),
      truncated: r.truncated,
      message: entries.length ? null : t('intezo.no_hits', { q }),
    })
    _intezoRender()
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.search_failed'))
  }
}

/**
 * A forrasjelveny kirajzolasa.
 *
 * A jelveny a nev ELOTT all, sajat szinnel -- a fajl nevet SOSE szinezzuk,
 * mert az rontana az olvashatosagot (Boss kikotese). A `title` a lebego
 * sugo: ott all a reszletes magyarazat.
 */
function _intezoBadge(entry) {
  const mode = _intezoBadgeMode()
  if (mode === 'off') return ''
  const src = entry.source || {}
  const colors = { local: '#6b7280', drive: '#2563eb', photos: '#d97706', git: '#7c3aed', mixed: '#0f766e' }
  const color = colors[src.kind] || '#6b7280'
  // Szoveges modban a KIOSZTOTT sorszam all a jelvenyben (DRIVE_02), nem
  // csak a fajta: ket Drive-fiok kulonben pontosan ugyanugy nezne ki. Ha meg
  // nincs sorszam, a fajta-rovidites marad -- kitalalt szamot nem irunk ki.
  const label = mode === 'icon' ? (src.icon || '•') : ('[' + (src.storageId || src.short || '?') + ']')
  const tip = escapeHtml((src.label || '') + (src.details && src.details.length
    ? '\n' + src.details.map((d) => d.label + ': ' + d.value).join('\n') : ''))
  return '<span class="intezo-badge" title="' + tip + '" style="color:' + color
    + ';font-size:' + (mode === 'icon' ? '15px' : '11px') + ';margin-right:6px;white-space:nowrap">' + escapeHtml(label) + '</span>'
}

/**
 * A reszletes panel VISSZAKOLTOZIK az allando helyere.
 *
 * Minden lista-ujrarajzolas elott le kell valasztani a sorrol: a listat
 * `innerHTML`-lel epitjuk ujra, ami a benne allo panelt (es a rajta levo
 * esemenykezeloket) elpusztitana.
 */
function _intezoDetachInfoCard() {
  const card = document.getElementById('intezoInfoCard')
  const home = document.getElementById('intezoInfoHome')
  if (card && home && card.parentNode !== home) home.appendChild(card)
  const row = document.getElementById('intezoInlineRow')
  if (row) row.remove()
}

/**
 * A panel a KIJELOLT SOR ALA kerul.
 *
 * Boss, 2026-08-21: "annak kozvetlen ahol raklikkeltem azon sor alatt kellne
 * megjelennie". Egy tobb szaz tetelt tartalmazo mappaban a lap aljara kerulo
 * panel gyakorlatilag nem letezik: a szem nem talalja meg, a gorgetes meg
 * elveszti a sort, amirol szol.
 */
function _intezoPlaceInfoCard() {
  const card = document.getElementById('intezoInfoCard')
  if (!card || !_intezoSelected) return
  // Becsukott adatlapot nincs mit elhelyezni: enelkul egy ures sor maradna a
  // kijelolt tetel alatt, es a lista latszolag ok nelkul szethuzodna.
  if (card.hidden) return
  const list = document.getElementById('intezoList')
  if (!list) return
  const rows = list.querySelectorAll('tr[data-rel]')
  let host = null
  for (const r of rows) { if (r.getAttribute('data-rel') === _intezoSelected.rel) { host = r; break } }
  // Ha a kijelolt tetel nincs a mostani listaban (mas mappaba leptunk),
  // marad az allando helyen -- nem tuntetjuk el, csak nem tolakszik.
  if (!host) return
  const tr = document.createElement('tr')
  tr.id = 'intezoInlineRow'
  const td = document.createElement('td')
  td.colSpan = 4
  td.style.cssText = 'padding:0 0 10px'
  tr.appendChild(td)
  host.parentNode.insertBefore(tr, host.nextSibling)
  td.appendChild(card)
  // NEM nyitjuk ki. Ez a fuggveny csak azt intezi, HOVA kerul az adatlap --
  // hogy latszik-e, azt a hivo donti el. Korabban itt allt egy
  // `card.hidden = false`, es mivel minden lista-ujrarajzolas idehiv, az
  // adatlap magatol kinyilt: eleg volt egy uj mappat letrehozni a jobb
  // gombbal, es a becsukott panel visszajott. (Boss, 2026-08-22.)
}

/**
 * MAPPA-SUGOK mappanev szerint, a szerverrol.
 *
 * Egyetlen forras: a bongeszo nem tarol sajat masolatot a szovegekbol. Ket
 * helyen allo ugyanaz a szoveg elobb-utobb ketfele megy, es az a valtozat
 * marad fenn, amelyiket epp nezik.
 */
let _faSugok = null
async function _faSugokBetolt() {
  if (_faSugok) return _faSugok
  try {
    // A mappaNEV a lemez nyelvén áll (azt átnevezni adatvesztés volna),
    // a zárójeles magyarázat viszont a felület nyelvét követi.
    const r = await _intezoGet('/api/life/hints?lang=' + (window._lang || 'hu'))
    _faSugok = (r && r.hints) ? r.hints : {}
  } catch (e) { _faSugok = {} }
  return _faSugok
}

/** Egy mappa sugoja: eloszor amit a lista hozott, aztan a globalis tabla. */
function _faSugo(entry) {
  if (entry && entry.hint) return entry.hint
  const nev = (entry && entry.name) ? entry.name : String(entry || '')
  return (_faSugok && _faSugok[nev]) ? _faSugok[nev] : ''
}

/** A BEERKEZO-e ez a mappa. A nevet a szerver adja, nyelvfuggo. */
function _faBeerkezo(entry) {
  const nev = (entry && entry.name) ? entry.name : String(entry || '')
  return nev === 'Beérkező' || nev === 'Inbox'
}

function _intezoRender() {
  // A panelt MINDIG le kell valasztani, mielott a lista ujraepul.
  _intezoDetachInfoCard()
  const list = document.getElementById('intezoList')
  const crumbs = document.getElementById('intezoCrumbs')
  const msg = document.getElementById('intezoMessage')
  const pathEl = document.getElementById('intezoPath')
  const trunc = document.getElementById('intezoTruncated')
  if (!list || !_intezoListing) return
  const L = _intezoListing

  if (crumbs) {
    crumbs.innerHTML = (L.breadcrumb || []).map((b, i, arr) =>
      '<a href="#" data-crumb="' + escapeHtml(b.rel) + '">' + escapeHtml(b.name) + '</a>'
      + (i < arr.length - 1 ? ' <span style="opacity:.5">›</span> ' : '')).join('')
    crumbs.querySelectorAll('a[data-crumb]').forEach((a) => {
      a.addEventListener('click', (e) => { e.preventDefault(); _intezoOpen(a.getAttribute('data-crumb')) })
    })
  }
  if (pathEl) pathEl.textContent = L.display || ''
  if (msg) { msg.hidden = !L.message; msg.textContent = L.message || '' }
  if (trunc) trunc.hidden = !L.truncated

  const rows = [].concat(L.folders || [], L.files || [])
  if (!rows.length) {
    list.innerHTML = L.message ? '' : '<p style="opacity:.7" data-i18n="intezo.empty">Ez a mappa üres.</p>'
    return
  }
  list.innerHTML = '<table style="width:100%;font-size:14px;border-collapse:collapse"><tbody>'
    + rows.map((e) =>
      '<tr data-rel="' + escapeHtml(e.rel) + '" data-dir="' + (e.isDir ? '1' : '') + '"'
      + ' title="' + escapeHtml(t('intezo.row_title')) + '"'
      + ' data-pick="1"'
      + (_intezoSelected && _intezoSelected.rel === e.rel
          ? ' style="background:rgba(127,127,127,.15)"'
          // A BEERKEZO sajat hattere: ez a munka kezdopontja, ne kelljen
          // keresni a listaban.
          : (_faBeerkezo(e) ? ' style="background:rgba(255,179,0,.14)"' : ''))
      + '>'
      + '<td style="padding:2px 8px;white-space:nowrap">' + _intezoBadge(e) + '</td>'
      + '<td style="padding:2px 8px"><a href="#" data-open="' + escapeHtml(e.rel) + '"'
      // Git-terulet: PIROS nev es lakat-jelzes. Nem tiltas -- minden muvelet
      // mukodik --, csak figyelemfelkeltes (Boss, 2026-08-21): "az egy fontos
      // mappa. jobb nem piszkalni".
      + (e.caution ? ' style="color:var(--danger,#d33)" title="' + escapeHtml(e.caution) + '"' : '')
      + '>'
      + (e.isDir ? (e.caution ? '📛 ' : (_faBeerkezo(e) ? '📥 ' : '📁 ')) : '') + escapeHtml(e.name) + '</a>'
      // A magyarazat: halvanyabb es kisebb, hogy a NEV maradjon a fo informacio.
      // Aki mar tudja, hova tesz, annak ne alljon utban; aki nem tudja, annak
      // ott legyen ugyanabban a sorban.
      + (_faSugo(e) ? ' <span style="opacity:.6;font-size:12px">(' + escapeHtml(_faSugo(e)) + ')</span>' : '')
      + (e.caution ? ' <span style="color:var(--danger,#d33);font-size:12px" title="'
          + escapeHtml(e.caution) + '">⚠ ' + escapeHtml(t('intezo.caution_badge')) + '</span>' : '')
      + (e.physical ? ' <span title="' + escapeHtml(t('intezo.badge_paper')) + '">🗂</span>' : '')
      + (e.mounted ? ' <span style="opacity:.65;font-size:12px" title="' + escapeHtml(t('intezo.badge_mounted')) + '">→ '
          + escapeHtml(e.mounted) + '</span>' : '') + '</td>'
      + '<td style="padding:2px 8px;text-align:right;opacity:.7;white-space:nowrap">' + escapeHtml(e.sizeHuman) + '</td>'
      + '<td style="padding:0 8px;white-space:nowrap"><button class="btn-secondary" '
      + 'style="padding:1px 7px;font-size:11px;line-height:1.5;min-height:0;height:auto" '
      + 'data-info="' + escapeHtml(e.rel) + '">Info</button></td>'
      + '</tr>').join('')
    + '</tbody></table>'

  list.querySelectorAll('a[data-open]').forEach((a) => {
    a.addEventListener('click', (e) => {
      e.preventDefault()
      const rel = a.getAttribute('data-open')
      const row = a.closest('tr')
      // Ha eppen celt valasztunk (athelyezes / papir helye), a kattintas
      // BELEP a mappaba -- a kivalasztas kulon gombbal tortenik, hogy egy
      // fel-kattintas ne helyezzen at semmit.
      if (row && row.getAttribute('data-dir')) _intezoOpen(rel)
      else if (_intezoSelected && _intezoSelected.rel === rel) _intezoClearSelection()
      else _intezoInfo(rel)
    })
  })
  // BAL KLIKK A SOR BARMELY PONTJARA = kijeloles/kijeloles-levetel.
  // A neven levo link es az Info gomb sajat kezelot kap, azok elol kiterunk:
  // a nev BELEP, ez pedig KIJELOL -- ket kulon szandek, ket kulon hely.
  list.querySelectorAll('tr[data-pick]').forEach((tr) => {
    tr.style.cursor = 'pointer'
    tr.addEventListener('click', (ev) => {
      if (ev.target && ev.target.closest && ev.target.closest('a[data-open],button')) return
      const rel = tr.getAttribute('data-rel')
      if (_intezoSelected && _intezoSelected.rel === rel) _intezoClearSelection()
      else void _intezoInfo(rel)
    })
  })

  // JOBB EGERGOMB a sorokon. A sor teljes szelessegen mukodik, nem csak a
  // neven -- aki jobbra, az ures reszre kattint, ugyanugy a sort erti alatta.
  list.querySelectorAll('tr[data-rel]').forEach((tr) => {
    tr.addEventListener('contextmenu', (ev) => {
      const rel = tr.getAttribute('data-rel')
      const e = rows.find((x) => x.rel === rel)
      if (e) void _intezoOpenMenu(ev, e)
    })
  })
  // (Az ures teruletre adott jobb klikket mar nem itt fogjuk el, hanem az
  //  EGESZ Intezo lapon -- lasd `_intezoMenuBound`. A lista magassaga ugyanis
  //  a sorok szama: egy ket-elemu mappaban a tablazat par pixel, alatta meg
  //  fel kepernyonyi ures hely, ahol a bongeszo sajat menuje jott elo.)

  list.querySelectorAll('button[data-info]').forEach((b) => {
    b.addEventListener('click', () => {
      // Kapcsolo: ugyanarra a tetelre masodszor kattintva becsukodik.
      const rel = b.getAttribute('data-info')
      if (_intezoSelected && _intezoSelected.rel === rel) _intezoClearSelection()
      else _intezoInfo(rel)
    })
  })

  _intezoPlaceInfoCard()
}

/**
 * KULON KIS PANEL a celmappa kitallozasahoz.
 *
 * `mode`: 'move' = athelyezes celja, 'paper' = a papir peldany helye.
 * Fajlt es MAPPAT egyarant lehet athelyezni -- a mappa a tartalmaval egyutt
 * megy. Ezert a panel a sajat kiindulasi agat kiszurkiti: egy mappat nem lehet
 * onmagaba tenni, es jobb ezt latni, mint utolag hibauzenetet kapni.
 */
function _intezoOpenFolderPicker(mode) {
  const sel = _intezoSelected
  if (!sel) { showToast(t('intezo.select_first')); return }

  const overlay = document.createElement('div')
  // KET `.modal-overlay` szabaly all a lapon: a korabbi `opacity:0` +
  // `visibility:hidden` allapotbol csak az `.active` osztaly hozza elo.
  // Nelkule a panel letrejonne, de LATHATATLAN maradna.
  overlay.className = 'modal-overlay active'
  overlay.id = 'intezoPickerOverlay'
  const what = mode === 'move'
    ? t('intezo.pick_move_to', { name: sel.name || '' })
    : t('intezo.pick_paper_at', { name: sel.name || '' })
  overlay.innerHTML = '<div class="modal-content" style="max-width:560px;padding:18px">'
    + '<h3 style="margin:0 0 4px">' + escapeHtml(what) + '</h3>'
    + '<p class="subtitle" style="margin:0 0 10px">' + escapeHtml(t('intezo.pick_help')) + '</p>'
    + '<div id="intezoPickerCrumb" style="font-size:13px;opacity:.85;margin-bottom:6px"></div>'
    + '<div id="intezoPickerList" style="max-height:320px;overflow:auto;border:1px solid var(--border,#3336);border-radius:8px;padding:4px"></div>'
    + '<p style="margin:10px 0 4px;font-size:13px">' + escapeHtml(t('intezo.pick_here')) + ' <b id="intezoPickerHere"></b></p>'
    + '<div style="text-align:right;margin-top:8px">'
    + '<button class="btn-secondary" id="intezoPickerCancel">' + escapeHtml(t('intezo.cancel')) + '</button> '
    + '<button class="btn-primary" id="intezoPickerOk">Ez legyen az</button>'
    + '</div></div>'
  document.body.appendChild(overlay)

  const close = () => overlay.remove()
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close() })
  overlay.querySelector('#intezoPickerCancel').addEventListener('click', close)

  // A panel a SAJAT helyerol indul -- rendszerint a szomszed mappaba akarunk
  // tenni valamit, nem a fa tetejerol lefele keresgelni.
  let here = _intezoPath || ''
  overlay.querySelector('#intezoPickerOk').addEventListener('click', () => {
    close()
    _intezoConfirmPick(mode, here)
  })

  async function draw() {
    const crumb = overlay.querySelector('#intezoPickerCrumb')
    const list = overlay.querySelector('#intezoPickerList')
    const hereEl = overlay.querySelector('#intezoPickerHere')
    hereEl.textContent = here ? here.split('/').join(' › ') : t('intezo.tree_root')
    list.textContent = t('intezo.loading')
    let data
    try {
      data = await _intezoGet('/api/life/list?deep=0&lang=' + (window._lang || 'hu')
        + '&path=' + encodeURIComponent(here))
    } catch (e) {
      list.textContent = (e && e.message) ? e.message : t('intezo.open_this_failed')
      return
    }
    crumb.textContent = data.display || ''
    list.innerHTML = ''
    if (data.parent !== null && data.parent !== undefined) {
      const up = document.createElement('button')
      up.className = 'btn-secondary btn-compact'
      up.style.cssText = 'display:block;width:100%;text-align:left;margin:2px 0'
      up.textContent = '⬆ Fel egy szintet'
      up.addEventListener('click', () => { here = data.parent; draw() })
      list.appendChild(up)
    }
    const folders = (data.folders || []).filter((f) => {
      // Onmagaba nem lehet athelyezni -- ne is kinaljuk fel.
      if (mode !== 'move' || !sel.isDir) return true
      return f.rel !== sel.rel && String(f.rel + '/').indexOf(sel.rel + '/') !== 0
    })
    if (!folders.length) {
      const p = document.createElement('p')
      p.style.cssText = 'opacity:.7;font-size:13px;padding:6px'
      p.textContent = t('intezo.pick_no_sub')
      list.appendChild(p)
    }
    for (const f of folders) {
      const b = document.createElement('button')
      b.className = 'btn-secondary btn-compact'
      b.style.cssText = 'display:block;width:100%;text-align:left;margin:2px 0'
      // A git-repok itt is jelolve vannak: aki ide tallozik, lassa elore,
      // hogy oda nem fog tudni bepakolni.
      const sugo = _faSugo(f)
      b.textContent = (f.caution ? '📛 ' : (_faBeerkezo(f) ? '📥 ' : '📁 ')) + f.name
        + (f.caution ? '  (git — ide nem)' : (sugo ? '  (' + sugo + ')' : ''))
      if (f.caution) b.title = f.caution
      b.addEventListener('click', () => { here = f.rel; draw() })
      list.appendChild(b)
    }
  }
  draw()
}

function _intezoStartPick(mode) {
  _intezoOpenFolderPicker(mode)
}

async function _intezoConfirmPick(mode, target) {
  const sel = _intezoSelected
  if (!sel) { _intezoRender(); return }
  if (mode === 'move') {
    try {
      const r = await _depoPost('/api/life/move', { from: sel.rel, to: target })
      showToast(r.message || t('intezo.done'))
      await _intezoOpen(_intezoPath)
      if (r.ok) await _intezoInfo(r.rel)
    } catch (e) {
      showToast((e && e.message) ? e.message : t('intezo.move_failed'))
      _intezoRender()
    }
    return
  }
  // Papir helye: csak beirjuk a mezobe. A mentes kulon gomb -- igy egy
  // felreklikkelt mappa meg visszavonhato.
  const el = document.getElementById('intezoPhysLocation')
  if (el) { el.textContent = target || t('intezo.tree_root'); el.setAttribute('data-rel', target) }
  const has = document.getElementById('intezoPhysHas')
  if (has && !has.checked) { has.checked = true; document.getElementById('intezoPhysFields').hidden = false }
  _intezoRender()
}

/**
 * Egy elem kijelolese es az adatlapja.
 *
 * `quiet` = csak kijelol: az adatlapot nem NYITJA KI, ha zarva volt. (Ha
 * nyitva van, frissul -- kulonben egy regi elem adatai maradnanak a kepen,
 * ami rosszabb, mint ha becsukodna.)
 */
async function _intezoInfo(rel, quiet) {
  const card = document.getElementById('intezoInfoCard')
  const rowsEl = document.getElementById('intezoInfoRows')
  if (!card || !rowsEl) return
  let info
  try {
    info = await _intezoGet('/api/life/info?path=' + encodeURIComponent(rel))
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.info_failed'))
    return
  }
  _intezoSelected = info
  if (!quiet) card.hidden = false

  const src = info.source || {}
  const rows = [
    [t('intezo.info_type'), info.type],
    [t('intezo.info_owner'), info.owner || '—'],
    [t('intezo.info_digital'), info.digitalLocation || t('intezo.tree_root')],
    [t('intezo.info_source'), (src.icon || '') + ' ' + (src.label || '')],
  ]
  if (info.mount) rows.push([t('intezo.info_mounted'), info.mount.label + '  (' + info.mount.target + ')'])
  ;(src.details || []).forEach((d) => rows.push([d.label, d.value]))
  // A 20. pont ot mezoje. Az azonosito HIANYA is sor: a storageNote egy
  // MERT okbol jon (nincs raktar / nem tarolobol jon / nincs kiosztva
  // sorszam), tehat sose ures kepernyot mutatunk helyette.
  const stg = info.storage || {}
  rows.push([t('intezo.st_logical'), stg.logicalPath || t('intezo.tree_root')])
  rows.push([t('intezo.st_id'), stg.storageId || stg.storageNote || '—'])
  if (stg.storageType) rows.push([t('intezo.st_type'), stg.storageType])
  if (stg.physicalPath) rows.push([t('intezo.st_physical'), stg.physicalPath])
  if (stg.sourceProvider) rows.push([t('intezo.st_provider'), stg.sourceProvider])
  if (!info.isDir) rows.push([t('intezo.info_size'), info.sizeHuman || '—'])
  // A datumformatum is a felulet nyelvet koveti, nem a telepitesét.
  rows.push([t('intezo.info_mtime'), info.mtime
    ? new Date(info.mtime).toLocaleString(window._lang === 'en' ? 'en-GB' : 'hu-HU') : '—'])
  rows.push([t('intezo.info_physical'),
    t(info.physical && info.physical.physical ? 'intezo.info_has' : 'intezo.info_hasnt')])
  if (info.physicalLocationHuman) rows.push([t('intezo.info_physloc'), info.physicalLocationHuman])

  rowsEl.innerHTML = rows.map((r) =>
    '<tr><td style="padding:4px 10px 4px 0;opacity:.7;white-space:nowrap">' + escapeHtml(r[0])
    + '</td><td style="padding:4px 0">' + escapeHtml(r[1]) + '</td></tr>').join('')

  const has = document.getElementById('intezoPhysHas')
  const fields = document.getElementById('intezoPhysFields')
  const loc = document.getElementById('intezoPhysLocation')
  const note = document.getElementById('intezoPhysNote')
  const p = info.physical || {}
  if (has) has.checked = Boolean(p.physical)
  if (fields) fields.hidden = !p.physical
  if (loc) {
    // Ha meg nincs megadva papir-hely, a fajl SAJAT mappaja az ajanlat: a
    // legtobb irat ott all papiron is, ahova digitalisan tettuk. Igy a
    // legtobb esetben tallozni sem kell -- csak menteni.
    const own = String(info.rel || '').includes('/') ? String(info.rel).slice(0, String(info.rel).lastIndexOf('/')) : ''
    const relLoc = p.location || own
    loc.textContent = info.physicalLocationHuman || (own ? own.split('/').join(' › ') : t('intezo.tree_root'))
    loc.setAttribute('data-rel', relLoc)
  }
  if (note) note.value = p.note || ''
  _intezoRenderMount(info)
  _intezoRenderGit(info)
  _intezoRenderActions()
  _intezoRender()
}

/**
 * A GIT-BLOKK: mit szabad ezzel a repoval, es mi tortenne torleskor.
 *
 * Boss: "ha mar nincs szukseg ra akor lecsatlakoztatni vagy az egeszet
 * torolni azt lehessen."
 *
 * A ket kiut sorrendje SZANDEKOS: elol a bekotes megszuntetese, mert az
 * semmit nem torol -- a fabol tunik el, a fajlok a helyukon maradnak. A
 * torles csak masodik, es csak a MERT mondat kiirasa utan.
 */
async function _intezoRenderGit(info) {
  const box = document.getElementById('intezoGitBox')
  if (!box) return
  box.innerHTML = ''
  const git = info && info.git
  if (!git) { box.hidden = true; return }
  box.hidden = false

  const head = document.createElement('div')
  head.className = 'info-box'
  head.style.marginTop = '14px'
  head.innerHTML = '<p style="margin:0 0 6px">' + t('intezo.git_head') + '</p>'
    + (git.isRoot
      ? '<p style="margin:0;font-size:13px;opacity:.85">' + escapeHtml(t('intezo.git_root_note')) + '</p>'
      : '<p style="margin:0;font-size:13px;opacity:.85">' + escapeHtml(t('intezo.git_inside_note', { repo: git.repo })) + '</p>')
  box.appendChild(head)
  if (!git.isRoot) return

  const state = document.createElement('p')
  state.style.cssText = 'margin:8px 0;font-size:13px'
  state.textContent = t('intezo.git_asking')
  box.appendChild(state)

  let st
  try {
    st = await _intezoGet('/api/life/repo-status?path=' + encodeURIComponent(info.rel))
  } catch (e) {
    state.textContent = t('intezo.git_status_failed')
    return
  }
  state.innerHTML = '<b>' + escapeHtml(st.sentence || '') + '</b>'
    + (st.branch ? '<br><span style="opacity:.75">' + escapeHtml(t('intezo.git_branch')) + ' ' + escapeHtml(st.branch) + (st.remote ? ' → ' + escapeHtml(st.remote) : '') + '</span>' : '')

  const btns = document.createElement('div')
  btns.style.marginTop = '6px'

  // ELOSZOR a veszelytelen kiut.
  if ((st.mounts || []).length) {
    const un = document.createElement('button')
    un.className = 'btn-secondary btn-compact'
    un.textContent = '🔌 ' + t('intezo.unmount')
    un.addEventListener('click', async () => {
      if (!confirm(t('intezo.unmount_confirm'))) return
      try {
        const r = await _depoPost('/api/life/mounts/remove', { rel: st.mounts[0].rel })
        showToast(r.message || t('intezo.done'))
        await _intezoOpen(_intezoPath)
      } catch (e) { showToast((e && e.message) ? e.message : t('intezo.failed')) }
    })
    btns.appendChild(un)
    btns.appendChild(document.createTextNode(' '))
  }

  // A ZAR ALLAPOTA es kapcsoloja. Csak ott jelenik meg, ahol ertelme van:
  // git-tarolo alatti repo gyokerenel.
  if (st.zarhato) {
    const zar = document.createElement('p')
    zar.style.cssText = 'margin:8px 0;font-size:13px'
    zar.innerHTML = st.csakOlvasas
      ? t('intezo.repo_ro')
      : t('intezo.repo_rw')
    box.appendChild(zar)

    const kapcs = document.createElement('button')
    kapcs.className = 'btn-secondary btn-compact'
    kapcs.textContent = st.csakOlvasas ? '✏️ ' + t('intezo.repo_unlock') : '🔒 ' + t('intezo.repo_lock')
    kapcs.addEventListener('click', async () => {
      const be = !st.csakOlvasas
      if (!be && !confirm(t('intezo.unlock_confirm'))) return
      kapcs.disabled = true
      try {
        const r = await _depoPost('/api/life/repo-lock', { rel: info.rel, on: be })
        showToast(r.message || t('intezo.done'))
        st.csakOlvasas = r.csakOlvasas === true
        zar.innerHTML = st.csakOlvasas
          ? t('intezo.repo_ro')
          : t('intezo.repo_rw')
        kapcs.textContent = st.csakOlvasas ? '✏️ ' + t('intezo.repo_unlock') : '🔒 ' + t('intezo.repo_lock')
      } catch (e) { showToast((e && e.message) ? e.message : t('intezo.failed')) }
      kapcs.disabled = false
    })
    btns.appendChild(kapcs)
    btns.appendChild(document.createTextNode(' '))
  }

  const del = document.createElement('button')
  del.className = 'btn-secondary btn-compact'
  del.style.color = 'var(--danger,#d33)'
  del.textContent = '🗑 ' + t('intezo.repo_delete')
  del.addEventListener('click', async () => {
    // A mert mondatot MEGMUTATJUK a kerdesben -- a felhasznalo ne emlekezetbol
    // dontson arrol, elveszik-e munka.
    if (!confirm((st.sentence || '') + '\n\n' + t('intezo.repo_delete_q'))) return
    try {
      const r = await _depoPost('/api/life/repo-delete', { rel: info.rel, force: st.safe !== true })
      showToast(r.message || t('intezo.done'))
      _intezoClearSelection()
      await _intezoOpen(_intezoPath)
    } catch (e) { showToast((e && e.message) ? e.message : t('intezo.delete_failed')) }
  })
  btns.appendChild(del)
  box.appendChild(btns)
}

/**
 * A LEFIXALT FEJLEC muveletsava.
 *
 * Boss, 2026-08-21: "Ez az athelyezes masik mappaba nevu gomb ott van a lista
 * legaljan. nem a felso reszhez kellene tenni? ott alul senki sem latja."
 *
 * A gombok NEM masoljak a logikat: ugyanazokat a fuggvenyeket hivjak, mint a
 * lenti panel gombjai, vagy egyszeruen odagorgetnek. Igy nem tud a ket hely
 * kulon utra menni.
 */
function _intezoRenderActions() {
  const bar = document.getElementById('intezoActionBar')
  const name = document.getElementById('intezoActionName')
  if (!bar) return
  if (!_intezoSelected) { bar.hidden = true; return }
  bar.hidden = false
  if (name) {
    name.textContent = (_intezoSelected.isDir ? '📁 ' : '📄 ') + (_intezoSelected.name || '')
    name.title = _intezoSelected.rel || ''
  }
  // Bekotni csak mappat lehet -- fajlnal a gomb ne igerjen semmit.
  const mount = bar.querySelector('[data-intezo-act="mount"]')
  if (mount) mount.disabled = !_intezoSelected.isDir
}

/** A panel egy reszehez gorget, es elore lathatova teszi a panelt. */
function _intezoJumpTo(id) {
  const card = document.getElementById('intezoInfoCard')
  if (card) card.hidden = false
  const el = document.getElementById(id) || card
  if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'center' })
}

/** A kijeloles vege: a panel becsukodik, a sav eltunik, a sor kijelolese megszunik. */
function _intezoClearSelection() {
  _intezoSelected = null
  _intezoDetachInfoCard()
  const card = document.getElementById('intezoInfoCard')
  if (card) card.hidden = true
  _intezoRenderActions()
  _intezoRender()
}

function _intezoActionClick(ev) {
  const btn = ev.target && ev.target.closest ? ev.target.closest('[data-intezo-act]') : null
  if (!btn) return
  ev.preventDefault()
  if (!_intezoSelected && btn.getAttribute('data-intezo-act') !== 'clear') {
    showToast(t('intezo.select_first'))
    return
  }
  switch (btn.getAttribute('data-intezo-act')) {
    case 'move': _intezoStartPick('move'); break
    case 'mount': {
      _intezoJumpTo('intezoMountTitle')
      const sel = document.getElementById('intezoMountTarget')
      if (sel && !sel.disabled) sel.focus()
      break
    }
    case 'paper': _intezoJumpTo('intezoPhysTitle'); break
    case 'info': _intezoJumpTo('intezoInfoCard'); break
    case 'clear': _intezoClearSelection(); break
  }
}

/** A bekotesek felajanlhato celjai. Egyszer szedjuk ossze, oldal-nyitaskor. */
let _intezoMountOpts = []

async function _intezoMountOptions() {
  try {
    const data = await _intezoGet('/api/life/mount-options')
    _intezoMountOpts = data.options || []
  } catch (e) { _intezoMountOpts = [] }
  const sel = document.getElementById('intezoMountTarget')
  if (!sel) return
  if (!_intezoMountOpts.length) {
    // Ez nem hiba: meg egyszeruen nincs mit bekotni. Azt mondjuk meg, HOL
    // lesz mit -- nem azt, hogy "nincs adat".
    sel.innerHTML = '<option value="">' + escapeHtml(t('intezo.mount_nothing')) + '</option>'
    return
  }
  sel.innerHTML = '<option value="">' + escapeHtml(t('intezo.choose')) + '</option>' + _intezoMountOpts.map((o) =>
    '<option value="' + escapeHtml(o.target) + '">' + escapeHtml(o.label)
    + ' ' + (o.items ? t('intezo.mount_items', { n: o.items }) : t('intezo.mount_empty')) + '</option>').join('')
}

/** Be van-e kotve a kijelolt mappa, es mit lehet vele csinalni. */
function _intezoRenderMount(info) {
  const state = document.getElementById('intezoMountState')
  const add = document.getElementById('intezoMountAddBtn')
  const del = document.getElementById('intezoMountDelBtn')
  const sel = document.getElementById('intezoMountTarget')
  if (!state) return
  // Bekotni csak MAPPAT lehet -- egy fajl mogott nincs mit mutatni.
  const canMount = info.isDir
  if (add) add.disabled = !canMount
  if (sel) sel.disabled = !canMount
  if (info.mount) {
    state.textContent = 'Ez a mappa most ezt mutatja: ' + info.mount.label
    if (del) del.hidden = false
    if (add) add.disabled = true
  } else {
    state.textContent = canMount
      ? t('intezo.mount_own')
      : t('intezo.mount_dir_only')
    if (del) del.hidden = true
  }
}

async function _intezoAddMount() {
  if (!_intezoSelected) return
  const sel = document.getElementById('intezoMountTarget')
  const target = sel ? sel.value : ''
  if (!target) { showToast(t('intezo.mount_pick_first')); return }
  const opt = _intezoMountOpts.find((o) => o.target === target) || {}
  try {
    const r = await _depoPost('/api/life/mounts', {
      rel: _intezoSelected.rel, target: target, kind: opt.kind || 'local', label: opt.label || target,
    })
    showToast(r.message || t('intezo.done'))
    await _intezoOpen(_intezoPath)
    await _intezoInfo(_intezoSelected.rel)
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.mount_failed'))
  }
}

async function _intezoRemoveMount() {
  if (!_intezoSelected) return
  if (!confirm(t('intezo.unmount_confirm2'))) return
  try {
    const r = await _depoPost('/api/life/mounts/remove', { rel: _intezoSelected.rel })
    showToast(r.message || t('intezo.done'))
    await _intezoOpen(_intezoPath)
    await _intezoInfo(_intezoSelected.rel)
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.unmount_failed'))
  }
}

async function _intezoSavePhysical() {
  if (!_intezoSelected) return
  const has = document.getElementById('intezoPhysHas')
  const loc = document.getElementById('intezoPhysLocation')
  const note = document.getElementById('intezoPhysNote')
  try {
    await _depoPost('/api/life/physical', {
      path: _intezoSelected.rel,
      physical: has ? has.checked : false,
      location: loc ? (loc.getAttribute('data-rel') || '') : '',
      note: note ? note.value : '',
    })
    showToast('Mentve.')
    await _intezoInfo(_intezoSelected.rel)
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.save_failed'))
  }
}

/* ===================== JOBB EGERGOMB (helyi menu) =====================
 *
 * Egy fa-nezetben a jobb klikk az, amit MINDENKI kiprobal -- mert a Windows
 * Intezoben ez mukodik. Ha nem tortenik semmi, a felhasznalo azt hiszi, a
 * funkcio nincs is meg. A menu ugyanazokat a fuggvenyeket hivja, mint a fenti
 * gombsor: egy viselkedes, ket bejarat.
 *
 * A jobb klikk KIJELOLI a sort is, mielott a menu megjelenik -- kulonben a
 * „mappa bekotese" azt kerdezne, mit kotunk be.
 */
let _intezoMenuEl = null
/**
 * Hanyadik menunyitas tart eppen.
 *
 * A megnyitas ASZINKRON (megvarja az adatlapot), ezert ket gyors jobb klikk
 * egymasba fut: a masodik hivas bezarja az elsot MIELOTT az egyaltalan a
 * lapra kerult volna, aztan mindketto beteszi magat. Igy volt latszik ket
 * menu -- es a `_intezoMenuEl` mar csak az egyikre mutatott, a masik pedig
 * KIZARHATATLANUL ott maradt a lapon (ezert nem tunt el kattintasra).
 */
let _intezoMenuSeq = 0

function _intezoCloseMenu() {
  // Az OSSZESET keressuk meg a lapon, nem csak azt, amit szamon tartunk: ha
  // valahogy megis ottragadna egy arva menu, ez a sor akkor is eltakaritja.
  document.querySelectorAll('.intezo-ctxmenu').forEach((el) => {
    if (el.parentNode) el.parentNode.removeChild(el)
  })
  _intezoMenuEl = null
  _intezoMenuSeq++
}

/** Egy menupont. `veszelyes` = piros (torles). */
function _intezoMenuItem(cimke, fn, veszelyes) {
  const b = document.createElement('button')
  b.type = 'button'
  b.textContent = cimke
  b.style.cssText = 'display:block;width:100%;text-align:left;border:0;background:none;'
    + 'padding:7px 14px;font-size:13px;cursor:pointer;white-space:nowrap;color:'
    + (veszelyes ? 'var(--danger)' : 'var(--text)')
  b.addEventListener('mouseenter', () => { b.style.background = 'var(--bg-card-hover)' })
  b.addEventListener('mouseleave', () => { b.style.background = 'none' })
  b.addEventListener('click', () => { _intezoCloseMenu(); fn() })
  return b
}

function _intezoMenuSep() {
  const d = document.createElement('div')
  d.style.cssText = 'height:1px;background:var(--border);margin:4px 0'
  return d
}

/**
 * A helyi menu megnyitasa.
 *
 * `entry` = a sor (nev, rel, isDir), vagy `null`, ha ures teruletre kattintott:
 * olyankor csak az „ide uj mappa" ertelmes.
 */
/**
 * A MOSTANI mappa embernek szolo neve -- a helyi menu felirataba.
 * A puszta „itt" / „ide" nem mond semmit arrol, hova kerul az uj mappa; a
 * teljes utvonal viszont hosszu. Az utolso szakasz a jo kompromisszum.
 */
function _intezoMostaniNev() {
  const u = String(_intezoPath || '')
  if (!u) return 'Marveen'
  const r = u.split('/').filter(Boolean)
  return r.length ? r[r.length - 1] : 'Marveen'
}

async function _intezoOpenMenu(ev, entry) {
  ev.preventDefault()
  _intezoCloseMenu()
  const jegy = ++_intezoMenuSeq

  // ELOBB KIJELOLES. A Boss keresere: „persze elobb kivalasztas."
  // CSENDESEN: a jobb klikk menut ker, nem adatlapot. A „Részletes információ"
  // menupont nyitja ki, ha tenyleg az kell.
  if (entry) {
    try { await _intezoInfo(entry.rel, true) } catch (e) {}
    // A jobb klikk MENUT ker, nem adatlapot. A `quiet` csak azt ereti el, hogy
    // ne NYISSA ki -- ha viszont mar nyitva volt egy korabbi bal kattintastol,
    // ott maradt es a menu alatt ugrott at masik tetelre. Ezert csukjuk be:
    // az adatlapot a „Részletes információ" menupont nyitja, semmi mas.
    const kartya = document.getElementById('intezoInfoCard')
    if (kartya) kartya.hidden = true
  }
  // Kozben inditottak egy ujabb menut? Akkor ez a hivas mar elkesett: NEM
  // teszunk ki semmit. Enelkul ket menu kerulne a lapra.
  if (jegy !== _intezoMenuSeq) return

  const m = document.createElement('div')
  m.className = 'intezo-ctxmenu'
  // A szinek a style.css valtozoibol jonnek, hogy a menu vilagos es sotet
  // temaban is olvashato legyen. (Egy elirt valtozonev itt nemán sotet dobozt
  // ad -- lasd a 2026-08-22-i javitast.)
  m.style.cssText = 'position:fixed;z-index:9999;min-width:220px;padding:6px 0;'
    + 'background:var(--bg-modal);color:var(--text);border:1px solid var(--border);'
    + 'border-radius:8px;box-shadow:0 8px 28px rgba(0,0,0,.18)'

  if (!entry) {
    m.appendChild(_intezoMenuItem('📁  ' + t('intezo.menu_mkdir_into', { name: _intezoMostaniNev() }), () => _intezoMkdir()))
    // A Kukaban allva a leggyakoribb szandek nem uj mappa, hanem a takaritas.
    if (_intezoKukaban(_intezoPath)) {
      m.appendChild(_intezoMenuSep())
      m.appendChild(_intezoMenuItem('🔥  ' + t('intezo.menu_empty_trash'), () => _intezoEmptyKuka(), true))
    }
  } else {
    if (entry.isDir) m.appendChild(_intezoMenuItem('📂  ' + t('intezo.menu_open'), () => _intezoOpen(entry.rel)))
    if (entry.isDir) m.appendChild(_intezoMenuItem('📁  ' + t('intezo.menu_mkdir_into', { name: entry.name || entry.rel }), () => _intezoMkdirInto(entry.rel)))
    m.appendChild(_intezoMenuItem('✏️  ' + t('intezo.menu_rename'), () => _intezoRename(entry)))
    m.appendChild(_intezoMenuItem('➡️  ' + t('intezo.menu_move'), () => _intezoStartPick('move')))
    if (entry.isDir) {
      m.appendChild(_intezoMenuItem('🔗  ' + t('intezo.menu_mount'), () => {
        _intezoJumpTo('intezoMountTitle')
        const sel = document.getElementById('intezoMountTarget')
        if (sel && !sel.disabled) sel.focus()
      }))
    }
    m.appendChild(_intezoMenuItem('🗂  ' + t('intezo.menu_paper'), () => _intezoJumpTo('intezoPhysTitle')))
    m.appendChild(_intezoMenuItem('ℹ️  ' + t('intezo.menu_info'), async () => {
      await _intezoInfo(entry.rel)
      _intezoJumpTo('intezoInfoCard')
    }))
    m.appendChild(_intezoMenuSep())
    // A Kukaban a „torles" mar nem athelyezes: onnan mar csak lefele van ut.
    if (entry.rel === _INTEZO_KUKA) {
      m.appendChild(_intezoMenuItem('🔥  ' + t('intezo.menu_empty_trash'), () => _intezoEmptyKuka(), true))
    } else if (_intezoKukaban(entry.rel)) {
      m.appendChild(_intezoMenuItem('🔥  ' + t('intezo.menu_purge'), () => _intezoPurge(entry), true))
    } else {
      m.appendChild(_intezoMenuItem('🗑  ' + t('intezo.menu_trash'), () => _intezoTrash(entry), true))
    }
  }

  document.body.appendChild(m)
  _intezoMenuEl = m
  // A menu SAJAT kattintasa ne csukja be azonnal a dokumentum-figyelon at --
  // a menupontok maguk zarnak be, miutan lefutottak.
  m.addEventListener('click', (e) => e.stopPropagation())
  m.addEventListener('contextmenu', (e) => e.preventDefault())
  // Ne logjon ki a kepernyorol: ha a jobb also sarokban kattintott, a menu
  // befele nyilik.
  const r = m.getBoundingClientRect()
  const x = Math.min(ev.clientX, window.innerWidth - r.width - 8)
  const y = Math.min(ev.clientY, window.innerHeight - r.height - 8)
  m.style.left = Math.max(4, x) + 'px'
  m.style.top = Math.max(4, y) + 'px'
}

if (!window._intezoMenuBound) {
  window._intezoMenuBound = 1
  document.addEventListener('click', () => _intezoCloseMenu())
  document.addEventListener('mousedown', (e) => {
    if (e.target && e.target.closest && e.target.closest('.intezo-ctxmenu')) return
    _intezoCloseMenu()
  })
  document.addEventListener('scroll', () => _intezoCloseMenu(), true)
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') _intezoCloseMenu() })

  // JOBB EGERGOMB AZ INTEZO BARMELY URES PONTJAN = a MOSTANI mappa menuje
  // (elsosorban az „Uj mappa itt"). Boss, 2026-08-22: „ha itt az ures reszen
  // megnyomom az eger jobb gombjat, akkor az uj mappa letrehozasa gomb
  // jelenjen meg. ne csak akkor, ha ott kozvetlenul a mappa alatt nyomom meg."
  // Korabban csak a tablazat fogadta a kattintast -- az meg pont addig tart,
  // ameddig sorok vannak.
  document.addEventListener('contextmenu', (e) => {
    const t = e.target
    if (!t || !t.closest) return
    const lap = document.getElementById('intezoPage')
    if (!lap || lap.hidden || !lap.contains(t)) return
    // A sorok sajat menut kapnak (a sor tetelere vonatkozot), a beviteli
    // mezokon es gombokon pedig a bongeszo sajat menuje a hasznos (masolas,
    // beillesztes, link megnyitasa uj lapon).
    if (t.closest('tr[data-rel]')) return
    if (t.closest('input,textarea,select,a,button,.intezo-ctxmenu')) return
    void _intezoOpenMenu(e, null)
  })
}

// A Kuka utvonala. A felulet magyar nevekkel dolgozik (APP_LANG=hu); a
// DONTES viszont nem itt szuletik: a szerver `purgeLife`-ja akkor sem torol
// veglegesen, ha innen barmi mast kuldenenk. Ez itt csak azt intezi, hogy a
// felhasznalo a HELYES menupontot lassa.
const _INTEZO_KUKA = 'Rendszer/Kuka'
function _intezoKukaban(rel) {
  const r = String(rel || '')
  return r === _INTEZO_KUKA || r.indexOf(_INTEZO_KUKA + '/') === 0
}

/** Vegleges torles a Kukabol -- ez az egyetlen visszavonhatatlan gomb a fan. */
async function _intezoPurge(entry) {
  const mi = t(entry.isDir ? 'intezo.the_folder' : 'intezo.the_file')
  if (!confirm(t('intezo.purge_confirm', { name: entry.name || entry.rel, what: mi })
      + '\n\nBiztos vagy benne?')) return
  await _intezoPurgeKeres({ rel: entry.rel })
}

/** A Kuka teljes kiuritese -- a mappa marad, a tartalma nem. */
async function _intezoEmptyKuka() {
  if (!confirm(t('intezo.empty_trash_confirm'))) return
  await _intezoPurgeKeres({ rel: _INTEZO_KUKA })
}

// A ketto ugyanazt a vegpontot hivja, ugyanazzal a masodik kerdessel: ha
// git-repo is menne vele, a szerver ELOSZOR megall es megmondja, mennyi es mi.
// A fel nem toltott munka az egyetlen dolog itt, ami nem all helyre sehonnan.
async function _intezoPurgeKeres(body) {
  try {
    const r = await _depoPost('/api/life/purge', body)
    showToast(r.message || t('intezo.done'))
  } catch (e) {
    const uz = (e && e.message) ? e.message : t('intezo.purge_failed')
    if (uz.indexOf('git-repó') >= 0 && confirm(uz + '\n\n' + t('intezo.purge_anyway'))) {
      try {
        const r2 = await _depoPost('/api/life/purge', Object.assign({}, body, { force: true }))
        showToast(r2.message || t('intezo.done'))
      } catch (e2) {
        showToast((e2 && e2.message) ? e2.message : t('intezo.purge_failed'))
        return
      }
    } else {
      showToast(uz)
      return
    }
  }
  _intezoClearSelection()
  await _intezoOpen(_intezoPath)
}

/** Uj mappa EGY MASIK mappaba (a jobb klikkelt sorba), nem a mostaniba. */
async function _intezoMkdirInto(rel) {
  const name = prompt(t('intezo.mkdir_prompt'))
  if (!name) return
  try {
    const r = await _depoPost('/api/life/mkdir', { parent: rel, name: name })
    showToast(r.message || t('intezo.done'))
    // BELEPUNK abba a mappaba, amibe az uj mappa kerult -- kulonben a
    // felhasznalo egy olyan listat lat, amiben az uj mappa nincs is benne, es
    // csak hisz a visszajelzesnek. Boss, 2026-08-22: "jobb lenne ha az
    // identitas mappaba menne. hogy lassam hogy megcsinalta e a kk mappat."
    await _intezoOpen(rel)
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.mkdir_failed'))
  }
}

async function _intezoRename(entry) {
  const name = prompt(t('intezo.rename_prompt'), entry.name || '')
  if (!name || name === entry.name) return
  try {
    const r = await _depoPost('/api/life/rename', { rel: entry.rel, name: name })
    showToast(r.message || t('intezo.done'))
    _intezoClearSelection()
    await _intezoOpen(_intezoPath)
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.rename_failed'))
  }
}

/**
 * Torles -- valojaban a Kukaba teszi.
 *
 * A megerosito kerdes KIMONDJA, hogy visszaszerezheto: aki azt hiszi, veglegeset
 * nyom, vagy nem meri megnyomni, vagy utana ijed meg.
 */
async function _intezoTrash(entry) {
  const mi = t(entry.isDir ? 'intezo.the_folder' : 'intezo.the_file')
  if (!confirm(t('intezo.trash_confirm', { what: mi, name: entry.name || entry.rel }))) return
  try {
    const r = await _depoPost('/api/life/trash', { rel: entry.rel })
    showToast(r.message || t('intezo.done'))
    _intezoClearSelection()
    await _intezoOpen(_intezoPath)
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.trash_failed'))
  }
}

async function _intezoMkdir() {
  const name = prompt(t('intezo.mkdir_prompt'))
  if (!name) return
  try {
    const r = await _depoPost('/api/life/mkdir', { parent: _intezoPath, name: name })
    showToast(r.message || t('intezo.done'))
    await _intezoOpen(_intezoPath)
  } catch (e) {
    showToast((e && e.message) ? e.message : t('intezo.mkdir_failed'))
  }
}


// ===========================================================================
// A FA LAKOI -- szemelyek es cegek szerkesztese a feluletrol.
//
// Ez teszi a rendszert telepitesfuggetlenne. A kodban egyetlen valodi nev sincs:
// a kod csak a VAZAT ismeri (SZEMELYES / JOGI / PENZUGY / ...), a neveket
// kizarolag a `store/life-tree.json` adja -- amit eddig csak API-bol lehetett
// irni. Egy frissen telepitett Marveenben a felhasznalo innen epiti fel a
// sajat szerkezetet: terminal, JSON es Claude nelkul.
//
// A szerkesztes a bongeszoben egy egyszeru tombon dolgozik, es CSAK a Mentesre
// megy ki a szerverre. Igy egy felig beirt nev nem valt ki ervenyesitesi hibat
// minden leutesnel.
// ===========================================================================

let _intezoCfg = null
// A szerverbol jovo valaszthato kulcsok (kategoriak, media-tipusok, nevek).
// SZANDEKOSAN nincs itt lemasolt lista: ha a fa bovul, ez maga kovetni fogja.
let _intezoOpts = null

/** Egy szemely ures vaza. A mezoket a szerver alapertelmezesebol toltjuk. */
function _intezoNewPerson(role) {
  const d = (_intezoOpts && _intezoOpts.defaults) || {}
  return {
    id: '', name: '', role: role,
    countries: [],
    countrySplit: (d.countrySplit || []).slice(),
    mediaKinds: (d.mediaKinds || []).slice(),
    mediaGroups: [],
    projects: [],
  }
}

function _intezoNewCompany() {
  const d = (_intezoOpts && _intezoOpts.defaults) || {}
  return { id: '', name: '', countries: [], countrySplit: (d.companyCountrySplit || []).slice() }
}

async function _intezoCfgOpen() {
  const card = document.getElementById('intezoConfigCard')
  if (!card) return
  card.hidden = false
  try {
    _intezoCfg = await _intezoGet('/api/life/config')
  } catch (e) {
    // Ha meg nincs config (uj telepites), NEM hibazunk: egy ures gazdaval
    // indulunk, hogy a felhasznalo azonnal tudjon gepelni.
    _intezoCfg = { persons: [], companies: [] }
  }
  _intezoOpts = _intezoCfg.options || null
  if (!_intezoCfg.persons || !_intezoCfg.persons.length) {
    _intezoCfg.persons = [_intezoNewPerson('owner')]
  }
  if (!_intezoCfg.companies) _intezoCfg.companies = []
  await _intezoTplLoad()
  _intezoCfgRender()
}

function _intezoCfgAddPerson() {
  if (!_intezoCfg) return
  // Az uj szemely SOSE gazda: gazda pontosan egy lehet, es azt mar
  // kivalasztotta a felhasznalo. Igy nem kell hibauzenetet kapnia azert,
  // mert felvett valakit.
  _intezoCfg.persons.push(_intezoNewPerson('person'))
  _intezoCfgRender()
}

function _intezoCfgAddCompany() {
  if (!_intezoCfg) return
  _intezoCfg.companies.push(_intezoNewCompany())
  _intezoCfgRender()
}

// ---------------------------------------------------------------------------
// KESZ SABLONOK
// ---------------------------------------------------------------------------

let _intezoTemplates = null

async function _intezoTplLoad() {
  const box = document.getElementById('intezoTplBox')
  try {
    const r = await _intezoGet('/api/life/templates')
    _intezoTemplates = r.templates || []
    // A `fresh` azt mondja meg, van-e mar sajat beallitas. A sablonok akkor is
    // lathatok maradnak (kesobb is valthat), de figyelmeztetest kapunk melle,
    // hogy a valasztas FELULIRJA a mar beirt neveket.
    _intezoTplRender(!r.fresh)
  } catch (e) {
    if (box) box.hidden = true
  }
}

function _intezoTplRender(collapsed) {
  const el = document.getElementById('intezoTemplates')
  if (!el || !_intezoTemplates) return
  el.innerHTML = _intezoTemplates.map((tpl, i) => {
    // A mappaszam a leghasznosabb informacio a valasztashoz: ebbol latszik,
    // hogy tulzas-e valakinek a "teljes" szerkezet.
    const db = _intezoTplCount(tpl.config)
    return '<div style="border:1px solid var(--border,#3336);border-radius:8px;padding:10px;margin-bottom:8px">'
      + '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
      + '<strong style="flex:1;min-width:180px">' + escapeHtml(tpl.title) + '</strong>'
      + '<span class="subtitle" style="font-size:12px">' + escapeHtml(t('intezo.tpl_count', { n: db })) + '</span>'
      + '<button class="btn-secondary" data-tpl="' + i + '">' + escapeHtml(t('intezo.tpl_pick')) + '</button>'
      + '</div>'
      + '<p class="subtitle" style="margin:6px 0 0">' + escapeHtml(tpl.summary) + '</p>'
      + '<ul style="margin:6px 0 0;padding-left:18px;font-size:13px;opacity:.85">'
      + (tpl.highlights || []).map((h) => '<li>' + escapeHtml(h) + '</li>').join('')
      + '</ul></div>'
  }).join('')
    + (collapsed
      ? '<p class="subtitle" style="font-size:12px">' + escapeHtml(t('intezo.tpl_overwrite_note')) + '</p>'
      : '')

  el.querySelectorAll('[data-tpl]').forEach((b) => {
    b.addEventListener('click', () => {
      const tpl = _intezoTemplates[Number(b.getAttribute('data-tpl'))]
      if (!tpl) return
      // MEGERSITES, ha van mit elveszteni. A sablon a NEVEKET irja felul; ha
      // a felhasznalo mar begepelte a csaladjat, azt nem nyeljuk el szotlanul.
      const named = (_intezoCfg.persons || []).some((x) => (x.name || '').trim())
      if (named && !confirm(t('intezo.tpl_confirm'))) return
      _intezoCfg.persons = JSON.parse(JSON.stringify(tpl.config.persons))
      _intezoCfg.companies = JSON.parse(JSON.stringify(tpl.config.companies))
      _intezoCfgRender()
      showToast(t('intezo.tpl_loaded'))
      const first = document.querySelector('[data-cfg="pname"]')
      if (first) { first.focus(); first.select() }
    })
  })
}

/** Durva becsles a mappaszamra -- csak nagysagrendet mutat a valasztashoz. */
function _intezoTplCount(cfg) {
  const cats = ((_intezoOpts && _intezoOpts.personCategories) || []).length || 12
  let n = 0
  for (const p of cfg.persons || []) {
    const split = (p.countrySplit || []).length
    const c = (p.countries || []).length
    n += 1 + cats + split * c
    n += 1 + (p.mediaKinds || []).length * (1 + c) * Math.max(1, (p.mediaGroups || []).length)
    n += (p.projects || []).length * 6
  }
  n += (cfg.companies || []).length * 12
  return n + 12
}

/** A beirt szoveget listava. Vesszo VAGY pontosvesszo -- ki hogy szokta. */
function _intezoCfgList(text) {
  return String(text || '').split(/[,;]/).map((x) => x.trim()).filter(Boolean)
}

/** Egy jelolonegyzet-sor. `sel` a bepipaltak listaja. */
function _intezoBoxRow(items, sel, cfgKey, i, title, hint) {
  if (!items || !items.length) return ''
  return '<div style="margin-top:10px">'
    + '<div style="font-size:13px;font-weight:600">' + escapeHtml(title) + '</div>'
    + (hint ? '<div style="font-size:12px;opacity:.7;margin-bottom:4px">' + escapeHtml(hint) + '</div>' : '')
    + '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:4px">'
    + items.map((o) =>
      '<label style="font-size:12px;white-space:nowrap">'
      + '<input type="checkbox" data-cfg="' + cfgKey + '" data-i="' + i + '" data-key="' + escapeHtml(o.key) + '"'
      + ((sel || []).indexOf(o.key) >= 0 ? ' checked' : '') + '> ' + escapeHtml(o.label) + '</label>').join('')
    + '</div></div>'
}

/** Melyik kategoriak bomoljanak orszagra ennel a szemelynel. */
function _intezoSplitBoxes(p, i) {
  if (!_intezoOpts) return ''
  if (!(p.countries || []).length) return ''  // orszag nelkul nincs mit bontani
  const items = (_intezoOpts.personCategories || []).slice()
  // A MEDIA orszagbontasa KULON kulcs a szerveren (`MEDIA_COUNTRY_KEY`), de az
  // erteke ugyanaz a 'media' sztring, ami a szemelyi kategoriak kozott is ott
  // all. Amig ezt a sort `push` vegezte, a Media KETSZER jelent meg a listaban
  // (Boss, 2026-08-23: „miert van ketszer felsorolva?"): ket jelolonegyzet
  // ugyanarra az EGY beallitasra: az egyiket atkattintva a masik pipaja
  // ujrarajzolasig hazudott. Ezert a meglevo tetelt CIMKEZZUK AT -- es csak
  // akkor teszunk hozza ujat, ha a szerver egy nap tenyleg kulon kulcsot ad.
  const mk = _intezoOpts.mediaCountryKey
  const suffix = ' ' + t('intezo.cfg_media_suffix')
  const at = items.findIndex((o) => o.key === mk)
  if (at >= 0) items[at] = { key: mk, label: items[at].label + suffix }
  else items.push({ key: mk, label: _intezoOpts.mediaLabel + suffix })
  return _intezoBoxRow(items, p.countrySplit, 'psplit', i,
    t('intezo.cfg_split_title'), t('intezo.cfg_split_hint'))
}

/** Melyik media-tipusok keszuljenek el. */
function _intezoKindBoxes(p, i) {
  if (!_intezoOpts) return ''
  return _intezoBoxRow(_intezoOpts.mediaKinds, p.mediaKinds, 'pkinds', i,
    t('intezo.cfg_kinds_title'), t('intezo.cfg_kinds_hint'))
}

function _intezoCompanySplitBoxes(c, i) {
  if (!_intezoOpts) return ''
  if (!(c.countries || []).length) return ''
  return _intezoBoxRow(_intezoOpts.companyCategories, c.countrySplit, 'csplit', i,
    t('intezo.cfg_csplit_title'), '')
}

/** A szemely sajat projektjei (specifikacio 12-13., 31. pont). */
function _intezoProjectRows(p, i) {
  const rows = (p.projects || []).map((pr, j) =>
    '<div style="display:flex;gap:6px;align-items:center;margin-top:4px">'
    + '<input type="text" data-cfg="prname" data-i="' + i + '" data-j="' + j + '" style="flex:1;min-width:140px" '
    + 'placeholder="' + escapeHtml(t('intezo.cfg_project_ph')) + '" value="' + escapeHtml(pr.name || '') + '">'
    + '<label style="font-size:12px;white-space:nowrap"><input type="checkbox" data-cfg="prdev" '
    + 'data-i="' + i + '" data-j="' + j + '"' + (pr.development !== false ? ' checked' : '') + '> '
    + escapeHtml(t('intezo.cfg_project_dev')) + '</label>'
    + '<button class="btn-secondary" data-cfg="prdel" data-i="' + i + '" data-j="' + j + '">✕</button>'
    + '</div>').join('')
  return '<div style="margin-top:10px">'
    + '<div style="font-size:13px;font-weight:600">' + escapeHtml(t('intezo.cfg_projects')) + '</div>'
    + '<div style="font-size:12px;opacity:.7">' + escapeHtml(t('intezo.cfg_projects_hint')) + '</div>'
    + rows
    + '<button class="btn-secondary" data-cfg="pradd" data-i="' + i + '" style="margin-top:6px">'
    + escapeHtml(t('intezo.cfg_add_project')) + '</button>'
    + '</div>'
}

function _intezoCfgRender() {
  const ps = document.getElementById('intezoPersons')
  const cs = document.getElementById('intezoCompanies')
  if (!ps || !cs || !_intezoCfg) return

  ps.innerHTML = _intezoCfg.persons.map((p, i) =>
    '<div style="border:1px solid var(--border,#3336);border-radius:8px;padding:10px;margin-bottom:8px">'
    + '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
    + '<input type="text" data-cfg="pname" data-i="' + i + '" placeholder="' + escapeHtml(t('intezo.cfg_name_ph')) + '" '
    + 'style="flex:1;min-width:180px" value="' + escapeHtml(p.name || '') + '">'
    + '<label style="font-size:13px"><input type="radio" name="intezoOwner" data-cfg="powner" data-i="' + i + '"'
    + (p.role === 'owner' ? ' checked' : '') + '> ' + escapeHtml(t('intezo.cfg_owner')) + '</label>'
    + '<button class="btn-secondary" data-cfg="pdel" data-i="' + i + '" title="'
    + escapeHtml(t('intezo.cfg_del_row')) + '">✕</button>'
    + '</div>'
    + '<div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">'
    + '<input type="text" data-cfg="pcountries" data-i="' + i + '" style="flex:1;min-width:180px" '
    + 'placeholder="' + escapeHtml(t('intezo.cfg_countries_ph')) + '" '
    + 'value="' + escapeHtml((p.countries || []).join(', ')) + '">'
    + '<input type="text" data-cfg="pmedia" data-i="' + i + '" style="flex:1;min-width:180px" '
    + 'placeholder="' + escapeHtml(t('intezo.cfg_groups_ph')) + '" '
    + 'value="' + escapeHtml((p.mediaGroups || []).join(', ')) + '">'
    + '</div>'
    + '<div style="font-size:12px;opacity:.7;margin-top:6px">' + escapeHtml(t('intezo.cfg_countries_hint')) + '</div>'
    + _intezoSplitBoxes(p, i)
    + _intezoKindBoxes(p, i)
    + _intezoProjectRows(p, i)
    + '</div>').join('')

  cs.innerHTML = _intezoCfg.companies.map((c, i) =>
    '<div style="border:1px solid var(--border,#3336);border-radius:8px;padding:10px;margin-bottom:8px">'
    + '<div style="display:flex;gap:8px;align-items:center">'
    + '<input type="text" data-cfg="cname" data-i="' + i + '" style="flex:1;min-width:180px" '
    + 'placeholder="' + escapeHtml(t('intezo.cfg_company_ph')) + '" value="' + escapeHtml(c.name || '') + '">'
    + '<button class="btn-secondary" data-cfg="cdel" data-i="' + i + '" title="'
    + escapeHtml(t('intezo.cfg_del_row')) + '">✕</button>'
    + '</div>'
    + '<input type="text" data-cfg="ccountries" data-i="' + i + '" style="width:100%;margin-top:8px" '
    + 'placeholder="' + escapeHtml(t('intezo.cfg_ccountries_ph')) + '" '
    + 'value="' + escapeHtml((c.countries || []).join(', ')) + '">'
    + _intezoCompanySplitBoxes(c, i)
    + '</div>').join('')
    || '<p class="subtitle">' + escapeHtml(t('intezo.cfg_no_company')) + '</p>'

  // A beirt szoveget azonnal visszairjuk a modellbe, kulonben egy ujrarajzolas
  // (pl. "+ Szemely") eldobna, amit a felhasznalo eppen beirt.
  const wire = (el) => {
    const i = Number(el.getAttribute('data-i'))
    const what = el.getAttribute('data-cfg')
    if (what === 'pdel' || what === 'cdel') {
      el.addEventListener('click', () => {
        if (what === 'pdel') _intezoCfg.persons.splice(i, 1)
        else _intezoCfg.companies.splice(i, 1)
        if (!_intezoCfg.persons.length) _intezoCfg.persons = [_intezoNewPerson('owner')]
        _intezoCfgRender()
      })
      return
    }
    if (what === 'psplit' || what === 'pkinds' || what === 'csplit') {
      el.addEventListener('change', () => {
        const key = el.getAttribute('data-key')
        const target = what === 'csplit' ? _intezoCfg.companies[i] : _intezoCfg.persons[i]
        const field = what === 'pkinds' ? 'mediaKinds' : 'countrySplit'
        const list = (target[field] || []).slice()
        const at = list.indexOf(key)
        if (el.checked) { if (at < 0) list.push(key) } else if (at >= 0) list.splice(at, 1)
        target[field] = list
      })
      return
    }
    if (what === 'pradd' || what === 'prdel') {
      el.addEventListener('click', () => {
        const p = _intezoCfg.persons[i]
        if (!p.projects) p.projects = []
        if (what === 'pradd') p.projects.push({ id: '', name: '', development: true })
        else p.projects.splice(Number(el.getAttribute('data-j')), 1)
        _intezoCfgRender()
      })
      return
    }
    if (what === 'prdev') {
      el.addEventListener('change', () => {
        _intezoCfg.persons[i].projects[Number(el.getAttribute('data-j'))].development = el.checked
      })
      return
    }
    if (what === 'prname') {
      el.addEventListener('input', () => {
        _intezoCfg.persons[i].projects[Number(el.getAttribute('data-j'))].name = el.value
      })
      return
    }
    if (what === 'powner') {
      el.addEventListener('change', () => {
        _intezoCfg.persons.forEach((p, k) => { p.role = (k === i) ? 'owner' : 'person' })
      })
      return
    }
    el.addEventListener('input', () => {
      const v = el.value
      if (what === 'pname') _intezoCfg.persons[i].name = v
      else if (what === 'pcountries') {
        _intezoCfg.persons[i].countries = _intezoCfgList(v)
        // Az elso orszag beirasakor jelennek meg a bontas-negyzetek. Ujrarajzolas
        // NELKUL a felhasznalo azt hinne, nincs is ilyen lehetoseg -- de csak az
        // ures->nem-ures atmenetnel, kulonben minden leutesnel elveszne a fokusz.
        if (_intezoCfg.persons[i].countries.length === 1) setTimeout(_intezoCfgRender, 0)
      }
      else if (what === 'ccountries') {
        _intezoCfg.companies[i].countries = _intezoCfgList(v)
        if (_intezoCfg.companies[i].countries.length === 1) setTimeout(_intezoCfgRender, 0)
      }
      else if (what === 'pmedia') _intezoCfg.persons[i].mediaGroups = _intezoCfgList(v)
      else if (what === 'cname') _intezoCfg.companies[i].name = v
    })
  }
  ps.querySelectorAll('[data-cfg]').forEach(wire)
  cs.querySelectorAll('[data-cfg]').forEach(wire)
}

async function _intezoCfgSave() {
  if (!_intezoCfg) return
  const msg = document.getElementById('intezoCfgMsg')
  const prev = document.getElementById('intezoCfgPreview')
  try {
    const r = await _depoPost('/api/life/config', _intezoCfg)
    _intezoCfg = r.config || _intezoCfg
    if (msg) { msg.hidden = true; msg.textContent = '' }
    _intezoCfgRender()
    // ELONEZET: pontosan az a lista, ami letre fog jonni. A felhasznalo igy
    // MEG a lemezre iras elott lathatja, hogy elgepelte-e a nevet.
    const st = r.status || {}
    const miss = st.missing || []
    if (prev) {
      prev.innerHTML = miss.length
        ? ('<p>' + t('intezo.cfg_preview_head', { n: miss.length }) + '</p>'
           + '<div style="max-height:220px;overflow:auto;font-family:monospace;font-size:12px;opacity:.85">'
           + miss.slice(0, 300).map((m) => escapeHtml(m)).join('<br>')
           + (miss.length > 300 ? '<br>' + escapeHtml(t('intezo.cfg_preview_more', { n: miss.length - 300 })) : '') + '</div>')
        : '<p>' + escapeHtml(t('intezo.cfg_preview_none')) + '</p>'
    }
    showToast(t('intezo.cfg_saved'))
    await _intezoStatus()
    // Boss: „igazan felugorhatna az oldal tetejere ahhoz a gombhoz amit
    // szinten meg kell nyomnom." A mentes utan a kovetkezo lepes gombja az
    // oldal TETEJEN van -- ha nem visszuk oda, a felhasznalo azt hiszi, kesz.
    const box = document.getElementById('intezoSetupBox')
    if (box && !box.hidden) {
      box.scrollIntoView({ behavior: 'smooth', block: 'center' })
      // Rovid kiemeles: a szem odataláljon a gombra a dobozon belul is.
      const btn = document.getElementById('intezoEnsureBtn')
      if (btn) {
        btn.style.outline = '3px solid var(--accent,#f0a500)'
        btn.style.outlineOffset = '3px'
        setTimeout(() => { btn.style.outline = ''; btn.style.outlineOffset = '' }, 4000)
      }
    }
  } catch (e) {
    // A szerver ervenyesito uzenete MAGYAR MONDAT, ami megmondja, mit tegyen
    // ("Pontosan egy szemely legyen a gazda") -- ezt mutatjuk valtozatlanul.
    if (msg) { msg.hidden = false; msg.textContent = (e && e.message) ? e.message : t('intezo.cfg_save_failed') }
    if (prev) prev.innerHTML = ''
  }
}

// ============================================================
// === Kod-hid (VS Code Claude Code bridge) ===
//
// A hid szerver-oldala 2026-08-20 ota kesz volt, de KIZAROLAG .env-bol es
// parancssorbol lehetett uzemeltetni: egy friss telepitesen semmit nem lehetett
// belole elinditani a feluletrol. Ez a modul az a felulet.
//
// Ket dolgot csinal, amit a REST onmagaban nem tud megmondani:
//   * kimondja, ha a VEGREHAJTO all. A hid egyetlen nema hibamodja ez -- a
//     feladatok gyulnek a sorban, a lap zolden mutat, es kivulrol semmi nem
//     arulja el. (Merve 2026-08-22: a worker 08-20 19:47 ota allt, es az egyetlen
//     nyoma egy ures projekt-lista volt.)
//   * megmondja, MIT KELL TENNI, nem csak azt, hogy baj van.
// ============================================================
;(function () {
  let _cbTimer = null
  let _cbLastHealth = null
  let _cbProjects = []
  let _cbCandidates = []
  // A MENTETT kizarasi lista (kisbetusen). `null` = meg nem kerdeztuk le.
  // Ebbol latszik, hogy egy kizart mappa feloldasa MAR EL VAN MENTVE, csak a
  // vezerlopult ujrainditasara var -- kulonben a "Kizaras feloldasa" gomb a
  // kattintas utan is ott maradna, mintha nem tortent volna semmi.
  let _cbSavedExclude = null

  window.__cbStopPollImpl = function () {
    if (_cbTimer) { clearInterval(_cbTimer); _cbTimer = null }
  }

  async function cbFetch(path, opts) {
    const res = await fetch(path, opts)
    const text = await res.text()
    let data = null
    try { data = text ? JSON.parse(text) : null } catch (e) { /* nem JSON */ }
    if (!res.ok) throw new Error((data && data.error) || ('HTTP ' + res.status))
    return data
  }

  function cbPostJson(path, body) {
    return cbFetch(path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })
  }

  // Magyar, emberi idokulonbseg. A "mikor jelentkezett utoljara" a lap
  // legfontosabb adata, ezert nem ISO-datumot mutatunk.
  function cbAgo(ms) {
    if (!ms) return t('cb.ago.never')
    const d = Math.max(0, Date.now() - ms)
    const s = Math.round(d / 1000)
    if (s < 60) return t('cb.ago.seconds', { n: s })
    const m = Math.round(s / 60)
    if (m < 60) return t('cb.ago.minutes', { n: m })
    const h = Math.round(m / 60)
    if (h < 48) return t('cb.ago.hours', { n: h })
    return t('cb.ago.days', { n: Math.round(h / 24) })
  }

  function cbDur(ms) {
    if (ms === null || ms === undefined) return ''
    if (ms < 1000) return ms + ' ms'
    const s = Math.round(ms / 1000)
    if (s < 60) return s + ' mp'
    const m = Math.floor(s / 60)
    return m + ' p ' + (s % 60) + ' mp'
  }

  const CB_STATUS_HU = {
    queued: 'sorban', running: 'fut', done: 'kész', error: 'hiba', cancelled: 'megszakítva',
  }

  // ---- allapot ---------------------------------------------------------

  // ---- beuzemeles (friss telepites) ------------------------------------
  //
  // Egy frissen letoltott Marveenben a kod-hid harom dolog nelkul semmit nem
  // csinal, es egyik sem talalhato ki a lapot nezve: be kell kapcsolni, fel
  // kell tenni a Windows-vegrehajtot, es kell legalabb egy VS Code Claude Code
  // session. Ez a harom eddig szet volt szorva negy kartya kozott, sorrend
  // nelkul -- vagyis pontosan az a "manualisan beallitani" allapot, amit egy
  // friss telepites nem enged meg (Boss, 2026-08-22).
  //
  // A negyedik lepes (Telegram kod-bot) szandekosan NEM kotelezo: a felulet es
  // a Marvin-atadas nelkule is megy. Ezert a doboz akkor tunik el, ha a harom
  // KOTELEZO pont kesz -- egy mukodo hidon egy allando teendo-lista mar csak
  // zaj lenne.
  function cbSetupStepList(h) {
    return [
      {
        done: Boolean(h.enabled),
        title: 'A kód-híd be van kapcsolva',
        todo: 'A <em>Működés</em> kártyán kapcsold be, majd indítsd újra a vezérlőpultot az ott megjelenő gombbal.',
        target: 'cbOpsCard',
        optional: false,
      },
      {
        done: Boolean(h.workerOnline),
        title: 'A Windows-végrehajtó fut',
        todo: 'A <em>Windows-végrehajtó</em> kártyán töltsd le a két fájlt, és futtasd a kimásolható parancsot a Windows-gépen. Enélkül a feladatok csak gyűlnek a sorban.',
        target: 'cbWorkerCard',
        optional: false,
      },
      {
        done: Number(h.sessions) > 0,
        title: 'Van legalább egy regisztrált projekt',
        todo: 'Nyiss meg egy projektet VS Code-ban Claude Code-dal, és küldj benne egy üzenetet — a felderítés egy percen belül bejegyzi. Ha a projekt a <em>Működés</em> kártyán a kizártak közt van, előbb vedd ki onnan. A <em>Projektek</em> kártyán kézzel is felvehető.',
        target: 'cbProjectsCard',
        optional: false,
      },
      {
        done: Boolean(h.botConfigured),
        title: 'Telegram kód-bot',
        todo: 'BotFathertől kérj egy <strong>külön</strong> botot (a fő bot tokenjét nem lehet megosztani), és illeszd be a tokent. Enélkül a felület és a Marvin-átadás működik, csak a Telegramos <code>/code</code> parancs nem.',
        target: 'cbBotCard',
        optional: true,
      },
    ]
  }

  function cbRenderSetup(h) {
    const card = document.getElementById('cbSetupCard')
    if (!card) return
    const steps = cbSetupStepList(h)
    const required = steps.filter(function (s) { return !s.optional })
    const doneCount = required.filter(function (s) { return s.done }).length
    if (doneCount === required.length) { card.hidden = true; return }
    card.hidden = false

    const prog = document.getElementById('cbSetupProgress')
    if (prog) prog.textContent = doneCount + '/' + required.length + ' kötelező lépés kész'

    const box = document.getElementById('cbSetupSteps')
    if (!box) return
    box.innerHTML = ''
    steps.forEach(function (s, i) {
      const row = document.createElement('div')
      row.className = 'cb-setup-step'
      row.style.cssText = 'display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-top:1px solid var(--border-color,#30363d)'
      row.innerHTML =
        '<span style="font-size:14px;line-height:1.6;min-width:16px;color:' + (s.done ? '#3fb950' : '#8b949e') + '">' +
          (s.done ? '&#10003;' : (i + 1) + '.') + '</span>' +
        '<div style="flex:1;min-width:0">' +
          '<div style="font-size:14px">' + escapeHtml(s.title) +
            (s.optional ? ' <span class="subtitle">(nem kötelező)</span>' : '') + '</div>' +
          (s.done ? '' : '<div class="subtitle" style="margin-top:3px">' + s.todo + '</div>') +
        '</div>'
      if (!s.done) {
        const btn = document.createElement('button')
        btn.className = 'btn-secondary btn-compact'
        btn.textContent = 'Ugrás'
        btn.addEventListener('click', function () {
          const target = document.getElementById(s.target)
          if (!target) return
          target.scrollIntoView({ behavior: 'smooth', block: 'center' })
          // Rovid kiemeles: egy hosszu lapon kulonben nem latszik, hova ugrott.
          target.style.transition = 'box-shadow .3s'
          target.style.boxShadow = '0 0 0 2px #58a6ff'
          setTimeout(function () { target.style.boxShadow = '' }, 1600)
        })
        row.appendChild(btn)
      }
      box.appendChild(row)
    })
  }

  function cbRenderHealth(h) {
    const box = document.getElementById('cbHealthBox')
    const el = document.getElementById('cbHealthText')
    if (!box || !el) return
    const lines = []
    let tone = 'ok'

    if (!h.enabled) {
      tone = 'warn'
      lines.push('<strong>A kód-híd ki van kapcsolva.</strong> A <em>Működés</em> kártyán kapcsold be, majd indítsd újra a vezérlőpultot.')
    } else if (!h.workerOnline) {
      tone = 'bad'
      if (!h.lastSeenAt) {
        lines.push('<strong>A Windows-végrehajtó még soha nem jelentkezett.</strong> Enélkül a híd sorba tesz, de semmi nem fut le. A lap alján lévő <em>Windows-végrehajtó</em> kártya két lépésben feltelepíti.')
      } else {
        lines.push('<strong>' + escapeHtml(t('cb.health.worker_offline')) + '</strong> ' + escapeHtml(t('cb.health.worker_offline_since', { ago: cbAgo(h.lastSeenAt) })))
      }
    } else {
      lines.push('<strong>' + escapeHtml(t('cb.health.worker_online')) + '</strong> (' + escapeHtml(h.workers[0] && h.workers[0].host ? h.workers[0].host : t('cb.health.unknown_host')) + ', ' + cbAgo(h.lastSeenAt) + ').')
    }

    if (h.enabled && h.workerOnline && h.sessions === 0) {
      tone = tone === 'ok' ? 'warn' : tone
      lines.push('<strong>Nincs regisztrált projekt.</strong> Nyiss meg egy projektet VS Code-ban Claude Code-dal, és a felderítés egy percen belül bejegyzi. Ha a projekt szerepel a kizártak közt, előbb vedd ki onnan.')
    }

    const bits = []
    bits.push(h.sessions + ' projekt')
    bits.push(h.queued + ' sorban')
    bits.push(h.running + ' fut')
    if (h.done24h) bits.push(h.done24h + ' kész (24 óra)')
    if (h.failed24h) bits.push('<strong>' + h.failed24h + ' hibás (24 óra)</strong>')
    lines.push(bits.join(' · '))

    if (!h.botConfigured) {
      lines.push('A Telegram kód-bot nincs beállítva — a <code>/code</code> parancs innen még nem használható. (A felület és a Marvin-átadás enélkül is megy.)')
    }
    el.innerHTML = lines.map(function (l) { return '<p style="margin:4px 0">' + l + '</p>' }).join('')
    box.style.borderLeft = '4px solid ' + (tone === 'bad' ? '#e5534b' : tone === 'warn' ? '#d29922' : '#3fb950')

    // A telepito parancs a VALODI utvonalakkal, nem sablonnal.
    const hint = h.installHint || {}
    const cmd = document.getElementById('cbInstallCmd')
    // Hogyan jut a worker a dashboard-tokenhez. Ha Marveen es a worker UGYANAZON
    // a gepen van (WSL vagy nativ Windows), van kozos utvonal -- akkor a
    // -TokenPath a helyes, mert a token soha nem kerul a vagolapra, a
    // parancssor-elozmenyekbe vagy egy kepernyokepre. Kulon gepen ilyen ut
    // NINCS: ott a -Token az egyetlen jarhato mod, es a lap megmondja, melyik
    // fajlbol kell kimasolni. Eddig a lap minden telepitesnek a sajat gepem
    // \\wsl.localhost utjat kinalta, ami maskent telepitve nem letezik.
    const authArg = hint.tokenPath
      ? '-TokenPath "' + hint.tokenPath + '"'
      : '-Token "<IDE-MASOLD-A-TOKENT>"'
    if (cmd) {
      cmd.textContent =
        'powershell -ExecutionPolicy Bypass -File "$env:USERPROFILE\\marvin-code-worker\\marvin-code-worker.ps1" ' +
        '-BaseUrl "' + window.location.origin + '" ' + authArg + '\n\n' +
        '$t = "`"$env:USERPROFILE\\marvin-code-worker\\marvin-code-worker.cmd`""' + '\n' +
        'schtasks /create /f /tn "MarvinCodeWorker" /sc minute /mo 5 /tr $t'
    }
    const note = document.getElementById('cbInstallNote')
    if (note) {
      if (hint.tokenPath) {
        note.hidden = true
        note.textContent = ''
      } else {
        note.hidden = false
        note.innerHTML = 'A Marveen nem ezen a Windows-gépen fut, ezért a tokenhez nincs közös útvonal: ' +
          'nyisd meg a Marveen gépén a <code>' + escapeHtml(hint.tokenFile || 'store/.dashboard-token') +
          '</code> fájlt, és a tartalmát írd a <code>-Token</code> helyére. ' +
          'A <code>-BaseUrl</code> az a cím, amin ezt a lapot most eléred (<code>' +
          escapeHtml(window.location.origin) + '</code>) &mdash; ha ez <code>localhost</code>, ' +
          'írd át a Marveen gép hálózati címére, különben a worker saját magát keresné.'
      }
    }
    // A bevezeto mondat is telepites-fuggo: a "Marveen a WSL-ben fut" egyetlen
    // topologiara igaz, es egy friss telepites allhat nativ Windowson vagy egy
    // kulon Linux-gepen is.
    const intro = document.getElementById('cbWorkerIntro')
    if (intro) {
      const where = hint.hostKind === 'wsl'
        ? 'A Marveen a WSL-ben fut és <strong>nem</strong> éri el a Windows fájlrendszerét, ezért a Windows-oldali worker '
        : hint.hostKind === 'windows'
          ? 'A Marveen ezen a Windowson fut, a <code>claude.exe</code>-t viszont a saját munkameneted alatt kell indítani, ezért a worker külön folyamat. A worker '
          : 'A Marveen nem Windowson fut, ezért a végrehajtót arra a Windows-gépre kell feltenni, ahol a VS Code Claude Code sessionjeid vannak. A worker '
      intro.innerHTML = where +
        '<strong>befelé</strong> kérdez: ő veszi ki a feladatot és ő indítja a <code>claude.exe</code>-t. ' +
        'Nem nyit portot, nem hallgat a hálózaton, és nem kattintgat &mdash; sima gyerekfolyamat. ' +
        'Nélküle a híd sorba tesz, de semmi nem fut le.'
    }
    const seen = document.getElementById('cbWorkerSeen')
    if (seen) {
      seen.innerHTML = h.workers && h.workers.length
        ? h.workers.map(function (w) {
            return escapeHtml(w.host) + ' — ' + cbAgo(w.lastSeenAt) +
              (w.lastAction ? ' (' + escapeHtml(w.lastAction) + ')' : '') +
              (w.sessionsReported !== null && w.sessionsReported !== undefined ? ', ' + w.sessionsReported + ' sessiont látott' : '')
          }).join('<br>')
        : 'Még egyetlen végrehajtó sem jelentkezett be.'
    }

    cbRenderSetup(h)
  }

  // ---- projektek -------------------------------------------------------

  function cbRenderProjects(projects) {
    _cbProjects = projects || []
    const el = document.getElementById('cbProjectsTable')
    if (!el) return
    if (!_cbProjects.length) {
      el.innerHTML = '<p class="subtitle">Nincs egyetlen regisztrált projekt sem.</p>'
    } else {
      el.innerHTML =
        '<table style="width:100%;border-collapse:collapse;font-size:14px">' +
        '<thead><tr>' +
        ['Projekt', 'Workspace', 'Session', 'Kitűzve', 'Frissült', ''].map(function (h) {
          return '<th style="text-align:left;padding:6px 8px;border-bottom:1px solid var(--border,#333)">' + h + '</th>'
        }).join('') +
        '</tr></thead><tbody>' +
        _cbProjects.map(function (p) {
          return '<tr>' +
            '<td style="padding:6px 8px"><strong>' + escapeHtml(p.project) + '</strong></td>' +
            '<td style="padding:6px 8px"><code>' + escapeHtml(p.workspacePath) + '</code></td>' +
            '<td style="padding:6px 8px" title="' + escapeAttr(p.sessionId) + '"><code>' + escapeHtml(String(p.sessionId).slice(0, 8)) + '…</code></td>' +
            '<td style="padding:6px 8px">' + (p.pinned ? 'igen' : '—') + '</td>' +
            '<td style="padding:6px 8px">' + cbAgo(p.updatedAt) + '</td>' +
            '<td style="padding:6px 8px;white-space:nowrap">' +
              '<button class="btn-secondary btn-compact cb-pin" data-project="' + escapeAttr(p.project) + '" data-pinned="' + (p.pinned ? '1' : '0') + '">' +
                (p.pinned ? 'Elenged' : 'Kitűz') + '</button> ' +
              '<button class="btn-secondary btn-compact cb-del" data-project="' + escapeAttr(p.project) + '">Törlés</button>' +
            '</td>' +
          '</tr>'
        }).join('') +
        '</tbody></table>'
    }

    // A feladat-kuldo legordulo ugyanebbol az egy forrasbol el.
    const sel = document.getElementById('cbTaskProject')
    if (sel) {
      const prev = sel.value
      sel.innerHTML = _cbProjects.length
        ? _cbProjects.map(function (p) { return '<option value="' + escapeAttr(p.project) + '">' + escapeHtml(p.project) + '</option>' }).join('')
        : '<option value="">— nincs regisztrált projekt —</option>'
      if (prev && _cbProjects.some(function (p) { return p.project === prev })) sel.value = prev
    }
    // A ful-legordulo a projekt-valasztast koveti: projekt-valtasnal mas fulek
    // tartoznak hozza.
    cbRenderTabOptions()
  }

  // ---- chat fulek ------------------------------------------------------
  //
  // Boss (2026-08-23): "nem fogok en foglalkozni ezzel ... hanem majd fogom
  // kerni a maximum azt, hogy listazza ki, hogy milyen chatfulek vannak".
  // Ezert nincs itt sem elnevezes, sem kituzes, sem UUID-gepeles: a lista maga
  // a termek. A cimzest vagy a fenti legordulo, vagy Marvin intezi
  // (`GET /api/code/tabs` -> `POST /api/code/tasks` `sessionId`).
  var _cbTabs = { projects: [], reason: 'worker-never', window: { maxTabsPerProject: 10, maxAgeDays: 21 } }

  function cbTabTitle(tab) {
    return tab && tab.title ? tab.title : t('cb.tabs.no_title')
  }

  function cbRenderTabs(view) {
    const el = document.getElementById('cbTabsBox')
    if (!el) return
    if (view && view.disabled) {
      // KIKAPCSOLT hid: ilyenkor a "nem jelentkezett a vegrehajto" TALALGATAS
      // lenne -- az ok ismert, es azt kell kiirni.
      _cbTabs = { projects: [], reason: 'worker-never', window: _cbTabs.window }
      el.innerHTML = '<p class="subtitle">' + escapeHtml(t('cb.tabs.disabled')) + '</p>'
      cbRenderTabOptions()
      return
    }
    if (view && view.error) {
      _cbTabs = { projects: [], reason: 'worker-never', window: _cbTabs.window }
      el.innerHTML = '<p class="subtitle">' + escapeHtml(t('cb.tabs.error', { msg: view.error })) + '</p>'
      cbRenderTabOptions()
      return
    }
    _cbTabs = view || { projects: [], reason: 'worker-never', window: _cbTabs.window }
    const projects = _cbTabs.projects || []

    if (!projects.length) {
      // A NULLA ket dolgot jelenthet -- a szerver `reason` mezoje mondja meg,
      // melyiket --, es ezt SOSE szabad a lista hosszabol kitalalni.
      const key = _cbTabs.reason === 'empty' ? 'cb.tabs.empty'
        : _cbTabs.reason === 'not-reported-yet' ? 'cb.tabs.not_reported_yet'
        : _cbTabs.reason === 'worker-stale' ? 'cb.tabs.worker_stale'
        : 'cb.tabs.worker_never'
      el.innerHTML = '<p class="subtitle">' + escapeHtml(t(key)) + '</p>'
      cbRenderTabOptions()
      return
    }

    let html = ''
    for (const p of projects) {
      const head = p.project
        ? escapeHtml(p.project)
        : escapeHtml(p.workspacePath) + ' <em>(' + escapeHtml(t('cb.tabs.unbound')) + ')</em>'
      html += '<div class="cb-cand" style="display:block">'
        + '<div class="cb-cand-main" style="margin-bottom:6px">'
          + '<span class="cb-cand-name">📁 ' + head + '</span>'
          + '<code class="cb-cand-path">' + escapeHtml(p.workspacePath) + '</code>'
          + '<span class="cb-cand-path">' + escapeHtml(t('cb.tabs.count', { n: (p.tabs || []).length })) + '</span>'
        + '</div>'
        + '<ul style="list-style:none;margin:0;padding:0">'
        + (p.tabs || []).map(function (tab) {
          return '<li style="padding:3px 0;display:flex;gap:8px;align-items:baseline;flex-wrap:wrap">'
            + '<span style="width:1.4em;flex:none">' + (tab.current ? '➡️' : '') + '</span>'
            + '<span' + (tab.current ? ' style="font-weight:600"' : '') + '>' + escapeHtml(cbTabTitle(tab)) + '</span>'
            + '<span class="cb-cand-path">' + cbAgo(tab.mtime) + '</span>'
            + '<code class="cb-cand-path" title="' + escapeAttr(tab.sessionId) + '">' + escapeHtml(tab.shortId) + '</code>'
          + '</li>'
        }).join('')
        + '</ul>'
      + '</div>'
    }
    const w = _cbTabs.window || { maxTabsPerProject: 10, maxAgeDays: 21 }
    html += '<p class="subtitle" style="margin-top:8px">'
      + escapeHtml(t('cb.tabs.window', { n: w.maxTabsPerProject, d: w.maxAgeDays })) + '</p>'
    if (_cbTabs.reason === 'worker-stale') {
      html += '<p class="subtitle">' + escapeHtml(t('cb.tabs.worker_stale')) + '</p>'
    }
    el.innerHTML = html
    cbRenderTabOptions()
  }

  // A legordulo a KIVALASZTOTT projekt fuleit mutatja: egy masik projekt fulere
  // cimezni ugyis hiba lenne, es a lista is athatolhatatlan lenne tole.
  function cbRenderTabOptions() {
    const sel = document.getElementById('cbTaskTab')
    const proj = document.getElementById('cbTaskProject')
    if (!sel) return
    const wanted = proj ? proj.value : ''
    const group = (_cbTabs.projects || []).find(function (p) { return p.project === wanted })
    const prev = sel.value
    let opts = '<option value="">' + escapeHtml(t('cb.tabs.default_option')) + '</option>'
    if (group) {
      opts += (group.tabs || []).map(function (tab) {
        // A cimzes nelkuli celpont mar az elso sorban all, ezert itt nem
        // ismeteljuk meg a nyilat -- de a cimet igen, hogy azonosithato legyen.
        return '<option value="' + escapeAttr(tab.sessionId) + '">'
          + escapeHtml(cbTabTitle(tab)) + ' · ' + escapeHtml(cbAgo(tab.mtime))
          + '</option>'
      }).join('')
    }
    sel.innerHTML = opts
    // A valasztas TULELI a masodpercenkenti frissitest, kulonben gepeles kozben
    // visszaugrana az alapertelmezesre.
    if (prev && sel.querySelector('option[value="' + (window.CSS && CSS.escape ? CSS.escape(prev) : prev) + '"]')) {
      sel.value = prev
    }
  }

  // ---- felderitett mappak ("tallozas") ---------------------------------
  //
  // Boss (2026-08-22): "miert nem lehet kitallozni a projekt mappat? ... miert
  // kellene kezzel megadnom az eleresi utvonalat? hiszen en egy komuves
  // vagyok! hulyebiztosra kell megcsinalni a szoftvert!"
  //
  // Igazi mappa-tallozo NEM lehetseges: a vezerlopult a WSL-ben fut es nem
  // latja a Windows lemezt, a bongeszo pedig valodi eleresi utat sosem ad ki
  // egy lapnak. De nincs is ra szukseg: a WORKER mar bejarta a gepet, es a
  // jelenteseben ott van az eleresi ut ES a session-azonosito is -- eddig ez
  // az adat egyszeruen sosem kerult a felhasznalo ele. A "tallozas" ezert ez
  // a lista.
  //
  // Harom allapot, mert harom kulon teendo tartozik hozzajuk. A KIZART sor
  // kulonosen fontos: a Boss egyetlen projektje pont ki volt zarva, ezert
  // latszott ugy, mintha a felderites nem talalna semmit -- es ezert szorult
  // ra a kezi urlapra.
  function cbSamePath(a, b) {
    const norm = function (x) {
      return String(x == null ? '' : x).trim().replace(/[\\/]+$/, '').replace(/\\/g, '/').toLowerCase()
    }
    return norm(a) !== '' && norm(a) === norm(b)
  }

  function cbRenderCandidates(resp) {
    const el = document.getElementById('cbCandidatesBox')
    if (!el) return
    if (resp && resp.error) {
      _cbCandidates = []
      el.innerHTML = '<p class="subtitle">Nem sikerült lekérdezni a felderített mappákat: '
        + escapeHtml(resp.error) + '</p>'
      return
    }
    if (resp && resp.disabled) {
      _cbCandidates = []
      el.innerHTML = '<p class="subtitle">A kód-híd ki van kapcsolva — kapcsold be lentebb, a <em>Működés</em> résznél.</p>'
      return
    }
    _cbCandidates = (resp && resp.candidates) || []
    const online = Boolean(_cbLastHealth && _cbLastHealth.workerOnline)
    // ★ A NULLA KET DOLGOT JELENTHET. Ha a vegrehajto FUT, de a vezerlopult
    //   indulasa ota meg nem erkezett tole EGY jelentes sem (`reported`), akkor
    //   a nulla nem azt jelenti, hogy nincs nyitva semmi -- azt, hogy meg nem
    //   latunk oda. Eddig ilyenkor is az allt, hogy "nem talalt semmit", ami
    //   ujraindítás után minden alkalommal hazudott egy percig.
    if (!_cbCandidates.length && online && resp && resp.reported === false) {
      el.innerHTML = '<p class="subtitle">' + escapeHtml(t('cb.cand.not_yet_reported')) + '</p>'
      return
    }
    if (!_cbCandidates.length) {
      el.innerHTML = '<p class="subtitle">' + (online
        ? 'A végrehajtó fut, de egyetlen VS Code Claude Code beszélgetést sem talált ezen a gépen. '
          + 'Nyiss meg egy projektet VS Code-ban, indíts benne egy Claude Code beszélgetést — egy percen belül itt lesz.'
        : 'Ehhez előbb el kell indulnia a végrehajtónak (lásd a <em>Windows-végrehajtó</em> részt lentebb): '
          + 'ő járja be a gépet, és ő jelenti a mappákat.') + '</p>'
      return
    }
    el.innerHTML = _cbCandidates.map(function (c) {
      const parts = String(c.workspacePath).split(/[\\/]/).filter(function (x) { return x })
      const folder = parts.length ? parts[parts.length - 1] : c.workspacePath
      let right = ''
      if (c.state === 'registered') {
        right = '<span class="cb-cand-state">\u2713 már fel van véve <strong>' + escapeHtml(c.alias) + '</strong> néven</span>'
      } else if (c.state === 'excluded') {
        const lifted = _cbSavedExclude !== null
          && _cbSavedExclude.indexOf(String(c.alias).toLowerCase()) === -1
        right = lifted
          ? '<span class="cb-cand-state">kizárás feloldva — újraindítás után lép életbe</span>'
          : '<span class="cb-cand-state">kizárva</span> '
            + '<button class="btn-secondary btn-compact cb-cand-unexclude" data-alias="' + escapeAttr(c.alias) + '">Kizárás feloldása</button>'
      } else if (c.state === 'dismissed') {
        // Nem "uj": a felhasznalo TUDATOSAN vette le. Kulon feliratot kap, hogy
        // lassa, mi tortent -- de egy kattintassal visszavehető.
        right = '<span class="cb-cand-state">' + escapeHtml(t('cb.cand.dismissed_state')) + '</span> '
          + '<button class="btn-secondary btn-compact cb-cand-add"'
          + ' data-alias="' + escapeAttr(c.alias) + '"'
          + ' data-ws="' + escapeAttr(c.workspacePath) + '"'
          + ' data-sid="' + escapeAttr(c.sessionId) + '">' + escapeHtml(t('cb.cand.re_add')) + '</button>'
      } else {
        right = '<button class="btn-primary btn-compact cb-cand-add"'
          + ' data-alias="' + escapeAttr(c.alias) + '"'
          + ' data-ws="' + escapeAttr(c.workspacePath) + '"'
          + ' data-sid="' + escapeAttr(c.sessionId) + '">Felvétel</button>'
      }
      return '<div class="cb-cand">'
        + '<div class="cb-cand-main">'
          + '<span class="cb-cand-name">' + escapeHtml(folder) + '</span>'
          + '<code class="cb-cand-path">' + escapeHtml(c.workspacePath) + '</code>'
          + '<span class="cb-cand-path">beszélgetés: ' + cbAgo(c.mtime) + '</span>'
        + '</div>'
        + '<div>' + right + '</div>'
      + '</div>'
    }).join('')
  }

  // ---- feladatok -------------------------------------------------------

  function cbRenderTasks(tasks) {
    const el = document.getElementById('cbTasksList')
    if (!el) return
    if (!tasks || !tasks.length) {
      el.innerHTML = '<p class="subtitle">Még nem futott feladat.</p>'
      return
    }
    el.innerHTML =
      '<table style="width:100%;border-collapse:collapse;font-size:14px">' +
      '<thead><tr>' +
      ['Állapot', 'Projekt', 'Feladat', 'Mikor', 'Idő', 'Költség'].map(function (h) {
        return '<th style="text-align:left;padding:6px 8px;border-bottom:1px solid var(--border,#333)">' + h + '</th>'
      }).join('') +
      '</tr></thead><tbody>' +
      tasks.map(function (t) {
        const color = t.status === 'done' ? '#3fb950' : t.status === 'error' ? '#e5534b'
          : t.status === 'running' ? '#d29922' : 'inherit'
        return '<tr class="cb-task-row" data-id="' + escapeAttr(t.id) + '" style="cursor:pointer">' +
          '<td style="padding:6px 8px;color:' + color + '">' + (CB_STATUS_HU[t.status] || t.status) + '</td>' +
          '<td style="padding:6px 8px">' + escapeHtml(t.project) + '</td>' +
          '<td style="padding:6px 8px">' + escapeHtml(String(t.prompt).slice(0, 70)) + (String(t.prompt).length > 70 ? '…' : '') + '</td>' +
          '<td style="padding:6px 8px">' + cbAgo(t.createdAt) + '</td>' +
          '<td style="padding:6px 8px">' + cbDur(t.durationMs) + '</td>' +
          '<td style="padding:6px 8px">' + (t.costUsd ? ('$' + Number(t.costUsd).toFixed(4)) : '') + '</td>' +
        '</tr>'
      }).join('') +
      '</tbody></table>'
  }

  // A TELJES eredmeny, nem a kivonat: a kivonat a Telegram-ertesitese, ide
  // pontosan azert jon az ember, mert tobbet akar latni annal.
  async function cbOpenTask(id) {
    let task = null
    try { task = await cbFetch('/api/code/tasks/' + encodeURIComponent(id)) } catch (e) {
      showToast('Nem sikerült betölteni: ' + e.message, { type: 'error' }); return
    }
    const old = document.getElementById('cbTaskModal')
    if (old) old.remove()
    const wrap = document.createElement('div')
    wrap.id = 'cbTaskModal'
    wrap.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:24px'
    const body = (task.status === 'error' || task.error) ? (task.error || '(nincs hibaüzenet)') : (task.result || '(nincs eredmény)')
    wrap.innerHTML =
      '<div class="card" style="max-width:900px;width:100%;max-height:80vh;overflow:auto;margin:0">' +
        '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px">' +
          '<h2 style="margin:0">' + escapeHtml(task.project) + ' — ' + (CB_STATUS_HU[task.status] || task.status) + '</h2>' +
          '<button class="btn-secondary btn-compact" id="cbTaskModalClose">Bezárás</button>' +
        '</div>' +
        '<p class="subtitle" style="margin-top:8px">' +
          cbAgo(task.createdAt) + ' · ' + cbDur(task.durationMs) +
          (task.numTurns ? ' · ' + task.numTurns + ' kör' : '') +
          (task.costUsd ? ' · $' + Number(task.costUsd).toFixed(4) : '') +
          (task.host ? ' · ' + escapeHtml(task.host) : '') +
          (task.attempts > 1 ? ' · ' + task.attempts + '. nekifutás' : '') +
        '</p>' +
        '<h3 style="margin-top:14px;font-size:14px">Feladat</h3>' +
        '<pre style="white-space:pre-wrap;word-break:break-word;font-size:13px;padding:10px;border-radius:6px;background:var(--bg-alt,#111)">' + escapeHtml(task.prompt) + '</pre>' +
        '<h3 style="margin-top:14px;font-size:14px">' + ((task.status === 'error' || task.error) ? 'Hiba' : 'Eredmény') + '</h3>' +
        '<pre style="white-space:pre-wrap;word-break:break-word;font-size:13px;padding:10px;border-radius:6px;background:var(--bg-alt,#111)">' + escapeHtml(body) + '</pre>' +
        (task.status === 'queued' ? '<button class="btn-secondary btn-compact" id="cbTaskCancel" style="margin-top:12px">Feladat visszavonása</button>' : '') +
      '</div>'
    document.body.appendChild(wrap)
    const close = function () { wrap.remove() }
    wrap.addEventListener('click', function (e) { if (e.target === wrap) close() })
    const closeBtn = document.getElementById('cbTaskModalClose')
    if (closeBtn) closeBtn.addEventListener('click', close)
    const cancelBtn = document.getElementById('cbTaskCancel')
    if (cancelBtn) cancelBtn.addEventListener('click', async function () {
      try {
        await cbPostJson('/api/code/tasks/' + encodeURIComponent(task.id) + '/cancel', {})
        showToast('Visszavonva.')
        close(); cbRefresh()
      } catch (e) { showToast('Nem sikerült: ' + e.message, { type: 'error' }) }
    })
  }

  // ---- betoltes --------------------------------------------------------

  async function cbRefresh() {
    // Az allapot ELOSZOR es KULON: kikapcsolt hidnal a tobbi vegpont szandekosan
    // 503-at ad, es egy kozos Promise.all-bol 'nem sikerult lekerdezni' lenne --
    // pont az az egy mondat veszne el, ami szamit ('ki van kapcsolva, itt a kapcsolo').
    let health = null
    try {
      health = await cbFetch('/api/code/health')
      _cbLastHealth = health
      cbRenderHealth(health)
      // Az Attekintes ful harom uj eleme. Kikapcsolt hidnal is KELL: pont akkor
      // kell latni az identitast es az "Inditas" gombot.
      cbRenderIdentity(health)
      cbRenderService(health)
      cbRenderTiles(health)
    } catch (e) {
      const el = document.getElementById('cbHealthText')
      if (el) el.innerHTML = '<strong>Nem sikerült lekérdezni a kód-hidat:</strong> ' + escapeHtml(e.message)
      return
    }
    if (health && health.enabled === false) {
      cbRenderProjects([])
      cbRenderTasks([])
      cbRenderCandidates({ disabled: true })
      cbRenderTabs({ disabled: true })
      return
    }
    try {
      const [projects, tasks, cands, tabs] = await Promise.all([
        cbFetch('/api/code/projects'),
        cbFetch('/api/code/tasks?limit=25'),
        // Sajat catch: egy hibas jeloltlista NE vigye magaval a projekt- es a
        // feladat-tablat is -- a sajat dobozaban mondja meg, mi a baj.
        cbFetch('/api/code/candidates').catch(function (e) { return { error: e.message } }),
        cbFetch('/api/code/tabs').catch(function (e) { return { error: e.message } }),
      ])
      cbRenderProjects(projects.projects)
      cbRenderTiles(health)
      if (_cbTab === 'skills') cbLoadSkills()
      cbRenderTasks(tasks.tasks)
      cbRenderCandidates(cands)
      // A fulek a projektek UTAN: a legordulo a kivalasztott projekthez tartozo
      // fuleket mutatja, tehat kell hozza a mar kirajzolt projekt-lista.
      cbRenderTabs(tabs)
    } catch (e) {
      const el = document.getElementById('cbTasksList')
      if (el) el.innerHTML = '<p class="subtitle">Nem sikerült lekérdezni: ' + escapeHtml(e.message) + '</p>'
    }
  }
  window._cbRefresh = cbRefresh

  // ---- "ujrainditas utan lep eletbe" -> GOMB ---------------------------
  //
  // Boss (2026-08-16): "tegyel egy gombot oda a beallitasokba illetve minden
  // ilyen helyre ahol ezt irjatok ki hogy ujrainditas utan lep eletbe."
  //
  // Ez a lap ot olyan beallitast ir, amit a config.ts INDULASKOR olvas be
  // (`const`), tehat a mentes onmagaban semmit nem valtoztat a mukodesen. Egy
  // FRISS telepitesen ez a kulonbseg dont: a bot-token mentese utan a Telegram
  // ut addig halott, amig valaki ujra nem inditja a vezerlopultot -- es ha
  // ehhez terminal kell, akkor a lap onmagaban nem elegendo.
  //
  // A gomb NEM all ott mindig: csak akkor jelenik meg, ha az elmentett ertek
  // tenylegesen elter az eppen futotol. Igy nem szoktatja hozza a felhasznalot
  // ahhoz, hogy egy ujrainditas-gomb csak dekoracio.
  // A `cbServiceRestart` az Attekintes fulon all: ha ott nyomtad meg a
  // Leallitast, ott is kell latnod, hogy a valtozas ujrainditasra var --
  // nem egy masik fulon, ahova at kell kattintani.
  var _cbRestartState = { cbBotRestart: null, cbOpsRestart: null, cbCandRestart: null, cbServiceRestart: null }

  // A mentett ertek SZTRING ("a, b"), az elo ertek viszont mar feldolgozott
  // TOMB (['a','b']) -- a config.ts vesszo menten szetvagja, trimmeli, es a
  // kizarasi listat kisbetusiti is. Osszehasonlitani csak ugyanabban a formaban
  // szabad oket, kulonben egy szokoz vagy egy nagybetu miatt a gomb az
  // ujrainditas UTAN is ottmarad -- amit a Boss mar egyszer kifogasolt
  // (2026-08-18: "ujraindtottam es megis kiirja hogy ujrainditasra var!!?").
  function cbNormList(value, lower) {
    const parts = Array.isArray(value) ? value : String(value == null ? '' : value).split(',')
    return parts
      .map((x) => String(x).trim())
      .map((x) => (lower ? x.toLowerCase() : x))
      .filter((x) => x.length > 0)
      .join(',')
  }

  async function cbMountRestart(slotId, pending, note) {
    const slot = document.getElementById(slotId)
    if (!slot) return
    // Ugyanaz az allapot -> hozza sem nyulunk. Kulonben minden Frissites
    // ujraepitene a gombot, es egy eppen futo kattintas allapota elveszne.
    if (_cbRestartState[slotId] === pending) return
    _cbRestartState[slotId] = pending
    if (!pending) { slot.innerHTML = ''; return }
    await mountRestartButton(slot, note)
  }

  async function cbLoadConfig() {
    let cfg = null
    try { cfg = await cbFetch('/api/code/config') } catch (e) { return }
    const enabled = document.getElementById('cbEnabled')
    if (enabled) enabled.checked = String(cfg.CODE_BRIDGE_ENABLED) === '1'
    const perm = document.getElementById('cbPermMode')
    if (perm) perm.value = cfg.CODE_PERMISSION_MODE || 'acceptEdits'
    const excl = document.getElementById('cbExclude')
    if (excl) excl.value = cfg.CODE_BRIDGE_EXCLUDE || ''
    _cbSavedExclude = cbNormList(cfg.CODE_BRIDGE_EXCLUDE, true).split(',').filter(function (x) { return x })
    const chats = document.getElementById('cbAllowedChats')
    if (chats) chats.value = cfg.CODE_BOT_ALLOWED_CHAT_IDS || ''
    const state = document.getElementById('cbBotState')
    if (state) {
      // A tokent SOHA nem irjuk vissza a mezobe -- csak azt mondjuk meg, van-e.
      state.textContent = cfg.botConfigured
        ? (cfg.live && cfg.live.botConfigured ? 'be van állítva' : 'elmentve — újraindítás után lép életbe')
        : 'nincs beállítva'
    }

    // Kartyankent kulon: a bot-token mentese utan nem kell azt allitani, hogy
    // a Mukodes-kartya is ujrainditasra var -- es forditva.
    const live = cfg.live || {}
    const botPending =
      Boolean(cfg.botConfigured) !== Boolean(live.botConfigured) ||
      cbNormList(cfg.CODE_BOT_ALLOWED_CHAT_IDS, false) !== cbNormList(live.allowedChatIds, false)
    // A kizarasi lista KULON: a felderitett mappak alatti gomb csak erre
    // vonatkozik, es egy jogosultsag-valtas utan nem allithatja, hogy egy
    // kizaras feloldasa var ujrainditasra.
    const exclPending = cbNormList(cfg.CODE_BRIDGE_EXCLUDE, true) !== cbNormList(live.excluded, true)
    const opsPending =
      (String(cfg.CODE_BRIDGE_ENABLED) === '1') !== Boolean(live.enabled) ||
      String(cfg.CODE_PERMISSION_MODE || '') !== String(live.permissionMode || '') ||
      exclPending
    // A `void` szandekos: a konfiguracio kirajzolasa nem varhat egy halozati
    // korre, es a gomb sajat maga kezeli, ha a vezerlopult nem tudja magat
    // ujrainditani (akkor megmondja, mit csinaljon helyette az ember).
    void cbMountRestart('cbBotRestart', botPending,
      'A mentés a vezérlőpult újraindítása után lép életbe — a kód-bot csak utána kezd figyelni.')
    void cbMountRestart('cbOpsRestart', opsPending,
      'A mentés a vezérlőpult újraindítása után lép életbe.')
    void cbMountRestart('cbServiceRestart', opsPending,
      'A mentés a vezérlőpult újraindítása után lép életbe.')
    // Ugyanaz a gomb a felderitett mappak ALATT is: a kizarast ott lehet
    // feloldani, es egy gomb, amiert at kell gorgetni egy masik kartyahoz, a
    // gyakorlatban nem letezik.
    void cbMountRestart('cbCandRestart', exclPending,
      'A kizárás feloldása a vezérlőpult újraindítása után lép életbe.')
  }

  // ======================================================================
  // FULEK -- ugyanaz a sablon, mint barmelyik masik ugynok-kartyanal.
  //
  // Boss, 2026-08-23: "az nem szep hogy vscode ba bemegyek es egy oldalon van
  // minden!" A lap tartalma NEM valtozott, csak ot csoportra bomlott, es a
  // csoportok ugyanazok, ugyanabban a sorrendben, mint az ugynok-ablakban.
  // ======================================================================
  const CB_TABS = {
    overview: 'cbTabOverview',
    settings: 'cbTabSettings',
    channel: 'cbTabChannel',
    skills: 'cbTabSkills',
    team: 'cbTabTeam',
  }
  let _cbTab = 'overview'

  window.cbSwitchTab = function (tab) {
    if (!CB_TABS[tab]) tab = 'overview'
    _cbTab = tab
    document.querySelectorAll('#cbTabNav .tab-btn').forEach(function (b) {
      b.classList.toggle('active', b.dataset.tab === tab)
    })
    Object.keys(CB_TABS).forEach(function (key) {
      const el = document.getElementById(CB_TABS[key])
      if (el) el.hidden = key !== tab
    })
    // A skillek a projekt MAPPAJABOL jonnek (halozat + lemez), ezert csak
    // akkor kerdezzuk le, amikor tenyleg latszanak.
    if (tab === 'skills') cbLoadSkills()
  }

  document.getElementById('cbTabNav')?.addEventListener('click', function (e) {
    const btn = e.target instanceof Element ? e.target.closest('.tab-btn') : null
    if (btn && btn.dataset.tab) window.cbSwitchTab(btn.dataset.tab)
  })

  // ---- IDENTITAS: a hid sajat ikonja ------------------------------------
  //
  // Boss: "attekintesben lehessen ugy pld az ikont kepet valtoztatni".
  // A 404 a `/api/code/avatar`-on NEM hiba, hanem a "meg nincs beallitva"
  // allapot -- friss telepitesen pont ez az alapertelmezes, es olyankor a
  // monogram a helyes valasz, nem egy hibauzenet.
  function cbRenderIdentity(health) {
    const el = document.getElementById('cbDetailAvatar')
    if (!el) return
    if (health && health.avatar) {
      el.className = 'detail-avatar'
      el.style.background = ''
      el.innerHTML = '<img src="/api/code/avatar' + avatarBust() + '" alt="">'
      return
    }
    el.className = 'detail-avatar avatar-mono'
    el.style.background = monogramColor('vscode-bridge')
    el.textContent = 'K'
  }

  async function cbSetAvatar(opts) {
    try {
      await cbFetch('/api/code/avatar', opts)
      bumpAvatarEpoch()
      showToast(t('cb.detail.avatar_saved'))
      const gal = document.getElementById('cbAvatarGallery')
      if (gal) gal.hidden = true
      await cbRefresh()
      await loadCodeBridgeCards()
      renderAgents()
    } catch (err) {
      showToast(t('cb.detail.avatar_failed', { msg: err.message }), { type: 'error' })
    }
  }

  function cbPopulateAvatarGrid() {
    const grid = document.getElementById('cbAvatarGrid')
    if (!grid || grid.dataset.filled === '1') return
    grid.dataset.filled = '1'
    for (const avatar of AVATARS) {
      const item = document.createElement('div')
      item.className = 'avatar-grid-item'
      item.innerHTML = '<img src="/avatars/' + avatar + '" alt="">'
      item.addEventListener('click', function () {
        cbSetAvatar({
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ galleryAvatar: avatar }),
        })
      })
      grid.appendChild(item)
    }
  }

  // ---- CSEMPEK ----------------------------------------------------------
  //
  // Minden csempe MERT ertekbol dolgozik, es ha nem latunk oda, azt mondja ki,
  // nem nullat mutat. (A "0 skill" es a "nem latok a mappara" ket KULON
  // allapot; osszemosva a felhasznalo azt hinne, nincs egy skillje sem.)
  let _cbSkillCount = null

  function cbRenderTiles(health) {
    const set = function (id, text) {
      const el = document.getElementById(id)
      if (el) el.textContent = text
    }
    // Modell: amivel a beszelgetesek eppen valaszoltak. Tobbfele is lehet.
    const models = []
    for (const p of _cbProjects) {
      const m = (p && typeof p.model === 'string') ? p.model.trim() : ''
      if (m && models.indexOf(m) === -1) models.push(m)
    }
    set('cbTileModel', models.length ? models.join(', ') : t('cb.card.model_unknown'))
    // A modellt a VS Code-ban valasztjak (/model). Ez ITT, a csempe alatt all
    // ki -- a kartyan mar eleg informacio van. A teljes mondat a tooltipben.
    const modelNote = document.getElementById('cbTileModelNote')
    if (modelNote) modelNote.title = t('cb.card.model_where_help')

    // Csatorna: a kod-bot. A nev is kiirodik, ha tudjuk -- azt keresi a szem.
    const bot = health && health.codeBot
    set('cbTileChannel',
      !health ? t('cb.tile.unknown')
      : !health.botConfigured ? t('cb.tile.channel_none')
      : (bot && bot.username) ? '@' + String(bot.username).replace(/^@+/, '')
      : t('cb.tile.channel_set'))

    set('cbTileSkills', _cbSkillCount === null ? t('cb.tile.unknown') : String(_cbSkillCount))
    set('cbTileProjects', String(_cbProjects.length))
  }

  // ---- SZOLGALTATAS: indit / leallit -------------------------------------
  //
  // ★ Boss, 2026-08-23: "attekintes alatt a kartyan belul pedig latod ott van
  // az hogy leallit meg elindit. a szolgaltatast. nem am kint a torles gob
  // alatt ahogy te csinaltad."
  //
  // KET kulon dolog latszik itt, mert ket kulon dolog tud elromlani:
  //   * a HID maga (CODE_BRIDGE_ENABLED) -- ezt innen lehet be- es kikapcsolni,
  //   * a Windows-VEGREHAJTO -- ez egy masik gepen fut, innen NEM inditható.
  // A masodikhoz ezert nincs gomb: gomb helyett megmondjuk, hol vegezheto el.
  // Egy gomb, ami nem tud hatni, rosszabb a hianyzo gombnal.
  function cbRenderService(health) {
    const dot = document.getElementById('cbServiceDot')
    const label = document.getElementById('cbServiceLabel')
    const worker = document.getElementById('cbServiceWorker')
    const startBtn = document.getElementById('cbServiceStartBtn')
    const stopBtn = document.getElementById('cbServiceStopBtn')
    if (!dot || !label) return
    const on = !(health && health.enabled === false)
    // A MENTETT allapot kulon a futotol: a hid indulaskor olvassa a beallitast,
    // ezert egy "Leallitas" utan a mentett mar 0, a folyamat meg fut. Ha ezt
    // nem mondjuk ki, a gomb ugy nez ki, mintha nem mukodne.
    const saved = (health && typeof health.savedEnabled === 'boolean') ? health.savedEnabled : on
    const pending = saved !== on
    // A 'restarting' a haz meglevo sarga, pulzalo pontja -- pontosan azt jelenti,
    // hogy egy mentett valtozas ujrainditasra var. Uj osztalyt nem talalunk ki.
    dot.className = 'process-dot ' + (pending ? 'restarting' : (on ? 'running' : 'stopped'))
    label.textContent = pending
      ? (saved ? t('cb.service.on_pending') : t('cb.service.off_pending'))
      : (on ? t('cb.service.on') : t('cb.service.off'))
    // A gombok a MENTETT allapotot kovetik: ha mar leallitottad, ne a
    // "Leallitas" alljon ott masodszor is.
    if (startBtn) startBtn.hidden = saved
    if (stopBtn) stopBtn.hidden = !saved
    if (!worker) return
    if (!health) { worker.textContent = ''; return }
    // Harom allapot, mert harom kulon teendo. A "meg soha nem jelentkezett" NEM
    // ugyanaz, mint a "jelentkezett, de elhallgatott": az elso telepitest ker,
    // a masodik azt, hogy nezd meg, mi tortent a masik gepen.
    if (health.workerOnline) worker.textContent = t('cb.service.worker_online')
    else if (health.lastSeenAt) worker.textContent = t('cb.service.worker_offline', { ago: cbAgo(health.lastSeenAt) })
    else worker.textContent = t('cb.service.worker_never')
  }

  async function cbSetService(on) {
    try {
      await cbPostJson('/api/code/config', { CODE_BRIDGE_ENABLED: on ? '1' : '0' })
      // A mentes onmagaban NEM lep eletbe: a config.ts indulaskor olvassa be.
      // Ezt a `cbLoadConfig` mondja ki azzal, hogy kirakja az ujrainditas-gombot
      // -- ide, ugyanarra a fulre, ahol a kapcsolot megnyomtad.
      showToast(t('cb.service.saved'))
      await cbLoadConfig()
      await cbRefresh()
    } catch (err) {
      showToast(t('cb.service.failed', { msg: err.message }), { type: 'error' })
    }
  }

  // ---- SKILLEK -----------------------------------------------------------
  //
  // Boss, 2026-08-23: "skilleket is lehet ehhez irni. ugye miert ne lhetne."
  //
  // A skillek a PROJEKT mappajaban laknak (`.claude/skills/`), mert a feladatot
  // vegrehajto headless Claude Code is onnan olvassa oket. Marveen sajat
  // `~/.claude/skills`-e ide nem jo: az egy masik gep masik fajlrendszere.
  function cbSkillProjectEl() { return document.getElementById('cbSkillProject') }

  function cbFillSkillProjects() {
    const sel = cbSkillProjectEl()
    if (!sel) return null
    const want = sel.value
    const names = _cbProjects.map(function (p) { return p.project })
    const same = sel.options.length === names.length
      && names.every(function (n, i) { return sel.options[i].value === n })
    if (!same) {
      sel.innerHTML = ''
      for (const n of names) {
        const o = document.createElement('option')
        o.value = n
        o.textContent = n
        sel.appendChild(o)
      }
    }
    if (want && names.indexOf(want) !== -1) sel.value = want
    return sel.value || null
  }

  async function cbLoadSkills() {
    const list = document.getElementById('cbSkillList')
    const note = document.getElementById('cbSkillNote')
    if (!list) return
    const project = cbFillSkillProjects()
    if (!project) {
      // NEM "nincs skill": nincs mihez. A kettot kulon kell kimondani.
      list.innerHTML = '<p class="subtitle">' + escapeHtml(t('cb.skills.no_project')) + '</p>'
      if (note) note.textContent = ''
      _cbSkillCount = null
      cbRenderTiles(_cbLastHealth)
      return
    }
    let data = null
    try {
      data = await cbFetch('/api/code/skills?project=' + encodeURIComponent(project))
    } catch (err) {
      list.innerHTML = '<p class="subtitle">' + escapeHtml(t('cb.skills.failed', { msg: err.message })) + '</p>'
      if (note) note.textContent = ''
      _cbSkillCount = null
      cbRenderTiles(_cbLastHealth)
      return
    }
    cbRenderSkills(data)
  }

  function cbRenderSkills(d) {
    const list = document.getElementById('cbSkillList')
    const note = document.getElementById('cbSkillNote')
    if (!list) return
    list.innerHTML = ''
    // ★ A NULLA KET DOLGOT JELENTHET. Ha nem latunk a mappara, a nulla skill NEM
    // azt jelenti, hogy nincs egy sem -- es az okot a szerver TENYLEGES
    // hibauzenetebol mondjuk, nem talalgatjuk.
    if (!d.reachable) {
      list.innerHTML = '<p class="subtitle">' + escapeHtml(t('cb.skills.unreachable', { r: d.reason || '?' })) + '</p>'
      if (note) note.textContent = ''
      _cbSkillCount = null
      cbRenderTiles(_cbLastHealth)
      return
    }
    _cbSkillCount = d.skills.length
    if (d.skills.length === 0) {
      list.innerHTML = '<p class="subtitle">' + escapeHtml(t('cb.skills.empty')) + '</p>'
    }
    for (const skill of d.skills) {
      const item = document.createElement('div')
      item.className = 'skill-item'
      item.innerHTML =
        '<div class="skill-item-info">'
        + '<div class="skill-item-name">' + escapeHtml(skill.name) + '</div>'
        + (skill.description ? '<div class="skill-item-desc">' + escapeHtml(skill.description) + '</div>' : '')
        + '</div>'
        + '<div class="skill-item-actions">'
        + '<button class="btn-icon btn-icon-danger" title="' + escapeAttr(t('cb.skills.delete')) + '">' + trashIcon() + '</button>'
        + '</div>'
      item.querySelector('.btn-icon-danger').addEventListener('click', async function () {
        if (!confirm(t('cb.skills.delete_confirm', { n: skill.name, p: d.project }))) return
        try {
          await cbFetch('/api/code/skills?project=' + encodeURIComponent(d.project)
            + '&name=' + encodeURIComponent(skill.name), { method: 'DELETE' })
          showToast(t('cb.skills.deleted', { n: skill.name }))
          cbLoadSkills()
        } catch (err) {
          showToast(t('cb.skills.failed', { msg: err.message }), { type: 'error' })
        }
      })
      list.appendChild(item)
    }
    if (note) note.textContent = t('cb.skills.dir_note', { d: d.skillsDir || '' })
    cbRenderTiles(_cbLastHealth)
  }

  document.addEventListener('change', function (e) {
    const el = e.target
    if (!(el instanceof Element)) return
    if (el.id === 'cbSkillProject') { cbLoadSkills(); return }
    if (el.id === 'cbAvatarFileInput') {
      const file = el.files && el.files[0]
      if (!file) return
      // Ugyanaz az 1 MB-os korlat, mint az ugynok-avataroknal: a bongeszo
      // mondja meg elore, ne a szerver utolag.
      if (file.size > 1024 * 1024) {
        showToast(t('cb.detail.avatar_too_big'), { type: 'error' })
        el.value = ''
        return
      }
      const fd = new FormData()
      fd.append('file', file)
      cbSetAvatar({ method: 'POST', body: fd }).finally(function () { el.value = '' })
    }
  })

  window.loadCodeBridgePage = function () {
    cbRefresh()
    cbLoadConfig()
    window.__cbStopPollImpl()
    // Egy futo feladat percekig tart; 5 masodperces kor eleg ahhoz, hogy a
    // lap eljen, es nem terheli sem a bongeszot, sem az SQLite-ot.
    _cbTimer = setInterval(cbRefresh, 5000)
  }

  // ---- esemenyek -------------------------------------------------------

  document.addEventListener('click', async function (e) {
    const tgt = e.target
    if (!(tgt instanceof Element)) return

    if (tgt.id === 'cbRefreshBtn') { cbRefresh(); cbLoadConfig(); return }

    if (tgt.id === 'cbAvatarChangeBtn' || (tgt.closest && tgt.closest('#cbAvatarChangeBtn'))) {
      const gal = document.getElementById('cbAvatarGallery')
      if (gal) { cbPopulateAvatarGrid(); gal.hidden = !gal.hidden }
      return
    }
    if (tgt.id === 'cbAvatarResetBtn') {
      await cbSetAvatar({ method: 'DELETE' })
      return
    }
    if (tgt.closest && tgt.closest('#cbAvatarUploadZone')) {
      document.getElementById('cbAvatarFileInput')?.click()
      return
    }

    if (tgt.id === 'cbServiceStartBtn') { await cbSetService(true); return }
    if (tgt.id === 'cbServiceStopBtn') {
      if (!confirm(t('cb.service.stop_confirm'))) return
      await cbSetService(false)
      return
    }

    if (tgt.id === 'cbSkillAddBtn') {
      const form = document.getElementById('cbSkillForm')
      if (form) form.hidden = !form.hidden
      return
    }
    if (tgt.id === 'cbSkillCancelBtn') {
      const form = document.getElementById('cbSkillForm')
      if (form) form.hidden = true
      return
    }
    if (tgt.id === 'cbSkillCreateBtn') {
      const project = cbFillSkillProjects()
      const nameEl = document.getElementById('cbSkillName')
      const descEl = document.getElementById('cbSkillDesc')
      const status = document.getElementById('cbSkillStatus')
      if (!project) { if (status) status.textContent = t('cb.skills.no_project'); return }
      const name = (nameEl?.value || '').trim()
      const desc = (descEl?.value || '').trim()
      if (!name || !desc) { if (status) status.textContent = t('cb.skills.need_both'); return }
      tgt.setAttribute('disabled', 'disabled')
      if (status) status.textContent = t('cb.skills.working')
      try {
        const out = await cbPostJson('/api/code/skills', { project, name, description: desc })
        if (status) status.textContent = ''
        if (nameEl) nameEl.value = ''
        if (descEl) descEl.value = ''
        document.getElementById('cbSkillForm').hidden = true
        showToast(t('cb.skills.created', { n: out.name }))
        cbLoadSkills()
      } catch (err) {
        if (status) status.textContent = t('cb.skills.failed', { msg: err.message })
      } finally {
        tgt.removeAttribute('disabled')
      }
      return
    }

    if (tgt.id === 'cbTasksClearBtn') {
      if (!confirm('Törlöd a lezárt feladatok előzményeit? A sorban álló és az éppen futó feladatok megmaradnak.')) return
      tgt.setAttribute('disabled', 'disabled')
      try {
        const out = await cbFetch('/api/code/tasks', { method: 'DELETE' })
        showToast('Törölve: ' + (out && out.removed != null ? out.removed : 0) + ' lezárt sor.')
        cbRefresh()
      } catch (err) {
        showToast('Nem sikerült: ' + err.message, { type: 'error' })
      } finally {
        tgt.removeAttribute('disabled')
      }
      return
    }

    if (tgt.id === 'cbDlPs1' || tgt.id === 'cbDlCmd') {
      window.location.href = '/api/code/worker-script?file=' + (tgt.id === 'cbDlCmd' ? 'cmd' : 'ps1')
      return
    }

    if (tgt.id === 'cbCopyInstall') {
      const cmd = document.getElementById('cbInstallCmd')
      if (cmd) {
        try { await navigator.clipboard.writeText(cmd.textContent) ; showToast('Parancs a vágólapon.') }
        catch (err) { showToast('A böngésző nem engedte a másolást — jelöld ki kézzel.', { type: 'error' }) }
      }
      return
    }

    if (tgt.id === 'cbTaskSendBtn') {
      const sel = document.getElementById('cbTaskProject')
      const tabSel = document.getElementById('cbTaskTab')
      const prompt = document.getElementById('cbTaskPrompt')
      const status = document.getElementById('cbTaskStatus')
      if (!sel || !prompt) return
      if (!sel.value) { if (status) status.textContent = 'Előbb kell legalább egy regisztrált projekt.'; return }
      if (!prompt.value.trim()) { if (status) status.textContent = 'Írd le, mit csináljon.'; return }
      tgt.setAttribute('disabled', 'disabled')
      if (status) status.textContent = 'Küldés…'
      try {
        const task = await cbPostJson('/api/code/tasks', {
          project: sel.value, prompt: prompt.value, origin: 'dashboard', requestedBy: 'dashboard',
          // Ures = a projekt aktualis beszelgetese, vagyis a korabbi viselkedes.
          sessionId: (tabSel && tabSel.value) ? tabSel.value : null,
        })
        prompt.value = ''
        if (status) status.textContent = 'Átadva: ' + task.project + ' (' + String(task.id).slice(0, 8) + ')'
        cbRefresh()
      } catch (err) {
        if (status) status.textContent = 'Nem sikerült: ' + err.message
      } finally {
        tgt.removeAttribute('disabled')
      }
      return
    }

    if (tgt.classList.contains('cb-pin')) {
      const project = tgt.getAttribute('data-project')
      const pinned = tgt.getAttribute('data-pinned') === '1'
      const row = _cbProjects.find(function (p) { return p.project === project })
      if (!row) return
      try {
        await cbPostJson('/api/code/projects', {
          project: row.project, workspacePath: row.workspacePath, sessionId: row.sessionId, pinned: !pinned,
        })
        cbRefresh()
      } catch (err) { showToast('Nem sikerült: ' + err.message, { type: 'error' }) }
      return
    }

    if (tgt.classList.contains('cb-del')) {
      const project = tgt.getAttribute('data-project')
      if (!confirm('Törlöd a(z) "' + project + '" leképezést? A session maga nem sérül; a felderítés vissza is teheti, ha a workspace nyitva van.')) return
      try {
        await cbFetch('/api/code/projects/' + encodeURIComponent(project), { method: 'DELETE' })
        cbRefresh()
      } catch (err) { showToast('Nem sikerült: ' + err.message, { type: 'error' }) }
      return
    }

    if (tgt.classList.contains('cb-cand-add')) {
      const alias = tgt.getAttribute('data-alias') || ''
      tgt.setAttribute('disabled', 'disabled')
      try {
        await cbPostJson('/api/code/projects', {
          project: alias,
          workspacePath: tgt.getAttribute('data-ws') || '',
          sessionId: tgt.getAttribute('data-sid') || '',
          pinned: true,
        })
        showToast('Felvéve: ' + alias)
        cbRefresh()
      } catch (err) {
        showToast('Nem sikerült: ' + err.message, { type: 'error' })
        tgt.removeAttribute('disabled')
      }
      return
    }

    if (tgt.classList.contains('cb-cand-unexclude')) {
      const alias = tgt.getAttribute('data-alias') || ''
      // A kizaras nem veletlen volt: pont az elo beszelgetes workspace-et
      // szokas kizarni. Ezert megmondjuk, mit old fel, MIELOTT feloldja.
      if (!confirm('Feloldod a(z) "' + alias + '" kizárását?\n\n'
        + 'A kizárás azt akadályozza meg, hogy egy feladat abba a beszélgetésbe írjon, '
        + 'amelyikben éppen te dolgozol. Feloldás után ez a mappa is felvehető és feladható lesz.')) return
      tgt.setAttribute('disabled', 'disabled')
      try {
        const cfg = await cbFetch('/api/code/config')
        const kept = String(cfg.CODE_BRIDGE_EXCLUDE || '').split(',')
          .map(function (x) { return x.trim() })
          .filter(function (x) { return x && x.toLowerCase() !== alias.toLowerCase() })
        await cbPostJson('/api/code/config', { CODE_BRIDGE_EXCLUDE: kept.join(', ') })
        showToast('Feloldás elmentve — a vezérlőpult újraindítása után lép életbe.')
        cbLoadConfig()
        cbRefresh()
      } catch (err) {
        showToast('Nem sikerült: ' + err.message, { type: 'error' })
        tgt.removeAttribute('disabled')
      }
      return
    }

    if (tgt.id === 'cbAddBtn') {
      const project = document.getElementById('cbAddProject')
      const ws = document.getElementById('cbAddWorkspace')
      const sid = document.getElementById('cbAddSession')
      const status = document.getElementById('cbAddStatus')
      if (!project || !ws || !sid) return
      const name = project.value.trim()
      const wsPath = ws.value.trim()
      const uuid = sid.value.trim()
      const say = function (msg) { if (status) status.textContent = msg }
      // Elore szolunk, magyarul. A szerver hibauzenete angol, es itt egyenesen
      // a felhasznalo ele kerulne -- ezt a hatart a lapnak kell allnia.
      if (!name) { say('Adj nevet a projektnek — ezt írod majd a /code után.'); project.focus(); return }
      if (!wsPath) { say('Add meg a projekt mappáját (VS Code → jobb gomb a gyökérmappán → Copy Path).'); ws.focus(); return }
      const known = _cbCandidates.some(function (c) { return cbSamePath(c.workspacePath, wsPath) })
      if (!uuid && !known) {
        say('Ehhez a mappához a végrehajtó nem jelentett beszélgetést, ezért a session-azonosító most kötelező. '
          + 'A VS Code Claude Code panelben a /status parancs írja ki.')
        sid.focus(); return
      }
      try {
        await cbPostJson('/api/code/projects', {
          project: name, workspacePath: wsPath, sessionId: uuid, pinned: true,
        })
        project.value = ''; ws.value = ''; sid.value = ''
        if (status) status.textContent = 'Felvéve.'
        cbRefresh()
      } catch (err) { if (status) status.textContent = 'Nem sikerült: ' + err.message }
      return
    }

    if (tgt.id === 'cbBotSaveBtn' || tgt.id === 'cbBotClearBtn') {
      const token = document.getElementById('cbBotToken')
      const chats = document.getElementById('cbAllowedChats')
      const status = document.getElementById('cbBotStatus')
      const body = {}
      if (tgt.id === 'cbBotClearBtn') {
        if (!confirm('Törlöd a kód-bot tokenjét? Ezután Telegramról nem lehet közvetlenül feladni.')) return
        body.CODE_BOT_TOKEN = null
      } else if (token && token.value.trim()) {
        body.CODE_BOT_TOKEN = token.value.trim()
      }
      if (chats) body.CODE_BOT_ALLOWED_CHAT_IDS = chats.value.trim()
      try {
        await cbPostJson('/api/code/config', body)
        if (token) token.value = ''
        if (status) status.textContent = 'Elmentve — a vezérlőpult újraindítása után lép életbe.'
        cbLoadConfig()
      } catch (err) { if (status) status.textContent = 'Nem sikerült: ' + err.message }
      return
    }

    if (tgt.id === 'cbSaveOpsBtn') {
      const enabled = document.getElementById('cbEnabled')
      const perm = document.getElementById('cbPermMode')
      const excl = document.getElementById('cbExclude')
      const status = document.getElementById('cbOpsStatus')
      try {
        await cbPostJson('/api/code/config', {
          CODE_BRIDGE_ENABLED: enabled && enabled.checked ? '1' : '0',
          CODE_PERMISSION_MODE: perm ? perm.value : 'acceptEdits',
          CODE_BRIDGE_EXCLUDE: excl ? excl.value.trim() : '',
        })
        if (status) status.textContent = 'Elmentve — a vezérlőpult újraindítása után lép életbe.'
        cbLoadConfig()
      } catch (err) { if (status) status.textContent = 'Nem sikerült: ' + err.message }
      return
    }

    const row = tgt.closest ? tgt.closest('.cb-task-row') : null
    if (row) { cbOpenTask(row.getAttribute('data-id')); return }
  })

  // A prompt-korlat a szerveren 12 000 karakter; a szamlalo ELORE szol, hogy a
  // hosszu feladat ne a kuldes pillanataban bukjon el.
  document.addEventListener('input', function (e) {
    if (!(e.target instanceof Element) || e.target.id !== 'cbTaskPrompt') return
    const counter = document.getElementById('cbTaskCounter')
    if (!counter) return
    const n = e.target.value.length
    counter.textContent = n > 12000 ? (n + ' / 12000 — túl hosszú') : (n ? n + ' karakter' : '')
    counter.style.color = n > 12000 ? '#e5534b' : ''
  })

  // Projekt-valtaskor MAS fulek tartoznak a legordulohoz. Delegalt figyelo,
  // mert a legordulo tartalmat a rajzolas cserelgeti.
  document.addEventListener('change', function (e) {
    if (!(e.target instanceof Element) || e.target.id !== 'cbTaskProject') return
    const tabSel = document.getElementById('cbTaskTab')
    // Projekt-valtas utan a regi ful-valasztas mar egy MASIK projekte lenne --
    // azt megtartani csendes felrekuldes volna.
    if (tabSel) tabSel.value = ''
    cbRenderTabOptions()
  })
})()

// A fo asszisztens (Marvin) folyamat-allapota. Korabban a kartya FIXEN
// "Fut"-ot irt ki, mert az /api/marveen a running mezot hardcode true-ra
// allitotta -- vagyis a kepernyo akkor is azt allitotta, hogy fut, amikor
// egyaltalan nem lattunk bele. Boss, 2026-08-24: "parobalom ujrainditani a
// marvint de nem sikerult" -- kozben eppen ujraindult, csak ezt semmi nem
// mondta meg. A NULLA KET DOLGOT JELENTHET: a "nem talalok folyamatot" nem
// azonos a "nincs folyamat"-tal, ezert HAROM allapotot kulonboztetunk meg,
// es a forrast kerdezzuk meg (fut-e a tmux session), nem talalgatunk.
function marveenProcessState(m) {
  if (!m || typeof m.running !== 'boolean') return 'unknown'   // regi backend
  if (m.running) return 'running'
  if (m.sessionExists) return 'unseen'                          // van session, nincs folyamat
  return 'stopped'
}

function marveenProcessHtml(m) {
  const state = marveenProcessState(m)
  if (state === 'running') {
    return `<span class="process-indicator" title="${escapeAttr(t('agents.marveen_process_tip'))}">`
      + `<span class="process-dot running"></span>${escapeHtml(t('agents.status.running'))}</span>`
  }
  if (state === 'unseen') {
    return `<span class="process-indicator" title="${escapeAttr(t('agents.marveen_process_unseen_tip'))}">`
      + `<span class="process-dot restarting"></span>${escapeHtml(t('agents.marveen_process_unseen'))}</span>`
  }
  if (state === 'stopped') {
    return `<span class="process-indicator" title="${escapeAttr(t('agents.marveen_process_stopped_tip'))}">`
      + `<span class="process-dot stopped"></span>${escapeHtml(t('agents.status.stopped'))}</span>`
  }
  return `<span class="process-indicator" title="${escapeAttr(t('agents.marveen_process_unknown_tip'))}">`
    + `<span class="process-dot stopped"></span>${escapeHtml(t('agents.marveen_process_unknown'))}</span>`
}
